// Cache-busting version for runtime fetch('pages/*.html') calls — kept in sync with
// index.html's own ?v= on <script>/<link> by hand. Without this, editing a page fragment
// (e.g. pages/challenges.html) can silently keep serving an old cached copy to returning
// visitors indefinitely, even though js/app.js.css/styles.css/index.html themselves get
// re-fetched correctly — this bit Rizers twice in one session before this existed.
var _RZ_ASSET_V='20260822e';
var lpData={name:'',phone:'',pass:'',prof:'',time:''};
var lpStepCur=1;

function lpPhoneToEmail(phone) {
  return 'p' + phone.replace(/\D/g,'') + '@xwdmhwaxzwowlezqruaj.supabase.co';
}
function lpStart(){
  var name=document.getElementById('lp-name').value.trim();
  var phone=document.getElementById('lp-phone').value.trim();
  if(!name){document.getElementById('lp-name').focus();return;}
  var digits=phone.replace(/\D/g,'');
  if(digits.length < 10){document.getElementById('lp-phone').focus();return;}
  lpData.name=name; lpData.phone=phone; lpData.email=lpPhoneToEmail(phone);
  document.querySelector('.lp-hero').classList.add('signup-mode');
  document.body.classList.add('lp-noscroll'); window.scrollTo(0,0);
  if(location.pathname.indexOf('/signup')===-1) history.pushState({rz:1},'','/signup');
  lpGoStep(2);
}
function lpShowMsg(msg, ok) {
  var el = document.getElementById('lp-msg');
  if (!el) return;
  el.style.display = 'block';
  el.style.background = ok ? 'rgba(34,197,94,.12)' : 'rgba(239,68,68,.12)';
  el.style.color = ok ? '#86efac' : '#fca5a5';
  el.style.border = '1px solid ' + (ok ? 'rgba(34,197,94,.3)' : 'rgba(239,68,68,.3)');
  el.textContent = msg;
}
function lpShowPassMsg(msg, ok) {
  var el = document.getElementById('lp-pass-msg');
  if (!el) return;
  el.style.display = 'block';
  el.style.background = ok ? 'rgba(34,197,94,.12)' : 'rgba(239,68,68,.12)';
  el.style.color = ok ? '#86efac' : '#fca5a5';
  el.style.border = '1px solid ' + (ok ? 'rgba(34,197,94,.3)' : 'rgba(239,68,68,.3)');
  el.textContent = msg;
}
async function lpSignupSubmit() {
  var el = document.getElementById('lp-pass'); if (!el) return;
  var pass = el.value;
  if (pass.length < 6) {
    el.focus(); el.style.borderColor='#ff6b6b';
    setTimeout(function(){el.style.borderColor='';},1200);
    lpShowPassMsg('Password কমপক্ষে ৬ অক্ষর দাও');
    return;
  }
  var btn = document.getElementById('lp-pass-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'তৈরি হচ্ছে...'; }
  window.lpOnboarding = true;
  try {
    var { data, error } = await _sb.auth.signUp({
      email: lpData.email,
      password: pass,
      options: { data: { name: lpData.name } }
    });
    if (error) { lpShowPassMsg(error.message); return; }
    // Insert profile
    if (data.user) {
      await _sb.from('profiles').upsert({ id: data.user.id, name: lpData.name, username: _makeUsername(lpData.name) });
    }
    // Check if email confirmation required
    if (data.session) {
      sbUser = data.user; window.sbUser = sbUser;
      await sbLoadProfile();
      sbUpdateUI();
      if (btn) { btn.disabled = false; btn.textContent = 'Account বানাও →'; }
      lpGoStep(3);
    } else {
      lpShowPassMsg('✓ Email দেখো — confirm করলেই login করতে পারবে!', true);
      if (btn) { btn.textContent = 'Email পাঠানো হয়েছে ✓'; }
      setTimeout(function(){
        // switch to login view after 2s
        lpShowPassMsg('এখন Login করো', true);
        if (btn) { btn.textContent = 'Login করো →'; btn.disabled = false; btn.onclick = function(){ lpGoStep(1); lpShowLogin(); }; }
      }, 2500);
    }
  } catch(e) { window.lpOnboarding = false; lpShowPassMsg('Error: ' + e.message); }
  finally { if (btn && btn.textContent === 'তৈরি হচ্ছে...') { window.lpOnboarding = false; btn.disabled = false; btn.textContent = 'Account বানাও →'; } }
}
function lpShowLogin() {
  sbOpenAuth('login');
}

function lpGoStep(n){
  var cur=document.querySelector('.lp-step.active');
  var next=document.querySelector('.lp-step[data-step="'+n+'"]');
  if(!next) return;
  if(cur && cur!==next){
    cur.classList.add('leaving');
    setTimeout(function(){cur.classList.remove('active','leaving'); next.classList.add('active'); afterStep(n);},220);
  } else if(!cur){
    next.classList.add('active'); afterStep(n);
  } else { afterStep(n); }
  lpStepCur=n;
  if(n===1){
    window.lpOnboarding = false;
    document.querySelector('.lp-hero').classList.remove('signup-mode');
    document.body.classList.remove('lp-noscroll');
    if(location.pathname.indexOf('/signup')!==-1) history.pushState({},'','/');
  }
  updateProg(n);
}
function afterStep(n){
  if(n===2){var p=document.getElementById('lp-pass'); if(p) setTimeout(function(){p.focus();},60);}
  if(n===5){document.getElementById('lp-welcome-h').textContent='স্বাগতম, '+(lpData.name||'Riser')+'!';}
}
function updateProg(n){
  var dots=document.querySelectorAll('.lp-prog-dot');
  for(var i=0;i<dots.length;i++){
    var stepForDot=i+2; // dot1->step2 ... dot4->step5
    dots[i].classList.remove('active','done');
    if(stepForDot<n) dots[i].classList.add('done');
    else if(stepForDot===n) dots[i].classList.add('active');
  }
}
function lpPassNext(){
  var el=document.getElementById('lp-pass'); var p=el.value;
  if(p.length<6){ el.focus(); el.style.borderColor='#ff6b6b'; setTimeout(function(){el.style.borderColor='';},1200); return; }
  lpData.pass=p; lpGoStep(3);
}
function lpPick(btn,key,val){
  var parent=btn.parentNode;
  var chips=parent.querySelectorAll('.lp-chip');
  for(var i=0;i<chips.length;i++) chips[i].classList.remove('sel');
  btn.classList.add('sel');
  lpData[key]=val;
  setTimeout(function(){ if(key==='prof') lpGoStep(4); else if(key==='time') lpGoStep(5); },300);
}
function lpFinish(){
  window.lpOnboarding = false;
  document.body.classList.remove('lp-noscroll');
  if(location.pathname.indexOf('/signup')!==-1) history.pushState({},'','/');
  showApp(true);
}
window.addEventListener('popstate',function(){
  var hero=document.querySelector('.lp-hero'); if(!hero) return;
  if(location.pathname.indexOf('/signup')===-1 && hero.classList.contains('signup-mode')){
    hero.classList.remove('signup-mode');
    document.body.classList.remove('lp-noscroll');
    var steps=document.querySelectorAll('.lp-step');
    for(var i=0;i<steps.length;i++) steps[i].classList.remove('active','leaving');
    var t=document.querySelector('.lp-step[data-step="1"]'); if(t) t.classList.add('active');
    lpStepCur=1; updateProg(1);
  }
});
// avoid a broken state if user refreshes/lands directly on /signup
if(location.pathname.indexOf('/signup')!==-1) history.replaceState({},'','/');
