// WEEK STRIP
var rzBnMonths    = ['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
var rzBnDaysFull  = ['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
var rzBnDaysShort = ['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
window.rzViewDate = new Date();

function rzToBn(n) { return String(n).replace(/\d/g, function(d){ return '০১২৩৪৫৬৭৮৯'[d]; }); }

function rzUpdateDateDisplay() {
  var vd    = window.rzViewDate || new Date();
  var today = new Date();
  var main  = document.getElementById('date-main');
  var sub   = document.getElementById('date-sub');
  if (!main) return;
  var isToday  = vd.toDateString() === today.toDateString();
  var dateStr  = rzToBn(vd.getDate()) + ' ' + rzBnMonths[vd.getMonth()] + ' ' + rzToBn(vd.getFullYear());
  main.textContent = (isToday ? 'আজ, ' : '') + dateStr;
  if (sub) sub.textContent = rzBnDaysFull[vd.getDay()];
}

function renderWeek() {
  var strip = document.getElementById('week-strip');
  if (!strip) return;
  var today = new Date();
  var vd    = window.rzViewDate || today;
  var startOfWeek = new Date(vd);
  startOfWeek.setDate(vd.getDate() - vd.getDay());
  var todayStr = today.toDateString();
  strip.innerHTML = '';
  for (var i = 0; i < 7; i++) {
    var d = new Date(startOfWeek);
    d.setDate(startOfWeek.getDate() + i);
    var isSelected = d.toDateString() === vd.toDateString();
    var isToday2   = d.toDateString() === todayStr;
    var el = document.createElement('div');
    el.className = 'week-day' + (isSelected ? ' active' : '');
    el.innerHTML = '<div class="wd-name">' + rzBnDaysShort[i] + '</div>' +
                   '<div class="wd-date">' + rzToBn(d.getDate()) + '</div>' +
                   '<div class="wd-dot' + (isToday2 ? '' : ' hidden') + '"></div>';
    (function(day){ el.onclick = function() {
      document.querySelectorAll('.week-day').forEach(function(x){ x.classList.remove('active'); });
      el.classList.add('active');
      window.rzViewDate = new Date(day);
      rzUpdateDateDisplay();
      if (window.rzActiveKid && typeof rzLoadKidData === 'function') rzLoadKidData();
    }; })(d);
    strip.appendChild(el);
  }
  rzUpdateDateDisplay();
}

// HABITS
function renderHabits() {
  const list = document.getElementById('habits-list');
  list.innerHTML = '';
  habits.forEach(h => {
    const card = document.createElement('div');
    card.className = 'habit-card' + (h.done?' completed':'');
    card.onclick = () => toggleHabit(h.id);
    const _icon = HABIT_ICONS[h.iconKey] || HABIT_ICONS['default'];
    card.innerHTML = `
      <div class="habit-check">${h.done?'<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>':''}</div>
      <div class="habit-icon">${_icon}</div>
      <div class="habit-info">
        <div class="habit-name">${h.name}</div>
        <div class="habit-desc">${h.desc}</div>
      </div>
      <div style="display:flex;gap:8px;align-items:center">
        <div class="habit-streak"><svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="#EF4444" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2L3 14h9l-1 8 10-12h-9l1-8z"/></svg> ${h.streak}দিন</div>
        <div class="habit-points">+${h.points}pts</div>
      </div>
    `;
    list.appendChild(card);
  });
  updateStats();
}

function toggleHabit(id) {
  const h = habits.find(x=>x.id===id);
  h.done = !h.done;
  if(h.done) {
    totalPoints += h.points;
    h.streak++;
    if(habits.every(x=>x.done)) showToast('সব Habit সম্পন্ন! Special Badge পেয়েছো! 🏆');
    else showToast(`${h.name} সম্পন্ন! +${h.points} points 🎉`);
  } else {
    totalPoints -= h.points;
    h.streak = Math.max(0, h.streak-1);
  }
  renderHabits();
}

function updateStats() {
  const done = habits.filter(x=>x.done).length;
  const total = habits.length;
  const pct = Math.round((done/total)*100);
  document.getElementById('s-done').textContent = done;
  document.getElementById('s-total').textContent = total;
  document.getElementById('s-points').textContent = totalPoints;
  document.getElementById('progress-pct').textContent = pct+'%';
  document.getElementById('progress-fill').style.width = pct+'%';
  document.getElementById('progress-sub').textContent = `${total}টির মধ্যে ${done}টি সম্পন্ন`;
}

// KID TABS
function selectKid(el, name) {
  document.querySelectorAll('.kid-tab').forEach(x=>x.classList.remove('active'));
  el.classList.add('active');
  currentKid = name;
}

// DATE
function changeDate(dir) {
  var vd = window.rzViewDate || new Date();
  vd.setDate(vd.getDate() + dir);
  window.rzViewDate = new Date(vd);
  renderWeek();
  if (window.rzActiveKid && typeof rzLoadKidData === 'function') rzLoadKidData();
}

// MODAL
function openModal() {
  const grid = document.getElementById('emoji-grid');
  grid.innerHTML = '';
  HABIT_ICON_KEYS.forEach(key => {
    const el = document.createElement('div');
    el.className = 'emoji-option' + (key===selectedIconKey?' selected':'');
    el.innerHTML = HABIT_ICONS[key];
    el.title = key;
    el.onclick = () => {
      document.querySelectorAll('.emoji-option').forEach(x=>x.classList.remove('selected'));
      el.classList.add('selected');
      selectedIconKey = key;
    };
    grid.appendChild(el);
  });
  document.getElementById('modal').classList.add('show');
}
function closeModal(e) { if(e.target===document.getElementById('modal')) closeModalDirect(); }
function closeModalDirect() { document.getElementById('modal').classList.remove('show'); }

function addHabit() {
  const name = document.getElementById('habit-name-input').value.trim();
  const desc = document.getElementById('habit-desc-input').value.trim();
  if(!name) { alert('Habit এর নাম দিন'); return; }
  habits.push({ id: Date.now(), name, iconKey: selectedIconKey, desc: desc||'নতুন অভ্যাস', streak:0, points:10, done:false });
  closeModalDirect();
  document.getElementById('habit-name-input').value = '';
  document.getElementById('habit-desc-input').value = '';
  renderHabits();
  showToast(`"${name}" habit যোগ হয়েছে! ✅`);
}

// TOAST
function showToast(msg) {
  const t = document.getElementById('toast');
  const tm = document.getElementById('toast-msg');
  if (!t || !tm) { if (typeof cmToast === 'function') cmToast(msg); return; }
  tm.textContent = msg;
  t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'), 3000);
}

function goto(page) { alert(`"${page}" page এ যাচ্ছি... (এটি demo)`); }

// INIT — guarded: elements live in lazy-loaded pages/habits.html
if(document.getElementById('week-strip')) renderWeek();
if(document.getElementById('habits-list')) renderHabits();

