var rzAdultHabits = [];
var rzAdultActiveCat = 'all';
var rzAdultAddPtsSelected = 10;
var rzAdultAddCatSelected = 'health';
var rzAdultAddIconSelected = 'exercise';

function rzAdultTodayKey() {
  var d = new Date();
  return d.getFullYear() + '-' + (d.getMonth()+1) + '-' + d.getDate();
}

function rzLoadAdultHabits() {
  try {
    var saved = localStorage.getItem('rz_adult_habits_v2');
    rzAdultHabits = saved ? JSON.parse(saved) : JSON.parse(JSON.stringify(ADULT_DEFAULT_HABITS));
  } catch(e) {
    rzAdultHabits = JSON.parse(JSON.stringify(ADULT_DEFAULT_HABITS));
  }
  var todayKey = rzAdultTodayKey();
  rzAdultHabits.forEach(function(h) { if(h.lastDoneDate !== todayKey) h.done = false; });
  rzSaveAdultHabits();
}

async function rzLoadAdultHabitsFromSb() {
  if(!window.sbUser||!_sb) return;
  try {
    var res = await _sb.from('adult_habits').select('*').eq('user_id',sbUser.id).order('created_at',{ascending:true});
    if(res.data&&res.data.length) {
      var todayKey = rzAdultTodayKey();
      rzAdultHabits = res.data.map(function(r){
        var done = r.done && r.last_done_date===todayKey;
        return {id:r.id,name:r.name,iconKey:r.icon_key||'exercise',cat:r.cat||'health',desc:r.description||'',streak:r.streak||0,points:r.points||10,done:done,lastDoneDate:r.last_done_date||'',history:r.history||[]};
      });
      try{localStorage.setItem('rz_adult_habits_v2',JSON.stringify(rzAdultHabits));}catch(e){}
    } else {
      rzLoadAdultHabits();
    }
  } catch(e) { rzLoadAdultHabits(); }
}

function rzSaveAdultHabits() {
  try { localStorage.setItem('rz_adult_habits_v2', JSON.stringify(rzAdultHabits)); } catch(e) {}
  if(!window.sbUser||!_sb) return;
  rzAdultHabits.forEach(function(h){
    _sb.from('adult_habits').upsert({id:h.id,user_id:sbUser.id,name:h.name,icon_key:h.iconKey||'exercise',cat:h.cat||'health',description:h.desc||'',streak:h.streak||0,points:h.points||10,done:h.done||false,last_done_date:h.lastDoneDate||'',history:h.history||[]},{onConflict:'id'});
  });
}

function rzRenderAdultHabits() {
  if(window.sbUser&&_sb) {
    rzLoadAdultHabitsFromSb().then(function(){ rzRenderAdultHero(); rzRenderAdultCatTabs(); rzRenderAdultHabitList(); });
  } else {
    rzLoadAdultHabits();
    rzRenderAdultHero(); rzRenderAdultCatTabs(); rzRenderAdultHabitList();
  }
}

function rzRenderAdultHero() {
  var today = new Date();
  var dateEl = document.getElementById('ahab-date');
  if(dateEl) dateEl.textContent = rzBnDaysFull[today.getDay()] + ', ' + rzToBn(today.getDate()) + ' ' + rzBnMonths[today.getMonth()] + ' ' + rzToBn(today.getFullYear());

  var msgs = ['প্রতিটি অভ্যাস তোমাকে আরও শক্তিশালী করে','ছোট পদক্ষেপ বড় পরিবর্তন আনে','আজকের পরিশ্রম কালকের সাফল্য','ধারাবাহিকতাই সাফল্যের চাবিকাঠি','তুমি পারবে — শুরু করো এখনই!','শুধু একটু করে এগিয়ে যাও প্রতিদিন','অভ্যাস গড়া হয় প্রতিটি ছোট পদক্ষেপে'];
  var motEl = document.getElementById('ahab-motivation');
  if(motEl && !motEl._rzSet) { motEl.textContent = msgs[today.getDay() % msgs.length]; motEl._rzSet = true; }

  var done  = rzAdultHabits.filter(function(h){ return h.done; }).length;
  var total = rzAdultHabits.length;
  var pct   = total > 0 ? Math.round((done/total)*100) : 0;
  var todayPts = rzAdultHabits.filter(function(h){ return h.done; }).reduce(function(s,h){ return s+h.points; }, 0);
  var maxStreak = rzAdultHabits.length > 0 ? Math.max.apply(null, rzAdultHabits.map(function(h){ return h.streak||0; })) : 0;

  var pctEl = document.getElementById('ahab-pct');       if(pctEl) pctEl.textContent = pct + '%';
  var ptsEl = document.getElementById('ahab-pts');       if(ptsEl) ptsEl.textContent = todayPts;
  var strEl = document.getElementById('ahab-streak');    if(strEl) strEl.textContent = rzToBn(maxStreak) + '🔥';
  var dtEl  = document.getElementById('ahab-done-txt');  if(dtEl)  dtEl.textContent  = rzToBn(done) + '/' + rzToBn(total);

  var ring = document.getElementById('ahab-ring');
  if(ring) ring.style.strokeDashoffset = (213.6 * (1 - pct/100)).toFixed(2);

  var allDone = document.getElementById('ahab-alldone');
  if(allDone) allDone.style.display = (done === total && total > 0) ? 'block' : 'none';
}

function rzRenderAdultCatTabs() {
  var container = document.getElementById('ahab-cats');
  if(!container) return;
  container.innerHTML = '';
  ADULT_HABIT_CATS.forEach(function(cat) {
    var isActive = cat.key === rzAdultActiveCat;
    var tab = document.createElement('div');
    tab.style.cssText = 'flex-shrink:0;display:flex;align-items:center;gap:5px;padding:7px 13px;border-radius:20px;font-size:12px;font-weight:700;cursor:pointer;transition:.2s;white-space:nowrap;border:1.5px solid '+(isActive?cat.color:'var(--border)')+';background:'+(isActive?cat.color+'20':'transparent')+';color:'+(isActive?cat.color:'var(--text2)')+';';
    tab.innerHTML = cat.svg + cat.label;
    tab.onclick = (function(k){ return function(){ rzAdultActiveCat=k; rzRenderAdultCatTabs(); rzRenderAdultHabitList(); }; })(cat.key);
    container.appendChild(tab);
  });
}

function rzRenderAdultHabitList() {
  var list = document.getElementById('ahab-list');
  if(!list) return;
  list.innerHTML = '';
  var filtered = rzAdultActiveCat==='all' ? rzAdultHabits : rzAdultHabits.filter(function(h){ return h.cat===rzAdultActiveCat; });
  if(filtered.length===0) {
    list.innerHTML = '<div style="text-align:center;padding:36px 16px;color:var(--text2)"><div style="font-size:36px;margin-bottom:10px">📭</div><div style="font-size:13px;font-weight:600">এই ক্যাটাগরিতে কোনো Habit নেই</div><div style="font-size:11px;opacity:.6;margin-top:4px">উপরের বাটনে ক্লিক করে যোগ করুন</div></div>';
    return;
  }
  var sorted = filtered.slice().sort(function(a,b){ return (a.done?1:0)-(b.done?1:0); });
  var todayD = new Date();
  sorted.forEach(function(h) {
    var cc = ADULT_CAT_COLORS[h.cat] || '#FF8A00';
    var rawIcon = HABIT_ICONS[h.iconKey] || HABIT_ICONS['default'];
    var icon = rawIcon.replace(/stroke="(?!none)[^"]*"/g, 'stroke="'+cc+'"');

    // 7-day dots
    var dotsHtml = '';
    for(var di=6; di>=0; di--) {
      var dd = new Date(todayD); dd.setDate(todayD.getDate()-di);
      var ddKey = dd.getFullYear()+'-'+(dd.getMonth()+1)+'-'+dd.getDate();
      var isToday2 = di===0;
      var wasDone  = (h.history||[]).indexOf(ddKey)!==-1 || (isToday2&&h.done);
      var sz = isToday2?'9px':'6px';
      dotsHtml += '<div style="width:'+sz+';height:'+sz+';border-radius:50%;background:'+(wasDone?cc:'rgba(128,128,128,0.2)')+(isToday2?';outline:2px solid '+cc+'40':'')+';transition:.2s" title="'+(isToday2?'আজ':rzToBn(dd.getDate())+'/'+(dd.getMonth()+1))+'"></div>';
    }

    var card = document.createElement('div');
    card.style.cssText = 'border-radius:18px;padding:15px 16px;margin-bottom:10px;display:flex;align-items:center;gap:14px;transition:all .25s;cursor:pointer;position:relative;overflow:hidden;'+(h.done?'border:1.5px solid '+cc+'55;background:linear-gradient(135deg,var(--card),'+cc+'08);opacity:.8;':'border:1.5px solid var(--border);background:var(--card);');

    card.innerHTML =
      (h.done?'<div style="position:absolute;left:0;top:0;bottom:0;width:4px;background:linear-gradient(180deg,'+cc+','+cc+'88);border-radius:4px 0 0 4px"></div>':'')+
      '<div style="width:48px;height:48px;border-radius:14px;background:'+cc+'1a;display:flex;align-items:center;justify-content:center;flex-shrink:0">'+icon+'</div>'+
      '<div style="flex:1;min-width:0">'+
        '<div style="font-size:13.5px;font-weight:700;color:var(--text);'+(h.done?'text-decoration:line-through;opacity:.65':'')+';overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+h.name+'</div>'+
        '<div style="font-size:11px;color:var(--text2);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+h.desc+'</div>'+
        '<div style="display:flex;align-items:center;gap:4px;margin-top:9px">'+dotsHtml+'<span style="font-size:9.5px;color:var(--text2);margin-left:5px;opacity:.7">৭ দিন</span></div>'+
      '</div>'+
      '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:8px;flex-shrink:0">'+
        '<div style="font-size:10px;font-weight:800;color:'+cc+';background:'+cc+'18;padding:3px 9px;border-radius:20px">+'+h.points+'pts</div>'+
        '<div style="font-size:11px;color:#EF4444;font-weight:700">🔥'+rzToBn(h.streak||0)+'d</div>'+
        '<div style="width:36px;height:36px;border-radius:50%;border:2.5px solid '+(h.done?cc:'var(--border)')+';background:'+(h.done?'linear-gradient(135deg,'+cc+','+cc+'cc)':'transparent')+';display:flex;align-items:center;justify-content:center;transition:.25s;flex-shrink:0">'+
          (h.done?'<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>':'')+
        '</div>'+
      '</div>';

    card.onclick = (function(hid){ return function(){ rzToggleAdultHabit(hid); }; })(h.id);
    list.appendChild(card);
  });
}

function rzToggleAdultHabit(id) {
  var h = rzAdultHabits.find ? rzAdultHabits.find(function(x){ return x.id===id; }) : (function(){ for(var i=0;i<rzAdultHabits.length;i++) if(rzAdultHabits[i].id===id) return rzAdultHabits[i]; }());
  if(!h) return;
  var todayKey = rzAdultTodayKey();
  h.done = !h.done;
  if(h.done) {
    h.lastDoneDate = todayKey;
    h.streak = (h.streak||0)+1;
    if(!h.history) h.history=[];
    if(h.history.indexOf(todayKey)===-1) h.history.push(todayKey);
    if(h.history.length>30) h.history=h.history.slice(-30);
    showToast(h.name+' সম্পন্ন! +'+h.points+' pts 🎉');
    var allDone = rzAdultHabits.every(function(x){ return x.done; });
    if(allDone) setTimeout(function(){ showToast('🏆 অসাধারণ! সব Habit সম্পন্ন! তুমিই Rizer!'); },600);
  } else {
    h.lastDoneDate = null;
    h.streak = Math.max(0,(h.streak||0)-1);
    var idx=(h.history||[]).indexOf(todayKey); if(idx!==-1) h.history.splice(idx,1);
  }
  rzSaveAdultHabits();
  rzRenderAdultHero();
  rzRenderAdultHabitList();
}

// ── Adult Add Habit Modal ──
function rzOpenAdultAddHabit() {
  var modal = document.getElementById('ahab-modal');
  if(!modal) return;
  var inp = document.getElementById('ahab-inp-name'); if(inp) inp.value='';
  var inp2= document.getElementById('ahab-inp-desc'); if(inp2) inp2.value='';
  rzAdultAddCatSelected  = 'health';
  rzAdultAddIconSelected = 'exercise';
  rzAdultAddPtsSelected  = 10;
  rzRenderAdultAddCats();
  rzRenderAdultAddIcons();
  rzRenderAdultAddPts();
  modal.style.display = 'flex';
  setTimeout(function(){
    var box = modal.querySelector('.ahab-modal-box');
    if(box){ box.style.transform='translateY(0)'; box.style.opacity='1'; }
  }, 10);
}

function rzCloseAdultAddHabit() {
  var modal = document.getElementById('ahab-modal');
  if(!modal) return;
  var box = modal.querySelector('.ahab-modal-box');
  if(box){ box.style.transform='translateY(60px)'; box.style.opacity='0'; }
  setTimeout(function(){ modal.style.display='none'; }, 220);
}

function rzRenderAdultAddCats() {
  var c = document.getElementById('ahab-modal-cats'); if(!c) return;
  c.innerHTML='';
  ADULT_HABIT_CATS.filter(function(x){ return x.key!=='all'; }).forEach(function(cat) {
    var isA = cat.key===rzAdultAddCatSelected;
    var el = document.createElement('div');
    el.style.cssText='display:flex;align-items:center;gap:5px;padding:6px 12px;border-radius:20px;font-size:11.5px;font-weight:700;cursor:pointer;transition:.15s;border:1.5px solid '+(isA?cat.color:'var(--border)')+';background:'+(isA?cat.color+'22':'transparent')+';color:'+(isA?cat.color:'var(--text2)')+';white-space:nowrap';
    el.innerHTML=cat.svg+cat.label;
    el.onclick=(function(k){ return function(){ rzAdultAddCatSelected=k; rzRenderAdultAddCats(); }; })(cat.key);
    c.appendChild(el);
  });
}

function rzSelectAdultPts(pts) {
  rzAdultAddPtsSelected = pts;
  rzRenderAdultAddPts();
}

function rzRenderAdultAddPts() {
  [10,15,20].forEach(function(v) {
    var el = document.getElementById('ahab-pts-'+v);
    if(!el) return;
    var isA = rzAdultAddPtsSelected===v;
    el.style.borderColor  = isA ? '#FF8A00' : 'var(--border)';
    el.style.background   = isA ? 'rgba(255,138,0,0.15)' : 'transparent';
    el.style.color        = isA ? '#FF8A00' : 'var(--text2)';
  });
}

function rzRenderAdultAddIcons() {
  var g = document.getElementById('ahab-modal-icons'); if(!g) return;
  g.innerHTML='';
  var keys = Object.keys(HABIT_ICONS).filter(function(k){ return k!=='default'; });
  keys.forEach(function(key) {
    var isA = key===rzAdultAddIconSelected;
    var el = document.createElement('div');
    el.style.cssText='width:42px;height:42px;border-radius:11px;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:.15s;border:1.5px solid '+(isA?'#FF8A00':'var(--border)')+';background:'+(isA?'rgba(255,138,0,0.15)':'var(--bg,#f8f9fa)')+';';
    el.innerHTML=HABIT_ICONS[key];
    el.onclick=(function(k){ return function(){ rzAdultAddIconSelected=k; rzRenderAdultAddIcons(); }; })(key);
    g.appendChild(el);
  });
}

function rzSaveAdultNewHabit() {
  var nameEl = document.getElementById('ahab-inp-name');
  var descEl = document.getElementById('ahab-inp-desc');
  var name = nameEl ? nameEl.value.trim() : '';
  var desc = descEl ? descEl.value.trim() : '';
  if(!name) { showToast('Habit এর নাম দিন!'); return; }
  rzAdultHabits.push({ id:Date.now(), name:name, iconKey:rzAdultAddIconSelected, cat:rzAdultAddCatSelected, desc:desc||'নতুন অভ্যাস', streak:0, points:rzAdultAddPtsSelected, done:false, history:[] });
  rzSaveAdultHabits();
  rzCloseAdultAddHabit();
  rzRenderAdultHero();
  rzRenderAdultCatTabs();
  rzRenderAdultHabitList();
  showToast('"'+name+'" Habit যোগ হয়েছে! ✅');
}

