function _kzH(){
  var pg=document.getElementById('knokz-page');
  if(!pg||pg.style.display==='none')return;
  var topEl=document.querySelector('.app-topbar,.app-header,.top-nav,#top-bar');
  var botEl=document.querySelector('.rz-bottomnav,.rz-bottom-nav,.bottom-nav-bar,#bottom-nav');
  var topH=topEl&&botEl&&botEl.style.display!=='none'?topEl.offsetHeight:topEl?topEl.offsetHeight:56;
  var botH=botEl&&botEl.style.display!=='none'?botEl.offsetHeight:0;
  var h=window.innerHeight-topH-botH;
  // Use CSS variable to beat height:auto!important in media query
  document.documentElement.style.setProperty('--kz-h',h+'px');
  pg.style.setProperty('height',h+'px','important');
  var root=document.getElementById('kz-root');
  if(root)root.style.height=h+'px';
}

function _kzCK(a,b){return[a,b].sort().join('_');}
function _kzFmt(ts){if(!ts)return'';var d=new Date(ts),n=new Date();return d.toDateString()===n.toDateString()?d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):d.toLocaleDateString([],{month:'short',day:'numeric'});}
function _kzAv(p,sz){sz=sz||48;if(p&&p.avatar_url)return'<img src="'+p.avatar_url+'" style="width:'+sz+'px;height:'+sz+'px;border-radius:50%;object-fit:cover;flex-shrink:0">';var i=(p&&p.name)?p.name.charAt(0).toUpperCase():'?';return'<div style="width:'+sz+'px;height:'+sz+'px;border-radius:50%;background:linear-gradient(135deg,#FF8A00,#FFB800);display:flex;align-items:center;justify-content:center;font-size:'+Math.round(sz/2.8)+'px;font-weight:700;color:#090B12;flex-shrink:0">'+i+'</div>';}

