    if(!convs.length){el.innerHTML=_hadiRowHTML+'<div style="text-align:center;padding:52px 20px"><div style="margin-bottom:12px;display:flex;justify-content:center"><svg width="64" height="64" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg"><rect width="64" height="64" rx="18" fill="#FF8A0015"/><path d="M44 22H20C18.9 22 18 22.9 18 24V40C18 41.1 18.9 42 20 42H27V47L34.5 42H44C45.1 42 46 41.1 46 40V24C46 22.9 45.1 22 44 22Z" fill="#FF8A00" opacity="0.15"/><path d="M44 22H20C18.9 22 18 22.9 18 24V40C18 41.1 18.9 42 20 42H27V47L34.5 42H44C45.1 42 46 41.1 46 40V24C46 22.9 45.1 22 44 22Z" stroke="#FF8A00" stroke-width="1.8" stroke-linejoin="round"/><circle cx="25" cy="32" r="2" fill="#FF8A00"/><circle cx="32" cy="32" r="2" fill="#FF8A00"/><circle cx="39" cy="32" r="2" fill="#FF8A00"/></svg></div><div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:4px">No messages yet</div><div style="font-size:12px;color:var(--sub-text)">Connect with Risers and say hi!</div></div>';return;}
