/* ── Hadi AI Partner ─────────────────────────────── */
// hadi_history/hadi_proactive used to be stored under one shared, unscoped localStorage
// key — every account on the same browser saw the previous account's Hadi conversation.
// Keying by user id fixes that; _hadiPurgeLegacyKeys() removes the old shared key so it
// can never leak to a fresh account again.
function _hadiStorageKey(base){
  var uid=(typeof sbUser!=='undefined'&&sbUser&&sbUser.id)?sbUser.id:'anon';
  return base+'_'+uid;
}
function _hadiPurgeLegacyKeys(){
  try{localStorage.removeItem('hadi_history');localStorage.removeItem('hadi_proactive');}catch(e){}
}
var _hadiHistory=[];
// Groq calls go through a server-side proxy (supabase/functions/groq-proxy) — the API key
// never lives in this client bundle. See _groqProxyFetch below.
var _groqProxyUrl='https://zsmyscntuunrmzekdxjo.supabase.co/functions/v1/groq-proxy';
async function _groqProxyFetch(groqPath,body,isForm){
  var sess=await _sb.auth.getSession();
  var token=sess&&sess.data&&sess.data.session&&sess.data.session.access_token;
  var headers={'Authorization':'Bearer '+(token||''),'x-groq-path':groqPath};
  if(!isForm)headers['Content-Type']='application/json';
  return fetch(_groqProxyUrl,{method:'POST',headers:headers,body:body});
}
var _hadiModels=[
  {id:'llama-3.3-70b-versatile',api:'groq'},
  {id:'meta-llama/llama-4-scout-17b-16e-instruct',api:'groq'},
  {id:'llama-3.1-8b-instant',api:'groq'}
];
var _hadiModelIdx=0;
var _hadiModelCooldown={};

(function(){
  var k=localStorage.getItem('hadi_gemini_key');
  if(k)_hadiGeminiKey=k;
})();

window.kzHadiSetGeminiKey=function(key){
  _hadiGeminiKey=key||'';
  if(key)localStorage.setItem('hadi_gemini_key',key);
  else localStorage.removeItem('hadi_gemini_key');
  console.log('Hadi: Gemini key '+(key?'set':'cleared'));
};

function _hadiGetModel(){
  var now=Date.now();
  for(var i=0;i<_hadiModels.length;i++){
    var idx=(_hadiModelIdx+i)%_hadiModels.length;
    var m=_hadiModels[idx];
    if(m.api==='gemini'&&!_hadiGeminiKey)continue; // skip Gemini if no key
    if(!_hadiModelCooldown[m.id]||(now-_hadiModelCooldown[m.id])>60000){
      _hadiModelIdx=idx;
      return m;
    }
  }
  // All rate-limited — return least-recently-limited Groq model
  for(var j=0;j<_hadiModels.length;j++){
    if(_hadiModels[j].api==='groq')return _hadiModels[j];
  }
  return _hadiModels[_hadiModels.length-1];
}

async function _hadiCallGemini(messages,maxTokens,modelId){
  // Convert OpenAI messages format to Gemini format
  var systemText='';
  var contents=[];
  for(var i=0;i<messages.length;i++){
    var msg=messages[i];
    if(msg.role==='system'){systemText=msg.content;continue;}
    contents.push({role:msg.role==='assistant'?'model':'user',parts:[{text:msg.content}]});
  }
  var body={
    contents:contents,
    generationConfig:{maxOutputTokens:maxTokens||300,temperature:0.75,responseMimeType:'application/json'}
  };
  if(systemText)body.systemInstruction={parts:[{text:systemText}]};
  return fetch('https://generativelanguage.googleapis.com/v1beta/models/'+modelId+':generateContent?key='+_hadiGeminiKey,{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify(body)
  });
}

async function _hadiCallGroq(messages,maxTokens){
  var tried=new Set();
  for(var attempt=0;attempt<_hadiModels.length*2;attempt++){
    var model=_hadiGetModel();
    if(tried.has(model.id))break;
    tried.add(model.id);
    try{
      var res;
      if(model.api==='openrouter'){
        res=await fetch('https://openrouter.ai/api/v1/chat/completions',{
          method:'POST',
          headers:{'Authorization':'Bearer '+_hadiOpenRouterKey,'Content-Type':'application/json','HTTP-Referer':'https://rizers.app','X-Title':'Rizers Hadi'},
          body:JSON.stringify({model:model.id,messages:messages,max_tokens:maxTokens||300,temperature:0.75,response_format:{type:'json_object'}})
        });
        if(res.ok){console.log('Hadi: using',model.id);return res;}
        if(res.status===429||res.status===503||res.status===502){
          _hadiModelCooldown[model.id]=Date.now();
          _hadiModelIdx=(_hadiModelIdx+1)%_hadiModels.length;
          console.log('Hadi: '+model.id+' rate limited, trying next...');
          continue;
        }
        console.warn('Hadi: OpenRouter error',res.status,model.id);
        _hadiModelCooldown[model.id]=Date.now();
        _hadiModelIdx=(_hadiModelIdx+1)%_hadiModels.length;
        continue;
      } else if(model.api==='gemini'){
        res=await _hadiCallGemini(messages,maxTokens,model.id);
        if(res.ok){
          var gData=await res.json();
          var gText=(gData.candidates&&gData.candidates[0]&&gData.candidates[0].content&&gData.candidates[0].content.parts&&gData.candidates[0].content.parts[0]&&gData.candidates[0].content.parts[0].text)||'{"message":"একটু সমস্যা হলো।","actions":[]}';
          return {ok:true,json:function(){return Promise.resolve({choices:[{message:{content:gText}}]});}};
        }
        if(res.status===429||res.status===503){
          _hadiModelCooldown[model.id]=Date.now();
          _hadiModelIdx=(_hadiModelIdx+1)%_hadiModels.length;
          console.log('Hadi: Gemini rate limited, trying next...');
          continue;
        }
        console.warn('Hadi: Gemini error',res.status);
        _hadiModelCooldown[model.id]=Date.now();
        _hadiModelIdx=(_hadiModelIdx+1)%_hadiModels.length;
        continue;
      } else {
        res=await _groqProxyFetch('chat/completions',JSON.stringify({model:model.id,messages:messages,max_tokens:maxTokens||300,temperature:0.75,response_format:{type:'json_object'}}));
        if(res.status===429){
          _hadiModelCooldown[model.id]=Date.now();
          _hadiModelIdx=(_hadiModelIdx+1)%_hadiModels.length;
          console.log('Hadi: '+model.id+' rate limited, trying next...');
          continue;
        }
        if(res.status===400){
          _hadiModelCooldown[model.id]=Date.now()+15000;
          _hadiModelIdx=(_hadiModelIdx+1)%_hadiModels.length;
          console.log('Hadi: '+model.id+' bad request (transient — retrying in 15s)...');
          continue;
        }
        return res;
      }
    }catch(e){
      console.warn('Hadi: network error for',model.id,e);
      _hadiModelCooldown[model.id]=Date.now();
      _hadiModelIdx=(_hadiModelIdx+1)%_hadiModels.length;
      continue;
    }
  }
  return null;
}

window.kzHadiClearChat=function(){
  if(!confirm('Chat history clear করবো?'))return;
  _hadiHistory=[];
  localStorage.removeItem(_hadiStorageKey('hadi_history'));
  var el=document.getElementById('kz-hadi-msgs');
  if(el)el.innerHTML='';
  setTimeout(function(){_hadiGreet();},400);
};

window.kzOpenHadi=function(){
  var panel=document.getElementById('kz-hadi-panel');
  if(!panel)return;
  panel.style.display='flex';
  requestAnimationFrame(function(){panel.style.transform='translateX(0)';});
  _hadiPurgeLegacyKeys();
  try{
    _hadiHistory=JSON.parse(localStorage.getItem(_hadiStorageKey('hadi_history'))||'[]');
    // Auto-clear corrupted history (raw JSON messages)
    var hasCorruption=_hadiHistory.some(function(m){return m.content&&m.content.trim().startsWith('{');});
    if(hasCorruption){_hadiHistory=[];localStorage.removeItem(_hadiStorageKey('hadi_history'));}
  }catch(e){_hadiHistory=[];}
  _hadiRenderHistory();
  if(_hadiHistory.length===0){setTimeout(function(){_hadiGreet();},600);}
  else{setTimeout(function(){_hadiProactiveCheck();},800);}
};

window.kzCloseHadi=function(){
  var panel=document.getElementById('kz-hadi-panel');
  if(panel)panel.style.transform='translateX(100%)';
  setTimeout(function(){if(panel)panel.style.display='none';},300);
};

function _hadiRenderHistory(){
  var el=document.getElementById('kz-hadi-msgs');
  if(!el)return;
  el.innerHTML='';
  _hadiHistory.forEach(function(msg){_hadiAppendBubble(msg.role,msg.content);});
  el.scrollTop=el.scrollHeight;
}

function _hadiAppendBubble(role,text,isHtml,quickReplies){
  var el=document.getElementById('kz-hadi-msgs');
  if(!el)return;
  // Remove any existing quick-reply buttons
  var old=el.querySelector('.hadi-quick-replies');
  if(old)old.remove();
  var div=document.createElement('div');
  div.className='hadi-msg-bubble '+(role==='assistant'?'hadi-msg-hadi':'hadi-msg-user');
  if(isHtml){div.innerHTML=text;}else{div.textContent=text;}
  el.appendChild(div);
  if(role==='assistant'&&quickReplies&&quickReplies.length){
    var row=document.createElement('div');
    row.className='hadi-quick-replies';
    row.style.cssText='display:flex;flex-wrap:wrap;gap:8px;padding:4px 12px 8px 12px;';
    quickReplies.forEach(function(label){
      var btn=document.createElement('button');
      btn.textContent=label;
      btn.style.cssText='background:var(--card);border:1.5px solid #FF8A00;color:#FF8A00;border-radius:20px;padding:6px 14px;font-size:13px;cursor:pointer;font-family:inherit;transition:all 0.15s;';
      btn.onmouseover=function(){this.style.background='#FF8A00';this.style.color='#fff';};
      btn.onmouseout=function(){this.style.background='var(--card)';this.style.color='#FF8A00';};
      btn.onclick=function(){
        var r=el.querySelector('.hadi-quick-replies');
        if(r)r.remove();
        var inp=document.getElementById('kz-hadi-input');
        if(inp){inp.textContent=label;}
        window.kzHadiSend&&window.kzHadiSend();
      };
      row.appendChild(btn);
    });
    el.appendChild(row);
  }
  el.scrollTop=el.scrollHeight;
}

// ═══════════════════════════════════════════════════════════════
// Menu-tree navigation — button clicks call handlers directly, bypassing
// all regex/AI intent-parsing. _hadiMenuState only tracks the rare case
// where we're waiting for a raw text VALUE (e.g. a habit name) — the
// intent itself was already decided by the button that got us here.
// ═══════════════════════════════════════════════════════════════
var _hadiMenuState=null; // null | {step:'habit_add_name'}

function _hadiMenuButtons(list){
  var el=document.getElementById('kz-hadi-msgs');
  if(!el)return;
  var old=el.querySelector('.hadi-menu-buttons');
  if(old)old.remove();
  var row=document.createElement('div');
  row.className='hadi-menu-buttons';
  row.style.cssText='display:flex;flex-wrap:wrap;gap:8px;padding:4px 12px 10px 12px;';
  list.forEach(function(item){
    var btn=document.createElement('button');
    btn.textContent=item.label;
    btn.style.cssText='background:var(--card);border:1.5px solid #FF8A00;color:#FF8A00;border-radius:20px;padding:6px 14px;font-size:13px;cursor:pointer;font-family:inherit;transition:all 0.15s;';
    btn.onmouseover=function(){this.style.background='#FF8A00';this.style.color='#fff';};
    btn.onmouseout=function(){this.style.background='var(--card)';this.style.color='#FF8A00';};
    btn.onclick=function(){
      var r=el.querySelector('.hadi-menu-buttons');
      if(r)r.remove();
      if(item.label!=='🏠 মেনু')_hadiAppendBubble('user',item.label); // echo the click so it's obvious it registered — skip the menu button itself, that's a reset not a choice
      item.onClick();
    };
    row.appendChild(btn);
  });
  el.appendChild(row);
  el.scrollTop=el.scrollHeight;
}

