// ── Goal ──
// ctx.goals (from _hadiGetContext) is just plain text strings — the menu-tree needs
// id/progress/done to target the right row and offer progress-aware buttons, so it
// fetches the richer adult_goals rows directly instead of piggybacking on ctx.
async function _hadiFetchGoalsRaw(){
  if(!window.sbUser||typeof _sb==='undefined')return [];
  var res=await _sb.from('adult_goals').select('id,text,progress,done').eq('user_id',sbUser.id).order('created_at',{ascending:false}).limit(20);
  return res.data||[];
}

