function _hadiShowCard(type,ctx){
  var el=document.getElementById('kz-hadi-msgs');
  if(!el)return;
  var card=document.createElement('div');
  card.style.cssText='margin:8px 0;width:100%;';
  if(type==='streak'){
    var s=ctx.streak||0;
    var fire=s>=21?'🔥🔥🔥':s>=7?'🔥🔥':s>=1?'🔥':'💤';
    card.innerHTML='<div style="background:linear-gradient(135deg,#FF8A00,#FFB800);border-radius:16px;padding:16px;color:#fff;text-align:center;">'
      +'<div style="font-size:32px;margin-bottom:4px;">'+fire+'</div>'
      +'<div style="font-size:28px;font-weight:800;">'+s+' দিন</div>'
      +'<div style="font-size:13px;opacity:.85;margin-top:2px;">টানা streak</div>'
      +'</div>';
  }else if(type==='habits'){
    var done=ctx.habitsRaw.filter(function(h){return h.done;}).length;
    var total=ctx.habitsRaw.length;
    var pct=total?Math.round(done/total*100):0;
    var rows=ctx.habitsRaw.map(function(h){
      return '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid rgba(255,255,255,.15);">'
        +'<span style="font-size:13px;">'+h.name+'</span>'
        +'<span style="font-size:16px;">'+(h.done?'✅':'⏳')+'</span></div>';
    }).join('');
    card.innerHTML='<div style="background:linear-gradient(135deg,#1a1a2e,#16213e);border-radius:16px;padding:16px;color:#fff;">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">'
      +'<span style="font-weight:700;font-size:15px;">আজকের হ্যাবিট</span>'
      +'<span style="background:#FF8A00;padding:3px 10px;border-radius:20px;font-size:13px;font-weight:700;">'+done+'/'+total+'</span></div>'
      +rows
      +'<div style="margin-top:10px;background:rgba(255,255,255,.1);border-radius:8px;height:8px;">'
      +'<div style="background:#FF8A00;height:8px;border-radius:8px;width:'+pct+'%;transition:width .5s;"></div></div>'
      +'<div style="text-align:right;font-size:12px;opacity:.7;margin-top:4px;">'+pct+'% complete</div>'
      +'</div>';
  }else if(type==='todos'){
    var tRows=(ctx.todos||[]).slice(0,6).map(function(t){
      return '<div style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.1);">'
        +'<span style="font-size:14px;">⬜</span><span style="font-size:13px;">'+t+'</span></div>';
    }).join('')||(ctx.todos&&ctx.todos.length===0?'<div style="font-size:13px;opacity:.7;padding:8px 0;">কোনো pending todo নেই 🎉</div>':'');
    card.innerHTML='<div style="background:linear-gradient(135deg,#2d1b69,#1a0533);border-radius:16px;padding:16px;color:#fff;">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">'
      +'<span style="font-weight:700;font-size:15px;">Todo List</span>'
      +'<span style="background:#7c3aed;padding:3px 10px;border-radius:20px;font-size:13px;font-weight:700;">'+(ctx.todos?ctx.todos.length:0)+'টি</span></div>'
      +tRows+'</div>';
  }else if(type==='goals'){
    var gRows=ctx.goals.slice(0,5).map(function(g){
      return '<div style="padding:7px 0;border-bottom:1px solid rgba(255,255,255,.1);font-size:13px;">🎯 '+g+'</div>';
    }).join('');
    card.innerHTML='<div style="background:linear-gradient(135deg,#0f3460,#16213e);border-radius:16px;padding:16px;color:#fff;">'
      +'<div style="font-weight:700;font-size:15px;margin-bottom:10px;">তোমার লক্ষ্যগুলো</div>'
      +gRows+'</div>';
  }else if(type==='namaz'){
    var prayers=['Fajr','Dhuhr','Asr','Maghrib','Isha'];
    var today=new Date().toISOString().slice(0,10);
    var todayLogs=ctx.namaz.filter(function(n){return n.startsWith(today);});
    var prayerRows=prayers.map(function(p){
      var done=todayLogs.some(function(n){return n.includes(p);});
      return '<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;">'
        +'<span style="font-size:13px;">'+p+'</span>'
        +'<span style="font-size:16px;">'+(done?'✅':'⬜')+'</span></div>';
    }).join('');
    var doneCount=prayers.filter(function(p){return todayLogs.some(function(n){return n.includes(p);});}).length;
    card.innerHTML='<div style="background:linear-gradient(135deg,#1b4332,#2d6a4f);border-radius:16px;padding:16px;color:#fff;">'
      +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">'
      +'<span style="font-weight:700;font-size:15px;">আজকের নামাজ</span>'
      +'<span style="background:#52b788;padding:3px 10px;border-radius:20px;font-size:13px;font-weight:700;">'+doneCount+'/5</span></div>'
      +prayerRows+'</div>';
  }
  el.appendChild(card);
  el.scrollTop=el.scrollHeight;
}

// Pattern detection — runs on open, returns insights
function _hadiDetectPatterns(ctx){
  var insights=[];
  var today=new Date().toISOString().slice(0,10);
  // Namaz miss pattern
  var last3days=[];
  for(var i=1;i<=3;i++){var d=new Date();d.setDate(d.getDate()-i);last3days.push(d.toISOString().slice(0,10));}
  var fajrMissed=last3days.filter(function(d){
    return !ctx.namaz.some(function(n){return n.startsWith(d)&&n.includes('Fajr');});
  }).length;
  if(fajrMissed>=2)insights.push('ফজর '+fajrMissed+' দিন ধরে miss হচ্ছে');
  // Habit streak about to break
  var pendingToday=ctx.habitsRaw.filter(function(h){return !h.done;});
  if(pendingToday.length>0){
    var highStreak=ctx.habitsRaw.filter(function(h){return !h.done&&(h.streak||0)>=3;});
    if(highStreak.length>0){
      insights.push(highStreak[0].name+' এর '+highStreak[0].streak+' দিনের streak আজ ভাঙতে পারে');
    }
  }
  // All habits done
  if(ctx.habitsRaw.length>0&&ctx.habitsRaw.every(function(h){return h.done;})){
    insights.push('আজকের সব habit complete! মাশাআল্লাহ 🎉');
  }
  return insights;
}

