var _hadiCtxCache=null,_hadiCtxCacheTime=0;
var _hadiPendingAdd=null; // {type:'habit'|'todo'|'goal'} — set when we asked user to name items, waiting for reply
var _hadiLastTopic=null; // last habit/todo/goal/namaz/streak topic discussed — lets bare "চেক করি"/"check" replies resolve to a real card

var _hadiAddTriggerStrip=/হ্যাবিট|অভ্যাস|habit|টুডু|todo|to\s*do|কাজ|গোল|লক্ষ্য|goal|[0-9০-৯]+\s*(টা|টি)|যোগ করো|যোগ করে দাও|যোগ করে দিও|যোগ|যুক্ত|add|করে দাও|করে দিও|করো|koro|kora|আমার জন্য|আমার|\bte\b|\bdao\b|\bjeno\b|\bvule\b|\bna\b|\bjai\b|\bholo\b|\bhoyeche\b|\bkorte\b|\bhobe\b|\bchai\b|\bkorbo\b|\bkore\b/gi;
function _hadiExtractItems(text){
  // Complex/long sentences ("আরেকটা কাজ যুক্ত করো আমি ভিডিও রেকর্ড করবো...") are unsafe to regex-strip —
  // Bengali has no reliable \b word boundary, so filler words leak into the item name. For anything but
  // a short, direct phrase, skip regex entirely and let the caller fall back to AI extraction.
  if(text.split(/\s+/).filter(Boolean).length>8)return [];
  var out=text.replace(_hadiAddTriggerStrip,' ').split(/,|৷|আর\s+|এবং\s+|\n|-|:/).map(function(s){return s.trim().replace(/\s+/g,' ');}).filter(function(s){return s.length>=2;});
  // if leftover Banglish filler words remain, extraction is unreliable — reject so it falls through to AI extraction
  out=out.filter(function(s){return !/\b(te|dao|jeno|vule|na|jai|kore|korte|hobe|chai|korbo)\b/i.test(s);});
  // if any item is itself still long/wordy, it's probably an un-stripped fragment, not a clean name
  return out.filter(function(s){return s.split(/\s+/).filter(Boolean).length<=5;});
}

async function _hadiAIExtractAdd(type,text){
  var label=type==='habit'?'habit (অভ্যাস)':type==='todo'?'todo (কাজ)':'goal (লক্ষ্য)';
  var sys='তুমি একটা structured data extractor, কোনো personality নেই। user এর বাংলা/বাংলিশ বাক্য পড়ে বুঝবে সে কী কী '+label+' add করতে চাইছে। '+
    'শুধু valid JSON দিবে, অন্য কোনো টেক্সট না। Format: {"items":["আইটেম ১","আইটেম ২"]}। '+
    'যদি user স্পষ্ট কোনো নাম/বিষয় না বলে থাকে (শুধু সংখ্যা বা "add করো" বলেছে), items কে empty array [] রাখবে — নিজে থেকে নাম বানাবে না। '+
    'বাক্যের ভেতরের filler শব্দ (add করো, habit, যোগ করো ইত্যাদি) বাদ দিয়ে শুধু আসল item এর নাম রাখবে, প্রতিটা item সংক্ষিপ্ত রাখবে।';
  var msgs=[{role:'system',content:sys},{role:'user',content:text}];
  // Extraction needs strict instruction-following (empty-array-when-unsure) — small 8b model hallucinates
  // fake item names here, so only use the reliable models for this task, not the full fallback chain.
  var extractModels=['llama-3.3-70b-versatile','meta-llama/llama-4-scout-17b-16e-instruct'];
  for(var i=0;i<extractModels.length;i++){
    try{
      var res=await _groqProxyFetch('chat/completions',JSON.stringify({model:extractModels[i],messages:msgs,max_tokens:120,temperature:0.2,response_format:{type:'json_object'}}));
      if(!res.ok)continue;
      var data=await res.json();
      var raw=(data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||'{"items":[]}';
      var clean=raw.replace(/^```json\s*/,'').replace(/```\s*$/,'').trim();
      var parsed=JSON.parse(clean);
      return Array.isArray(parsed.items)?parsed.items.filter(function(s){return typeof s==='string'&&s.trim().length>=2;}).map(function(s){return s.trim();}):[];
    }catch(e){continue;}
  }
  return [];
}

async function _hadiRuleAddItems(type,items){
  if(!window.sbUser||typeof _sb==='undefined')return;
  _hadiShowTyping();
  var results=[];
  for(var i=0;i<items.length;i++){
    var name=items[i];
    if(type==='habit'){results.push(await _hadiRunOneAction({type:'add_habit',name:name}));}
    else if(type==='todo'){results.push(await _hadiRunOneAction({type:'add_todo',title:name}));}
    else if(type==='goal'){results.push(await _hadiRunOneAction({type:'add_goal',text:name}));}
  }
  _hadiHideTyping();
  _hadiCtxCacheTime=0;
  var okMsgs=results.filter(Boolean);
  _hadiAppendBubble('assistant',okMsgs.length?okMsgs.join('\n'):'😅 কিছু add করা গেলো না, নাম গুলো একটু পরিষ্কার করে আবার বলো।');
}
async function _hadiGetContext(force){
  var now=Date.now();
  if(!force&&_hadiCtxCache&&(now-_hadiCtxCacheTime)<60000)return _hadiCtxCache;
  var ctx={name:'User',streak:0,goals:[],habits:[],habitsRaw:[],namaz:[],fasting:[],todos:[],completedTodos:[],journal:[],finance:[],sleep:[],deepwork:[],quran:null,study:null,reading:null,notes:[],weeklyReview:null};
  if(!sbUser||typeof _sb==='undefined')return ctx;
  try{
    if(sbProfile){ctx.name=sbProfile.name||'User';ctx.streak=sbProfile.streak_count||0;}
    var today=new Date().toISOString().slice(0,10);
    var d7=new Date();d7.setDate(d7.getDate()-7);var week7=d7.toISOString().slice(0,10);
    var results=await Promise.all([
      _sb.from('adult_goals').select('text,created_at').eq('user_id',sbUser.id).limit(20),
      _sb.from('adult_habits').select('name,streak,done,last_done_date').eq('user_id',sbUser.id).limit(30),
      _sb.from('adult_namaz_logs').select('prayer,status,date').eq('user_id',sbUser.id).order('date',{ascending:false}).limit(15),
      _sb.from('todo_tasks').select('title,status').eq('user_id',sbUser.id).eq('status','pending').limit(20),
      _sb.from('journal_entries').select('content,created_at').eq('user_id',sbUser.id).order('created_at',{ascending:false}).limit(3),
      _sb.from('finance_transactions').select('amount,type,note,date').eq('user_id',sbUser.id).order('date',{ascending:false}).limit(5),
      _sb.from('fasting_logs').select('date,type').eq('user_id',sbUser.id).order('date',{ascending:false}).limit(5),
      _sb.from('todo_tasks').select('title').eq('user_id',sbUser.id).eq('status','done').limit(10),
      _sb.from('adult_sleep_logs').select('date_key,dur,q,st,wt').eq('user_id',sbUser.id).gte('date_key',week7).order('date_key',{ascending:false}).limit(7),
      _sb.from('deepwork_sessions').select('*').eq('user_id',sbUser.id).gte('date',week7).order('date',{ascending:false}).limit(7),
      _sb.from('adult_quran_data').select('tilawat,progress,daily_goal,updated_at').eq('user_id',sbUser.id).maybeSingle(),
      _sb.from('adult_study_data').select('logs,goal,total_xp,updated_at').eq('user_id',sbUser.id).maybeSingle(),
      _sb.from('adult_reading_data').select('books,year_goal,updated_at').eq('user_id',sbUser.id).maybeSingle(),
      _sb.from('smart_notes').select('*').eq('user_id',sbUser.id).order('ts',{ascending:false}).limit(5),
      _sb.from('weekly_reviews').select('*').eq('user_id',sbUser.id).order('week_key',{ascending:false}).limit(1)
    ]);
    ctx.goals=(results[0].data||[]).map(function(g){return g.text;});
    ctx.habitsRaw=(results[1].data||[]);
    ctx.habits=ctx.habitsRaw.map(function(h){return h.name+' (streak:'+(h.streak||0)+', আজকে:'+(h.done?'✅':'⏳')+')';});
    ctx.namaz=(results[2].data||[]).map(function(n){return n.date+' '+n.prayer+':'+n.status;});
    ctx.todos=(results[3].data||[]).map(function(t){return t.title;});
    ctx.journal=(results[4].data||[]).map(function(j){return(j.created_at||'').substring(0,10)+': '+(j.content||'').substring(0,100);});
    ctx.finance=(results[5].data||[]).map(function(f){return f.type+' '+f.amount+' - '+(f.note||'');});
    ctx.fasting=(results[6].data||[]).map(function(f){return f.date+' ('+f.type+')';});
    ctx.completedTodos=(results[7].data||[]).map(function(t){return t.title;});
    // Sleep: last 7 days
    ctx.sleep=(results[8].data||[]).map(function(s){
      var hrs=s.dur?Math.round(s.dur/60*10)/10:0;
      return s.date_key+': '+hrs+'ঘণ্টা (মান:'+(s.q||'?')+'/5)';
    });
    // Deep Work: last 7 days sessions
    ctx.deepwork=(results[9].data||[]).map(function(d){
      var min=d.duration_mins||0;
      return d.date+': '+(d.task||'Session')+' — '+min+'মিনিট';
    });
    // Quran
    var qRow=results[10].data;
    if(qRow){
      var tilawatToday=0;
      try{
        var tDate=new Date().toISOString().slice(0,10);
        if(qRow.tilawat&&typeof qRow.tilawat==='object')tilawatToday=qRow.tilawat[tDate]||0;
      }catch(e){}
      ctx.quran={dailyGoal:qRow.daily_goal||2,todayPages:tilawatToday};
    }
    // Study
    var stRow=results[11].data;
    if(stRow){
      var recentStudy=(stRow.logs||[]).slice(-3).map(function(l){return l.date+': '+(l.subject||'Study')+' '+(l.duration||0)+'মিনিট';});
      ctx.study={totalXP:stRow.total_xp||0,weeklyGoalHrs:stRow.goal||4,recent:recentStudy};
    }
    // Reading
    var rdRow=results[12].data;
    if(rdRow){
      var booksInProgress=(rdRow.books||[]).filter(function(b){return b.status==='reading';}).map(function(b){return b.title;});
      var booksFinished=(rdRow.books||[]).filter(function(b){return b.status==='finished';}).length;
      ctx.reading={yearGoal:rdRow.year_goal||24,booksFinished:booksFinished,currentBooks:booksInProgress};
    }
    // Smart Notes
    ctx.notes=(results[13].data||[]).map(function(n){
      var txt=(n.title||n.body||n.content||'').substring(0,80);
      var date=(n.ts||n.created_at||n.updated_ts||'').substring(0,10);
      return date+': '+txt;
    });
    // Weekly Review
    var wrRow=(results[14].data||[])[0];
    if(wrRow){
      var wrWins='';
      try{
        var wArr=typeof wrRow.wins==='string'?JSON.parse(wrRow.wins):wrRow.wins;
        wrWins=Array.isArray(wArr)?wArr.join(', '):String(wArr||'');
      }catch(e){wrWins=wrRow.wins||'';}
      var wrChallenges='';
      try{
        var wRef=wrRow.reflection||{};
        wrChallenges=wRef.challenges||wRef.challenge||wrRow.challenges||'';
      }catch(e){}
      ctx.weeklyReview={
        weekKey:wrRow.week_key||wrRow.weekKey||'',
        wins:wrWins.substring(0,100),
        challenges:wrChallenges.substring(0,80),
        nextFocus:(wrRow.next_focus||wrRow.nextFocus||'').substring(0,80)
      };
    }
  }catch(e){}
  _hadiCtxCache=ctx;_hadiCtxCacheTime=Date.now();
  return ctx;
}

// Relationship stage — a truly fresh account shouldn't get the same data-driven
// "streak/todo check-in" greeting as someone with months of history. New users get a
// simple, low-pressure introduction first (rule-based, no AI call), then a light
// check-in referencing what they said, and only later the full personalized greet.
function _hadiRelationshipState(){
  try{return JSON.parse(localStorage.getItem(_hadiStorageKey('hadi_relationship'))||'null');}catch(e){return null;}
}
function _hadiSaveRelationshipState(state){
  try{localStorage.setItem(_hadiStorageKey('hadi_relationship'),JSON.stringify(state));}catch(e){}
}
function _hadiIsAccountEmpty(ctx){
  return !(ctx.habitsRaw&&ctx.habitsRaw.length)&&!(ctx.todos&&ctx.todos.length)&&!(ctx.goals&&ctx.goals.length)&&!(ctx.namaz&&ctx.namaz.length)&&!(ctx.streak);
}
var _hadiFocusLabels={namaz:'নামাজ',habit:'habit',todo:'কাজ গোছানো',goal:'বড় লক্ষ্য'};

function _hadiIntroFocusPick(focus){
  var state=_hadiRelationshipState()||{};
  state.focus=focus;
  _hadiSaveRelationshipState(state);
  _hadiAppendBubble('assistant','লেখা থাকলো! ধীরে ধীরে এটা নিয়ে একসাথে কাজ করবো, তাড়াহুড়ো নেই 🙂');
  _hadiMenuButtons([{label:'🏠 মেনু',onClick:_hadiShowMainMenu}]);
}

function _hadiShowFocusQuestion(){
  _hadiAppendBubble('assistant','আসসালামু আলাইকুম! আমি Hadi — তোমার সাথে থাকতে চাই।\nএকটা জিনিস জানতে চাই — তুমি এখন সবচেয়ে বেশি কী নিয়ে কাজ করতে চাও?');
  _hadiMenuButtons([
    {label:'🕌 নামাজ',onClick:function(){_hadiIntroFocusPick('namaz');}},
    {label:'✅ Habit',onClick:function(){_hadiIntroFocusPick('habit');}},
    {label:'📝 কাজ গোছানো',onClick:function(){_hadiIntroFocusPick('todo');}},
    {label:'🎯 বড় লক্ষ্য',onClick:function(){_hadiIntroFocusPick('goal');}}
  ]);
}

async function _hadiGreetStage1(){
  var state={firstContact:new Date().toISOString().slice(0,10),focus:null};
  _hadiSaveRelationshipState(state);
  _hadiShowFocusQuestion();
}

function _hadiGreetStage2(state){
  var focusLabel=_hadiFocusLabels[state.focus]||'তোমার লক্ষ্য';
  _hadiAppendBubble('assistant','তুমি বলেছিলে '+focusLabel+' নিয়ে কাজ করতে চাও — এখন পর্যন্ত কেমন যাচ্ছে?');
  _hadiMenuButtons([
    {label:'ভালোই যাচ্ছে',onClick:function(){_hadiAppendBubble('assistant','আলহামদুলিল্লাহ! চালিয়ে যাও 💪');_hadiMenuButtons([{label:'🏠 মেনু',onClick:_hadiShowMainMenu}]);}},
    {label:'একটু কঠিন লাগছে',onClick:function(){_hadiAppendBubble('assistant','কোনো সমস্যা না — ছোট একটা ধাপ দিয়ে শুরু করলে সহজ হবে। তাড়াহুড়ো নেই।');_hadiMenuButtons([{label:'🏠 মেনু',onClick:_hadiShowMainMenu}]);}},
    {label:'এখনো শুরু করিনি',onClick:function(){_hadiAppendBubble('assistant','ঠিক আছে, চাপ নেই। যখন মনে হবে তখনই শুরু করো — আমি এখানেই আছি।');_hadiMenuButtons([{label:'🏠 মেনু',onClick:_hadiShowMainMenu}]);}}
  ]);
}

async function _hadiGreetStage3(ctx,state){
  var focus=state.focus;
  var focusLabel=_hadiFocusLabels[focus]||'এটা';
  _hadiAppendBubble('assistant','একটা ছোট জিনিস try করবে? '+focusLabel+' নিয়ে একদম ছোট একটা শুরু — বেশি না, শুধু আজকেরটুকু। করবে?');
  _hadiMenuButtons([
    {label:'হ্যাঁ, করি',onClick:function(){
      if(focus==='namaz')_hadiNamazLogPick();
      else if(focus==='todo')_hadiTodoAddStart();
      else if(focus==='goal')_hadiGoalAddStart();
      else _hadiHabitAddStart();
    }},
    {label:'পরে করবো',onClick:function(){_hadiAppendBubble('assistant','ঠিক আছে, যখন মন চায় তখনই বলো।');_hadiMenuButtons([{label:'🏠 মেনু',onClick:_hadiShowMainMenu}]);}}
  ]);
}

async function _hadiGreet(){
  var ctx=await _hadiGetContext();
  if(!ctx.habitsRaw)ctx.habitsRaw=[];
  var relState=_hadiRelationshipState();
  if(!relState){await _hadiGreetStage1();return;} // Day 1 — never seen before, no data check-in
  if(_hadiIsAccountEmpty(ctx)){
    if(!relState.focus){_hadiShowFocusQuestion();return;} // asked before but never answered (e.g. hit Menu instead) — ask again, don't fall back to a data dump that has nothing to show
    var daysSince=Math.floor((new Date(new Date().toISOString().slice(0,10))-new Date(relState.firstContact))/86400000);
    if(daysSince<=2){_hadiGreetStage2(relState);return;} // Day 1-2 — light check-in, no raw data dump
    if(daysSince<=6){await _hadiGreetStage3(ctx,relState);return;} // Day 3-6 — one tiny suggestion, nothing more
    // Day 7+ with still-empty account — fall through to the normal data-driven greet,
    // which will correctly reflect "nothing logged yet" rather than staying in onboarding forever.
  }
  var systemPrompt=_hadiSystemPrompt(ctx);
  var hour=new Date().getHours();
  var timeCtx,greetTone;
  if(hour>=5&&hour<12){timeCtx='সকাল';greetTone='সকালের greeting দাও। দিন শুরুর motivation। Fajr হয়েছে কিনা জিজ্ঞেস করতে পারো।';}
  else if(hour>=12&&hour<17){timeCtx='দুপুর';greetTone='দুপুরের greeting দাও। কাজকর্মের মাঝে একটু check-in।';}
  else if(hour>=17&&hour<21){timeCtx='সন্ধ্যা';greetTone='সন্ধ্যার greeting দাও। আজকের দিন কেমন গেল সেটা জিজ্ঞেস করো।';}
  else{timeCtx='রাত';greetTone='রাতের greeting দাও — একদম ছোট, calm। Fajr বা নামাজের কথা এখন জিজ্ঞেস করবে না। শুধু "রাত জাগছ?" বা "কেমন আছো?" টাইপের কিছু।';}
  var patterns=_hadiDetectPatterns(ctx);
  var patternNote=patterns.length?'⚠️ Pattern দেখা গেছে: '+patterns.join('; '):'';
  var greetPrompt=[
    'এখন '+timeCtx+'।',
    greetTone,
    patternNote||'',
    '',
    'এই user এর data দেখে একটা personalized opening message লেখো:',
    '- Streak: '+(ctx.streak||0)+' দিন',
    '- আজ habits: '+(ctx.habits.length?ctx.habits.join(', '):'কোনোটা নেই'),
    '- Todos: '+(ctx.todos.length?ctx.todos.length+'টি pending':'সব শেষ'),
    '- Goals: '+(ctx.goals.length?ctx.goals[0]:'কোনো goal নেই'),
    '',
    'নিয়ম:',
    '- ২-৩টা natural বাক্য। একেবারে বন্ধুর মতো — robot বা assistant এর মতো না।',
    '- Data থেকে একটা specific জিনিস mention করো (streak বা habit বা goal)।',
    '- শেষে একটা ছোট question রাখো যেটা user কে কথা বলতে উৎসাহিত করে।',
    '- Formal "আপনি" না, "তুমি" form। Banglish না, বাংলা হরফ।',
  ].filter(Boolean).join('\n');
  _hadiShowTyping();
  try{
    var greetMsgs=[
      {role:'system',content:systemPrompt},
      {role:'user',content:greetPrompt}
    ];
    var res=await _hadiCallGroq(greetMsgs,250);
    _hadiHideTyping();
    if(!res){_hadiAppendBubble('assistant','একটু পরে আবার চেষ্টা করো 😊');return;}
    var data=await res.json();
    var raw=(data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||'{"message":"হাই! কেমন আছো?","actions":[]}';
    var parsed=null;
    try{var clean=raw.replace(/^```json\s*/,'').replace(/```\s*$/,'').trim();parsed=JSON.parse(clean);}catch(e){parsed={message:raw,actions:[]};}
    // Fix: actions must be array, message must be non-empty string
    if(parsed&&!Array.isArray(parsed.actions)){parsed.actions=parsed.actions?[parsed.actions]:[];}
    var msgText=(parsed&&typeof parsed.message==='string'&&parsed.message.trim())?parsed.message.trim():'একটু সমস্যা হলো, আবার বলো।';
    msgText=msgText
      .replace(/আপনার/g,'তোমার').replace(/আপনাকে/g,'তোমাকে').replace(/আপনি/g,'তুমি').replace(/আপনাদের/g,'তোমাদের')
      .replace(/করবি\b/g,'করবে').replace(/যাবি\b/g,'যাবে').replace(/বলবি\b/g,'বলবে').replace(/দেখবি\b/g,'দেখবে')
      .replace(/খাবি\b/g,'খাবে').replace(/পারবি\b/g,'পারবে').replace(/নেবি\b/g,'নেবে').replace(/দিবি\b/g,'দিবে')
      .replace(/করিস\b/g,'করো').replace(/যাস\b/g,'যাও').replace(/বলিস\b/g,'বলো').replace(/দেখিস\b/g,'দেখো')
      .replace(/আছিস\b/g,'আছো').replace(/ঘুমাবি\b/g,'ঘুমাবে').replace(/উঠবি\b/g,'উঠবে').replace(/পড়বি\b/g,'পড়বে')
      .replace(/থাকবি\b/g,'থাকবে').replace(/চলবি\b/g,'চলবে').replace(/হবি\b/g,'হবে').replace(/জানবি\b/g,'জানবে');
    _hadiHistory.push({role:'assistant',content:msgText});
    _hadiSaveHistory();
    var qr=(parsed&&Array.isArray(parsed.quick_replies)&&parsed.quick_replies.length)?parsed.quick_replies:null;
    _hadiAppendBubble('assistant',msgText,false,qr);
    var greetActs=parsed.actions||(parsed.action?[parsed.action]:[]);
    if(greetActs.length){await _hadiExecuteActions(greetActs);}
    _hadiMenuButtons([{label:'🏠 মেনু',onClick:_hadiShowMainMenu}]);
  }catch(e){_hadiHideTyping();}
}

async function _hadiProactiveCheck(){
  var hour=new Date().getHours();
  var today=new Date().toISOString().slice(0,10);
  var stored=JSON.parse(localStorage.getItem(_hadiStorageKey('hadi_proactive'))||'{}');

  // Determine which slot we're in
  var slot=null;
  var promptExtra='';
  if(hour>=5&&hour<10){slot='morning';promptExtra='সকালের শুরুতে একটা motivating message দাও। আজকের top habit বা goal এর কথা mention করো। ফজরের কথা জিজ্ঞেস করো যদি এখনো log না হয়।';}
  else if(hour>=13&&hour<16){slot='afternoon';promptExtra='দুপুরের energy dip এ একটা ছোট nudge দাও। Deep work বা একটা habit এর কথা বলো।';}
  else if(hour>=18&&hour<21){slot='evening';promptExtra='সন্ধ্যায় আজকের progress দেখো। কতটা habit হয়েছে সেটা বলো। বাকিটা করতে encourage করো।';}
  else if(hour>=21&&hour<23){slot='night';promptExtra='রাতে দিনের reflection করো। আজ কী ভালো হয়েছে সেটা ছোট করে বলো। ঘুমের আগে কিছু suggest করো।';}

  if(!slot)return; // না morning, না afternoon, না evening, না night
  if(stored[today]&&stored[today][slot])return; // আজ এই slot এ already গেছে

  // Mark as sent
  if(!stored[today])stored[today]={};
  stored[today][slot]=true;
  // Clean old dates (keep only last 7 days)
  var keys=Object.keys(stored);
  if(keys.length>30){keys.sort();delete stored[keys[0]];}
  localStorage.setItem(_hadiStorageKey('hadi_proactive'),JSON.stringify(stored));

  var ctx=await _hadiGetContext();
  if(!ctx.habitsRaw)ctx.habitsRaw=[];
  var patterns=_hadiDetectPatterns(ctx);
  var patternNote=patterns.length?'⚠️ Pattern: '+patterns.join('; '):'';
  var systemPrompt=_hadiSystemPrompt(ctx);
  var proactivePrompt=promptExtra+(patternNote?' '+patternNote:'')+'\n\n১-২ বাক্যে বলো। Bangla Unicode। তুমি form।';

  _hadiShowTyping();
  try{
    var msgs=[
      {role:'system',content:systemPrompt},
      {role:'user',content:proactivePrompt}
    ];
    var res=await _hadiCallGroq(msgs,250);
    _hadiHideTyping();
    if(!res)return;
    var data=await res.json();
    var raw=(data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||'';
    if(!raw)return;
    var parsed=null;
    try{var clean=raw.replace(/^```json\s*/,'').replace(/```\s*$/,'').trim();parsed=JSON.parse(clean);}catch(e){parsed={message:raw,actions:[]};}
    if(parsed&&!Array.isArray(parsed.actions)){parsed.actions=[];}
    var msgText=(parsed&&typeof parsed.message==='string'&&parsed.message.trim())?parsed.message.trim():raw.trim();
    if(!msgText)return;
    msgText=msgText
      .replace(/আপনার/g,'তোমার').replace(/আপনাকে/g,'তোমাকে').replace(/আপনি/g,'তুমি')
      .replace(/করবি\b/g,'করবে').replace(/যাবি\b/g,'যাবে').replace(/পড়বি\b/g,'পড়বে')
      .replace(/করিস\b/g,'করো').replace(/থাকবি\b/g,'থাকবে').replace(/ঘুমাবি\b/g,'ঘুমাবে');
    _hadiHistory.push({role:'assistant',content:msgText});
    _hadiSaveHistory();
    var qr=(parsed&&Array.isArray(parsed.quick_replies)&&parsed.quick_replies.length)?parsed.quick_replies:null;
    _hadiAppendBubble('assistant',msgText,false,qr);
    if(parsed&&parsed.actions&&parsed.actions.length){await _hadiExecuteActions(parsed.actions);}
  }catch(e){_hadiHideTyping();}
}

