function _hadiSaveHistory(){
  try{localStorage.setItem(_hadiStorageKey('hadi_history'),JSON.stringify(_hadiHistory.slice(-50)));}catch(e){}
}

function _hadiShowActionToast(msg){
  var t=document.createElement('div');
  t.style.cssText='position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#22c55e;color:#fff;padding:8px 18px;border-radius:20px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 16px rgba(34,197,94,.35);animation:hadiToastIn .3s ease';
  t.textContent=msg;
  document.body.appendChild(t);
  setTimeout(function(){t.style.opacity='0';t.style.transition='opacity .3s';setTimeout(function(){t.remove();},300);},2500);
}

async function _hadiRunOneAction(action){
  var today=new Date().toISOString().slice(0,10);
  if(action.type==='show_card'){
    var ctx=await _hadiGetContext();
    if(!ctx.habitsRaw)ctx.habitsRaw=[];
    _hadiShowCard(action.card_type||'habits',ctx);
    return null;
  } else if(action.type==='log_namaz'){
    var prayer=action.prayer||'Fajr';
    var date=action.date||today;
    await _sb.from('adult_namaz_logs').upsert({user_id:sbUser.id,prayer:prayer,status:action.status||'completed',date:date},{onConflict:'user_id,prayer,date'});
    return '✅ '+prayer+' log হয়েছে!';
  } else if(action.type==='log_habit'){
    var hres=await _sb.from('adult_habits').select('id,streak,last_done_date').eq('user_id',sbUser.id).ilike('name','%'+(action.habit_name||'')+'%').limit(1);
    if(hres.data&&hres.data.length){
      var h=hres.data[0];
      var newStreak=(h.last_done_date===today)?h.streak:(h.streak||0)+1;
      await _sb.from('adult_habits').update({done:true,last_done_date:today,streak:newStreak}).eq('id',h.id);
      return '✅ Habit log হয়েছে!';
    }
    return null;
  } else if(action.type==='add_habit'){
    if(!action.name||!action.name.trim())return null;
    var hName=action.name.trim();
    var hDupe=await _sb.from('adult_habits').select('id').eq('user_id',sbUser.id).ilike('name',hName).limit(1);
    if(hDupe.data&&hDupe.data.length)return '⚠️ "'+hName+'" habit আগে থেকেই আছে।';
    var hid=([1e7]+-1e3+-4e3+-8e3+-1e11).replace(/[018]/g,function(c){return(c^crypto.getRandomValues(new Uint8Array(1))[0]&15>>c/4).toString(16);});
    await _sb.from('adult_habits').insert({id:hid,user_id:sbUser.id,name:hName,icon_key:action.icon_key||'exercise',cat:action.cat||'health',description:'',points:10,streak:0,done:false,last_done_date:'',history:[]});
    return '✅ "'+hName+'" habit যোগ হয়েছে!';
  } else if(action.type==='add_goal'){
    if(!action.text||!action.text.trim())return null;
    await _sb.from('adult_goals').insert({user_id:sbUser.id,text:action.text.trim(),priority:action.priority||'medium',deadline:action.deadline||'',progress:0,done:false,tier:action.tier||'life',area:action.area||'personal',created_at:new Date().toISOString()});
    return '✅ "'+action.text.trim()+'" goal যোগ হয়েছে!';
  } else if(action.type==='update_goal_progress'){
    if(!action.goal_text)return null;
    var gpRes=await _sb.from('adult_goals').select('id,text,progress').eq('user_id',sbUser.id).ilike('text','%'+action.goal_text.substring(0,30)+'%').limit(1);
    if(gpRes.data&&gpRes.data.length){
      var newProgress=Math.max(0,Math.min(100,action.progress||0));
      var goalDone=newProgress>=100;
      await _sb.from('adult_goals').update({progress:newProgress,done:goalDone}).eq('id',gpRes.data[0].id);
      return goalDone?('🎉 "'+gpRes.data[0].text+'" গোল সম্পূর্ণ হয়েছে!'):('✅ "'+gpRes.data[0].text+'" progress '+newProgress+'% আপডেট হয়েছে!');
    }
    return '⚠️ Goal খুঁজে পাওয়া যায়নি।';
  } else if(action.type==='complete_goal'){
    if(!action.goal_text)return null;
    var cgRes=await _sb.from('adult_goals').select('id,text').eq('user_id',sbUser.id).ilike('text','%'+action.goal_text.substring(0,30)+'%').limit(1);
    if(cgRes.data&&cgRes.data.length){
      await _sb.from('adult_goals').update({progress:100,done:true}).eq('id',cgRes.data[0].id);
      return '🎉 "'+cgRes.data[0].text+'" গোল সম্পূর্ণ হয়েছে! মাশাআল্লাহ!';
    }
    return '⚠️ Goal খুঁজে পাওয়া যায়নি।';
  } else if(action.type==='delete_goal'){
    if(!action.goal_text)return null;
    var dgRes=await _sb.from('adult_goals').select('id,text').eq('user_id',sbUser.id).ilike('text','%'+action.goal_text.substring(0,30)+'%').limit(1);
    if(dgRes.data&&dgRes.data.length){
      var delGoalText=dgRes.data[0].text;
      await _sb.from('adult_goals').delete().eq('id',dgRes.data[0].id);
      return '✅ "'+delGoalText+'" goal delete হয়েছে!';
    }
    return '⚠️ Goal খুঁজে পাওয়া যায়নি।';
  } else if(action.type==='update_habit'){
    var ures=await _sb.from('adult_habits').select('id').eq('user_id',sbUser.id).ilike('name','%'+(action.old_name||'')+'%').limit(1);
    if(ures.data&&ures.data.length){
      await _sb.from('adult_habits').update({name:action.new_name}).eq('id',ures.data[0].id);
      return '✅ Habit rename হয়েছে: "'+action.new_name+'"';
    }
    return '⚠️ Habit খুঁজে পাওয়া যায়নি।';
  } else if(action.type==='delete_habit'){
    var dres=await _sb.from('adult_habits').select('id,name').eq('user_id',sbUser.id).ilike('name','%'+(action.habit_name||'')+'%').limit(1);
    if(dres.data&&dres.data.length){
      var deletedName=dres.data[0].name;
      await _sb.from('adult_habits').delete().eq('id',dres.data[0].id);
      return '✅ "'+deletedName+'" habit delete হয়েছে!';
    }
    return '⚠️ Habit খুঁজে পাওয়া যায়নি।';
  } else if(action.type==='add_todo'){
    if(!action.title||action.title.trim().length<2)return null;
    await _sb.from('todo_tasks').insert({user_id:sbUser.id,title:action.title.trim(),status:'pending',created_at:new Date().toISOString()});
    return '✅ "'+action.title.trim()+'" todo যোগ হয়েছে!';
  } else if(action.type==='log_fasting'){
    await _sb.from('fasting_logs').insert({user_id:sbUser.id,date:action.date||today,type:action.fast_type||'voluntary'});
    return '✅ Fasting log হয়েছে!';
  } else if(action.type==='log_finance'){
    await _sb.from('finance_transactions').insert({user_id:sbUser.id,amount:action.amount||0,type:action.transaction_type||'expense',note:action.note||'',date:today,category:action.category||'other'});
    return '✅ Finance log হয়েছে!';
  } else if(action.type==='complete_todo'){
    if(!action.title)return null;
    var ctRes=await _sb.from('todo_tasks').select('id,title').eq('user_id',sbUser.id).eq('status','pending').ilike('title','%'+action.title.substring(0,30)+'%').limit(1);
    if(ctRes.data&&ctRes.data.length){
      await _sb.from('todo_tasks').update({status:'done',updated_at:new Date().toISOString()}).eq('id',ctRes.data[0].id);
      return '✅ "'+ctRes.data[0].title+'" complete হয়েছে!';
    }
    return '⚠️ Todo খুঁজে পাওয়া যায়নি।';
  } else if(action.type==='delete_todo'){
    if(!action.title)return null;
    var dtRes=await _sb.from('todo_tasks').select('id,title').eq('user_id',sbUser.id).ilike('title','%'+action.title.substring(0,30)+'%').limit(1);
    if(dtRes.data&&dtRes.data.length){
      var deletedTitle=dtRes.data[0].title;
      await _sb.from('todo_tasks').delete().eq('id',dtRes.data[0].id);
      return '✅ "'+deletedTitle+'" todo delete হয়েছে!';
    }
    return '⚠️ Todo খুঁজে পাওয়া যায়নি।';
  } else if(action.type==='add_journal'){
    if(!action.content||action.content.trim().length<2)return null;
    await _sb.from('journal_entries').insert({user_id:sbUser.id,content:action.content.trim(),created_at:new Date().toISOString()});
    return '✅ Journal entry লেখা হয়েছে!';
  } else if(action.type==='add_note'){
    if(!action.content||action.content.trim().length<2)return null;
    await _sb.from('smart_notes').insert({user_id:sbUser.id,content:action.content.trim(),ts:new Date().toISOString()});
    return '✅ Note সেভ হয়েছে!';
  } else if(action.type==='log_quran'){
    var qPages=action.pages||1;
    var qDate=action.date||today;
    var qRow=await _sb.from('adult_quran_data').select('tilawat,daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var qData=(qRow&&qRow.data)||{};
    var qTilawat=qData.tilawat||{};
    qTilawat[qDate]=(qTilawat[qDate]||0)+qPages;
    await _sb.from('adult_quran_data').upsert({user_id:sbUser.id,tilawat:qTilawat,daily_goal:qData.daily_goal||2,updated_at:new Date().toISOString()},{onConflict:'user_id'});
    return '✅ Quran '+qPages+' পৃষ্ঠা log হয়েছে! আজ মোট: '+qTilawat[qDate]+' পৃষ্ঠা';
  } else if(action.type==='log_sleep'){
    var slSt=action.sleep_time||'23:00';
    var slWt=action.wake_time||'06:00';
    var slQ=action.quality||3;
    // Calculate duration in minutes from sleep_time → wake_time
    function _toMin(t){var p=t.split(':');return parseInt(p[0])*60+parseInt(p[1]||0);}
    var slStMin=_toMin(slSt);var slWtMin=_toMin(slWt);
    var slDur=slWtMin>slStMin?(slWtMin-slStMin):(1440-slStMin+slWtMin);
    var slYest=new Date();slYest.setDate(slYest.getDate()-1);
    var slDate=slYest.toISOString().slice(0,10);
    await _sb.from('adult_sleep_logs').upsert({user_id:sbUser.id,date_key:slDate,st:slSt,wt:slWt,dur:slDur,q:slQ,tags:[]},{onConflict:'user_id,date_key'});
    return '✅ ঘুম log হয়েছে! '+(Math.round(slDur/60*10)/10)+'ঘণ্টা ('+slDate+')';
  } else if(action.type==='log_deepwork'){
    var dwTask=action.task||'Focus Session';
    var dwDur=action.duration||25;
    await _sb.from('deepwork_sessions').insert({id:crypto.randomUUID(),user_id:sbUser.id,task:dwTask,duration_mins:dwDur,date:today});
    return '✅ Deep work session log হয়েছে! '+dwTask+' — '+dwDur+' মিনিট';
  }
  return null;
}

async function _hadiExecuteActions(actions){
  if(!actions||!actions.length||!window.sbUser||typeof _sb==='undefined')return;
  _hadiCtxCacheTime=0; // force refresh context after action
  var toasts=[];
  for(var i=0;i<actions.length;i++){
    try{
      var msg=await _hadiRunOneAction(actions[i]);
      if(msg)toasts.push(msg);
    }catch(e){console.warn('Hadi action error:',actions[i].type,e);}
  }
  if(toasts.length===1){
    _hadiShowActionToast(toasts[0]);
  } else if(toasts.length>1){
    _hadiShowActionToast('✅ '+toasts.length+'টা কাজ হয়েছে!');
  }
}

var _hadiVoiceRec=null,_hadiVoiceTimer=null,_hadiVoiceSecs=0,_hadiIsTyping=false;

var _MIC_SVG='<rect x="9" y="2" width="6" height="12" rx="3" fill="#fff"/><path d="M5 10a7 7 0 0 0 14 0" stroke="#fff" stroke-width="2" stroke-linecap="round"/><line x1="12" y1="17" x2="12" y2="21" stroke="#fff" stroke-width="2" stroke-linecap="round"/><line x1="8" y1="21" x2="16" y2="21" stroke="#fff" stroke-width="2" stroke-linecap="round"/>';
var _SEND_SVG='<path d="M22 2L11 13M22 2L15 22L11 13M11 13L2 9L22 2" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>';
var _STOP_SVG='<rect x="6" y="6" width="12" height="12" rx="2" fill="#fff"/>';

window.kzHadiInputChange=function(){
  var inp=document.getElementById('kz-hadi-input');
  var hasText=inp&&inp.textContent.trim().length>0;
  _hadiIsTyping=hasText;
  _hadiUpdateActionBtn();
};

function _hadiUpdateActionBtn(){
  var btn=document.getElementById('hadi-action-btn');
  var icon=document.getElementById('hadi-action-icon');
  if(!btn||!icon)return;
  var isRecording=_hadiVoiceRec&&_hadiVoiceRec.state==='recording';
  if(isRecording){
    icon.innerHTML=_STOP_SVG;
    btn.style.background='linear-gradient(135deg,#ef4444,#f87171)';
    btn.style.boxShadow='0 2px 8px rgba(239,68,68,.4)';
  } else if(_hadiIsTyping){
    icon.innerHTML=_SEND_SVG;
    btn.style.background='linear-gradient(135deg,#FF8A00,#FFB800)';
    btn.style.boxShadow='0 2px 8px rgba(255,138,0,.3)';
  } else {
    icon.innerHTML=_MIC_SVG;
    btn.style.background='linear-gradient(135deg,#FF8A00,#FFB800)';
    btn.style.boxShadow='0 2px 8px rgba(255,138,0,.3)';
  }
}

window.kzHadiActionBtn=function(){
  var isRecording=_hadiVoiceRec&&_hadiVoiceRec.state==='recording';
  if(isRecording){
    // Send button clicked while recording — stop and send
    _hadiVoiceStop(true);
    return;
  }
  if(_hadiIsTyping){window.kzHadiSend();return;}
  // Start voice
  var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){alert('তোমার browser এ voice input supported না। Chrome use করো।');return;}
  var rec=new SR();
  rec.lang='bn-BD';
  rec.interimResults=true;
  rec.continuous=true;   // keep recording even during pauses
  rec.maxAlternatives=1;
  _hadiVoiceRec=rec;
  var voiceBar=document.getElementById('hadi-voice-bar');
  var timerEl=document.getElementById('hadi-rec-timer');
  if(voiceBar)voiceBar.style.display='flex';
  _hadiVoiceSecs=0;
  _hadiUpdateActionBtn();
  _hadiVoiceTimer=setInterval(function(){
    _hadiVoiceSecs++;
    var m=Math.floor(_hadiVoiceSecs/60),s=_hadiVoiceSecs%60;
    if(timerEl)timerEl.textContent=m+':'+(s<10?'0':'')+s;
  },1000);
  rec.onresult=function(e){
    var transcript='';
    for(var i=0;i<e.results.length;i++){transcript+=e.results[i][0].transcript;}
    var inp=document.getElementById('kz-hadi-input');
    if(inp){inp.textContent=transcript;_hadiIsTyping=transcript.trim().length>0;}
    _hadiUpdateActionBtn();
  };
  rec.onerror=function(e){
    if(e.error==='not-allowed'){_hadiVoiceStop(false);alert('Microphone permission দাও।');}
    // ignore 'no-speech' errors so recording continues
  };
  rec.onend=function(){
    // If still supposed to be recording (not manually stopped), restart
    if(_hadiVoiceRec===rec&&!_hadiVoiceStopping){
      try{rec.start();}catch(e){}
    }
  };
  rec.start();
  // Click anywhere on the panel = stop (but not the action button itself)
  setTimeout(function(){
    document.addEventListener('click',_hadiVoiceTapStop,{capture:true,once:false});
  },300);
};

var _hadiVoiceStopping=false;
function _hadiVoiceTapStop(e){
  // Let action button handle itself
  var btn=document.getElementById('hadi-action-btn');
  if(btn&&btn.contains(e.target))return;
  document.removeEventListener('click',_hadiVoiceTapStop,true);
  _hadiVoiceStop(false);
}

function _hadiVoiceStop(andSend){
  _hadiVoiceStopping=true;
  document.removeEventListener('click',_hadiVoiceTapStop,true);
  if(_hadiVoiceTimer){clearInterval(_hadiVoiceTimer);_hadiVoiceTimer=null;}
  if(_hadiVoiceRec){
    _hadiVoiceRec.onresult=null;_hadiVoiceRec.onend=null;_hadiVoiceRec.onerror=null;
    try{_hadiVoiceRec.stop();}catch(e){}
    _hadiVoiceRec=null;
  }
  var voiceBar=document.getElementById('hadi-voice-bar');
  var timerEl=document.getElementById('hadi-rec-timer');
  if(voiceBar)voiceBar.style.display='none';
  if(timerEl)timerEl.textContent='0:00';
  var inp=document.getElementById('kz-hadi-input');
  _hadiIsTyping=inp&&inp.textContent.trim().length>0;
  _hadiUpdateActionBtn();
  _hadiVoiceStopping=false;
  if(andSend){
    window.kzHadiSend();
  } else if(inp&&inp.textContent.trim()){
    inp.focus();
    var range=document.createRange();range.selectNodeContents(inp);range.collapse(false);
    var sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);
  }
}

var _hadiLastSend=0;
window.kzHadiSend=async function(){
  var inputEl=document.getElementById('kz-hadi-input');
  if(!inputEl)return;
  var text=inputEl.textContent.trim();
  if(!text)return;
  var now=Date.now();
  if(now-_hadiLastSend<4000){
    var rem=Math.ceil((4000-(now-_hadiLastSend))/1000);
    _hadiShowActionToast('⏳ '+rem+' সেকেন্ড পরে পাঠাও');
    inputEl.textContent=''; // don't leave a "stuck" ghost message in the box — button clicks auto-send and shouldn't look broken
    return;
  }
  _hadiLastSend=now;
  // Reset voice state on send
  _hadiIsTyping=false;
  var _vb=document.getElementById('hadi-voice-bar');
  var _vt=document.getElementById('hadi-rec-timer');
  if(_vb)_vb.style.display='none';
  if(_vt)_vt.textContent='0:00';
  _hadiUpdateActionBtn();
  inputEl.textContent='';
  _hadiHistory.push({role:'user',content:text});
  _hadiSaveHistory();
  _hadiAppendBubble('user',text);
  // Menu-tree raw value capture — the intent was already decided by the button that led here,
  // so this text is used as-is (no regex/AI parsing at all).
  if(_hadiMenuState&&_hadiMenuState.step==='habit_add_name'){
    _hadiMenuState=null;
    _hadiHabitAddCategoryPick(text.trim());
    return;
  }
  if(_hadiMenuState&&_hadiMenuState.step==='todo_add_name'){
    _hadiMenuState=null;
    await _hadiTodoAddDo(text.trim());
    return;
  }
  if(_hadiMenuState&&_hadiMenuState.step==='goal_add_name'){
    _hadiMenuState=null;
    _hadiGoalAddPriorityPick(text.trim());
    return;
  }
  // Explicit menu trigger — always available, resets any in-progress flow
  if(/^(মেনু|menu)$/i.test(text.trim())){
    _hadiShowMainMenu();return;
  }
  // Rule-based add flow — no AI needed
  if(_hadiPendingAdd){
    var pType=_hadiPendingAdd.type;
    _hadiPendingAdd=null;
    var pItems=_hadiExtractItems(text);
    if(!pItems.length){_hadiShowTyping();pItems=await _hadiAIExtractAdd(pType,text);_hadiHideTyping();}
    if(pItems.length){await _hadiRuleAddItems(pType,pItems);return;}
    _hadiAppendBubble('assistant','নাম গুলো বুঝতে পারিনি, আবার কমা দিয়ে আলাদা করে লেখো।');return;
  }
  var addHabitRe=/(habit|অভ্যাস|হ্যাবিট)/i,addTodoRe=/(to\s*-?\s*do|কাজ|টু[\s-]?ডু)/i,addGoalRe=/(goal|গোল|লক্ষ্য)/i,addVerbRe=/(add|যোগ|যুক্ত)/i;
  if(addVerbRe.test(text)&&(addHabitRe.test(text)||addTodoRe.test(text)||addGoalRe.test(text))){
    var addType=addHabitRe.test(text)?'habit':addTodoRe.test(text)?'todo':'goal';
    _hadiLastTopic=addType==='habit'?'habits':addType==='todo'?'todos':'goals';
    var addItems=_hadiExtractItems(text);
    if(!addItems.length){_hadiShowTyping();addItems=await _hadiAIExtractAdd(addType,text);_hadiHideTyping();}
    if(addItems.length){await _hadiRuleAddItems(addType,addItems);return;}
    _hadiPendingAdd={type:addType};
    var addLabel=addType==='habit'?'habit':addType==='todo'?'কাজ':'goal';
    _hadiAppendBubble('assistant','অবশ্যই! কোন '+addLabel+'(গুলো) add করব? নাম লিখে দাও (একাধিক হলে কমা দিয়ে আলাদা করো) 👇');return;
  }
  // Quick card shortcuts — no AI needed, but always fetch fresh data (never trust stale cache)
  var tl=text.toLowerCase();
  var topicRe=/(habit|অভ্যাস|হ্যাবিট|todo|to\s*-?\s*do|কাজ|টু[\s-]?ডু|streak|স্ট্রিক|namaz|নামাজ|goal|গোল|লক্ষ্য)/i;
  var checkVerbRe=/(দেখ|show|visual|card|চেক|check)/i;
  var bareCheckFillerRe=/দেখ|চেক|check|show|এখন|কয়টা|কতটা|কতগুলো|আছে|টা|টি|কি|মোট|সব|\?/gi;
  var hasTopic=topicRe.test(tl);
  var bareCheckRemainder=tl.replace(bareCheckFillerRe,'').trim();
  var needsCard=(hasTopic&&checkVerbRe.test(tl))||(!hasTopic&&checkVerbRe.test(tl)&&_hadiLastTopic&&bareCheckRemainder.length<4);
  if(needsCard){
    if(hasTopic){
      var mHabit=/(habit|অভ্যাস|হ্যাবিট)/i.test(tl),mTodo=/(to\s*-?\s*do|কাজ|টু[\s-]?ডু)/i.test(tl),mStreak=/(streak|স্ট্রিক)/i.test(tl),mNamaz=/(namaz|নামাজ)/i.test(tl),mGoal=/(goal|গোল|লক্ষ্য)/i.test(tl);
      _hadiLastTopic=mHabit?'habits':mTodo?'todos':mStreak?'streak':mNamaz?'namaz':mGoal?'goals':_hadiLastTopic;
    }
    var ctx0=await _hadiGetContext(true);
    if(!hasTopic&&_hadiLastTopic){
      var lblMap={habits:['এই নাও তোমার আজকের habits 👇','habits'],todos:['তোমার pending কাজগুলো 👇','todos'],streak:['তোমার streak 🔥','streak'],namaz:['আজকের নামাজ 🕌','namaz'],goals:['তোমার goals 🎯','goals']};
      var lbl=lblMap[_hadiLastTopic];
      _hadiAppendBubble('assistant',lbl[0]);_hadiShowCard(lbl[1],ctx0);return;
    }
    if(/(habit|অভ্যাস|হ্যাবিট)/i.test(tl)){
      _hadiAppendBubble('assistant','এই নাও তোমার আজকের habits 👇');_hadiShowCard('habits',ctx0);return;
    }
    if(/(to\s*-?\s*do|কাজ|টু[\s-]?ডু)/i.test(tl)){
      _hadiAppendBubble('assistant','তোমার pending কাজগুলো 👇');_hadiShowCard('todos',ctx0);return;
    }
    if(/(streak|স্ট্রিক)/i.test(tl)){
      _hadiAppendBubble('assistant','তোমার streak 🔥');_hadiShowCard('streak',ctx0);return;
    }
    if(/(namaz|নামাজ)/i.test(tl)){
      _hadiAppendBubble('assistant','আজকের নামাজ 🕌');_hadiShowCard('namaz',ctx0);return;
    }
    if(/(goal|গোল|লক্ষ্য)/i.test(tl)){
      _hadiAppendBubble('assistant','তোমার goals 🎯');_hadiShowCard('goals',ctx0);return;
    }
  }
  _hadiShowTyping();
  try{
    var ctx=await _hadiGetContext();
    var systemPrompt=_hadiSystemPrompt(ctx);
    var messages=[{role:'system',content:systemPrompt}];
    _hadiHistory.slice(-6).forEach(function(m){messages.push({role:m.role,content:m.content});});
    var res=await _hadiCallGroq(messages,300);
    _hadiHideTyping();
    if(!res){_hadiAppendBubble('assistant','😅 সব model এ একটু load আছে, ১ মিনিট পরে try করো।');return;}
    var data=await res.json();
    var raw=(data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||'{"message":"একটু সমস্যা হলো।","actions":[]}';
    var parsed=null;
    try{var clean=raw.replace(/^```json\s*/,'').replace(/```\s*$/,'').trim();parsed=JSON.parse(clean);}catch(e){parsed={message:raw,actions:[]};}
    // Fix: actions must be array, message must be non-empty string
    if(parsed&&!Array.isArray(parsed.actions)){parsed.actions=parsed.actions?[parsed.actions]:[];}
    var msgText=(parsed&&typeof parsed.message==='string'&&parsed.message.trim())?parsed.message.trim():'একটু সমস্যা হলো, আবার বলো।';
    msgText=msgText
      .replace(/আপনার/g,'তোমার').replace(/আপনাকে/g,'তোমাকে').replace(/আপনি/g,'তুমি').replace(/আপনাদের/g,'তোমাদের')
      .replace(/করবি\b/g,'করবে').replace(/যাবি\b/g,'যাবে').replace(/বলবি\b/g,'বলবে').replace(/দেখবি\b/g,'দেখবে')
      .replace(/খাবি\b/g,'খাবে').replace(/পারবি\b/g,'পারবে').replace(/নেবি\b/g,'নেবে').replace(/দিবি\b/g,'দিবে')
      .replace(/করিস\b/g,'করো').replace(/যাস\b/g,'যাও').replace(/বলিস\b/g,'বলো').replace(/দেখিস\b/g,'দেখো')
      .replace(/আছিস\b/g,'আছো').replace(/ঘুমাবি\b/g,'ঘুমাবে').replace(/উঠবি\b/g,'উঠবে').replace(/পড়বি\b/g,'পড়বে')
      .replace(/থাকবি\b/g,'থাকবে').replace(/চলবি\b/g,'চলবে').replace(/হবি\b/g,'হবে').replace(/জানবি\b/g,'জানবে');
    _hadiHistory.push({role:'assistant',content:msgText});
    _hadiSaveHistory();
    var qr=(parsed&&Array.isArray(parsed.quick_replies)&&parsed.quick_replies.length)?parsed.quick_replies:null;
    _hadiAppendBubble('assistant',msgText,false,qr);
    var acts=parsed.actions||(parsed.action?[parsed.action]:[]);
    if(acts.length){await _hadiExecuteActions(acts);}
  }catch(e){_hadiHideTyping();_hadiAppendBubble('assistant','😕 Connection এ সমস্যা হলো। Internet check করো।');}
};
