// ── Offline compose + auto-send: a message written with no internet is queued locally
// (localStorage, per-user) instead of failing outright, then flushed automatically the
// moment connectivity returns (window 'online' event) or the next time Knokz opens. The
// optimistic bubble already shows a single grey tick for any message with no server id yet
// (see _kzMsgHTML/_kzTickSVG) — that same look doubles as the "pending" indicator here, so
// no new UI element was needed for it.
function _kzOfflineKey(){return 'kz_offline_queue_'+(window.sbUser?sbUser.id:'anon');}
function _kzGetOfflineQueue(){try{return JSON.parse(localStorage.getItem(_kzOfflineKey())||'[]');}catch(e){return [];}}
function _kzSaveOfflineQueue(q){try{localStorage.setItem(_kzOfflineKey(),JSON.stringify(q));}catch(e){}}
function _kzQueueOffline(msg){
  var q=_kzGetOfflineQueue();
  q.push(msg);
  _kzSaveOfflineQueue(q);
  if(typeof cmToast==='function')cmToast('ইন্টারনেট নেই — internet ফিরলেই message পাঠানো হবে');
}
window._kzFlushOfflineQueue=async function(){
  if(!navigator.onLine||typeof _sb==='undefined'||!window.sbUser)return;
  var q=_kzGetOfflineQueue();
  if(!q.length)return;
  _kzSaveOfflineQueue([]); // clear up front so a second flush call (e.g. re-opening Knokz) can't double-send
  var sentCount=0;
  for(var i=0;i<q.length;i++){
    var m=q[i];
    try{
      if(m.isGroup)await _sb.from('knokz_messages').insert({conversation_id:m.conversation_id,sender_id:m.sender_id,receiver_id:null,content:m.content,group_id:m.group_id});
      else await _sb.from('knokz_messages').insert({conversation_id:m.conversation_id,sender_id:m.sender_id,receiver_id:m.receiver_id,content:m.content,reply_to:m.reply_to||null,reply_preview:m.reply_preview||null});
      sentCount++;
    }catch(e){
      var remaining=_kzGetOfflineQueue();remaining.push(m);_kzSaveOfflineQueue(remaining); // still offline/failed — retry next flush
    }
  }
  if(sentCount&&typeof cmToast==='function')cmToast(sentCount+'টা pending message পাঠানো হয়েছে');
  if(typeof _kzLoadConvs==='function')_kzLoadConvs();
  // Re-render whichever thread is currently open so its optimistic single-tick bubbles
  // update to the real confirmed state.
  if(_cid){
    if(_kzIsGroup&&_kzActiveGroup&&typeof window.kzOpenGroup==='function')window.kzOpenGroup(_kzActiveGroup);
    else if(!_kzIsGroup&&_uid&&typeof window.kzOpen==='function')window.kzOpen(_uid);
  }
};
window.addEventListener('online',function(){if(typeof window._kzFlushOfflineQueue==='function')window._kzFlushOfflineQueue();});

window.kzSend=async function(){
  var inp=document.getElementById('kz-inp');
  if(!inp||!inp.value.trim()||!_cid)return;
  if(!_kzIsGroup&&!_uid)return;
  var content=inp.value.trim();inp.value='';inp.style.height='auto';
  if(window._kzUpdateActionBtn)window._kzUpdateActionBtn();
  kzCloseEmoji();
  var ep=document.getElementById('kz-emoji-panel');if(ep)ep.classList.remove('open','closing');
  var replyId=_kzReplyTo?_kzReplyTo.id:null;
  var replyPreview=_kzReplyTo?_kzReplyTo.preview:null;
  window.kzCancelReply();
  if(_kzIsGroup){
    _kzAppendGroup({conversation_id:_cid,sender_id:sbUser.id,receiver_id:null,content:content,sent_at:new Date().toISOString()},_kzActiveGroup);
    if(!navigator.onLine){_kzQueueOffline({isGroup:true,conversation_id:_cid,sender_id:sbUser.id,group_id:_kzActiveGroup.id,content:content});return;}
    try{await _sb.from('knokz_messages').insert({conversation_id:_cid,sender_id:sbUser.id,receiver_id:null,content:content,group_id:_kzActiveGroup.id});_kzLoadConvs();}
    catch(e){_kzQueueOffline({isGroup:true,conversation_id:_cid,sender_id:sbUser.id,group_id:_kzActiveGroup.id,content:content});}
  } else {
    _kzAppend({conversation_id:_cid,sender_id:sbUser.id,receiver_id:_uid,content:content,sent_at:new Date().toISOString(),reply_to:replyId,reply_preview:replyPreview});
    if(!navigator.onLine){_kzQueueOffline({isGroup:false,conversation_id:_cid,sender_id:sbUser.id,receiver_id:_uid,content:content,reply_to:replyId,reply_preview:replyPreview});return;}
    try{
      var _ins=await _sb.from('knokz_messages').insert({conversation_id:_cid,sender_id:sbUser.id,receiver_id:_uid,content:content,reply_to:replyId,reply_preview:replyPreview});
      if(_ins.error)throw _ins.error;
      // INSERT succeeded — now fetch the row separately (RLS may block chained .select())
      var _sel=await _sb.from('knokz_messages').select('id,conversation_id,sender_id,receiver_id,content,sent_at,read_at,reply_to,reply_preview').eq('sender_id',sbUser.id).eq('conversation_id',_cid).order('sent_at',{ascending:false}).limit(1);
      var _row=_sel.data&&_sel.data[0];
      if(_row)_kzConfirmSent(_row);
      _kzLoadConvs();
    }catch(e){_kzQueueOffline({isGroup:false,conversation_id:_cid,sender_id:sbUser.id,receiver_id:_uid,content:content,reply_to:replyId,reply_preview:replyPreview});}
  }
};

window.kzCancelReply=function(){
  _kzReplyTo=null;
  var bar=document.getElementById('kz-reply-bar');if(bar)bar.style.display='none';
};

// ── Context menu ──
function _kzShowCtx(x,y,msgId,isSent){
  _kzHideCtx();
  _kzCtxMsgId=msgId;_kzCtxSent=isSent;
  var ctx=document.getElementById('kz-ctx');if(!ctx)return;
  var del=document.getElementById('kz-ctx-del');if(del)del.style.display=isSent?'flex':'none';
  ctx.style.display='block';
  var cw=ctx.offsetWidth||180,ch=ctx.offsetHeight||160;
  ctx.style.left=Math.min(x,window.innerWidth-cw-8)+'px';
  ctx.style.top=Math.min(y,window.innerHeight-ch-8)+'px';
}
function _kzHideCtx(){
  var ctx=document.getElementById('kz-ctx');if(ctx)ctx.style.display='none';
  _kzCtxMsgId=null;
}

window.kzCtxReply=function(){
  if(!_kzCtxMsgId)return;
  var msgEl=document.querySelector('.kz-msg[data-id="'+_kzCtxMsgId+'"]');
  var bubble=msgEl?msgEl.querySelector('.kz-bubble'):null;
  var preview=(bubble?bubble.textContent:'').trim().substring(0,80);
  _kzReplyTo={id:_kzCtxMsgId,preview:preview};
  var bar=document.getElementById('kz-reply-bar');if(bar)bar.style.display='flex';
  var rt=document.getElementById('kz-reply-text');if(rt)rt.textContent=preview;
  _kzHideCtx();
  var inp=document.getElementById('kz-inp');if(inp)inp.focus();
};

window.kzCtxDelete=async function(){
  var id=_kzCtxMsgId;_kzHideCtx();
  if(!id||typeof _sb==='undefined')return;
  await _sb.from('knokz_messages').update({deleted_at:new Date().toISOString(),content:''}).eq('id',id).eq('sender_id',sbUser.id);
  var msgEl=document.querySelector('.kz-msg[data-id="'+id+'"]');
  if(msgEl){var b=msgEl.querySelector('.kz-bubble');if(b)b.innerHTML='<span style="font-style:italic;opacity:.55">🚫 Message deleted</span>';}
};

window.kzCtxReact=function(emoji){kzReact(_kzCtxMsgId,emoji);_kzHideCtx();};

window.kzReact=async function(msgId,emoji){
  if(!msgId||!emoji||typeof _sb==='undefined')return;
  var r=await _sb.from('knokz_messages').select('reactions').eq('id',msgId).maybeSingle();
  var rx=(r.data&&r.data.reactions)||{};
  if(!rx[emoji])rx[emoji]=[];
  var idx=rx[emoji].indexOf(sbUser.id);
  if(idx>-1)rx[emoji].splice(idx,1);else rx[emoji].push(sbUser.id);
  if(!rx[emoji].length)delete rx[emoji];
  await _sb.from('knokz_messages').update({reactions:rx}).eq('id',msgId);
  // Update DOM immediately (realtime will also fire)
  var r2=await _sb.from('knokz_messages').select('*').eq('id',msgId).maybeSingle();
  if(r2.data){
    var msgEl=document.querySelector('.kz-msg[data-id="'+msgId+'"]');
    if(msgEl){
      var tmp=document.createElement('div');tmp.innerHTML=_kzMsgHTML(r2.data);
      msgEl.parentNode.replaceChild(tmp.firstChild,msgEl);
      _kzAttachMsgEvents(document.getElementById('kz-msgs'));
    }
  }
};

