// ── Unread badge ──
function _kzUpdateBadge(n){
  var b=document.getElementById('kz-nav-badge');
  if(!b)return;
  if(n>0){b.textContent=n>99?'99+':n;b.style.display='flex';}
  else{b.style.display='none';}
}

async function _kzLoadUnread(){
  if(!window.sbUser||typeof _sb==='undefined')return;
  try{
    var r=await _sb.from('knokz_messages').select('id',{count:'exact',head:true})
      .eq('receiver_id',sbUser.id).is('read_at',null);
    _kzUpdateBadge(r.count||0);
  }catch(e){}
}

// ── Global realtime: all new messages for this user ──
function _kzStartGlobal(){
  if(_kzGlobalSub||!window.sbUser||typeof _sb==='undefined')return;
  _kzGlobalSub=_sb.channel('kz-global-'+sbUser.id)
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'knokz_messages',filter:'sender_id=eq.'+sbUser.id},function(pl){
      var m=pl.new;if(!m)return;
      var _hasUpdate=m.read_at||m.voice_listened_at;
      if(!_hasUpdate)return;
      if(document.getElementById('kz-root')&&document.getElementById('knokz-page')&&document.getElementById('knokz-page').style.display!=='none'){
        _kzLoadConvs();
      }
      var msgEl=document.querySelector('.kz-msg[data-id="'+m.id+'"]');
      if(msgEl){var tmp=document.createElement('div');tmp.innerHTML=(window._kzMsgHTML||_kzMsgHTML)(m);var newNode=tmp.firstChild;msgEl.parentNode.replaceChild(newNode,msgEl);(window._kzAttachMsgEvents||_kzAttachMsgEvents)(document.getElementById('kz-msgs'));}
    })
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'knokz_messages',filter:'receiver_id=eq.'+sbUser.id},function(pl){
      var m=pl.new;if(!m)return;
      // If this conv is currently open, don't show badge/toast (chat handles it)
      if(_cid&&m.conversation_id===_cid)return;
      // Update unread badge
      _kzLoadUnread();
      // Toast + browser notification
      var senderName=_prof[m.sender_id]?(_prof[m.sender_id].name||'Someone'):'Someone';
      var preview=m.content.indexOf('[img]')==0?'📷 Image':m.content.substring(0,40)+(m.content.length>40?'…':'');
      var senderAvatar=_prof[m.sender_id]&&_prof[m.sender_id].avatar_url||null;
      _kzBrowserNotif('Knokz — '+senderName,preview,senderAvatar);
      // Refresh conv list if Knokz page open
      if(document.getElementById('kz-root')&&document.getElementById('knokz-page')&&document.getElementById('knokz-page').style.display!=='none'){
        _kzLoadConvs();
      }
    }).subscribe();
}

