window.kzSendWelcome=async function(toUserId){
  if(!window.sbUser||typeof _sb==='undefined')return;
  try{
    var cid=_kzCK(sbUser.id,toUserId);
    // Check if conversation already exists
    var ex=await _sb.from('knokz_messages').select('id',{count:'exact',head:true}).eq('conversation_id',cid);
    if(ex.count>0)return; // already have messages
    var myName=(window.sbProfile&&window.sbProfile.name)||'A fellow Rizer';
    await _sb.from('knokz_messages').insert({
      conversation_id:cid,sender_id:sbUser.id,receiver_id:toUserId,
      content:'⚡ Hey! We\'re Rising Together now. Let\'s keep each other accountable! — '+myName
    });
  }catch(e){}
};

