window.kzNewMsgSearch=async function(q){
  var list=document.getElementById('kz-nm-list');
  if(!list)return;
  q=(q||'').trim();
  if(!q){list.innerHTML='<div style="text-align:center;padding:32px 16px;color:var(--sub-text);font-size:13px">Search for someone to message</div>';return;}
  if(q.length<2){return;}
  list.innerHTML='<div style="text-align:center;padding:24px;color:var(--sub-text);font-size:13px">Searching...</div>';
  try{
    var r=await _sb.from('profiles').select('id,name,username,avatar_url').or('name.ilike.%'+q+'%,username.ilike.%'+q+'%').neq('id',sbUser.id).limit(20);
    var users=r.data||[];
    if(!users.length){list.innerHTML='<div style="text-align:center;padding:32px 16px;color:var(--sub-text);font-size:13px">No users found</div>';return;}
    list.innerHTML=users.map(function(u){
      var av=u.avatar_url?'<img src="'+u.avatar_url+'" style="width:40px;height:40px;border-radius:50%;object-fit:cover;flex-shrink:0">':'<div style="width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,#FF8A00,#FFB800);display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:#090B12;flex-shrink:0">'+(u.name||'?').charAt(0).toUpperCase()+'</div>';
      return'<div onclick="kzNewMsgStart(\''+u.id+'\')" style="display:flex;align-items:center;gap:12px;padding:10px 16px;cursor:pointer;transition:background .12s" onmouseenter="this.style.background=\'rgba(255,138,0,.06)\'" onmouseleave="this.style.background=\'\'">'+av+'<div style="flex:1;min-width:0"><div style="font-size:14px;font-weight:600;color:var(--text)">'+(u.name||'Rizer')+'</div><div style="font-size:12px;color:var(--sub-text)">@'+(u.username||'')+'</div></div><svg viewBox="0 0 24 24" style="width:16px;height:16px;fill:none;stroke:var(--sub-text);stroke-width:2;stroke-linecap:round"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"/></svg></div>';
    }).join('');
  }catch(e){list.innerHTML='<div style="text-align:center;padding:24px;color:var(--sub-text);font-size:13px">Error searching</div>';}
};

window.kzNewMsgStart=function(userId){
  kzNewMsgClose();
  setTimeout(function(){window.kzOpen(userId);},200);
};

var _kzLastSeenInterval=null;
window.kzInitPage=function(openUserId){
  _kzH();
  window.removeEventListener('resize',_kzH);
  window.addEventListener('resize',_kzH);
  var root=document.getElementById('kz-root');if(root)root.classList.remove('chat-open');
  _kzUpdateBadge(0);
  // Update last_seen every 60s while page is open
  _kzUpdateLastSeen();
  if(_kzLastSeenInterval)clearInterval(_kzLastSeenInterval);
  _kzLastSeenInterval=setInterval(_kzUpdateLastSeen,60000);
  _kzLoadConvs().then(function(){
    if(openUserId)window.kzOpen(openUserId);
  });
};

