// ── Group chat ──
var _kzGroupMembers=[]; // selected members for group creation
var _kzIsGroup=false;
var _kzActiveGroup=null;

// ── KzMeet inline booking flow ───────────────────────────
var _kzm={step:1,evt:null,avail:null,selDate:null,selSlot:null,otherUid:null,otherName:'',otherAvatar:''};

function _kzmSheet(){return document.getElementById('kz-meet-sheet');}
function _kzmBd(){return document.getElementById('kz-meet-bd');}
function _kzmBody(){return document.getElementById('kzm-body');}

function _kzmAnimate(html,dir){
  // dir: 'in'=slide from right, 'back'=slide from left
  var body=_kzmBody();if(!body)return;
  var from=dir==='back'?'translateX(-40px)':'translateX(40px)';
  body.style.opacity='0';body.style.transform=from;body.innerHTML=html;
  requestAnimationFrame(function(){
    body.style.transition='opacity .22s ease,transform .22s ease';
    body.style.opacity='1';body.style.transform='translateX(0)';
    setTimeout(function(){body.style.transition='';},240);
  });
}

function _kzmHdr(title,showBack,backFn){
  return'<div style="display:flex;align-items:center;gap:10px;padding:14px 18px 12px;flex-shrink:0;position:relative">'
    +(showBack?'<button onclick="'+backFn+'()" style="width:34px;height:34px;border-radius:50%;background:var(--bg2,var(--bg));border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 2px 8px rgba(0,0,0,.15)"><svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><path d="M19 12H5M12 5l-7 7 7 7"/></svg></button>':'<div style="width:34px"></div>')
    +'<span style="flex:1;font-size:15px;font-weight:800;color:var(--text);text-align:center;letter-spacing:-.3px">'+title+'</span>'
    +'<button onclick="kzCloseMeetSheet()" style="width:34px;height:34px;border-radius:50%;background:var(--bg2,var(--bg));border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 2px 8px rgba(0,0,0,.15)"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button>'
    +'</div>';
}

window.kzOpenMeetSheet=function(){
  var sheet=_kzmSheet(),bd=_kzmBd();if(!sheet||!bd)return;
  _kzm.step=1;_kzm.evt=null;_kzm.selDate=null;_kzm.selSlot=null;
  _kzm.otherUid=window._kzActiveUid||null;
  _kzm.otherName=window._kzChatName||'User';
  var p=window._kzChatProfile||null;
  _kzm.otherAvatar=(p&&p.avatar_url)||'';
  bd.style.display='block';bd.style.opacity='0';
  sheet.style.display='flex';
  sheet.classList.remove('close','open');
  sheet.style.transform='translateY(100%)';
  requestAnimationFrame(function(){
    requestAnimationFrame(function(){
      sheet.style.transform='';
      sheet.classList.add('open');
      bd.style.transition='opacity .25s';bd.style.opacity='1';
      setTimeout(function(){bd.style.transition='';},260);
    });
  });
  _kzmStep1();
};

function _kzmStep1(){
  _kzm.step=1;
  var avEl=_kzm.otherAvatar
    ?'<img src="'+_kzm.otherAvatar+'" style="width:52px;height:52px;border-radius:50%;object-fit:cover;border:2.5px solid #FF8A00;box-shadow:0 0 0 4px rgba(255,138,0,.12)">'
    :'<div style="width:52px;height:52px;border-radius:50%;background:linear-gradient(135deg,#FF8A00,#ff6b00);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:800;color:#fff;box-shadow:0 4px 12px rgba(255,138,0,.35)">'+(_kzm.otherName[0]||'?').toUpperCase()+'</div>';
  var hdr=_kzmHdr('মিটিং বুক করুন',false,'');
  var profile='<div style="display:flex;align-items:center;gap:14px;padding:6px 18px 16px">'
    +avEl
    +'<div>'
    +'<div style="font-size:16px;font-weight:800;color:var(--text);letter-spacing:-.3px">'+_kzm.otherName+'</div>'
    +'<div style="font-size:12px;color:var(--sub-text);margin-top:2px">একটি মিটিং ধরন বেছে নিন</div>'
    +'</div>'
    +'</div>';
  var listWrap='<div id="kzm-step1-list" style="flex:1;overflow-y:auto;padding:0 16px 20px">'
    +'<div style="text-align:center;padding:30px;color:var(--sub-text);font-size:13px">লোড হচ্ছে...</div></div>';
  _kzmBody().innerHTML='';
  _kzmBody().insertAdjacentHTML('beforeend', hdr+profile+listWrap);

  if(!window._sb||!_kzm.otherUid){
    document.getElementById('kzm-step1-list').innerHTML='<div style="text-align:center;padding:24px;color:var(--sub-text);font-size:13px">ব্যবহারকারী পাওয়া যায়নি।</div>';
    return;
  }
  window._sb.from('rizmeet_event_types').select('*').eq('user_id',_kzm.otherUid).eq('is_active',true).then(function(res){
    var listEl=document.getElementById('kzm-step1-list');if(!listEl)return;
    var evts=res.data||[];
    if(!evts.length){listEl.innerHTML='<div style="text-align:center;padding:24px;color:var(--sub-text);font-size:13px">'+_kzm.otherName+'-এর কোনো active মিটিং নেই।</div>';return;}
    _kzm.evts=evts;
    var locIcon={video:'<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M23 7l-7 5 7 5V7z"/><rect x="1" y="5" width="15" height="14" rx="2"/></svg>',phone:'<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 9.8 19.79 19.79 0 01.22 1.18 2 2 0 012.18 0h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L6.91 7.09a16 16 0 006 6l.56-.56a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 14.92z"/></svg>',inperson:'<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>'};
    listEl.innerHTML=evts.map(function(e,i){
      var loc={video:'Video Call',phone:'Phone Call',inperson:'সরাসরি দেখা'}[e.location_type]||'Meeting';
      var locIco=locIcon[e.location_type]||locIcon.video;
      var price=e.price>0?'৳'+e.price:'Free Booking';
      var col=e.color||'#FF8A00';
      var colRgb=col==='#FF8A00'?'255,138,0':'255,138,0';
      return'<div onclick="kzmPickEvt(\''+e.id+'\')" style="position:relative;overflow:hidden;padding:16px;border-radius:18px;background:var(--bg2,var(--bg));border:1.5px solid var(--border);margin-bottom:10px;cursor:pointer;transition:all .2s;box-shadow:0 2px 10px rgba(0,0,0,.12)" onmouseenter="this.style.transform=\'translateY(-1px)\';this.style.boxShadow=\'0 8px 24px rgba('+colRgb+',.22)\';this.style.borderColor=\''+col+'\'" onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'0 2px 10px rgba(0,0,0,.12)\';this.style.borderColor=\'var(--border)\'">'
        +'<div style="position:absolute;top:0;left:0;width:100%;height:3px;background:linear-gradient(90deg,'+col+','+col+'88)"></div>'
        +'<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px">'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:14px;font-weight:800;color:var(--text);margin-bottom:6px;letter-spacing:-.2px">'+(e.name||e.title||'মিটিং')+'</div>'
        +'<div style="display:flex;align-items:center;gap:10px">'
        +'<span style="display:inline-flex;align-items:center;gap:4px;font-size:11px;color:var(--sub-text);background:var(--bg2,var(--bg));padding:3px 8px;border-radius:20px">'+locIco+' '+loc+'</span>'
        +'<span style="display:inline-flex;align-items:center;gap:3px;font-size:11px;color:var(--sub-text)"><svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg> '+(e.duration_mins||30)+' মিনিট</span>'
        +'</div>'
        +'</div>'
        +'<div style="text-align:right;flex-shrink:0">'
        +'<div style="font-size:15px;font-weight:800;color:'+col+'">'+price+'</div>'
        +'<div style="margin-top:6px;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg,'+col+','+col+'cc);display:flex;align-items:center;justify-content:center;margin-left:auto;box-shadow:0 3px 8px rgba('+colRgb+',.3)">'
        +'<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round"><path d="M5 12h14M12 5l7 7-7 7"/></svg>'
        +'</div>'
        +'</div>'
        +'</div>'
        +'</div>';
    }).join('');
  });
}

window.kzmPickEvt=function(id){
  _kzm.evt=(_kzm.evts||[]).find(function(e){return e.id===id;})||null;
  if(!_kzm.evt)return;
  _kzmStep2();
};

function _kzmStep2(){
  _kzm.step=2;
  var days=[],today=new Date();today.setHours(0,0,0,0);
  var dayNames=['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
  var monthNames=['জান','ফেব','মার','এপ্রি','মে','জুন','জুল','আগ','সেপ','অক্টো','নভে','ডিসে'];
  for(var i=1;i<=14;i++){var d=new Date(today);d.setDate(today.getDate()+i);days.push(d);}
  var col=_kzm.evt.color||'#FF8A00';
  var evtName=_kzm.evt.name||_kzm.evt.title||'মিটিং';
  var dur=_kzm.evt.duration_mins||30;
  var locLabel={video:'Video Call',phone:'Phone Call',inperson:'সরাসরি'}[_kzm.evt.location_type]||'Meeting';
  var evtBadge='<div style="display:flex;align-items:center;gap:8px;padding:10px 16px;margin:0 16px 14px;background:linear-gradient(135deg,'+col+'18,'+col+'08);border-radius:14px;border:1px solid '+col+'30">'
    +'<div style="width:8px;height:8px;border-radius:50%;background:'+col+';flex-shrink:0"></div>'
    +'<div style="font-size:12px;font-weight:700;color:var(--text)">'+evtName+'</div>'
    +'<div style="font-size:11px;color:var(--sub-text);margin-left:auto">'+dur+'মি · '+locLabel+'</div>'
    +'</div>';
  var daysHTML=days.map(function(d){
    var key=d.toISOString().slice(0,10);
    var isWeekend=d.getDay()===5||d.getDay()===6;
    return'<div onclick="kzmPickDate(\''+key+'\')" id="kzmd-'+key+'" style="flex:0 0 50px;display:flex;flex-direction:column;align-items:center;gap:2px;padding:10px 6px;border-radius:14px;border:1.5px solid var(--border);cursor:pointer;transition:all .18s;background:var(--bg2,var(--bg))" onmouseenter="if(!this.classList.contains(\'sel\')){this.style.borderColor=\''+col+'\';this.style.background=\''+col+'20\'}" onmouseleave="if(!this.classList.contains(\'sel\')){this.style.borderColor=\'var(--border)\';this.style.background=\'var(--bg2,var(--bg))\'}">'
      +'<div style="font-size:10px;font-weight:700;color:'+(isWeekend?col:'var(--sub-text)')+'">'+dayNames[d.getDay()]+'</div>'
      +'<div style="font-size:18px;font-weight:900;color:var(--text);line-height:1.1">'+d.getDate()+'</div>'
      +'<div style="font-size:9px;color:var(--sub-text)">'+monthNames[d.getMonth()]+'</div>'
      +'</div>';
  }).join('');
  var html=_kzmHdr(evtName,'kzmBackStep1','kzmBackStep1')
    +evtBadge
    +'<div style="padding:0 16px 6px;font-size:11px;font-weight:700;color:var(--sub-text);text-transform:uppercase;letter-spacing:.6px">তারিখ বেছে নিন</div>'
    +'<div style="display:flex;gap:7px;overflow-x:auto;padding:4px 16px 16px;-webkit-overflow-scrolling:touch;scrollbar-width:none">'+daysHTML+'</div>'
    +'<div style="padding:0 16px 6px;font-size:11px;font-weight:700;color:var(--sub-text);text-transform:uppercase;letter-spacing:.6px" id="kzm-slot-lbl" style="display:none">সময় বেছে নিন</div>'
    +'<div id="kzm-slots-wrap" style="flex:1;overflow-y:auto;padding:0 16px 20px"><div style="text-align:center;padding:28px 0;color:var(--sub-text);font-size:13px;opacity:.6">⬆ উপরে তারিখ বেছে নিন</div></div>';
  _kzmAnimate(html,'in');
}

window.kzmBackStep1=function(){_kzmAnimate('','back');setTimeout(function(){_kzmStep1();},0);};

window.kzmPickDate=function(key){
  _kzm.selDate=key;
  document.querySelectorAll('[id^="kzmd-"]').forEach(function(el){
    el.classList.remove('sel');
    el.style.borderColor='var(--border)';el.style.background='';
    el.querySelector('div:nth-child(2)').style.color='var(--text)';
  });
  var el=document.getElementById('kzmd-'+key);
  if(el){el.classList.add('sel');el.style.borderColor=(_kzm.evt.color||'#FF8A00');el.style.background='rgba(255,138,0,.08)';el.querySelector('div:nth-child(2)').style.color=(_kzm.evt.color||'#FF8A00');}
  // Generate time slots
  var slotWrap=document.getElementById('kzm-slots-wrap');
  if(!slotWrap)return;
  var dur=_kzm.evt.duration_mins||30;
  var slots=[];
  for(var h=8;h<20;h++){for(var m=0;m<60;m+=dur){if(h*60+m+dur<=20*60)slots.push({h:h,m:m});}}
  var col=_kzm.evt.color||'#FF8A00';
  var slotLbl=document.getElementById('kzm-slot-lbl');if(slotLbl)slotLbl.style.display='block';
  slotWrap.innerHTML='<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">'
    +slots.map(function(s){
      var label=(s.h<10?'0':'')+s.h+':'+(s.m<10?'0':'')+s.m;
      var ampm=s.h<12?'AM':'PM';var h12=s.h%12||12;
      var disp=(h12<10?'0':'')+h12+':'+(s.m<10?'0':'')+s.m;
      return'<div onclick="kzmPickSlot(\''+label+'\')" id="kzms-'+label.replace(':','')+'" style="padding:10px 4px;border-radius:12px;border:1.5px solid var(--border);text-align:center;cursor:pointer;transition:all .18s;background:var(--bg2,var(--bg))" onmouseenter="if(!this.classList.contains(\'sel\')){this.style.borderColor=\''+col+'\';this.style.background=\''+col+'25\'}" onmouseleave="if(!this.classList.contains(\'sel\')){this.style.borderColor=\'var(--border)\';this.style.background=\'var(--bg2,var(--bg))\'}">'
        +'<div style="font-size:12px;font-weight:700;color:var(--text)">'+disp+'</div>'
        +'<div style="font-size:10px;color:var(--sub-text);margin-top:1px">'+ampm+'</div>'
        +'</div>';
    }).join('')
    +'</div>';
}

window.kzmPickSlot=function(slot){
  _kzm.selSlot=slot;
  document.querySelectorAll('[id^="kzms-"]').forEach(function(el){
    el.classList.remove('sel');el.style.borderColor='var(--border)';el.style.background='';el.style.color='var(--text)';
  });
  var key=slot.replace(':','');
  var el=document.getElementById('kzms-'+key);
  var col=_kzm.evt.color||'#FF8A00';
  if(el){el.classList.add('sel');el.style.borderColor=col;el.style.background=col;el.style.color='#fff';}
  setTimeout(function(){_kzmStep3();},200);
};

async function _kzmStep3(){
  _kzm.step=3;
  var d=new Date(_kzm.selDate+'T'+_kzm.selSlot);
  var dayNames=['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
  var monthNames=['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
  var dateStr=dayNames[d.getDay()]+', '+d.getDate()+' '+monthNames[d.getMonth()];
  var h12=d.getHours()%12||12;var ampm=d.getHours()<12?'AM':'PM';
  var timeStr=(h12<10?'0':'')+h12+':'+(d.getMinutes()<10?'0':'')+d.getMinutes()+' '+ampm;
  var col=_kzm.evt.color||'#FF8A00';
  var _mp=window.sbProfile||{};
  var _authEmail=(window.sbUser&&window.sbUser.email)||'';
  var _phoneFromEmail='';
  var _pem=_authEmail.match(/^p(\d+)@.*\.supabase\.co$/);
  if(_pem) _phoneFromEmail=_pem[1];
  var myName=_mp.name||(window.sbUser&&window.sbUser.user_metadata&&(window.sbUser.user_metadata.full_name||window.sbUser.user_metadata.name))||'';
  var myEmail=_mp.contact_email||_mp.email||(_authEmail.indexOf('.supabase.co')<0?_authEmail:'')||'';
  var myPhone=_mp.phone||(window.sbUser&&window.sbUser.phone)||_phoneFromEmail||'';
  var inpStyle='width:100%;box-sizing:border-box;border:1.5px solid var(--border);border-radius:14px;padding:13px 14px 13px 40px;font-size:13px;font-family:inherit;background:var(--input-bg,var(--bg));color:var(--text);outline:none;transition:border-color .18s';
  var wrapStyle='position:relative;display:flex;align-items:center';
  var icoStyle='position:absolute;left:13px;top:50%;transform:translateY(-50%);pointer-events:none;color:var(--sub-text)';
  var nameIco='<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="8" r="4"/><path d="M4 20c0-4 3.6-7 8-7s8 3 8 7"/></svg>';
  var emailIco='<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="M22 7l-10 7L2 7"/></svg>';
  var phoneIco='<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 9.8 19.79 19.79 0 01.22 1.18 2 2 0 012.18 0h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L6.91 7.09a16 16 0 006 6l.56-.56a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 14.92z"/></svg>';
  var noteIco='<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>';
  var html=_kzmHdr('আপনার তথ্য','kzmBackStep2','kzmBackStep2')
    +'<div style="margin:2px 16px 14px;padding:14px 16px;background:linear-gradient(135deg,'+col+'18,'+col+'08);border-radius:16px;border:1px solid '+col+'30">'
    +'<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">'
    +'<div style="width:8px;height:8px;border-radius:50%;background:'+col+'"></div>'
    +'<div style="font-size:13px;font-weight:800;color:var(--text)">'+(_kzm.evt.name||_kzm.evt.title||'মিটিং')+'</div>'
    +'</div>'
    +'<div style="display:flex;gap:12px;flex-wrap:wrap">'
    +'<span style="font-size:11px;color:var(--sub-text);display:flex;align-items:center;gap:4px"><svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg> '+dateStr+'</span>'
    +'<span style="font-size:11px;color:var(--sub-text);display:flex;align-items:center;gap:4px"><svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg> '+timeStr+' · '+(_kzm.evt.duration_mins||30)+'মিনিট</span>'
    +'</div>'
    +'</div>'
    +'<div style="flex:1;overflow-y:auto;padding:0 16px 16px;display:flex;flex-direction:column;gap:10px">'
    +'<div style="'+wrapStyle+'"><span style="'+icoStyle+'">'+nameIco+'</span><input id="kzmf-name" placeholder="আপনার নাম *" value="'+myName+'" style="'+inpStyle+'" onfocus="this.style.borderColor=\''+col+'\'" onblur="this.style.borderColor=\'var(--border)\'"></div>'
    +'<div style="'+wrapStyle+'"><span style="'+icoStyle+'">'+emailIco+'</span><input id="kzmf-email" placeholder="ইমেইল *" type="email" value="'+myEmail+'" style="'+inpStyle+'" onfocus="this.style.borderColor=\''+col+'\'" onblur="this.style.borderColor=\'var(--border)\'"></div>'
    +'<div style="'+wrapStyle+'"><span style="'+icoStyle+'">'+phoneIco+'</span><input id="kzmf-phone" placeholder="ফোন নম্বর (ঐচ্ছিক)" type="tel" value="'+myPhone+'" style="'+inpStyle+'" onfocus="this.style.borderColor=\''+col+'\'" onblur="this.style.borderColor=\'var(--border)\'"></div>'
    +'<div style="position:relative"><span style="position:absolute;left:13px;top:14px;pointer-events:none;color:var(--sub-text)">'+noteIco+'</span><textarea id="kzmf-note" placeholder="কোনো বার্তা? (ঐচ্ছিক)" rows="2" style="width:100%;box-sizing:border-box;border:1.5px solid var(--border);border-radius:14px;padding:13px 14px 13px 40px;font-size:13px;font-family:inherit;background:var(--input-bg,var(--bg));color:var(--text);outline:none;resize:none;transition:border-color .18s" onfocus="this.style.borderColor=\''+col+'\'" onblur="this.style.borderColor=\'var(--border)\'"></textarea></div>'
    +'</div>'
    +'<div style="padding:10px 16px 18px;flex-shrink:0">'
    +'<button onclick="kzmConfirmBook()" style="width:100%;padding:15px;border-radius:16px;background:linear-gradient(135deg,'+col+','+col+'cc);border:none;cursor:pointer;font-size:14px;font-weight:800;color:#fff;font-family:inherit;letter-spacing:-.2px;box-shadow:0 6px 20px '+col+'55;transition:all .18s" onmouseenter="this.style.transform=\'translateY(-1px)\';this.style.boxShadow=\'0 10px 28px '+col+'66\'" onmouseleave="this.style.transform=\'\';this.style.boxShadow=\'0 6px 20px '+col+'55\'">মিটিং নিশ্চিত করুন →</button>'
    +'</div>';
  _kzmAnimate(html,'in');
}

window.kzmBackStep2=function(){_kzmAnimate('','back');setTimeout(function(){_kzmStep2();},0);};

window.kzmConfirmBook=async function(){
  var name=(document.getElementById('kzmf-name')||{}).value||'';
  var email=(document.getElementById('kzmf-email')||{}).value||'';
  var phone=(document.getElementById('kzmf-phone')||{}).value||'';
  var note=(document.getElementById('kzmf-note')||{}).value||'';
  if(!name.trim()||!email.trim()){alert('নাম এবং ইমেইল দিন');return;}
  var btn=_kzmBody().querySelector('button[onclick="kzmConfirmBook()"]');
  if(btn){btn.textContent='বুক হচ্ছে...';btn.disabled=true;}
  // Calculate end time
  var start=new Date(_kzm.selDate+'T'+_kzm.selSlot+':00');
  var end=new Date(start.getTime()+(_kzm.evt.duration_mins||30)*60000);
  try{
    var res=await window._sb.from('rizmeet_bookings').insert({
      event_type_id:_kzm.evt.id,
      host_user_id:_kzm.otherUid,
      booker_name:name.trim(),
      booker_email:email.trim(),
      booker_phone:phone.trim(),
      booker_note:note.trim(),
      start_time:start.toISOString(),
      end_time:end.toISOString(),
      duration_mins:_kzm.evt.duration_mins||30,
      location_type:_kzm.evt.location_type||'video',
      price:_kzm.evt.price||0,
      status:'confirmed'
    });
    if(res.error)throw res.error;
    _kzmStep4();
  }catch(err){
    if(btn){btn.textContent='মিটিং নিশ্চিত করুন →';btn.disabled=false;}
    alert('Error: '+(err.message||'কিছু সমস্যা হয়েছে'));
  }
};

function _kzmStep4(){
  var d=new Date(_kzm.selDate+'T'+_kzm.selSlot);
  var h12=d.getHours()%12||12;var ampm=d.getHours()<12?'AM':'PM';
  var timeStr=(h12<10?'0':'')+h12+':'+(d.getMinutes()<10?'0':'')+d.getMinutes()+' '+ampm;
  var months=['জানু','ফেব','মার্চ','এপ্রি','মে','জুন','জুল','আগ','সেপ','অক্টো','নভে','ডিসে'];
  var dateStr=d.getDate()+' '+months[d.getMonth()]+' '+d.getFullYear();
  var col=_kzm.evt.color||'#FF8A00';
  var avEl2=_kzm.otherAvatar
    ?'<img src="'+_kzm.otherAvatar+'" style="width:44px;height:44px;border-radius:50%;object-fit:cover;border:2px solid '+col+'">'
    :'<div style="width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,'+col+','+col+'aa);display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:800;color:#fff">'+(_kzm.otherName[0]||'?').toUpperCase()+'</div>';
  var html='<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:28px 20px;text-align:center">'
    +'<div style="position:relative;margin-bottom:20px">'
    +'<div style="width:80px;height:80px;border-radius:50%;background:linear-gradient(135deg,'+col+','+col+'bb);display:flex;align-items:center;justify-content:center;box-shadow:0 8px 28px '+col+'55;animation:kzm-pop .4s cubic-bezier(.34,1.56,.64,1)">'
    +'<svg viewBox="0 0 24 24" width="38" height="38" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>'
    +'</div>'
    +'</div>'
    +'<div style="font-size:22px;font-weight:900;color:var(--text);margin-bottom:4px;letter-spacing:-.5px">বুকিং সম্পন্ন!</div>'
    +'<div style="font-size:13px;color:var(--sub-text);margin-bottom:22px;max-width:220px;line-height:1.5">'+_kzm.otherName+'-এর সাথে আপনার মিটিং নিশ্চিত হয়েছে</div>'
    +'<div style="width:100%;background:linear-gradient(135deg,'+col+'18,'+col+'08);border-radius:18px;padding:18px;box-sizing:border-box;border:1px solid '+col+'30;margin-bottom:20px">'
    +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;padding-bottom:12px;border-bottom:1px solid '+col+'20">'
    +avEl2
    +'<div style="text-align:left">'
    +'<div style="font-size:13px;font-weight:800;color:var(--text)">'+_kzm.otherName+'</div>'
    +'<div style="font-size:11px;color:'+col+';font-weight:600">'+(_kzm.evt.name||_kzm.evt.title||'মিটিং')+'</div>'
    +'</div>'
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:8px;text-align:left">'
    +'<div style="display:flex;align-items:center;gap:8px;font-size:12px;color:var(--text)"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="'+col+'" stroke-width="2" stroke-linecap="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg><span style="font-weight:600">'+dateStr+'</span></div>'
    +'<div style="display:flex;align-items:center;gap:8px;font-size:12px;color:var(--text)"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="'+col+'" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span style="font-weight:600">'+timeStr+' · '+(_kzm.evt.duration_mins||30)+' মিনিট</span></div>'
    +'</div>'
    +'</div>'
    +'<button onclick="kzCloseMeetSheet()" style="width:100%;padding:15px;border-radius:16px;background:linear-gradient(135deg,'+col+','+col+'cc);border:none;cursor:pointer;font-size:14px;font-weight:800;color:#fff;font-family:inherit;letter-spacing:-.2px;box-shadow:0 6px 20px '+col+'55">দারুণ, ধন্যবাদ! ✓</button>'
    +'</div>';
  _kzmAnimate(html,'in');
  // Also send a chat message notification
  setTimeout(function(){
    var d2=new Date(_kzm.selDate+'T'+_kzm.selSlot);
    var msg='📅 আমি একটি মিটিং বুক করেছি!\n\n🗓 '+(_kzm.evt.name||_kzm.evt.title||'মিটিং')+'\n📆 '+dateStr+' · '+timeStr;
    var inp=document.getElementById('kz-inp');
    if(inp){inp.value=msg;inp.dispatchEvent(new Event('input'));kzSend();}
  },500);
}

window.kzCloseMeetSheet=function(){
  var sheet=_kzmSheet(),bd=_kzmBd();if(!sheet)return;
  sheet.classList.remove('open');sheet.classList.add('close');
  setTimeout(function(){sheet.style.display='none';if(bd)bd.style.display='none';},220);
};
// ────────────────────────────────────────────────────────

var _kzSettings={notif:true,sound:true,read:true,lastseen:true,autodl:true};
(function(){try{var s=localStorage.getItem('kz_settings');if(s)_kzSettings=Object.assign(_kzSettings,JSON.parse(s));}catch(e){}})();

// ── Chat background patterns ──
var _kzBgDefs=[
  {id:'solid',label:'Solid',desc:'Clean default'},
  {id:'dots',label:'Dot Grid',desc:'Notion style'},
  {id:'graph',label:'Graph',desc:'Notebook grid'},
  {id:'circuit',label:'Circuit',desc:'Tech flow'},
  {id:'topo',label:'Topo',desc:'Focus rings'},
  {id:'chevron',label:'Arrow',desc:'Drive forward'},
];
function _kzBgGet(id,forTile){
  var dark=document.body.classList.contains('dark-mode');
  var op=forTile?(dark?0.55:0.45):(dark?0.07:0.055);
  var f='rgba('+(dark?'255,255,255':'0,0,0')+','+op+')';
  var enc=encodeURIComponent;
  var u=function(svg){return'url("data:image/svg+xml,'+enc(svg)+'")';};
  if(id==='dots')return u('<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20"><circle cx="2" cy="2" r="1.3" fill="'+f+'"/></svg>');
  if(id==='graph')return u('<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24"><path d="M24 0L0 0 0 24" fill="none" stroke="'+f+'" stroke-width="0.7"/></svg>');
  if(id==='circuit')return u('<svg xmlns="http://www.w3.org/2000/svg" width="48" height="48"><circle cx="0" cy="0" r="2.2" fill="'+f+'"/><circle cx="48" cy="0" r="2.2" fill="'+f+'"/><circle cx="0" cy="48" r="2.2" fill="'+f+'"/><circle cx="48" cy="48" r="2.2" fill="'+f+'"/><circle cx="24" cy="24" r="3.5" fill="none" stroke="'+f+'" stroke-width="1.3"/><circle cx="24" cy="24" r="1.2" fill="'+f+'"/><path d="M0 0L18 0 M30 0L48 0 M0 48L18 48 M30 48L48 48 M0 0L0 18 M0 30L0 48 M48 0L48 18 M48 30L48 48 M18 0L18 13 24 13 24 20.5 M24 27.5L24 35 30 35 30 48 M18 48L18 35" fill="none" stroke="'+f+'" stroke-width="0.9"/></svg>');
  if(id==='topo')return u('<svg xmlns="http://www.w3.org/2000/svg" width="80" height="60"><ellipse cx="40" cy="30" rx="38" ry="27" fill="none" stroke="'+f+'" stroke-width="1.2"/><ellipse cx="40" cy="30" rx="26" ry="18" fill="none" stroke="'+f+'" stroke-width="1.2"/><ellipse cx="40" cy="30" rx="14" ry="9" fill="none" stroke="'+f+'" stroke-width="1.2"/><ellipse cx="40" cy="30" rx="4" ry="2.5" fill="none" stroke="'+f+'" stroke-width="1.2"/></svg>');
  if(id==='chevron')return u('<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28"><path d="M0 14L14 0 28 14 M0 28L14 14 28 28" fill="none" stroke="'+f+'" stroke-width="1.1"/></svg>');
  return'none';
}
window._kzApplyBg=function(){
  var el=document.getElementById('kz-msgs');if(!el)return;
  var id='solid';try{id=localStorage.getItem('kz_bg')||'solid';}catch(e){}
  if(id==='solid'){el.style.backgroundImage='none';return;}
  el.style.backgroundImage=_kzBgGet(id,false);
  el.style.backgroundRepeat='repeat';
  el.style.backgroundSize='auto';
};
function _kzRenderBgTiles(){
  var c=document.getElementById('kz-bg-tiles');if(!c)return;
  var cur='solid';try{cur=localStorage.getItem('kz_bg')||'solid';}catch(e){}
  c.innerHTML=_kzBgDefs.map(function(d){
    var sel=cur===d.id;
    var tileBg=d.id==='solid'?'none':_kzBgGet(d.id,true);
    return'<div class="kz-bg-tile" data-bg="'+d.id+'" onclick="kzSetBg(\''+d.id+'\')" style="cursor:pointer;border-radius:10px;overflow:hidden;outline:'+(sel?'2.5px solid #FF8A00':'2.5px solid var(--border)')+';transition:outline .15s">'
      +'<div style="height:52px;background:var(--bg);background-image:'+tileBg+';background-repeat:repeat;background-size:auto"></div>'
      +'<div style="padding:5px 4px 6px;font-size:10px;font-weight:700;color:'+(sel?'#FF8A00':'var(--sub-text)')+';text-align:center;background:var(--card);letter-spacing:.3px">'+d.label+'</div>'
      +'</div>';
  }).join('');
}
window.kzSetBg=function(id){
  try{localStorage.setItem('kz_bg',id);}catch(e){}
  window._kzApplyBg();
  document.querySelectorAll('.kz-bg-tile').forEach(function(t){
    var sel=t.dataset.bg===id;
    t.style.outline=sel?'2.5px solid #FF8A00':'2.5px solid var(--border)';
    t.querySelector('div:last-child').style.color=sel?'#FF8A00':'var(--sub-text)';
  });
};

window.kzOpenSettings=function(){
  var panel=document.getElementById('kz-settings-panel');
  var bd=document.getElementById('kz-settings-bd');
  if(!panel||!bd)return;
  // Sync toggles
  ['notif','sound','read','lastseen','autodl'].forEach(function(k){
    var el=document.getElementById('kzs-'+k);
    if(el)el.checked=!!_kzSettings[k];
  });
  _kzRenderBgTiles();
  bd.style.display='block';
  panel.style.display='flex';
};

window.kzCloseSettings=function(){
  var panel=document.getElementById('kz-settings-panel');
  var bd=document.getElementById('kz-settings-bd');
  if(panel)panel.style.display='none';
  if(bd)bd.style.display='none';
};

window.kzSettingChange=function(key,val){
  _kzSettings[key]=val;
  try{localStorage.setItem('kz_settings',JSON.stringify(_kzSettings));}catch(e){}
};

window.kzClearAllChats=function(){
  if(!confirm('সব chat history local থেকে clear করবে?'))return;
  try{
    Object.keys(localStorage).filter(function(k){return k.indexOf('kz_')===0;}).forEach(function(k){localStorage.removeItem(k);});
  }catch(e){}
  kzCloseSettings();
};

window.kzNewGroupOpen=function(){
  _kzGroupMembers=[];
  var modal=document.getElementById('kz-ng-modal');
  var bd=document.getElementById('kz-ng-bd');
  if(!modal||!bd)return;
  document.getElementById('kz-ng-name').value='';
  document.getElementById('kz-ng-inp').value='';
  document.getElementById('kz-ng-members').innerHTML='';
  document.getElementById('kz-ng-list').innerHTML='<div style="text-align:center;padding:24px;color:var(--sub-text);font-size:13px">Search to add members</div>';
  bd.style.display='block';
  modal.style.display='block';
  requestAnimationFrame(function(){modal.style.opacity='1';modal.style.transform='translate(-50%,-50%) scale(1)';});
};

window.kzNewGroupClose=function(){
  var modal=document.getElementById('kz-ng-modal');
  var bd=document.getElementById('kz-ng-bd');
  if(modal){modal.style.opacity='0';modal.style.transform='translate(-50%,-50%) scale(.95)';}
  setTimeout(function(){if(modal)modal.style.display='none';if(bd)bd.style.display='none';},180);
};

window.kzNewGroupSearch=async function(q){
  var list=document.getElementById('kz-ng-list');if(!list)return;
  q=(q||'').trim();
  if(q.length<2){list.innerHTML='<div style="text-align:center;padding:24px;color:var(--sub-text);font-size:13px">Type at least 2 characters</div>';return;}
  try{
    var r=await _sb.from('profiles').select('id,name,username,avatar_url').or('name.ilike.%'+q+'%,username.ilike.%'+q+'%').neq('id',sbUser.id).limit(20);
    var users=r.data||[];
    list.innerHTML=users.map(function(u){
      var sel=_kzGroupMembers.some(function(m){return m.id===u.id;});
      var av=u.avatar_url?'<img src="'+u.avatar_url+'" style="width:38px;height:38px;border-radius:50%;object-fit:cover;flex-shrink:0">':'<div style="width:38px;height:38px;border-radius:50%;background:linear-gradient(135deg,#FF8A00,#FFB800);display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:700;color:#090B12;flex-shrink:0">'+(u.name||'?').charAt(0).toUpperCase()+'</div>';
      return'<div onclick="kzGroupToggleMember('+JSON.stringify(u)+')" style="display:flex;align-items:center;gap:10px;padding:9px 16px;cursor:pointer;transition:background .12s;background:'+(sel?'rgba(255,138,0,.08)':'')+'">'+av+'<div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:600;color:var(--text)">'+(u.name||'Rizer')+'</div><div style="font-size:11px;color:var(--sub-text)">@'+(u.username||'')+'</div></div><div style="width:20px;height:20px;border-radius:50%;border:2px solid '+(sel?'#FF8A00':'var(--border)')+';background:'+(sel?'#FF8A00':'transparent')+';display:flex;align-items:center;justify-content:center;flex-shrink:0">'+(sel?'<svg viewBox="0 0 24 24" style="width:12px;height:12px;fill:#fff"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41L9 16.17z"/></svg>':'')+'</div></div>';
    }).join('');
  }catch(e){}
};

window.kzGroupToggleMember=function(u){
  var idx=_kzGroupMembers.findIndex(function(m){return m.id===u.id;});
  if(idx>-1)_kzGroupMembers.splice(idx,1);else _kzGroupMembers.push(u);
  // Re-render chips
  var chips=document.getElementById('kz-ng-members');
  if(chips)chips.innerHTML=_kzGroupMembers.map(function(m){
    return'<span style="display:inline-flex;align-items:center;gap:4px;background:rgba(255,138,0,.12);border:1px solid #FF8A00;border-radius:20px;padding:3px 8px 3px 4px;font-size:12px;color:var(--text)">'+(m.avatar_url?'<img src="'+m.avatar_url+'" style="width:18px;height:18px;border-radius:50%;object-fit:cover">':'<span style="width:18px;height:18px;border-radius:50%;background:#FF8A00;display:inline-flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;color:#fff">'+(m.name||'?').charAt(0).toUpperCase()+'</span>')+(m.name||'Rizer')+'<span onclick="kzGroupToggleMember('+JSON.stringify(m)+')" style="cursor:pointer;opacity:.6;margin-left:2px;line-height:1">✕</span></span>';
  }).join('');
  // Re-render search results to update checkmarks
  kzNewGroupSearch(document.getElementById('kz-ng-inp')?.value||'');
};

window.kzNewGroupCreate=async function(){
  var nameEl=document.getElementById('kz-ng-name');
  var name=(nameEl?.value||'').trim();
  if(!name){if(typeof cmToast==='function')cmToast('Group name dao');return;}
  if(_kzGroupMembers.length<1){if(typeof cmToast==='function')cmToast('Minimum 1 member add koro');return;}
  var memberIds=[sbUser.id].concat(_kzGroupMembers.map(function(m){return m.id;}));
  try{
    var r=await _sb.from('knokz_groups').insert({name:name,members:memberIds,created_by:sbUser.id}).select().single();
    if(r.error)throw r.error;
    var group=r.data;
    // Send welcome message
    await _sb.from('knokz_messages').insert({conversation_id:'grp_'+group.id,sender_id:sbUser.id,receiver_id:null,content:'👥 Group "'+name+'" created!',group_id:group.id});
    kzNewGroupClose();
    await _kzLoadConvs();
    kzOpenGroup(group);
  }catch(e){if(typeof cmToast==='function')cmToast('Group create হয়নি! Supabase-এ knokz_groups table create koro.');}
};

window.kzOpenGroup=async function(group){
  if(!window.sbUser||typeof _sb==='undefined')return;
  _kzIsGroup=true;
  _kzActiveGroup=group;
  _cid='grp_'+group.id;
  _uid=null;
  window._kzActiveCid=_cid;window._kzActiveUid=null;
  // Hide bottom nav on mobile
  if(window.innerWidth<768){var bn=document.querySelector('.rz-bottomnav');if(bn)bn.style.display='none';_kzH();}
  var root=document.getElementById('kz-root');if(root)root.classList.add('chat-open');
  // Set header
  var hname=document.getElementById('kz-hname');if(hname)hname.textContent=group.name;
  var hsub=document.getElementById('kz-hsub');if(hsub){var st=document.getElementById('kz-status');if(st)st.textContent=(group.members||[]).length+' members';}
  var hav=document.getElementById('kz-hav');
  if(hav)hav.innerHTML='<div style="width:100%;height:100%;background:linear-gradient(135deg,#FF8A00,#FFB800);display:flex;align-items:center;justify-content:center;font-size:18px;font-weight:700;color:#090B12">👥</div>';
  // Mark selected
  document.querySelectorAll('.kzci').forEach(function(e){e.classList.remove('sel');});
  var ci=document.getElementById('kzc-grp_'+group.id);if(ci)ci.classList.add('sel');
  // Load messages
  _kzMsgOffset=0;_kzMsgHasMore=false;
  var el=document.getElementById('kz-msgs');if(el)el.innerHTML='<div style="text-align:center;padding:24px;color:var(--sub-text);font-size:13px">Loading...</div>';
  try{
    var r=await _sb.from('knokz_messages').select('id,conversation_id,sender_id,sent_at,content,deleted_at,voice_listened_at,read_at').eq('conversation_id',_cid).order('sent_at',{ascending:false}).limit(51);
    var data=(r.data||[]).reverse();
    _kzMsgHasMore=r.data&&r.data.length>50;
    if(_kzMsgHasMore)data=data.slice(1);
    _kzMsgOffset=data.length;
    // Fetch sender profiles for group
    var sids=[...new Set(data.map(function(m){return m.sender_id;}).filter(function(id){return id&&!_prof[id];}))];
    if(sids.length){var pr=await _sb.from('profiles').select('id,name,avatar_url,last_seen').in('id',sids);(pr.data||[]).forEach(function(p){_prof[p.id]=p;});}
    _kzRenderGroup(data,group);
  }catch(e){if(el)el.innerHTML='<div style="padding:20px;text-align:center;color:var(--sub-text)">Load হয়নি।</div>';}
  // Realtime
  _kzStopRT();
  _kzSub=_sb.channel('kz-'+_cid)
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'knokz_messages',filter:'conversation_id=eq.'+_cid},function(pl){
      var m=pl.new;if(!m||m.sender_id===sbUser.id)return;
      if(!_prof[m.sender_id])_sb.from('profiles').select('id,name,avatar_url,last_seen').eq('id',m.sender_id).single().then(function(r){if(r.data)_prof[r.data.id]=r.data;_kzAppendGroup(m,group);});
      else _kzAppendGroup(m,group);
      _kzLoadConvs();
    }).subscribe();
  _kzInitEmoji();
};

function _kzGroupMsgHTML(m,group){
  var sent=m.sender_id===sbUser.id;
  var deleted=!!m.deleted_at;
  var t=new Date(m.sent_at||Date.now()).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
  var isImg=!deleted&&typeof m.content==='string'&&m.content.indexOf('[img]')==0;
  var isAudio=!deleted&&typeof m.content==='string'&&m.content.indexOf('[audio]')==0;
  var contentHTML=deleted?'<span style="font-style:italic;opacity:.55">🚫 Message deleted</span>':isImg?'<img src="'+m.content.slice(5)+'" style="max-width:220px;max-height:200px;border-radius:10px;display:block;cursor:pointer" onclick="window.open(this.src)">':isAudio?_kzVoiceHTML(_kzParseAudio(m.content.slice(7)),sent,m.id||(m.sent_at||'').replace(/\D/g,''),null):_kzEsc(m.content).replace(/\n/g,'<br>');
  var bs=(isImg?'padding:6px;':isAudio?'padding:8px 10px;':'padding:9px 14px;')+'border-radius:18px;font-size:14px;line-height:1.45;word-break:break-word;'+(sent?'background:#FF8A00;color:#fff;border-bottom-right-radius:4px':'background:var(--card);color:var(--text);border-bottom-left-radius:4px;border:1px solid var(--border)');
  var senderName='';
  if(!sent){var sp=_prof[m.sender_id]||{};senderName='<div style="font-size:11px;font-weight:600;color:#FF8A00;margin-bottom:2px">'+(sp.name||'Rizer')+'</div>';}
  var tickHTML=sent?(!m.id?_kzTickSVG(1,false):m.read_at?_kzTickSVG(2,true):_kzTickSVG(2,false)):'';
  return'<div class="kz-msg" data-id="'+(m.id||'')+'" data-sent="'+sent+'" style="display:flex;flex-direction:column;max-width:72%;'+(sent?'align-self:flex-end;align-items:flex-end':'align-self:flex-start;align-items:flex-start')+'">'+senderName+
    '<div class="kz-msg-wrap"><div class="kz-bubble" style="'+bs+'">'+contentHTML+'</div></div>'+
    '<div style="font-size:10px;color:var(--sub-text);margin-top:2px;padding:0 2px;display:flex;align-items:center;gap:2px">'+t+tickHTML+'</div>'+
  '</div>';
}

function _kzRenderGroup(msgs,group){
  var el=document.getElementById('kz-msgs');if(!el)return;
  if(!msgs.length){el.innerHTML='<div style="text-align:center;padding:52px 20px"><div style="font-size:36px;margin-bottom:8px">👥</div><div style="font-size:13px;color:var(--sub-text)">Group created! Say something.</div></div>';return;}
  var html='',ld='';
  msgs.forEach(function(m){
    var d=new Date(m.sent_at),ds=d.toDateString();
    if(ds!==ld){ld=ds;var now=new Date();var lbl=d.toDateString()===now.toDateString()?'Today':d.toLocaleDateString([],{weekday:'short',month:'short',day:'numeric'});html+='<div style="text-align:center;margin:8px 0 4px"><span style="font-size:11px;color:var(--sub-text);background:var(--card);padding:3px 12px;border-radius:20px;border:1px solid var(--border)">'+lbl+'</span></div>';}
    html+=_kzGroupMsgHTML(m,group);
  });
  el.innerHTML=html;el.scrollTop=el.scrollHeight;
  _kzAttachMsgEvents(el);
}

function _kzAppendGroup(m,group){
  var el=document.getElementById('kz-msgs');if(!el)return;
  if(el.querySelector('[style*="Say something"]')||el.querySelector('[style*="Loading"]'))el.innerHTML='';
  var tmp=document.createElement('div');
  tmp.innerHTML=_kzGroupMsgHTML(m,group);
  el.appendChild(tmp.firstChild);
  el.scrollTop=el.scrollHeight;
  _kzAttachMsgEvents(el);
}


