var _rzSharePostId = null;
var _rzSsAudience = 'everyone';

function rzShareOpen(postId) {
  _rzSharePostId = postId || null;
  var bd = document.getElementById('rz-share-bd');
  var sh = document.getElementById('rz-share-sheet');
  if(!bd||!sh) return;

  // Populate real user data
  var p = window.sbProfile;
  var av = document.getElementById('rz-ss-av');
  var nameEl = document.getElementById('rz-ss-uname');
  if(p) {
    var ini = (p.name||'R').charAt(0).toUpperCase();
    if(av) {
      if(p.avatar_url) {
        av.style.backgroundImage = 'url('+p.avatar_url+')';
        av.style.backgroundSize = 'cover';
        av.style.backgroundPosition = 'center';
        av.textContent = '';
      } else {
        av.style.backgroundImage = '';
        av.textContent = ini;
      }
    }
    if(nameEl) nameEl.textContent = p.name || 'Rizer';
  } else {
    if(av) { av.style.backgroundImage=''; av.textContent='R'; }
    if(nameEl) nameEl.textContent = 'তোমার নাম';
  }

  // Reset caption & audience
  var cap = document.getElementById('rz-ss-caption');
  if(cap) cap.value = '';
  _rzSsAudience = 'everyone';
  rzSsAudRender();

  // Load real contacts
  rzSsLoadContacts();

  bd.style.display='block';
  requestAnimationFrame(function(){ sh.classList.add('open'); });
}

function rzShareClose() {
  var bd = document.getElementById('rz-share-bd');
  var sh = document.getElementById('rz-share-sheet');
  if(!sh) return;
  sh.classList.remove('open');
  setTimeout(function(){ if(bd) bd.style.display='none'; }, 320);
}

var _rzAudLabels = {everyone:'Everyone', custom:'Custom', only_me:'Only Me'};
function rzSsAudRender() {
  var lbl = document.getElementById('rz-ss-aud-label');
  if(lbl) lbl.textContent = _rzAudLabels[_rzSsAudience] || 'Everyone';
  ['everyone','custom','only_me'].forEach(function(k){
    var chk = document.getElementById('rz-ss-aud-chk-'+k);
    if(chk) chk.style.display = k===_rzSsAudience ? 'inline' : 'none';
  });
}
function rzSsAudToggle() {
  var pop = document.getElementById('rz-ss-aud-pop');
  if(!pop) return;
  pop.style.display = pop.style.display==='block' ? 'none' : 'block';
}
function rzSsAudPick(val) {
  _rzSsAudience = val;
  rzSsAudRender();
  var pop = document.getElementById('rz-ss-aud-pop');
  if(pop) pop.style.display='none';
}

async function rzSsLoadContacts() {
  var el = document.getElementById('rz-ss-contacts');
  if(!el) return;
  var colors = ['#6366f1','#10b981','#ef4444','#3b82f6','#f59e0b','#8b5cf6'];
  try {
    if(typeof _sb === 'undefined') throw new Error('no sb');
    var myId = window.sbUser ? window.sbUser.id : null;
    var q = _sb.from('profiles').select('id,name,avatar_url').limit(6);
    if(myId) q = q.neq('id', myId);
    var { data } = await q;
    if(!data || !data.length) throw new Error('no data');
    var html = '';
    // Self first
    var p = window.sbProfile;
    if(p) {
      var selfIni = (p.name||'R').charAt(0).toUpperCase();
      var selfBg = p.avatar_url
        ? 'background-image:url('+p.avatar_url+');background-size:cover;background-position:center;color:transparent'
        : 'background:linear-gradient(135deg,#FF8A00,#FFB800)';
      html += '<div class="rz-ss-contact" onclick="rzShareKnokz(\'self\')">'
        +'<div class="rz-ss-cav" style="'+selfBg+'">'+selfIni+'</div>'
        +'<div class="rz-ss-cname">You</div></div>';
    }
    data.forEach(function(u,i){
      var ini = (u.name||'?').charAt(0).toUpperCase();
      var bg = u.avatar_url
        ? 'background-image:url('+u.avatar_url+');background-size:cover;background-position:center;color:transparent'
        : 'background:'+colors[i%colors.length];
      html += '<div class="rz-ss-contact" onclick="rzShareKnokz(\''+u.id+'\')">'
        +'<div class="rz-ss-cav" style="'+bg+'">'+ini+'</div>'
        +'<div class="rz-ss-cname">'+((u.name||'').split(' ')[0]||'User')+'</div></div>';
    });
    // More button
    html += '<div class="rz-ss-contact" onclick="rzShareKnokz(\'more\')">'
      +'<div class="rz-ss-cav" style="background:#334155;font-size:18px">+</div>'
      +'<div class="rz-ss-cname">আরো</div></div>';
    el.innerHTML = html;
  } catch(e) {
    // Fallback demo contacts
    el.innerHTML = ''
      +'<div class="rz-ss-contact" onclick="rzShareKnokz(\'self\')">'
      +'<div class="rz-ss-cav" style="background:linear-gradient(135deg,#FF8A00,#FFB800)">'+(window.sbProfile?(window.sbProfile.name||'R').charAt(0).toUpperCase():'R')+'</div>'
      +'<div class="rz-ss-cname">You</div></div>'
      +'<div class="rz-ss-contact" onclick="rzShareKnokz(\'more\')">'
      +'<div class="rz-ss-cav" style="background:#334155;font-size:18px">+</div>'
      +'<div class="rz-ss-cname">আরো</div></div>';
  }
}

