var duaFilter = 'all';
var duaLearnedSet = new Set([2,8]);
duaData.forEach(function(d){if(duaLearnedSet.has(d.id))d.learned=true;});

function getDuaCardHTML(d,i) {
  var done = d.learned;
  return '\x3Cdiv class="dua-card'+(done?' expanded':'')+'" id="dua-card-'+i+'" onclick="openDua('+i+')"\x3E'
    +'\x3Cbutton class="learned-btn'+(done?' done':'')+'" onclick="event.stopPropagation();toggleLearned('+i+')" title="মুখস্থ হয়েছে"\x3E'+(done?'✓':'○')+'\x3C/button\x3E'
    +'\x3Cdiv style="display:flex;align-items:center;gap:10px;padding-right:40px"\x3E'
      +'\x3Cdiv style="width:36px;height:36px;border-radius:10px;background:'+(done?'#f0f9f4':'#f9fafb')+';border:1px solid '+(done?'#c8e6c9':'#f0f0f0')+';display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0"\x3E'
        +(d.cat==='daily'?'☀️':d.cat==='emergency'?'🆘':'🌙')
      +'\x3C/div\x3E'
      +'\x3Cdiv\x3E'
        +'\x3Cdiv style="font-size:14px;font-weight:700;color:#1a1a2e"\x3E'+d.title+'\x3C/div\x3E'
        +'\x3Cdiv style="font-size:12px;color:#888;margin-top:2px;direction:rtl;font-family:serif"\x3E'+d.arabic.substring(0,30)+'...\x3C/div\x3E'
      +'\x3C/div\x3E'
    +'\x3C/div\x3E'
  +'\x3C/div\x3E';
}

function getDuaDetailHTML(d,i) {
  return '\x3Cdiv style="margin-bottom:16px"\x3E'
    +'\x3Cdiv style="display:flex;align-items:center;gap:10px;margin-bottom:16px"\x3E'
      +'\x3Cdiv style="width:40px;height:40px;border-radius:12px;background:#f0f9f4;border:1px solid #c8e6c9;display:flex;align-items:center;justify-content:center;font-size:22px"\x3E'+(d.cat==='daily'?'☀️':d.cat==='emergency'?'🆘':'🌙')+'\x3C/div\x3E'
      +'\x3Cdiv\x3E\x3Cdiv style="font-size:17px;font-weight:700;color:#1a1a2e"\x3E'+d.title+'\x3C/div\x3E'
      +'\x3Cdiv style="font-size:11px;color:#1a6b3c;font-weight:600;margin-top:2px"\x3E'+(d.cat==='daily'?'দৈনিক দোয়া':d.cat==='emergency'?'Emergency দোয়া':'বিশেষ দোয়া')+'\x3C/div\x3E\x3C/div\x3E'
    +'\x3C/div\x3E'
    +'\x3Cdiv class="dua-arabic"\x3E'+d.arabic+'\x3C/div\x3E'
    +'\x3Cdiv class="dua-pron"\x3Eউচ্চারণ: '+d.pron+'\x3C/div\x3E'
    +'\x3Cdiv class="dua-bn"\x3E'+d.meaning+'\x3C/div\x3E'
    +'\x3Cbutton onclick="toggleLearned('+i+')" id="detail-learn-btn-'+i+'" style="width:100%;margin-top:14px;padding:12px;border-radius:12px;border:none;background:'+(d.learned?'#dcfce7':'#1a6b3c')+';color:'+(d.learned?'#16a34a':'#fff')+';font-size:14px;font-weight:700;cursor:pointer;font-family:inherit"\x3E'
      +(d.learned?'✅ মুখস্থ হয়েছে':'✓ মুখস্থ করেছি — Mark করো')
    +'\x3C/button\x3E'
  +'\x3C/div\x3E';
}

function renderDuas() {
  var container = document.getElementById('dua-container');
  if(!container) return;
  var filtered = duaFilter==='all' ? duaData : duaData.filter(function(d){return d.cat===duaFilter;});
  container.innerHTML = filtered.map(function(d,i){return getDuaCardHTML(d,duaData.indexOf(d));}).join('');
  updateDuaProgress();
}

function filterDua(cat) {
  duaFilter = cat;
  document.querySelectorAll('.dua-tab').forEach(function(t){t.classList.remove('active');});
  event.target.classList.add('active');
  renderDuas();
}

function openDua(i) {
  var d = duaData[i];
  var modal = document.getElementById('dua-modal');
  var content = document.getElementById('dua-modal-content');
  if(modal && content) {
    content.innerHTML = getDuaDetailHTML(d,i);
    modal.style.display = 'block';
    document.body.style.overflow = 'hidden';
  }
}

function closeDuaModal() {
  var modal = document.getElementById('dua-modal');
  if(modal) { modal.style.display='none'; document.body.style.overflow=''; }
}

function toggleLearned(i) {
  duaData[i].learned = !duaData[i].learned;
  var btn = document.getElementById('dua-card-'+i)?.querySelector('.learned-btn');
  if(btn) {
    btn.textContent = duaData[i].learned ? '✓' : '○';
    btn.classList.toggle('done', duaData[i].learned);
  }
  // Update detail button if open
  var detBtn = document.getElementById('detail-learn-btn-'+i);
  if(detBtn) {
    detBtn.style.background = duaData[i].learned ? '#dcfce7' : '#1a6b3c';
    detBtn.style.color = duaData[i].learned ? '#16a34a' : '#fff';
    detBtn.textContent = duaData[i].learned ? '✅ মুখস্থ হয়েছে' : '✓ মুখস্থ করেছি — Mark করো';
  }
  updateDuaProgress();
  renderDuas();
  if(document.getElementById('dua-modal').style.display === 'block') openDua(i);
}

function updateDuaProgress() {
  var done = duaData.filter(function(d){return d.learned;}).length;
  var total = duaData.length;
  var pct = Math.round(done/total*100);
  var c = document.getElementById('dua-learned-count');
  var b = document.getElementById('dua-progress-bar');
  if(c) c.textContent = done+'/'+total;
  if(b) b.style.width = pct+'%';
}

var _dpOrig = window.showPage;
window.showPage = function(page) {
  _dpOrig(page);
  if(page==='dua') setTimeout(function(){renderDuas();}, 50);
};

