function stMakeToggle(id,on){
  var bg=on?'#FF8A00':'#e5e7eb';
  var lft=on?'26px':'3px';
  return '<div onclick="stToggleNotif(\''+id+'\')" id="st-ntog-'+id+'" style="width:50px;height:27px;border-radius:50px;background:'+bg+';cursor:pointer;position:relative;transition:.3s;flex-shrink:0"><div id="st-nknob-'+id+'" style="width:21px;height:21px;border-radius:50%;background:#fff;position:absolute;top:3px;left:'+lft+';transition:.3s;box-shadow:0 1px 4px rgba(0,0,0,.25)"></div></div>';
}

function stToggleNotif(id){
  stNotifStates[id]=!stNotifStates[id];
  var on=stNotifStates[id];
  localStorage.setItem('notif_'+id, on?'1':'0');
  var tog=document.getElementById('st-ntog-'+id);
  var knob=document.getElementById('st-nknob-'+id);
  if(tog)tog.style.background=on?'#FF8A00':'#e5e7eb';
  if(knob)knob.style.left=on?'26px':'3px';
}

function stMakeRow(iconKey,label,sub,action,toggle,isLast){
  var svgHtml=_stIcons[iconKey]||iconKey;
  var chevron=action?'<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--text-muted,#ccc)" stroke-width="2" aria-hidden="true"><path d="M9 18l6-6-6-6"/></svg>':'';
  var border=isLast?'':'border-bottom:1px solid var(--border,#f5f5f5);';
  var cursor=action?'cursor:pointer;':'';
  var onclick=action?'onclick="('+action.toString()+')()"':'';
  return '<div '+onclick+' style="display:flex;align-items:center;gap:12px;padding:14px 18px;'+border+cursor+'">'+
    _stIconWrap(svgHtml)+
    '<div style="flex:1;min-width:0"><div style="font-size:14px;font-weight:600;color:var(--text,#1a1a2e)">'+label+'</div>'+(sub?'<div style="font-size:11px;color:var(--text-muted,#888);margin-top:1px">'+sub+'</div>':'')+'</div>'+
    (toggle||chevron)+
    '</div>';
}

function stRenderNotifRows(){
  var el=document.getElementById('st-notif-rows');if(!el)return;
  el.innerHTML=stNotifConfig.map(function(c,i){
    return stMakeRow(c.icon,c.label,c.sub,null,stMakeToggle(c.id,stNotifStates[c.id]),i===stNotifConfig.length-1);
  }).join('');
}

function stRenderAccountRows(){
  var el=document.getElementById('st-account-rows');if(!el)return;
  el.innerHTML=stAccountConfig.map(function(c,i){
    return stMakeRow(c.icon,c.label,c.sub,c.action,null,i===stAccountConfig.length-1);
  }).join('');
}

function stRenderAboutRows(){
  var el=document.getElementById('st-about-rows');if(!el)return;
  el.innerHTML=stAboutConfig.map(function(c,i){
    return stMakeRow(c.icon,c.label,c.sub,c.action||null,null,i===stAboutConfig.length-1);
  }).join('');
}

function stToggleProfileForm(){
  var f=document.getElementById('st-profile-form');
  if(!f)return;
  f.style.display=f.style.display==='none'?'block':'none';
}

async function stSaveProfile(){
  var nm=document.getElementById('st-inp-name');
  var name=nm&&nm.value.trim()?nm.value.trim():'';
  var restrictMsg=document.getElementById('st-name-restrict-msg');

  var currentName=(window.sbProfile&&window.sbProfile.name)||'';
  if(name&&name!==currentName){
    /* 7-day name change restriction — only if name actually changed */
    var lastChanged=localStorage.getItem('_rz_name_changed_at');
    var now=Date.now();
    var sevenDays=7*24*60*60*1000;
    if(lastChanged&&(now-parseInt(lastChanged,10))<sevenDays){
      var daysLeft=Math.ceil((sevenDays-(now-parseInt(lastChanged,10)))/(24*60*60*1000));
      if(restrictMsg){restrictMsg.style.display='block';restrictMsg.textContent='নাম পরিবর্তন করা যাবে না — আরো '+daysLeft+' দিন পরে আবার চেষ্টা করো।';}
      return;
    }
    /* Save name to Supabase */
    if(typeof _sb!=='undefined'&&sbUser){
      await _sb.from('profiles').update({name:name}).eq('id',sbUser.id);
      localStorage.setItem('_rz_name_changed_at',String(now));
    }
    var nd=document.getElementById('st-name');if(nd)nd.textContent=name;
    var av=document.getElementById('st-avatar');if(av&&!av.querySelector('img'))av.textContent=name.charAt(0).toUpperCase();
    if(typeof sbProfile!=='undefined'&&sbProfile)sbProfile.name=name;
    if(restrictMsg)restrictMsg.style.display='none';
  } else {
    if(restrictMsg)restrictMsg.style.display='none';
  }

  /* Username change — weekly restriction */
  var uninp=document.getElementById('st-inp-uname');
  var newUname=uninp&&uninp.value.trim().toLowerCase().replace(/[^a-z0-9_.]/g,'');
  if(newUname&&newUname!==(window.sbProfile&&window.sbProfile.username)){
    var lastUC=localStorage.getItem('_rz_uname_changed_at');
    var nowU=Date.now();
    if(lastUC&&(nowU-parseInt(lastUC,10))<7*24*60*60*1000){
      var uDL=Math.ceil((7*24*60*60*1000-(nowU-parseInt(lastUC,10)))/(24*60*60*1000));
      var uStat=document.getElementById('st-uname-status');
      if(uStat){uStat.style.color='#EF4444';uStat.textContent='Username আরো '+uDL+' দিন পরে পরিবর্তন করা যাবে।';}
    } else if(typeof _sb!=='undefined'&&sbUser){
      /* Check uniqueness */
      var uChk=await _sb.from('profiles').select('id').eq('username',newUname).neq('id',sbUser.id);
      if(uChk.data&&uChk.data.length>0){
        var uStat2=document.getElementById('st-uname-status');
        if(uStat2){uStat2.style.color='#EF4444';uStat2.textContent='এই username টি আগেই নেওয়া হয়েছে।';}
      } else {
        await _sb.from('profiles').update({username:newUname}).eq('id',sbUser.id);
        localStorage.setItem('_rz_uname_changed_at',String(nowU));
        if(window.sbProfile)window.sbProfile.username=newUname;
      }
    }
  }

  stToggleProfileForm();
  var msg=document.createElement('div');
  msg.style.cssText='position:fixed;bottom:100px;left:50%;transform:translateX(-50%);background:#10B981;color:#fff;padding:10px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 12px rgba(0,0,0,.15)';
  msg.textContent='Profile save হয়েছে!';
  document.body.appendChild(msg);
  setTimeout(function(){msg.remove();},2500);
}

function stSyncDarkUI(){
  var dark=typeof isDark!=='undefined'?isDark:document.body.classList.contains('dark-mode');
  var tog=document.getElementById('dm-toggle');
  var knob=document.getElementById('dm-knob');
  var label=document.getElementById('st-dm-label');
  if(tog)tog.style.background=dark?'#FF8A00':'#e5e7eb';
  if(knob)knob.style.left=dark?'26px':'3px';
  if(label)label.textContent=dark?'চালু আছে':'বন্ধ আছে';
}

function stSyncLangUI(){
  var lang=typeof currentLang!=='undefined'?currentLang:(localStorage.getItem('lang')||'bn');
  var lbl=document.getElementById('lang-label');
  var bn=document.getElementById('lang-bn');
  var en=document.getElementById('lang-en');
  if(lbl)lbl.textContent=lang==='bn'?'বাংলা':'English';
  if(bn){bn.style.background=lang==='bn'?'#FF8A00':'var(--card,#fff)';bn.style.color=lang==='bn'?'#fff':'var(--text-muted,#888)';bn.style.borderColor=lang==='bn'?'#FF8A00':'var(--border,#e5e7eb)';}
  if(en){en.style.background=lang==='en'?'#FF8A00':'var(--card,#fff)';en.style.color=lang==='en'?'#fff':'var(--text-muted,#888)';en.style.borderColor=lang==='en'?'#FF8A00':'var(--border,#e5e7eb)';}
}

function stRenderKids(){
  var el=document.getElementById('st-kids-list');if(!el)return;
  var kids=[];
  try{kids=JSON.parse(localStorage.getItem('_rz_kids')||'[]');}catch(e){}
  if(!kids.length){
    el.innerHTML='<div style="text-align:center;padding:16px;color:var(--text-muted,#aaa);font-size:12px">এখনো কোনো kid profile নেই। Add করো!</div>';
    return;
  }
  var cols=['#FF8A00','#8B5CF6','#3B82F6','#10B981','#EF4444'];
  el.innerHTML=kids.map(function(k,i){
    var c=cols[i%cols.length];
    return '<div style="display:flex;align-items:center;gap:10px;padding:10px 4px;border-bottom:1px solid var(--border,#f5f5f5)">'+
      '<div style="width:36px;height:36px;border-radius:50%;background:'+c+';display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:700;color:#fff;flex-shrink:0">'+(k.name||'?').charAt(0).toUpperCase()+'</div>'+
      '<div style="flex:1"><div style="font-size:13px;font-weight:600;color:var(--text,#1a1a2e)">'+(k.name||'Kid'+(i+1))+'</div><div style="font-size:11px;color:var(--text-muted,#888)">'+(k.age?k.age+' বছর':'')+'</div></div>'+
      '<button onclick="showPage(\'kids\')" style="font-size:11px;color:#FF8A00;background:none;border:none;cursor:pointer;font-weight:600;font-family:inherit">Edit</button>'+
      '</div>';
  }).join('');
}

function stRenderSubscription(){
  var prof=window.sbProfile||{};
  if(typeof _rzSyncExpiredDailyReys==='function') _rzSyncExpiredDailyReys();
  var bal=document.getElementById('st-reys-bal');
  var total=typeof rzEffectiveTotalReys==='function' ? rzEffectiveTotalReys(prof) : (prof.reys_balance||0);
  if(bal)bal.textContent=total.toLocaleString('bn-BD')+' Reys';
}

function stReysTab(tab){
  var balBtn=document.getElementById('st-reys-tab-balance'), histBtn=document.getElementById('st-reys-tab-history');
  var balView=document.getElementById('st-reys-view-balance'), histView=document.getElementById('st-reys-view-history');
  if(!balBtn||!histBtn||!balView||!histView)return;
  var isHist=tab==='history';
  balBtn.style.background=isHist?'transparent':'rgba(255,138,0,.16)';
  balBtn.style.color=isHist?'var(--text-muted,#888)':'#FF8A00';
  histBtn.style.background=isHist?'rgba(255,138,0,.16)':'transparent';
  histBtn.style.color=isHist?'#FF8A00':'var(--text-muted,#888)';
  balView.style.display=isHist?'none':'flex';
  histView.style.display=isHist?'block':'none';
  if(isHist) stRenderReysHistory();
}

var _stReysHistoryIcons={daily_claim:'🎁',purchase:'💳',challenge_join:'🎯'};
async function stRenderReysHistory(){
  var el=document.getElementById('st-reys-history-list');
  if(!el||!sbUser)return;
  el.innerHTML='<div style="text-align:center;padding:26px 0;color:var(--text-muted,#999);font-size:12.5px">লোড হচ্ছে...</div>';
  try{
    var r=await _sb.from('reys_transactions').select('*').eq('user_id',sbUser.id).order('created_at',{ascending:false}).limit(50);
    if(r.error){
      el.innerHTML='<div style="text-align:center;padding:26px 0;color:var(--text-muted,#999);font-size:12.5px">লোড করা যায়নি</div>';
      return;
    }
    if(!r.data||!r.data.length){
      el.innerHTML='<div style="text-align:center;padding:26px 0;color:var(--text-muted,#999);font-size:12.5px">এখনো কোনো Reys history নেই</div>';
      return;
    }
    el.innerHTML=r.data.map(function(t){
      var pos=t.amount>0;
      return '<div style="display:flex;align-items:center;gap:10px;padding:9px 6px;border-bottom:1px solid rgba(255,138,0,.08)">'
        +'<div style="width:34px;height:34px;border-radius:10px;background:rgba(255,138,0,.08);display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0">'+(_stReysHistoryIcons[t.type]||'🪙')+'</div>'
        +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:12.5px;font-weight:600;color:var(--text,#1a1a2e);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escapeHtml(t.description||'')+'</div>'
        +'<div style="font-size:10.5px;color:var(--text-muted,#999);margin-top:1px">'+cmTimeAgo(t.created_at)+'</div>'
        +'</div>'
        +'<div style="font-size:13.5px;font-weight:800;color:'+(pos?'#10B981':'#EF4444')+';flex-shrink:0;white-space:nowrap">'+(pos?'+':'')+t.amount+'</div>'
        +'</div>';
    }).join('');
  }catch(e){
    el.innerHTML='<div style="text-align:center;padding:26px 0;color:var(--text-muted,#999);font-size:12.5px">লোড করা যায়নি</div>';
  }
}

function stLoadProfile(){
  // load notification states from localStorage
  stNotifConfig.forEach(function(c){
    var saved=localStorage.getItem('notif_'+c.id);
    stNotifStates[c.id]=saved===null?stNotifDefaults[c.id]:saved==='1';
  });

  // profile — retry if sbProfile not ready yet
  var _stPr=window.sbProfile;
  var _stU=window.sbUser;
  if(!_stPr){setTimeout(stLoadProfile,400);return;}

  var nd=document.getElementById('st-name');if(nd)nd.textContent=_stPr.name||'';
  var av=document.getElementById('st-avatar');
  if(av&&_stPr.name&&!av.querySelector('img'))av.textContent=_stPr.name.charAt(0).toUpperCase();
  /* Show actual phone number, not the fake email */
  var _stPhone='';
  if(_stU&&_stU.email){
    var _em=_stU.email.match(/^p(\d+)@/);
    if(_em){var _d=_em[1];if(_d.startsWith('880'))_d='0'+_d.slice(3);_stPhone=_d;}
  }
  if(!_stPhone&&_stU)_stPhone=_stU.phone||'';
  var em=document.getElementById('st-email');
  if(em)em.textContent=_stPhone||(_stU&&_stU.email?_stU.email:'');
  /* Name input */
  var inp=document.getElementById('st-inp-name');if(inp&&_stPr.name)inp.value=_stPr.name;
  /* Username input */
  var uinp=document.getElementById('st-inp-uname');
  if(uinp)uinp.value=_stPr.username||'';
  var uDaysEl=document.getElementById('st-uname-days-left');
  var lastUnameChanged=localStorage.getItem('_rz_uname_changed_at');
  if(lastUnameChanged&&uDaysEl){
    var uRem=Math.ceil((7*24*60*60*1000-(Date.now()-parseInt(lastUnameChanged,10)))/(24*60*60*1000));
    if(uRem>0){
      uDaysEl.textContent='('+uRem+' দিন পরে পরিবর্তন করা যাবে)';
      if(uinp){uinp.readOnly=true;uinp.style.background='var(--bg,#f5f5f5)';uinp.style.color='var(--text-muted,#999)';uinp.style.cursor='not-allowed';}
    } else {
      uDaysEl.textContent='';
      if(uinp){uinp.readOnly=false;uinp.style.background='';uinp.style.color='';uinp.style.cursor='';}
    }
  }
  /* 7-day restriction hint */
  var lastChanged=localStorage.getItem('_rz_name_changed_at');
  var daysLeftEl=document.getElementById('st-name-days-left');
  var saveBtn=document.getElementById('st-save-btn');
  if(lastChanged&&daysLeftEl){
    var rem=Math.ceil((7*24*60*60*1000-(Date.now()-parseInt(lastChanged,10)))/(24*60*60*1000));
    if(rem>0){
      daysLeftEl.textContent='('+rem+' দিন পরে পরিবর্তন করা যাবে)';
      if(inp){inp.readOnly=true;inp.style.background='var(--bg,#f5f5f5)';inp.style.color='var(--text-muted,#999)';inp.style.cursor='not-allowed';}
      if(saveBtn){saveBtn.style.opacity='0.5';saveBtn.style.cursor='not-allowed';}
    } else {
      if(daysLeftEl)daysLeftEl.textContent='';
      if(inp){inp.readOnly=false;inp.style.background='';inp.style.color='';inp.style.cursor='';}
      if(saveBtn){saveBtn.style.opacity='';saveBtn.style.cursor='';}
    }
  }
  /* Phone field */
  var ph=document.getElementById('st-inp-phone');
  if(ph)ph.value=_stPhone;
  /* Profession */
  var jb=document.getElementById('st-inp-job');
  if(jb)jb.value=_stPr.profession||_stPr.work||localStorage.getItem('_rz_job')||'';

  // reys balance
  var reys=parseInt(localStorage.getItem('ref_rzc')||'0',10);
  var rb=document.getElementById('st-reys-bal');if(rb)rb.textContent=reys.toLocaleString()+' Reys';

  // referral stats
  var refCount=parseInt(localStorage.getItem('ref_count')||'0',10);
  var rc=document.getElementById('st-ref-count');if(rc)rc.textContent=refCount+' জন';

  // subscription
  stRenderSubscription();

  // dark mode + language sync
  stSyncDarkUI();
  stSyncLangUI();

  // kids
  stRenderKids();

  // row sections
  stRenderNotifRows();
  stRenderAccountRows();
  stRenderAboutRows();
}

