function copyNumber() {
  navigator.clipboard.writeText('01XXXXXXXXX').then(function(){
    alert('Number copied! ✅');
  }).catch(function(){
    alert('01XXXXXXXXX — এই নম্বরে send করুন');
  });
}

// reys_balance is permanent (from approved purchases); daily_free_reys is
// today's free claim, only valid while last_reys_claim_date is still today
// — once the date rolls over, the stored value is treated as already spent
// (0) regardless of what's left in it, matching the 24-hour expiry rule.
function rzDailyFreeIsValid(prof){
  var today=new Date().toISOString().slice(0,10);
  return prof.last_reys_claim_date===today;
}
function rzEffectiveDailyFree(prof){
  return rzDailyFreeIsValid(prof) ? (prof.daily_free_reys||0) : 0;
}
function rzEffectiveTotalReys(prof){
  return (prof.reys_balance||0) + rzEffectiveDailyFree(prof);
}
// Self-heals a stale (expired but not yet zeroed) daily_free_reys on the
// server — no cron job needed, this just runs the next time anyone loads
// the page. Updates the in-memory profile synchronously so the caller's
// render pass is already correct even before the write resolves.
function _rzSyncExpiredDailyReys(){
  var prof=window.sbProfile;
  if(!prof || !window.sbUser) return;
  if(!rzDailyFreeIsValid(prof) && (prof.daily_free_reys||0)>0){
    prof.daily_free_reys=0;
    _sb.from('profiles').update({daily_free_reys:0}).eq('id',sbUser.id).then(function(){},function(){});
  }
}

function rzRenderSubscriptionPage(){
  var prof=window.sbProfile||{};
  _rzSyncExpiredDailyReys();
  var bal=document.getElementById('sub-reys-balance');
  if(bal)bal.textContent=rzEffectiveTotalReys(prof).toLocaleString('bn-BD');
  var breakdown=document.getElementById('sub-reys-breakdown');
  if(breakdown){
    var free=rzEffectiveDailyFree(prof);
    breakdown.textContent=(prof.reys_balance||0).toLocaleString('bn-BD')+' স্থায়ী + '+free.toLocaleString('bn-BD')+' আজকের ফ্রি (রাত ১২টায় শেষ হবে)';
  }
  var today=new Date().toISOString().slice(0,10);
  var claimed=prof.last_reys_claim_date===today;
  var claimCard=document.getElementById('sub-claim-card');
  var claimedCard=document.getElementById('sub-claimed-card');
  if(claimCard)claimCard.style.display=claimed?'none':'flex';
  if(claimedCard)claimedCard.style.display=claimed?'flex':'none';
  if(typeof rzCollapseReysBuy==='function') rzCollapseReysBuy();
}

// Custom "buy more Reys" purchases (no preset bonus) use this base rate,
// anchored to the smallest preset tier: ৳৩০ = ১,০০০ Reys.
var RZ_REYS_BASE_RATE = 1000/30;

function _rzClearTierHighlights(){
  document.querySelectorAll('.sub-tier-card').forEach(function(c){
    var featured = c.dataset.featured==='1';
    c.style.borderColor = featured ? '#FF8A00' : 'rgba(255,255,255,.12)';
    c.style.borderWidth = featured ? '2px' : '1.5px';
    c.style.boxShadow = featured ? '0 4px 16px rgba(255,138,0,.2)' : 'none';
    var check=c.querySelector('.sub-tier-check'); if(check) check.remove();
  });
}

// cardEl is the clicked preset card (for highlighting), or omitted for a custom amount.
function rzSelectReysTier(amount,reys,cardEl){
  window._subSelectedAmount=amount;
  window._subSelectedReys=reys;
  var summary=document.getElementById('sub-buy-summary');
  if(summary)summary.textContent='৳'+amount.toLocaleString('bn-BD')+' পাঠাচ্ছো → '+reys.toLocaleString('bn-BD')+' Reys পাবে';

  _rzClearTierHighlights();
  if(cardEl){
    // Deliberately blue, not orange — the "জনপ্রিয়" card is already permanently
    // orange-bordered, so a same-color selection ring was hard to tell apart
    // from that badge. Blue reads as "this is what you picked" either way.
    cardEl.style.borderColor='#3B82F6';
    cardEl.style.borderWidth='2px';
    cardEl.style.boxShadow='0 4px 14px rgba(59,130,246,.35)';
    var badge=document.createElement('div');
    badge.className='sub-tier-check';
    badge.style.cssText='position:absolute;top:-8px;left:8px;width:20px;height:20px;border-radius:50%;background:#3B82F6;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 8px rgba(59,130,246,.55);z-index:1';
    badge.innerHTML='<svg width="11" height="11" viewBox="0 0 12 12" fill="none"><path d="M2 6l3 3 5-5" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    cardEl.appendChild(badge);
  }

  // Below the still-visible cards, animate the bKash section open (or just update it if already open).
  var s2=document.getElementById('sub-buy-step2');
  if(s2){
    s2.style.maxHeight='1200px';
    s2.style.opacity='1';
    s2.style.marginTop='14px';
  }
}

function rzShowCustomReys(){
  var w=document.getElementById('sub-custom-wrap');
  var t=document.getElementById('sub-custom-toggle');
  if(w)w.style.display='block';
  if(t)t.style.display='none';
}

function rzCalcCustomReys(){
  var inp=document.getElementById('sub-custom-amount');
  var calc=document.getElementById('sub-custom-calc');
  var amt=parseFloat(inp.value)||0;
  var reys=Math.round(amt*RZ_REYS_BASE_RATE);
  if(calc)calc.textContent='= '+reys.toLocaleString('bn-BD')+' Reys পাবে';
}

function rzConfirmCustomReys(){
  var inp=document.getElementById('sub-custom-amount');
  var amt=parseFloat(inp.value)||0;
  if(amt<30){ alert('কমপক্ষে ৳৩০ লিখো'); return; }
  rzSelectReysTier(amt,Math.round(amt*RZ_REYS_BASE_RATE));
}

// Collapses the bKash section and clears any selection — cards + custom option stay visible throughout.
function rzCollapseReysBuy(){
  var s2=document.getElementById('sub-buy-step2');
  if(s2){ s2.style.maxHeight='0'; s2.style.opacity='0'; s2.style.marginTop='0'; }
  _rzClearTierHighlights();
  var custWrap=document.getElementById('sub-custom-wrap'), custToggle=document.getElementById('sub-custom-toggle');
  if(custWrap)custWrap.style.display='none';
  if(custToggle)custToggle.style.display='block';
  var custInp=document.getElementById('sub-custom-amount'); if(custInp)custInp.value='';
  window._subSelectedAmount=null;
  window._subSelectedReys=null;
}

async function rzClaimDailyReys(){
  if(!window.sbUser){ if(typeof sbOpenAuth==='function') sbOpenAuth('login'); return; }
  var btn=document.getElementById('sub-claim-btn');
  if(btn) btn.disabled=true;
  try{
    var r=await _sb.rpc('claim_daily_reys');
    if(r.error){
      // Already claimed today (or some other server-side rejection) — resync from the real profile row.
      var fresh=await _sb.from('profiles').select('*').eq('id',sbUser.id).single();
      if(fresh.data) window.sbProfile=fresh.data;
      rzRenderSubscriptionPage();
      if(btn) btn.disabled=false;
      return;
    }
    window.sbProfile.daily_free_reys=r.data;
    window.sbProfile.last_reys_claim_date=new Date().toISOString().slice(0,10);
    rzRenderSubscriptionPage();
    if(typeof cmToast==='function') cmToast('🎉 ৩০০ Reys যোগ হয়েছে! রাত ১২টার মধ্যে ব্যবহার করো');
  }catch(e){
    if(btn) btn.disabled=false;
  }
}

async function submitPayment() {
  var txn = document.getElementById('txn-input');
  var msg = document.getElementById('txn-msg');
  var btn = document.getElementById('sub-submit-btn');
  var amount = window._subSelectedAmount;
  var reysRequested = window._subSelectedReys;
  if(!amount || amount < 30) {
    if(msg){msg.textContent='আগে কত Reys কিনতে চাও বেছে নাও';msg.style.color='#EF4444';}
    return;
  }
  if(!txn || !txn.value.trim()) {
    if(msg){msg.textContent='Transaction ID দিন!';msg.style.color='#EF4444';}
    return;
  }
  if(txn.value.trim().length < 6) {
    if(msg){msg.textContent='Valid Transaction ID দিন (কমপক্ষে ৬ অক্ষর)';msg.style.color='#EF4444';}
    return;
  }
  if(!window.sbUser){ if(typeof sbOpenAuth==='function') sbOpenAuth('login'); return; }
  if(btn) btn.disabled = true;
  try {
    var { error } = await _sb.from('subscription_payments').insert({ user_id: sbUser.id, amount: amount, reys_requested: reysRequested, trx_id: txn.value.trim() });
    if(error){
      if(msg){msg.textContent='কিছু ভুল হয়েছে, আবার চেষ্টা করো।';msg.style.color='#EF4444';}
      if(btn) btn.disabled=false;
      return;
    }
    if(msg){
      msg.textContent='✅ Submit হয়েছে! ২-৪ ঘণ্টার মধ্যে verify করে Reys যোগ করা হবে। ধন্যবাদ!';
      msg.style.color='#16a34a';
      msg.style.fontWeight='600';
    }
    txn.value='';
    if(typeof rzCollapseReysBuy==='function') rzCollapseReysBuy();
  } catch(e) {
    if(msg){msg.textContent='কিছু ভুল হয়েছে, আবার চেষ্টা করো।';msg.style.color='#EF4444';}
    if(btn) btn.disabled=false;
  }
}

