function rdChangeGoal(d){
  rdGoal=Math.max(1,Math.min(20,rdGoal+d));
  var el=document.getElementById('rd-goal-num');
  if(el) el.textContent=rdGoal;
  rdUpdateProgress();
}
function rdPickCat(el,cat){
  rdCat=cat;
  document.querySelectorAll('.rd-cat').forEach(function(b){b.style.borderColor='#e5e7eb';b.style.background='#fff';b.style.color='#666';});
  el.style.borderColor='#1a6b3c';el.style.background='#f0f9f4';el.style.color='#1a6b3c';
}
function rdLogBook(){
  var name=document.getElementById('rd-book-name');
  var pages=document.getElementById('rd-pages');
  if(!name||!name.value.trim()){alert('\u09AC\u0987\u09AF\u09BC\u09C7\u09B0 \u09A8\u09BE\u09AE \u09A6\u09BF\u09A8!');return;}
  var p=parseInt(pages.value)||0;
  rdLogs.unshift({book:name.value.trim(),pages:p,cat:rdCat,date:'\u098F\u0987\u09AE\u09BE\u09A4\u09CD\u09B0'});
  rdPagesTotal+=p;
  rdBooksRead++;
  name.value='';if(pages)pages.value='';
  rdUpdateProgress();rdRenderLogs();
}
function rdUpdateProgress(){
  var pct=Math.min(100,Math.round(rdBooksRead/rdGoal*100));
  var bar=document.getElementById('rd-progress-bar');
  var txt=document.getElementById('rd-progress-text');
  var gtxt=document.getElementById('rd-goal-text');
  var total=document.getElementById('rd-total-books');
  var ptotal=document.getElementById('rd-total-pages');
  if(bar) bar.style.width=pct+'%';
  if(txt) txt.textContent=rdBooksRead+'/'+rdGoal;
  if(gtxt) gtxt.textContent='\u09B2\u0995\u09CD\u09B7\u09CD\u09AF: '+rdGoal+' \u09AC\u0987';
  if(total) total.textContent=rdBooksRead;
  if(ptotal) ptotal.textContent=rdPagesTotal;
}
function rdRenderLogs(){
  var el=document.getElementById('rd-log-list');
  if(!el) return;
  if(!rdLogs.length){el.innerHTML='\u003Cdiv style="text-align:center;padding:20px;color:#aaa;font-size:13px">\u09AA\u09DC;ার লগ নেই\u003C/div>';return;}
  el.innerHTML='';
  rdLogs.forEach(function(log){
    var row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:12px;padding:12px 14px;border-radius:12px;background:#f9fafb;border:1px solid #f0f0f0;margin-bottom:8px';
    var ic=document.createElement('div');ic.style.cssText='width:40px;height:40px;background:#f0f9f4;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:20px;flex-shrink:0';ic.textContent=catIcons[log.cat]||'\uD83D\uDCDA';
    var info=document.createElement('div');info.style.flex='1';
    var name=document.createElement('div');name.style.cssText='font-size:13px;font-weight:700;color:#1a1a2e';name.textContent=log.book;
    var meta=document.createElement('div');meta.style.cssText='font-size:11px;color:#888;margin-top:2px';meta.textContent=log.pages+' \u09AA\u09C3\u09B7\u09CD\u09A0\u09BE \u2022 '+log.date;
    info.appendChild(name);info.appendChild(meta);
    var badge=document.createElement('span');badge.style.cssText='font-size:11px;background:#dcfce7;color:#16a34a;padding:3px 10px;border-radius:50px;font-weight:600;white-space:nowrap';badge.textContent='\u2713 \u09B2\u0997 \u09B9\u09AF\u09BC\u09C7\u099B\u09C7';
    row.appendChild(ic);row.appendChild(info);row.appendChild(badge);el.appendChild(row);
  });
}
