// ── Storage helpers ───────────────────────────────────
function rtToday(){return new Date().toISOString().split('T')[0];}
function rtLoadTasks(){try{var d=localStorage.getItem('_rtTasks');if(d)return JSON.parse(d);}catch(e){}return null;}
function rtSaveTasks(tasks){try{localStorage.setItem('_rtTasks',JSON.stringify(tasks));}catch(e){}}
function rtGetDone(){try{var d=localStorage.getItem('_rtDone_'+rtToday());if(d)return JSON.parse(d);}catch(e){}return [];}
function rtSaveDone(ids){try{localStorage.setItem('_rtDone_'+rtToday(),JSON.stringify(ids));}catch(e){}}

// ── Time helpers ──────────────────────────────────────
function rtFmt12(t24){
  if(!t24)return ['--','--'];
  var p=t24.split(':'),h=parseInt(p[0]),m=p[1],ap=h>=12?'PM':'AM';
  h=h%12||12;return [h+':'+m,ap];
}
function rtNowMins(){var n=new Date();return n.getHours()*60+n.getMinutes();}
function rtTimeMins(t24){if(!t24)return 0;var p=t24.split(':');return parseInt(p[0])*60+parseInt(p[1]);}

// ── Icon row builder ──────────────────────────────────
function rtBuildIconRow(containerId,ref){
  var row=document.getElementById(containerId);if(!row)return;
  row.innerHTML='';
  rtIconKeys.forEach(function(key){
    var btn=document.createElement('button');
    var act=key===ref.val;
    btn.style.cssText='width:38px;height:38px;border-radius:10px;border:1.5px solid '+(act?'#FF8A00':'var(--border,#e5e7eb)')+';background:'+(act?'rgba(255,138,0,.12)':'var(--card,#fff)')+';cursor:pointer;display:flex;align-items:center;justify-content:center;color:'+(act?'#FF8A00':'var(--text2,#888)')+';transition:.15s;flex-shrink:0';
    btn.innerHTML=rtGetSVG(key,18);
    btn.onclick=function(){ref.val=key;rtBuildIconRow(containerId,ref);};
    row.appendChild(btn);
  });
}

