function _agKey(){return '_agGoals_v1';}
function _agLoadGoals(){
  try{var d=localStorage.getItem(_agKey());if(d){var p=JSON.parse(d);if(Array.isArray(p))return p;}}catch(e){}
  return[];
}
function _agSaveGoals(){try{localStorage.setItem(_agKey(),JSON.stringify(_agGoals));}catch(e){}}
_agGoals=_agLoadGoals();

async function agLoadFromSb(){
  if(!window.sbUser||!_sb) return;
  try{
    var res=await _sb.from('adult_goals').select('*').eq('user_id',sbUser.id).order('created_at',{ascending:false});
    if(res.data&&res.data.length){
      _agGoals=(res.data).map(function(r){return{id:r.id,text:r.text,why:r.why||'',tier:r.tier||'life',area:r.area||'personal',priority:r.priority||'medium',progress:r.progress||0,deadline:r.deadline||'',done:r.done||false,createdAt:r.id};});
    }
  }catch(e){}
}
function agInsertSb(goal){
  if(!window.sbUser||!_sb) return;
  _sb.from('adult_goals').insert({id:goal.id,user_id:sbUser.id,text:goal.text,why:goal.why||'',tier:goal.tier||'life',area:goal.area||'personal',priority:goal.priority||'medium',progress:goal.progress||0,deadline:goal.deadline||'',done:goal.done||false});
}
function agUpdateSb(id,fields){
  if(!window.sbUser||!_sb) return;
  _sb.from('adult_goals').update(fields).eq('id',id).eq('user_id',sbUser.id);
}
function agDeleteSb(id){
  if(!window.sbUser||!_sb) return;
  _sb.from('adult_goals').delete().eq('id',id).eq('user_id',sbUser.id);
}

function agQuickAdd(tier){
  var tInp=document.getElementById('ag-inp-tier');
  if(tInp)tInp.value=tier;
  var titles={life:'জীবনের লক্ষ্য যোগ করুন',quarterly:'কোয়ার্টারলি লক্ষ্য যোগ করুন',weekly:'সাপ্তাহিক লক্ষ্য যোগ করুন'};
  var titleEl=document.getElementById('ag-sheet-title');
  if(titleEl)titleEl.textContent=titles[tier]||'নতুন লক্ষ্য যোগ করুন';
  ['ag-inp-text','ag-inp-why'].forEach(function(id){var e=document.getElementById(id);if(e)e.value='';});
  var dl=document.getElementById('ag-inp-deadline');if(dl)dl.value='';
  var headerColors={life:'linear-gradient(135deg,#5B21B6,#8B5CF6)',quarterly:'linear-gradient(135deg,#1D4ED8,#3B82F6)',weekly:'linear-gradient(135deg,#C2410C,#F97316)'};
  var tierLabels={life:'জীবনের লক্ষ্য • ১-৫ বছর',quarterly:'কোয়ার্টারলি লক্ষ্য • ৩ মাস',weekly:'সাপ্তাহিক স্প্রিন্ট • এই সপ্তাহ'};
  var hdr=document.getElementById('ag-modal-header');
  if(hdr)hdr.style.background=headerColors[tier]||headerColors.life;
  var tlbl=document.getElementById('ag-modal-tier-label');
  if(tlbl)tlbl.textContent=tierLabels[tier]||tierLabels.life;
  var o=document.getElementById('ag-sheet-overlay'),s=document.getElementById('ag-sheet');
  if(!o||!s)return;
  o.style.display='flex';
  requestAnimationFrame(function(){s.style.opacity='1';s.style.transform='scale(1) translateY(0)';});
}
window.agQuickAdd=agQuickAdd;

function agCloseSheet(){
  var o=document.getElementById('ag-sheet-overlay'),s=document.getElementById('ag-sheet');
  if(s){s.style.opacity='0';s.style.transform='scale(0.9) translateY(8px)';}
  setTimeout(function(){if(o)o.style.display='none';},280);
}
window.agCloseSheet=agCloseSheet;

function agSaveGoal(){
  var text=(document.getElementById('ag-inp-text')||{}).value||'';
  if(!text.trim()){alert('লক্ষ্য লিখুন!');return;}
  var goal={
    id:Date.now(),
    text:text.trim(),
    why:((document.getElementById('ag-inp-why')||{}).value||'').trim(),
    tier:(document.getElementById('ag-inp-tier')||{}).value||'life',
    area:(document.getElementById('ag-inp-area')||{}).value||'personal',
    priority:(document.getElementById('ag-inp-priority')||{}).value||'medium',
    progress:0,
    deadline:(document.getElementById('ag-inp-deadline')||{}).value||'',
    done:false,
    createdAt:Date.now()
  };
  _agGoals.unshift(goal);
  _agSaveGoals();
  agInsertSb(goal);
  agCloseSheet();
  agRender();
}
window.agSaveGoal=agSaveGoal;

function agToggleDone(id){
  var g=_agGoals.find(function(x){return x.id===id;});
  if(g){g.done=!g.done;if(g.done)g.progress=100;_agSaveGoals();agUpdateSb(id,{done:g.done,progress:g.progress});agRender();}
}
window.agToggleDone=agToggleDone;

function agOpenProgSheet(id){
  var g=_agGoals.find(function(x){return x.id===id;});
  if(!g)return;
  _agProgGoalId=id;
  var nm=document.getElementById('ag-prog-goalname');
  var wy=document.getElementById('ag-prog-why');
  var sl=document.getElementById('ag-prog-slider');
  var lb=document.getElementById('ag-prog-pct-label');
  if(nm)nm.textContent=g.text;
  if(wy)wy.textContent=g.why?'"'+g.why+'"':'';
  if(sl)sl.value=g.progress;
  if(lb)lb.textContent=g.progress+'%';
  var o=document.getElementById('ag-prog-overlay'),s=document.getElementById('ag-prog-sheet');
  if(!o||!s)return;
  o.style.display='flex';
  requestAnimationFrame(function(){s.style.opacity='1';s.style.transform='scale(1) translateY(0)';});
}
window.agOpenProgSheet=agOpenProgSheet;

function agCloseProgSheet(){
  var o=document.getElementById('ag-prog-overlay'),s=document.getElementById('ag-prog-sheet');
  if(s){s.style.opacity='0';s.style.transform='scale(0.9) translateY(8px)';}
  setTimeout(function(){if(o)o.style.display='none';},280);
}
window.agCloseProgSheet=agCloseProgSheet;

function agSaveProgress(){
  if(!_agProgGoalId)return;
  var sl=document.getElementById('ag-prog-slider');
  var val=sl?parseInt(sl.value):0;
  var g=_agGoals.find(function(x){return x.id===_agProgGoalId;});
  if(g){g.progress=val;g.done=val===100;_agSaveGoals();agUpdateSb(g.id,{progress:g.progress,done:g.done});}
  agCloseProgSheet();
  agRender();
}
window.agSaveProgress=agSaveProgress;

function agDelete(id){
  if(!confirm('এই লক্ষ্যটি মুছে ফেলবেন?'))return;
  _agGoals=_agGoals.filter(function(x){return x.id!==id;});
  _agSaveGoals();agDeleteSb(id);agRender();
}
window.agDelete=agDelete;

function agFilterArea(area){
  _agCurArea=area;
  agRenderAreaChips();
  agRenderBoard();
}
window.agFilterArea=agFilterArea;

function _agDaysLeft(deadline){
  if(!deadline)return null;
  var d=new Date(deadline);var now=new Date();now.setHours(0,0,0,0);
  return Math.round((d-now)/(864e5));
}

function agRenderCard(g){
  var area=_agAreas.find(function(a){return a.id===g.area;})||{id:'personal',label:'ব্যক্তিগত',color:'#FF8A00',emoji:'⭐'};
  var tc=_agTierColors[g.tier]||_agTierColors.life;
  var daysLeft=_agDaysLeft(g.deadline);
  var priorColor={high:'#EF4444',medium:'#F59E0B',normal:'#10B981'}[g.priority]||'#aaa';
  var priorLabel={high:'উচ্চ',medium:'মাঝারি',normal:'সাধারণ'}[g.priority]||'';

  var card=document.createElement('div');
  card.style.cssText='background:var(--bg,#f9fafb);border:1.5px solid var(--border,#f0f0f0);border-radius:14px;padding:13px;margin-bottom:8px;transition:.2s;'+(g.done?'opacity:.55':'');

  // Row 1: area chip + priority dot + delete btn
  var r1=document.createElement('div');
  r1.style.cssText='display:flex;align-items:center;gap:6px;margin-bottom:9px';
  var aChip=document.createElement('div');
  aChip.style.cssText='display:inline-flex;align-items:center;gap:3px;background:'+area.color+'18;padding:3px 8px;border-radius:20px;font-size:10px;font-weight:700;color:'+area.color;
  aChip.innerHTML='<span style="display:inline-flex;align-items:center">'+(_agAreaSVGs[area.id]||'')+'</span><span>'+area.label+'</span>';
  var pDot=document.createElement('div');
  pDot.title=priorLabel+' অগ্রাধিকার';
  pDot.style.cssText='width:7px;height:7px;border-radius:50%;background:'+priorColor+';flex-shrink:0;margin-left:auto;cursor:help';
  var delBtn=document.createElement('button');
  delBtn.style.cssText='width:24px;height:24px;border-radius:7px;border:none;background:rgba(239,68,68,.08);color:#EF4444;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0';
  delBtn.innerHTML='<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
  delBtn.onclick=(function(id){return function(e){e.stopPropagation();agDelete(id);};})(g.id);
  r1.appendChild(aChip);r1.appendChild(pDot);r1.appendChild(delBtn);

  // Title
  var title=document.createElement('div');
  title.style.cssText='font-size:13px;font-weight:700;color:var(--text,#1a1a2e);margin-bottom:'+(g.why?'5px':'10px')+(g.done?';text-decoration:line-through;opacity:.5':'');
  title.textContent=g.text;

  // Why
  var whyEl=null;
  if(g.why){
    whyEl=document.createElement('div');
    whyEl.style.cssText='font-size:11px;color:var(--text2,#999);font-style:italic;margin-bottom:10px;line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden';
    whyEl.textContent='"'+g.why+'"';
  }

  // Progress section (click to open sheet)
  var progWrap=document.createElement('div');
  progWrap.style.cssText='margin-bottom:10px;cursor:pointer';
  progWrap.title='ক্লিক করুন অগ্রগতি আপডেট করতে';
  progWrap.onclick=(function(id){return function(e){e.stopPropagation();agOpenProgSheet(id);};})(g.id);

  var progTop=document.createElement('div');
  progTop.style.cssText='display:flex;justify-content:space-between;align-items:center;margin-bottom:5px';
  var progLbl=document.createElement('div');
  progLbl.style.cssText='font-size:10px;font-weight:600;color:var(--text2,#aaa)';
  progLbl.textContent='অগ্রগতি';
  var progPct=document.createElement('div');
  progPct.style.cssText='font-size:12px;font-weight:800;color:'+area.color;
  progPct.textContent=g.progress+'%';
  progTop.appendChild(progLbl);progTop.appendChild(progPct);

  var progTrack=document.createElement('div');
  progTrack.style.cssText='height:5px;background:var(--border,#eee);border-radius:10px;overflow:hidden';
  var progFill=document.createElement('div');
  progFill.style.cssText='height:100%;width:'+g.progress+'%;background:linear-gradient(90deg,'+area.color+','+area.color+'aa);border-radius:10px;transition:.3s ease';
  progTrack.appendChild(progFill);
  progWrap.appendChild(progTop);progWrap.appendChild(progTrack);

  // Bottom row: deadline + done button
  var bottom=document.createElement('div');
  bottom.style.cssText='display:flex;align-items:center;gap:8px';

  if(daysLeft!==null){
    var dlEl=document.createElement('div');
    var dlColor=daysLeft<0?'#EF4444':daysLeft<=7?'#F59E0B':'var(--text2,#aaa)';
    var dlText=daysLeft<0?Math.abs(daysLeft)+'দিন অতিক্রান্ত':daysLeft===0?'আজই ডেডলাইন!':daysLeft+'দিন বাকি';
    dlEl.style.cssText='font-size:10px;font-weight:700;color:'+dlColor+';display:flex;align-items:center;gap:3px;flex:1';
    dlEl.innerHTML='<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>'+dlText;
    bottom.appendChild(dlEl);
  }else{
    bottom.appendChild(document.createElement('div')).style.flex='1';
  }

  var ckBtn=document.createElement('button');
  ckBtn.style.cssText='width:28px;height:28px;border-radius:50%;border:2px solid '+(g.done?tc.main:'var(--border,#d1d5db)')+';background:'+(g.done?tc.main:'transparent')+';cursor:pointer;display:flex;align-items:center;justify-content:center;transition:.2s;flex-shrink:0';
  ckBtn.innerHTML=g.done?'<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg>':'';
  ckBtn.onclick=(function(id){return function(e){e.stopPropagation();agToggleDone(id);};})(g.id);
  bottom.appendChild(ckBtn);

  card.appendChild(r1);
  card.appendChild(title);
  if(whyEl)card.appendChild(whyEl);
  card.appendChild(progWrap);
  card.appendChild(bottom);
  return card;
}

function agRenderBoard(){
  var tiers=['life','quarterly','weekly'];
  var listIds={life:'ag-life-list',quarterly:'ag-quarterly-list',weekly:'ag-weekly-list'};
  var countIds={life:'ag-life-count',quarterly:'ag-quarterly-count',weekly:'ag-weekly-count'};
  tiers.forEach(function(tier){
    var el=document.getElementById(listIds[tier]);
    var ct=document.getElementById(countIds[tier]);
    if(!el)return;
    var filtered=_agGoals.filter(function(g){
      return g.tier===tier&&(_agCurArea==='all'||g.area===_agCurArea);
    });
    if(ct)ct.textContent=filtered.length;
    el.innerHTML='';
    if(!filtered.length){
      var em=document.createElement('div');
      em.style.cssText='text-align:center;padding:24px 10px;color:var(--text2,#ccc);font-size:12px;font-style:italic';
      em.textContent='এখানে কোনো লক্ষ্য নেই';
      el.appendChild(em);return;
    }
    filtered.forEach(function(g){el.appendChild(agRenderCard(g));});
  });
}

function agRenderAreaChips(){
  var wrap=document.getElementById('ag-area-chips');if(!wrap)return;
  wrap.innerHTML='';
  var allBtn=document.createElement('button');
  allBtn.style.cssText='padding:5px 12px;border-radius:20px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;border:1.5px solid '+(_agCurArea==='all'?'#FF8A00':'var(--border,#e5e7eb)')+';background:'+(_agCurArea==='all'?'#FF8A00':'transparent')+';color:'+(_agCurArea==='all'?'#fff':'var(--text2,#888)')+';transition:.15s';
  allBtn.textContent='সব';
  allBtn.onclick=function(){agFilterArea('all');};
  wrap.appendChild(allBtn);
  _agAreas.forEach(function(area){
    var cnt=_agGoals.filter(function(g){return g.area===area.id;}).length;
    var active=_agCurArea===area.id;
    var btn=document.createElement('button');
    btn.style.cssText='padding:5px 10px;border-radius:20px;font-size:11px;font-weight:700;cursor:pointer;font-family:inherit;border:1.5px solid '+(active?area.color:'var(--border,#e5e7eb)')+';background:'+(active?area.color+'18':'transparent')+';color:'+(active?area.color:'var(--text2,#888)')+';display:inline-flex;align-items:center;gap:3px;transition:.15s';
    btn.innerHTML='<span style="display:inline-flex;align-items:center">'+(_agAreaSVGs[area.id]||'')+'</span><span>'+area.label+'</span>'+(cnt?'<span style="background:'+area.color+';color:#fff;border-radius:10px;padding:0 5px;font-size:9px;margin-left:2px">'+cnt+'</span>':'');
    btn.onclick=(function(id){return function(){agFilterArea(id);};})(area.id);
    wrap.appendChild(btn);
  });
}

function agBuildRadar(){
  var svg=document.getElementById('ag-radar');if(!svg)return;
  var cx=95,cy=95,r=68,n=7;
  function angle(i){return -Math.PI/2+i*(2*Math.PI/n);}
  function pt(i,radius){return {x:cx+radius*Math.cos(angle(i)),y:cy+radius*Math.sin(angle(i))};}
  function toPath(pts2){return pts2.map(function(p,i){return(i===0?'M':'L')+p.x.toFixed(1)+','+p.y.toFixed(1);}).join(' ')+'Z';}
  svg.innerHTML='';
  var ns='http://www.w3.org/2000/svg';
  [0.25,0.5,0.75,1].forEach(function(pct){
    var pts2=Array.from({length:n},function(_,i){return pt(i,r*pct);});
    var path=document.createElementNS(ns,'path');
    path.setAttribute('d',toPath(pts2));
    path.setAttribute('fill',pct===1?'rgba(255,138,0,.04)':'none');
    path.setAttribute('stroke',pct===1?'rgba(255,138,0,.2)':'var(--border,#e5e7eb)');
    path.setAttribute('stroke-width','1');
    svg.appendChild(path);
  });
  for(var i=0;i<n;i++){
    var outerPt=pt(i,r);
    var line=document.createElementNS(ns,'line');
    line.setAttribute('x1',cx);line.setAttribute('y1',cy);
    line.setAttribute('x2',outerPt.x.toFixed(1));line.setAttribute('y2',outerPt.y.toFixed(1));
    line.setAttribute('stroke','var(--border,#e5e7eb)');line.setAttribute('stroke-width','1');
    svg.appendChild(line);
  }
  var areaProgress=_agAreas.map(function(area){
    var goals=_agGoals.filter(function(g){return g.area===area.id;});
    if(!goals.length)return 0;
    return goals.reduce(function(s,g){return s+g.progress;},0)/goals.length/100;
  });
  var dataPts=_agAreas.map(function(area,i){return pt(i,r*Math.max(0.05,areaProgress[i]));});
  var fill=document.createElementNS(ns,'path');
  fill.setAttribute('d',toPath(dataPts));
  fill.setAttribute('fill','rgba(255,138,0,.12)');
  fill.setAttribute('stroke','#FF8A00');
  fill.setAttribute('stroke-width','2');
  svg.appendChild(fill);
  dataPts.forEach(function(p,i){
    var dot=document.createElementNS(ns,'circle');
    dot.setAttribute('cx',p.x.toFixed(1));dot.setAttribute('cy',p.y.toFixed(1));
    dot.setAttribute('r','4');dot.setAttribute('fill',_agAreas[i].color);
    dot.setAttribute('stroke','var(--card,#fff)');dot.setAttribute('stroke-width','2');
    svg.appendChild(dot);
  });
  _agAreas.forEach(function(area,i){
    var lp=pt(i,r+15);
    var txt=document.createElementNS(ns,'text');
    txt.setAttribute('x',lp.x.toFixed(1));txt.setAttribute('y',lp.y.toFixed(1));
    txt.setAttribute('text-anchor','middle');txt.setAttribute('dominant-baseline','middle');
    txt.setAttribute('font-size','9');txt.setAttribute('font-weight','600');svg.appendChild(txt);
    txt.textContent=area.short;
  });
}

function agUpdateHero(){
  var total=_agGoals.length;
  var done=_agGoals.filter(function(g){return g.done;}).length;
  var active=_agGoals.filter(function(g){return !g.done;}).length;
  var pct=total?Math.round(done/total*100):0;
  function s(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}
  s('ag-stat-total',total);s('ag-stat-done',done);s('ag-stat-active',active);
  var arc=document.getElementById('ag-ring-arc');
  var pctEl=document.getElementById('ag-ring-pct');
  if(arc){var circ=251.3;setTimeout(function(){arc.style.strokeDashoffset=circ-(circ*pct/100);},100);}
  if(pctEl)pctEl.textContent=pct+'%';
}

function agRender(){
  agUpdateHero();
  agBuildRadar();
  agRenderAreaChips();
  agRenderBoard();
}
window.agRender=agRender;

