var sctGoalMins=60,sctUsedMins=0,sctRunning=false,sctSec=0,sctIv=null;
var sctApps=[{app:'YouTube',mins:20},{app:'TikTok',mins:10}];
var sctWeek=[45,80,30,65,20,55,0];
var sctDays=['\u09b6\u09a8\u09bf','\u09b0\u09ac\u09bf','\u09b8\u09cb\u09ae','\u09ae\u0999\u09cd\u0997\u09b2','\u09ac\u09c1\u09a7','\u09ac\u09c3\u09b9','\u0986\u099c'];

function sctFmtGoal(m){if(m<60)return m+' min';var h=Math.floor(m/60),r=m%60;return h+' \u0998\u09a3\u09cd\u099f\u09be'+(r?' '+r+' min':'');}
function sctSet(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}

function sctGoalChange(d){
  sctGoalMins=Math.max(15,Math.min(480,sctGoalMins+d));
  sctSet('sct-goal-lbl',sctFmtGoal(sctGoalMins));
  sctRefresh();
}

function sctToggle(){
  if(!sctRunning){
    sctRunning=true;
    sctSet('sct-btn','\u23f8 \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09c1\u09a8');
    sctSet('sct-clock-lbl','\u09b8\u09cd\u0995\u09cd\u09b0\u09bf\u09a8 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u099a\u09b2\u099b\u09c5...');
    sctIv=setInterval(function(){sctSec++;sctUsedMins=Math.floor(sctSec/60);sctTickClock();sctRefresh();},1000);
  } else {
    sctRunning=false;clearInterval(sctIv);
    sctSet('sct-btn','\u25b6 \u09b6\u09c1\u09b0\u09c1 \u0995\u09b0\u09c1\u09a8');
    sctSet('sct-clock-lbl','\u099f\u09be\u0987\u09ae\u09be\u09b0 \u09ac\u09a8\u09cd\u09a7');
  }
}

function sctReset(){
  clearInterval(sctIv);sctRunning=false;sctSec=0;sctUsedMins=0;
  sctSet('sct-btn','\u25b6 \u09b6\u09c1\u09b0\u09c1 \u0995\u09b0\u09c1\u09a8');
  sctSet('sct-clock-lbl','\u099f\u09be\u0987\u09ae\u09be\u09b0 \u09ac\u09a8\u09cd\u09a7');
  sctTickClock();sctRefresh();
}

function sctTickClock(){
  var h=Math.floor(sctSec/3600),m=Math.floor((sctSec%3600)/60),s=sctSec%60;
  sctSet('sct-clock',(h<10?'0':'')+h+':'+(m<10?'0':'')+m+':'+(s<10?'0':'')+s);
  sctSet('sct-used-lbl',sctFmtGoal(sctUsedMins));
}

function sctRefresh(){
  var pct=Math.min(100,Math.round(sctUsedMins/sctGoalMins*100));
  var bar=document.getElementById('sct-bar'),pctEl=document.getElementById('sct-pct'),stEl=document.getElementById('sct-status'),bdg=document.getElementById('sct-badge');
  var lbl=document.getElementById('sct-used-lbl');
  if(bar){bar.style.width=pct+'%';bar.style.background=pct>=100?'linear-gradient(90deg,#EF4444,#dc2626)':pct>=80?'linear-gradient(90deg,#F59E0B,#d97706)':'linear-gradient(90deg,#1a6b3c,#2e7d32)';}
  if(pctEl){pctEl.textContent=pct+'%';pctEl.style.color=pct>=100?'#EF4444':pct>=80?'#d97706':'#1a6b3c';}
  if(stEl){
    if(pct>=100){stEl.textContent='\u26a0\ufe0f \u09b2\u0995\u09cd\u09b7\u09cd\u09af \u09aa\u09c5\u09b0\u09bf\u09af\u09bc\u09c5 \u0997\u09c5\u099b\u09c5! Screen \u09ac\u09a8\u09cd\u09a7 \u0995\u09b0\u09c1\u09a8';stEl.style.color='#EF4444';}
    else if(pct>=80){stEl.textContent='\u09b8\u09be\u09ac\u09a7\u09be\u09a8! \u09ac\u09c5\u09b6\u09bf \u09b9\u09af\u09bc\u09c5 \u09af\u09be\u099a\u09cd\u099b\u09c5 \u26a0\ufe0f';stEl.style.color='#d97706';}
    else{stEl.textContent='\u09b2\u0995\u09cd\u09b7\u09cd\u09af\u09c5\u09b0 \u09ae\u09a7\u09cd\u09af\u09c5 \u0986\u099b\u09c5 \u2713';stEl.style.color='#1a6b3c';}
  }
  if(bdg){
    bdg.style.background=pct>=100?'#fee2e2':pct>=80?'#fff9e6':'#dcfce7';
    bdg.style.borderColor=pct>=100?'#fca5a5':pct>=80?'#fde68a':'#86efac';
    if(lbl)lbl.style.color=pct>=100?'#dc2626':pct>=80?'#d97706':'#16a34a';
  }
}

function sctLogApp(){
  var n=document.getElementById('sct-app'),m=document.getElementById('sct-mins');
  if(!n||!n.value.trim()){alert('App \u09a8\u09be\u09ae \u09a6\u09bf\u09a8!');return;}
  var mins=parseInt(m&&m.value)||0;
  var ex=sctApps.find(function(a){return a.app.toLowerCase()===n.value.trim().toLowerCase();});
  if(ex)ex.mins+=mins;else sctApps.unshift({app:n.value.trim(),mins:mins});
  sctUsedMins+=mins;n.value='';if(m)m.value='';
  sctTickClock();sctRefresh();sctRenderApps();
}

function sctRenderApps(){
  var el=document.getElementById('sct-app-list');if(!el)return;el.innerHTML='';
  if(!sctApps.length){
    var em=document.createElement('div');em.style.cssText='text-align:center;padding:14px;color:#aaa;font-size:13px';em.textContent='\u0995\u09cb\u09a8\u09cb log \u09a8\u09c5\u0987';el.appendChild(em);return;
  }
  var total=sctApps.reduce(function(s,a){return s+a.mins;},0)||1;
  var cols=['#1a6b3c','#8B5CF6','#3B82F6','#F59E0B','#EF4444','#EC4899'];
  sctApps.forEach(function(a,i){
    var pct=Math.round(a.mins/total*100);
    var row=document.createElement('div');row.style.cssText='background:#fafafa;border-radius:10px;padding:10px 14px;border:1px solid #f0f0f0';
    var hd=document.createElement('div');hd.style.cssText='display:flex;justify-content:space-between;font-size:13px;font-weight:600;margin-bottom:5px';
    var nm=document.createElement('span');nm.textContent=a.app;
    var vl=document.createElement('span');vl.style.color=cols[i%cols.length];vl.textContent=a.mins+' min ('+pct+'%)';
    hd.appendChild(nm);hd.appendChild(vl);
    var bg=document.createElement('div');bg.style.cssText='height:6px;background:#f0f0f0;border-radius:10px;overflow:hidden';
    var fl=document.createElement('div');fl.style.cssText='height:100%;border-radius:10px;background:'+cols[i%cols.length];fl.style.width=pct+'%';
    bg.appendChild(fl);row.appendChild(hd);row.appendChild(bg);el.appendChild(row);
  });
}

function sctRenderChart(){
  var el=document.getElementById('sct-chart');if(!el)return;el.innerHTML='';
  var maxV=Math.max(Math.max.apply(null,sctWeek),sctGoalMins,1);
  sctWeek.forEach(function(v,i){
    var today=i===6,over=v>sctGoalMins;
    var hPx=Math.max(4,Math.round(v/maxV*80));
    var col=document.createElement('div');col.style.cssText='display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100px';
    var val=document.createElement('div');val.style.cssText='font-size:9px;font-weight:700;color:'+(over?'#EF4444':'#1a6b3c')+';margin-bottom:2px';val.textContent=v?v+'m':'';
    var bar=document.createElement('div');bar.style.cssText='width:100%;border-radius:4px 4px 0 0;background:'+(over?'#EF4444':'#1a6b3c')+';height:'+hPx+'px'+(today?';outline:2px solid #F9A825;outline-offset:1px':'');
    var lbl=document.createElement('div');lbl.style.cssText='font-size:9px;margin-top:4px;color:'+(today?'#1a6b3c':'#888')+';font-weight:'+(today?'700':'400');lbl.textContent=sctDays[i];
    col.appendChild(val);col.appendChild(bar);col.appendChild(lbl);el.appendChild(col);
  });
}

var _sctOrig=window.showPage;
window.showPage=function(page){
  _sctOrig(page);
  if(page==='screentime')setTimeout(function(){sctTickClock();sctRefresh();sctRenderApps();sctRenderChart();},50);
};

