function ntfUnreadCount(){return ntfData.filter(function(n){return !n.read;}).length;}

function ntfTimeAgo(ts){
  var s=Math.floor((Date.now()-new Date(ts))/1000);
  if(s<60) return 'just now';
  if(s<3600) return Math.floor(s/60)+' min ago';
  if(s<86400) return Math.floor(s/3600)+(Math.floor(s/3600)>1?' hrs':' hr')+' ago';
  if(s<172800) return 'Yesterday';
  return Math.floor(s/86400)+' days ago';
}

function ntfToggle(){
  var sheet=document.getElementById('ntf-sheet');
  if(!sheet)return;
  if(sheet.style.display==='flex') ntfClose(); else ntfOpen();
}

function ntfOpen(){
  var sheet=document.getElementById('ntf-sheet');
  var bd=document.getElementById('ntf-sheet-bd');
  if(!sheet)return;
  var isMobile=window.innerWidth<768;
  sheet.style.display='flex';
  if(bd){bd.style.display='block';bd.style.background=isMobile?'rgba(0,0,0,.45)':'transparent';}
  requestAnimationFrame(function(){
    requestAnimationFrame(function(){
      sheet.classList.add('ntf-open');
    });
  });
  ntfLoadFromDB();
}

function ntfClose(){
  var sheet=document.getElementById('ntf-sheet');
  var bd=document.getElementById('ntf-sheet-bd');
  if(!sheet)return;
  sheet.classList.remove('ntf-open');
  var delay=window.innerWidth<768?340:200;
  setTimeout(function(){
    sheet.style.display='none';
    if(bd)bd.style.display='none';
  },delay);
}

async function ntfLoadFromDB(){
  if(!window.sbUser){ntfSheetRender();return;}
  var el=document.getElementById('ntf-sheet-list');
  if(el)el.innerHTML='<div style="text-align:center;padding:48px 20px;color:var(--sub-text)"><div style="width:36px;height:36px;border:3px solid #FF8A00;border-top-color:transparent;border-radius:50%;animation:spin .7s linear infinite;margin:0 auto 14px"></div><div style="font-size:13px;font-family:\'Bahnschrift\',sans-serif">Loading...</div></div>';
  try{
    var res=await _sb.from('notifications').select('*').eq('user_id',window.sbUser.id).order('created_at',{ascending:false}).limit(40);
    if(!res.error && res.data && res.data.length>0){
      ntfData=res.data.map(function(n){
        var meta=n.metadata||{};
        // handle metadata stored as string (legacy)
        if(typeof meta==='string'){try{meta=JSON.parse(meta);}catch(e){meta={};}}
        return {id:n.id,type:n.type,title:n.title,msg:n.msg||'',time:ntfTimeAgo(n.created_at),read:n.read,dot:n.dot||'#FF8A00',metadata:meta};
      });
      // Fetch missing avatars for user-type notifications
      var missingIds=[];
      ntfData.forEach(function(n){
        if(n.metadata&&n.metadata.from_user_id&&!n.metadata.from_avatar){
          if(missingIds.indexOf(n.metadata.from_user_id)===-1) missingIds.push(n.metadata.from_user_id);
        }
      });
      if(missingIds.length){
        try{
          var pr=await _sb.from('profiles').select('id,avatar_url').in('id',missingIds);
          if(pr.data){
            var avatarMap={};
            pr.data.forEach(function(p){avatarMap[p.id]=p.avatar_url||'';});
            ntfData.forEach(function(n){
              if(n.metadata&&n.metadata.from_user_id&&avatarMap[n.metadata.from_user_id]!==undefined){
                n.metadata.from_avatar=avatarMap[n.metadata.from_user_id];
              }
            });
          }
        }catch(e){}
      }
    }
  }catch(e){}
  ntfSheetRender();
}

async function ntfLoadBadge(){
  if(!window.sbUser){ntfUpdateBadge();return;}
  try{
    var res=await _sb.from('notifications').select('id',{count:'exact',head:true}).eq('user_id',window.sbUser.id).eq('read',false);
    var count=res.count||0;
    var badge=document.getElementById('ntf-badge');
    if(badge){badge.textContent=count>0?count:'';badge.style.display=count>0?'flex':'none';}
    var b2=document.getElementById('ntf-sheet-badge');
    if(b2){b2.textContent=count;b2.style.display=count>0?'inline-block':'none';}
  }catch(e){ntfUpdateBadge();}
}

async function ntfMarkAll(){
  ntfData.forEach(function(n){n.read=true;});
  ntfUpdateBadge();ntfSheetRender();
  if(window.sbUser&&_sb){
    try{await _sb.from('notifications').update({read:true}).eq('user_id',window.sbUser.id).eq('read',false);}catch(e){}
  }
}

async function ntfMarkRead(id){
  var n=ntfData.find(function(x){return x.id==id;});
  if(n&&!n.read){
    n.read=true;
    ntfUpdateBadge();ntfSheetRender();
    if(window.sbUser&&_sb){
      try{await _sb.from('notifications').update({read:true}).eq('id',id).eq('user_id',window.sbUser.id);}catch(e){}
    }
  }
}

function ntfUpdateBadge(){
  var badge=document.getElementById('ntf-badge');
  var count=ntfUnreadCount();
  if(badge){badge.textContent=count>0?count:'';badge.style.display=count>0?'flex':'none';}
  var badge2=document.getElementById('ntf-sheet-badge');
  if(badge2){badge2.textContent=count;badge2.style.display=count>0?'inline-block':'none';}
}

window._rzAvErr=function(el,bg,letter,fs){el.style.display='none';el.parentNode.style.background=bg;el.parentNode.innerHTML='<span style="font-size:'+fs+'px;font-weight:800;color:#fff;line-height:1">'+letter+'</span>';};
function _ntfAvatar(avatarUrl, name, size){
  size=size||44;
  var letter=(name||'R').charAt(0).toUpperCase();
  var cols=['#FF8A00','#8B5CF6','#3B82F6','#10B981','#EF4444'];
  var bg=cols[letter.charCodeAt(0)%cols.length];
  var fs=Math.round(size*0.4);
  var base='width:'+size+'px;height:'+size+'px;min-width:'+size+'px;border-radius:50%;flex-shrink:0;overflow:hidden;display:flex;align-items:center;justify-content:center;';
  if(avatarUrl){
    return '<div style="'+base+'background:'+bg+'"><img src="'+avatarUrl+'" style="width:100%;height:100%;object-fit:cover" onerror="window._rzAvErr(this,\''+bg+'\',\''+letter+'\','+fs+')"/></div>';
  }
  return '<div style="'+base+'background:'+bg+';font-size:'+fs+'px;font-weight:800;color:#fff">'+letter+'</div>';
}

var _ntfFont='\'Space Grotesk\',\'Hind Siliguri\',sans-serif';

function ntfItemHtml(n){
  var bg=n.read?'transparent':'rgba(255,138,0,.06)';
  // Special card for rise_request
  if(n.type==='rise_request' && n.metadata && n.metadata.from_user_id && !n.metadata._acted){
    var fromId=n.metadata.from_user_id;
    var fromName=n.metadata.from_name||'একজন Rizer';
    var reqId=n.metadata.request_id||null;
    var av=_ntfAvatar(n.metadata.from_avatar,fromName,44);
    return '<div id="ntf-rise-'+n.id+'" style="padding:14px 16px;border-bottom:1px solid var(--border);background:'+bg+'">'
      +'<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px">'
        +av
        +'<div style="flex:1;min-width:0">'
          +'<div style="font-size:14px;font-weight:700;color:var(--text);line-height:1.3;font-family:'+_ntfFont+'">'+n.title+'</div>'
          +'<div style="font-size:12px;color:var(--sub-text);margin-top:2px;line-height:1.4;font-family:'+_ntfFont+'">'+n.msg+'</div>'
          +'<div style="font-size:11px;color:#FF8A00;font-weight:600;margin-top:4px;font-family:'+_ntfFont+'">'+n.time+'</div>'
        +'</div>'
        +(n.read?'':'<div style="width:8px;height:8px;min-width:8px;background:#FF8A00;border-radius:50%"></div>')
      +'</div>'
      +'<div style="display:flex;gap:8px">'
        +'<button onclick="pfNtfAcceptRise(\''+n.id+'\',\''+fromId+'\',\''+reqId+'\')" style="flex:1;padding:9px;background:linear-gradient(90deg,#FF8A00,#FFB800);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;font-family:'+_ntfFont+'">⚡ Accept</button>'
        +'<button onclick="pfNtfDeclineRise(\''+n.id+'\',\''+fromId+'\',\''+reqId+'\')" style="flex:1;padding:9px;background:var(--border);color:var(--sub-text);border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;font-family:'+_ntfFont+'">Not Yet</button>'
      +'</div>'
      +'</div>';
  }
  // Special card for rise_accepted
  if(n.type==='rise_accepted'){
    var fromName2=(n.metadata&&n.metadata.from_name)||'একজন Rizer';
    var av2=_ntfAvatar(n.metadata&&n.metadata.from_avatar,fromName2,44);
    return '<div onclick="ntfMarkRead(\''+n.id+'\')" style="display:flex;align-items:center;gap:12px;padding:13px 16px;border-bottom:1px solid var(--border);cursor:pointer;background:'+bg+'">'
      +av2
      +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:14px;font-weight:'+(n.read?600:700)+';color:var(--text);line-height:1.3;font-family:'+_ntfFont+'">'+n.title+'</div>'
        +'<div style="font-size:12px;color:var(--sub-text);margin-top:2px;font-family:'+_ntfFont+'">'+n.msg+'</div>'
        +'<div style="font-size:11px;color:#22c55e;font-weight:600;margin-top:4px;font-family:'+_ntfFont+'">'+n.time+'</div>'
      +'</div>'
      +(n.read?'':'<div style="width:8px;height:8px;min-width:8px;background:#22c55e;border-radius:50%"></div>')
      +'</div>';
  }
  // Default notification card
  var dotColor=n.dot||'#FF8A00';
  return '<div onclick="ntfMarkRead(\''+n.id+'\')" style="display:flex;align-items:center;gap:13px;padding:13px 16px;border-bottom:1px solid var(--border);cursor:pointer;background:'+bg+';-webkit-tap-highlight-color:transparent">'
    +'<div style="width:42px;height:42px;min-width:42px;border-radius:14px;background:var(--bg);display:flex;align-items:center;justify-content:center;flex-shrink:0">'+(ntfIcons[n.type]||ntfIcons['bell']||'')+'</div>'
    +'<div style="flex:1;min-width:0">'
      +'<div style="font-size:14px;font-weight:'+(n.read?600:700)+';color:var(--text);line-height:1.35;margin-bottom:2px;font-family:'+_ntfFont+'">'+n.title+'</div>'
      +'<div style="font-size:12.5px;color:var(--sub-text);line-height:1.45;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;font-family:'+_ntfFont+'">'+n.msg+'</div>'
      +'<div style="font-size:11.5px;color:'+(n.read?'var(--sub-text)':dotColor)+';font-weight:'+(n.read?400:600)+';margin-top:4px;font-family:'+_ntfFont+'">'+n.time+'</div>'
    +'</div>'
    +(n.read?'':'<div style="width:8px;height:8px;min-width:8px;background:'+dotColor+';border-radius:50%"></div>')
    +'</div>';
}

function ntfSheetRender(){
  var el=document.getElementById('ntf-sheet-list');
  if(!el)return;
  var visible=ntfData.filter(function(n){return !(n.type==='rise_request'&&n.metadata&&n.metadata._acted);});
  var unread=visible.filter(function(n){return !n.read;});
  var read=visible.filter(function(n){return n.read;});
  var html='';
  if(ntfData.length===0){
    html='<div style="text-align:center;padding:60px 20px;color:var(--sub-text)"><div style="font-size:52px;margin-bottom:14px">&#128276;</div><div style="font-size:15px;font-weight:700;font-family:\'Bahnschrift\',\'DIN Alternate\',sans-serif">No notifications yet</div></div>';
  } else {
    var labelStyle='padding:12px 16px 6px;font-size:11px;font-weight:700;color:var(--sub-text);letter-spacing:.8px;text-transform:uppercase;font-family:\'Space Grotesk\',\'Hind Siliguri\',sans-serif';
    if(unread.length>0){
      html+='<div style="'+labelStyle+'">New</div>';
      unread.forEach(function(n){html+=ntfItemHtml(n);});
    }
    if(read.length>0){
      html+='<div style="'+labelStyle+'">Earlier</div>';
      read.forEach(function(n){html+=ntfItemHtml(n);});
    }
  }
  el.innerHTML=html;
  ntfUpdateBadge();
}

