function grEntriesKey(){return '_grEntries_'+(grCurKid||'me');}

function grLoadEntries(){
  try{var d=localStorage.getItem(grEntriesKey());if(d){var p=JSON.parse(d);if(Array.isArray(p)&&p.length)return p;}}catch(e){}
  if(!grCurKid){
    return[
      {id:1,text:'আল্লাহ আমাদের সুস্থ পরিবার দিয়েছেন। রাফিয়া আজ প্রথমবার সূরা ইখলাস মুখস্থ করেছে।',mood:'happy',tags:['পরিবার','দ্বীন'],dateKey:grDateKey(),dateLabel:'আজ'},
      {id:2,text:'আল্লাহর শুকর যে আরিয়ান আজ নিজে থেকে ফজর নামাজের জন্য উঠেছে।',mood:'grateful',tags:['দ্বীন'],dateKey:(function(){var d=new Date();d.setDate(d.getDate()-1);return grDateKey(d);})(),dateLabel:'গতকাল'},
      {id:3,text:'আল্লাহ আমাদের খাদ্য দিয়েছেন। অনেক মানুষ আজ খেতে পায়নি।',mood:'calm',tags:['রিজক'],dateKey:(function(){var d=new Date();d.setDate(d.getDate()-2);return grDateKey(d);})(),dateLabel:'২ দিন আগে'}
    ];
  }
  return[];
}
function grSaveEntries(){try{localStorage.setItem(grEntriesKey(),JSON.stringify(grEntries));}catch(e){}}

function grBuildKidTabs(){
  var wrap=document.getElementById('gr-kid-tabs');if(!wrap)return;
  var kids=grGetKids();
  if(!kids||!kids.length){wrap.style.display='none';return;}
  wrap.style.display='block';
  wrap.innerHTML='';
  kids.forEach(function(k,i){
    var isActive=grCurKid===k.id;
    var color=_grTabColors[i%_grTabColors.length];
    var btn=document.createElement('button');
    btn.style.cssText='display:inline-flex;align-items:center;gap:7px;padding:8px 14px;border-radius:50px;border:2px solid '+(isActive?'#FF8A00':'var(--border,#e5e7eb)')+';background:'+(isActive?'rgba(255,138,0,.12)':'var(--card,#fff)')+';color:'+(isActive?'#FF8A00':'var(--text2,#666)')+';font-size:13px;font-weight:'+(isActive?'700':'500')+';cursor:pointer;font-family:inherit;white-space:nowrap;margin-right:8px;transition:.15s';
    var av=document.createElement('div');
    av.style.cssText='width:24px;height:24px;border-radius:50%;background:'+color+';display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:#fff;flex-shrink:0';
    av.textContent=(k.name||'?').charAt(0).toUpperCase();
    var lbl=document.createElement('span');lbl.textContent=k.name;
    btn.appendChild(av);btn.appendChild(lbl);
    btn.onclick=(function(id){return function(){grSwitchKid(id);};})(k.id);
    wrap.appendChild(btn);
  });
}

function grSwitchKid(kidId){
  grCurKid=kidId;
  grEntries=grLoadEntries();
  grSelectedTags=[];
  grCurrentMood='happy';
  grBuildKidTabs();
  grInitDate();
  grRefresh();
}
window.grSwitchKid=grSwitchKid;

function grCalcStreak(){
  var today=grDateKey();
  var streak=0;
  var d=new Date();
  while(true){
    var key=grDateKey(d);
    var hasEntry=grEntries.some(function(e){return e.dateKey===key;});
    if(!hasEntry)break;
    streak++;
    d.setDate(d.getDate()-1);
    if(streak>365)break;
  }
  return streak;
}

function grBuildAyat(){
  var idx=new Date().getDate()%_grAyat.length;
  var a=_grAyat[idx];
  var arEl=document.getElementById('gr-ayat-ar');
  var bnEl=document.getElementById('gr-ayat-bn');
  var srcEl=document.getElementById('gr-ayat-src');
  if(arEl)arEl.textContent=a.ar;
  if(bnEl)bnEl.textContent=a.bn;
  if(srcEl)srcEl.textContent=a.src;
}

function grBuildTagRow(){
  var row=document.getElementById('gr-tag-row');if(!row)return;
  row.innerHTML='';
  _grTags.forEach(function(t){
    var act=grSelectedTags.indexOf(t)>-1;
    var btn=document.createElement('button');
    btn.style.cssText='padding:5px 12px;border-radius:50px;border:1.5px solid '+(act?'#FF8A00':'rgba(255,255,255,.2)')+';background:'+(act?'rgba(255,138,0,.25)':'transparent')+';color:'+(act?'#FFB800':'rgba(255,255,255,.6)')+';font-size:11px;font-weight:'+(act?'700':'400')+';cursor:pointer;font-family:inherit;transition:.15s';
    btn.textContent=t;
    btn.onclick=(function(tag){return function(){
      var i=grSelectedTags.indexOf(tag);
      if(i>-1)grSelectedTags.splice(i,1);else grSelectedTags.push(tag);
      grBuildTagRow();
    };})(t);
    row.appendChild(btn);
  });
}

function grBuildMoodRow(){
  var row=document.getElementById('gr-mood-row');if(!row)return;
  row.innerHTML='';
  Object.keys(_grMoods).forEach(function(key){
    var m=_grMoods[key];
    var act=grCurrentMood===key;
    var btn=document.createElement('button');
    btn.style.cssText='display:flex;flex-direction:column;align-items:center;gap:5px;padding:10px 12px;border-radius:14px;border:2px solid '+(act?m.color:'var(--border,#e5e7eb)')+';background:'+(act?'rgba(255,138,0,.08)':'transparent')+';cursor:pointer;font-family:inherit;transition:.15s;min-width:56px';
    var ic=document.createElement('div');
    ic.style.cssText='width:28px;height:28px;color:'+(act?m.color:'var(--text2,#999)');
    ic.innerHTML=m.svg;
    var lb=document.createElement('span');
    lb.style.cssText='font-size:11px;font-weight:'+(act?'700':'500')+';color:'+(act?m.color:'var(--text2,#666)');
    lb.textContent=m.label;
    btn.appendChild(ic);btn.appendChild(lb);
    btn.onclick=(function(k){return function(){grCurrentMood=k;grBuildMoodRow();};})(key);
    row.appendChild(btn);
  });
}

function grBuildStreakCal(){
  var cal=document.getElementById('gr-streak-cal');if(!cal)return;
  cal.innerHTML='';
  var labelEl=document.getElementById('gr-week-count');
  var count=0;
  for(var i=6;i>=0;i--){
    var d=new Date();d.setDate(d.getDate()-i);
    var key=grDateKey(d);
    var isToday=(i===0);
    var hasEntry=grEntries.some(function(e){return e.dateKey===key;});
    if(hasEntry)count++;
    var cell=document.createElement('div');
    cell.style.cssText='display:flex;flex-direction:column;align-items:center;gap:4px';
    var dot=document.createElement('div');
    dot.style.cssText='width:100%;aspect-ratio:1;border-radius:8px;background:'+(hasEntry?'linear-gradient(135deg,#FF8A00,#FFB800)':isToday?'rgba(255,138,0,.2)':'var(--border,#f0f0f0)')+';border:'+(isToday&&!hasEntry?'2px dashed rgba(255,138,0,.4)':'none');
    if(hasEntry){
      dot.innerHTML='<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#090B12" stroke-width="3" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg></div>';
    }
    var dl=document.createElement('div');
    dl.style.cssText='font-size:9px;color:'+(isToday?'#FF8A00':'var(--text2,#aaa)')+';font-weight:'+(isToday?'700':'400');
    dl.textContent=_grBnDays[d.getDay()];
    cell.appendChild(dot);cell.appendChild(dl);
    cal.appendChild(cell);
  }
  if(labelEl)labelEl.textContent=count+'/7';
}

function grBuildMoodTrend(){
  var trend=document.getElementById('gr-mood-trend');
  var labels=document.getElementById('gr-mood-trend-labels');
  if(!trend)return;
  trend.innerHTML='';if(labels)labels.innerHTML='';
  for(var i=6;i>=0;i--){
    var d=new Date();d.setDate(d.getDate()-i);
    var key=grDateKey(d);
    var entry=null;
    for(var j=0;j<grEntries.length;j++){if(grEntries[j].dateKey===key){entry=grEntries[j];break;}}
    var col=document.createElement('div');
    col.style.cssText='display:flex;flex-direction:column;justify-content:flex-end;height:100%';
    var bar=document.createElement('div');
    var moodH={happy:100,grateful:85,hopeful:75,calm:60,tired:35};
    var h=entry?(moodH[entry.mood]||50):0;
    var mColor=entry?(_grMoods[entry.mood]||{color:'#FF8A00'}).color:'var(--border,#e8e8e8)';
    bar.style.cssText='width:100%;height:'+h+'%;border-radius:6px 6px 0 0;background:'+mColor+';opacity:'+(entry?'1':'.4')+';min-height:4px;transition:.4s';
    bar.title=entry?(_grMoods[entry.mood]||{label:''}).label:'';
    col.appendChild(bar);trend.appendChild(col);
    if(labels){
      var lb=document.createElement('div');
      var isToday=(i===0);
      lb.style.cssText='font-size:9px;text-align:center;color:'+(isToday?'#FF8A00':'var(--text2,#aaa)')+';font-weight:'+(isToday?'700':'400');
      lb.textContent=_grBnDays[d.getDay()];
      labels.appendChild(lb);
    }
  }
}

function grRenderEntries(){
  var el=document.getElementById('gr-entries');if(!el)return;
  el.innerHTML='';
  var countEl=document.getElementById('gr-entry-count');
  if(countEl)countEl.textContent=grEntries.length+' টি লেখা';
  if(!grEntries.length){
    el.innerHTML='<div style="text-align:center;padding:24px;color:var(--text2,#aaa);font-size:13px">এখনো কোনো entry নেই</div>';
    return;
  }
  grEntries.forEach(function(e,idx){
    var m=_grMoods[e.mood]||_grMoods.happy;
    var card=document.createElement('div');
    card.style.cssText='background:var(--border,#fafafa);border-radius:14px;padding:14px;border:1px solid var(--border,#f0f0f0);margin-bottom:10px';
    // Header row
    var hd=document.createElement('div');hd.style.cssText='display:flex;align-items:center;gap:8px;margin-bottom:8px';
    var ic=document.createElement('div');
    ic.style.cssText='width:28px;height:28px;border-radius:8px;background:'+(m.color.replace('#','rgba(').replace(/^rgba\(([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})\)$/i,function(_,r,g,b){return 'rgba('+parseInt(r,16)+','+parseInt(g,16)+','+parseInt(b,16)+',.12)';})||'rgba(255,138,0,.12)')+';display:flex;align-items:center;justify-content:center;flex-shrink:0;color:'+m.color;
    ic.innerHTML='<div style="width:16px;height:16px">'+m.svg+'</div>';
    var moodLbl=document.createElement('span');
    moodLbl.style.cssText='font-size:11px;font-weight:700;color:'+m.color;
    moodLbl.textContent=m.label;
    var dt=document.createElement('span');
    dt.style.cssText='font-size:11px;color:var(--text2,#aaa);font-weight:500;margin-left:auto';
    dt.textContent=e.dateLabel||e.dateKey;
    var dlBtn=document.createElement('button');
    dlBtn.style.cssText='width:24px;height:24px;border-radius:6px;border:none;background:rgba(239,68,68,.1);color:#ef4444;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0';
    dlBtn.innerHTML='<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
    dlBtn.onclick=(function(id){return function(){grEntries=grEntries.filter(function(x){return x.id!==id;});grSaveEntries();grRefresh();};})(e.id);
    hd.appendChild(ic);hd.appendChild(moodLbl);hd.appendChild(dt);hd.appendChild(dlBtn);
    // Text
    var txt=document.createElement('p');
    txt.style.cssText='font-size:13px;color:var(--text,#444);line-height:1.6;margin:0 0 8px';
    txt.textContent=e.text;
    card.appendChild(hd);card.appendChild(txt);
    // Tags
    if(e.tags&&e.tags.length){
      var tagRow=document.createElement('div');tagRow.style.cssText='display:flex;gap:5px;flex-wrap:wrap';
      e.tags.forEach(function(t){
        var tb=document.createElement('span');
        tb.style.cssText='font-size:10px;background:rgba(255,138,0,.1);color:#FF8A00;padding:2px 8px;border-radius:50px;font-weight:600;border:1px solid rgba(255,138,0,.2)';
        tb.textContent=t;tagRow.appendChild(tb);
      });
      card.appendChild(tagRow);
    }
    el.appendChild(card);
  });
}

function grUpdateStats(){
  var streak=grCalcStreak();
  var el=document.getElementById('gr-streak');if(el)el.textContent=streak;
  var el2=document.getElementById('gr-streak2');if(el2)el2.textContent=streak;
  var tot=document.getElementById('gr-total');if(tot)tot.textContent=grEntries.length;
  var now=new Date();
  var weekStart=new Date(now);weekStart.setDate(now.getDate()-now.getDay());
  var weekCount=grEntries.filter(function(e){
    var d=new Date(e.dateKey);return d>=weekStart;
  }).length;
  var wk=document.getElementById('gr-this-week');if(wk)wk.textContent=weekCount;
  // streak box animation
  var box=document.getElementById('gr-streak-box');
  if(box){
    box.style.background=streak>=7?'rgba(255,184,0,.15)':streak>0?'rgba(255,138,0,.1)':'rgba(255,138,0,.08)';
    box.style.borderColor=streak>=7?'rgba(255,184,0,.4)':'rgba(255,138,0,.25)';
  }
}

function grRefresh(){
  grUpdateStats();
  grBuildStreakCal();
  grBuildMoodTrend();
  grRenderEntries();
}

function grSaveToday(){
  var inp=document.getElementById('gr-today-input');
  if(!inp||!inp.value.trim()){alert('লিখুন!');return;}
  var now=new Date();
  var todayKey=grDateKey();
  // Remove existing entry for today if any
  grEntries=grEntries.filter(function(e){return e.dateKey!==todayKey;});
  grEntries.unshift({
    id:Date.now(),
    text:inp.value.trim(),
    mood:grCurrentMood,
    tags:grSelectedTags.slice(),
    dateKey:todayKey,
    dateLabel:'আজ'
  });
  inp.value='';
  grSelectedTags=[];
  grBuildTagRow();
  grSaveEntries();
  grRefresh();
  // Save confirmation
  var btn=document.getElementById('gr-save-btn');
  if(btn){
    btn.innerHTML='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg> শুকর সংরক্ষিত হয়েছে!';
    setTimeout(function(){btn.innerHTML='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z"/></svg> শুকর লিখুন';},2000);
  }
}
window.grSaveToday=grSaveToday;

function grInitDate(){
  var now=new Date();
  var el=document.getElementById('gr-date');
  if(el)el.textContent=now.getDate()+'/'+(now.getMonth()+1)+'/'+now.getFullYear();
  // Pre-fill today's entry if exists
  var todayKey=grDateKey();
  var todayEntry=grEntries.find(function(e){return e.dateKey===todayKey;});
  var inp=document.getElementById('gr-today-input');
  if(inp&&todayEntry){inp.value=todayEntry.text;grCurrentMood=todayEntry.mood;grSelectedTags=todayEntry.tags||[];}
}

var _grOrig=window.showPage;
window.showPage=function(page){
  _grOrig(page);
  if(page==='gratitude')setTimeout(function(){
    var doRender=function(){
      var kids=grGetKids();
      if(kids&&kids.length&&grCurKid===null){grCurKid=kids[0].id;}
      grEntries=grLoadEntries();
      grBuildKidTabs();
      grInitDate();
      grBuildAyat();
      grBuildTagRow();
      grBuildMoodRow();
      grRefresh();
    };
    if(window.sbUser&&window._sb&&typeof rzLoadKids==='function'){
      rzLoadKids().then(doRender);
    }else{doRender();}
  },50);
};
/* ── Adult Gratitude Journal ─────────────────────────────────────────────── */
var _graEntries=[];
var _graMood='happy';
var _graTags=[];

var _graMoods={
  happy:   {label:'খুশি',   emoji:'😊'},
  grateful:{label:'কৃতজ্ঞ', emoji:'🤲'},
  hopeful: {label:'আশাবাদী',emoji:'🌱'},
  calm:    {label:'শান্ত',  emoji:'🕊️'},
  tired:   {label:'ক্লান্ত', emoji:'😌'}
};
var _graTagsList=['দ্বীন','পরিবার','স্বাস্থ্য','রিজক','বন্ধু','শিক্ষা','কাজ','অন্যান্য'];
var _graAreaColors={দ্বীন:'#8B5CF6',পরিবার:'#F59E0B',স্বাস্থ্য:'#10B981',রিজক:'#3B82F6',বন্ধু:'#EC4899',শিক্ষা:'#06B6D4',কাজ:'#FF8A00',অন্যান্য:'#6B7280'};

function graKey(){return '_graEntries_v1';}
function graLoad(){try{var d=localStorage.getItem(graKey());if(d)return JSON.parse(d)||[];}catch(e){}return [];}
function graSave(){try{localStorage.setItem(graKey(),JSON.stringify(_graEntries));}catch(e){}}

function graSetMood(key){_graMood=key;graRenderMoodRow();}
window.graSetMood=graSetMood;

function graToggleTag(t){var i=_graTags.indexOf(t);if(i>-1)_graTags.splice(i,1);else _graTags.push(t);graRenderTagRow();}
window.graToggleTag=graToggleTag;

function graRenderMoodRow(){
  var row=document.getElementById('gra-mood-row');if(!row)return;
  row.innerHTML='';
  Object.keys(_graMoods).forEach(function(key){
    var m=_graMoods[key];var act=_graMood===key;
    var btn=document.createElement('button');
    btn.onclick=function(){graSetMood(key);};
    btn.style.cssText='padding:8px 14px;border-radius:50px;border:1.5px solid '+(act?'#FF8A00':'var(--border,#e5e7eb)')+';background:'+(act?'rgba(255,138,0,.12)':'transparent')+';color:'+(act?'#FF8A00':'var(--text2,#888)')+';font-size:12px;font-weight:'+(act?'700':'500')+';cursor:pointer;font-family:inherit;display:flex;align-items:center;gap:5px;transition:.15s';
    btn.innerHTML='<span style="font-size:15px">'+m.emoji+'</span><span>'+m.label+'</span>';
    row.appendChild(btn);
  });
}

function graRenderTagRow(){
  var row=document.getElementById('gra-tag-row');if(!row)return;
  row.innerHTML='';
  _graTagsList.forEach(function(t){
    var act=_graTags.indexOf(t)>-1;
    var btn=document.createElement('button');
    btn.onclick=function(){graToggleTag(t);};
    btn.style.cssText='padding:6px 12px;border-radius:50px;border:1.5px solid '+(act?(_graAreaColors[t]||'#FF8A00'):'var(--border,#e5e7eb)')+';background:'+(act?'rgba(255,138,0,.1)':'transparent')+';color:'+(act?(_graAreaColors[t]||'#FF8A00'):'var(--text2,#888)')+';font-size:12px;font-weight:'+(act?'700':'500')+';cursor:pointer;font-family:inherit;transition:.15s';
    btn.textContent=t;
    row.appendChild(btn);
  });
}

function graBuildJar(){
  var total=_graEntries.length;
  var fill=Math.min(total/30,1);
  var fillEl=document.getElementById('gra-jar-fill');
  var ripple=document.getElementById('gra-jar-ripple');
  if(fillEl){
    var fillH=Math.round(fill*90); // 90px max fill (y=42 to y=132)
    var fillY=132-fillH;
    fillEl.setAttribute('y',fillY);
    fillEl.setAttribute('height',fillH);
    if(ripple){ripple.setAttribute('y1',fillY);ripple.setAttribute('y2',fillY);}
  }
  var pctEl=document.getElementById('gra-jar-pct');
  if(pctEl)pctEl.textContent=Math.round(fill*100)+'%';
  var lbl=document.getElementById('gra-jar-label');
  if(lbl){
    if(fill===0)lbl.textContent='শুরু করো...';
    else if(fill<0.3)lbl.textContent='ভরতে শুরু হয়েছে!';
    else if(fill<0.6)lbl.textContent='ভরে আসছে! 🌟';
    else if(fill<1)lbl.textContent='প্রায় পূর্ণ! ✨';
    else lbl.textContent='পূর্ণ বরকত! 🤲';
  }
}

function graBuildHeatmap(){
  var el=document.getElementById('gra-heatmap');if(!el)return;
  el.innerHTML='';
  var now=new Date();
  var year=now.getFullYear(),month=now.getMonth(),today=now.getDate();
  var daysInMonth=new Date(year,month+1,0).getDate();
  var entryDays={};
  _graEntries.forEach(function(e){
    var d=new Date(e.createdAt);
    if(d.getFullYear()===year&&d.getMonth()===month)entryDays[d.getDate()]=true;
  });
  var monthNames=['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
  var hdr=document.createElement('div');
  hdr.style.cssText='display:flex;justify-content:space-between;align-items:center;margin-bottom:10px';
  hdr.innerHTML='<span style="font-size:13px;font-weight:700;color:var(--text,#1a1a2e)">'+monthNames[month]+' '+year+'</span><span style="font-size:12px;color:#FF8A00;font-weight:700;background:rgba(255,138,0,.1);padding:3px 10px;border-radius:50px">'+Object.keys(entryDays).length+'/'+today+' দিন</span>';
  el.appendChild(hdr);
  var labelsRow=document.createElement('div');
  labelsRow.style.cssText='display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-bottom:5px';
  ['রবি','সোম','মঙ্গ','বুধ','বৃহ','শুক্র','শনি'].forEach(function(d){
    var lbl=document.createElement('div');
    lbl.style.cssText='text-align:center;font-size:9px;color:var(--text2,#aaa);font-weight:600;padding:2px 0';
    lbl.textContent=d;labelsRow.appendChild(lbl);
  });
  el.appendChild(labelsRow);
  var grid=document.createElement('div');
  grid.style.cssText='display:grid;grid-template-columns:repeat(7,1fr);gap:4px';
  var firstDay=new Date(year,month,1).getDay();
  for(var i=0;i<firstDay;i++){var emp=document.createElement('div');emp.style.cssText='aspect-ratio:1;';grid.appendChild(emp);}
  for(var day=1;day<=daysInMonth;day++){
    var cell=document.createElement('div');
    var isFuture=day>today,hasEntry=entryDays[day],isToday=day===today;
    var bg=isFuture?'var(--bg,#f3f4f6)':hasEntry?'linear-gradient(135deg,#FF8A00,#FFB800)':'var(--border,#e5e7eb)';
    cell.style.cssText='aspect-ratio:1;border-radius:5px;background:'+bg+';display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:600;color:'+(hasEntry?'#090B12':isFuture?'transparent':'var(--text2,#bbb)')+(isToday?';outline:2px solid #FF8A00;outline-offset:1px':'')+';cursor:'+(isFuture?'default':'pointer')+';transition:.2s';
    cell.textContent=day;
    if(!isFuture)cell.title=hasEntry?day+' তারিখে লিখেছ':day+' তারিখে লেখা হয়নি';
    grid.appendChild(cell);
  }
  el.appendChild(grid);
}

function graBuildAreaBars(){
  var el=document.getElementById('gra-area-bars');if(!el)return;
  el.innerHTML='';
  var counts={};
  _graTagsList.forEach(function(a){counts[a]=0;});
  _graEntries.forEach(function(e){
    if(Array.isArray(e.tags))e.tags.forEach(function(t){if(counts.hasOwnProperty(t))counts[t]++;});
  });
  var max=Math.max.apply(null,_graTagsList.map(function(a){return counts[a];}));
  if(!max){
    el.innerHTML='<div style="text-align:center;color:var(--text2,#aaa);font-size:13px;padding:16px 0">এখনো tag করা হয়নি</div>';
    return;
  }
  _graTagsList.forEach(function(a){
    if(!counts[a])return;
    var row=document.createElement('div');row.style.cssText='margin-bottom:11px';
    var labelRow=document.createElement('div');
    labelRow.style.cssText='display:flex;justify-content:space-between;align-items:center;margin-bottom:5px';
    labelRow.innerHTML='<span style="font-size:13px;font-weight:600;color:var(--text,#1a1a2e)">'+a+'</span><span style="font-size:11px;color:var(--text2,#888)">'+counts[a]+'টি</span>';
    var track=document.createElement('div');
    track.style.cssText='height:8px;background:var(--border,#e5e7eb);border-radius:50px;overflow:hidden';
    var fill=document.createElement('div');
    fill.style.cssText='height:100%;width:'+Math.round(counts[a]/max*100)+'%;background:'+(_graAreaColors[a]||'#FF8A00')+';border-radius:50px;transition:width .8s cubic-bezier(.4,0,.2,1)';
    track.appendChild(fill);row.appendChild(labelRow);row.appendChild(track);el.appendChild(row);
  });
}

function graUpdateStats(){
  var total=_graEntries.length;
  var tEl=document.getElementById('gra-total');if(tEl)tEl.textContent=total;
  var now=new Date(),streak=0;
  for(var i=0;i<365;i++){
    var d=new Date(now.getFullYear(),now.getMonth(),now.getDate()-i);
    var found=_graEntries.some(function(e){var ed=new Date(e.createdAt);return ed.getFullYear()===d.getFullYear()&&ed.getMonth()===d.getMonth()&&ed.getDate()===d.getDate();});
    if(found)streak++;else if(i>0)break;
  }
  var sEl=document.getElementById('gra-streak');
  if(sEl)sEl.innerHTML='<svg width="12" height="12" viewBox="0 0 24 24" fill="#FF8A00"><path d="M12 2C8.5 7 6 10 6 14a6 6 0 0012 0c0-4-2.5-7-6-12z"/></svg>'+streak;
  var weekStart=new Date(now);weekStart.setDate(now.getDate()-now.getDay());weekStart.setHours(0,0,0,0);
  var thisWeek=_graEntries.filter(function(e){return new Date(e.createdAt)>=weekStart;}).length;
  var wEl=document.getElementById('gra-week');if(wEl)wEl.textContent=thisWeek;
  var ecEl=document.getElementById('gra-entry-count');if(ecEl)ecEl.textContent=total+'টি entry';
}

function graRenderEntries(){
  var el=document.getElementById('gra-entries');if(!el)return;
  el.innerHTML='';
  if(!_graEntries.length){
    el.innerHTML='<div style="text-align:center;padding:28px;color:var(--text2,#aaa);font-size:13px">এখনো কোনো লেখা নেই। আজ থেকে শুরু করো!</div>';
    return;
  }
  _graEntries.slice(0,20).forEach(function(e){
    var card=document.createElement('div');
    card.style.cssText='background:var(--bg,#fafafa);border:1px solid var(--border,#f0f0f0);border-radius:14px;padding:14px;margin-bottom:10px';
    var d=new Date(e.createdAt);
    var dateStr=d.getDate()+'/'+(d.getMonth()+1)+'/'+d.getFullYear();
    var moodEmoji=(_graMoods[e.mood]||{emoji:'😊'}).emoji;
    var texts=[];
    if(e.p1)texts.push({icon:'🌟',text:e.p1});
    if(e.p2)texts.push({icon:'✨',text:e.p2});
    if(e.p3)texts.push({icon:'🤲',text:e.p3});
    if(!texts.length&&e.text)texts.push({icon:'📝',text:e.text});
    card.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">'
      +'<span style="font-size:11px;color:var(--text2,#888)">📅 '+dateStr+'</span>'
      +'<div style="display:flex;align-items:center;gap:6px">'
      +(e.mood?'<span style="font-size:16px">'+moodEmoji+'</span>':'')
      +'<button onclick="graDelete('+e.createdAt+')" style="width:22px;height:22px;border-radius:50%;border:none;background:rgba(239,68,68,.1);color:#ef4444;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:14px;line-height:1">×</button>'
      +'</div></div>'
      +texts.map(function(t,i){return '<div style="font-size:13px;color:var(--text,#1a1a2e);line-height:1.6;padding-left:8px;border-left:2px solid rgba(255,138,0,.3);margin-bottom:'+(i<texts.length-1?'8':'0')+'px">'+t.icon+' '+t.text+'</div>';}).join('')
      +(e.tags&&e.tags.length?'<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:10px">'+e.tags.map(function(t){return '<span style="padding:3px 8px;border-radius:50px;background:rgba(255,138,0,.1);color:#FF8A00;font-size:10px;font-weight:600">'+t+'</span>';}).join('')+'</div>':'');
    el.appendChild(card);
  });
}

function graDelete(createdAt){
  _graEntries=_graEntries.filter(function(e){return e.createdAt!==createdAt;});
  graSave();graRender();
}
window.graDelete=graDelete;

function graSaveTodayAdult(){
  var p1=((document.getElementById('gra-p1')||{}).value||'').trim();
  var p2=((document.getElementById('gra-p2')||{}).value||'').trim();
  var p3=((document.getElementById('gra-p3')||{}).value||'').trim();
  if(!p1&&!p2&&!p3){alert('অন্তত একটি প্রশ্নের উত্তর লিখুন!');return;}
  var entry={createdAt:Date.now(),p1:p1,p2:p2,p3:p3,mood:_graMood,tags:_graTags.slice()};
  _graEntries.unshift(entry);
  graSave();
  ['gra-p1','gra-p2','gra-p3'].forEach(function(id){var el=document.getElementById(id);if(el)el.value='';});
  _graTags=[];_graMood='happy';
  graRender();
  var btn=document.getElementById('gra-save-btn');
  if(btn){var orig=btn.innerHTML;btn.innerHTML='✓ সংরক্ষিত হয়েছে!';btn.style.background='linear-gradient(135deg,#10B981,#059669)';setTimeout(function(){btn.innerHTML=orig;btn.style.background='';},2000);}
}
window.graSaveTodayAdult=graSaveTodayAdult;

function graRender(){
  _graEntries=graLoad();
  graUpdateStats();
  graBuildJar();
  graBuildHeatmap();
  graBuildAreaBars();
  graRenderMoodRow();
  graRenderTagRow();
  graRenderEntries();
}
window.graRender=graRender;
