function refRenderMilestones(){
  var el=document.getElementById('ref-milestones');if(!el)return;el.innerHTML='';
  var cnt=refGetCount();
  refMilestones.forEach(function(m,i){
    var done=cnt>=m.count;
    var prev=i===0?0:refMilestones[i-1].count;
    var progress=done?100:Math.min(100,Math.round(((cnt-prev)/(m.count-prev))*100));
    var row=document.createElement('div');
    row.style.cssText='padding:14px 0;border-bottom:1px solid var(--border,#f0f0f0);'+(i===refMilestones.length-1?'border-bottom:none':'');
    var top=document.createElement('div');top.style.cssText='display:flex;align-items:center;gap:10px;margin-bottom:8px';
    var ic=document.createElement('div');
    ic.style.cssText='width:36px;height:36px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0;background:'+(done?'rgba(255,138,0,.15)':'rgba(0,0,0,.06)');
    ic.innerHTML=m.badge;
    var info=document.createElement('div');info.style.flex='1';
    var nm=document.createElement('div');nm.style.cssText='font-size:13px;font-weight:700;color:'+(done?'var(--text,#1a1a2e)':'var(--text2,#888)');nm.textContent=m.label;
    var sub=document.createElement('div');sub.style.cssText='font-size:11px;color:var(--text2,#888);margin-top:1px';
    sub.textContent=m.count+' জন refer → +'+m.rzc.toLocaleString()+' Reys'+(m.bonus?' + '+m.bonus+' bonus':'');
    info.appendChild(nm);info.appendChild(sub);
    var badge2=document.createElement('span');
    if(done){badge2.innerHTML='<span style="background:rgba(255,138,0,.15);color:#FF8A00;padding:4px 10px;border-radius:50px;font-size:11px;font-weight:700">&#10003; Done</span>';}
    else{badge2.innerHTML='<span style="background:rgba(0,0,0,.06);color:var(--text2,#888);padding:4px 10px;border-radius:50px;font-size:11px;font-weight:600">'+cnt+'/'+m.count+'</span>';}
    top.appendChild(ic);top.appendChild(info);top.appendChild(badge2);
    if(!done){
      var bar=document.createElement('div');bar.style.cssText='height:4px;background:var(--border,#f0f0f0);border-radius:50px;overflow:hidden';
      var fill=document.createElement('div');fill.style.cssText='height:100%;width:'+progress+'%;background:linear-gradient(90deg,#FF8A00,#FFB800);border-radius:50px;transition:width .6s ease';
      bar.appendChild(fill);row.appendChild(top);row.appendChild(bar);
    }else{row.appendChild(top);}
    el.appendChild(row);
  });
}

