function refRenderProof(){
  var av=document.getElementById('ref-proof-avatars');var tx=document.getElementById('ref-proof-text');var td=document.getElementById('ref-today-count');
  var names=['রা','আ','সা','না','ফা','মা','রু','কা'];
  var colors=['#FF8A00','#8B5CF6','#3B82F6','#10B981','#EF4444','#F59E0B','#06B6D4','#EC4899'];
  if(av){
    av.innerHTML='';
    for(var i=0;i<6;i++){
      var d=document.createElement('div');
      d.style.cssText='width:32px;height:32px;border-radius:50%;background:'+colors[i]+';border:2px solid var(--card,#fff);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#fff;margin-left:'+(i===0?'0':'-8px');
      d.textContent=names[i];av.appendChild(d);
    }
  }
  var todayCount=42+(new Date().getDate()%16);
  if(td)td.textContent=todayCount;
  if(tx)tx.textContent='আজকে '+todayCount+' জন নতুন member join করেছে Rizers এ!';
}

