  _pcActiveVideo=v;_pcLiked=false;_pcDescExpanded=false;
  var modal=document.getElementById('pc-video-modal');if(!modal)return;
  modal.style.display='block';
  modal.style.transform='translateY(100%)';
  modal.style.transition='transform .32s cubic-bezier(.4,0,.2,1)';
  document.body.style.overflow='hidden';
  setTimeout(function(){modal.style.transform='translateY(0)';},10);
  var catColors={parenting:'rgba(255,138,0,.18)',islamic:'rgba(124,58,237,.18)',habit:'rgba(255,184,0,.18)',live:'rgba(239,68,68,.18)'};
