  var cb=document.getElementById('pc-vid-cat-badge');if(cb){cb.textContent=catLabel[v.cat]||v.cat;cb.style.background=catColors[v.cat]||catColors.parenting;cb.style.color=catText[v.cat]||'#FF8A00';}
  var db=document.getElementById('pc-vid-dur-badge');if(db)db.textContent=v.dur;
  var dm=document.getElementById('pc-vid-desc-meta');if(dm)dm.textContent=v.views+' views • 4 days ago • #islamicparenting';
  var di=document.getElementById('pc-vid-desc-inner');if(di){di.style.webkitLineClamp='2';di.style.overflow='hidden';}
  var dt=document.getElementById('pc-vid-desc-toggle');if(dt)dt.textContent='…আরো দেখুন';
  var lk=document.getElementById('pc-vid-likes');if(lk)lk.textContent='587';
  var lb=document.getElementById('pc-vid-like-btn');if(lb){lb.style.color='#fff';}
  pcVidRefreshSaveBtn();
  var prog=document.getElementById('pc-vid-progress');
  if(prog){prog.style.transition='none';prog.style.width='0%';setTimeout(function(){var mins=parseInt(v.dur)||8;prog.style.transition='width '+(mins*60)+'s linear';prog.style.width='100%';},80);}
  _pcVidFilter='all';
  pcRenderVidTabs();pcRenderSuggestions();
