function pcRenderVidTabs(){
  var el=document.getElementById('pc-vid-tabs');if(!el)return;el.innerHTML='';
  var tabs=[{key:'all',label:'সব'},{key:'parenting',label:'Parenting'},{key:'islamic',label:'Islamic'},{key:'habit',label:'Habit'},{key:'live',label:'Live'}];
  tabs.forEach(function(tab){
    var btn=document.createElement('button');
    var act=_pcVidFilter===tab.key;
    btn.style.cssText='padding:7px 16px;border-radius:6px;border:none;background:'+(act?'#fff':'rgba(255,255,255,.12)')+';color:'+(act?'#0f0f0f':'#fff')+';font-size:12px;font-weight:'+(act?'700':'500')+';cursor:pointer;font-family:inherit;white-space:nowrap;flex-shrink:0';
    btn.textContent=tab.label;
    btn.onclick=(function(k){return function(){_pcVidFilter=k;pcRenderVidTabs();pcRenderSuggestions();};})(tab.key);
    el.appendChild(btn);
  });
}
function pcRenderSuggestions(){
  var el=document.getElementById('pc-vid-suggestions');if(!el||!_pcActiveVideo)return;el.innerHTML='';
  var watched=pcGetWatched();
  var catColors={parenting:'rgba(255,138,0,.18)',islamic:'rgba(124,58,237,.18)',habit:'rgba(255,184,0,.18)',live:'rgba(239,68,68,.18)'};
  var catText={parenting:'#FF8A00',islamic:'#a78bfa',habit:'#d97706',live:'#f87171'};
  var catLabel={parenting:'Parenting',islamic:'Islamic',habit:'Habit',live:'Live'};
  var list=pcVideos.filter(function(v){return v.id!==_pcActiveVideo.id;});
  if(_pcVidFilter!=='all')list=list.filter(function(v){return v.cat===_pcVidFilter;});
  if(!list.length){var em=document.createElement('div');em.style.cssText='text-align:center;padding:30px;color:#555;font-size:13px';em.textContent='এই category তে আর কোনো ভিডিও নেই';el.appendChild(em);return;}
  list.forEach(function(v){
    var isW=watched.indexOf(v.id)>-1;
    var row=document.createElement('div');
    row.style.cssText='display:flex;gap:10px;margin-bottom:14px;cursor:pointer;align-items:flex-start';
    row.onclick=(function(id){return function(){pcOpenVideo(id);};})(v.id);
    var th=document.createElement('div');
    th.style.cssText='width:120px;height:68px;background:#1e1e1e;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0;position:relative;overflow:hidden';
    th.innerHTML=pcIcon(v.thumb,28,isW?'#FF8A00':'#555');
    var dp=document.createElement('span');dp.style.cssText='position:absolute;bottom:5px;right:5px;background:rgba(0,0,0,.9);color:#fff;font-size:10px;font-weight:700;padding:1px 5px;border-radius:3px';dp.textContent=v.dur;th.appendChild(dp);
    if(isW){var wb=document.createElement('div');wb.style.cssText='position:absolute;top:5px;right:5px;background:#FF8A00;color:#090B12;font-size:9px;font-weight:700;width:16px;height:16px;border-radius:50%;display:flex;align-items:center;justify-content:center';wb.textContent='✓';th.appendChild(wb);}
    if(v.new_&&!isW){var nb2=document.createElement('div');nb2.style.cssText='position:absolute;top:5px;left:5px;background:#EF4444;color:#fff;font-size:8px;font-weight:700;padding:1px 5px;border-radius:4px';nb2.textContent='NEW';th.appendChild(nb2);}
    var info=document.createElement('div');info.style.cssText='flex:1;min-width:0';
    var tt=document.createElement('div');tt.style.cssText='font-size:13px;font-weight:600;color:'+(isW?'#FF8A00':'#fff')+';line-height:1.4;margin-bottom:4px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden';tt.textContent=v.title;
    var ch=document.createElement('div');ch.style.cssText='font-size:12px;color:#aaa;margin-bottom:2px';ch.textContent='Tayef Vai';
    var st=document.createElement('div');st.style.cssText='font-size:11px;color:#777;display:flex;align-items:center;gap:6px;margin-bottom:4px';
    st.innerHTML='<span>'+v.views+' views</span><span style="color:#444">•</span><span>'+v.dur+'</span>';
    var ct=document.createElement('span');ct.style.cssText='font-size:10px;padding:2px 7px;border-radius:4px;font-weight:700;background:'+(catColors[v.cat]||catColors.parenting)+';color:'+(catText[v.cat]||'#FF8A00');ct.textContent=catLabel[v.cat]||v.cat;
    info.appendChild(tt);info.appendChild(ch);info.appendChild(st);info.appendChild(ct);
    row.appendChild(th);row.appendChild(info);el.appendChild(row);
  });
}
