var stData=[{id:1,cat:'islamic',title:'নবীজির শিশুকাল',sub:'মুহাম্মদ (সা.) শিশুকালে কী শিখেছিলেন',dur:8,reads:245,cl:'Islamic',icon:'&#9733;',bk:true,read:true,body:'মুহাম্মদ (সা.) শিশুকাল৅ মতিম পিতাকে হারিয়েছিলেন। তাঁর মা আমিনা তাঁকে বুকে ধরে নিতেন। প্রতিদিন মার সাথে কুরআন শিখতেন। ছোট বেলায় তিনি সবসময় সত্য কথা বলতেন। প্রতিবেশীরা তাঁকে আল-আমিন (বিশ্বস্ত) বলতেন। তাঁর ভেতরে তখন থেকেই ছিল মানুষের প্রতি ভালোবাসা। আমরাও সত্য বলব, মানুষকে ভালোবাসব — এটাই তাঁর সবচেয়ে বড় শিক্ষা।',quiz:{q:'নবীজিকে নিয়ে প্রতিবেশীরা কী বলতেন?',opts:['আল-আমিন','রাসূল','হাবিব','সাহাবী'],ans:0}},{id:2,cat:'moral',title:'সত্যের পুরস্কার',sub:'মিথ্যা বললে কি হয়?',dur:5,reads:312,cl:'নৈতিক',icon:'&#127775;',bk:true,read:true,body:'আরিয়ান রাস্তায় একটি বাক্স পেল। ভেতরে টাকা। নিয়ে যাওয়ার প্রলোভন হলো। কিন্তু আল্লাহর ভয়ে থানায় দিয়ে আসল। বাড়ি ফিরে মা জড়িয়ে ধরলেন। আল্লাহ সত্যবাদীকে ভালোবাসেন। সাদা মন হলো সবচেয়ে বড় পুরস্কার।',quiz:{q:'আরিয়ান বাক্স পাওয়ার পর কি করল?',opts:['টাকা নিল','থানায় দিল','লুকিয়ে রাখল','বন্ধুকে দিল'],ans:1}},{id:3,cat:'adventure',title:'মসজিদের পথে',sub:'এক শিশুর সাহসী যাত্রা',dur:12,reads:189,cl:'Adventure',icon:'&#127758;',bk:true,read:false,body:'রাফিয়া মাত্র 8 বছর বয়সেই সিদ্ধান্ত নিল। বাজারে যাওয়ার পথে সে আজান শুনল। সে মাকে বলল — মা, আমরা কি প্রথমে নামাজ পড়তে যেতে পারি? মা হাসলেন ও রাফিয়ার হাত ধরলেন। সেই দিন থেকে রাফিয়া প্রতিদিন মসজিদে যায়।',quiz:{q:'রাফিয়া কি শুনল?',opts:['পাখির গান','আজান','বাজারের শব্দ','গাড়ির শব্দ'],ans:1}},{id:4,cat:'moral',title:'ভাগাভাগির বরকত',sub:'বন্ধুত্ব ও ভাগাভাগি',dur:6,reads:201,cl:'নৈতিক',icon:'&#128149;',bk:false,read:false,body:'আরিয়ান তার প্রিয় টিফিন দুভাগ করে বন্ধুকে দিল। বন্ধুর চোখ ভিজে গেল। আল্লাহ বলেন — যে ভাগাভাগি করে তার রিজিক বাড়ে। ভাগাভাগির মধ্যে বরকত আসে।',quiz:{q:'আরিয়ান বন্ধুকে কী দিল?',opts:['টাকা','ফুল','স্যান্ডওয়িচ','বই'],ans:2}},{id:5,cat:'islamic',title:'মিরাজের রাত',sub:'নাবীজির অবিশ্বাস্য যাত্রা',dur:10,reads:298,cl:'Islamic',icon:'&#9728;',bk:false,read:false,body:'সেই রাতে আল্লাহ তাঁর প্রিয় নবীকে আরশ পর্যন্ত নিয়ে গেলেন। সেই দিন থেকে নামাজ ফরজ হয়েছিল। প্রতিদিন পাঁচবার নামাজ পড়া হলো আল্লাহর সাথে সবচেয়ে কাছে যাওয়ার সুযোগ।',quiz:{q:'মিরাজে কোন ইবাদত ফরজ হয়?',opts:['রোজা','নামাজ','হজ','যাকাত'],ans:1}}];
