function rwRedeem(cost,type){
  var bal=rwGetBalance();
  if(bal<cost){
    alert('পর্যাপ্ত RZC নেই। আপনার কাছে আছে '+bal+' RZC, দরকার '+cost+' RZC');
    return;
  }
  var label=type==='month'?'১ মাস':'১ সপ্তাহ';
  if(confirm(cost+' RZC দিয়ে '+label+' Subscription নেবেন?')){
    localStorage.setItem('_rzc_balance',bal-cost);
    alert('✅ সফল! '+label+' Subscription activate হয়েছে।');
    rwRenderWallet();
  }
}
window.rwRedeem=rwRedeem;

