var _catOrig = window.showPage;
window.showPage = function(page) {
  _catOrig(page);
  // Map page to category
  var catMap = {
    habits:'cat-trackers', namaz:'cat-trackers', quran:'cat-trackers',
    sleep:'cat-trackers', study:'cat-trackers', reading:'cat-trackers', screentime:'cat-trackers',
    stories:'cat-content', dua:'cat-content', hadith:'cat-content', parents:'cat-content', islamic:'cat-content',
    kids:'cat-kids', routine:'cat-kids', goals:'cat-kids', gratitude:'cat-kids',
    rewards:'cat-rewards', quiz:'cat-rewards',
    community:'cat-community', referral:'cat-community', gift:'cat-community',
    settings:'cat-account', subscription:'cat-account'
  };
  var catId = catMap[page];
  if (catId) {
    var catEl = document.getElementById(catId);
    if (catEl && !catEl.classList.contains('open')) {
      catEl.classList.add('open');
      // Also open the cat button
      var catBtn = catEl.previousElementSibling;
      if (catBtn) catBtn.classList.add('open');
    }
  }
};

