var isDark = localStorage.getItem('darkMode') === 'true';
var currentLang = localStorage.getItem('lang') || 'bn';

function applyDarkMode(dark) {
  var tog = document.getElementById('dm-toggle');
  var knob = document.getElementById('dm-knob');
  var icon = document.getElementById('dm-icon');
  var label = document.getElementById('dm-label');
  if (dark) {
    document.body.classList.add('dark-mode');
    document.documentElement.style.background = '#0f1117';
    if (tog) tog.style.background = '#1a6b3c';
    if (knob) knob.style.left = '27px';
    if (icon) icon.innerHTML = '&#9728;&#65039;';
    if (label) label.textContent = 'চালু আছে';
  } else {
    document.body.classList.remove('dark-mode');
    document.documentElement.style.background = '';
    if (tog) tog.style.background = '#e5e7eb';
    if (knob) knob.style.left = '3px';
    if (icon) icon.innerHTML = '&#127769;';
    if (label) label.textContent = 'বন্ধ আছে';
  }
}

function toggleDarkMode() {
  isDark = !isDark;
  localStorage.setItem('darkMode', isDark);
  applyDarkMode(isDark);
}

