var cmPosts=[];
var _cmPostsLoading=true;
/* Pre-load from cache so first cmRenderFeed() call shows posts instantly */
try{var _cmC=localStorage.getItem('cm_posts_cache');if(_cmC){var _cmCP=JSON.parse(_cmC);if(_cmCP&&_cmCP.length>0){cmPosts=_cmCP;_cmPostsLoading=false;}}}catch(e){}
/* ── REAL SUPABASE POSTS ─────────────────────────────── */
var _cmPostsGen=0;

// Row → in-memory post object. Extracted out of cmLoadPosts() so a challenge-scoped feed load
// (chlLoadChallengeFeed) can map its own query results into the exact same shape and merge them
// into the shared cmPosts array — see chlRenderFeed()'s comment for why that merge matters.
var cmAvatarColors=['#8B5CF6','#3B82F6','#F59E0B','#EF4444','#10B981','#FF8A00','#1a6b3c'];
function cmMapPostRow(p, i) {
  var name = p.profiles ? p.profiles.name : 'Rizer';
  var initial = name.charAt(0).toUpperCase();
  var color = cmAvatarColors[i % cmAvatarColors.length];
  var parsed = cmParsePostContent(p.content);
  var rxList = p.post_reactions || [];
  var reactions = { inspire: 0, respect: 0, dua: 0, wow: 0, support: 0, super: 0 };
  var myReaction = null;
  var seen = {};
  rxList.forEach(function(r) {
    var dk = r.post_id + '|' + r.user_id;
    if (seen[dk]) return; seen[dk] = true;
    if (reactions[r.type] !== undefined) reactions[r.type]++;
    if (sbUser && r.user_id === sbUser.id) myReaction = r.type;
  });
  return {
    id: p.id, sbId: p.id,
    type: p.category || 'general',
    user: name, avBg: color, avL: initial,
    userId: p.user_id,
    avatarUrl: (p.profiles && p.profiles.avatar_url) || null,
    text: parsed.text,
    voice_url: parsed.voiceUrl,
    voice_wave: parsed.voiceWave,
    voice_dur: parsed.voiceDur,
    image: p.image_url || null,
    time: cmTimeAgo(p.created_at), created_at: p.created_at,
    likes: 0, liked: false,
    comments: [],
    commentCount: (p.comments && p.comments[0]) ? (p.comments[0].count || 0) : 0,
    reactions: reactions,
    myReaction: myReaction,
    shares: 0, real: true,
    own: !!(sbUser && p.user_id === sbUser.id),
    challengeId: p.challenge_id || null,
    challengeTitle: (p.challenges && p.challenges.title) || null,
    challengeIcon: (p.challenges && p.challenges.icon) || null,
    streakCount: (p.profiles && p.profiles.streak_count) || 0,
    isVerified: !!(p.profiles && p.profiles.is_verified)
  };
}

async function cmLoadPosts() {
  _cmPostsLoading=true;
  var _gen=++_cmPostsGen;
  try {
    var { data, error } = await _sb
      .from('posts')
      .select('*, profiles(name, streak_count, points, avatar_url, is_verified), comments(count), post_reactions(post_id, type, user_id), challenges(title, icon)')
      .neq('category','story')
      .order('created_at', { ascending: false })
      .limit(30);
    if (error) { _cmPostsLoading=false; console.warn('Posts load error:', error.message); cmRenderFeed(); return; }
    if (_gen !== _cmPostsGen) return;
    _cmPostsLoading=false;
    if (data && data.length > 0) {
      cmPosts = data.map(cmMapPostRow);
      try { var _toCache=cmPosts.map(function(p){var c=Object.assign({},p);if(c.image&&c.image.startsWith('data:'))c.image=null;return c;});localStorage.setItem('cm_posts_cache',JSON.stringify(_toCache)); } catch(e) {}
      // Preload images before rendering so they appear instantly
      var _imgUrls=cmPosts.filter(function(p){return p.image;}).map(function(p){return p.image;});
      if(_imgUrls.length>0){
        var _loaded=0;
        var _doRender=function(){_loaded++;if(_loaded>=_imgUrls.length)cmRenderFeed();};
        var _timeout=setTimeout(function(){cmRenderFeed();},800);
        _imgUrls.forEach(function(url){
          var i=new Image();
          i.onload=i.onerror=function(){_loaded++;if(_loaded>=_imgUrls.length){clearTimeout(_timeout);cmRenderFeed();}};
          i.src=url;
        });
      } else {
        cmRenderFeed();
      }
    } else {
      _cmPostsLoading=false;
      cmRenderFeed();
    }
  } catch(e) { _cmPostsLoading=false; console.warn('cmLoadPosts:', e); cmRenderFeed(); }
}

function cmParsePostContent(raw){
  if(!raw)return{text:'',voiceUrl:'',voiceWave:null,voiceDur:null};
  var marker='\n\n__AUDIO__:';
  var idx=raw.indexOf(marker);
  if(idx===-1)return{text:raw,voiceUrl:'',voiceWave:null,voiceDur:null};
  var text=raw.substring(0,idx).trim();
  var rest=raw.substring(idx+marker.length);
  var waveMarker='\n__AUDIOWAVE__:';
  var wIdx=rest.indexOf(waveMarker);
  if(wIdx===-1)return{text:text,voiceUrl:rest.trim(),voiceWave:null,voiceDur:null};
  var waveData=null;
  try{waveData=JSON.parse(rest.substring(wIdx+waveMarker.length).trim());}catch(e){}
  return{text:text,voiceUrl:rest.substring(0,wIdx).trim(),voiceWave:(waveData&&waveData.peaks)||null,voiceDur:(waveData&&waveData.duration)||null};
}

function cmTimeAgo(ts) {
  if (!ts) return 'just now';
  var d = new Date(ts);
  if (isNaN(d.getTime())) return ts || 'just now';
  var diff = Math.floor((Date.now() - d) / 1000);
  if (diff < 0) diff = 0;
  if (diff < 60) return 'just now';
  if (diff < 3600) return Math.floor(diff/60) + ' min ago';
  if (diff < 86400) return Math.floor(diff/3600) + ' hr ago';
  return Math.floor(diff/86400) + ' days ago';
}

async function cmSubmitPost(content, category) {
  if (!sbUser) { sbOpenAuth('login'); return false; }
  if (!content || !content.trim()) return false;
  try {
    var { data, error } = await _sb.from('posts').insert({
      user_id: sbUser.id,
      content: content.trim(),
      category: category || 'general',
      rays: 0
    }).select('*, profiles(name)').single();
    if (error) { cmToast('পোস্ট হয়নি: ' + error.message); return false; }
    // Prepend to feed immediately
    var name = sbProfile ? sbProfile.name : 'তুমি';
    var colors = ['#FF8A00','#8B5CF6','#3B82F6'];
    var _newTs = (data && data.created_at) ? data.created_at : new Date().toISOString();
    cmPosts.unshift({
      id: data.id, sbId: data.id,
      type: category || 'general',
      user: name,
      avBg: colors[0],
      avL: name.charAt(0).toUpperCase(),
      userId: sbUser.id,
      avatarUrl: sbProfile ? sbProfile.avatar_url : null,
      text: content.trim(),
      time: cmTimeAgo(_newTs), created_at: _newTs,
      likes: 0, liked: false, comments: [],
      commentCount: 0,
      reactions:{inspire:0,respect:0,dua:0,wow:0,support:0,super:0},
      myReaction:null, shares:0, real:true, own:true,
      voice_url: ''
    });
    cmRenderFeed();
    if (typeof pfLoadPosts === 'function') pfLoadPosts();
    return true;
  } catch(e) { cmToast('Error: ' + e.message); return false; }
}

