// Real progress computed from the user's own logs instead of the fixed 12/30, 7/21, 3/7 this
// used to hardcode — no dedicated "challenges" table exists (or is planned yet), so each
// challenge here is defined as a rule over data that's already real: "30 Day Salah" = how many
// of the last 30 days had all 5 prayers logged; "Fajr Club"/"Quran Before Scroll" = current
// consecutive-day streaks, same streak rule as the Fajr/Quran feed cards.
async function cmInitChallenges(){
  var el=document.getElementById('cm-challenges-left');if(!el)return;
  if(typeof _sb==='undefined'||!window.sbUser)return;
  // Clearing here (before the awaits below) then appending afterward left a race window: if
  // this function got called again (or already was running) before the awaits resolved, both
  // calls' rows landed in the same now-non-empty container — that's what caused the "3 sets of
  // 3 challenges" duplication. Clearing again right before the (now synchronous, no more
  // awaits) append step below closes that window regardless of how many overlapping calls
  // happened in between.
  var svgMoon='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9z"/></svg>';
  var svgSun='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41"/></svg>';
  var svgBook='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>';
  var today=new Date().toISOString().split('T')[0];
  var day30=new Date(Date.now()-29*86400000).toISOString().split('T')[0];
  var salah30=0, fajrStreak=0, quranStreak=0;
  try{
    var nRes=await _sb.from('adult_namaz_logs').select('date,prayer,status').eq('user_id',sbUser.id).gte('date',day30).eq('status','completed');
    var byDate={};
    (nRes.data||[]).forEach(function(r){ (byDate[r.date]=byDate[r.date]||new Set()).add(r.prayer); });
    salah30=Object.keys(byDate).filter(function(d){return byDate[d].size>=5;}).length;
    var fajrCheck=new Date();
    var fajrDoneToday=byDate[today]&&byDate[today].has('Fajr');
    if(!fajrDoneToday)fajrCheck.setDate(fajrCheck.getDate()-1);
    while(true){ var ds=fajrCheck.toISOString().split('T')[0]; if(byDate[ds]&&byDate[ds].has('Fajr')){fajrStreak++;fajrCheck.setDate(fajrCheck.getDate()-1);} else break; }
  }catch(e){}
  try{
    var qRes=await _sb.from('adult_quran_data').select('tilawat,daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var qData=qRes.data; var tilawat=(qData&&qData.tilawat)||{}; var qGoal=(qData&&qData.daily_goal)||2;
    var qCheck=new Date();
    if((tilawat[today]||0)<qGoal)qCheck.setDate(qCheck.getDate()-1);
    while(true){ var qds=qCheck.toISOString().split('T')[0]; if((tilawat[qds]||0)>=qGoal){quranStreak++;qCheck.setDate(qCheck.getDate()-1);} else break; }
  }catch(e){}
  el.innerHTML='';
  [{name:'30 Day Salah',icon:svgMoon,prog:salah30,total:30,color:'#1a6b3c'},
   {name:'Fajr Club',icon:svgSun,prog:Math.min(fajrStreak,21),total:21,color:'#F59E0B'},
   {name:'Quran Before Scroll',icon:svgBook,prog:Math.min(quranStreak,7),total:7,color:'#8B5CF6'}
  ].forEach(function(c){
    var row=document.createElement('div');row.style.cssText='margin-bottom:12px';
    var top=document.createElement('div');top.style.cssText='display:flex;align-items:center;gap:8px;margin-bottom:6px';
    var ic=document.createElement('span');ic.style.cssText='display:flex;color:'+c.color;ic.innerHTML=c.icon;
    var nm=document.createElement('span');nm.style.cssText='font-size:13px;font-weight:600;color:var(--ct);flex:1';nm.textContent=c.name;
    var pct=document.createElement('span');pct.style.cssText='font-size:11px;font-weight:700;color:'+c.color;pct.textContent=Math.round(c.prog/c.total*100)+'%';
    top.appendChild(ic);top.appendChild(nm);top.appendChild(pct);
    var pb=document.createElement('div');pb.style.cssText='height:5px;background:var(--cl);border-radius:10px;overflow:hidden';
    var pf=document.createElement('div');pf.style.cssText='height:100%;width:'+Math.round(c.prog/c.total*100)+'%;background:'+c.color+';border-radius:10px';
    pb.appendChild(pf);
    row.appendChild(top);row.appendChild(pb);
    el.appendChild(row);
  });
}

// "এখন Grind করছে" — used to be 4 hardcoded names/tools. Real version: for each bonded Rizer,
// find whichever tool has their MOST RECENTLY updated activity today (Namaz/Habit/Quran/Deep
// Work), show up to 4 of them. Falls back to demo profiles only when the user has no bonded
// Rizers yet — same pattern as Grow Your Network/Squad Activity, so an empty network doesn't
// just show a blank sidebar.
async function cmLoadGrindingNow(){
  var el=document.getElementById('cm-grinding-now');
  if(!el||typeof _sb==='undefined'||!window.sbUser)return;
  try{
    var mine=await _sb.from('rizerships').select('rizer_id').eq('user_id',sbUser.id);
    var bondedIds=(mine.data||[]).map(function(r){return r.rizer_id;});
    var people=[];
    if(bondedIds.length){
      var today=new Date().toISOString().split('T')[0];
      var profRes=await _sb.from('profiles').select('id,name,avatar_url').in('id',bondedIds);
      var nRes=await _sb.from('adult_namaz_logs').select('user_id,created_at').in('user_id',bondedIds).eq('date',today).order('created_at',{ascending:false});
      var hRes=await _sb.from('adult_habits').select('user_id,last_done_date').in('user_id',bondedIds).eq('last_done_date',today);
      var dRes=await _sb.from('deepwork_sessions').select('user_id,created_at').in('user_id',bondedIds).eq('date',today).order('created_at',{ascending:false});
      var latest={}; // user_id -> {tool,ts}
      (nRes.data||[]).forEach(function(r){ var ts=new Date(r.created_at).getTime(); if(!latest[r.user_id]||ts>latest[r.user_id].ts)latest[r.user_id]={tool:'Namaz',ts:ts}; });
      (hRes.data||[]).forEach(function(r){ var ts=Date.now(); if(!latest[r.user_id])latest[r.user_id]={tool:'Habit',ts:ts}; });
      (dRes.data||[]).forEach(function(r){ var ts=new Date(r.created_at).getTime(); if(!latest[r.user_id]||ts>latest[r.user_id].ts)latest[r.user_id]={tool:'Deep Work',ts:ts}; });
      people=(profRes.data||[]).filter(function(p){return latest[p.id];}).map(function(p){return {p:p,tool:latest[p.id].tool};}).slice(0,4);
    }
    var isDemo=!people.length;
    if(isDemo){
      people=[
        {p:{id:'demo-1',name:'রাফিয়া'},tool:'Deep Work',grad:'linear-gradient(135deg,#8B5CF6,#5B21B6)'},
        {p:{id:'demo-2',name:'আরিয়ান'},tool:'Quran',grad:'linear-gradient(135deg,#3B82F6,#1D4ED8)'},
        {p:{id:'demo-3',name:'মীম'},tool:'Namaz',grad:'linear-gradient(135deg,#F59E0B,#B45309)'},
        {p:{id:'demo-4',name:'সাদিয়া'},tool:'Streak',grad:'linear-gradient(135deg,#10B981,#065F46)'}
      ];
    }
    el.innerHTML=people.map(function(x){
      var p=x.p, initial=(p.name||'?').charAt(0).toUpperCase();
      var avStyle=p.avatar_url?('background-image:url('+p.avatar_url+');background-size:cover'):('background:'+(x.grad||'linear-gradient(135deg,#FF8A00,#FFB800)'));
      var click=x.isDemo!==false&&isDemo?'cmToast(\'এটা একটা demo profile 🙂\')':'viewUserProfile(\''+p.id+'\')';
      return '<div onclick="'+click+'" style="display:flex;align-items:center;gap:9px;cursor:pointer">'
        +'<div style="width:32px;height:32px;border-radius:50%;'+avStyle+';display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:13px;flex-shrink:0;position:relative">'+(p.avatar_url?'':'<div class="cm-online-dot"></div>'+initial)+'</div>'
        +'<div style="font-size:13px;color:var(--ct);font-weight:500;flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escapeHtml(p.name||'Rizer')+'</div>'
        +'<div style="font-size:11px;color:var(--ct2)">'+x.tool+'</div>'
        +'</div>';
    }).join('')||'<div style="font-size:12px;color:var(--ct2);text-align:center;padding:8px 0">এখনো কেউ active নেই</div>';
  }catch(e){ el.innerHTML='<div style="font-size:12px;color:var(--ct2);text-align:center;padding:8px 0">লোড করা যায়নি</div>'; }
}

