function escapeHtml(x){return (x+'').replace(/[&<>"]/g,function(c){return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c];});}
function myInitial(){try{return (window.lpData&&lpData.name)?lpData.name.trim().charAt(0).toUpperCase():'R';}catch(e){return 'R';}}
function cmShare(id){rzShareOpen(id);}
var cmExpanded={};
function cmBodyText(p){if(p.text.length<=140||cmExpanded[p.id])return escapeHtml(p.text);return escapeHtml(p.text.slice(0,128))+'… <span class="cm-seemore" onclick="cmExpand(\''+p.id+'\')">আরও দেখুন</span>';}
function cmExpand(id){cmExpanded[id]=true;cmUpdatePostCard(id);}
function cmFollow(id){var p=cmPosts.find(function(x){return x.id===id;});if(p){p.following=true;cmUpdatePostCard(id);}}
var cmMenuId=null;
function cmOpenMenu(e,id){e.stopPropagation();cmMenuId=id;var menu=document.getElementById('cm-menu');var bd=document.getElementById('cm-menu-backdrop');if(!menu)return;menu.style.display='block';var mw=menu.offsetWidth||230;var r=e.currentTarget.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(r.right-mw,window.innerWidth-mw-8))+'px';menu.style.top=(r.bottom+6)+'px';if(bd)bd.style.display='block';}
function cmCloseMenu(){var menu=document.getElementById('cm-menu');var bd=document.getElementById('cm-menu-backdrop');if(menu)menu.style.display='none';if(bd)bd.style.display='none';cmMenuId=null;}
function cmMenuAction(a){var id=cmMenuId;cmCloseMenu();var p=cmPosts.find(function(x){return x.id===id;});if(!p)return;if(a==='hide'){p.hidden=true;cmRemovePostCard(id);}else if(a==='save'){alert('পোস্ট সেভ হয়েছে ✓');}else if(a==='report'){alert('রিপোর্ট পাঠানো হয়েছে। ধন্যবাদ — আমরা দেখছি।');}else if(a==='unfollow'){p.following=false;cmUpdatePostCard(id);}}
