var cmStoryIdx=0,cmStoryTimer=null;
function cmRenderStories(){
  var el=document.getElementById('cm-stories'); if(!el)return;
  var _avBg='';
  var _storyPic=window._myStoryPhotoUrl||(window.sbProfile&&sbProfile.avatar_url);
  if(_storyPic){_avBg='background-image:url('+_storyPic+');background-size:cover;background-position:center top';}else{_avBg='background:linear-gradient(135deg,#FF8A00,#FFB800)';}
  var h='<div class="cm-story cm-story-add" onclick="cmOpenCreateStory()"><div class="cm-story-card"><div class="cm-story-add-bg" style="'+_avBg+'"></div><div class="cm-story-add-bottom"><div class="cm-story-plus-new">+</div><div class="cm-story-name">তোমার Rise</div></div></div></div>';
  cmStoryList.forEach(function(s,i){
    h+='<div class="cm-story'+(s.viewed?' viewed':'')+'" onclick="cmStoryOpen('+i+')"><div class="cm-story-card" style="background:linear-gradient(160deg,'+s.grad[0]+','+s.grad[1]+')"><div class="cm-story-av" style="background:'+s.grad[1]+'">'+s.av+'</div><div class="cm-story-preview">'+s.title+'</div><div class="cm-story-name">'+s.name+'</div></div></div>';
  });
  el.innerHTML=h;
}
function cmStoryOpen(i){cmStoryIdx=i;document.getElementById('cm-story-view').classList.add('show');document.body.style.overflow='hidden';cmStoryRender();}
function cmStoryRender(){
  var s=cmStoryList[cmStoryIdx]; if(!s)return; s.viewed=true;
  document.getElementById('cm-sv-name').textContent=s.name;
  var av=document.getElementById('cm-sv-av'); av.textContent=s.av; av.style.background='linear-gradient(135deg,'+s.grad[0]+','+s.grad[1]+')';
  document.getElementById('cm-sv-title').textContent=s.title;
  document.getElementById('cm-sv-sub').textContent=s.sub;
  document.getElementById('cm-sv-card').style.background='linear-gradient(160deg,'+s.grad[0]+','+s.grad[1]+')';
  var pr=document.getElementById('cm-sv-progress'),ph='';
  for(var i=0;i<cmStoryList.length;i++){ph+='<div class="cm-sv-seg"><div class="cm-sv-seg-fill" style="width:'+(i<cmStoryIdx?'100%':'0')+'"></div></div>';}
  pr.innerHTML=ph;
  requestAnimationFrame(function(){var seg=pr.children[cmStoryIdx];if(seg){var f=seg.querySelector('.cm-sv-seg-fill');f.style.transition='width 5s linear';f.style.width='100%';}});
  clearTimeout(cmStoryTimer); cmStoryTimer=setTimeout(cmStoryNext,5000);
}
function cmStoryNext(){clearTimeout(cmStoryTimer);if(cmStoryIdx<cmStoryList.length-1){cmStoryIdx++;cmStoryRender();}else{cmStoryClose();}}
function cmStoryPrev(){clearTimeout(cmStoryTimer);if(cmStoryIdx>0){cmStoryIdx--;cmStoryRender();}else{cmStoryRender();}}
function cmStoryClose(){clearTimeout(cmStoryTimer);document.getElementById('cm-story-view').classList.remove('show');document.body.style.overflow='';cmRenderStories();}
function cmStoryReact(){clearTimeout(cmStoryTimer);var b=event&&event.currentTarget;if(b){b.textContent='🔥 পাঠানো হলো';b.style.background='rgba(255,184,0,.25)';}setTimeout(cmStoryNext,700);}
var cmCSGrads=[['#8B5CF6','#5B21B6'],['#3B82F6','#1D4ED8'],['#10B981','#065F46'],['#F59E0B','#B45309'],['#EF4444','#991B1B'],['#FF8A00','#FFB800']];
var cmCSIcons=[
  '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"/></svg>',
  '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9z"/></svg>',
  '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>',
  '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/></svg>',
  '<svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>'
];
var cmCSChips=[{l:'Streak',t:'STREAK পূর্ণ'},{l:'ফজর',t:'ফজরে জয়'},{l:'Quran',t:'৫ পেজ Quran'},{l:'Deep Work',t:'Deep Work'},{l:'Habit',t:'Habit পূরণ'}];
var cmCSGi=0;
function cmOpenCreateStory(){var m=document.getElementById('cm-cs');if(!m)return;m.classList.add('show');document.body.style.overflow='hidden';cmCSGi=0;
  document.getElementById('cm-cs-chips').innerHTML=cmCSChips.map(function(c,i){return '<button class="cm-cs-chip" onclick="cmCSPickChip('+i+')">'+cmCSIcons[i]+c.l+'</button>';}).join('');
  document.getElementById('cm-cs-grads').innerHTML=cmCSGrads.map(function(g,i){return '<div class="cm-cs-grad'+(i===cmCSGi?' on':'')+'" style="background:linear-gradient(160deg,'+g[0]+','+g[1]+')" onclick="cmCSPickGrad('+i+')"></div>';}).join('');
  document.getElementById('cm-cs-title').value='';document.getElementById('cm-cs-sub').value='';cmCSUpdate();}
function cmCloseCreateStory(){var m=document.getElementById('cm-cs');if(m)m.classList.remove('show');document.body.style.overflow='';}
function cmCSPickChip(i){document.getElementById('cm-cs-title').value=cmCSChips[i].t;cmCSUpdate();}
function cmCSPickGrad(i){cmCSGi=i;[].forEach.call(document.querySelectorAll('#cm-cs .cm-cs-grad'),function(e,j){e.classList.toggle('on',j===i);});cmCSUpdate();}
function cmCSUpdate(){var t=(document.getElementById('cm-cs-title').value||'').trim()||'তোমার অর্জন';var sub=(document.getElementById('cm-cs-sub').value||'').trim();var g=cmCSGrads[cmCSGi];document.getElementById('cm-cs-ptitle').textContent=t;document.getElementById('cm-cs-psub').textContent=sub;document.getElementById('cm-cs-card').style.background='linear-gradient(160deg,'+g[0]+','+g[1]+')';}
async function cmCSPost(){
  var ti=document.getElementById('cm-cs-title');
  var t=ti.value.trim();if(!t){ti.focus();return;}
  var sub=document.getElementById('cm-cs-sub').value.trim();
  var g=cmCSGrads[cmCSGi];
  var storyData={name:(window.sbProfile&&sbProfile.name)||(window.lpData&&lpData.name)||'তুমি',av:myInitial(),grad:[g[0],g[1]],title:t,sub:sub||'থামবো না, এবার করতেই হবে।',mine:true};
  cmCloseCreateStory();
  cmStoryList.unshift(storyData);
  cmRenderStories();
  cmToast('তোমার আজকের Rise শেয়ার হলো 🔥');
  if(typeof _sb!=='undefined'&&window.sbUser){
    try{
      await _sb.from('posts').insert({user_id:sbUser.id,content:JSON.stringify({title:t,sub:storyData.sub,grad:[g[0],g[1]]}),category:'story'});
    }catch(e){console.warn('story save error',e);}
  }
}
async function cmLoadStories(){
  if(typeof _sb==='undefined'||!window.sbUser)return;
  try{
    var res=await _sb.from('posts').select('id,content,created_at,user_id,profiles(name,username)').eq('category','story').order('created_at',{ascending:false}).limit(30);
    if(!res.data||!res.data.length)return;
    var loaded=res.data.map(function(row){
      var c={};try{c=JSON.parse(row.content||'{}');}catch(e){}
      var pname=(row.profiles&&row.profiles.name)||'User';
      var av=pname.charAt(0).toUpperCase();
      return {name:pname,av:av,grad:c.grad||['#8B5CF6','#5B21B6'],title:c.title||'',sub:c.sub||'',mine:row.user_id===sbUser.id};
    });
    var myStory=loaded.filter(function(s){return s.mine;});
    var others=loaded.filter(function(s){return !s.mine;});
    cmStoryList=myStory.concat(others);
    cmRenderStories();
  }catch(e){console.warn('cmLoadStories',e);}
}
function cmToast(msg){var t=document.createElement('div');t.textContent=msg;t.style.cssText='position:fixed;left:50%;bottom:92px;transform:translateX(-50%);background:#1a1d24;color:#fff;padding:11px 18px;border-radius:50px;font-size:13px;font-weight:600;z-index:10005;box-shadow:0 6px 20px rgba(0,0,0,.3);font-family:inherit;max-width:88%;text-align:center';document.body.appendChild(t);setTimeout(function(){t.style.transition='opacity .4s';t.style.opacity='0';setTimeout(function(){t.remove();},400);},1900);}
function cmShowPostSuccess(){
  var old=document.getElementById('_cm_ps_card');if(old)old.remove();
  var card=document.createElement('div');
  card.id='_cm_ps_card';
  card.style.cssText='position:fixed;bottom:90px;left:50%;transform:translateX(-50%) translateY(80px);z-index:10010;background:#fff;border-radius:50px;padding:6px 12px 6px 6px;display:flex;align-items:center;gap:7px;box-shadow:0 4px 24px rgba(0,0,0,.13),0 1px 6px rgba(0,0,0,.08);opacity:0;transition:transform .4s cubic-bezier(.34,1.56,.64,1),opacity .25s;font-family:inherit;white-space:nowrap';
  card.innerHTML=
    '<div style="width:24px;height:24px;border-radius:50%;background:linear-gradient(135deg,#FF8A00,#FFB800);display:flex;align-items:center;justify-content:center;flex-shrink:0">'+
      '<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>'+
    '</div>'+
    '<span style="font-size:11.5px;font-weight:700;color:#111">Posted!</span>'+
    '<span style="font-size:10.5px;color:#555;font-weight:600">Live in your Feed</span>';
  document.body.appendChild(card);
  requestAnimationFrame(function(){requestAnimationFrame(function(){
    card.style.transform='translateX(-50%) translateY(0)';
    card.style.opacity='1';
  });});
  var _t=setTimeout(function(){_cmPsDismiss(card);},2500);
  card._dismiss=_t;
}
function _cmPsDismiss(card){
  if(!card||!card.parentNode)return;
  clearTimeout(card._dismiss);
  card.style.transition='transform .35s ease-in,opacity .35s ease-in';
  card.style.transform='translateX(-50%) translateY(110px)';
  card.style.opacity='0';
  setTimeout(function(){if(card.parentNode)card.remove();},360);
}
// Card constants — module-level so they're built once, not recomputed on every cmRenderFeed() call.
var cmCard_FL='<svg viewBox="0 0 24 24"><path d="M12 2c1 3-2 4-2 7a3 3 0 0 0 6 0c0-1 0-2-1-3 2 1 4 3 4 6a7 7 0 1 1-14 0c0-4 4-5 7-10z"/></svg>';
var cmCard_FLs='<svg width="11" height="11" viewBox="0 0 24 24"><path d="M12 2c1 3-2 4-2 7a3 3 0 0 0 6 0c0-1 0-2-1-3 2 1 4 3 4 6a7 7 0 1 1-14 0c0-4 4-5 7-10z"/></svg>';
var cmCard_CM='<svg viewBox="0 0 24 24"><path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z"/></svg>';
var cmCard_SH='<svg viewBox="0 0 24 24"><path d="M13 9V5.4L20.2 12 13 18.6V15c-5 0-8.2 1.5-10.2 5 .8-6.2 4-10.3 10.2-11z"/></svg>';
var cmCard_RY='<svg viewBox="0 0 24 24" fill="currentColor" stroke="none"><circle cx="12" cy="12" r="4"/><g stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M12 2.5v2.3M12 19.2v2.3M2.5 12h2.3M19.2 12h2.3M5 5l1.6 1.6M17.4 17.4 19 19M19 5l-1.6 1.6M6.6 17.4 5 19"/></g></svg>';
var cmCard_EM_LIKE='<img class="cm-emoji" alt="" src="https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@main/assets/Thumbs%20up/Default/3D/thumbs_up_3d_default.png">';
var cmCard_EM_LOVE='<img class="cm-emoji" alt="" src="https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@main/assets/Red%20heart/3D/red_heart_3d.png">';
var cmCard_EM_CARE='<img class="cm-emoji" alt="" src="https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@main/assets/Smiling%20face%20with%20hearts/3D/smiling_face_with_hearts_3d.png">';
var cmCard_EM_WOW='<img class="cm-emoji" alt="" src="https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@main/assets/Face%20with%20open%20mouth/3D/face_with_open_mouth_3d.png">';
var cmCard_EM_SAD='<img class="cm-emoji" alt="" src="https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@main/assets/Crying%20face/3D/crying_face_3d.png">';
var cmCard_EM_SUPER='<img class="cm-emoji" alt="" src="https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@main/assets/Rocket/3D/rocket_3d.png">';
var cmCard_THUMB='<svg viewBox="0 0 24 24"><path d="M7 10v12"/><path d="M15 5.88 14 10h5.83a2 2 0 0 1 1.92 2.56l-2.33 8A2 2 0 0 1 17.5 22H4a2 2 0 0 1-2-2v-8a2 2 0 0 1 2-2h2.76a2 2 0 0 0 1.79-1.11L12 2a3.13 3.13 0 0 1 3 3.88Z"/></svg>';
var cmCard_rays={streak:15,win:10,habit:8};

// Builds one post's .cm-post card HTML. Extracted out of cmRenderFeed()'s loop body so a
// challenge-scoped feed (chlRenderFeed) can render posts with the exact same markup instead of
// hand-copying it — cmInjectFeedRizPlayCard's own comment already flagged hand-copying .cm-post's
// classes as a mistake once; this extraction is what avoids doing that a second time.
function cmBuildPostCardHtml(p){
  var tc=cmTypeColors[p.type]||'#FF8A00';
  var ring=(p.type==='streak')?' ring':'';
  var sb=(p.type==='streak')?'<span class="cm-streakb">'+cmCard_FLs+(p.streakCount||0)+'</span>':'';
  var vb=p.isVerified?'<img src="Only%20Badge-02.svg" style="height:20px;margin-left:2px;object-fit:contain;pointer-events:none;flex-shrink:0;vertical-align:middle;display:inline-block" alt="" draggable="false">':'';
  var tcChip=(p.type&&cmTypeLabels[p.type])?'<span style="color:var(--ct2)">·</span><span class="cm-typechip" style="color:'+tc+';background:'+tc+'1f">'+cmTypeLabels[p.type]+'</span>':'';
  // Cross-link tag for a challenge progress post rendered in the general feed (FB-Group-post-
  // in-your-News-Feed style) — tapping jumps into that challenge's own page.
  var chlTag=p.challengeId?('<span style="color:var(--ct2)">·</span><span class="cm-typechip" style="cursor:pointer" onclick="event.stopPropagation();chlJumpToChallenge(\''+p.challengeId+'\')">'+escapeHtml(p.challengeIcon||'🎯')+' '+escapeHtml(p.challengeTitle||'Challenge')+'</span>'):'';
  var raysLine=cmCard_rays[p.type]?'<div class="cm-rays">'+cmCard_RY+' +'+cmCard_rays[p.type]+' Rays</div>':'';
  // Challenge progress images (the auto-generated dark card, or a real photo) are meant to
  // read as the whole post edge-to-edge, matching how they already look wrapped in .chl-pcard
  // on the Challenges page — but here in the plain feed, the shared .cm-post-media CSS still
  // applies its normal 14px left/right margin + border meant for regular photos, which shows
  // up as an ugly white frame around the dark card in light mode. Only skip it for challenge
  // posts; normal posts keep their usual framed-photo treatment.
  var _chlMediaOverride=p.challengeId?';margin-left:0;margin-right:0;border:none':'';
  var mediaHtml=p.image?'<div class="cm-post-media" style="border-radius:12px;overflow:hidden;min-height:200px;background:#f0f0f0;position:relative;margin-bottom:4px'+_chlMediaOverride+'"><div class="cm-shimmer-overlay" style="position:absolute;inset:0;background:linear-gradient(90deg,transparent 0%,rgba(255,255,255,0.55) 50%,transparent 100%);background-size:200% 100%;animation:cmShimmer 1.4s ease-in-out infinite;z-index:1;pointer-events:none"></div><img src="'+escapeHtml(p.image)+'" alt="" loading="eager" fetchpriority="high" style="width:100%;display:block;border-radius:12px;opacity:0;transition:opacity .35s ease;position:relative;z-index:2" onload="this.style.opacity=\'1\';var ov=this.previousElementSibling;if(ov)ov.remove();this.parentElement.style.minHeight=\'0\';this.parentElement.style.background=\'none\'" onerror="this.parentElement.style.display=\'none\'"></div>':'';
  if(p.voice_url){
    window._cmVoiceUrls=window._cmVoiceUrls||{};
    window._cmVoiceUrls[p.id]=p.voice_url;
    window._cmVoiceDurs=window._cmVoiceDurs||{};
    if(p.voice_dur)window._cmVoiceDurs[p.id]=p.voice_dur;
    else if(window._cmVoiceDurs[p.id]==null)_cmDiscoverVoiceDuration(p.id,p.voice_url);
    window._cmVoicePeaks=window._cmVoicePeaks||{};
    window._cmVoicePeaks[p.id]=(p.voice_wave&&p.voice_wave.length)?p.voice_wave:null;
    // "Now Playing"-style square card (phone Music-app look) instead of the old thin horizontal
    // bar — same 1:1 footprint an image post gets. Every id below (cm-vplay-/cm-vwave-/cm-vdur-)
    // is unchanged from the old markup on purpose: cmFeedVoiceToggle's playback engine, play/
    // pause icon swap, and duration timer all key off these exact ids. cm-vwave- is now a canvas
    // (see _cmDrawFlowWave) rendering a flowing wave whose amplitude comes from this post's real
    // decoded peaks (window._cmVoicePeaks) instead of a bar-per-sample equalizer.
    var _micSvg='<svg width="15" height="15" viewBox="0 0 24 24" fill="rgba(255,255,255,.55)"><path d="M12 14a3 3 0 0 0 3-3V5a3 3 0 0 0-6 0v6a3 3 0 0 0 3 3zM19 11a1 1 0 0 0-2 0 5 5 0 0 1-10 0 1 1 0 0 0-2 0 7 7 0 0 0 6 6.92V20H9a1 1 0 0 0 0 2h6a1 1 0 0 0 0-2h-2v-2.08A7 7 0 0 0 19 11z"/></svg>';
    var _psvg='<svg viewBox="0 0 24 24" width="26" height="26" fill="#fff"><polygon points="6 3 20 12 6 21 6 3"/></svg>';
    var _knownDurAtRender=p.voice_dur||window._cmVoiceDurs[p.id]||null;
    mediaHtml+='<div data-cm-voice-card="'+p.id+'" style="position:relative;margin:0 14px 12px;aspect-ratio:1/1;border-radius:22px;overflow:hidden;background:linear-gradient(165deg,#3a1216 0%,#230c0e 45%,#150708 100%);border:1px solid rgba(255,255,255,.08);box-shadow:0 26px 60px -16px rgba(0,0,0,.6),inset 0 1px 0 rgba(255,255,255,.08);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:28px 20px;box-sizing:border-box">'
      +'<div style="position:absolute;top:-50px;right:-50px;width:180px;height:180px;border-radius:50%;background:radial-gradient(circle,rgba(239,68,68,.22) 0%,transparent 70%);pointer-events:none"></div>'
      +'<div style="position:absolute;bottom:-60px;left:-60px;width:200px;height:200px;border-radius:50%;background:radial-gradient(circle,rgba(255,107,107,.14) 0%,transparent 70%);pointer-events:none"></div>'
      +'<div style="position:relative;z-index:1;display:flex;align-items:center;gap:6px;margin-bottom:18px;opacity:.9">'+_micSvg+'<span style="color:rgba(255,255,255,.6);font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase">Voice Message</span></div>'
      +'<button id="cm-vplay-'+p.id+'" class="cm-fv-play-btn" onclick="cmFeedVoiceToggle(\''+p.id+'\')" style="position:relative;z-index:1;width:72px;height:72px;border-radius:50%;background:radial-gradient(circle at 34% 28%,rgba(255,255,255,.3),rgba(255,255,255,.09) 55%,rgba(255,255,255,.04) 100%) padding-box,linear-gradient(135deg,#FF8A00,#ff6b6b,#ffb199) border-box;border:2px solid transparent;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 10px 32px rgba(255,107,107,.42),inset 0 1px 2px rgba(255,255,255,.35);margin-bottom:20px;transition:transform .15s ease">'+_psvg+'</button>'
      +'<canvas id="cm-vwave-'+p.id+'" class="cm-wave-canvas" width="440" height="112" style="position:relative;z-index:1;width:100%;max-width:220px;height:56px;display:block"></canvas>'
      +'<span id="cm-vdur-'+p.id+'" style="position:relative;z-index:1;color:rgba(255,255,255,.5);font-size:11px;font-weight:600;margin-top:12px;letter-spacing:.4px;font-variant-numeric:tabular-nums">'+escapeHtml(_cmFmtDur(0,_knownDurAtRender))+'</span>'
      +'</div>';
  }

  if(!p.reactions){p.reactions={inspire:(p.likes||0),respect:0,dua:0,wow:0,support:0,super:0};p.myReaction=p.liked?'inspire':null;}
  if(p.shares===undefined)p.shares=Math.floor((p.likes||0)/5);
  var RC={inspire:{i:cmCard_EM_LIKE,l:'Inspire'},respect:{i:cmCard_EM_LOVE,l:'Respect'},dua:{i:cmCard_EM_CARE,l:'Dua'},wow:{i:cmCard_EM_WOW,l:'Wow'},support:{i:cmCard_EM_SAD,l:'Support'},super:{i:cmCard_EM_SUPER,l:'Super'}};
  var rtotal=p.reactions.inspire+p.reactions.respect+p.reactions.dua+p.reactions.wow+p.reactions.support+(p.reactions.super||0);
  var sumIcons='';
  var _sc=0;
  // Show current user's reaction first, then other types by count
  if(p.myReaction&&RC[p.myReaction]){sumIcons+='<span class="cm-rsum-ic">'+RC[p.myReaction].i+'</span>';_sc++;}
  ['inspire','respect','dua','wow','support','super'].forEach(function(k){if(k!==p.myReaction&&p.reactions[k]>0&&_sc<3){sumIcons+='<span class="cm-rsum-ic">'+RC[k].i+'</span>';_sc++;}});
  if(!sumIcons&&rtotal>0) sumIcons='<span class="cm-rsum-ic">'+cmCard_EM_LIKE+'</span>';
  var _rct=(p.commentCount||p.comments.length);
  var mr=p.myReaction;var mrInfo=mr?RC[mr]:{i:cmCard_THUMB,l:'Inspire'};
  var tray='';
  // Mobile right side
  var actRight=(_rct>0||rtotal>0)?'<div class="cm-act-right">'
    +(_rct>0?'<span class="cm-rsum-c" style="font-size:12.5px;font-weight:600;color:var(--ct2)" onclick="cmToggleCmts(\''+p.id+'\')">'+_rct+' Comment'+(+_rct!==1?'s':'')+'</span>':'')
    +(rtotal>0?'<span style="display:inline-flex;align-items:center">'+sumIcons+'<span style="margin-left:5px;font-size:12.5px;font-weight:600;color:var(--ct2)">'+rtotal+'</span></span>':'')
    +'</div>':'';
  // Desktop FB-style summary row (hidden on mobile via CSS)
  var actSum=(rtotal>0||_rct>0)?'<div class="cm-actbar-sum">'
    +'<span class="cm-sum-left" onclick="cmToggleCmts(\''+p.id+'\')">'+(rtotal>0?sumIcons+'<span class="cm-sum-rc">'+rtotal+'</span>':'')+'</span>'
    +'<span class="cm-sum-right">'+(_rct>0?'<span class="cm-rsum-c" onclick="cmToggleCmts(\''+p.id+'\')">'+_rct+' Comment'+(+_rct!==1?'s':'')+'</span>':'')+(p.shares>0?'<span class="cm-sum-dot">·</span><span>'+p.shares+' Share'+(p.shares!==1?'s':'')+'</span>':'')+'</span>'
    +'</div>':'';
  var _isMyPost=window._myAvatarUrl&&(p.mine||p.own||(window.sbProfile&&p.user===window.sbProfile.name)||(window.sbUser&&p.userId===window.sbUser.id));
  var _uid=p.userId||'';
  if(_uid){ if(!window._cmProfileCache) window._cmProfileCache={};  window._cmProfileCache[_uid]={n:p.user,bg:p.avBg,l:p.avL,av:p.avatarUrl||''}; }
  // _profClick carries ONLY onclick — a style="cursor:pointer" here too (as it used to) would
  // give the avatar div two separate style="" attributes once concatenated with its own
  // background/overflow/border-radius one below; HTML silently keeps just the first and drops
  // the second, which was quietly dropping every avatar's background color (and the
  // overflow:hidden/border-radius that clips a real photo into a circle). _profCursor folds
  // the same cursor:pointer into each element's own single style attribute instead.
  var _profClick=_uid?'onclick="viewUserProfile(\''+_uid+'\')"':'';
  var _profCursor=_uid?'cursor:pointer;':'';
  var _avEl=_isMyPost
    ?'<div class="cm-av'+ring+'" '+_profClick+' style="'+_profCursor+'background:transparent;overflow:hidden;border-radius:50%"><img src="'+escapeHtml(window._myAvatarUrl)+'" style="width:100%;height:100%;object-fit:cover;display:block;border-radius:50%"></div>'
    :(p.avatarUrl
      ?'<div class="cm-av'+ring+'" '+_profClick+' style="'+_profCursor+'background:transparent;overflow:hidden;border-radius:50%"><img src="'+escapeHtml(p.avatarUrl)+'" style="width:100%;height:100%;object-fit:cover;display:block;border-radius:50%"></div>'
      :'<div class="cm-av'+ring+'" '+_profClick+' style="'+_profCursor+'background:'+p.avBg+';color:#fff">'+p.avL+'</div>');
  return '<div class="cm-post" data-post-id="'+p.id+'"><div class="cm-post-hd">'+_avEl
    +'<div class="cm-post-meta"><div class="cm-name"><span '+_profClick+' style="'+_profCursor+'">'+escapeHtml(p.user)+'</span>'+vb+sb+((!p.following&&!p.own)?' <span class="cm-follow" onclick="cmFollow(\''+p.id+'\')">· Follow</span>':'')+'</div><div class="cm-sub"><span class="cm-time" data-ts="'+(p.created_at||'')+'">'+cmTimeAgo(p.created_at||p.time)+'</span>'+tcChip+chlTag+'</div></div>'
    +'<button class="cm-more" onclick="cmOpenMenu(event,\''+p.id+'\')">&#8943;</button></div>'
    +(p.text?'<div class="cm-post-body">'+cmBodyText(p)+'</div>':'')+mediaHtml+raysLine
    +actSum
    +'<div class="cm-actbar"><div class="cm-act-left">'
    +'<button class="cm-actbtn'+(mr?' on':'')+'" style="touch-action:none;-webkit-user-select:none;user-select:none" onpointerdown="cmReactDown(event,\''+p.id+'\')" onmouseenter="cmReactHoverIn(event,\''+p.id+'\')" onmouseleave="cmReactHoverOut()">'+mrInfo.i+'<span>'+(mr?mrInfo.l:'Inspire')+'</span></button>'
    +'<button class="cm-actbtn" onclick="cmToggleCmts(\''+p.id+'\')">'+cmCard_CM+(_rct>0?'<span>'+_rct+'</span>':'')+'</button>'
    +'<button class="cm-actbtn" onclick="cmShare(\''+p.id+'\')">'+cmCard_SH+(p.shares>0?'<span>'+p.shares+'</span>':'')+'</button>'
    +'</div>'+actRight+'</div></div>';
}

function cmRenderFeed(){
  var el=document.getElementById('cm-feed');if(!el)return;
  if(_cmPostsLoading&&cmPosts.length===0){
    var sk='';for(var _s=0;_s<3;_s++){sk+='<div style="border-radius:14px;background:var(--card);border:1px solid var(--border);padding:14px 14px 10px;margin-bottom:10px"><div style="display:flex;gap:10px;margin-bottom:12px"><div style="width:38px;height:38px;border-radius:50%;background:var(--border);flex-shrink:0"></div><div style="flex:1"><div style="height:11px;border-radius:6px;background:var(--border);width:38%;margin-bottom:7px"></div><div style="height:9px;border-radius:5px;background:var(--border);width:22%"></div></div></div><div style="height:11px;border-radius:6px;background:var(--border);width:92%;margin-bottom:7px"></div><div style="height:11px;border-radius:6px;background:var(--border);width:75%;margin-bottom:7px"></div><div style="height:11px;border-radius:6px;background:var(--border);width:55%"></div></div>';}
    el.innerHTML='<div style="padding:8px 0">'+sk+'</div>';
    return;
  }
  var list=cmPosts.filter(function(p){return !p.hidden;});
  var html='';
  list.forEach(function(p){ html+=cmBuildPostCardHtml(p); });
  el.innerHTML=html;
  _cmStartTimeUpdater();
  // cmRenderFeed replaces #cm-feed's innerHTML wholesale, wiping any previously-injected
  // RizPlay/Suggested cards (they're plain DOM nodes, not part of `list`) — re-inject after
  // every render (not just the first) so a later re-render (e.g. duplicate auth-state event
  // re-calling cmLoadPosts) doesn't leave the feed missing them.
  if(typeof cmInjectFeedRizPlayCard==='function') cmInjectFeedRizPlayCard();
  if(typeof cmInjectFeedSuggestedCard==='function') cmInjectFeedSuggestedCard();
  if(typeof cmInjectFeedSquadCard==='function') cmInjectFeedSquadCard();
  if(typeof cmInjectFeedActNowCard==='function') cmInjectFeedActNowCard();
  if(typeof cmInjectFeedTodoCard==='function') cmInjectFeedTodoCard();
  if(typeof cmInjectFeedQuranCard==='function') cmInjectFeedQuranCard();
  if(typeof cmInjectFeedScreenTimeCard==='function') cmInjectFeedScreenTimeCard();
  if(typeof cmInjectFeedDeepWorkCard==='function') cmInjectFeedDeepWorkCard();
  // Keeps an open challenge detail page's own feed in sync with any action here (react/comment/
  // post) that already re-renders the general feed — see chlRenderFeed()'s own guard.
  if(typeof chlRenderFeed==='function') chlRenderFeed();
}

// Patches just ONE post's DOM in #cm-feed in place, instead of cmRenderFeed()'s full wholesale
// rebuild of every post — reacting to/commenting on/following one post was destroying and
// rebuilding every OTHER post's DOM too: every image reflashing through its shimmer-loading
// state (a visible layout jolt as each collapses back to its real height at a slightly
// different time), the RizPlay suggestion card's video restarting from 0:00, and the other 7
// injected smart cards re-fetching from Supabase from scratch and losing any in-progress typing
// — none of which had anything to do with the post that actually changed. Falls back to the old
// full cmRenderFeed() (still always correct, just not scoped) if the post isn't currently
// rendered in #cm-feed — e.g. reacting to a post from the Challenges page's own #chl-feed copy.
function cmUpdatePostCard(id){
  var p=cmPosts.find(function(x){return x.id===id;});
  var el=document.querySelector('#cm-feed [data-post-id="'+id+'"]');
  if(!p||!el){ cmRenderFeed(); return; }
  var tmp=document.createElement('div');
  tmp.innerHTML=cmBuildPostCardHtml(p);
  el.replaceWith(tmp.firstElementChild);
  _cmStartTimeUpdater();
}
// Removes just ONE post's DOM node (used by "hide") instead of a full rebuild. Same
// always-correct fallback as cmUpdatePostCard above.
function cmRemovePostCard(id){
  var el=document.querySelector('#cm-feed [data-post-id="'+id+'"]');
  if(el) el.remove(); else cmRenderFeed();
}
// Reacting/commenting on a post needs to also refresh whichever Profile view is currently open
// (own or a visitor's) so its own copy of that post card stays in sync — the old unconditional
// pfLoadPosts() call silently no-ops in visitor-mode (see pfLoadPosts's own early return),
// leaving a reacted-to/commented-on post on someone else's profile stuck showing its stale state
// until the user navigates away and back. This dispatches to whichever of the two
// profile-loading functions actually applies to the page currently open.
function cmRefreshOpenProfilePosts(){
  var pg=document.getElementById('profile-page');
  if(!pg) return;
  if(pg.classList.contains('visitor-mode')){
    if(_pfVisitingUserId && typeof pfLoadVisitorPosts==='function') pfLoadVisitorPosts(_pfVisitingUserId);
  } else if(typeof pfLoadPosts==='function') pfLoadPosts();
}

// Mobile stats show/hide
function cmCheckMobile(){
  var ms=document.getElementById('cm-stats-bar');
  if(ms)ms.style.display=window.innerWidth<=900?'block':'none';
}


var cmCurMobileTab = 'feed';

function cmMobileTab(tab, btn) {
  cmCurMobileTab = tab;
  // Update tab buttons
  document.querySelectorAll('.cm-tab-btn').forEach(function(b) { b.classList.remove('active'); });
  if (btn) btn.classList.add('active');

  // Show/hide panels
  var isMobile = window.innerWidth <= 700;
  var feedEl = document.getElementById('cm-feed');
  var feedContainer = feedEl ? feedEl.closest('.cm-center') : null;

  ['challenges','leaderboard','profile'].forEach(function(p) {
    var el = document.getElementById('cm-panel-' + p);
    if (el) el.classList.remove('active');
  });

  if (tab === 'feed') {
    if (feedContainer) feedContainer.style.display = '';
  } else {
    if (feedContainer && isMobile) feedContainer.style.display = 'none';
    var panel = document.getElementById('cm-panel-' + tab);
    if (panel) {
      panel.classList.add('active');
      if (tab === 'challenges') cmRenderMobileChallenges();
      if (tab === 'leaderboard') cmRenderMobileLeaderboard();
      if (tab === 'profile') cmRenderMobileProfile();
    }
  }
}

