window.showPage=function(page){
  _cmOrig(page);
  if(page==='community')setTimeout(function(){
    cmInitFilters();cmInitChallenges();cmInitLeaderboard();cmRenderStories();cmCheckMobile();cmLoadStories();cmLoadGrindingNow();
    // Load real posts if logged in, otherwise show demo
    if (typeof _sb !== 'undefined' && typeof sbUser !== 'undefined' && sbUser) {
      cmLoadPosts();
    } else {
      cmRenderFeed();
    }
    // Reset mobile panels on navigate
    if(window.innerWidth<=700){cmMobileTab('feed',document.getElementById('cmtab-feed'));}
  },50);
};
