var sleepGoalHrs = 8;

function changeGoal(delta) {
  sleepGoalHrs = Math.max(4, Math.min(12, sleepGoalHrs + delta));
  var d = document.getElementById('sleep-goal-display');
  var s = document.getElementById('sleep-goal-stat');
  if(d) d.textContent = sleepGoalHrs % 1 === 0 ? sleepGoalHrs : sleepGoalHrs.toFixed(1);
  if(s) s.textContent = (sleepGoalHrs % 1 === 0 ? sleepGoalHrs : sleepGoalHrs.toFixed(1)) + ' ঘণ্টা';
}

function saveSleepLog() {
  var bed = document.getElementById('bedtime-input');
  var wake = document.getElementById('waketime-input');
  if(!bed || !wake) return;
  var bedVal = bed.value; var wakeVal = wake.value;
  var bedParts = bedVal.split(':'); var wakeParts = wakeVal.split(':');
  var bedMins = parseInt(bedParts[0])*60 + parseInt(bedParts[1]);
  var wakeMins = parseInt(wakeParts[0])*60 + parseInt(wakeParts[1]);
  var diffMins = wakeMins - bedMins;
  if(diffMins < 0) diffMins += 1440;
  var hrs = (diffMins/60).toFixed(1);
  var pct = Math.min(100, Math.round((diffMins/60)/sleepGoalHrs*100));
  var offset = 314 - (314 * pct/100);
  var circle = document.getElementById('sleep-circle');
  var pctText = document.getElementById('sleep-pct-text');
  var actualEl = document.getElementById('sleep-actual');
  var todayEl = document.getElementById('sleep-hrs-today');
  var statusEl = document.getElementById('sleep-status-msg');
  if(circle) circle.setAttribute('stroke-dashoffset', offset);
  if(pctText) pctText.textContent = pct + '%';
  if(actualEl) actualEl.textContent = hrs + ' ঘণ্টা';
  if(todayEl) todayEl.textContent = hrs + ' ঘণ্টা';
  if(statusEl) {
    if(pct >= 100) {
      statusEl.style.background='#dcfce7'; statusEl.style.color='#16a34a';
      statusEl.textContent='\u2705 Goal পূরণ হয়েছে! চমৎকার!';
    } else if(pct >= 75) {
      statusEl.style.background='#fff9e6'; statusEl.style.color='#d97706';
      statusEl.textContent='\u26A0\uFE0F একটু কম হয়েছে, চেষ্টা করো!';
    } else {
      statusEl.style.background='#fee2e2'; statusEl.style.color='#dc2626';
      statusEl.textContent='\u274C ঘুম কম হয়েছে, আগে ঘুমাও!';
    }
  }
}

