function toggleSidebar() {
  var sb = document.querySelector('.sidebar');
  var ov = document.getElementById('mobile-overlay');
  var main = document.querySelector('.app-main');
  var btn = document.querySelector('.hamburger-btn');
  var isMobile = window.innerWidth <= 768;
  if(isMobile){
    if(sb) sb.classList.toggle('open');
    if(ov) ov.classList.toggle('open');
  } else {
    var isHidden = sb && sb.classList.contains('sb-hidden');
    if(isHidden){
      sb.classList.remove('sb-hidden');
      document.body.classList.remove('sb-hidden-state');
      if(main) main.style.marginLeft='220px';
    var tb=document.querySelector('.app-topbar');if(tb)tb.style.left='220px';
      if(btn) btn.classList.remove('active');
    } else {
      if(sb) sb.classList.add('sb-hidden');
      document.body.classList.add('sb-hidden-state');
      if(main) main.style.marginLeft='0px';
      if(btn) btn.classList.add('active');
    }
  }
}
// Explicit set (not toggle) — used to auto-collapse the sidebar on Rise Feed/RizPlay so those
// content-heavy pages get the full screen width, and auto-restore it elsewhere. Desktop only;
// mobile's sidebar is already an overlay drawer that doesn't take up page width.
function _rzSetSidebarHidden(hidden){
  if(window.innerWidth<=768)return;
  var sb=document.querySelector('.sidebar');
  var main=document.querySelector('.app-main');
  var btn=document.querySelector('.hamburger-btn');
  var tb=document.querySelector('.app-topbar');
  if(!sb)return;
  var isHidden=sb.classList.contains('sb-hidden');
  if(hidden===isHidden)return; // already in the desired state — skip so it doesn't fight a manual toggle mid-transition
  if(hidden){
    sb.classList.add('sb-hidden');
    document.body.classList.add('sb-hidden-state');
    if(main)main.style.marginLeft='0px';
    if(btn)btn.classList.add('active');
  }else{
    sb.classList.remove('sb-hidden');
    document.body.classList.remove('sb-hidden-state');
    if(main)main.style.marginLeft='220px';
    if(tb)tb.style.left='220px';
    if(btn)btn.classList.remove('active');
  }
}
(function(){
  var _rzSbOrig=window.showPage;
  window.showPage=function(page){
    var r=_rzSbOrig.apply(this,arguments);
    _rzSetSidebarHidden(page==='community'||page==='rizplay');
    return r;
  };
})();

// Forward wheel events from layout empty areas to cm-center. NOT via scrollBy(...,{behavior:
// 'smooth'}) — a wheel gesture fires many events per second, and each scrollBy(smooth) call
// restarts/fights the browser's in-flight easing animation, producing a visible shake/jitter
// instead of smooth motion. Instead: accumulate wheel deltas into a target position and ease
// toward it in one continuous requestAnimationFrame loop, which is what actually produces
// smooth momentum-like scrolling without the restart-jitter problem.
var _cmGapScrollTarget=null,_cmGapScrollRAF=null;
function _cmGapScrollStep(center){
  var diff=_cmGapScrollTarget-center.scrollTop;
  if(Math.abs(diff)<0.5){
    center.scrollTop=_cmGapScrollTarget;
    _cmGapScrollRAF=null;_cmGapScrollTarget=null;
    return;
  }
  center.scrollTop+=diff*0.22;
  _cmGapScrollRAF=requestAnimationFrame(function(){_cmGapScrollStep(center);});
}
document.addEventListener('wheel', function(e) {
  var center = document.querySelector('.cm-center');
  if(!center) return;
  if(center.contains(e.target)){
    // A genuine native scroll directly on the feed — cancel any gap-scroll animation still
    // converging toward its old target, otherwise it keeps pulling scrollTop back every frame
    // and fights this fresh input, producing a reverse/stutter glitch.
    if(_cmGapScrollRAF){cancelAnimationFrame(_cmGapScrollRAF);_cmGapScrollRAF=null;}
    _cmGapScrollTarget=null;
    return;
  }
  var left = document.querySelector('.cm-left');
  var right = document.querySelector('.cm-right');
  if((left && left.contains(e.target)) || (right && right.contains(e.target))) return;
  var layout = document.querySelector('.cm-layout');
  if(!layout || !layout.contains(e.target)) return;
  e.preventDefault();
  var maxScroll=center.scrollHeight-center.clientHeight;
  if(_cmGapScrollTarget===null)_cmGapScrollTarget=center.scrollTop;
  _cmGapScrollTarget=Math.max(0,Math.min(maxScroll,_cmGapScrollTarget+e.deltaY));
  if(!_cmGapScrollRAF)_cmGapScrollStep(center);
}, {passive: false});

