var stDurations={study:25,short:5,long:15};
var stMode='study';
var stRunning=false;
var stTimer=null;
var stSecondsLeft=25*60;
var stTotalSeconds=25*60;
var stSessionsToday=0;
var stMinutesToday=0;
var stLog=[];
var stColors={study:'#1a6b3c',short:'#3B82F6',long:'#8B5CF6'};
var stLabels={study:'পড়াশোনা',short:'Short Break',long:'Long Break'};
function stUpdateDisplay(){
  var m=Math.floor(stSecondsLeft/60),s=stSecondsLeft%60;
  var el=document.getElementById('st-time');
  if(el)el.textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;
  var c=document.getElementById('st-circle');
  if(c){c.setAttribute('stroke-dashoffset',490*(1-stSecondsLeft/stTotalSeconds));c.setAttribute('stroke',stColors[stMode]);}
}
function setMode(m){
  if(stRunning)return;
  stMode=m;stSecondsLeft=stDurations[m]*60;stTotalSeconds=stSecondsLeft;
  ['study','short','long'].forEach(function(x){
    var b=document.getElementById('mode-'+x);
    if(b){b.style.background=x===m?stColors[m]:'#f0f0f0';b.style.color=x===m?'#fff':'#666';}
  });
  var l=document.getElementById('st-label');if(l)l.textContent=stLabels[m];
  stUpdateDisplay();
}
function stToggle(){
  var btn=document.getElementById('st-play-btn');
  if(stRunning){clearInterval(stTimer);stRunning=false;if(btn)btn.innerHTML='▶';}
  else{stRunning=true;if(btn)btn.innerHTML='⏸';
    stTimer=setInterval(function(){
      stSecondsLeft--;stUpdateDisplay();
      if(stSecondsLeft<=0){clearInterval(stTimer);stRunning=false;if(btn)btn.innerHTML='▶';stOnComplete();}
    },1000);
  }
}
function stOnComplete(){
  if(stMode==='study'){
    stSessionsToday++;stMinutesToday+=stDurations.study;
    var sub=document.getElementById('st-subject');
    stLog.push((sub&&sub.value?sub.value:'পড়াশোনা')+' - '+stDurations.study+' মিনিট');
    var logEl=document.getElementById('st-log');
    if(logEl)logEl.innerHTML=stLog.map(function(l){return '\x3Cdiv style="padding:4px 0;border-bottom:1px solid #f5f5f5;color:#444;text-align:left"\x3E✓ '+l+'\x3C/div\x3E';}).join('');
    var s1=document.getElementById('st-sessions'),s2=document.getElementById('st-total-min'),s3=document.getElementById('st-total-ses');
    if(s1)s1.textContent=stSessionsToday;if(s2)s2.textContent=stMinutesToday;if(s3)s3.textContent=stSessionsToday;
    if(stSessionsToday%4===0)setMode('long');else setMode('short');
  }else{setMode('study');}
  if(navigator.vibrate)navigator.vibrate([200,100,200]);
}
function stReset(){
  clearInterval(stTimer);stRunning=false;
  var btn=document.getElementById('st-play-btn');if(btn)btn.innerHTML='▶';
  stSecondsLeft=stDurations[stMode]*60;stTotalSeconds=stSecondsLeft;stUpdateDisplay();
}
function stSkip(){clearInterval(stTimer);stRunning=false;stSecondsLeft=0;stOnComplete();}
function changeDur(m,d){
  stDurations[m]=Math.max(1,stDurations[m]+d);
  var el=document.getElementById('dur-'+m);if(el)el.textContent=stDurations[m];
  if(m===stMode&&!stRunning){stSecondsLeft=stDurations[m]*60;stTotalSeconds=stSecondsLeft;stUpdateDisplay();}
}


