var _R2_WORKER = 'https://rizers-upload.5minuteartsbrand.workers.dev';

async function _r2Upload(file, folder) {
  var ext = (file.name ? file.name.split('.').pop().toLowerCase() : null) || (file.type ? file.type.split('/').pop() : 'bin');
  var fileName = folder + '/' + (window.sbUser ? window.sbUser.id : 'u') + '_' + Date.now() + '.' + ext;
  var res = await fetch(_R2_WORKER + '/upload', {
    method: 'POST',
    headers: { 'X-File-Name': fileName, 'X-File-Type': file.type || 'application/octet-stream' },
    body: file
  });
  if (!res.ok) throw new Error('R2 upload failed: ' + res.status);
  var data = await res.json();
  return data.url;
}

