var _rzAIRecorder = null;
var _rzAIChunks = [];
var _rzAIActive = false;

async function _rzAITranscribe(blob) {
  var fd = new FormData();
  fd.append('file', blob, 'voice.webm');
  fd.append('model', _rzAI.whisperModel);
  fd.append('language', 'bn');
  fd.append('response_format', 'json');
  var res = await _groqProxyFetch('audio/transcriptions', fd, true);
  var data = await res.json();
  return (data.text || '').trim();
}

async function _rzAIClassify(text) {
  var messages = [
    { role: 'system', content: _rzAI.systemPrompt },
    ..._rzAI.examples,
    { role: 'user', content: text }
  ];
  var res = await _groqProxyFetch('chat/completions', JSON.stringify({ model: _rzAI.intentModel, messages: messages, max_tokens: 300, temperature: 0.1 }));
  var data = await res.json();
  var raw = (data.choices && data.choices[0] && data.choices[0].message.content) || '{"action":"unclear","reason":"API error"}';
  try { return JSON.parse(raw); } catch(e) { return { action: 'unclear', reason: 'Parse error' }; }
}

async function _rzAIExecute(intent, originalText) {
  if (!sbUser) return;
  var uid = sbUser.id;
  var today = new Date().toISOString().split('T')[0];
  var result = { success: false, summary: '', detail: '' };

  if (intent.action === 'add_todo') {
    var items = Array.isArray(intent.items) ? intent.items : [intent.items || originalText];
    var rows = items.map(function(t) { return { user_id: uid, title: t, status: 'pending', created_at: new Date().toISOString() }; });
    var { error } = await _sb.from('todo_tasks').insert(rows);
    if (!error) {
      result.success = true;
      result.summary = items.length + 'টি Todo যোগ করা হয়েছে ✅';
      result.detail = items.map(function(t,i){ return (i+1)+'. '+t; }).join('\n');
    }
  } else if (intent.action === 'add_note') {
    var { error } = await _sb.from('smart_notes').insert({ user_id: uid, content: intent.content || originalText, created_at: new Date().toISOString() });
    if (!error) {
      result.success = true;
      result.summary = 'Smart Note সেভ হয়েছে ✅';
      result.detail = intent.content || originalText;
    }
  } else if (intent.action === 'add_goal') {
    var { error } = await _sb.from('adult_goals').insert({ user_id: uid, text: intent.title || originalText, created_at: new Date().toISOString() });
    if (!error) {
      result.success = true;
      result.summary = 'Goal সেট করা হয়েছে ✅';
      result.detail = intent.title || originalText;
    }
  } else if (intent.action === 'add_journal') {
    var { error } = await _sb.from('journal_entries').insert({ user_id: uid, content: intent.content || originalText, created_at: new Date().toISOString() });
    if (!error) {
      result.success = true;
      result.summary = 'Journal Entry লেখা হয়েছে ✅';
      result.detail = intent.content || originalText;
    }
  } else if (intent.action === 'log_namaz') {
    var prayer = intent.prayer || 'fajr';
    var { error } = await _sb.from('adult_namaz_logs').insert({ user_id: uid, prayer: prayer, date: today, status: intent.status || 'completed', created_at: new Date().toISOString() });
    if (!error) {
      result.success = true;
      result.summary = prayer.charAt(0).toUpperCase()+prayer.slice(1)+' নামাজ লগ হয়েছে ✅';
      result.detail = 'নামাজ: '+prayer+' | তারিখ: '+today;
    }
  } else if (intent.action === 'log_fasting') {
    var { error } = await _sb.from('fasting_logs').insert({ user_id: uid, date: today, type: intent.type || 'voluntary', created_at: new Date().toISOString() });
    if (!error) {
      result.success = true;
      result.summary = 'রোজার লগ হয়েছে ✅';
      result.detail = 'তারিখ: '+today;
    }
  } else if (intent.action === 'log_quran') {
    var { error } = await _sb.from('adult_quran_data').upsert({ user_id: uid, last_read: intent.surah || '', pages_today: intent.pages || 1, date: today, updated_at: new Date().toISOString() });
    if (!error) {
      result.success = true;
      result.summary = 'কুরআন তিলাওয়াত লগ হয়েছে ✅';
      result.detail = intent.surah ? 'সূরা: '+intent.surah : 'পেজ: '+(intent.pages||1);
    }
  } else if (intent.action === 'add_finance') {
    var { error } = await _sb.from('finance_transactions').insert({ user_id: uid, amount: intent.amount || 0, type: intent.type || 'expense', note: intent.note || originalText, date: today, created_at: new Date().toISOString() });
    if (!error) {
      result.success = true;
      result.summary = 'Finance entry যোগ হয়েছে ✅';
      result.detail = (intent.type||'expense')+': '+(intent.amount||0)+' টাকা — '+(intent.note||'');
    }
  } else if (intent.action === 'unclear') {
    result.success = false;
    result.summary = 'বুঝতে পারিনি 🤔';
    result.detail = intent.reason || 'আবার বলুন, একটু স্পষ্ট করে।';
  } else {
    result.success = false;
    result.summary = 'এই কাজটা এখনো পারছি না 🔧';
    result.detail = 'Action: '+intent.action;
  }

  return result;
}

async function _rzAISendKnokz(originalText, intent, execResult) {
  if (!sbUser) return;
  var AI_UID = 'rizers-ai-bot';
  var userUid = sbUser.id;
  var ids = [AI_UID, userUid].sort();
  var cid = ids[0] + '_' + ids[1];

  var icon = execResult.success ? '✅' : '⚠️';
  var msgBody = icon + ' **' + execResult.summary + '**\n\n';
  if (execResult.detail) msgBody += execResult.detail + '\n\n';
  msgBody += '🎤 তুমি বলেছিলে: _"' + originalText + '"_';

  await _sb.from('knokz_messages').insert({
    conversation_id: cid,
    sender_id: AI_UID,
    receiver_id: userUid,
    content: msgBody,
    type: 'text',
    sent_at: new Date().toISOString()
  });

  if (typeof _rzAINotify === 'function') _rzAINotify(execResult.summary);
}

function _rzAINotify(msg) {
  var n = document.getElementById('rz-ai-notify');
  if (!n) return;
  n.textContent = msg;
  n.style.display = 'flex';
  setTimeout(function(){ n.style.display = 'none'; }, 3500);
}

async function _rzAIProcess(blob, originalText) {
  _rzAISetUI('processing');
  try {
    var text = originalText || await _rzAITranscribe(blob);
    if (!text) { _rzAISetUI('idle'); _rzAINotify('কিছু শুনতে পাইনি 🎤'); return; }
    var intent = await _rzAIClassify(text);
    var execResult = await _rzAIExecute(intent, text);
    await _rzAISendKnokz(text, intent, execResult);
    _rzAISetUI('done');
    _rzAINotify(execResult.summary);
    setTimeout(function(){ _rzAISetUI('idle'); }, 2000);
  } catch(e) {
    console.error('[RizersAI]', e);
    _rzAISetUI('idle');
    _rzAINotify('কিছু একটা সমস্যা হয়েছে');
  }
}

function _rzAISetUI(state) {
  var btn = document.getElementById('rz-ai-fab');
  if (!btn) return;
  var icon = btn.querySelector('.rz-ai-icon');
  if (state === 'recording') {
    btn.style.background = 'linear-gradient(135deg,#EF4444,#DC2626)';
    btn.style.animation = 'rz-ai-pulse 1s infinite';
    if (icon) icon.textContent = '⏹';
  } else if (state === 'processing') {
    btn.style.background = 'linear-gradient(135deg,#F59E0B,#D97706)';
    btn.style.animation = 'rz-ai-spin 1s linear infinite';
    if (icon) icon.textContent = '⟳';
  } else if (state === 'done') {
    btn.style.background = 'linear-gradient(135deg,#10B981,#059669)';
    btn.style.animation = 'none';
    if (icon) icon.textContent = '✓';
  } else {
    btn.style.background = 'linear-gradient(135deg,#7C3AED,#5B21B6)';
    btn.style.animation = 'none';
    if (icon) icon.textContent = '🎙';
  }
}

function _rzAIStartRecord() {
  if (_rzAIActive) { _rzAIStopRecord(); return; }
  navigator.mediaDevices.getUserMedia({ audio: true }).then(function(stream) {
    _rzAIActive = true;
    _rzAIChunks = [];
    _rzAISetUI('recording');
    _rzAIRecorder = new MediaRecorder(stream, { mimeType: 'audio/webm' });
    _rzAIRecorder.ondataavailable = function(e) { if (e.data.size > 0) _rzAIChunks.push(e.data); };
    _rzAIRecorder.onstop = function() {
      stream.getTracks().forEach(function(t){ t.stop(); });
      var blob = new Blob(_rzAIChunks, { type: 'audio/webm' });
      _rzAIActive = false;
      _rzAIProcess(blob, null);
    };
    _rzAIRecorder.start(250);
  }).catch(function(e) {
    _rzAINotify('Mic access দরকার 🎤');
  });
}

function _rzAIStopRecord() {
  if (_rzAIRecorder && _rzAIRecorder.state !== 'inactive') _rzAIRecorder.stop();
  _rzAIActive = false;
}

