/* ─── AUTH MODAL ────────────────────────────────────────── */
function sbOpenAuth(tab) {
  document.getElementById('sb-auth').classList.add('show');
  sbSwitchTab(tab || 'login');
  sbClearMsg();
}
function sbCloseAuth() {
  document.getElementById('sb-auth').classList.remove('show');
}
function sbSwitchTab(t) {
  var toLogin = t === 'login';
  var loginForm = document.getElementById('sb-login-form');
  var signupForm = document.getElementById('sb-signup-form');
  loginForm.style.display = toLogin ? '' : 'none';
  signupForm.style.display = toLogin ? 'none' : '';
  // Animate panel in from correct direction
  var activePanel = toLogin ? loginForm : signupForm;
  activePanel.classList.remove('sb-panel','from-left');
  void activePanel.offsetWidth;
  activePanel.classList.add('sb-panel');
  if (toLogin) activePanel.classList.add('from-left');
  document.getElementById('sb-tab-login').classList.toggle('on', toLogin);
  document.getElementById('sb-tab-signup').classList.toggle('on', !toLogin);
  sbClearMsg();
  // Focus first input
  setTimeout(function(){ var inp = activePanel.querySelector('input'); if(inp) inp.focus(); }, 100);
}
function sbShowErr(msg) {
  var e = document.getElementById('sb-err');
  e.textContent = msg; e.classList.add('show');
  document.getElementById('sb-ok').classList.remove('show');
}
function sbShowOk(msg) {
  var e = document.getElementById('sb-ok');
  e.textContent = msg; e.classList.add('show');
  document.getElementById('sb-err').classList.remove('show');
}
function sbClearMsg() {
  document.getElementById('sb-err').classList.remove('show');
  document.getElementById('sb-ok').classList.remove('show');
}

function _makeUsername(name) {
  var base = (name || '').toLowerCase().replace(/[^a-z0-9]/g, '');
  if (!base) base = 'rizer';
  var n = Math.floor(Math.random() * 900) + 100;
  return base + n;
}

/* ─── SIGN UP ───────────────────────────────────────────── */
async function sbSignUp() {
  var name = document.getElementById('sb-signup-name').value.trim();
  var phoneRaw = document.getElementById('sb-signup-email').value.trim();
  var pass = document.getElementById('sb-signup-pass').value;
  var digits = phoneRaw.replace(/\D/g,'');
  if (!name) return sbShowErr('নাম দাও');
  if (digits.length < 10) return sbShowErr('সঠিক ফোন নম্বর দাও (কমপক্ষে ১০ সংখ্যা)');
  if (pass.length < 6) return sbShowErr('Password কমপক্ষে 6 অক্ষর');
  var email = 'p' + digits + '@xwdmhwaxzwowlezqruaj.supabase.co';
  var btn = document.getElementById('sb-signup-btn');
  btn.disabled = true; btn.textContent = 'Loading...';
  try {
    var { data, error } = await _sb.auth.signUp({ email, password: pass });
    if (error) { sbShowErr(error.message); return; }
    if (data.user) {
      await _sb.from('profiles').insert({ id: data.user.id, name: name, username: _makeUsername(name) });
    }
    sbShowOk('✓ Account তৈরি হয়েছে! এখন Login করো।');
  } catch(e) { sbShowErr(e.message); }
  finally { btn.disabled = false; btn.textContent = 'Account বানাও'; }
}

/* ─── SIGN IN ───────────────────────────────────────────── */
async function sbSignIn() {
  var phoneRaw = document.getElementById('sb-login-email').value.trim();
  var pass = document.getElementById('sb-login-pass').value;
  var digits = phoneRaw.replace(/\D/g,'');
  if (!digits || digits.length < 10) return sbShowErr('সঠিক ফোন নম্বর দাও');
  if (!pass) return sbShowErr('Password দাও');
  var email = 'p' + digits + '@xwdmhwaxzwowlezqruaj.supabase.co';
  var btn = document.getElementById('sb-login-btn');
  btn.disabled = true; btn.textContent = 'Loading...';
  try {
    var { data, error } = await _sb.auth.signInWithPassword({ email, password: pass });
    if (error) { sbShowErr(error.message); return; }
    sbUser = data.user; window.sbUser = sbUser;
    sbCloseAuth();
    rzLoadBondsCacheForUser(sbUser.id);
    window._rzBondsCachePromise = rzLoadBondsCache();
    await sbLoadProfile();
    rzStartRealtimeListener();
    if(typeof window.kzStartGlobal==='function') window.kzStartGlobal();
    if(typeof window.kzLoadUnread==='function') window.kzLoadUnread();
    sbUpdateUI();
    cmToast('স্বাগতম! ' + (sbProfile ? sbProfile.name : '') + ' ✓');
  } catch(e) { sbShowErr(e.message); }
  finally { btn.disabled = false; btn.textContent = 'Login করুন'; }
}

/* ─── SIGN OUT ──────────────────────────────────────────── */
async function sbSignOut() {
  await _sb.auth.signOut();
  sbUser = null; window.sbUser = null; sbProfile = null;
  sbUpdateUI();
  cmToast('Logged out');
}

/* ─── LOAD PROFILE ──────────────────────────────────────── */
async function sbLoadProfile() {
  if (!sbUser) return;
  var { data } = await _sb.from('profiles').select('*').eq('id', sbUser.id).maybeSingle();
  sbProfile = data;
  window.sbProfile = data;
}

/* ─── BONDS CACHE (localStorage-backed for instant load on refresh) ─── */
window._rzBondedIds = new Set();
window._rzBondsCachePromise = null;

// Reads user ID from Supabase's own localStorage session — runs at script load, fully synchronous, 0ms
(function rzPreloadBondsCache() {
  try {
    var raw = localStorage.getItem('sb-xwdmhwaxzwowlezqruaj-auth-token');
    if (!raw) return;
    var session = JSON.parse(raw);
    var uid = session && session.user && session.user.id;
    if (!uid) return;
    var stored = localStorage.getItem('rz_bonds_' + uid);
    if (stored) window._rzBondedIds = new Set(JSON.parse(stored));
  } catch(e) {}
})();

// Load bonds for a SPECIFIC user (called after getSession to ensure correctness)
function rzLoadBondsCacheForUser(uid) {
  try {
    var stored = localStorage.getItem('rz_bonds_' + uid);
    if (stored) window._rzBondedIds = new Set(JSON.parse(stored));
  } catch(e) {}
}

function rzSaveBondsToStorage() {
  try {
    if (!sbUser) return;
    localStorage.setItem('rz_uid', sbUser.id);
    localStorage.setItem('rz_bonds_' + sbUser.id, JSON.stringify([...window._rzBondedIds]));
  } catch(e) {}
}

async function rzLoadBondsCache() {
  if (!sbUser || typeof _sb === 'undefined') return;
  try {
    var r = await _sb.from('rizerships').select('rizer_id').eq('user_id', sbUser.id);
    window._rzBondedIds = new Set((r.data || []).map(function(x){ return x.rizer_id; }));
    rzSaveBondsToStorage(); // update localStorage for next refresh
  } catch(e) {}
}

function rzAddBondCache(userId) {
  window._rzBondedIds.add(userId);
  rzSaveBondsToStorage(); // persist so next refresh is instant
  // If currently viewing this user's profile, update button instantly
  if(_pfVisitingUserId === userId){
    var btn=document.getElementById('pf-add-rizer-btn');
    var txt=document.getElementById('pf-rise-btn-txt');
    var icon=document.getElementById('pf-rise-btn-icon');
    if(btn&&txt){ _pfRiseStatus='bonded'; _pfSetBondedBtn(btn,txt,icon); }
  }
  // Send auto welcome message in Knokz
  if(typeof window.kzSendWelcome==='function') window.kzSendWelcome(userId);
}
function rzIsBonded(userId) {
  return window._rzBondedIds.has(userId);
}

/* ─── REALTIME: listen for new bonds where I am rizer_id (someone accepted my request) ─── */
window._rzRealtimeSub = null;
function rzStartRealtimeListener(){
  if(window._rzRealtimeSub || !sbUser || typeof _sb==='undefined') return;
  window._rzRealtimeSub = _sb
    .channel('rz-bonds-'+sbUser.id)
    .on('postgres_changes', {
      event: 'INSERT',
      schema: 'public',
      table: 'rizerships',
      filter: 'user_id=eq.'+sbUser.id
    }, function(payload){
      var newBond = payload.new;
      if(newBond && newBond.rizer_id){
        rzAddBondCache(newBond.rizer_id); // updates button instantly if on that profile
      }
    })
    .subscribe();
}
function rzStopRealtimeListener(){
  if(window._rzRealtimeSub){ _sb.removeChannel(window._rzRealtimeSub); window._rzRealtimeSub=null; }
}

/* ─── REALTIME: notifications ─────────────────────────────── */
window._rzNtfRealtimeSub=null;
function ntfStartRealtime(){
  if(window._rzNtfRealtimeSub||!sbUser||typeof _sb==='undefined') return;
  window._rzNtfRealtimeSub=_sb
    .channel('rz-ntf-'+sbUser.id)
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'user_id=eq.'+sbUser.id},function(payload){
      var n=payload.new;if(!n)return;
      var meta=n.metadata||{};
      if(typeof meta==='string'){try{meta=JSON.parse(meta);}catch(e){meta={};}}
      ntfData.unshift({id:n.id,type:n.type,title:n.title,msg:n.msg||'',time:ntfTimeAgo(n.created_at),read:false,dot:n.dot||'#FF8A00',metadata:meta});
      ntfUpdateBadge();
      var sheet=document.getElementById('ntf-sheet');
      if(sheet&&sheet.classList.contains('ntf-open')) ntfSheetRender();
    })
    .subscribe();
}

/* ─── UPDATE UI WITH REAL USER ──────────────────────────── */
function sbUpdateUI() {
  var loggedIn = !!sbUser;
  /* Topbar login button */
  var topBtn = document.getElementById('sb-login-topbtn');
  if (topBtn) {
    topBtn.textContent = loggedIn ? 'Logout' : 'Login';
    topBtn.style.color = loggedIn ? '#EF4444' : '#FF8A00';
    topBtn.style.borderColor = loggedIn ? '#EF4444' : '#FF8A00';
  }
  /* Topbar avatar initial */
  var topAvatar = document.getElementById('rz-avatar');
  if (topAvatar && sbProfile) topAvatar.textContent = sbProfile.name.charAt(0).toUpperCase();
  /* Bottom nav profile avatar */
  var bnAv2 = document.getElementById('rz-bn-av');
  if (bnAv2) {
    if (loggedIn && sbProfile) {
      bnAv2.textContent = sbProfile.name.charAt(0).toUpperCase();
      bnAv2.style.background = 'linear-gradient(135deg,#FF8A00,#FFB800)';
    } else {
      bnAv2.textContent = '👤';
      bnAv2.style.fontSize = '16px';
      bnAv2.style.background = '#e0e0e0';
    }
  }
  /* Show/hide auth button */
  var authBtns = document.querySelectorAll('[data-auth-btn]');
  authBtns.forEach(function(b) {
    b.textContent = loggedIn ? 'Logout' : 'Login';
    b.onclick = loggedIn ? sbSignOut : function(){ sbOpenAuth('login'); };
  });
  /* Community profile card */
  if (sbProfile) {
    var nameEl = document.querySelector('#cm-profile-name, .cm-profile-name');
    var streakEl = document.querySelector('#cm-profile-streak, .cm-profile-streak');
    var ptsEl = document.querySelector('#cm-profile-pts, .cm-profile-pts');
    var initial = sbProfile.name.charAt(0).toUpperCase();
    if (nameEl) nameEl.textContent = sbProfile.name;
    if (streakEl) streakEl.textContent = sbProfile.streak_count || 0;
    if (ptsEl) ptsEl.textContent = sbProfile.points || 0;
    var profAv = document.getElementById('cm-profile-av');
    if (profAv) profAv.textContent = initial;
    var compAv = document.getElementById('cm-composer-av');
    if (compAv) compAv.textContent = initial;
    var compUn = document.getElementById('cm-composer-uname');
    if (compUn) compUn.textContent = sbProfile.name;
    var topAv = document.getElementById('rz-avatar');
    if (topAv) topAv.textContent = initial;
    var bnAv = document.getElementById('rz-bn-av');
    if (bnAv) bnAv.textContent = initial;
    /* Sidebar user footer */
    var sbSideAv = document.getElementById('sb-user-av');
    var sbSideName = document.getElementById('sb-user-name');
    if (sbSideName) sbSideName.textContent = sbProfile.name || 'User';
    if (sbSideAv) {
      if (sbProfile.avatar_url) {
        sbSideAv.style.background = 'transparent';
        sbSideAv.style.overflow = 'hidden';
        sbSideAv.innerHTML = '<img src="'+sbProfile.avatar_url+'" style="width:100%;height:100%;object-fit:cover;border-radius:50%">';
      } else {
        sbSideAv.innerHTML = '';
        sbSideAv.textContent = sbProfile.name.charAt(0).toUpperCase();
        sbSideAv.style.background = 'linear-gradient(135deg,#FF8A00,#FFB800)';
        sbSideAv.style.overflow = '';
      }
    }
    var sbBadge = document.getElementById('sb-verified-badge');
    if (sbBadge) sbBadge.src = 'Only%20Badge-02.svg';
  }
  /* Populate profile page with real data whenever logged in — skip if viewing another user's profile */
  var _rvPending=null;try{_rvPending=sessionStorage.getItem('rz_visiting_user');}catch(e){}
  var _isVisitorMode=_rvPending||(function(){var pg=document.getElementById('profile-page');return pg&&pg.classList.contains('visitor-mode');})();
  if (loggedIn && !_isVisitorMode && typeof pfRenderPage === 'function') pfRenderPage();
  /* Sync avatar photo everywhere if set — skip pf-avatar in visitor mode */
  if (loggedIn && sbProfile && sbProfile.avatar_url && typeof pfAvUpdateUI==='function'){
    if(_isVisitorMode){
      // Only update non-profile elements when visiting another user's profile
      window._myAvatarUrl=sbProfile.avatar_url;
    } else {
      pfAvUpdateUI(sbProfile.avatar_url);
    }
  }
  /* If logged in and still on landing page → go to app (skip if onboarding in progress) */
  if (loggedIn && !window.lpOnboarding) {
    var landing = document.getElementById('landing-section');
    var appLayout = document.getElementById('app-layout');
    if (landing && landing.style.display !== 'none' && appLayout && !appLayout.classList.contains('visible')) {
      showApp(true);
    }
    /* Reload posts if community is open — but only once per actual signed-in user, not on every
       sbUpdateUI() call (this runs on every auth re-validation, including tab-switch-back). A
       plain user-id check (not a boolean flag) so a real account switch still reloads. */
    if (appLayout && appLayout.classList.contains('visible')) {
      if (typeof cmLoadPosts === 'function' && typeof _sb !== 'undefined' && window._rzPostsLoadedForUser !== (sbUser&&sbUser.id)) {
        window._rzPostsLoadedForUser = sbUser&&sbUser.id;
        cmLoadPosts();
      }
    }
    /* Load real notification badge count from Supabase */
    if(typeof ntfLoadBadge==='function') ntfLoadBadge();
    if(typeof ntfStartRealtime==='function') ntfStartRealtime();
  }
}

/* ─── SESSION CHECK ON LOAD ─────────────────────────────── */
(async function sbInit() {
  var { data: { session } } = await _sb.auth.getSession();
  if (session) {
    sbUser = session.user; window.sbUser = sbUser;
    rzLoadBondsCacheForUser(sbUser.id); // instant — correct user's bonds from localStorage
    /* Read visiting user BEFORE sbUpdateUI — showPage('dashboard') inside sbUpdateUI clears sessionStorage */
    var _rvId = null;
    try { _rvId = sessionStorage.getItem('rz_visiting_user'); } catch(e) {}
    // Refresh bond cache from Supabase in background
    window._rzBondsCachePromise = rzLoadBondsCache();
    await sbLoadProfile();
    rzStartRealtimeListener();
    ntfStartRealtime();
    sbUpdateUI();
    /* Restore visitor profile if user refreshed while viewing someone else's profile */
    if(_rvId && typeof viewUserProfile === 'function') viewUserProfile(_rvId);
  } else {
    /* Token was stale/expired — remove preauth so landing shows cleanly */
    document.documentElement.removeAttribute('data-preauth');
    setTimeout(rzHideSplash, Math.max(0, 1000-(Date.now()-window._rzLoadTime)));
  }
  /* Listen for auth changes */
  _sb.auth.onAuthStateChange(async function(event, session) {
    // NOTE: this fires on every silent session re-validation too (tab regains focus/visibility),
    // not just real sign-in/out — it used to also serve as an implicit retry for sbLoadProfile()/
    // sbUpdateUI() if the very first attempt (in the `if(session)` branch above) hadn't finished
    // yet or failed. An earlier attempt to skip re-firing here for "same user, nothing changed"
    // broke that retry — the profile-card name/avatar could get stuck on "লোড হচ্ছে..." forever
    // if sbLoadProfile() lost the race the first time. So: always run this (it's cheap/idempotent),
    // and only skip the genuinely expensive/disruptive part — cmLoadPosts() re-rendering the
    // whole feed — inside sbUpdateUI() itself, gated separately below.
    sbUser = session ? session.user : null; window.sbUser = sbUser;
    if (sbUser) { rzLoadBondsCacheForUser(sbUser.id); window._rzBondsCachePromise = rzLoadBondsCache(); await sbLoadProfile(); rzStartRealtimeListener(); if(typeof window.kzStartGlobal==='function') window.kzStartGlobal(); if(typeof window.kzLoadUnread==='function') window.kzLoadUnread(); if(typeof window._kzFlushOfflineQueue==='function') window._kzFlushOfflineQueue(); }
    else { sbProfile = null; window._rzBondedIds = new Set(); window._rzBondsCachePromise = null; rzStopRealtimeListener(); }
    sbUpdateUI();
  });
})();

