function waAutoDetectCode() {
  var tz = ''; try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone; } catch(e) {}
  for (var i = 0; i < WA_CODES.length; i++) { if (WA_CODES[i].tz === tz) return WA_CODES[i].code; }
  return '+880';
}

function waPopulateCC(sel, selectedCode) {
  if (!sel || sel.options.length > 1) return;
  sel.innerHTML = '';
  WA_CODES.forEach(function(c) {
    var opt = document.createElement('option');
    opt.value = c.code;
    opt.textContent = c.flag + ' ' + c.code;
    opt.title = c.name;
    if (c.code === selectedCode) opt.selected = true;
    sel.appendChild(opt);
  });
}

/* ── Location Autocomplete (Nominatim/OSM) ──────────────── */
var _locTimer = {};

function locSearch(q, field) {
  var dd = document.getElementById('loc-dd-' + field);
  if (!dd) return;
  q = (q || '').trim();
  if (!q) { dd.classList.remove('show'); return; }
  if (q.length < 2) { dd.classList.remove('show'); return; }

  dd.innerHTML = '<div class="loc-loading">Searching…</div>';
  dd.classList.add('show');

  clearTimeout(_locTimer[field]);
  _locTimer[field] = setTimeout(function() {
    var url = 'https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(q)
      + '&format=json&addressdetails=1&limit=7&accept-language=en'
      + '&email=jubayerpro01@gmail.com';
    fetch(url)
      .then(function(r){ return r.json(); })
      .then(function(data){ locRender(data, field, q); })
      .catch(function(){ dd.classList.remove('show'); });
  }, 380);
}

function locBuildDisplay(addr) {
  var place = addr.neighbourhood || addr.suburb || addr.city_district ||
              addr.village || addr.town || addr.municipality || addr.hamlet;
  var city  = addr.city || addr.town || addr.county;
  var state = addr.state;
  var country = addr.country;
  var parts = [];
  if (place) parts.push(place);
  if (city && city !== place) parts.push(city);
  if (state && state !== city && state !== place) parts.push(state);
  if (country) parts.push(country);
  return parts.slice(0, 3).join(', ');
}

function locBuildSecondary(addr) {
  var district = addr.county || addr.state_district;
  var division = addr.state;
  var country  = addr.country;
  var parts = [];
  if (district && district !== division) parts.push(district);
  if (division) parts.push(division);
  if (country)  parts.push(country);
  return parts.slice(0, 3).join(', ');
}

var _locStore = {};

function locRender(data, field, q) {
  var dd = document.getElementById('loc-dd-' + field);
  if (!dd) return;
  if (!data || !data.length) { dd.innerHTML = '<div class="loc-loading">No results found</div>'; return; }

  var pinSvg = '<svg viewBox="0 0 24 24" style="width:14px;height:14px;fill:currentColor"><path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z"/></svg>';

  var seen = {}, results = [];
  data.forEach(function(item) {
    var addr = item.address || {};
    var primary = locBuildDisplay(addr) || item.display_name;
    if (seen[primary]) return;
    seen[primary] = true;
    results.push({ primary: primary, secondary: locBuildSecondary(addr),
                   lat: parseFloat(item.lat), lon: parseFloat(item.lon), address: addr });
  });
  results = results.slice(0, 6);
  _locStore[field] = results;

  dd.innerHTML = results.map(function(r, i) {
    return '<div class="loc-item" onmousedown="locSelectIdx(' + i + ',\'' + field + '\')">'
      + '<span class="loc-item-ic">' + pinSvg + '</span>'
      + '<div class="loc-item-body">'
      + '<div class="loc-item-primary">' + escapeHtml(r.primary) + '</div>'
      + (r.secondary ? '<div class="loc-item-secondary">' + escapeHtml(r.secondary) + '</div>' : '')
      + '</div></div>';
  }).join('');
  dd.classList.add('show');
}

function locSelectIdx(i, field) {
  var r = (_locStore[field] || [])[i];
  if (!r) return;
  var inp = document.getElementById('loc-inp-' + field);
  if (inp) inp.value = r.primary;
  window['_locPending_' + field] = { lat: r.lat, lon: r.lon, address: r.address, display: r.primary };
  locHide(field);
}

function locHide(field) {
  var dd = document.getElementById('loc-dd-' + field);
  if (dd) dd.classList.remove('show');
}

/* ── Username availability check ───────────────────────── */
var _unTimer, _unAvail = false;

function unCheckUsername(raw) {
  var val = raw.toLowerCase().replace(/[^a-z0-9_.]/g, '');
  var inp = document.getElementById('pf-ieinp-username');
  if (inp && inp.value !== val) inp.value = val;
  var status  = document.getElementById('un-status');
  var saveBtn = document.getElementById('un-save-btn');
  _unAvail = false;
  if (saveBtn) saveBtn.disabled = true;
  if (!status) return;

  if (!val || val.length < 3) {
    status.innerHTML = val.length > 0 ? '<span class="un-taken">Minimum 3 characters</span>' : '';
    return;
  }

  var current = (window.sbProfile && window.sbProfile.username) ? window.sbProfile.username.toLowerCase() : '';
  if (val === current) {
    status.innerHTML = '<span class="un-avail">✓ Your current username</span>';
    _unAvail = true;
    if (saveBtn) saveBtn.disabled = false;
    return;
  }

  status.innerHTML = '<span class="un-hint">Checking…</span>';
  clearTimeout(_unTimer);
  _unTimer = setTimeout(function() {
    if (typeof _sb === 'undefined') {
      status.innerHTML = '<span class="un-avail">✓ Available!</span>';
      _unAvail = true;
      if (saveBtn) saveBtn.disabled = false;
      return;
    }
    _sb.from('profiles').select('id').eq('username', val).then(function(res) {
      var taken = res.data && res.data.length > 0;
      if (taken) {
        status.innerHTML = '<span class="un-taken">✗ Already taken</span>';
        _unAvail = false;
        if (saveBtn) saveBtn.disabled = true;
      } else {
        status.innerHTML = '<span class="un-avail">✓ Available!</span>';
        _unAvail = true;
        if (saveBtn) saveBtn.disabled = false;
      }
    });
  }, 500);
}

