function wkPosInput(v) {
  var dd = document.getElementById('wk-pos-dd');
  if (!dd) return;
  var q = (v || '').trim();
  var ql = q.toLowerCase();
  var items, hasExact = false;
  if (q) {
    var starts   = RIZERS_POSITIONS.filter(function(p){ return p.toLowerCase().indexOf(ql) === 0; });
    var contains = RIZERS_POSITIONS.filter(function(p){ return p.toLowerCase().indexOf(ql) > 0; });
    items = starts.concat(contains).slice(0, 8);
    hasExact = RIZERS_POSITIONS.some(function(p){ return p.toLowerCase() === ql; });
  } else {
    items = RIZERS_POSITIONS.slice(0, 10);
  }
  var html = items.map(function(c) {
    var safe = escapeHtml(c);
    var hi = q ? safe.replace(new RegExp('(' + escapeHtml(q).replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + ')', 'gi'), '<strong style="color:#FF8A00">$1</strong>') : safe;
    return '<div class="wk-pos-item" onmousedown="wkPosSelect(\'' + c.replace(/\\/g,'\\\\').replace(/'/g,"\\'") + '\')">' + hi + '</div>';
  }).join('');
  if (q.length > 1 && !hasExact) {
    html += '<div class="wk-pos-item wk-pos-add" onmousedown="wkPosAddCustom(\'' + q.replace(/\\/g,'\\\\').replace(/'/g,"\\'") + '\')">'
          + '<svg viewBox="0 0 24 24" style="width:15px;height:15px;fill:currentColor;flex-shrink:0"><path d="M19 13h-6v6h-2v-6H5v-2h6V5h2v6h6v2z"/></svg>'
          + 'Add &ldquo;' + escapeHtml(q) + '&rdquo;</div>';
  }
  if (!html) { dd.classList.remove('show'); return; }
  dd.innerHTML = html;
  dd.classList.add('show');
}

