/* ── Profile Completeness / Verified Badge ────────────────
   Mirrors pf_recompute_completion()'s point table in
   scripts/db-fixes/profile_verification_score.sql — the DB trigger is the real source of
   truth for is_verified (recomputed server-side on every profile write), this is purely a
   client-side preview so the user sees live progress while typing, before saving. Keep both
   in sync by hand if the weights ever change. */
var PF_COMPLETENESS_FIELDS = [
  { key:'avatar_url', tier:'important', points:30, label:'Profile Photo', icon:'📷' },
  { key:'bio',      tier:'important', points:15, label:'Bio / Tagline',    inputId:'pfe-bio',        icon:'📝' },
  { key:'category', tier:'important', points:15, label:'Category',        inputId:'pfe-category',    icon:'🏷️' },
  { key:'gender',   tier:'important', points:10, label:'Gender',          inputId:'pfe-gender',      icon:'👤' },
  { key:'city',     tier:'important', points:10, label:'Current City',    inputId:'pfe-city',        icon:'📍' },
  { key:'birthday', tier:'important', points:10, label:'Birthday',        inputId:'pfe-birthday',    icon:'🎂' },
  { key:'work',     tier:'important', points:10, label:'Occupation',      inputId:'pfe-occupation',  icon:'💼' },
  { key:'hometown',            tier:'optional', points:5, label:'Hometown',            inputId:'pfe-hometown' },
  { key:'company',             tier:'optional', points:5, label:'Company',             inputId:'pfe-company' },
  { key:'education',           tier:'optional', points:5, label:'Education',           inputId:'pfe-education' },
  { key:'relationship_status', tier:'optional', points:5, label:'Relationship Status', inputId:'pfe-relationship' },
  { key:'goals',                tier:'optional', points:5, label:'Goal / Intention',   inputId:'pfe-goals' },
  { key:'website',              tier:'optional', points:5, label:'Website',            inputId:'pfe-website' },
  { key:'youtube',              tier:'optional', points:5, label:'YouTube',            inputId:'pfe-youtube' },
  { key:'instagram',            tier:'optional', points:5, label:'Instagram',          inputId:'pfe-instagram' },
  { key:'madhhab',              tier:'optional', points:5, label:'Madhhab',            inputId:'pfe-madhhab' },
  { key:'quran_goal',           tier:'optional', points:5, label:'Daily Quran Goal',   inputId:'pfe-quran-goal' }
];

function pfComputeCompleteness() {
  var important = 0, importantMax = 0, optional = 0, missing = [];
  PF_COMPLETENESS_FIELDS.forEach(function(f) {
    var filled;
    if (f.key === 'avatar_url') {
      // Not editable from this modal (separate upload flow) — reflects the currently saved value.
      filled = !!(window.sbProfile && window.sbProfile.avatar_url);
    } else if (f.key === 'quran_goal') {
      var el = document.getElementById(f.inputId);
      filled = el && parseInt(el.value, 10) > 0;
    } else {
      var el2 = document.getElementById(f.inputId);
      filled = el2 && el2.value && el2.value.trim() !== '';
    }
    if (f.tier === 'important') { importantMax += f.points; if (filled) important += f.points; else missing.push(f); }
    else if (filled) optional += f.points;
  });
  return { important:important, importantMax:importantMax, optional:optional, total:important+optional, missing:missing, verified: important >= importantMax };
}

function pfRenderCompletenessWidget() {
  var c = pfComputeCompleteness();
  var statusEl = document.getElementById('pfe-comp-status');
  if (!statusEl) return;
  var pctEl = document.getElementById('pfe-comp-pct');
  var barEl = document.getElementById('pfe-comp-bar');
  var listEl = document.getElementById('pfe-comp-checklist');
  var pct = Math.round((c.important / c.importantMax) * 100);
  pctEl.textContent = pct + '%';
  barEl.style.width = pct + '%';
  statusEl.textContent = c.verified
    ? '🎉 Verified badge earned! আরও তথ্য দিলে score বাড়বে'
    : 'Verified badge পেতে আরও ' + c.missing.length + 'টি জরুরি তথ্য দরকার';
  listEl.innerHTML = PF_COMPLETENESS_FIELDS.filter(function(f){ return f.tier === 'important'; }).map(function(f) {
    var done = c.missing.indexOf(f) === -1;
    var jump = f.key === 'avatar_url' ? "pfAvSheetOpen()" : "document.getElementById('" + f.inputId + "').focus()";
    return '<div onclick="' + jump + '" style="display:flex;align-items:center;gap:8px;font-size:12.5px;color:' + (done ? 'var(--text)' : 'var(--sub-text)') + ';cursor:pointer">' +
      '<span style="width:16px;height:16px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;' +
      (done ? 'background:#22c55e;color:#fff' : 'background:var(--border);color:transparent') + '">✓</span>' + escapeHtml(f.label) + '</div>';
  }).join('');
}

var _pfCompletenessWired = false;
function pfWireCompletenessListeners() {
  if (_pfCompletenessWired) return;
  _pfCompletenessWired = true;
  var body = document.querySelector('#pf-edit-modal .pfe-body');
  if (!body) return;
  body.addEventListener('input', pfRenderCompletenessWidget);
  body.addEventListener('change', pfRenderCompletenessWidget);
}

function pfCelebrateVerified() {
  if (!document.getElementById('rz-confetti-style')) {
    var style = document.createElement('style');
    style.id = 'rz-confetti-style';
    style.textContent = '@keyframes rzFall{0%{transform:translateY(0) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}';
    document.head.appendChild(style);
  }
  var overlay = document.createElement('div');
  overlay.id = 'pf-verified-confetti';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;pointer-events:none;overflow:hidden';
  var emojis = ['🎉','🏆','⭐','✨','💫','🥇'];
  var html = '';
  for (var i = 0; i < 24; i++) {
    var left = Math.floor(Math.random() * 100), delay = (Math.random()*1.5).toFixed(2), dur = (2+Math.random()*2).toFixed(2);
    html += '<div style="position:absolute;left:'+left+'%;top:-40px;font-size:22px;animation:rzFall '+dur+'s '+delay+'s ease-in forwards">'+emojis[Math.floor(Math.random()*emojis.length)]+'</div>';
  }
  overlay.innerHTML = html;
  document.body.appendChild(overlay);
  if (typeof cmToast === 'function') cmToast('🎉 Congrats! তুমি এখন Verified ✓');
  setTimeout(function(){ if (overlay.parentNode) overlay.parentNode.removeChild(overlay); }, 5500);
}

// Same tier/points as pfComputeCompleteness() but reads the already-saved window.sbProfile
// directly instead of live modal form inputs — powers the About-tab score card, which is
// visible outside the Edit Profile modal and must reflect real saved state at all times.
function pfComputeSavedCompleteness() {
  var p = window.sbProfile || {};
  var important = 0, importantMax = 0, optional = 0, missing = [];
  PF_COMPLETENESS_FIELDS.forEach(function(f) {
    var filled;
    if (f.key === 'avatar_url') {
      filled = !!p.avatar_url;
    } else if (f.key === 'category') {
      filled = pfCatGetFromProfile().length > 0;
    } else if (f.key === 'quran_goal') {
      filled = parseInt(p.quran_goal, 10) > 0;
    } else {
      filled = p[f.key] && (''+p[f.key]).trim() !== '';
    }
    if (f.tier === 'important') { importantMax += f.points; if (filled) important += f.points; else missing.push(f); }
    else if (filled) optional += f.points;
  });
  return { important:important, importantMax:importantMax, optional:optional, total:important+optional, missing:missing, verified: important >= importantMax };
}

function pfRenderScoreCard() {
  var ringEl = document.getElementById('pfe-sc-ring');
  var ringLabelEl = document.getElementById('pfe-sc-ring-label');
  var titleEl = document.getElementById('pfe-sc-title');
  var subEl = document.getElementById('pfe-sc-sub');
  var chipsEl = document.getElementById('pfe-sc-chips');
  var ctaEl = document.getElementById('pfe-sc-cta');
  if (!ringEl || !titleEl || !subEl || !chipsEl || !ctaEl) return;
  var p = window.sbProfile || {};
  // Once is_verified is true — real score or manual override, doesn't matter — stop nagging;
  // the card's job is "do you have the badge," not "did you earn every point fairly."
  var verified = !!p.is_verified;
  var c = pfComputeSavedCompleteness();
  var pct = c.importantMax ? Math.round((c.important / c.importantMax) * 100) : 0;
  var importantFields = PF_COMPLETENESS_FIELDS.filter(function(f){ return f.tier === 'important'; });
  var doneCount = importantFields.length - c.missing.length;

  var R = 27, CIRC = 2 * Math.PI * R;
  ringEl.style.strokeDasharray = CIRC;
  ringEl.style.strokeDashoffset = CIRC * (1 - (verified ? 100 : pct) / 100);
  if (ringLabelEl) ringLabelEl.textContent = verified ? '✓' : pct + '%';

  chipsEl.innerHTML = importantFields.map(function(f) {
    var done = c.missing.indexOf(f) === -1;
    return '<div onclick="pfJumpToField(\'' + f.key + '\')" title="' + escapeHtml(f.label) + '" style="width:32px;height:32px;border-radius:9px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:15px;cursor:pointer;' +
      (done ? 'background:linear-gradient(135deg,#FF8A00,#FFC400);box-shadow:0 2px 6px rgba(255,138,0,.35)' : 'background:var(--border);opacity:.55') + '">' + f.icon + '</div>';
  }).join('');

  if (verified) {
    titleEl.textContent = '🎉 Profile Complete';
    subEl.textContent = 'সব জরুরি তথ্য দেওয়া হয়েছে — Verified badge আনলক হয়েছে ✓ আরও তথ্য দিলে প্রোফাইল আরও শক্তিশালী হবে।';
    ctaEl.textContent = '+ আরও তথ্য যোগ করো';
    ctaEl.style.background = 'var(--border)';
    ctaEl.style.color = 'var(--text)';
  } else {
    titleEl.textContent = 'Profile Completeness';
    subEl.textContent = doneCount + '/' + importantFields.length + ' জরুরি তথ্য দেওয়া হয়েছে · আরও ' + c.missing.length + 'টি দিলে Verified badge ও আরও সুযোগ-সুবিধা আনলক হবে ✨';
    ctaEl.textContent = 'Complete Profile →';
    ctaEl.style.background = 'linear-gradient(90deg,#FF8A00,#FFB800)';
    ctaEl.style.color = '#fff';
  }
}

// Chip taps jump straight to that field's own editor instead of opening the Edit Profile
// modal — most important fields are already inline-editable right below the score card
// (pf-row-* rows, some tucked inside the collapsed "see more details" panel), so there's
// no need to leave the page. Only avatar_url (separate upload sheet) and bio (no inline
// row exists for it at all) fall back to their real editors.
function pfJumpToField(fieldKey) {
  if (fieldKey === 'avatar_url') { if (typeof pfAvSheetOpen === 'function') pfAvSheetOpen(); return; }
  if (fieldKey === 'bio') { if (typeof pfOpenEditProfile === 'function') pfOpenEditProfile(); return; }
  var rowIdMap = { category:'pf-row-cat', gender:'pf-row-gender', city:'pf-row-city', birthday:'pf-row-birthday', work:'pf-row-work' };
  var row = document.getElementById(rowIdMap[fieldKey] || '');
  if (!row) { if (typeof pfOpenEditProfile === 'function') pfOpenEditProfile(); return; }
  var more = document.getElementById('pf-about-more');
  var wasOpen = more ? more.getAttribute('data-open') === '1' : true;
  if (!wasOpen && typeof pfToggleMoreDetails === 'function') pfToggleMoreDetails();
  setTimeout(function() {
    row.scrollIntoView({ behavior:'smooth', block:'center' });
    var orig = row.style.backgroundColor;
    row.style.transition = 'background-color .3s';
    row.style.backgroundColor = 'rgba(255,138,0,.14)';
    setTimeout(function(){ row.style.backgroundColor = orig; }, 900);
  }, wasOpen ? 0 : 400);
}

function pfScrollToPersonalDetails() {
  var el = document.getElementById('pf-about-details-block');
  if (!el) { if (typeof pfOpenEditProfile === 'function') pfOpenEditProfile(); return; }
  var more = document.getElementById('pf-about-more');
  var wasOpen = more ? more.getAttribute('data-open') === '1' : true;
  if (!wasOpen && typeof pfToggleMoreDetails === 'function') pfToggleMoreDetails();
  setTimeout(function(){ el.scrollIntoView({ behavior:'smooth', block:'start' }); }, wasOpen ? 0 : 400);
}

/* ── Edit Profile ──────────────────────────────────────── */
function pfOpenEditProfile() {
  var p = window.sbProfile || {};
  document.getElementById('pfe-category').value = p.category || '';
  pfCatSelect(p.category || '');
  document.getElementById('pfe-name').value = p.name || '';
  document.getElementById('pfe-bio').value = p.bio || '';
  document.getElementById('pfe-city').value = p.city || '';
  document.getElementById('pfe-hometown').value = p.hometown || '';
  document.getElementById('pfe-birthday').value = p.birthday || '';
  document.getElementById('pfe-relationship').value = p.relationship_status || '';
  document.getElementById('pfe-gender').value = p.gender || '';
  document.getElementById('pfe-occupation').value = p.work || '';
  document.getElementById('pfe-company').value = p.company || '';
  document.getElementById('pfe-education').value = p.education || '';
  document.getElementById('pfe-goals').value = p.goals || '';
  document.getElementById('pfe-madhhab').value = p.madhhab || '';
  document.getElementById('pfe-quran-goal').value = p.quran_goal || '';
  document.getElementById('pfe-website').value = p.website || '';
  document.getElementById('pfe-youtube').value = p.youtube || '';
  document.getElementById('pfe-instagram').value = p.instagram || '';
  document.getElementById('pfe-phone').value = p.phone || '';
  var modal = document.getElementById('pf-edit-modal');
  if (modal) { modal.classList.add('open'); document.body.style.overflow = 'hidden'; }
  pfWireCompletenessListeners();
  pfRenderCompletenessWidget();
}

function pfCloseEditProfile() {
  var modal = document.getElementById('pf-edit-modal');
  if (modal) { modal.classList.remove('open'); document.body.style.overflow = ''; }
}

async function pfSaveProfile() {
  if (!window.sbUser) { if(typeof sbOpenAuth==='function') sbOpenAuth('login'); return; }
  var btn = document.getElementById('pfe-save-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
  var updates = {
    category: document.getElementById('pfe-category').value.trim(),
    name: (document.getElementById('pfe-name').value.trim()) || (sbProfile && sbProfile.name) || 'Rizer',
    bio: document.getElementById('pfe-bio').value.trim(),
    city: document.getElementById('pfe-city').value.trim(),
    hometown: document.getElementById('pfe-hometown').value.trim(),
    birthday: document.getElementById('pfe-birthday').value || null,
    relationship_status: document.getElementById('pfe-relationship').value,
    gender: document.getElementById('pfe-gender').value,
    work: document.getElementById('pfe-occupation').value.trim(),
    company: document.getElementById('pfe-company').value.trim(),
    education: document.getElementById('pfe-education').value.trim(),
    goals: document.getElementById('pfe-goals').value.trim(),
    madhhab: document.getElementById('pfe-madhhab').value,
    quran_goal: parseInt(document.getElementById('pfe-quran-goal').value) || 0,
    website: document.getElementById('pfe-website').value.trim(),
    youtube: document.getElementById('pfe-youtube').value.trim(),
    instagram: document.getElementById('pfe-instagram').value.trim(),
    phone: document.getElementById('pfe-phone').value.trim()
  };
  var wasVerified = !!(window.sbProfile && window.sbProfile.is_verified);
  var { data, error } = await _sb.from('profiles').update(updates).eq('id', sbUser.id)
    .select('is_verified, profile_completion_score').single();
  if (btn) { btn.disabled = false; btn.textContent = 'Save'; }
  if (error) { if(typeof cmToast==='function') cmToast('Save failed: ' + error.message); return; }
  window.sbProfile = Object.assign(window.sbProfile || {}, updates, data || {});
  pfRenderPage();
  pfRefreshAbout();
  pfCloseEditProfile();
  var nowVerified = !!(data && data.is_verified);
  if (nowVerified && !wasVerified) {
    if (typeof pfCelebrateVerified === 'function') pfCelebrateVerified();
  } else if (!nowVerified && wasVerified) {
    if(typeof cmToast==='function') cmToast('Profile updated — কিছু জরুরি তথ্য বাদ পড়ায় Verified badge সাময়িকভাবে সরে গেছে');
  } else {
    if(typeof cmToast==='function') cmToast('Profile updated ✓');
  }
}

/* ── Multi-category picker ── */
var _pfCatSel = [];

function pfCatGetFromProfile() {
  var p = window.sbProfile || {};
  /* try categories field first */
  var c = p.categories;
  if (typeof c === 'string') { try { c = JSON.parse(c); } catch(e) { c = null; } }
  if (Array.isArray(c) && c.length) return c.slice(0,3);
  /* fall back to category field (may be JSON array or single string) */
  var cat = p.category;
  if (typeof cat === 'string' && cat.charAt(0) === '[') {
    try { c = JSON.parse(cat); } catch(e) { c = null; }
    if (Array.isArray(c) && c.length) return c.slice(0,3);
  }
  return cat ? [cat] : [];
}

function pfCatChipsRender() {
  var row = document.getElementById('cat-chips-row');
  if (!row) return;
  var sinp = document.getElementById('cat-search-inp');
  if (!_pfCatSel.length) {
    row.innerHTML = '';
    if (sinp) sinp.placeholder = 'Search categories…';
  } else {
    row.innerHTML = _pfCatSel.map(function(c) {
      var ec = c.replace(/'/g,"\\'");
      return '<div class="cat-chip">'+escapeHtml(c)+
        '<button class="cat-chip-del" onclick="event.stopPropagation();pfCatRemoveSel(\''+ec+'\')">'+
        '<svg viewBox="0 0 24 24" style="width:9px;height:9px;fill:currentColor"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>'+
        '</button></div>';
    }).join('');
    if (sinp) sinp.placeholder = _pfCatSel.length >= 3 ? '' : 'Add more…';
  }
  pfCatSearch(sinp ? sinp.value : '');
}

function pfCatSearch(q) {
  var grid = document.getElementById('cat-results-grid');
  if (!grid) return;
  var query = (q||'').trim().toLowerCase();
  var starts = query ? RIZERS_CATS.filter(function(c){ return c.toLowerCase().indexOf(query)===0; }) : [];
  var contains = query ? RIZERS_CATS.filter(function(c){ return c.toLowerCase().indexOf(query)>0; }) : RIZERS_CATS;
  var list = query ? starts.concat(contains) : contains;
  var full = _pfCatSel.length >= 3;
  if (!list.length) { grid.innerHTML = '<span class="cat-no-sel">No results for "'+escapeHtml(q)+'"</span>'; return; }
  grid.innerHTML = list.map(function(c) {
    var sel = _pfCatSel.indexOf(c) !== -1;
    var cls = 'cat-pill' + (sel ? ' cat-pill-sel' : (!sel && full ? ' cat-pill-full' : ''));
    var click = (!sel && !full) ? ' onclick="pfCatAddSel(\''+c.replace(/'/g,"\\'")+'\')' + '"' : '';
    var q2 = query ? c.replace(new RegExp('('+query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+')','gi'),'<strong style="color:#FF8A00">$1</strong>') : escapeHtml(c);
    return '<div class="'+cls+'"'+click+'>'+q2+'</div>';
  }).join('');
}

function pfCatAddSel(cat) {
  if (_pfCatSel.indexOf(cat) !== -1 || _pfCatSel.length >= 3) return;
  _pfCatSel.push(cat);
  pfCatChipsRender();
}

function pfCatRemoveSel(cat) {
  _pfCatSel = _pfCatSel.filter(function(c){ return c !== cat; });
  pfCatChipsRender();
}

function pfCatBadgesRender(cats) {
  var el = document.getElementById('pf-about-cat');
  if (!el) return;
  if (!cats || !cats.length) {
    el.innerHTML = '<span style="color:var(--sub-text);font-style:italic;font-size:13px">Not added yet</span>';
    return;
  }
  el.innerHTML = cats.map(function(c, i) {
    return (i > 0 ? '<span style="color:var(--text);margin:0 3px;font-size:15px;font-weight:900;opacity:.5"> • </span>' : '') +
      '<span style="font-size:14px;font-weight:700;color:var(--text)">'+escapeHtml(c)+'</span>';
  }).join('');
}

function pfCatMove(cat, dir) {
  var i = _pfCatSel.indexOf(cat), j = i + dir;
  if (j < 0 || j >= _pfCatSel.length) return;
  var t = _pfCatSel[i]; _pfCatSel[i] = _pfCatSel[j]; _pfCatSel[j] = t;
  pfCatChipsRender();
}

/* ── Inline row editing config ── */
var PF_IE_CFG = {
  username:     { col:'username',             type:'uname',        displayId:'pf-about-username',  fmt:function(v){ return v?'@'+v:''; } },
  category:     { col:'categories',           type:'multi-cat',    displayId:'pf-about-cat',      fmt:function(){ return _pfCatSel; } },
  city:         { col:'city',                type:'location',     displayId:'pf-about-loc',       fmt:function(v){ return v?'Lives in '+v:''; }, locField:'city', privatable:true },
  hometown:     { col:'hometown',            type:'location',     displayId:'pf-about-hometown',  fmt:function(v){ return v||''; },                locField:'hometown', privatable:true },
  relationship: { col:'relationship_status', type:'select',       displayId:'pf-about-rel',       fmt:function(v){ return v||''; }, privatable:true },
  birthday:     { col:'birthday',            type:'date',         displayId:'pf-about-birthday',  fmt:function(v){ if(!v) return ''; var d=new Date(v); return d.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}); }, privatable:true },
  gender:       { col:'gender',              type:'select',       displayId:'pf-about-gender',    fmt:function(v){ return v==='Prefer not to say'?'':v||''; }, privatable:true },
  work:         { cols:['work','company'],   type:'work2',        displayId:'pf-about-work',      fmt:function(){ var p=window.sbProfile||{}; return [p.work,p.company].filter(Boolean).join(' at '); }, privatable:true },
  education:    { col:'education',           type:'text',         displayId:'pf-about-edu',       fmt:function(v){ return v||''; }, privatable:true },
  goals:        { col:'goals',               type:'textarea',     displayId:'pf-about-goals',     fmt:function(v){ return v||''; }, privatable:true },
  madhhab:      { col:'madhhab',             type:'select',       displayId:'pf-about-madhhab',   fmt:function(v){ return v==='Not specified'?'':v||''; }, privatable:true },
  quran_goal:   { col:'quran_goal',          type:'number',       displayId:'pf-about-quran',     fmt:function(v){ return v?v+' pages/day':''; }, privatable:true },
  website:      { col:'website',             type:'text',         displayId:'pf-about-website',   fmt:function(v){ return v||''; }, privatable:true },
  youtube:      { col:'youtube',   type:'username', displayId:'pf-about-youtube',   urlFmt:'https://youtube.com/@',  fmt:function(v){ return v?'@'+v:''; }, privatable:true },
  instagram:    { col:'instagram', type:'username', displayId:'pf-about-instagram', urlFmt:'https://instagram.com/', fmt:function(v){ return v?'@'+v:''; }, privatable:true },
  whatsapp:     { col:'whatsapp',            type:'whatsapp',     displayId:'pf-about-whatsapp',  fmt:function(v){ return v||''; }, privatable:true },
  email:        { col:'contact_email',       type:'text',         displayId:'pf-about-email',     fmt:function(v){ return v||''; }, privatable:true },
  phone:        { col:'phone',               type:'text',         displayId:'pf-about-phone',     fmt:function(v){ return v||''; }, privatable:true }
};

function pfIsFieldPrivate(prof, key) {
  var arr = (prof && prof.private_fields) || [];
  return Array.isArray(arr) && arr.indexOf(key) !== -1;
}

function pfEnsurePrivacyToggle(field) {
  var cfg = PF_IE_CFG[field];
  if (!cfg || !cfg.privatable) return;
  var panel = document.getElementById('pf-ie-' + field);
  if (!panel) return;
  var wrap = panel.querySelector('.pf-priv-toggle-wrap');
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.className = 'pf-priv-toggle-wrap';
    wrap.innerHTML =
      '<span class="pf-priv-toggle-label" id="pf-priv-label-' + field + '">🌐 Public</span>' +
      '<label class="pf-priv-toggle">' +
        '<input type="checkbox" id="pf-priv-chk-' + field + '" onchange="pfPrivToggleChange(\'' + field + '\',this.checked)">' +
        '<span class="pf-priv-toggle-slider"></span>' +
      '</label>';
    var acts = panel.querySelector('.pf-ie-acts');
    if (acts) panel.insertBefore(wrap, acts); else panel.appendChild(wrap);
  }
  var isPriv = pfIsFieldPrivate(window.sbProfile || {}, field);
  var chk = document.getElementById('pf-priv-chk-' + field);
  if (chk) chk.checked = isPriv;
  var lbl = document.getElementById('pf-priv-label-' + field);
  if (lbl) lbl.textContent = isPriv ? '🔒 Private' : '🌐 Public';
  panel.setAttribute('data-priv-pending', isPriv ? '1' : '0');
}

function pfPrivToggleChange(field, checked) {
  var panel = document.getElementById('pf-ie-' + field);
  if (panel) panel.setAttribute('data-priv-pending', checked ? '1' : '0');
  var lbl = document.getElementById('pf-priv-label-' + field);
  if (lbl) lbl.textContent = checked ? '🔒 Private' : '🌐 Public';
}

function pfInlineEdit(field) {
  var panel = document.getElementById('pf-ie-'+field);
  var cfg = PF_IE_CFG[field];
  if (!panel || !cfg) return;
  // Toggle: if already open, close it
  if (panel.classList.contains('open')) {
    panel.classList.remove('open');
    return;
  }
  // Close any other open panel
  document.querySelectorAll('.pf-ie-panel.open').forEach(function(p){ p.classList.remove('open'); });
  var p = window.sbProfile || {};
  if (cfg.type === 'work2') {
    var wi = panel.querySelector('#pf-ieinp-work'), ci = panel.querySelector('#pf-ieinp-company');
    if (wi) wi.value = p.work || '';
    if (ci) ci.value = p.company || '';
  } else if (cfg.type === 'multi-cat') {
    _pfCatSel = pfCatGetFromProfile();
    pfCatChipsRender();
    var sinp = document.getElementById('cat-search-inp');
    if (sinp) sinp.value = '';
    pfCatSearch('');
  } else if (cfg.type === 'uname') {
    var inp = document.getElementById('pf-ieinp-username');
    var status = document.getElementById('un-status');
    var saveBtn = document.getElementById('un-save-btn');
    _unAvail = false;
    if (status) status.innerHTML = '';
    if (saveBtn) saveBtn.disabled = true;
    if (inp) {
      inp.value = (p.username || '').replace(/^@/, '');
      inp.readOnly = false; inp.style.opacity = '';
      // Same 7-day cooldown the Settings page enforces (_rz_uname_changed_at) — this panel
      // used to skip it entirely, letting a username be changed again right away.
      var lastUC = localStorage.getItem('_rz_uname_changed_at');
      var unCooldownMs = lastUC ? (7*24*60*60*1000 - (Date.now()-parseInt(lastUC,10))) : 0;
      if (unCooldownMs > 0) {
        var unDaysLeft = Math.ceil(unCooldownMs/(24*60*60*1000));
        if (status) status.innerHTML = '<span class="un-taken">Username আরো '+unDaysLeft+' দিন পরে পরিবর্তন করা যাবে</span>';
        inp.readOnly = true; inp.style.opacity = '.6';
      } else if (inp.value) {
        setTimeout(function(){ unCheckUsername(inp.value); }, 50);
      }
    }
  } else if (cfg.type === 'username') {
    var raw = p[cfg.col] || '';
    // strip full URL, strip @
    var prefixes = cfg.urlFmt ? [cfg.urlFmt, cfg.urlFmt.replace('https://','https://www.')] : [];
    prefixes.forEach(function(pf){ if (raw.toLowerCase().startsWith(pf.toLowerCase())) raw = raw.slice(pf.length); });
    raw = raw.replace(/^@+/,'').replace(/\/+$/,'');
    var inp = document.getElementById('pf-ieinp-' + field);
    if (inp) inp.value = raw;
  } else if (cfg.type === 'location') {
    var li = document.getElementById('loc-inp-' + cfg.locField);
    if (li) { li.value = p[cfg.col] || ''; }
    window['_locPending_' + cfg.locField] = null;
  } else if (cfg.type === 'whatsapp') {
    var stored = p[cfg.col] || '';
    var parts = stored.match(/^(\+\d+)\s?(.*)$/);
    var detectedCode = waAutoDetectCode();
    var ccVal = parts ? parts[1] : detectedCode;
    var numVal = parts ? parts[2] : '';
    var sel = document.getElementById('wa-cc-sel');
    waPopulateCC(sel, ccVal);
    if (sel) sel.value = ccVal;
    var inp = document.getElementById('pf-ieinp-whatsapp');
    if (inp) inp.value = numVal;
  } else {
    var inp = panel.querySelector('.pf-ie-inp,.pf-ie-sel,.pf-ie-textarea');
    if (inp) inp.value = p[cfg.col] || '';
  }
  pfEnsurePrivacyToggle(field);
  panel.classList.add('open');
  /* re-measure expand panel */
  var more = document.getElementById('pf-about-more');
  if (more && more.getAttribute('data-open')==='1') setTimeout(function(){ more.style.maxHeight = more.scrollHeight+'px'; }, 10);
  var fi = panel.querySelector('input,select,textarea');
  if (fi) fi.focus();
}

function pfInlineSave(field) {
  var panel = document.getElementById('pf-ie-'+field);
  var cfg = PF_IE_CFG[field];
  if (!panel || !cfg) return;
  var p = window.sbProfile || {};
  var wasVerified = !!p.is_verified;
  var update = {};

  if (cfg.type === 'multi-cat') {
    /* store as JSON in category column (always exists) + categories if available */
    var catsJson = JSON.stringify(_pfCatSel);
    update.category = catsJson;
    /* always update window.sbProfile directly */
    if (!window.sbProfile) window.sbProfile = {};
    window.sbProfile.categories = _pfCatSel.slice();
    window.sbProfile.category = catsJson;
    pfCatBadgesRender(_pfCatSel);
    var rl = document.getElementById('pf-role');
    if (rl) rl.textContent = _pfCatSel[0] || 'Rizer';
  } else if (cfg.type === 'work2') {
    var wi = panel.querySelector('#pf-ieinp-work'), ci = panel.querySelector('#pf-ieinp-company');
    update.work = wi ? wi.value.trim() : '';
    update.company = ci ? ci.value.trim() : '';
    p.work = update.work; p.company = update.company;
    var el = document.getElementById(cfg.displayId);
    var displayVal = cfg.fmt();
    if (el) { el.textContent = displayVal||'Not added yet'; el.style.color = displayVal?'var(--text)':'var(--sub-text)'; el.style.fontStyle = displayVal?'normal':'italic'; }
  } else if (cfg.type === 'uname') {
    if (!_unAvail) { if (typeof cmToast === 'function') cmToast('Choose an available username first'); return; }
    var inp = document.getElementById('pf-ieinp-username');
    var val = inp ? inp.value.trim().toLowerCase() : '';
    if (!val || val.length < 3) { if (typeof cmToast === 'function') cmToast('Username too short'); return; }
    var prevUname = ((p.username || '')+'').toLowerCase();
    if (val !== prevUname) {
      // Same _rz_uname_changed_at cooldown key the Settings page uses — enforced here too so
      // either surface for changing the username respects the 7-day restriction.
      var lastUC = localStorage.getItem('_rz_uname_changed_at');
      var unRemainMs = lastUC ? (7*24*60*60*1000 - (Date.now()-parseInt(lastUC,10))) : 0;
      if (unRemainMs > 0) {
        var unDaysLeft = Math.ceil(unRemainMs/(24*60*60*1000));
        if (typeof cmToast === 'function') cmToast('Username আরো '+unDaysLeft+' দিন পরে পরিবর্তন করা যাবে');
        return;
      }
      localStorage.setItem('_rz_uname_changed_at', String(Date.now()));
    }
    update.username = val;
    if (!window.sbProfile) window.sbProfile = {};
    window.sbProfile.username = val;
    var el = document.getElementById(cfg.displayId);
    if (el) { el.textContent = '@' + val; el.style.color = 'var(--text)'; el.style.fontStyle = 'normal'; }
    // sync all @username displays in the page
    document.querySelectorAll('.pf-username-tag').forEach(function(t){ t.textContent = '@' + val; });
  } else if (cfg.type === 'username') {
    var inp = document.getElementById('pf-ieinp-' + field);
    var raw = inp ? inp.value.trim() : '';
    // strip @ and URL prefix if user pasted full URL
    var prefixes = cfg.urlFmt ? [cfg.urlFmt, cfg.urlFmt.replace('https://','https://www.')] : [];
    prefixes.forEach(function(pf){ if (raw.toLowerCase().startsWith(pf.toLowerCase())) raw = raw.slice(pf.length); });
    raw = raw.replace(/^@+/,'').replace(/\/+$/,'');
    update[cfg.col] = raw || null;
    if (!window.sbProfile) window.sbProfile = {};
    window.sbProfile[cfg.col] = raw;
    var displayVal = raw ? '@' + raw : '';
    var el = document.getElementById(cfg.displayId);
    if (el) {
      if (displayVal && cfg.urlFmt) {
        el.innerHTML = '<a class="pf-about-link" href="' + escapeHtml(cfg.urlFmt + raw) + '" target="_blank" rel="noopener">' + escapeHtml(displayVal) + '</a>';
      } else {
        el.innerHTML = '<span style="color:var(--sub-text);font-style:italic;font-size:13px">Not added yet</span>';
      }
    }
  } else if (cfg.type === 'whatsapp') {
    var sel = document.getElementById('wa-cc-sel');
    var inp = document.getElementById('pf-ieinp-whatsapp');
    var cc = sel ? sel.value : '+880';
    var num = inp ? inp.value.trim() : '';
    if (num.charAt(0) === '0') num = num.slice(1); // strip leading 0
    var val = num ? (cc + ' ' + num) : '';
    update[cfg.col] = val || null;
    if (!window.sbProfile) window.sbProfile = {};
    window.sbProfile[cfg.col] = val;
    var displayVal = cfg.fmt(val);
    var el = document.getElementById(cfg.displayId);
    if (el) { el.textContent = displayVal||'Not added yet'; el.style.color = displayVal?'var(--text)':'var(--sub-text)'; el.style.fontStyle = displayVal?'normal':'italic'; }
  } else if (cfg.type === 'location') {
    var li = document.getElementById('loc-inp-' + cfg.locField);
    var val = li ? li.value.trim() : '';
    update[cfg.col] = val || null;
    var pending = window['_locPending_' + cfg.locField];
    if (pending) {
      update[cfg.locField + '_lat']  = pending.lat;
      update[cfg.locField + '_lon']  = pending.lon;
      update[cfg.locField + '_data'] = JSON.stringify(pending.address);
      window['_locPending_' + cfg.locField] = null;
    }
    if (!window.sbProfile) window.sbProfile = {};
    window.sbProfile[cfg.col] = val;
    var displayVal = cfg.fmt(val);
    var el = document.getElementById(cfg.displayId);
    if (el) { el.textContent = displayVal||'Not added yet'; el.style.color = displayVal?'var(--text)':'var(--sub-text)'; el.style.fontStyle = displayVal?'normal':'italic'; }
  } else {
    var inp = panel.querySelector('.pf-ie-inp,.pf-ie-sel,.pf-ie-textarea');
    var val = inp ? inp.value.trim() : '';
    var displayVal = '';
    if (cfg.type === 'number') { update[cfg.col] = parseInt(val)||null; p[cfg.col] = update[cfg.col]; displayVal = cfg.fmt(update[cfg.col]); }
    else { update[cfg.col] = val||null; p[cfg.col] = val; displayVal = cfg.fmt(val); }
    var el = document.getElementById(cfg.displayId);
    if (el) { el.textContent = displayVal||'Not added yet'; el.style.color = displayVal?'var(--text)':'var(--sub-text)'; el.style.fontStyle = displayVal?'normal':'italic'; }
  }

  if (cfg.privatable) {
    var wantPrivate = panel.getAttribute('data-priv-pending') === '1';
    var curArr = (p.private_fields || []).slice();
    var idx = curArr.indexOf(field);
    if (wantPrivate && idx === -1) curArr.push(field);
    else if (!wantPrivate && idx !== -1) curArr.splice(idx, 1);
    update.private_fields = curArr;
    if (!window.sbProfile) window.sbProfile = {};
    window.sbProfile.private_fields = curArr;
  }

  panel.classList.remove('open');
  // Mirrors this field into the desktop "Personal details" card too (it reads the same
  // window.sbProfile this function just updated) — keeps both surfaces in sync regardless
  // of which one (mobile row or the relocated desktop edit panel) was actually edited.
  if (typeof pfRefreshAbout === 'function') pfRefreshAbout();
  if (typeof _sb !== 'undefined' && window.sbUser) {
    _sb.from('profiles').update(update).eq('id', window.sbUser.id)
      .select('is_verified, profile_completion_score').single().then(function(res) {
      if (res.error) { if (typeof cmToast === 'function') cmToast('Save failed: ' + res.error.message); return; }
      if (!window.sbProfile) window.sbProfile = {};
      Object.assign(window.sbProfile, res.data || {});
      if (typeof pfSyncBadge === 'function') pfSyncBadge(window.sbProfile.name, window.sbProfile.is_verified);
      if (typeof pfRenderScoreCard === 'function') pfRenderScoreCard();
      var nowVerified = !!(res.data && res.data.is_verified);
      if (nowVerified && !wasVerified) {
        if (typeof pfCelebrateVerified === 'function') pfCelebrateVerified();
      } else if (!nowVerified && wasVerified) {
        if (typeof cmToast === 'function') cmToast('Profile updated — কিছু জরুরি তথ্য বাদ পড়ায় Verified badge সাময়িকভাবে সরে গেছে');
      } else {
        if (typeof cmToast === 'function') cmToast('Saved ✓');
      }
    });
  } else {
    if (typeof cmToast === 'function') cmToast('Saved ✓');
  }
}

function pfInlineCancel(field) {
  var panel = document.getElementById('pf-ie-'+field);
  if (panel) panel.classList.remove('open');
}

function pfToggleMoreDetails() {
  var more = document.getElementById('pf-about-more');
  var txt  = document.getElementById('pf-more-btn-txt');
  var chev = document.getElementById('pf-more-chevron');
  if (!more) return;
  var open = more.getAttribute('data-open') === '1';
  if (open) {
    more.style.maxHeight = '0';
    more.setAttribute('data-open','0');
    if(txt) txt.textContent = 'See more details';
    if(chev) chev.style.transform = 'rotate(0deg)';
  } else {
    more.style.maxHeight = more.scrollHeight + 'px';
    more.setAttribute('data-open','1');
    if(txt) txt.textContent = 'See less';
    if(chev) chev.style.transform = 'rotate(180deg)';
  }
}

function pfSetUsernameRow(rowId, spanId, username, urlBase, isPrivate) {
  var row = document.getElementById(rowId);
  var span = document.getElementById(spanId);
  if (!row) return;
  row.style.display = 'flex';
  if (!span) return;
  // strip @ or old full URLs in case stored value is dirty
  var u = (username || '').replace(/^@+/,'').replace(/\/+$/,'');
  if (urlBase) { [urlBase, urlBase.replace('https://','https://www.')].forEach(function(p){ if(u.toLowerCase().startsWith(p.toLowerCase())) u=u.slice(p.length); }); }
  u = u.replace(/^@+/,'').replace(/\/+$/,'');
  if (u) {
    span.innerHTML = '<a class="pf-about-link" href="' + escapeHtml(urlBase + u) + '" target="_blank" rel="noopener">@' + escapeHtml(u) + '</a>' + (isPrivate ? ' 🔒' : '');
  } else {
    span.innerHTML = '<span style="color:var(--sub-text);font-style:italic;font-size:13px">Not added yet</span>';
  }
}

function pfSetRow(rowId, spanId, val) {
  var row = document.getElementById(rowId);
  var span = document.getElementById(spanId);
  if (!row) return;
  row.style.display = 'flex';
  if (span) {
    if (val) { span.textContent = val; span.style.color = 'var(--text)'; span.style.fontStyle = 'normal'; }
    else { span.textContent = 'Not added yet'; span.style.color = 'var(--sub-text)'; span.style.fontStyle = 'italic'; }
  }
}

function pfRefreshAbout() {
  var _pfPgA=document.getElementById('profile-page');
  if(_pfPgA&&_pfPgA.classList.contains('visitor-mode')&&!window._visitingProfile) return;
  // Restore rows that visitor-mode may have hidden
  ['pf-about-details-block','pf-row-username','pf-row-cat','pf-row-city','pf-row-hometown','pf-row-rel','pf-row-joined'].forEach(function(id){ var el=document.getElementById(id); if(el) el.style.display=''; });
  var p = window.sbProfile || {};
  function _lockSfx(val, key) { return val ? (val + (pfIsFieldPrivate(p, key) ? ' 🔒' : '')) : val; }
  /* username row */
  var unEl = document.getElementById('pf-about-username');
  if (unEl) {
    var un = p.username || '';
    unEl.textContent = un ? '@' + un : 'Not set';
    unEl.style.color = un ? 'var(--text)' : 'var(--sub-text)';
    unEl.style.fontStyle = un ? 'normal' : 'italic';
  }
  /* category row — multi-select badges */
  var catRow = document.getElementById('pf-row-cat');
  if (catRow) catRow.style.display = 'flex';
  pfCatBadgesRender(pfCatGetFromProfile());
  /* always-visible rows */
  var locEl = document.getElementById('pf-about-loc');
  if (locEl) locEl.textContent = p.city ? _lockSfx('Lives in ' + p.city, 'city') : 'Lives in Bangladesh';
  var htEl = document.getElementById('pf-about-hometown');
  if (htEl) htEl.textContent = p.hometown ? _lockSfx(p.hometown, 'hometown') : 'Bangladesh';
  var relEl = document.getElementById('pf-about-rel');
  if (relEl) relEl.textContent = p.relationship_status ? _lockSfx(p.relationship_status, 'relationship') : 'Not added yet';
  /* desktop "Personal details" card mirrors the same fields */
  var dUnEl = document.getElementById('pf-d-username');
  if (dUnEl) { var dun = p.username || ''; dUnEl.textContent = dun ? '@' + dun : 'Not set'; }
  var dLocEl = document.getElementById('pf-d-loc');
  if (dLocEl) dLocEl.textContent = p.city ? 'Lives in ' + p.city : 'Lives in Bangladesh';
  var dRelEl = document.getElementById('pf-d-rel');
  if (dRelEl) dRelEl.textContent = p.relationship_status ? p.relationship_status : 'Not added yet';
  // "Joined ..." (pf-about-joined / pf-d-joined) is set once in pfRenderPage() from the
  // auth user's created_at (reliable) — not re-derived here from profiles.created_at, which
  // is null on some accounts and isn't affected by editing other fields anyway.
  /* bio */
  var bioEl = document.getElementById('pf-bio');
  if (bioEl) { var bv = p.bio || ''; bioEl.textContent = bv; bioEl.style.display = bv ? '' : 'none'; }
  /* expandable rows */
  var bdVal = '';
  if (p.birthday) { var bd=new Date(p.birthday); bdVal=bd.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}); }
  pfSetRow('pf-row-birthday','pf-about-birthday', _lockSfx(bdVal, 'birthday'));
  pfSetRow('pf-row-gender', 'pf-about-gender',   _lockSfx(p.gender && p.gender!=='Prefer not to say' ? p.gender : '', 'gender'));
  pfSetRow('pf-row-work',   'pf-about-work',     _lockSfx([p.work,p.company].filter(Boolean).join(' at '), 'work'));
  pfSetRow('pf-row-edu',    'pf-about-edu',      _lockSfx(p.education, 'education'));
  pfSetRow('pf-row-goals',  'pf-about-goals',    _lockSfx(p.goals, 'goals'));
  pfSetRow('pf-row-madhhab','pf-about-madhhab',  _lockSfx(p.madhhab && p.madhhab!=='Not specified' ? p.madhhab : '', 'madhhab'));
  pfSetRow('pf-row-quran',  'pf-about-quran',    _lockSfx(p.quran_goal ? p.quran_goal+' pages/day' : '', 'quran_goal'));
  /* always show See-more button */
  var moreBtn = document.getElementById('pf-more-btn');
  if (moreBtn) moreBtn.style.display = 'flex';
  /* also re-measure if already open */
  var moreEl = document.getElementById('pf-about-more');
  if (moreEl && moreEl.getAttribute('data-open')==='1') moreEl.style.maxHeight = moreEl.scrollHeight+'px';
  /* links section summary card */
  var lnkEl = document.getElementById('pf-link-1');
  var lnkTxt = p.website || p.youtube || (p.instagram ? '@'+p.instagram : '');
  if (lnkEl) { lnkEl.textContent = lnkTxt || 'Add your website'; }
  /* see-more: links + contact rows */
  pfSetRow('pf-row-website',   'pf-about-website',   _lockSfx(p.website || '', 'website'));
  pfSetUsernameRow('pf-row-youtube',   'pf-about-youtube',   p.youtube,   'https://youtube.com/@',  pfIsFieldPrivate(p,'youtube'));
  pfSetUsernameRow('pf-row-instagram', 'pf-about-instagram', p.instagram, 'https://instagram.com/', pfIsFieldPrivate(p,'instagram'));
  pfSetRow('pf-row-whatsapp',  'pf-about-whatsapp',  _lockSfx(p.whatsapp || '', 'whatsapp'));
  pfSetRow('pf-row-email',     'pf-about-email',     _lockSfx(p.contact_email || '', 'email'));
  pfSetRow('pf-row-phone',     'pf-about-phone',     _lockSfx(p.phone || '', 'phone'));
  if (typeof pfRenderScoreCard === 'function') pfRenderScoreCard();
}

function pfHideEmptyVisitorRows(prof) {
  var p = prof || {};
  function _row(id, show){ var el=document.getElementById(id); if(el) el.style.display=show?'':'none'; }
  // Always-visible rows
  _row('pf-row-username', !!p.username);
  var cats=(function(){
    var c=p.categories; if(typeof c==='string'){try{c=JSON.parse(c);}catch(e){c=null;}}
    if(Array.isArray(c)&&c.length) return c;
    var cat=p.category; if(typeof cat==='string'&&cat.charAt(0)==='['){try{var a=JSON.parse(cat);if(Array.isArray(a)&&a.length)return a;}catch(e){}}
    return cat?[cat]:[];
  })();
  _row('pf-row-cat', cats.length>0);
  _row('pf-row-city', !!p.city && !pfIsFieldPrivate(p,'city'));
  _row('pf-row-hometown', !!p.hometown && !pfIsFieldPrivate(p,'hometown'));
  _row('pf-row-rel', !!p.relationship_status && !pfIsFieldPrivate(p,'relationship'));
  _row('pf-row-joined', !!p.created_at);
  // Expandable rows — hide if no data or marked private
  var bdVal=''; if(p.birthday){try{var bd=new Date(p.birthday);bdVal=bd.toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});}catch(e){}}
  _row('pf-row-birthday', !!bdVal && !pfIsFieldPrivate(p,'birthday'));
  _row('pf-row-gender', !!(p.gender&&p.gender!=='Prefer not to say') && !pfIsFieldPrivate(p,'gender'));
  _row('pf-row-work', !!(p.work||p.company) && !pfIsFieldPrivate(p,'work'));
  _row('pf-row-edu', !!p.education && !pfIsFieldPrivate(p,'education'));
  _row('pf-row-goals', !!p.goals && !pfIsFieldPrivate(p,'goals'));
  _row('pf-row-madhhab', !!(p.madhhab&&p.madhhab!=='Not specified') && !pfIsFieldPrivate(p,'madhhab'));
  _row('pf-row-quran', !!p.quran_goal && !pfIsFieldPrivate(p,'quran_goal'));
  _row('pf-row-website', !!p.website && !pfIsFieldPrivate(p,'website'));
  _row('pf-row-youtube', !!p.youtube && !pfIsFieldPrivate(p,'youtube'));
  _row('pf-row-instagram', !!p.instagram && !pfIsFieldPrivate(p,'instagram'));
  _row('pf-row-whatsapp', !!p.whatsapp && !pfIsFieldPrivate(p,'whatsapp'));
  _row('pf-row-email', !!p.contact_email && !pfIsFieldPrivate(p,'email'));
  _row('pf-row-phone', !!p.phone && !pfIsFieldPrivate(p,'phone'));
  // Hide entire Personal Details section if all rows are empty
  var secEl=document.getElementById('pf-about-details-block');
  if(secEl){
    var anyVisible=false;
    ['pf-row-username','pf-row-cat','pf-row-city','pf-row-hometown','pf-row-rel','pf-row-joined',
     'pf-row-birthday','pf-row-gender','pf-row-work','pf-row-edu','pf-row-goals','pf-row-madhhab','pf-row-quran',
     'pf-row-website','pf-row-youtube','pf-row-instagram','pf-row-whatsapp','pf-row-email','pf-row-phone'
    ].forEach(function(id){ var el=document.getElementById(id); if(el&&el.style.display!=='none') anyVisible=true; });
    secEl.style.display=anyVisible?'':'none';
  }
}

