// ── 1. Delete Habit ─────────────────────────────────────────────
async function rzDeleteHabit(habitId) {
  if (!window._sb || !window.sbUser) return;
  var habit = (window.rzTodayHabits || []).find(function(h) { return h.id === habitId; });
  var habitName = habit ? habit.name : 'এই habit';
  if (!confirm('"' + habitName + '" মুছে ফেলবেন?')) return;
  try {
    var res = await _sb.from('habits').delete().eq('id', habitId);
    if (res.error) throw res.error;
    window.rzTodayHabits = (window.rzTodayHabits || []).filter(function(h) { return h.id !== habitId; });
    renderHabitsFromDB(window.rzTodayHabits);
    rzUpdateHabitsStats(window.rzTodayHabits);
    if (typeof cmToast === 'function') cmToast('"' + habitName + '" মুছে ফেলা হয়েছে');
  } catch(e) {
    if (typeof cmToast === 'function') cmToast('Error: ' + (e.message || e));
    console.error('rzDeleteHabit:', e);
  }
}

// ── 2. Edit Habit Modal ─────────────────────────────────────────
window._rzEditHabitKey = 'default';

function rzOpenEditHabitModal(habitId) {
  var habit = (window.rzTodayHabits || []).find(function(h) { return h.id === habitId; });
  if (!habit) return;

  var existing = document.getElementById('rz-edit-habit-modal');
  if (existing) existing.remove();

  var iconKeys   = ['namaz','quran','water','exercise','study','dua','help','gratitude','sleep','food','journal','family','saving','music','goal','clock','sun','smile','leaf','default'];
  var iconLabels = ['নামাজ','কুরআন','পানি','ব্যায়াম','পড়া','দোয়া','সাহায্য','কৃতজ্ঞতা','ঘুম','খাবার','ডায়েরি','পরিবার','সঞ্চয়','সঙ্গীত','লক্ষ্য','সময়','রোজা','মানসিক','প্রকৃতি','অন্যান্য'];

  var iconsHtml = iconKeys.map(function(k, i) {
    var icon = (typeof HABIT_ICONS !== 'undefined' ? (HABIT_ICONS[k] || '') : '');
    var isSel = k === (habit.icon_key || 'default');
    return '<button id="rz-ehicon-' + k + '" onclick="rzEditHabitIconSelect(\'' + k + '\')" title="' + iconLabels[i] + '" style="' +
      'display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 6px;border-radius:10px;cursor:pointer;font-family:inherit;font-size:10px;' +
      'border:' + (isSel ? '2px solid #FF8A00' : '1.5px solid var(--border,#e5e7eb)') + ';' +
      'background:' + (isSel ? 'rgba(255,138,0,0.1)' : 'transparent') + ';' +
      'color:' + (isSel ? '#FF8A00' : 'var(--text2,#888)') + '">' +
      '<span style="display:flex;align-items:center;justify-content:center;width:22px;height:22px">' + icon + '</span>' +
      iconLabels[i] + '</button>';
  }).join('');

  window._rzEditHabitKey = habit.icon_key || 'default';

  var safeName = (habit.name || '').replace(/"/g, '&quot;');
  var safeDesc = (habit.description || '').replace(/"/g, '&quot;');

  var modal = document.createElement('div');
  modal.id = 'rz-edit-habit-modal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:9001;background:rgba(0,0,0,0.55);display:flex;align-items:flex-end;justify-content:center';
  modal.innerHTML =
    '<div style="background:var(--card,#fff);border-radius:20px 20px 0 0;padding:24px 20px;width:100%;max-width:480px;max-height:90vh;overflow-y:auto">' +
      '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px">' +
        '<div style="font-size:16px;font-weight:700;color:var(--text)">Habit সম্পাদনা</div>' +
        '<button onclick="rzCloseEditHabitModal()" style="background:none;border:none;cursor:pointer;color:var(--text2);font-size:22px;line-height:1">&times;</button>' +
      '</div>' +
      '<div style="margin-bottom:14px">' +
        '<label style="font-size:12px;font-weight:600;color:var(--text2);display:block;margin-bottom:6px">Habit এর নাম *</label>' +
        '<input id="rz-edit-habit-name" value="' + safeName + '" style="width:100%;padding:11px 14px;border:1.5px solid var(--border,#e5e7eb);border-radius:10px;font-family:inherit;font-size:14px;color:var(--text);background:var(--bg,#f9fafb);outline:none;box-sizing:border-box"/>' +
      '</div>' +
      '<div style="margin-bottom:14px">' +
        '<label style="font-size:12px;font-weight:600;color:var(--text2);display:block;margin-bottom:6px">বিবরণ</label>' +
        '<input id="rz-edit-habit-desc" value="' + safeDesc + '" style="width:100%;padding:11px 14px;border:1.5px solid var(--border,#e5e7eb);border-radius:10px;font-family:inherit;font-size:14px;color:var(--text);background:var(--bg,#f9fafb);outline:none;box-sizing:border-box"/>' +
      '</div>' +
      '<div style="margin-bottom:14px">' +
        '<label style="font-size:12px;font-weight:600;color:var(--text2);display:block;margin-bottom:6px">Points (+কত?)</label>' +
        '<input id="rz-edit-habit-points" type="number" min="5" max="50" value="' + (habit.points || 10) + '" style="width:100%;padding:11px 14px;border:1.5px solid var(--border,#e5e7eb);border-radius:10px;font-family:inherit;font-size:14px;color:var(--text);background:var(--bg,#f9fafb);outline:none;box-sizing:border-box"/>' +
      '</div>' +
      '<div style="margin-bottom:20px">' +
        '<label style="font-size:12px;font-weight:600;color:var(--text2);display:block;margin-bottom:8px">Icon বেছে নিন</label>' +
        '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:8px" id="rz-edit-habit-icons">' + iconsHtml + '</div>' +
      '</div>' +
      '<button onclick="rzSubmitEditHabit(\'' + habitId + '\')" style="width:100%;padding:13px;border-radius:12px;border:none;background:linear-gradient(135deg,#FF8A00,#FFB800);color:#090B12;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit">সংরক্ষণ করুন</button>' +
    '</div>';
  modal.onclick = function(e) { if (e.target === modal) rzCloseEditHabitModal(); };
  document.body.appendChild(modal);
}

function rzCloseEditHabitModal() {
  var m = document.getElementById('rz-edit-habit-modal');
  if (m) m.remove();
}

function rzEditHabitIconSelect(key) {
  window._rzEditHabitKey = key;
  var isDark = document.body.classList.contains('dark-mode');
  var iconKeys = ['namaz','quran','water','exercise','study','dua','help','gratitude','sleep','food','journal','family','saving','music','goal','clock','sun','smile','leaf','default'];
  iconKeys.forEach(function(k) {
    var b = document.getElementById('rz-ehicon-' + k);
    if (!b) return;
    if (k === key) {
      b.style.borderColor = '#FF8A00'; b.style.borderWidth = '2px';
      b.style.background  = 'rgba(255,138,0,0.1)'; b.style.color = '#FF8A00';
    } else {
      b.style.borderColor = isDark ? '#2d3748' : '#e5e7eb'; b.style.borderWidth = '1.5px';
      b.style.background  = 'transparent'; b.style.color = isDark ? '#94a3b8' : '#888';
    }
  });
}

async function rzSubmitEditHabit(habitId) {
  if (!window._sb || !window.sbUser) return;
  var nameEl   = document.getElementById('rz-edit-habit-name');
  var descEl   = document.getElementById('rz-edit-habit-desc');
  var pointsEl = document.getElementById('rz-edit-habit-points');
  var name   = nameEl   ? nameEl.value.trim()       : '';
  var desc   = descEl   ? descEl.value.trim()       : '';
  var points = pointsEl ? parseInt(pointsEl.value) || 10 : 10;
  if (!name) { if (nameEl) { nameEl.style.borderColor = '#EF4444'; nameEl.focus(); } return; }

  var btn = document.querySelector('#rz-edit-habit-modal button:last-child');
  if (btn) { btn.textContent = 'সংরক্ষণ হচ্ছে...'; btn.disabled = true; }

  try {
    var res = await _sb.from('habits').update({
      name: name, description: desc,
      icon_key: window._rzEditHabitKey || 'default', points: points
    }).eq('id', habitId);
    if (res.error) throw res.error;
    // Update local data immediately
    var h = (window.rzTodayHabits || []).find(function(x) { return x.id === habitId; });
    if (h) { h.name = name; h.description = desc; h.icon_key = window._rzEditHabitKey || 'default'; h.points = points; }
    rzCloseEditHabitModal();
    renderHabitsFromDB(window.rzTodayHabits);
    if (typeof cmToast === 'function') cmToast('"' + name + '" আপডেট হয়েছে!');
  } catch(e) {
    if (typeof cmToast === 'function') cmToast('Error: ' + (e.message || e));
    console.error('rzSubmitEditHabit:', e);
  } finally {
    if (btn) { btn.textContent = 'সংরক্ষণ করুন'; btn.disabled = false; }
  }
}

// ── 3. Habit Reorder (up/down arrows) ──────────────────────────
async function rzReorderHabit(idx, dir) {
  var habits = window.rzTodayHabits || [];
  var newIdx = idx + dir;
  if (newIdx < 0 || newIdx >= habits.length) return;
  // Swap locally
  var temp = habits[idx]; habits[idx] = habits[newIdx]; habits[newIdx] = temp;
  window.rzTodayHabits = habits;
  renderHabitsFromDB(habits);
  // Persist sort_order to DB
  try {
    await _sb.from('habits').update({ sort_order: newIdx + 1 }).eq('id', habits[idx].id);
    await _sb.from('habits').update({ sort_order: idx  + 1 }).eq('id', habits[newIdx].id);
  } catch(e) { console.error('rzReorderHabit:', e); }
}

// ── 4. Load 7-day history ───────────────────────────────────────
async function rzLoad7DayHistory() {
  if (!window._sb || !window.rzActiveKid) return;
  var today = new Date();
  var dates = [];
  for (var i = 6; i >= 0; i--) {
    var d = new Date(today); d.setDate(today.getDate() - i);
    dates.push(d.toISOString().split('T')[0]);
  }
  window.rzHistoryDates = dates;
  try {
    var res = await _sb.from('habit_logs')
      .select('habit_id, log_date, done')
      .eq('kid_id', window.rzActiveKid.id)
      .in('log_date', dates);
    window.rzHabitHistory = {};
    (res.data || []).forEach(function(log) {
      if (!window.rzHabitHistory[log.habit_id]) window.rzHabitHistory[log.habit_id] = {};
      window.rzHabitHistory[log.habit_id][log.log_date] = log.done;
    });
    // Re-render habits with dots if on habits page
    if (window.rzTodayHabits && window.rzTodayHabits.length && document.getElementById('habits-list')) {
      renderHabitsFromDB(window.rzTodayHabits);
      rzRenderWeeklySummary();
    }
  } catch(e) { console.error('rzLoad7DayHistory:', e); }
}

// ── 5. 100% Celebration ─────────────────────────────────────────
function rzCelebrate100() {
  if (document.getElementById('rz-confetti')) return;
  if (!document.getElementById('rz-confetti-style')) {
    var style = document.createElement('style');
    style.id = 'rz-confetti-style';
    style.textContent = '@keyframes rzFall{0%{transform:translateY(0) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}';
    document.head.appendChild(style);
  }
  var overlay = document.createElement('div');
  overlay.id = 'rz-confetti';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;pointer-events:none;overflow:hidden';
  var emojis = ['🌟','⭐','✨','🎉','🏆','🎊','💫','🥇'];
  var html = '';
  for (var i = 0; i < 24; i++) {
    var left = Math.floor(Math.random() * 100);
    var delay = (Math.random() * 1.5).toFixed(2);
    var dur   = (2 + Math.random() * 2).toFixed(2);
    var em    = emojis[Math.floor(Math.random() * emojis.length)];
    html += '<div style="position:absolute;left:' + left + '%;top:-40px;font-size:22px;animation:rzFall ' + dur + 's ' + delay + 's ease-in forwards">' + em + '</div>';
  }
  overlay.innerHTML = html;
  document.body.appendChild(overlay);
  if (typeof cmToast === 'function') cmToast('🎉 সব Habit সম্পন্ন! অসাধারণ!');
  setTimeout(function() { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); }, 5500);
}

// ── 6. Weekly Summary ───────────────────────────────────────────
function rzRenderWeeklySummary() {
  var container = document.getElementById('rz-weekly-summary');
  if (!container) return;
  var dates   = window.rzHistoryDates || [];
  var history = window.rzHabitHistory || {};
  var habits  = window.rzTodayHabits  || [];
  if (!dates.length || !habits.length) { container.style.display = 'none'; return; }
  container.style.display = 'block';

  var dayNames = ['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
  var totalDone = 0;
  var todayStr  = rzToday();

  var bars = dates.map(function(d) {
    var done = habits.filter(function(h) { return (history[h.id] || {})[d]; }).length;
    totalDone += done;
    var pct    = habits.length > 0 ? Math.round(done / habits.length * 100) : 0;
    var color  = pct >= 80 ? '#22c55e' : pct >= 50 ? '#FF8A00' : pct > 0 ? '#FFB800' : 'var(--border,#e5e7eb)';
    var isToday = d === todayStr;
    var barH   = Math.max(4, Math.round(pct * 0.44));
    return '<div style="display:flex;flex-direction:column;align-items:center;gap:3px;flex:1">' +
      '<div style="font-size:9px;color:' + (isToday ? '#FF8A00' : 'var(--text2)') + ';font-weight:' + (isToday ? '700' : '400') + '">' + pct + '%</div>' +
      '<div style="width:100%;height:44px;display:flex;align-items:flex-end">' +
        '<div style="width:100%;height:' + barH + 'px;border-radius:4px 4px 0 0;background:' + color + ';transition:.3s' + (isToday ? ';outline:2px solid #FF8A00;outline-offset:1px' : '') + '"></div>' +
      '</div>' +
      '<div style="font-size:9px;color:' + (isToday ? '#FF8A00' : 'var(--text2)') + ';font-weight:' + (isToday ? '700' : '400') + '">' + dayNames[new Date(d).getDay()] + '</div>' +
    '</div>';
  }).join('');

  var weekPct = habits.length * 7 > 0 ? Math.round(totalDone / (habits.length * 7) * 100) : 0;
  var weekColor = weekPct >= 70 ? '#22c55e' : '#FF8A00';

  container.innerHTML =
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">' +
      '<div style="font-size:13px;font-weight:700;color:var(--text)">সাপ্তাহিক অগ্রগতি</div>' +
      '<div style="font-size:18px;font-weight:800;color:' + weekColor + '">' + weekPct + '%</div>' +
    '</div>' +
    '<div style="display:flex;align-items:flex-end;gap:4px;border-bottom:1px solid var(--border,#e5e7eb);padding-bottom:0">' + bars + '</div>';
}


