window.rzNamazViewDate        = new Date();
window.rzNamazData            = {};
window.rzNamazHistory         = {};
window.rzNamazHistoryDates    = [];
window._rzNamazCelebrated     = false;

// ── Page init ──────────────────────────────────────────────────
async function rzNamazPageLoad() {
  window.rzNamazViewDate    = new Date();
  window._rzNamazCelebrated = false;
  rzUpdateNamazDateDisplay();
  rzRenderNamazKidTabs();
  await rzLoadNamazData();
  rzLoad7DayNamazHistory();
}

// ── Kid tabs ───────────────────────────────────────────────────
function rzRenderNamazKidTabs() {
  var container = document.getElementById('namaz-kid-tabs');
  if (!container) return;
  var kids     = window.rzKids || [];
  var activeId = window.rzActiveKid ? window.rzActiveKid.id : null;
  container.innerHTML = '';
  if (!kids.length) {
    container.innerHTML = '<div style="font-size:12px;color:var(--text2);padding:4px 0">কোনো বাচ্চা নেই — Dashboard থেকে যোগ করুন</div>';
    return;
  }
  kids.forEach(function(kid) {
    var isActive = kid.id === activeId;
    var tab = document.createElement('div');
    tab.className = 'kid-tab' + (isActive ? ' active' : '');
    tab.innerHTML =
      '<span class="kid-tab-ic"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg></span>' +
      kid.name + ' (' + kid.age + ' বছর)';
    tab.onclick = function() {
      window.rzActiveKid = kid;
      rzRenderNamazKidTabs();
      rzLoadNamazData();
      rzLoad7DayNamazHistory();
    };
    container.appendChild(tab);
  });
}

// ── Date display ───────────────────────────────────────────────
function rzUpdateNamazDateDisplay() {
  var vd    = window.rzNamazViewDate || new Date();
  var today = new Date();
  var main  = document.getElementById('namaz-date-main');
  var sub   = document.getElementById('namaz-date-sub');
  if (!main) return;
  var months   = ['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
  var daysFull = ['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
  var isToday  = vd.toDateString() === today.toDateString();
  var dateStr  = rzToBn(vd.getDate()) + ' ' + months[vd.getMonth()] + ' ' + rzToBn(vd.getFullYear());
  main.textContent = (isToday ? 'আজ, ' : '') + dateStr;
  if (sub) sub.textContent = daysFull[vd.getDay()];
}

// ── Navigate date (no future) ──────────────────────────────────
function rzNamazChangeDate(dir) {
  var vd   = new Date(window.rzNamazViewDate || new Date());
  vd.setDate(vd.getDate() + dir);
  var cap  = new Date(); cap.setHours(23, 59, 59, 999);
  if (vd > cap) return;
  window.rzNamazViewDate = vd;
  rzUpdateNamazDateDisplay();
  rzLoadNamazData();
}

// ── Load namaz data for current kid + date ─────────────────────
async function rzLoadNamazData() {
  if (!window._sb || !window.rzActiveKid) {
    window.rzNamazData = {};
    rzRenderNamazCards();
    rzUpdateNamazStats({});
    return;
  }
  var dateStr = (window.rzNamazViewDate || new Date()).toISOString().split('T')[0];
  try {
    var res = await _sb.from('namaz_logs').select('*')
      .eq('kid_id', window.rzActiveKid.id)
      .eq('log_date', dateStr)
      .maybeSingle();
    window.rzNamazData = res.data || {};
    rzRenderNamazCards();
    rzUpdateNamazStats(window.rzNamazData);
  } catch(e) {
    console.error('rzLoadNamazData:', e);
    window.rzNamazData = {};
    rzRenderNamazCards();
    rzUpdateNamazStats({});
  }
}

// ── Render 5 prayer cards ──────────────────────────────────────
function rzRenderNamazCards() {
  var list = document.getElementById('namaz-cards-list');
  if (!list) return;
  var data    = window.rzNamazData        || {};
  var history = window.rzNamazHistory     || {};
  var dates   = window.rzNamazHistoryDates|| [];
  var dateStr = (window.rzNamazViewDate || new Date()).toISOString().split('T')[0];
  var isDark  = document.body.classList.contains('dark-mode');

  list.innerHTML = '';
  RZ_NAMAZ_CONFIG.forEach(function(p) {
    var done = !!data[p.key];

    // 7-day dots
    var dotsHtml = '';
    if (dates.length) {
      dotsHtml = '<div style="display:flex;align-items:center;gap:3px;margin-top:5px">' +
        dates.map(function(d) {
          var hRow  = history[d] || {};
          var wasDone  = !!hRow[p.key];
          var isViewDay = d === dateStr;
          var sz = isViewDay ? 9 : 7;
          var bg = wasDone ? p.color : isViewDay ? p.bgMid : (isDark ? '#2d3748' : '#e5e7eb');
          return '<div style="width:' + sz + 'px;height:' + sz + 'px;border-radius:50%;background:' + bg + ';flex-shrink:0" title="' + d + '"></div>';
        }).join('') +
        '<span style="font-size:9px;color:var(--text2,#888);margin-left:3px;opacity:.7">৭দিন</span>' +
      '</div>';
    }

    var card = document.createElement('div');
    card.onclick = function() { rzToggleNamazPage(p.key); };
    card.style.cssText = [
      'display:flex', 'align-items:center', 'gap:12px', 'padding:14px',
      'border-radius:16px', 'cursor:pointer',
      'border-left:4px solid '   + (done ? p.color                      : (isDark ? '#2d3748' : '#e5e7eb')),
      'border-top:1.5px solid '  + (done ? p.color + '40'               : (isDark ? '#2d3748' : '#e5e7eb')),
      'border-right:1.5px solid '+ (done ? p.color + '40'               : (isDark ? '#2d3748' : '#e5e7eb')),
      'border-bottom:1.5px solid '+(done ? p.color + '40'               : (isDark ? '#2d3748' : '#e5e7eb')),
      'background:'              + (done ? p.bg                          : 'var(--card,#fff)'),
      'box-shadow:'              + (done ? '0 2px 10px ' + p.color + '22': '0 1px 3px rgba(0,0,0,.05)'),
      'transition:all .2s'
    ].join(';');

    card.innerHTML =
      // icon box
      '<div style="width:48px;height:48px;border-radius:14px;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:' + (done ? p.bg : (isDark ? 'rgba(255,255,255,.05)' : '#f9fafb')) + '">' +
        p.icon(done ? p.color : (isDark ? '#4a5568' : '#c4c4c4')) +
      '</div>' +
      // info
      '<div style="flex:1;min-width:0">' +
        '<div style="font-size:15px;font-weight:700;color:' + (done ? p.color : 'var(--text,#1f2937)') + '">' + p.name + '</div>' +
        '<div style="font-size:11px;color:var(--text2,#888);margin-top:1px">' + p.time + '</div>' +
        dotsHtml +
      '</div>' +
      // check + points
      '<div style="flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:5px">' +
        '<div style="width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:' +
          (done ? p.color : (isDark ? '#2d3748' : '#f3f4f6')) +
          ';box-shadow:' + (done ? '0 3px 8px ' + p.color + '44' : 'none') + '">' +
          (done
            ? '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>'
            : '<div style="width:14px;height:14px;border-radius:50%;border:2px solid ' + (isDark ? '#4a5568' : '#d1d5db') + '"></div>') +
        '</div>' +
        '<div style="font-size:10px;font-weight:700;color:' + p.color + '">+' + p.points + 'pts</div>' +
      '</div>';

    list.appendChild(card);
  });
}

// ── Circular arc progress ──────────────────────────────────────
function rzRenderNamazArc(done) {
  var arcEl = document.getElementById('namaz-arc-fill');
  var numEl = document.getElementById('namaz-arc-num');
  var n     = done || 0;
  var circ  = 194.8;
  if (arcEl) arcEl.style.strokeDashoffset = (circ * (1 - n / 5)).toFixed(1);
  if (numEl) numEl.textContent = (typeof rzToBn === 'function') ? rzToBn(n) : n;
}

// ── Update stats row ───────────────────────────────────────────
function rzUpdateNamazStats(data) {
  var done   = RZ_NAMAZ_CONFIG.filter(function(p) { return data && data[p.key]; }).length;
  var pts    = RZ_NAMAZ_CONFIG.filter(function(p) { return data && data[p.key]; })
               .reduce(function(s, p) { return s + p.points; }, 0);
  var kid    = window.rzActiveKid || {};
  var streak = kid.streak_count || 0;
  var fire   = streak >= 7 ? ' 🔥🔥' : streak >= 3 ? ' 🔥' : streak > 0 ? ' ✨' : '';

  function setEl(id, v) { var e = document.getElementById(id); if (e) e.textContent = v; }
  setEl('nz-done-count', done + '/৫');
  setEl('nz-streak',     streak + fire);
  setEl('nz-pts',        pts);
  rzRenderNamazArc(done);
  rzRenderNamazWeekly();

  // 5/5 celebration
  if (done === 5 && !window._rzNamazCelebrated) {
    window._rzNamazCelebrated = true;
    rzNamazCelebrate();
  } else if (done < 5) {
    window._rzNamazCelebrated = false;
  }
}

// ── Toggle prayer + save to DB ─────────────────────────────────
async function rzToggleNamazPage(prayerKey) {
  if (!window._sb || !window.rzActiveKid || !window.sbUser) return;
  var data   = window.rzNamazData || {};
  var newVal = !data[prayerKey];
  var update = {};
  update[prayerKey] = newVal;
  window.rzNamazData = Object.assign({}, data, update);
  rzRenderNamazCards();
  rzUpdateNamazStats(window.rzNamazData);

  var dateStr = (window.rzNamazViewDate || new Date()).toISOString().split('T')[0];
  var payload = Object.assign({ kid_id: rzActiveKid.id, parent_id: sbUser.id, log_date: dateStr }, window.rzNamazData);
  var res = await _sb.from('namaz_logs').upsert(payload, { onConflict: 'kid_id,log_date' });
  if (res.error) {
    window.rzNamazData = data;
    rzRenderNamazCards();
    rzUpdateNamazStats(data);
    console.error('rzToggleNamazPage:', res.error);
    if (typeof cmToast === 'function') cmToast('Error: ' + res.error.message);
  } else {
    var cfg = RZ_NAMAZ_CONFIG.find(function(x) { return x.key === prayerKey; });
    if (cfg) {
      if (newVal) {
        rzActiveKid.points = (rzActiveKid.points || 0) + cfg.points;
        if (typeof cmToast === 'function') cmToast(cfg.name + ' পড়া হয়েছে! +' + cfg.points + 'pts');
      } else {
        rzActiveKid.points = Math.max(0, (rzActiveKid.points || 0) - cfg.points);
      }
      rzUpdateNamazStats(window.rzNamazData);
    }
    // keep dashboard namaz in sync
    window.rzTodayNamaz = Object.assign({}, window.rzTodayNamaz || {}, update);
  }
}

// ── Load 7-day namaz history ───────────────────────────────────
async function rzLoad7DayNamazHistory() {
  if (!window._sb || !window.rzActiveKid) return;
  var today = new Date(), dates = [];
  for (var i = 6; i >= 0; i--) {
    var d = new Date(today); d.setDate(today.getDate() - i);
    dates.push(d.toISOString().split('T')[0]);
  }
  window.rzNamazHistoryDates = dates;
  try {
    var res = await _sb.from('namaz_logs')
      .select('log_date,fajr,dhuhr,asr,maghrib,isha')
      .eq('kid_id', window.rzActiveKid.id)
      .in('log_date', dates);
    window.rzNamazHistory = {};
    (res.data || []).forEach(function(row) {
      window.rzNamazHistory[row.log_date] = row;
    });
    if (document.getElementById('namaz-cards-list')) {
      rzRenderNamazCards();
      rzRenderNamazWeekly();
    }
  } catch(e) { console.error('rzLoad7DayNamazHistory:', e); }
}

// ── Weekly bar chart ───────────────────────────────────────────
function rzRenderNamazWeekly() {
  var container = document.getElementById('namaz-weekly');
  if (!container) return;
  var dates   = window.rzNamazHistoryDates || [];
  var history = window.rzNamazHistory      || {};
  if (!dates.length) { container.style.display = 'none'; return; }
  container.style.display = 'block';

  var prayers  = ['fajr','dhuhr','asr','maghrib','isha'];
  var dayNames = ['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
  var todayStr = rzToday(), totalDone = 0;

  var bars = dates.map(function(d) {
    var row    = history[d] || {};
    var done   = prayers.filter(function(p) { return row[p]; }).length;
    totalDone += done;
    var barH   = Math.max(4, Math.round(done / 5 * 48));
    var isToday= d === todayStr;
    var color  = done === 5 ? '#22c55e' : done >= 3 ? '#FF8A00' : done > 0 ? '#FFB800' : 'var(--border,#e5e7eb)';
    return '<div style="display:flex;flex-direction:column;align-items:center;gap:3px;flex:1">' +
      '<div style="font-size:9px;color:' + (isToday ? '#FF8A00' : 'var(--text2)') + ';font-weight:' + (isToday ? '700' : '400') + '">' + done + '/৫</div>' +
      '<div style="width:100%;height:48px;display:flex;align-items:flex-end">' +
        '<div style="width:100%;height:' + barH + 'px;border-radius:4px 4px 0 0;background:' + color + ';transition:.3s' + (isToday ? ';outline:2px solid #FF8A00;outline-offset:1px' : '') + '"></div>' +
      '</div>' +
      '<div style="font-size:9px;color:' + (isToday ? '#FF8A00' : 'var(--text2)') + ';font-weight:' + (isToday ? '700' : '400') + '">' + dayNames[new Date(d).getDay()] + '</div>' +
    '</div>';
  }).join('');

  var weekPct   = Math.round(totalDone / (dates.length * 5) * 100);
  var weekColor = weekPct >= 80 ? '#22c55e' : '#FF8A00';

  container.innerHTML =
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">' +
      '<div style="font-size:13px;font-weight:700;color:var(--text)">সাপ্তাহিক রিপোর্ট</div>' +
      '<div style="font-size:18px;font-weight:800;color:' + weekColor + '">' + weekPct + '%</div>' +
    '</div>' +
    '<div style="display:flex;align-items:flex-end;gap:4px">' + bars + '</div>';
}

// ══════════════════════════════════════════════════════════════
//  ADULT NAMAZ TRACKER
// ══════════════════════════════════════════════════════════════

