var RZ_AQURAN_STATUS = ['শেখা হয়নি', 'শিখছি', 'মুখস্থ', 'পুনরাবৃত্তি'];
var RZ_AQURAN_STATUS_COLORS = ['var(--border)', '#FF8A00', '#22C55E', '#818CF8'];

function rzAQuranTodayKey() {
  var d = new Date();
  return d.getFullYear() + '-' + (d.getMonth()+1) + '-' + d.getDate();
}

var _aqCache = null;

function rzLoadAQuranData() {
  if(_aqCache) return _aqCache;
  try { _aqCache = JSON.parse(localStorage.getItem('rz_adult_quran_v2') || '{}'); } catch(e) { _aqCache = {}; }
  return _aqCache;
}

function rzSaveAQuranData(data) {
  _aqCache = data;
  try { localStorage.setItem('rz_adult_quran_v2', JSON.stringify(data)); } catch(e) {}
  rzSaveAQuranDataSb(data);
}

async function rzLoadAQuranFromSb() {
  var u = window.sbUser || null;
  if(!u) return;
  var res = await window._sb.from('adult_quran_data').select('*').eq('user_id', u.id).maybeSingle();
  if(res.data) {
    _aqCache = { tilawat: res.data.tilawat || {}, progress: res.data.progress || {}, dailyGoal: res.data.daily_goal || 2 };
  } else {
    _aqCache = _aqCache || { tilawat: {}, progress: {}, dailyGoal: 2 };
  }
  try { localStorage.setItem('rz_adult_quran_v2', JSON.stringify(_aqCache)); } catch(e) {}
}

async function rzSaveAQuranDataSb(data) {
  var u = window.sbUser || null;
  if(!u) return;
  await window._sb.from('adult_quran_data').upsert({ user_id: u.id, tilawat: data.tilawat || {}, progress: data.progress || {}, daily_goal: data.dailyGoal || 2, updated_at: new Date().toISOString() }, { onConflict: 'user_id' });
}

function rzGetAQuranProgress(data) { return data.progress || {}; }
function rzGetAQuranTilawat(data)  { return data.tilawat  || {}; }
function rzGetAQuranGoal(data)     { return data.dailyGoal || 2; }

function rzCalcQuranStreak(data) {
  var tilawat = rzGetAQuranTilawat(data);
  var streak = 0;
  var d = new Date(); d.setHours(0,0,0,0);
  for(var i = 0; i < 365; i++) {
    var k = d.getFullYear() + '-' + (d.getMonth()+1) + '-' + d.getDate();
    if(tilawat[k] > 0) {
      streak++;
    } else if(i > 0) {
      break;
    }
    d.setDate(d.getDate() - 1);
  }
  return streak;
}

function rzForceHideQuranKids() {
  var _kq = document.getElementById('quran-kids-wrap');
  var _aq = document.getElementById('quran-adult-wrap');
  if(_kq) { _kq.style.cssText = 'display:none!important'; }
  if(_aq && _aq.style.display === 'none') { _aq.style.display = 'block'; }
}

function rzRenderAdultQuran() {
  rzForceHideQuranKids();
  window.rzAQuranFilter = window.rzAQuranFilter || 'juz30';
  _aqCache = null;
  var u = window.sbUser || null;
  if(u) {
    rzLoadAQuranFromSb().then(function() {
      rzRenderAQuranHero(); rzRenderAQuranTilawat(); rzRenderAQuranWeekly(); rzRenderAQuranGrid(); rzRenderAQuranMilestones();
    });
  } else {
    rzRenderAQuranHero(); rzRenderAQuranTilawat(); rzRenderAQuranWeekly(); rzRenderAQuranGrid(); rzRenderAQuranMilestones();
  }
}

function rzRenderAQuranHero() {
  var data = rzLoadAQuranData();
  var progress = rzGetAQuranProgress(data);
  var tilawat  = rzGetAQuranTilawat(data);
  var today    = rzAQuranTodayKey();

  var BN_DAYS   = ['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
  var BN_MONTHS = ['জানুয়ারি','ফেব্রুয়ারি','মার্চ','এপ্রিল','মে','জুন','জুলাই','আগস্ট','সেপ্টেম্বর','অক্টোবর','নভেম্বর','ডিসেম্বর'];
  var now = new Date();
  var dateStr = BN_DAYS[now.getDay()] + ', ' + (typeof rzToBn==='function'?rzToBn(now.getDate()):now.getDate()) + ' ' + BN_MONTHS[now.getMonth()] + ' ' + (typeof rzToBn==='function'?rzToBn(now.getFullYear()):now.getFullYear());

  var dateEl = document.getElementById('aquran-date');
  if(dateEl) dateEl.textContent = dateStr;

  var memorized = RZ_ADULT_SURAHS.filter(function(s){ return (progress[s.no]||{}).status === 2 || (progress[s.no]||{}).status === 3; }).length;
  var total     = RZ_ADULT_SURAHS.length;
  var pct       = Math.round(memorized / total * 100);
  var todayPages = tilawat[today] || 0;
  var streak    = rzCalcQuranStreak(data);

  var motivations = [
    'আজ কুরআন পড়ুন — আল্লাহ আপনাকে ভালোবাসেন',
    'প্রতিটি অক্ষরে ১০টি নেকি — পড়তে থাকুন!',
    'কুরআনের সাথে সময় কাটানো সর্বোত্তম',
    'আজ একটি নতুন সুরা শেখার চেষ্টা করুন',
    'ধীরে ধীরে পড়ুন — তাজবীদ মেনে চলুন'
  ];
  var motEl = document.getElementById('aquran-motivation');
  if(motEl) motEl.textContent = motivations[now.getDay() % motivations.length];

  var strEl = document.getElementById('aquran-streak');
  if(strEl) strEl.textContent = (typeof rzToBn==='function'?rzToBn(streak):streak) + (streak>=7?' 🔥🔥':streak>=3?' 🔥':streak>0?' ✨':'');

  var memEl = document.getElementById('aquran-memorized');
  if(memEl) memEl.textContent = typeof rzToBn==='function'?rzToBn(memorized):memorized;

  var tpEl = document.getElementById('aquran-today-pages');
  if(tpEl) tpEl.textContent = typeof rzToBn==='function'?rzToBn(todayPages):todayPages;

  var ring = document.getElementById('aquran-ring');
  if(ring) ring.style.strokeDashoffset = (213.6 * (1 - pct/100)).toFixed(2);
  var pctEl = document.getElementById('aquran-pct');
  if(pctEl) pctEl.textContent = (typeof rzToBn==='function'?rzToBn(pct):pct) + '%';

  var memBadge = document.getElementById('aquran-mem-badge');
  if(memBadge) memBadge.textContent = (typeof rzToBn==='function'?rzToBn(memorized):memorized) + '/' + (typeof rzToBn==='function'?rzToBn(total):total);
}

function rzRenderAQuranTilawat() {
  var data  = rzLoadAQuranData();
  var today = rzAQuranTodayKey();
  var pages = (rzGetAQuranTilawat(data))[today] || 0;
  var goal  = rzGetAQuranGoal(data);
  var pct   = Math.min(Math.round(pages / goal * 100), 100);

  var bigEl = document.getElementById('aquran-pages-big');
  if(bigEl) bigEl.textContent = typeof rzToBn==='function'?rzToBn(pages):pages;

  var goalBar = document.getElementById('aquran-goal-bar');
  if(goalBar) goalBar.style.width = pct + '%';

  var goalPctEl = document.getElementById('aquran-goal-pct');
  if(goalPctEl) goalPctEl.textContent = (typeof rzToBn==='function'?rzToBn(pct):pct) + '%';

  var goalBadge = document.getElementById('aquran-goal-badge');
  if(goalBadge) goalBadge.textContent = 'লক্ষ্য: ' + (typeof rzToBn==='function'?rzToBn(goal):goal) + ' পৃ/দিন ✎';
  var decBtn = document.getElementById('aquran-dec-btn');
  if(decBtn) { decBtn.style.opacity = pages > 0 ? '1' : '0.3'; decBtn.style.cursor = pages > 0 ? 'pointer' : 'default'; }

  var txtEl = document.getElementById('aquran-goal-txt');
  if(txtEl) {
    if(pages === 0) txtEl.textContent = 'আজ পড়া শুরু করুন';
    else if(pct >= 100) txtEl.textContent = 'আলহামদুলিল্লাহ! লক্ষ্য পূরণ হয়েছে 🌟';
    else txtEl.textContent = 'আর ' + (typeof rzToBn==='function'?rzToBn(goal-pages):goal-pages) + ' পৃষ্ঠা পড়লে লক্ষ্য পূরণ হবে';
  }
}

function rzLogAdultTilawat(pages) {
  var data  = rzLoadAQuranData();
  var today = rzAQuranTodayKey();
  if(!data.tilawat) data.tilawat = {};
  data.tilawat[today] = (data.tilawat[today] || 0) + pages;
  rzSaveAQuranData(data);
  rzRenderAQuranTilawat();
  rzRenderAQuranHero();
  rzRenderAQuranWeekly();
  var n = data.tilawat[today];
  if(typeof showToast==='function') showToast('📖 '+(typeof rzToBn==='function'?rzToBn(n):n)+' পৃষ্ঠা — জাযাকাল্লাহ খাইরান');
}

function rzDecAdultTilawat() {
  var data  = rzLoadAQuranData();
  var today = rzAQuranTodayKey();
  if(!data.tilawat) data.tilawat = {};
  var cur = data.tilawat[today] || 0;
  if(cur <= 0) return;
  data.tilawat[today] = cur - 1;
  rzSaveAQuranData(data);
  rzRenderAQuranTilawat();
  rzRenderAQuranHero();
  rzRenderAQuranWeekly();
}

function rzSetQuranGoal() {
  var data = rzLoadAQuranData();
  var cur  = rzGetAQuranGoal(data);
  var opts = [1,2,3,4,5,7,10];
  var next = opts[(opts.indexOf(cur)+1) % opts.length];
  data.dailyGoal = next;
  rzSaveAQuranData(data);
  rzRenderAQuranTilawat();
  if(typeof showToast==='function') showToast('লক্ষ্য নির্ধারিত: '+(typeof rzToBn==='function'?rzToBn(next):next)+' পৃষ্ঠা/দিন');
}

function rzRenderAQuranWeekly() {
  var container = document.getElementById('aquran-weekly');
  if(!container) return;
  var data    = rzLoadAQuranData();
  var tilawat = rzGetAQuranTilawat(data);
  var goal    = rzGetAQuranGoal(data);
  var today   = new Date();
  var BN_SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

  var days = [];
  for(var i=6;i>=0;i--) {
    var d = new Date(today); d.setDate(today.getDate()-i);
    var k = d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();
    days.push({ pages: tilawat[k]||0, isToday: i===0, dayName: BN_SHORT[d.getDay()] });
  }
  var maxPages = Math.max.apply(null, days.map(function(d){ return d.pages; }).concat([goal]));
  var totalPages = days.reduce(function(s,d){ return s+d.pages; },0);

  var gridCols = '30px repeat(7,1fr)';
  var gap = '5px';

  var countRow = '<div style="display:grid;grid-template-columns:'+gridCols+';gap:'+gap+';align-items:flex-end;margin-bottom:2px">' +
    '<div></div>' + days.map(function(d){
      return '<div style="text-align:center;font-size:10px;font-weight:700;color:var(--text2)">'+(d.pages>0?(typeof rzToBn==='function'?rzToBn(d.pages):d.pages):'·')+'</div>';
    }).join('') + '</div>';

  var barRow = '<div style="display:grid;grid-template-columns:'+gridCols+';gap:'+gap+';height:56px;align-items:flex-end;margin-bottom:3px">' +
    '<div style="display:flex;align-items:flex-end;justify-content:flex-end;padding-bottom:2px"><div style="width:100%;height:1px;background:rgba(34,197,94,0.2)"></div></div>' +
    days.map(function(d){
      var pct2 = maxPages > 0 ? d.pages/maxPages : 0;
      var metGoal = d.pages >= goal;
      var col2 = metGoal ? '#22C55E' : d.pages > 0 ? '#FF8A00' : 'var(--border)';
      var h = Math.max(Math.round(pct2*48), d.isToday ? 4 : 2);
      return '<div style="width:100%;background:var(--border);border-radius:5px;height:48px;position:relative;overflow:hidden;'+(d.isToday?'box-shadow:0 0 0 2px '+col2+'55;':'')+'">' +
        '<div style="position:absolute;bottom:0;left:0;right:0;height:'+h+'px;background:'+col2+';border-radius:5px;transition:.4s ease"></div>' +
      '</div>';
    }).join('') + '</div>';

  var dayNameRow = '<div style="display:grid;grid-template-columns:'+gridCols+';gap:'+gap+';margin-bottom:0">' +
    '<div></div>' + days.map(function(d){
      var col3 = d.pages>=goal?'#22C55E':d.pages>0?'#FF8A00':'var(--text2)';
      return '<div style="text-align:center;font-size:9.5px;color:'+(d.isToday?col3:'var(--text2)')+';font-weight:'+(d.isToday?'800':'400')+'">'+d.dayName+'</div>';
    }).join('') + '</div>';

  container.innerHTML =
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">' +
      '<div>' +
        '<div style="font-size:13px;font-weight:800;color:var(--text)">সাপ্তাহিক তেলাওয়াত</div>' +
        '<div style="font-size:11px;color:var(--text2);margin-top:2px">গত ৭ দিন — মোট '+(typeof rzToBn==='function'?rzToBn(totalPages):totalPages)+' পৃষ্ঠা</div>' +
      '</div>' +
      '<div style="font-size:10px;font-weight:700;color:#22C55E;background:rgba(34,197,94,0.1);padding:4px 10px;border-radius:20px">লক্ষ্য: '+(typeof rzToBn==='function'?rzToBn(goal):goal)+'পৃ/দিন</div>' +
    '</div>' +
    countRow + barRow + dayNameRow;
}

function rzAdultQuranFilter(cat) {
  window.rzAQuranFilter = cat;
  ['juz30','key','all'].forEach(function(c) {
    var btn = document.getElementById('aquran-cat-' + c);
    if(!btn) return;
    var active = c === cat;
    btn.style.borderColor = active ? '#22C55E' : 'var(--border)';
    btn.style.background  = active ? 'rgba(34,197,94,0.1)' : 'transparent';
    btn.style.color       = active ? '#22C55E' : 'var(--text2)';
    btn.style.fontWeight  = active ? '700' : '600';
  });
  rzRenderAQuranGrid();
}

function rzRenderAQuranGrid() {
  var grid = document.getElementById('aquran-grid');
  if(!grid) return;
  var data     = rzLoadAQuranData();
  var progress = rzGetAQuranProgress(data);
  var filter   = window.rzAQuranFilter || 'juz30';

  var surahs = filter === 'all' ? RZ_ADULT_SURAHS :
               filter === 'key' ? RZ_ADULT_SURAHS.filter(function(s){ return s.cat === 'key'; }) :
               RZ_ADULT_SURAHS.filter(function(s){ return s.cat === 'juz30'; });

  grid.innerHTML = '';
  surahs.forEach(function(s) {
    var prog   = progress[s.no] || { status: 0, stars: 0 };
    var status = prog.status || 0;
    var stars  = prog.stars  || 0;
    var sc     = RZ_AQURAN_STATUS_COLORS[status];
    var sl     = RZ_AQURAN_STATUS[status];
    var diffDots = '<span style="color:var(--text2);font-size:9px">' + '●'.repeat(s.diff) + '○'.repeat(3-s.diff) + '</span>';
    var starsHtml = '';
    for(var i=1;i<=3;i++) starsHtml += '<svg viewBox="0 0 24 24" width="11" height="11" fill="'+(i<=stars?'#FFB800':'none')+'" stroke="#FFB800" stroke-width="2"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>';

    var card = document.createElement('div');
    card.style.cssText = 'background:var(--card);border-radius:16px;padding:14px 12px;border:1.5px solid '+(status>0?sc+'44':'var(--border)')+';cursor:pointer;position:relative;overflow:hidden;transition:.2s';
    card.setAttribute('onclick', 'rzOpenAQuranModal(' + s.no + ')');
    card.innerHTML =
      '<div style="position:absolute;top:0;left:0;right:0;height:3px;background:'+(status>0?sc:'var(--border)')+';border-radius:16px 16px 0 0"></div>' +
      '<div class="rz-quran-font" style="font-size:22px;color:'+(status>0?sc:'var(--text2)')+';direction:rtl;text-align:right;line-height:1.4;margin-bottom:6px;opacity:'+(status>0?'1':'.4')+'">' + s.arabic + '</div>' +
      '<div style="font-size:12px;font-weight:700;color:var(--text);margin-bottom:2px">' + s.name + '</div>' +
      '<div style="font-size:10px;color:var(--text2);margin-bottom:8px">' + (typeof rzToBn==='function'?rzToBn(s.ayat):s.ayat) + ' আয়াত · ' + diffDots + '</div>' +
      '<div style="display:flex;align-items:center;justify-content:space-between">' +
        '<div style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:20px;background:'+sc+'18;color:'+sc+'">'+sl+'</div>' +
        '<div style="display:flex;gap:1px">' + starsHtml + '</div>' +
      '</div>';
    grid.appendChild(card);
  });
}

function rzOpenAQuranModal(surahNo) {
  var s = RZ_ADULT_SURAHS.filter(function(x){ return x.no === surahNo; })[0];
  if(!s) return;
  // If surah exists in the full kids reader, open it there
  var inKids = typeof RZ_SURAHS !== 'undefined' && RZ_SURAHS.find && RZ_SURAHS.find(function(x){ return x.no === surahNo; });
  if(inKids && typeof rzOpenSurahReader === 'function') {
    if(!window.rzQuranProgress) window.rzQuranProgress = {};
    rzOpenSurahReader(surahNo);
    return;
  }
  // Otherwise fall through to the adult tracking modal below
  var data  = rzLoadAQuranData();
  var prog  = (data.progress || {})[surahNo] || { status:0, stars:0 };
  var status = prog.status || 0;
  var stars  = prog.stars  || 0;

  var overlay = document.createElement('div');
  overlay.id = 'rz-aquran-modal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.65);z-index:9999;display:flex;align-items:flex-end;justify-content:center;padding:0';
  overlay.onclick = function(e){ if(e.target===overlay) rzCloseAQuranModal(); };

  var statusBtns = ['শেখা হয়নি','শিখছি','মুখস্থ','পুনরাবৃত্তি'].map(function(label, i){
    var active = i === status;
    var col = RZ_AQURAN_STATUS_COLORS[i];
    return '<button onclick="rzSetAQuranStatus('+surahNo+','+i+')" style="flex:1;padding:9px 4px;border-radius:10px;border:1.5px solid '+(active?col:col+'44')+';background:'+(active?col+'18':'transparent')+';color:'+(active?col:'var(--text2)')+';font-size:11px;font-weight:'+(active?'800':'500')+';cursor:pointer;font-family:inherit;transition:.15s">'+label+'</button>';
  }).join('');

  var starBtns = [1,2,3].map(function(i){
    return '<button onclick="rzSetAQuranStars('+surahNo+','+i+')" style="width:40px;height:40px;border-radius:10px;border:1.5px solid rgba(255,184,0,'+(i<=stars?'0.6':'0.2')+');background:rgba(255,184,0,'+(i<=stars?'0.12':'0.04')+');cursor:pointer;display:flex;align-items:center;justify-content:center">' +
      '<svg viewBox="0 0 24 24" width="18" height="18" fill="'+(i<=stars?'#FFB800':'none')+'" stroke="#FFB800" stroke-width="2"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>' +
    '</button>';
  }).join('');

  overlay.innerHTML =
    '<div style="background:var(--card);border-radius:24px 24px 0 0;width:100%;max-width:500px;padding:24px 20px 40px;max-height:85vh;overflow-y:auto">' +
      '<div style="width:40px;height:4px;background:var(--border);border-radius:2px;margin:0 auto 20px"></div>' +
      '<div style="text-align:center;margin-bottom:20px">' +
        '<div class="rz-quran-font" style="font-size:36px;color:#22C55E;margin-bottom:6px;line-height:1.4">' + s.arabic + '</div>' +
        '<div style="font-size:20px;font-weight:800;color:var(--text);margin-bottom:4px">' + s.name + '</div>' +
        '<div style="font-size:12px;color:var(--text2)">সুরা নং ' + (typeof rzToBn==='function'?rzToBn(s.no):s.no) + ' · ' + (typeof rzToBn==='function'?rzToBn(s.ayat):s.ayat) + ' আয়াত</div>' +
      '</div>' +
      '<div style="margin-bottom:18px">' +
        '<div style="font-size:11px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase;letter-spacing:.8px">অবস্থা</div>' +
        '<div style="display:flex;gap:6px">' + statusBtns + '</div>' +
      '</div>' +
      '<div style="margin-bottom:20px">' +
        '<div style="font-size:11px;font-weight:700;color:var(--text2);margin-bottom:8px;text-transform:uppercase;letter-spacing:.8px">আত্মবিশ্বাস</div>' +
        '<div style="display:flex;gap:10px;align-items:center">' + starBtns +
          '<span style="font-size:11px;color:var(--text2)">' + (stars===1?'মোটামুটি':stars===2?'ভালো':stars===3?'পারফেক্ট!':'রেটিং দিন') + '</span>' +
        '</div>' +
      '</div>' +
      '<button onclick="rzCloseAQuranModal()" style="width:100%;padding:14px;border-radius:14px;border:none;background:var(--border);color:var(--text);font-size:14px;font-weight:700;cursor:pointer;font-family:inherit">বন্ধ করুন</button>' +
    '</div>';

  document.body.appendChild(overlay);
}

function rzCloseAQuranModal() {
  var m = document.getElementById('rz-aquran-modal');
  if(m) m.parentNode.removeChild(m);
}
window.rzOpenAQuranModal  = rzOpenAQuranModal;
window.rzCloseAQuranModal = rzCloseAQuranModal;
window.rzSetAQuranStatus  = rzSetAQuranStatus;
window.rzSetAQuranStars   = rzSetAQuranStars;
window.rzLogAdultTilawat  = rzLogAdultTilawat;
window.rzDecAdultTilawat  = rzDecAdultTilawat;
window.rzSetQuranGoal     = rzSetQuranGoal;
window.rzAdultQuranFilter = rzAdultQuranFilter;

function rzSetAQuranStatus(surahNo, status) {
  var data = rzLoadAQuranData();
  if(!data.progress) data.progress = {};
  if(!data.progress[surahNo]) data.progress[surahNo] = { status:0, stars:0 };
  data.progress[surahNo].status = status;
  rzSaveAQuranData(data);
  rzCloseAQuranModal();
  rzOpenAQuranModal(surahNo);
  rzRenderAQuranGrid();
  rzRenderAQuranHero();
  rzRenderAQuranMilestones();
  var labels = ['শেখা হয়নি', 'শিখছি', 'মুখস্থ', 'পুনরাবৃত্তি'];
  if(typeof showToast==='function') showToast('সুরা আপডেট: ' + labels[status]);
  var prog = data.progress || {};
  var mem = RZ_ADULT_SURAHS.filter(function(s){ return (prog[s.no]||{}).status===2||(prog[s.no]||{}).status===3; }).length;
  var milestones = [5,10,20,30,43];
  milestones.forEach(function(m2){ if(mem===m2) rzAQuranCelebrate(m2); });
}

function rzSetAQuranStars(surahNo, stars) {
  var data = rzLoadAQuranData();
  if(!data.progress) data.progress = {};
  if(!data.progress[surahNo]) data.progress[surahNo] = { status:0, stars:0 };
  var prev = data.progress[surahNo].stars || 0;
  data.progress[surahNo].stars = stars === prev ? 0 : stars;
  rzSaveAQuranData(data);
  rzCloseAQuranModal();
  rzOpenAQuranModal(surahNo);
  rzRenderAQuranGrid();
}

function rzRenderAQuranMilestones() {
  var container = document.getElementById('aquran-milestones');
  if(!container) return;
  var data  = rzLoadAQuranData();
  var prog  = data.progress || {};
  var mem   = RZ_ADULT_SURAHS.filter(function(s){ return (prog[s.no]||{}).status===2||(prog[s.no]||{}).status===3; }).length;

  var ms = [
    { n:5,  icon:'🌱', label:'৫টি মুখস্থ',        color:'#CD7F32', title:'শিক্ষানবিস' },
    { n:10, icon:'⭐', label:'১০টি মুখস্থ',       color:'#A8A9AD', title:'হাফেজ শিক্ষার্থী' },
    { n:20, icon:'🏆', label:'২০টি মুখস্থ',       color:'#FFB800', title:'কুরআন প্রেমিক' },
    { n:30, icon:'👑', label:'জুয ৩০ সম্পন্ন',   color:'#22C55E', title:'জুয ৩০ হাফেজ' },
    { n:43, icon:'💎', label:'সব সুরা মুখস্থ',   color:'#818CF8', title:'মুকাম্মাল হাফেজ' }
  ];

  container.innerHTML =
    '<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:12px">মাইলস্টোন</div>' +
    '<div style="display:flex;flex-direction:column;gap:8px">' +
    ms.map(function(m2) {
      var done = mem >= m2.n;
      var pct2 = Math.min(Math.round(mem/m2.n*100), 100);
      return '<div style="background:var(--card);border-radius:14px;padding:12px 14px;border:1.5px solid '+(done?m2.color+'55':'var(--border)')+';display:flex;align-items:center;gap:12px">' +
        '<div style="width:40px;height:40px;border-radius:12px;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:20px;background:'+(done?m2.color+'18':'var(--border)')+'">'+m2.icon+'</div>' +
        '<div style="flex:1;min-width:0">' +
          '<div style="display:flex;justify-content:space-between;margin-bottom:5px">' +
            '<div style="font-size:12px;font-weight:700;color:'+(done?m2.color:'var(--text)')+'">'+m2.title+'</div>' +
            '<div style="font-size:11px;color:var(--text2)">'+m2.label+'</div>' +
          '</div>' +
          '<div style="height:5px;background:var(--border);border-radius:10px;overflow:hidden">' +
            '<div style="height:100%;width:'+pct2+'%;background:'+m2.color+';border-radius:10px;transition:.4s"></div>' +
          '</div>' +
        '</div>' +
        (done?'<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="'+m2.color+'" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>':'') +
      '</div>';
    }).join('') + '</div>';
}

function rzAQuranCelebrate(n) {
  var msg = n===5?'মাশাআল্লাহ! ৫টি সুরা মুখস্থ!':n===10?'সুবহানাল্লাহ! ১০টি সুরা মুখস্থ!':n===20?'আলহামদুলিল্লাহ! ২০টি সুরা!':n===30?'জুয ৩০ সম্পন্ন! অসাধারণ!':'মুবারকবাদ! সব সুরা মুখস্থ! 💎';
  if(typeof showToast==='function') showToast(msg);
  var s = document.createElement('style'); s.textContent = '@keyframes rzAQFall{0%{transform:translateY(0) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}';
  document.head.appendChild(s);
  var o = document.createElement('div');
  o.style.cssText = 'position:fixed;inset:0;z-index:99999;pointer-events:none;overflow:hidden';
  var emojis = ['📖','🌙','⭐','✨','🤲','💎','🏆','🌟'];
  var html3 = '';
  for(var i=0;i<28;i++) {
    var l=Math.round(Math.random()*100), dl=(Math.random()*1.5).toFixed(2), dr=(2.5+Math.random()*1.5).toFixed(2);
    html3 += '<div style="position:absolute;left:'+l+'%;top:-40px;font-size:22px;animation:rzAQFall '+dr+'s '+dl+'s ease-in forwards">'+emojis[i%emojis.length]+'</div>';
  }
  o.innerHTML = html3; document.body.appendChild(o);
  setTimeout(function(){ if(o.parentNode) o.parentNode.removeChild(o); if(s.parentNode) s.parentNode.removeChild(s); }, 5500);
}

// ══════════════════════════════════════════════════════════════
// ADULT SLEEP TRACKER
// ══════════════════════════════════════════════════════════════
(function() {
  var STORE_KEY = 'rz_adult_sleep_v2';

  var QUALITY_CFG = [
    { q:1, emoji:'😣', label:'খুব খারাপ', color:'#EF4444' },
    { q:2, emoji:'😕', label:'খারাপ',     color:'#F97316' },
    { q:3, emoji:'😐', label:'ঠিকঠাক',    color:'#EAB308' },
    { q:4, emoji:'😊', label:'ভালো',      color:'#22C55E' },
    { q:5, emoji:'😍', label:'দারুণ!',    color:'#FF8A00' }
  ];

  var TAGS_CFG = [
    { id:'exercise',  label:'🏃 ব্যায়াম',       color:'#22C55E' },
    { id:'noscreen',  label:'📵 স্ক্রিন কম',     color:'#3B82F6' },
    { id:'caffeine',  label:'☕ ক্যাফেইন',       color:'#A16207' },
    { id:'stress',    label:'😰 চাপ ছিল',         color:'#EF4444' },
    { id:'latesleep', label:'🌃 দেরিতে শোয়া',   color:'#8B5CF6' },
    { id:'routine',   label:'✅ ভালো রুটিন',     color:'#FF8A00' }
  ];

  var _aslData = null;
  var _aslQuality = 4;
  var _aslTags = [];
  var _aslCache = null;

  function loadData() {
    if(_aslCache) { _aslData = _aslCache; return _aslData; }
    try { _aslData = JSON.parse(localStorage.getItem(STORE_KEY)) || {}; } catch(e) { _aslData = {}; }
    if(!_aslData.logs) _aslData.logs = [];
    if(!_aslData.goal) _aslData.goal = 7.5;
    return _aslData;
  }
  function saveData() { try { localStorage.setItem(STORE_KEY, JSON.stringify(_aslData)); } catch(e) {} }

  async function aslLoadFromSb() {
    var u = window.sbUser || null;
    if(!u) return;
    var logsRes = await window._sb.from('adult_sleep_logs').select('*').eq('user_id', u.id);
    var setRes  = await window._sb.from('adult_sleep_settings').select('*').eq('user_id', u.id).single();
    var goal = (setRes.data && setRes.data.goal) ? Number(setRes.data.goal) : 7.5;
    var logs = (logsRes.data || []).map(function(r) {
      return { date: r.date_key, st: r.st, wt: r.wt, dur: r.dur, q: r.q, tags: r.tags || [] };
    });
    _aslData = { logs: logs, goal: goal };
    _aslCache = _aslData;
    try { localStorage.setItem(STORE_KEY, JSON.stringify(_aslData)); } catch(e) {}
  }

  async function aslUpsertLogSb(log) {
    var u = window.sbUser || null;
    if(!u) return;
    await window._sb.from('adult_sleep_logs').upsert({ user_id: u.id, date_key: log.date, st: log.st, wt: log.wt, dur: log.dur, q: log.q, tags: log.tags }, { onConflict: 'user_id,date_key' });
  }

  async function aslSaveGoalSb(goal) {
    var u = window.sbUser || null;
    if(!u) return;
    await window._sb.from('adult_sleep_settings').upsert({ user_id: u.id, goal: goal }, { onConflict: 'user_id' });
  }

  function todayKey() {
    var d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  }
  function dateKey(d) {
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  }
  function last14() {
    var r = [];
    for(var i=13;i>=0;i--) { var d=new Date(); d.setDate(d.getDate()-i); r.push(dateKey(d)); }
    return r;
  }
  function calcDur(st, wt) {
    if(!st||!wt) return 0;
    var sp = st.split(':').map(Number), wp = wt.split(':').map(Number);
    var d = (wp[0]*60+wp[1]) - (sp[0]*60+sp[1]);
    return d <= 0 ? d+1440 : d;
  }
  function toHM(min) {
    var h = Math.floor(min/60), m = min%60;
    return h + 'ঘ ' + (m > 0 ? m + 'মি' : '');
  }
  function bn(n) { return typeof rzToBn === 'function' ? rzToBn(n) : String(n); }

  // Score: 0-100
  function calcScore(log) {
    if(!log || !log.dur) return 0;
    var dh = log.dur / 60;
    var goal = (_aslData.goal || 7.5);
    // Duration score 0-50
    var diff = Math.abs(dh - goal);
    var dScore;
    if(diff <= 0.5) dScore = 50;
    else if(diff <= 1) dScore = 42;
    else if(diff <= 1.5) dScore = 32;
    else if(diff <= 2) dScore = 20;
    else if(diff <= 3) dScore = 10;
    else dScore = 2;
    // Quality score 0-35
    var qScore = ((log.q || 3) / 5) * 35;
    // Consistency score 0-15 (based on last 7 days std dev of sleep time)
    var recent = last14().slice(7).map(function(dk) {
      return (_aslData.logs||[]).find(function(l){ return l.date===dk; });
    }).filter(Boolean);
    var cScore = 0;
    if(recent.length >= 3) {
      var times = recent.map(function(l) {
        var p = (l.st||'22:00').split(':').map(Number);
        return p[0]*60+p[1];
      });
      var avg = times.reduce(function(a,b){return a+b;},0)/times.length;
      var variance = times.reduce(function(a,t){return a+Math.pow(t-avg,2);},0)/times.length;
      var stddev = Math.sqrt(variance);
      if(stddev < 15) cScore = 15;
      else if(stddev < 30) cScore = 10;
      else if(stddev < 45) cScore = 5;
      else cScore = 0;
    }
    return Math.min(100, Math.round(dScore + qScore + cScore));
  }

  function calcStreak() {
    var goal = _aslData.goal || 7.5;
    var streak = 0;
    var d = new Date();
    var today = todayKey();
    var hasTodayLog = (_aslData.logs||[]).some(function(l){return l.date===today;});
    if(!hasTodayLog) d.setDate(d.getDate()-1);
    for(var i=0;i<60;i++) {
      var dk = dateKey(d);
      var l = (_aslData.logs||[]).find(function(x){return x.date===dk;});
      if(l && l.dur >= goal*60) { streak++; d.setDate(d.getDate()-1); }
      else break;
    }
    return streak;
  }

  function calcAvg7() {
    var days = last14().slice(7);
    var logs = days.map(function(dk){
      return (_aslData.logs||[]).find(function(l){return l.date===dk;});
    }).filter(Boolean);
    if(!logs.length) return 0;
    return Math.round(logs.reduce(function(a,l){return a+(l.dur||0);},0)/logs.length);
  }

  function calcDebt7() {
    var goal = _aslData.goal || 7.5;
    var days = last14().slice(7);
    var debt = 0;
    days.forEach(function(dk) {
      var l = (_aslData.logs||[]).find(function(x){return x.date===dk;});
      var actual = l ? (l.dur/60) : 0;
      debt += (goal - actual);
    });
    return Math.round(debt * 10) / 10;
  }

  function getLastLog() {
    var logs = _aslData.logs || [];
    if(!logs.length) return null;
    var sorted = logs.slice().sort(function(a,b){ return a.date < b.date ? 1 : -1; });
    return sorted[0];
  }

  // ── Render functions ──────────────────────────────────────────
  function renderHero() {
    var lastLog = getLastLog();
    var streak = calcStreak();
    var avg7 = calcAvg7();
    var debt7 = calcDebt7();
    var score = lastLog ? calcScore(lastLog) : 0;

    // Duration
    var durEl = document.getElementById('asl-hero-duration');
    var timesEl = document.getElementById('asl-hero-times');
    if(durEl) {
      if(lastLog && lastLog.dur) {
        var h = Math.floor(lastLog.dur/60), m = lastLog.dur%60;
        durEl.textContent = h + ' hrs ' + (m>0? m+' min' : '');
      } else {
        durEl.textContent = 'Not logged yet';
      }
    }
    if(timesEl) {
      if(lastLog && lastLog.st) {
        timesEl.textContent = '🌙 ' + lastLog.st + '  →  ☀️ ' + lastLog.wt + '  •  ' + lastLog.date;
      } else {
        timesEl.textContent = 'Log today\'s sleep';
      }
    }

    // Streak
    var strEl = document.getElementById('asl-hero-streak');
    if(strEl) strEl.textContent = bn(streak);

    // Avg
    var avgEl = document.getElementById('asl-hero-avg');
    if(avgEl) avgEl.textContent = avg7 ? (Math.floor(avg7/60) + '.' + Math.round((avg7%60)/6) + 'h') : '—';

    // Debt
    var debtEl = document.getElementById('asl-hero-debt');
    var debtLblEl = document.getElementById('asl-hero-debt-lbl');
    if(debtEl) {
      if(debt7 > 0) {
        debtEl.textContent = debt7 + 'h';
        debtEl.style.color = '#EF4444';
        if(debtLblEl) { debtLblEl.textContent = 'Sleep Debt'; }
      } else if(debt7 < 0) {
        debtEl.textContent = Math.abs(debt7) + 'h+';
        debtEl.style.color = '#22C55E';
        if(debtLblEl) { debtLblEl.textContent = 'Ahead'; }
      } else {
        debtEl.textContent = '0h';
        debtEl.style.color = '#22C55E';
        if(debtLblEl) { debtLblEl.textContent = 'No debt'; }
      }
    }

    // Score ring
    var ring = document.getElementById('asl-score-ring');
    var scoreNumEl = document.getElementById('asl-score-num');
    if(ring && scoreNumEl) {
      var circumference = 213.6;
      var offset = circumference - (score/100)*circumference;
      setTimeout(function(){ ring.style.strokeDashoffset = offset; }, 100);
      scoreNumEl.textContent = score || '—';
      var ringColor = score >= 80 ? '#22C55E' : score >= 60 ? '#FFB800' : score >= 40 ? '#FF8A00' : '#EF4444';
      ring.style.stroke = score ? ringColor : 'rgba(255,255,255,0.08)';
      scoreNumEl.style.color = ringColor;
    }
  }

  function renderLogForm() {
    // Quality buttons
    var qRow = document.getElementById('asl-quality-row');
    if(qRow) {
      qRow.innerHTML = QUALITY_CFG.map(function(c) {
        var active = _aslQuality === c.q;
        return '<button onclick="rzAslSetQuality(' + c.q + ')" id="asl-q-' + c.q + '" style="flex:1;padding:10px 4px;border-radius:12px;border:2px solid ' + (active ? c.color : 'var(--border)') + ';background:' + (active ? 'rgba(' + hexToRgb(c.color) + ',0.12)' : 'transparent') + ';cursor:pointer;font-family:inherit;transition:.15s">' +
          '<div style="font-size:22px;line-height:1;margin-bottom:4px">' + c.emoji + '</div>' +
          '<div style="font-size:9px;font-weight:700;color:' + (active ? c.color : 'var(--text2)') + '">' + c.label + '</div>' +
          '</button>';
      }).join('');
    }
    // Tags
    var tRow = document.getElementById('asl-tags-row');
    if(tRow) {
      tRow.innerHTML = TAGS_CFG.map(function(t) {
        var active = _aslTags.indexOf(t.id) !== -1;
        return '<button onclick="rzAslToggleTag(\'' + t.id + '\')" id="asl-tag-' + t.id + '" style="padding:7px 12px;border-radius:20px;border:1.5px solid ' + (active ? t.color : 'var(--border)') + ';background:' + (active ? 'rgba(' + hexToRgb(t.color) + ',0.12)' : 'transparent') + ';cursor:pointer;font-family:inherit;font-size:11px;font-weight:700;color:' + (active ? t.color : 'var(--text2)') + ';transition:.15s">' + t.label + '</button>';
      }).join('');
    }
    renderGoal();
    rzAslUpdateDuration();
  }

  function loadTodayIntoForm() {
    var today = todayKey();
    var tLog = (_aslData.logs||[]).find(function(l){ return l.date===today; });
    if(!tLog) return;
    var stEl = document.getElementById('asl-sleep-time');
    var wtEl = document.getElementById('asl-wake-time');
    if(stEl && tLog.st) stEl.value = tLog.st;
    if(wtEl && tLog.wt) wtEl.value = tLog.wt;
    if(tLog.q) { _aslQuality = tLog.q; window.rzAslSetQuality(tLog.q); }
    if(tLog.tags) {
      _aslTags = tLog.tags.slice();
      _aslTags.forEach(function(tid){ window.rzAslToggleTag(tid); });
    }
    rzAslUpdateDuration();
  }

  function renderGoal() {
    var el = document.getElementById('asl-goal-display');
    if(el) {
      var g = _aslData.goal || 7.5;
      var h = Math.floor(g), half = (g % 1) >= 0.5;
      el.textContent = bn(h) + (half ? '.৫' : '') + ' ঘণ্টা';
    }
  }

  function hexToRgb(hex) {
    var r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    return r+','+g+','+b;
  }

  function renderScoreCard() {
    var el = document.getElementById('asl-score-card');
    if(!el) return;
    var lastLog = getLastLog();
    if(!lastLog || !lastLog.dur) {
      el.innerHTML = '<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:12px">📊 Sleep Score বিশ্লেষণ</div>' +
        '<div style="text-align:center;padding:20px 0;color:var(--text2);font-size:13px">ঘুম লগ করার পর স্কোর দেখা যাবে</div>';
      return;
    }
    var dh = lastLog.dur / 60;
    var goal = _aslData.goal || 7.5;
    var diff = Math.abs(dh - goal);
    var dScore = diff<=0.5?50:diff<=1?42:diff<=1.5?32:diff<=2?20:diff<=3?10:2;
    var qScore = Math.round(((lastLog.q||3)/5)*35);
    var cScore = calcScore(lastLog) - dScore - qScore; if(cScore<0)cScore=0;
    var total = Math.min(100, dScore+qScore+cScore);

    var scoreColor = total>=80?'#22C55E':total>=60?'#FFB800':total>=40?'#FF8A00':'#EF4444';
    var scoreLabel = total>=80?'অসাধারণ!':total>=60?'ভালো':total>=40?'ঠিকঠাক':'উন্নতি দরকার';

    el.innerHTML = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">' +
      '<div style="font-size:13px;font-weight:800;color:var(--text)">📊 Sleep Score বিশ্লেষণ</div>' +
      '<div style="font-size:11px;font-weight:700;color:' + scoreColor + ';background:rgba(' + hexToRgb(scoreColor) + ',0.1);padding:4px 10px;border-radius:20px">' + total + ' — ' + scoreLabel + '</div>' +
      '</div>' +
      renderScoreBar('⏱ সময়', dScore, 50, dScore>=40?'#22C55E':dScore>=25?'#FFB800':'#EF4444') +
      renderScoreBar('✨ মান', qScore, 35, qScore>=28?'#22C55E':qScore>=18?'#FFB800':'#EF4444') +
      renderScoreBar('🎯 ধারাবাহিকতা', cScore, 15, cScore>=12?'#22C55E':cScore>=6?'#FFB800':'#EF4444');
  }

  function renderScoreBar(label, val, max, color) {
    var pct = Math.round((val/max)*100);
    return '<div style="margin-bottom:10px">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px">' +
      '<div style="font-size:11px;color:var(--text2)">' + label + '</div>' +
      '<div style="font-size:11px;font-weight:800;color:' + color + '">' + val + '/' + max + '</div>' +
      '</div>' +
      '<div style="height:7px;background:var(--border);border-radius:6px;overflow:hidden">' +
      '<div style="height:100%;width:' + pct + '%;background:' + color + ';border-radius:6px;transition:width .6s ease"></div>' +
      '</div></div>';
  }

  function renderPhasesCard() {
    var el = document.getElementById('asl-phases-card');
    if(!el) return;
    var lastLog = getLastLog();
    if(!lastLog || !lastLog.dur) {
      el.innerHTML = '<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:12px">🌊 ঘুমের পর্যায়</div>' +
        '<div style="text-align:center;padding:20px 0;color:var(--text2);font-size:13px">ঘুম লগ করার পর phases দেখা যাবে</div>';
      return;
    }
    var q = lastLog.q || 3;
    var dur = lastLog.dur;
    // Phase estimates based on quality
    var awake = Math.round(dur * (q<=2 ? 0.12 : q<=3 ? 0.08 : 0.05));
    var light  = Math.round(dur * 0.48);
    var deep   = Math.round(dur * (q<=2 ? 0.18 : q<=3 ? 0.22 : 0.26));
    var rem    = dur - awake - light - deep;
    var total  = dur;

    el.innerHTML = '<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:14px">🌊 আনুমানিক ঘুমের পর্যায়</div>' +
      '<div style="display:flex;height:18px;border-radius:10px;overflow:hidden;margin-bottom:14px;gap:2px">' +
      '<div style="flex:' + awake + ';background:#EF4444;border-radius:10px 0 0 10px;min-width:' + (awake>0?'8px':'0') + '"></div>' +
      '<div style="flex:' + light + ';background:#93C5FD"></div>' +
      '<div style="flex:' + deep + ';background:#3B82F6"></div>' +
      '<div style="flex:' + rem + ';background:#8B5CF6;border-radius:0 10px 10px 0"></div>' +
      '</div>' +
      '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px">' +
      phaseItem('😳', 'জেগে', awake, total, '#EF4444') +
      phaseItem('💤', 'হালকা', light, total, '#93C5FD') +
      phaseItem('😴', 'গভীর', deep, total, '#3B82F6') +
      phaseItem('🌀', 'REM', rem, total, '#8B5CF6') +
      '</div>' +
      '<div style="margin-top:12px;padding:10px 12px;background:var(--bg);border-radius:10px;font-size:11px;color:var(--text2);line-height:1.5">' +
      '⚡ গভীর ঘুম স্মৃতি ও শরীর মেরামত করে। REM ঘুম সৃজনশীলতা ও মানসিক স্বাস্থ্যের জন্য জরুরি।' +
      '</div>';
  }

  function phaseItem(emoji, label, min, total, color) {
    var pct = total > 0 ? Math.round((min/total)*100) : 0;
    var h = Math.floor(min/60), m = min%60;
    return '<div style="text-align:center">' +
      '<div style="font-size:18px;margin-bottom:4px">' + emoji + '</div>' +
      '<div style="font-size:10px;font-weight:700;color:' + color + '">' + pct + '%</div>' +
      '<div style="font-size:9px;color:var(--text2);">' + label + '</div>' +
      '<div style="font-size:9px;color:var(--text2);">' + (h>0?h+'ঘ ':'') + m + 'মি</div>' +
      '</div>';
  }

  function renderChart() {
    var el = document.getElementById('asl-chart-card');
    if(!el) return;
    var days = last14();
    var goal = _aslData.goal || 7.5;
    var goalMin = goal * 60;
    var maxH = Math.max(goalMin * 1.3, 600);

    var bars = days.map(function(dk) {
      var log = (_aslData.logs||[]).find(function(l){ return l.date===dk; });
      return { dk:dk, dur: log ? log.dur : 0, q: log ? log.q : 0 };
    });

    var DAY_SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    var today = todayKey();

    el.innerHTML = '<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:6px;display:flex;align-items:center;justify-content:space-between">' +
      '<span>📅 ১৪ দিনের ঘুম</span>' +
      '<span style="font-size:10px;font-weight:600;color:var(--text2)">লক্ষ্য: ' + goal + 'ঘ</span>' +
      '</div>' +
      '<div style="font-size:10px;color:var(--text2);margin-bottom:12px">🟠 লক্ষ্য অর্জন &nbsp; 🔵 আংশিক &nbsp; ⬜ কোনো লগ নেই</div>' +
      '<div style="display:grid;grid-template-columns:repeat(14,1fr);gap:3px;align-items:end;height:80px;margin-bottom:6px">' +
      bars.map(function(b) {
        var h = b.dur > 0 ? Math.max(8, Math.round((b.dur/maxH)*80)) : 4;
        var color = b.dur === 0 ? 'var(--border)' : b.dur >= goalMin ? '#FF8A00' : '#93C5FD';
        var isToday = b.dk === today;
        return '<div title="' + b.dk + ': ' + (b.dur?toHM(b.dur):'없음') + '" style="height:' + h + 'px;background:' + color + ';border-radius:4px 4px 0 0;' + (isToday?'box-shadow:0 0 0 2px #FFB800;':'') + 'position:relative"></div>';
      }).join('') +
      '</div>' +
      '<div style="display:grid;grid-template-columns:repeat(14,1fr);gap:3px">' +
      bars.map(function(b, i) {
        var d = new Date(b.dk);
        var isToday = b.dk === today;
        return '<div style="font-size:7.5px;text-align:center;color:' + (isToday?'#FF8A00':'var(--text2)') + ';font-weight:' + (isToday?'800':'400') + '">' + (isToday?'আজ':DAY_SHORT[d.getDay()]) + '</div>';
      }).join('') +
      '</div>' +
      // Goal line indicator
      '<div style="margin-top:10px;display:flex;align-items:center;gap:6px">' +
      '<div style="flex:1;height:1px;background:rgba(255,138,0,0.3);border-top:1px dashed rgba(255,138,0,0.5)"></div>' +
      '<div style="font-size:9px;color:rgba(255,138,0,0.7)">লক্ষ্যমাত্রা</div>' +
      '</div>';
  }

  function renderInsights() {
    var el = document.getElementById('asl-insights-card');
    if(!el) return;
    var logs = _aslData.logs || [];
    var goal = _aslData.goal || 7.5;
    var avg7 = calcAvg7();
    var debt7 = calcDebt7();
    var streak = calcStreak();
    var days14 = last14();
    var recentLogs = days14.map(function(dk){ return logs.find(function(l){return l.date===dk;}); }).filter(Boolean);

    var insights = [];

    // Insight 1: avg vs goal
    if(avg7 > 0) {
      var avgH = avg7/60;
      var diff = avgH - goal;
      if(diff >= 0.5) insights.push({ icon:'🌙', title:'পর্যাপ্ত ঘুম', text:'গত ৭ দিনে গড়ে ' + avgH.toFixed(1) + 'ঘণ্টা ঘুমিয়েছ — লক্ষ্যের চেয়ে ' + diff.toFixed(1) + 'ঘণ্টা বেশি! চমৎকার।', color:'#22C55E' });
      else if(diff >= -0.5) insights.push({ icon:'✅', title:'লক্ষ্য মিলছে', text:'গত ৭ দিনে গড় ঘুম ' + avgH.toFixed(1) + 'ঘণ্টা। লক্ষ্যের খুব কাছে আছো!', color:'#FFB800' });
      else insights.push({ icon:'⚠️', title:'ঘুম কম হচ্ছে', text:'গত ৭ দিনে গড়ে মাত্র ' + avgH.toFixed(1) + 'ঘণ্টা ঘুমিয়েছ — লক্ষ্যের চেয়ে ' + Math.abs(diff).toFixed(1) + 'ঘণ্টা কম।', color:'#EF4444' });
    } else {
      insights.push({ icon:'📝', title:'শুরু করো', text:'ঘুম লগ করা শুরু করলে তোমার pattern বিশ্লেষণ করে পরামর্শ দিতে পারব।', color:'#FF8A00' });
    }

    // Insight 2: sleep debt
    if(debt7 > 2) insights.push({ icon:'😴', title:'ঘুম ঋণ আছে', text:'গত সপ্তাহে মোট ' + debt7 + 'ঘণ্টা ঘুমের ঘাটতি তৈরি হয়েছে। শীঘ্রই পূরণ করো।', color:'#EF4444' });
    else if(debt7 < -1) insights.push({ icon:'🏆', title:'এগিয়ে আছো!', text:'গত সপ্তাহে লক্ষ্যের চেয়ে ' + Math.abs(debt7) + 'ঘণ্টা বেশি ঘুমিয়েছ। শরীর ভালো আছে।', color:'#22C55E' });

    // Insight 3: streak
    if(streak >= 7) insights.push({ icon:'🔥', title:streak + ' দিনের Streak!', text:'টানা ' + streak + ' দিন ঘুমের লক্ষ্য পূরণ করেছ। এই ধারা অব্যাহত রাখো!', color:'#FF8A00' });

    // Insight 4: bedtime consistency
    if(recentLogs.length >= 4) {
      var times = recentLogs.map(function(l){ var p=(l.st||'22:00').split(':').map(Number); return p[0]*60+p[1]; });
      var avgT = times.reduce(function(a,b){return a+b;},0)/times.length;
      var vari = times.reduce(function(a,t){return a+Math.pow(t-avgT,2);},0)/times.length;
      var stddev = Math.sqrt(vari);
      if(stddev < 20) {
        var ah = Math.floor(avgT/60), am = Math.round(avgT%60);
        insights.push({ icon:'⏰', title:'ধারাবাহিক ঘুম', text:'তোমার গড় ঘুমানোর সময় ' + String(ah).padStart(2,'0') + ':' + String(am).padStart(2,'0') + ' — খুবই নিয়মিত! এটা শরীরের জন্য দারুণ।', color:'#22C55E' });
      } else if(stddev > 45) {
        insights.push({ icon:'⏰', title:'সময় অনিয়মিত', text:'ঘুমানোর সময় প্রতিদিন বদলায়। একটি নির্দিষ্ট সময়ে শোওয়ার চেষ্টা করো।', color:'#EAB308' });
      }
    }

    // Limit to 3
    insights = insights.slice(0, 3);

    el.innerHTML = '<div style="font-size:10px;font-weight:800;color:#FF8A00;letter-spacing:1px;text-transform:uppercase;margin-bottom:12px">💡 স্মার্ট বিশ্লেষণ</div>' +
      (insights.length ? insights.map(function(ins) {
        return '<div style="margin-bottom:12px;padding:12px 14px;background:rgba(255,255,255,0.05);border-radius:14px;border-left:3px solid ' + ins.color + '">' +
          '<div style="font-size:12px;font-weight:800;color:rgba(255,255,255,0.9);margin-bottom:4px">' + ins.icon + ' ' + ins.title + '</div>' +
          '<div style="font-size:11px;color:rgba(255,255,255,0.6);line-height:1.5">' + ins.text + '</div>' +
          '</div>';
      }).join('') : '<div style="padding:12px 14px;background:rgba(255,255,255,0.05);border-radius:14px"><div style="font-size:12px;color:rgba(255,255,255,0.5)">ঘুম লগ করলে স্মার্ট পরামর্শ পাবে।</div></div>');
  }

  function renderAchievements() {
    var el = document.getElementById('asl-achieve-card');
    if(!el) return;
    var logs = _aslData.logs || [];
    var goal = _aslData.goal || 7.5;
    var streak = calcStreak();
    var debt7 = calcDebt7();

    var ACHES = [
      { icon:'🌙', title:'প্রথম লগ', desc:'প্রথম ঘুম লগ করো', done: logs.length >= 1 },
      { icon:'🔥', title:'৭ দিন Streak', desc:'টানা ৭ দিন লক্ষ্য পূরণ', done: streak >= 7 },
      { icon:'⚡', title:'১৪ দিন Streak', desc:'টানা ১৪ দিন লক্ষ্য পূরণ', done: streak >= 14 },
      { icon:'🏆', title:'৩০ দিন Streak', desc:'টানা ৩০ দিন লক্ষ্য পূরণ', done: streak >= 30 },
      { icon:'💰', title:'ঘুম পরিশোধ', desc:'সপ্তাহে ঘুম ঘাটতি শূন্য করো', done: debt7 <= 0 && logs.length >= 7 },
      { icon:'⭐', title:'পারফেক্ট রাত', desc:'গুণমান ৫ এবং লক্ষ্য পূরণ', done: logs.some(function(l){ return l.q===5 && l.dur>=(goal*60); }) },
      { icon:'🌅', title:'আর্লি রাইজার', desc:'৫ দিন ভোর ৬টার আগে ওঠো', done: (function(){ var c=0; logs.forEach(function(l){ var p=(l.wt||'08:00').split(':').map(Number); if(p[0]<6) c++; }); return c>=5; })() },
      { icon:'🌃', title:'নাইট রুটিন', desc:'৭ দিন রাত ১১টার আগে শোও', done: (function(){ var c=0; logs.slice(-14).forEach(function(l){ var p=(l.st||'23:30').split(':').map(Number); if(p[0]<23||(p[0]===22)) c++; }); return c>=7; })() },
      { icon:'📊', title:'ডেটা মাস্টার', desc:'৩০টি ঘুম লগ করো', done: logs.length >= 30 }
    ];

    el.innerHTML = '<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:14px">🏅 অর্জন</div>' +
      '<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">' +
      ACHES.map(function(a) {
        return '<div style="text-align:center;padding:12px 6px;border-radius:14px;background:' + (a.done?'rgba(255,138,0,0.1)':'var(--bg)') + ';border:1.5px solid ' + (a.done?'rgba(255,138,0,0.3)':'var(--border)') + '">' +
          '<div style="font-size:24px;margin-bottom:6px;' + (a.done?'':'filter:grayscale(1);opacity:0.4') + '">' + a.icon + '</div>' +
          '<div style="font-size:10px;font-weight:800;color:' + (a.done?'#FF8A00':'var(--text2)') + ';margin-bottom:2px">' + a.title + '</div>' +
          '<div style="font-size:8.5px;color:var(--text2);line-height:1.3">' + a.desc + '</div>' +
          (a.done ? '<div style="margin-top:5px;font-size:9px;font-weight:800;color:#22C55E">✓ অর্জিত</div>' : '') +
          '</div>';
      }).join('') +
      '</div>';
  }

  var _aslCdTimer = null;
  function renderAslCountdown() {
    var el = document.getElementById('asl-countdown');
    if (!el) return;
    if (_aslCdTimer) { clearInterval(_aslCdTimer); _aslCdTimer = null; }
    var goalH = _aslData.goal || 7.5;
    var bedH = Math.round(((24 + 6 - goalH) % 24));

    function pad(n) { return String(n).padStart(2,'0'); }
    function tick() {
      var el2 = document.getElementById('asl-countdown'); if (!el2) return;
      var today = todayKey();
      var tLog = (_aslData.logs||[]).find(function(l){ return l.date === today; });
      if (tLog && tLog.dur >= goalH * 60) {
        el2.innerHTML = '<div style="background:linear-gradient(135deg,rgba(255,138,0,0.1),rgba(255,184,0,0.05));border-radius:16px;padding:14px 16px;display:flex;align-items:center;gap:12px"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#FF8A00" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg><div><div style="font-size:13px;font-weight:700;color:#FF8A00">আজকের ঘুম লগ করা হয়েছে!</div><div style="font-size:11px;color:var(--text2,#888)">ভালো ঘুমের জন্য শুভকামনা</div></div></div>';
        if (_aslCdTimer) { clearInterval(_aslCdTimer); _aslCdTimer = null; }
        return;
      }
      var now = new Date(), bed = new Date();
      bed.setHours(bedH, 0, 0, 0); if (bed <= now) bed.setDate(bed.getDate()+1);
      var diff = Math.floor((bed - now) / 1000);
      var h = Math.floor(diff/3600), m = Math.floor((diff%3600)/60), s = diff%60;
      var urgency = (h === 0 && m < 30), color = urgency ? '#ef4444' : '#FF8A00';
      el2.innerHTML =
        '<div style="background:linear-gradient(135deg,rgba(255,138,0,0.08),rgba(255,184,0,0.04));border-radius:16px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between">' +
          '<div style="display:flex;align-items:center;gap:10px">' +
            (urgency
              ? '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="'+color+'" stroke-width="2.2" stroke-linecap="round"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>'
              : '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="'+color+'" stroke-width="2" stroke-linecap="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>') +
            '<div>' +
              '<div style="font-size:12px;font-weight:700;color:'+color+'">'+(urgency?'ঘুমানোর সময় হয়ে গেছে!':'ঘুমানোর সময় কাউন্টডাউন')+'</div>' +
              '<div style="font-size:10px;color:var(--text,#1f2937);opacity:.75">রাত '+pad(bedH)+':০০ এ ঘুমানোর লক্ষ্য</div>' +
            '</div>' +
          '</div>' +
          '<div style="text-align:right">' +
            '<div style="font-size:26px;font-weight:800;letter-spacing:0.5px;color:'+color+'">' +
              pad(h)+'<span style="font-size:14px;font-weight:700;color:var(--text,#1f2937);opacity:.85">h</span> ' +
              pad(m)+'<span style="font-size:14px;font-weight:700;color:var(--text,#1f2937);opacity:.85">m</span> ' +
              pad(s)+'<span style="font-size:14px;font-weight:700;color:var(--text,#1f2937);opacity:.85">s</span>' +
            '</div>' +
            '<div style="font-size:9px;color:var(--text,#1f2937);opacity:.75;margin-top:1px">বাকি আছে</div>' +
          '</div>' +
        '</div>';
    }
    tick();
    _aslCdTimer = setInterval(tick, 1000);
  }

  function renderAll() {
    renderHero();
    renderAslCountdown();
    renderScoreCard();
    renderPhasesCard();
    renderChart();
    renderInsights();
    renderAchievements();
  }

  // ── Public API ────────────────────────────────────────────────
  window.rzRenderAdultSleep = function() {
    _aslCache = null;
    var u = window.sbUser || null;
    if(u) {
      aslLoadFromSb().then(function() {
        _aslQuality = 4; _aslTags = [];
        renderLogForm(); loadTodayIntoForm(); renderAll();
      });
    } else {
      loadData();
      _aslQuality = 4; _aslTags = [];
      renderLogForm(); loadTodayIntoForm(); renderAll();
    }
  };

  window.rzAslUpdateDuration = function() {
    var st = document.getElementById('asl-sleep-time');
    var wt = document.getElementById('asl-wake-time');
    if(!st||!wt) return;
    var dur = calcDur(st.value, wt.value);
    var el = document.getElementById('asl-dur-text');
    var badge = document.getElementById('asl-dur-badge');
    if(el) {
      var h = Math.floor(dur/60), m = dur%60;
      el.textContent = h + 'ঘ' + (m>0?' '+m+'মি':'');
    }
    var goal = (_aslData||{}).goal || 7.5;
    var goalMin = goal * 60;
    var color = dur >= goalMin ? '#22C55E' : dur >= goalMin*0.85 ? '#FFB800' : '#EF4444';
    if(el) el.style.color = color;
    if(badge) badge.style.background = 'rgba(' + (dur>=goalMin?'34,197,94':dur>=goalMin*0.85?'234,179,8':'239,68,68') + ',0.12)';
  };

  window.rzAslSetQuality = function(q) {
    _aslQuality = q;
    QUALITY_CFG.forEach(function(c) {
      var btn = document.getElementById('asl-q-' + c.q);
      if(!btn) return;
      var active = c.q === q;
      btn.style.borderColor = active ? c.color : 'var(--border)';
      btn.style.background = active ? 'rgba(' + hexToRgb(c.color) + ',0.12)' : 'transparent';
      btn.querySelector('div:last-child').style.color = active ? c.color : 'var(--text2)';
    });
  };

  window.rzAslToggleTag = function(tagId) {
    var idx = _aslTags.indexOf(tagId);
    if(idx === -1) _aslTags.push(tagId);
    else _aslTags.splice(idx, 1);
    var t = TAGS_CFG.find(function(x){ return x.id===tagId; });
    var btn = document.getElementById('asl-tag-' + tagId);
    if(!btn || !t) return;
    var active = _aslTags.indexOf(tagId) !== -1;
    btn.style.borderColor = active ? t.color : 'var(--border)';
    btn.style.background = active ? 'rgba(' + hexToRgb(t.color) + ',0.12)' : 'transparent';
    btn.style.color = active ? t.color : 'var(--text2)';
  };

  window.rzAslChangeGoal = function(delta) {
    if(!_aslData) loadData();
    _aslData.goal = Math.max(4, Math.min(12, (_aslData.goal||7.5) + delta));
    saveData();
    aslSaveGoalSb(_aslData.goal);
    renderGoal();
    rzAslUpdateDuration();
    renderChart();
    renderInsights();
  };

  window.rzAslSave = function() {
    if(!_aslData) loadData();
    var st = document.getElementById('asl-sleep-time');
    var wt = document.getElementById('asl-wake-time');
    if(!st||!wt) return;
    var dur = calcDur(st.value, wt.value);
    if(dur <= 0) { alert('সময় সঠিকভাবে দিন।'); return; }
    var today = todayKey();
    var existing = (_aslData.logs||[]).findIndex(function(l){ return l.date===today; });
    var log = { date:today, st:st.value, wt:wt.value, dur:dur, q:_aslQuality, tags:_aslTags.slice() };
    if(existing !== -1) _aslData.logs[existing] = log;
    else { _aslData.logs.push(log); if(_aslData.logs.length > 365) _aslData.logs.shift(); }
    saveData();
    aslUpsertLogSb(log);
    renderAll();
    // Success flash
    var btn = document.querySelector('button[onclick="rzAslSave()"]');
    if(btn) {
      var orig = btn.textContent;
      btn.textContent = '✅ সংরক্ষিত হয়েছে!';
      btn.style.background = 'linear-gradient(135deg,#22C55E,#4ADE80)';
      setTimeout(function(){ btn.textContent = orig; btn.style.background = 'linear-gradient(135deg,#FF8A00,#FFB800)'; }, 2000);
    }
  };

})();

// ══════════════════════════════════════════════════════════════
// ADULT STUDY TIMER
// ══════════════════════════════════════════════════════════════
(function() {
  var SK = 'rz_adult_study_v1';
  var TSK = 'rz_ast_timer_state'; // timer state key (separate from data)

  var MODES = {
    focus: { label:'Focus',       dur:25,  color:'#FF8A00', xp:10,  isBreak:false },
    deep:  { label:'Deep Work',   dur:90,  color:'#6366F1', xp:35,  isBreak:false },
    flow:  { label:'Flow',        dur:45,  color:'#8B5CF6', xp:18,  isBreak:false },
    short: { label:'Short Break', dur:5,   color:'#22C55E', xp:0,   isBreak:true  },
    long:  { label:'Long Break',  dur:15,  color:'#3B82F6', xp:0,   isBreak:true  }
  };

  var SUBJECTS = ['Work','Study','Reading','Writing','Coding','Research','Creative','Planning'];

  var BREAKS = [
    'একটু হাঁটো — রক্ত চলাচল বাড়াও, শরীর সতেজ হবে',
    'এক গ্লাস পানি পান করো',
    '৫টা গভীর শ্বাস নাও — ৪ সেকেন্ড নাও, ৪ ধরো, ৬ ছাড়ো',
    'চোখ বন্ধ করো — ২ মিনিট screen ছাড়া বিশ্রাম নাও',
    'ঘাড়, কাঁধ আর পিঠ একটু stretch করো',
    '২০ ফুট দূরে কিছু দেখো ২০ সেকেন্ড — চোখ বিশ্রাম পাবে',
    '১০টা jumping jack করো — শরীর ও মন সতেজ হবে'
  ];

  var CIRCUMFERENCE = 540.35;

  var _data = null;
  var _astCache = null;
  var _T = {
    mode: 'focus', running: false,
    secondsLeft: 25*60, totalSeconds: 25*60,
    subject: 'Work', timer: null,
    customDur: { focus:25, deep:90, flow:45, short:5, long:15 }
  };

  function loadData() {
    if(_astCache) { _data = _astCache; return; }
    try { _data = JSON.parse(localStorage.getItem(SK)) || {}; } catch(e) { _data = {}; }
    if (!_data.logs) _data.logs = [];
    if (!_data.goal) _data.goal = 4;
    if (!_data.totalXP) _data.totalXP = 0;
  }
  function saveData() {
    _astCache = _data;
    try { localStorage.setItem(SK, JSON.stringify(_data)); } catch(e) {}
    astSaveToSb();
  }

  async function astLoadFromSb() {
    var u = window.sbUser || null;
    if(!u) return;
    var res = await window._sb.from('adult_study_data').select('*').eq('user_id', u.id).single();
    if(res.data) {
      _data = { logs: res.data.logs || [], goal: res.data.goal || 4, totalXP: res.data.total_xp || 0 };
    } else {
      _data = _data || { logs: [], goal: 4, totalXP: 0 };
    }
    _astCache = _data;
    try { localStorage.setItem(SK, JSON.stringify(_data)); } catch(e) {}
  }

  async function astSaveToSb() {
    var u = window.sbUser || null;
    if(!u) return;
    await window._sb.from('adult_study_data').upsert({ user_id: u.id, logs: _data.logs || [], goal: _data.goal || 4, total_xp: _data.totalXP || 0, updated_at: new Date().toISOString() }, { onConflict: 'user_id' });
  }

  function saveTimerState() {
    try {
      localStorage.setItem(TSK, JSON.stringify({
        mode:         _T.mode,
        secondsLeft:  _T.secondsLeft,
        totalSeconds: _T.totalSeconds,
        running:      _T.running,
        savedAt:      _T.running ? Date.now() : 0,
        subject:      _T.subject,
        customDur:    _T.customDur
      }));
    } catch(e) {}
  }
  function restoreTimerState() {
    try {
      var raw = localStorage.getItem(TSK); if (!raw) return;
      var s = JSON.parse(raw);
      // Adjust for elapsed time if it was running
      if (s.running && s.savedAt) {
        var elapsed = Math.floor((Date.now() - s.savedAt) / 1000);
        s.secondsLeft = Math.max(0, (s.secondsLeft||0) - elapsed);
        if (s.secondsLeft === 0) { s.running = false; s.finished = true; }
      }
      _T.mode         = s.mode || 'focus';
      _T.secondsLeft  = s.secondsLeft != null ? s.secondsLeft : (MODES[_T.mode].dur*60);
      _T.totalSeconds = s.totalSeconds || (MODES[_T.mode].dur*60);
      _T.subject      = s.subject || 'Work';
      if (s.customDur) _T.customDur = s.customDur;
      if (s.running && !s.finished) {
        // Resume timer
        _T.running = true;
        var icon = document.getElementById('ast-play-icon');
        if (icon) icon.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>';
        _T.timer = setInterval(function() {
          _T.secondsLeft--;
          saveTimerState();
          updateDisplay();
          if (_T.secondsLeft <= 0) {
            clearInterval(_T.timer); _T.timer = null; _T.running = false;
            localStorage.removeItem(TSK);
            var icon2 = document.getElementById('ast-play-icon');
            if (icon2) icon2.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
            onComplete();
          }
        }, 1000);
      } else if (s.finished) {
        localStorage.removeItem(TSK);
        onComplete();
      }
    } catch(e) {}
  }

  function todayStr() {
    var d = new Date();
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  function last14() {
    var r = [];
    for (var i=13; i>=0; i--) {
      var d = new Date(); d.setDate(d.getDate()-i);
      r.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'));
    }
    return r;
  }
  function getDayLog(date) {
    var l = (_data.logs||[]).find(function(x){ return x.date===date; });
    if (!l) { l = {date:date, sessions:[], totalMins:0}; _data.logs.push(l); }
    return l;
  }
  function calcStreak() {
    var streak = 0, d = new Date(), today = todayStr();
    var hasToday = (_data.logs||[]).some(function(l){ return l.date===today && l.sessions && l.sessions.length>=(_data.goal||4); });
    if (!hasToday) d.setDate(d.getDate()-1);
    for (var i=0; i<60; i++) {
      var dk = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
      var l = (_data.logs||[]).find(function(x){ return x.date===dk; });
      if (l && l.sessions && l.sessions.length >= (_data.goal||4)) { streak++; d.setDate(d.getDate()-1); }
      else break;
    }
    return streak;
  }
  function calcScore() {
    var days = last14(), scored = 0;
    days.forEach(function(dk) {
      var l = (_data.logs||[]).find(function(x){ return x.date===dk; });
      if (l && l.sessions && l.sessions.length >= (_data.goal||4)) scored++;
    });
    return Math.round((scored/14)*100);
  }
  function getTodayMins() {
    var today = todayStr();
    var l = (_data.logs||[]).find(function(x){ return x.date===today; });
    return l ? (l.totalMins||0) : 0;
  }
  function getTodaySessions() {
    var today = todayStr();
    var l = (_data.logs||[]).find(function(x){ return x.date===today; });
    return l && l.sessions ? l.sessions.length : 0;
  }
  function get7DayAvgMins() {
    var days = last14().slice(7);
    var total = 0, count = 0;
    days.forEach(function(dk) {
      var l = (_data.logs||[]).find(function(x){ return x.date===dk; });
      if (l && l.totalMins) { total += l.totalMins; count++; }
    });
    return count ? Math.round(total/count) : 0;
  }
  function getBestDayMins() {
    var best = 0;
    (_data.logs||[]).forEach(function(l){ if((l.totalMins||0)>best) best=l.totalMins; });
    return best;
  }
  function fmtMins(mins) {
    if (!mins) return '—';
    var h = Math.floor(mins/60), m = mins%60;
    return h>0 ? h+'h '+(m>0?m+'m':'') : m+'m';
  }
  function playBell() {
    try {
      var ctx = new (window.AudioContext||window.webkitAudioContext)();
      var osc = ctx.createOscillator(), g = ctx.createGain();
      osc.connect(g); g.connect(ctx.destination);
      osc.type='sine'; osc.frequency.value=880;
      g.gain.setValueAtTime(0.4,ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+1.5);
      osc.start(ctx.currentTime); osc.stop(ctx.currentTime+1.5);
    } catch(e) {}
  }

  // ── Display update ────────────────────────────────────────────
  function updateDisplay() {
    var m = Math.floor(_T.secondsLeft/60), s = _T.secondsLeft%60;
    var tel = document.getElementById('ast-time');
    if (tel) tel.textContent = (m<10?'0':'')+m+':'+(s<10?'0':'')+s;
    var c = document.getElementById('ast-circle');
    var mCfg = MODES[_T.mode];
    var pct = _T.totalSeconds > 0 ? _T.secondsLeft/_T.totalSeconds : 0;
    if (c) {
      c.setAttribute('stroke-dashoffset', CIRCUMFERENCE*(1-pct));
      // Update gradient colors based on mode
      if (_T.mode === 'deep') c.setAttribute('stroke','#6366F1');
      else if (_T.mode === 'flow') c.setAttribute('stroke','#8B5CF6');
      else if (_T.mode === 'short') c.setAttribute('stroke','#22C55E');
      else if (_T.mode === 'long') c.setAttribute('stroke','#3B82F6');
      else c.setAttribute('stroke','url(#astTimerGrad)');
    }
    var lbl = document.getElementById('ast-label');
    if (lbl) lbl.textContent = mCfg.label;
    var xpEl = document.getElementById('ast-xp-earn');
    if (xpEl) xpEl.textContent = mCfg.xp > 0 ? '+'+mCfg.xp+' XP' : 'Rest & Recover';
  }

  // ── Mode switch ───────────────────────────────────────────────
  function applyModeStyles(m) {
    ['focus','deep','flow','short','long'].forEach(function(k) {
      var btn = document.getElementById('ast-mode-'+k);
      if (!btn) return;
      btn.style.background = k===m ? MODES[k].color : 'var(--bg,#f9fafb)';
      btn.style.color = k===m ? '#fff' : 'var(--text2,#888)';
    });
    var tip = document.getElementById('ast-break-tip');
    if (tip) {
      if (MODES[m].isBreak) {
        tip.style.display = 'block';
        var bt = document.getElementById('ast-break-text');
        if (bt) bt.textContent = BREAKS[Math.floor(Math.random()*BREAKS.length)];
      } else {
        tip.style.display = 'none';
      }
    }
  }

  function setMode(m) {
    if (_T.running) return;
    _T.mode = m;
    _T.secondsLeft = (_T.customDur[m]||MODES[m].dur)*60;
    _T.totalSeconds = _T.secondsLeft;
    applyModeStyles(m);
    updateDisplay();
    saveTimerState(); // save after full reset
  }

  // ── Timer controls ────────────────────────────────────────────
  function toggle() {
    var icon = document.getElementById('ast-play-icon');
    if (_T.running) {
      clearInterval(_T.timer); _T.timer = null; _T.running = false;
      saveTimerState();
      if (icon) icon.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
    } else {
      _T.running = true;
      saveTimerState();
      if (icon) icon.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>';
      _T.timer = setInterval(function() {
        _T.secondsLeft--;
        updateDisplay();
        if (_T.secondsLeft % 5 === 0) saveTimerState(); // save every 5s
        if (_T.secondsLeft <= 0) {
          clearInterval(_T.timer); _T.timer = null; _T.running = false;
          localStorage.removeItem(TSK);
          var icon2 = document.getElementById('ast-play-icon');
          if (icon2) icon2.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
          onComplete();
        }
      }, 1000);
    }
  }
  function reset() {
    clearInterval(_T.timer); _T.timer = null; _T.running = false;
    _T.secondsLeft = (_T.customDur[_T.mode]||MODES[_T.mode].dur)*60;
    _T.totalSeconds = _T.secondsLeft;
    localStorage.removeItem(TSK);
    var icon = document.getElementById('ast-play-icon');
    if (icon) icon.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
    updateDisplay();
  }
  function skip() {
    clearInterval(_T.timer); _T.timer = null; _T.running = false;
    localStorage.removeItem(TSK);
    _T.secondsLeft = 0; onComplete();
  }

  // ── Session complete ──────────────────────────────────────────
  function onComplete() {
    playBell();
    var mCfg = MODES[_T.mode];
    if (!mCfg.isBreak) {
      var today = todayStr();
      var dayLog = getDayLog(today);
      var subjectEl = document.getElementById('ast-subject-input');
      var noteEl = document.getElementById('ast-session-note');
      var subject = (subjectEl && subjectEl.value.trim()) || _T.subject;
      var note = noteEl ? noteEl.value.trim() : '';
      dayLog.sessions.push({ mode:_T.mode, subject:subject, note:note, mins:_T.customDur[_T.mode]||mCfg.dur, ts: Date.now() });
      dayLog.totalMins = (dayLog.totalMins||0) + (_T.customDur[_T.mode]||mCfg.dur);
      _data.totalXP = (_data.totalXP||0) + mCfg.xp;
      if (noteEl) noteEl.value = '';
      saveData();
      renderHero(); renderStats(); renderHeatmap(); renderGoal(); renderInsight();
      showCompletionBanner(mCfg);
    }
    // Auto-switch to break
    if (_T.mode==='focus') setMode('short');
    else if (_T.mode==='deep'||_T.mode==='flow') setMode('long');
    else setMode('focus');
  }
  function showCompletionBanner(mCfg) {
    var el = document.getElementById('ast-hero-card');
    if (!el) return;
    var flash = document.createElement('div');
    flash.style.cssText = 'position:fixed;top:80px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,'+mCfg.color+',#FFB800);color:#fff;padding:12px 24px;border-radius:50px;font-size:13px;font-weight:700;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,.2);pointer-events:none';
    flash.textContent = '✓ '+mCfg.label+' complete! +'+mCfg.xp+' XP';
    document.body.appendChild(flash);
    setTimeout(function(){ if (flash.parentNode) flash.parentNode.removeChild(flash); }, 3000);
  }

  // ── Render hero ───────────────────────────────────────────────
  function renderHero() {
    var todayMins = getTodayMins();
    var todaySess = getTodaySessions();
    var streak = calcStreak();
    var score = calcScore();
    var goal = _data.goal || 4;

    var ht = document.getElementById('ast-hero-time');
    if (ht) ht.textContent = todayMins > 0 ? fmtMins(todayMins) : '—';
    var hs = document.getElementById('ast-hero-sub');
    if (hs) hs.textContent = todaySess > 0 ? todaySess+' session'+(todaySess>1?'s':'')+' completed today' : 'Start your first session';
    var hss = document.getElementById('ast-hero-sessions');
    if (hss) hss.textContent = todaySess;
    var hst = document.getElementById('ast-hero-streak');
    if (hst) hst.textContent = streak;
    var hg = document.getElementById('ast-hero-goal');
    if (hg) {
      hg.textContent = todaySess+'/'+goal;
      hg.style.color = todaySess >= goal ? '#22C55E' : '#FF8A00';
    }
    // Score ring
    var ring = document.getElementById('ast-score-ring');
    var snum = document.getElementById('ast-score-num');
    var circumference = 213.6;
    if (ring) {
      var offset = circumference - (score/100)*circumference;
      setTimeout(function(){ ring.style.strokeDashoffset = offset; }, 100);
      var col = score>=80?'#22C55E':score>=60?'#FFB800':score>=40?'#FF8A00':'#EF4444';
      ring.style.stroke = score ? col : 'rgba(255,255,255,0.08)';
    }
    if (snum) { snum.textContent = score||'—'; }
  }

  // ── Render goal bar ───────────────────────────────────────────
  function renderGoal() {
    var goal = _data.goal || 4;
    var done = getTodaySessions();
    var pct = Math.min(100, Math.round((done/goal)*100));
    var bar = document.getElementById('ast-goal-bar');
    var txt = document.getElementById('ast-goal-text');
    var disp = document.getElementById('ast-goal-display');
    if (bar) bar.style.width = pct+'%';
    if (txt) txt.textContent = done+' / '+goal+' sessions done';
    if (disp) disp.textContent = goal+' session'+(goal>1?'s':'');
  }

  // ── Render stats ──────────────────────────────────────────────
  function renderStats() {
    var el = document.getElementById('ast-stats'); if (!el) return;
    var todayMins = getTodayMins();
    var avg = get7DayAvgMins();
    var best = getBestDayMins();
    var stats = [
      { icon:'⏱', label:'Today', value: fmtMins(todayMins), color:'#FF8A00' },
      { icon:'📊', label:'7-Day Avg', value: fmtMins(avg), color:'#FFB800' },
      { icon:'🏆', label:'Best Day', value: fmtMins(best), color:'#6366F1' }
    ];
    el.innerHTML = stats.map(function(s) {
      return '<div style="background:var(--card,#fff);border-radius:14px;padding:12px 10px;text-align:center;border:1.5px solid var(--border,#e5e7eb)">'+
        '<div style="font-size:18px;margin-bottom:4px">'+s.icon+'</div>'+
        '<div style="font-size:16px;font-weight:800;color:'+s.color+';line-height:1">'+s.value+'</div>'+
        '<div style="font-size:10px;color:var(--text2,#888);margin-top:3px">'+s.label+'</div>'+
        '</div>';
    }).join('');
  }

  // ── Render 14-day heatmap ─────────────────────────────────────
  function renderHeatmap() {
    var el = document.getElementById('ast-heatmap'); if (!el) return;
    var days = last14();
    var maxMins = 0;
    days.forEach(function(dk) {
      var l = (_data.logs||[]).find(function(x){ return x.date===dk; });
      if (l && (l.totalMins||0) > maxMins) maxMins = l.totalMins;
    });
    if (maxMins < 1) maxMins = 60;
    el.innerHTML = days.map(function(dk) {
      var l = (_data.logs||[]).find(function(x){ return x.date===dk; });
      var mins = l ? (l.totalMins||0) : 0;
      var pct = mins/maxMins;
      var bg, title;
      if (mins === 0) { bg='var(--border,#e5e7eb)'; }
      else if (pct < 0.33) { bg='rgba(255,138,0,0.3)'; }
      else if (pct < 0.66) { bg='rgba(255,138,0,0.6)'; }
      else { bg='#FF8A00'; }
      title = dk+': '+(mins?fmtMins(mins):'No focus');
      return '<div title="'+title+'" style="aspect-ratio:1;border-radius:4px;background:'+bg+';cursor:default"></div>';
    }).join('');
  }

  // ── Render insight ────────────────────────────────────────────
  function renderInsight() {
    var el = document.getElementById('ast-insight'); if (!el) return;
    var today = getTodayMins(), avg = get7DayAvgMins(), streak = calcStreak(), sessions = getTodaySessions(), goal = _data.goal||4;
    var msg, color = '#FF8A00', icon = '⚡';
    if (sessions === 0) { msg='Start your first session today — even 25 minutes builds momentum.'; }
    else if (sessions >= goal) { msg='Goal crushed! 🎯 You hit '+sessions+' sessions today. Consistency is your superpower.'; icon='🎯'; color='#22C55E'; }
    else if (today > avg*1.2 && avg>0) { msg='You\'re '+Math.round(((today/avg)-1)*100)+'% above your 7-day average — great focus day!'; icon='🚀'; color='#6366F1'; }
    else if (streak >= 5) { msg=streak+'-day focus streak! You\'re building a serious habit.'; icon='🔥'; color='#EF4444'; }
    else { msg='Keep going! '+sessions+' session'+(sessions>1?'s':'')+' done, '+(goal-sessions)+' to go for your daily goal.'; }
    el.innerHTML = '<div style="background:linear-gradient(135deg,rgba(255,138,0,0.08),rgba(255,184,0,0.04));border-radius:16px;padding:14px 16px;border-left:3px solid '+color+'">'+
      '<div style="font-size:18px;margin-bottom:4px">'+icon+'</div>'+
      '<div style="font-size:12px;font-weight:700;color:'+color+';margin-bottom:3px">Today\'s Insight</div>'+
      '<div style="font-size:13px;color:var(--text,#1f2937);line-height:1.5">'+msg+'</div>'+
      '</div>';
  }

  // ── Render subject chips ──────────────────────────────────────
  function renderSubjectChips() {
    var el = document.getElementById('ast-subj-chips'); if (!el) return;
    el.innerHTML = SUBJECTS.map(function(s) {
      var active = s===_T.subject;
      return '<button onclick="rzAstSetSubject(\''+s+'\')" style="padding:5px 12px;border-radius:50px;font-size:11px;font-weight:700;font-family:inherit;cursor:pointer;border:1.5px solid '+(active?'#FF8A00':'var(--border,#e5e7eb)')+';background:'+(active?'rgba(255,138,0,.12)':'transparent')+';color:'+(active?'#FF8A00':'var(--text2,#888)')+'">'+s+'</button>';
    }).join('');
  }

  function renderAll() {
    renderHero();
    renderGoal();
    renderStats();
    renderHeatmap();
    renderInsight();
    renderSubjectChips();
    // Restore dur displays
    ['focus','deep','flow','short','long'].forEach(function(k){
      var el=document.getElementById('ast-dur-'+k);
      if(el) el.textContent=_T.customDur[k]||MODES[k].dur;
    });
    // Only update styles — do NOT reset secondsLeft/totalSeconds here
    applyModeStyles(_T.mode);
    updateDisplay();
  }

  // ── Public API ────────────────────────────────────────────────
  window.rzRenderAdultStudy = function() {
    _astCache = null;
    var u = window.sbUser || null;
    var doRender = function() {
      // Stop any existing interval first
      if (_T.timer) { clearInterval(_T.timer); _T.timer = null; _T.running = false; }
      // Restore persisted timer state into _T BEFORE renderAll reads _T
      (function() {
        try {
          var raw = localStorage.getItem(TSK); if (!raw) return;
          var s = JSON.parse(raw);
          if (s.running && s.savedAt) {
            var elapsed = Math.floor((Date.now() - s.savedAt) / 1000);
            s.secondsLeft = Math.max(0, (s.secondsLeft||0) - elapsed);
            if (s.secondsLeft === 0) { s.running = false; s.finished = true; }
          }
          _T.mode         = s.mode || _T.mode;
          _T.secondsLeft  = s.secondsLeft != null ? s.secondsLeft : _T.secondsLeft;
          _T.totalSeconds = s.totalSeconds || _T.totalSeconds;
          _T.subject      = s.subject || _T.subject;
          if (s.customDur) _T.customDur = s.customDur;
          _T._pendingResume = s.running && !s.finished;
          if (s.finished) { localStorage.removeItem(TSK); _T._pendingFinish = true; }
        } catch(e) {}
      })();
      renderAll();
      // Now start interval if was running, or fire complete if finished
      if (_T._pendingResume) {
        _T._pendingResume = false;
        _T.running = true;
        var icon = document.getElementById('ast-play-icon');
        if (icon) icon.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>';
        _T.timer = setInterval(function() {
          _T.secondsLeft--;
          updateDisplay();
          if (_T.secondsLeft % 5 === 0) saveTimerState();
          if (_T.secondsLeft <= 0) {
            clearInterval(_T.timer); _T.timer = null; _T.running = false;
            localStorage.removeItem(TSK);
            var icon2 = document.getElementById('ast-play-icon');
            if (icon2) icon2.outerHTML = '<svg id="ast-play-icon" viewBox="0 0 24 24" width="28" height="28" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
            onComplete();
          }
        }, 1000);
      } else if (_T._pendingFinish) {
        _T._pendingFinish = false;
        onComplete();
      }
    };
    if(u) { astLoadFromSb().then(doRender); } else { loadData(); doRender(); }
  };

  // Save timer on tab hide / page unload
  document.addEventListener('visibilitychange', function() {
    if (document.hidden && _T.running) saveTimerState();
  });
  window.addEventListener('beforeunload', function() {
    if (_T.running) saveTimerState();
  });
  window.rzAstSetMode = function(m) { setMode(m); };
  window.rzAstToggle = function() { toggle(); };
  window.rzAstReset = function() { reset(); };
  window.rzAstSkip = function() { skip(); };
  window.rzAstSetSubject = function(s) {
    _T.subject = s;
    var inp = document.getElementById('ast-subject-input'); if(inp) inp.value='';
    renderSubjectChips();
  };
  window.rzAstClearChips = function() {
    _T.subject = '';
    renderSubjectChips();
  };
  window.rzAstChangeGoal = function(d) {
    _data.goal = Math.max(1, Math.min(12, (_data.goal||4)+d));
    saveData(); renderGoal(); renderHero();
  };
  window.rzAstChangeDur = function(m, d) {
    var min = (m==='short')?1:5;
    var max = (m==='deep')?180:(m==='flow'||m==='focus')?90:30;
    _T.customDur[m] = Math.max(min, Math.min(max, (_T.customDur[m]||MODES[m].dur)+d));
    var el = document.getElementById('ast-dur-'+m); if(el) el.textContent=_T.customDur[m];
    if (m===_T.mode && !_T.running) {
      _T.secondsLeft=_T.customDur[m]*60; _T.totalSeconds=_T.secondsLeft; updateDisplay();
    }
  };
})();

// ── 5/5 Celebration ───────────────────────────────────────────
function rzNamazAdultCelebrate() {
  if(document.getElementById('rz-anz-confetti')) return;
  var s = document.createElement('style'); s.id='rz-anz-confstyle';
  s.textContent = '@keyframes rzAnzFall{0%{transform:translateY(0) rotate(0deg) scale(1);opacity:1}100%{transform:translateY(115vh) rotate(720deg) scale(.5);opacity:0}}';
  document.head.appendChild(s);
  var overlay = document.createElement('div');
  overlay.id = 'rz-anz-confetti';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;pointer-events:none;overflow:hidden';
  var emojis = ['🕌','🌙','⭐','✨','🤲','📿','💫','🌟','☪️'];
  var html2 = '';
  for(var i2=0;i2<30;i2++) {
    var left2 = Math.round(Math.random()*100);
    var delay2 = (Math.random()*1.8).toFixed(2);
    var dur2 = (2.5+Math.random()*2).toFixed(2);
    html2 += '<div style="position:absolute;left:'+left2+'%;top:-40px;font-size:22px;animation:rzAnzFall '+dur2+'s '+delay2+'s ease-in forwards">'+emojis[i2%emojis.length]+'</div>';
  }
  overlay.innerHTML = html2;
  document.body.appendChild(overlay);
  setTimeout(function(){ if(overlay.parentNode) overlay.parentNode.removeChild(overlay); if(s.parentNode) s.parentNode.removeChild(s); },6000);
}

// ── 5/5 Celebration ───────────────────────────────────────────
function rzNamazCelebrate() {
  if (document.getElementById('rz-namaz-confetti')) return;
  if (!document.getElementById('rz-confetti-style')) {
    var s = document.createElement('style'); s.id = 'rz-confetti-style';
    s.textContent = '@keyframes rzFall{0%{transform:translateY(0) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}';
    document.head.appendChild(s);
  }
  var overlay = document.createElement('div');
  overlay.id  = 'rz-namaz-confetti';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;pointer-events:none;overflow:hidden';
  var emojis = ['🌙','⭐','✨','🕌','🤲','📿','💫','🌟'];
  var html = '';
  for (var i = 0; i < 24; i++) {
    var left  = Math.floor(Math.random() * 100);
    var delay = (Math.random() * 1.5).toFixed(2);
    var dur   = (2 + Math.random() * 2).toFixed(2);
    html += '<div style="position:absolute;left:' + left + '%;top:-40px;font-size:22px;animation:rzFall ' + dur + 's ' + delay + 's ease-in forwards">' + emojis[i % emojis.length] + '</div>';
  }
  overlay.innerHTML = html;
  document.body.appendChild(overlay);
  if (typeof cmToast === 'function') cmToast('আলহামদুলিল্লাহ! সব ৫ ওয়াক্ত সম্পন্ন!');
  setTimeout(function() { if (overlay.parentNode) overlay.parentNode.removeChild(overlay); }, 5500);
}


