window.rzQuranProgress   = {};
window.rzQuranActiveFilter = 'juz';
var _rzCurrentSurah = null;

// ── Page Init ─────────────────────────────────────────────────
async function rzQuranPageLoad() {
  window.rzQuranProgress = {};
  rzRenderQuranKidTabs();
  await rzLoadQuranProgress();
  rzRenderQuranStats();
  rzRenderTodaySurah();
  rzRenderQuranGrid();
  rzRenderMilestones();
}

// ── Kid Tabs ─────────────────────────────────────────────────
function rzRenderQuranKidTabs() {
  var el = document.getElementById('quran-kid-tabs');
  if (!el) return;
  var kids = window.rzKids || [];
  if (!kids.length) { el.innerHTML = ''; return; }
  if (!window.rzActiveKid) window.rzActiveKid = kids[0];
  el.innerHTML = kids.map(function(k) {
    var active = window.rzActiveKid && window.rzActiveKid.id === k.id;
    return '<button onclick="rzQuranSwitchKid(\'' + k.id + '\')" style="padding:5px 14px;border-radius:20px;border:1.5px solid ' + (active ? '#FF8A00' : 'var(--border,#e5e7eb)') + ';background:' + (active ? 'rgba(255,138,0,0.1)' : 'transparent') + ';color:' + (active ? '#FF8A00' : 'var(--text2,#888)') + ';font-size:12px;font-weight:' + (active ? '700' : '500') + ';cursor:pointer;font-family:inherit;white-space:nowrap">' + k.name + '</button>';
  }).join('');
}

async function rzQuranSwitchKid(kidId) {
  var k = (window.rzKids || []).find(function(x){ return x.id === kidId; });
  if (!k) return;
  window.rzActiveKid = k;
  rzRenderQuranKidTabs();
  await rzLoadQuranProgress();
  rzRenderQuranStats();
  rzRenderTodaySurah();
  rzRenderQuranGrid();
  rzRenderMilestones();
}

// ── Load from DB ──────────────────────────────────────────────
async function rzLoadQuranProgress() {
  if (!window._sb || !window.rzActiveKid) {
    window.rzQuranProgress = {};
    return;
  }
  try {
    var res = await _sb.from('quran_progress').select('*')
      .eq('kid_id', window.rzActiveKid.id);
    window.rzQuranProgress = {};
    (res.data || []).forEach(function(r) {
      window.rzQuranProgress[r.surah_no] = { status: r.status, stars: r.stars };
    });
  } catch(e) {
    console.warn('rzLoadQuranProgress:', e.message || e);
    window.rzQuranProgress = {};
  }
}

// ── Render Stats ──────────────────────────────────────────────
function rzRenderQuranStats() {
  var total = RZ_SURAHS.length;
  var memorized = 0;
  RZ_SURAHS.forEach(function(s) {
    var p = window.rzQuranProgress[s.no];
    if (p && p.status === 2) memorized++;
  });
  var pct = total > 0 ? Math.round(memorized / total * 100) : 0;
  var cntEl = document.getElementById('q-memorized-count');
  var pctEl = document.getElementById('q-pct');
  var barEl = document.getElementById('q-bar');
  if (cntEl) cntEl.textContent = rzToBn(memorized) + '/' + rzToBn(total);
  if (pctEl) pctEl.textContent = rzToBn(pct) + '%';
  if (barEl) { setTimeout(function(){ barEl.style.width = pct + '%'; }, 50); }
}

// ── Today's Surah Suggestion ──────────────────────────────────
function rzRenderTodaySurah() {
  var el = document.getElementById('q-today-surah');
  if (!el) return;

  var suggestion = null;
  for (var i = 0; i < RZ_SURAHS.length; i++) {
    var s = RZ_SURAHS[i];
    var p = window.rzQuranProgress[s.no];
    if (p && p.status === 1) { suggestion = s; break; }
  }
  if (!suggestion) {
    for (var j = 0; j < RZ_SURAHS.length; j++) {
      var s2 = RZ_SURAHS[j];
      var p2 = window.rzQuranProgress[s2.no];
      if (!p2 || p2.status === 0) { suggestion = s2; break; }
    }
  }
  if (!suggestion) { el.innerHTML = ''; return; }

  var p3 = window.rzQuranProgress[suggestion.no] || {};
  var label = p3.status === 1 ? 'চালিয়ে যাও' : 'শুরু করো';
  var labelColor = p3.status === 1 ? '#FF8A00' : '#22c55e';

  el.innerHTML =
    '<div onclick="rzOpenSurahModal(' + suggestion.no + ')" style="background:linear-gradient(135deg,rgba(255,184,0,0.15),rgba(255,138,0,0.08));border:1.5px solid rgba(255,184,0,0.4);border-radius:14px;padding:14px 16px;cursor:pointer">' +
      '<div style="display:flex;align-items:center;justify-content:space-between">' +
        '<div>' +
          '<div style="font-size:10px;font-weight:700;color:#FFB800;letter-spacing:.5px;margin-bottom:4px">আজকের সুরা</div>' +
          '<div style="font-size:16px;font-weight:800;color:var(--text,#1f2937)">' + suggestion.name + '</div>' +
          '<div style="font-size:11px;color:var(--text2,#888);margin-top:2px">' + suggestion.meaning + ' - ' + rzToBn(suggestion.ayat) + ' আয়াত</div>' +
        '</div>' +
        '<div style="text-align:right">' +
          '<div style="font-size:20px;direction:rtl;color:#FFB800;font-family:serif;margin-bottom:4px">' + suggestion.arabic + '</div>' +
          '<div style="font-size:11px;font-weight:700;color:' + labelColor + ';background:rgba(255,255,255,0.5);padding:2px 10px;border-radius:10px">' + label + '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
}

// ── Category Filter ───────────────────────────────────────────
function rzQuranFilter(cat) {
  window.rzQuranActiveFilter = cat;
  var juzBtn = document.getElementById('q-cat-juz');
  var allBtn = document.getElementById('q-cat-all');
  if (juzBtn) {
    juzBtn.style.border     = cat === 'juz' ? '1.5px solid #FF8A00' : '1.5px solid var(--border,#e5e7eb)';
    juzBtn.style.background = cat === 'juz' ? 'rgba(255,138,0,0.1)' : 'transparent';
    juzBtn.style.color      = cat === 'juz' ? '#FF8A00' : 'var(--text2,#888)';
    juzBtn.style.fontWeight = cat === 'juz' ? '700' : '600';
  }
  if (allBtn) {
    allBtn.style.border     = cat === 'all' ? '1.5px solid #FF8A00' : '1.5px solid var(--border,#e5e7eb)';
    allBtn.style.background = cat === 'all' ? 'rgba(255,138,0,0.1)' : 'transparent';
    allBtn.style.color      = cat === 'all' ? '#FF8A00' : 'var(--text2,#888)';
    allBtn.style.fontWeight = cat === 'all' ? '700' : '600';
  }
  rzRenderQuranGrid();
}

// ── Render Surah Grid ─────────────────────────────────────────
function rzRenderQuranGrid() {
  var grid = document.getElementById('quran-grid');
  if (!grid) return;
  var filter = window.rzQuranActiveFilter || 'juz';
  var list = RZ_SURAHS.filter(function(s) {
    if (filter === 'juz') return s.juz30 || s.no === 1;
    return true;
  });

  grid.innerHTML = list.map(function(s) {
    var p      = window.rzQuranProgress[s.no] || { status: 0, stars: 0 };
    var status = p.status || 0;
    var stars  = p.stars  || 0;

    var borderColor = status === 2 ? '#22c55e' : status === 1 ? '#FF8A00' : 'var(--border,#e5e7eb)';
    var bgColor     = status === 2 ? 'rgba(34,197,94,0.07)' : status === 1 ? 'rgba(255,138,0,0.07)' : 'var(--card,#fff)';
    var arabicColor = status === 2 ? '#22c55e' : status === 1 ? '#FF8A00' : 'var(--text2,#aaa)';
    var statusLabel = status === 2 ? 'মুখস্থ' : status === 1 ? 'শিখছি' : 'শেখা হয়নি';
    var statusBg    = status === 2 ? 'rgba(34,197,94,0.12)' : status === 1 ? 'rgba(255,138,0,0.12)' : 'var(--bg,#f3f4f6)';
    var statusColor = status === 2 ? '#16a34a' : status === 1 ? '#ea6500' : 'var(--text2,#aaa)';

    var starsHtml = '';
    for (var i = 1; i <= 3; i++) {
      starsHtml += '<svg viewBox="0 0 24 24" width="11" height="11" fill="' + (i <= stars ? '#FFB800' : 'none') + '" stroke="#FFB800" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>';
    }

    return '<div onclick="rzOpenSurahModal(' + s.no + ')" style="background:' + bgColor + ';border:1.5px solid ' + borderColor + ';border-radius:14px;padding:12px 10px;cursor:pointer;transition:.2s">' +
      '<div style="font-size:14px;direction:rtl;color:' + arabicColor + ';font-family:serif;text-align:right;margin-bottom:4px;line-height:1.2">' + s.arabic + '</div>' +
      '<div style="font-size:13px;font-weight:800;color:var(--text,#1f2937);margin-bottom:2px">' + s.name + '</div>' +
      '<div style="font-size:10px;color:var(--text2,#888);margin-bottom:7px">' + rzToBn(s.ayat) + ' আয়াত</div>' +
      '<div style="display:flex;align-items:center;justify-content:space-between">' +
        '<div style="display:flex;gap:1px;align-items:center">' + starsHtml + '</div>' +
        '<div style="font-size:9px;font-weight:700;color:' + statusColor + ';background:' + statusBg + ';padding:2px 6px;border-radius:8px">' + statusLabel + '</div>' +
      '</div>' +
    '</div>';
  }).join('');
}

// ── Milestones ────────────────────────────────────────────────
function rzRenderMilestones() {
  var el = document.getElementById('q-milestones');
  if (!el) return;
  var memorized = 0;
  RZ_SURAHS.forEach(function(s) {
    var p = window.rzQuranProgress[s.no];
    if (p && p.status === 2) memorized++;
  });
  var milestones = [
    { target: 5,  icon: 'star',   label: 'প্রথম পদক্ষেপ',   sub: '৫ সুরা মুখস্থ'  },
    { target: 10, icon: 'trophy', label: 'কুরআনের বন্ধু',    sub: '১০ সুরা মুখস্থ' },
    { target: 20, icon: 'crown',  label: 'জুজ আম্মা হাফেজ', sub: '২০ সুরা মুখস্থ' }
  ];
  var iconSvg = {
    star:  '<svg viewBox="0 0 24 24" width="24" height="24" fill="FILL" stroke="#FFB800" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>',
    trophy:'<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="STROKE" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 9a6 6 0 0 0 12 0"/><line x1="12" y1="15" x2="12" y2="22"/><line x1="8" y1="22" x2="16" y2="22"/><path d="M18 2c0 0 4 1 4 5H2c0-4 4-5 4-5"/></svg>',
    crown: '<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="STROKE" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M2 20h20M5 20L2 8l5 4 5-8 5 8 5-4-3 12"/></svg>'
  };

  el.innerHTML =
    '<div style="font-size:13px;font-weight:700;color:var(--text,#1f2937);margin-bottom:12px">অর্জন ও পুরস্কার</div>' +
    '<div style="display:flex;gap:8px">' +
      milestones.map(function(m) {
        var done = memorized >= m.target;
        var iconHtml = iconSvg[m.icon]
          .replace('FILL', done ? '#FFB800' : 'none')
          .replace('STROKE', done ? '#FFB800' : 'var(--border,#ccc)');
        return '<div style="flex:1;text-align:center;padding:12px 4px;border-radius:12px;background:' + (done ? 'rgba(255,184,0,0.1)' : 'var(--bg,#f3f4f6)') + ';border:1.5px solid ' + (done ? '#FFB800' : 'var(--border,#e5e7eb)') + '">' +
          '<div style="display:flex;justify-content:center;filter:' + (done ? 'none' : 'opacity(.3)') + '">' + iconHtml + '</div>' +
          '<div style="font-size:10px;font-weight:700;color:' + (done ? '#d97706' : 'var(--text2,#aaa)') + ';margin-top:6px">' + m.label + '</div>' +
          '<div style="font-size:9px;color:var(--text2,#bbb);margin-top:1px">' + m.sub + '</div>' +
        '</div>';
      }).join('') +
    '</div>';
}

// ── Surah Detail Modal ────────────────────────────────────────
function rzOpenSurahModal(surahNo) {
  var s = RZ_SURAHS.find(function(x){ return x.no === surahNo; });
  if (!s) return;
  _rzCurrentSurah = surahNo;
  rzCloseSurahModal();

  var p      = window.rzQuranProgress[surahNo] || { status: 0, stars: 0 };
  var status = p.status || 0;
  var stars  = p.stars  || 0;

  var starLabels = ['মোটামুটি','ভালো','পারফেক্ট'];
  var starsHtml = '';
  for (var i = 1; i <= 3; i++) {
    starsHtml +=
      '<button onclick="rzSetSurahStars(' + surahNo + ',' + i + ');event.stopPropagation()" style="display:flex;flex-direction:column;align-items:center;gap:3px;padding:8px 0;border-radius:12px;border:1.5px solid ' + (stars >= i ? '#FFB800' : 'var(--border,#e5e7eb)') + ';background:' + (stars >= i ? 'rgba(255,184,0,0.1)' : 'transparent') + ';cursor:pointer;font-family:inherit;flex:1">' +
        '<svg viewBox="0 0 24 24" width="18" height="18" fill="' + (stars >= i ? '#FFB800' : 'none') + '" stroke="#FFB800" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>' +
        '<span style="font-size:10px;color:var(--text2,#888)">' + starLabels[i-1] + '</span>' +
      '</button>';
  }

  var statusBtns = [
    { st:2, label:'মুখস্থ করেছি', icon:'check-circle', color:'#22c55e', bg:'rgba(34,197,94,0.1)', border:'rgba(34,197,94,0.4)' },
    { st:1, label:'শিখছি এখনো',   icon:'book-open',    color:'#FF8A00', bg:'rgba(255,138,0,0.1)',  border:'rgba(255,138,0,0.4)' },
    { st:0, label:'শুরু করিনি',    icon:'circle',       color:'var(--text2,#888)', bg:'var(--bg,#f3f4f6)', border:'var(--border,#e5e7eb)' }
  ].map(function(b) {
    var active = status === b.st;
    return '<button onclick="rzSetSurahStatus(' + surahNo + ',' + b.st + ');event.stopPropagation()" style="width:100%;padding:11px 14px;border-radius:12px;border:1.5px solid ' + (active ? b.border : 'var(--border,#e5e7eb)') + ';background:' + (active ? b.bg : 'transparent') + ';color:' + b.color + ';font-size:13px;font-weight:' + (active ? '700' : '500') + ';cursor:pointer;font-family:inherit;text-align:left;display:flex;align-items:center;gap:8px">' +
      (active ? '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>' : '<span style="width:15px"></span>') +
      b.label + '</button>';
  }).join('');

  var overlay = document.createElement('div');
  overlay.id  = 'rz-surah-modal-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9998;background:rgba(0,0,0,.45);display:flex;align-items:flex-end;justify-content:center';
  overlay.onclick = function(e){ if(e.target === overlay) rzCloseSurahModal(); };

  overlay.innerHTML =
    '<div style="background:var(--card,#fff);border-radius:20px 20px 0 0;padding:16px 20px 36px;width:100%;max-width:460px;max-height:88vh;overflow-y:auto" onclick="event.stopPropagation()">' +
      '<div style="width:36px;height:4px;background:var(--border,#e5e7eb);border-radius:4px;margin:0 auto 18px;cursor:pointer" onclick="rzCloseSurahModal()"></div>' +
      '<div style="text-align:center;margin-bottom:20px">' +
        '<div style="font-size:36px;direction:rtl;color:#FF8A00;font-family:serif;margin-bottom:6px;line-height:1.3">' + s.arabic + '</div>' +
        '<div style="font-size:20px;font-weight:800;color:var(--text,#1f2937)">' + s.name + '</div>' +
        '<div style="font-size:12px;color:var(--text2,#888);margin-top:4px">' + s.meaning + ' &bull; ' + rzToBn(s.ayat) + ' আয়াত</div>' +
      '</div>' +
      '<div style="margin-bottom:16px">' +
        '<div style="font-size:11px;font-weight:700;color:var(--text2,#888);margin-bottom:8px;letter-spacing:.5px">কতটা মনে আছে?</div>' +
        '<div style="display:flex;gap:6px">' + starsHtml + '</div>' +
      '</div>' +
      '<div style="display:flex;flex-direction:column;gap:8px">' + statusBtns + '</div>' +
    '</div>';
  document.body.appendChild(overlay);
}

function rzCloseSurahModal() {
  var el = document.getElementById('rz-surah-modal-overlay');
  if (el && el.parentNode) el.parentNode.removeChild(el);
}

// ── Set Status ────────────────────────────────────────────────
async function rzSetSurahStatus(surahNo, status) {
  var prevProgress = window.rzQuranProgress[surahNo] || { status: 0, stars: 0 };
  var prevMemorized = 0;
  RZ_SURAHS.forEach(function(s) {
    var p = window.rzQuranProgress[s.no];
    if (p && p.status === 2) prevMemorized++;
  });

  window.rzQuranProgress[surahNo] = { status: status, stars: prevProgress.stars || 0 };
  rzCloseSurahModal();
  rzRenderQuranStats();
  rzRenderTodaySurah();
  rzRenderQuranGrid();

  var newMemorized = 0;
  RZ_SURAHS.forEach(function(s) {
    var p = window.rzQuranProgress[s.no];
    if (p && p.status === 2) newMemorized++;
  });
  [5, 10, 20].forEach(function(m) {
    if (prevMemorized < m && newMemorized >= m) rzQuranCelebrate(m);
  });
  rzRenderMilestones();

  if (!window._sb || !window.rzActiveKid) return;
  try {
    await _sb.from('quran_progress').upsert({
      kid_id:     window.rzActiveKid.id,
      parent_id:  window.sbUser ? window.sbUser.id : null,
      surah_no:   surahNo,
      status:     status,
      stars:      window.rzQuranProgress[surahNo].stars,
      updated_at: new Date().toISOString()
    }, { onConflict: 'kid_id,surah_no' });
  } catch(e) {
    console.error('rzSetSurahStatus DB:', e.message || e);
    window.rzQuranProgress[surahNo] = prevProgress;
    rzRenderQuranStats();
    rzRenderQuranGrid();
  }
}

// ── Set Stars ─────────────────────────────────────────────────
async function rzSetSurahStars(surahNo, stars) {
  var prev = window.rzQuranProgress[surahNo] || { status: 0, stars: 0 };
  window.rzQuranProgress[surahNo] = { status: prev.status || 0, stars: stars };
  rzOpenSurahModal(surahNo);

  if (!window._sb || !window.rzActiveKid) return;
  try {
    await _sb.from('quran_progress').upsert({
      kid_id:     window.rzActiveKid.id,
      parent_id:  window.sbUser ? window.sbUser.id : null,
      surah_no:   surahNo,
      status:     window.rzQuranProgress[surahNo].status,
      stars:      stars,
      updated_at: new Date().toISOString()
    }, { onConflict: 'kid_id,surah_no' });
  } catch(e) {
    console.error('rzSetSurahStars DB:', e.message || e);
  }
}

// ── Celebration ───────────────────────────────────────────────
function rzQuranCelebrate(n) {
  if (!document.getElementById('rz-confetti-style')) {
    var s = document.createElement('style'); s.id = 'rz-confetti-style';
    s.textContent = '@keyframes rzFall{0%{transform:translateY(0) rotate(0deg);opacity:1}100%{transform:translateY(110vh) rotate(720deg);opacity:0}}';
    document.head.appendChild(s);
  }
  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;pointer-events:none;overflow:hidden';
  var emojis = ['📖','🌙','⭐','✨','💫','🌟','🏆','📿'];
  var html = '';
  for (var i = 0; i < 28; i++) {
    var left  = Math.floor(Math.random() * 100);
    var delay = (Math.random() * 1.5).toFixed(2);
    var dur   = (2 + Math.random() * 2).toFixed(2);
    html += '<div style="position:absolute;left:' + left + '%;top:-40px;font-size:22px;animation:rzFall ' + dur + 's ' + delay + 's ease-in forwards">' + emojis[i % emojis.length] + '</div>';
  }
  overlay.innerHTML = html;
  document.body.appendChild(overlay);
  var msgs = { 5:'মাশাআল্লাহ! ৫টি সুরা মুখস্থ!', 10:'সুবহানআল্লাহ! ১০টি সুরা!', 20:'আলহামদুলিল্লাহ! জুজ আম্মা হাফেজ!' };
  if (typeof cmToast === 'function') cmToast(msgs[n] || 'অভিনন্দন!');
  setTimeout(function(){ if (overlay.parentNode) overlay.parentNode.removeChild(overlay); }, 5500);
}

