  110: 'النَّصْر',
  112: 'الْإِخْلَاص',
  106: 'قُرَيْش',
  113: 'الْفَلَق',
  105: 'الْفِيل',
  111: 'الْمَسَد',
  114: 'النَّاس',
  109: 'الْكَافِرُون',
  1:   'الْفَاتِحَة',
  107: 'الْمَاعُون',
  97:  'الْقَدْر',
  99:  'الزَّلْزَلَة',
  102: 'التَّكَاثُر',
  98:  'الْبَيِّنَة',
  104: 'الْهُمَزَة',
  101: 'الْقَارِعَة',
  100: 'الْعَادِيَات',
