// ── Auto-fix missing sukun across all RZ_QURAN_TEXT ─────────
// Rule: an Arabic consonant with no diacritic, followed directly
// by another Arabic consonant, needs sukun (ْ U+0652).
// Exceptions: alif/waw/ya as long vowels, special forms.
(function fixAllTashkeel() {
  function isLetter(code) {
    return (code >= 0x0621 && code <= 0x063A) ||
           (code >= 0x0641 && code <= 0x064A) ||
           (code >= 0x0671 && code <= 0x06FF);
  }
  function isDiacritic(code) {
    return (code >= 0x064B && code <= 0x065F) ||
           code === 0x0670 ||
           (code >= 0x0610 && code <= 0x061A) ||
           (code >= 0x06D6 && code <= 0x06ED);
  }
  // Letters that act as long vowels and should NOT get auto-sukun:
  // ا (0627), و (0648), ي (064A), ى (0649), ئ (0626 hamza on ya),
  // ء (0621), أ (0623), إ (0625), آ (0622), ؤ (0624)
  var SKIP = { 0x0621:1, 0x0622:1, 0x0623:1, 0x0624:1, 0x0625:1,
               0x0626:1, 0x0627:1, 0x0648:1, 0x064A:1, 0x0649:1 };

  function addSukun(text) {
    var SUKUN = 'ْ';
    var chars = [];
    for (var i = 0; i < text.length; i++) chars.push(text[i]);

    var result = [];
    var i = 0;
    while (i < chars.length) {
      var c = chars[i];
      var code = c.charCodeAt(0);
      result.push(c);

      if (!isLetter(code) || SKIP[code]) { i++; continue; }

      // Collect diacritics that follow this letter
      var j = i + 1;
      while (j < chars.length && isDiacritic(chars[j].charCodeAt(0))) {
        result.push(chars[j]);
        j++;
      }
      var hasMark = j > i + 1;
      i = j; // advance past letter + its marks

      if (hasMark) continue;

      // No diacritic on this letter — if next char is also a letter, insert sukun
      if (i < chars.length && isLetter(chars[i].charCodeAt(0))) {
        result.push(SUKUN);
      }
    }
    return result.join('');
  }

  if (!window.RZ_QURAN_TEXT) return;
  Object.keys(RZ_QURAN_TEXT).forEach(function(surahNo) {
    var entry = RZ_QURAN_TEXT[surahNo];
    if (!entry || !entry.verses) return;
    entry.verses = entry.verses.map(function(v) {
      return { ar: addSukun(v.ar), tr: v.tr, bn: v.bn };
    });
  });
})();


// ── Tashkeel v2: fixes both missing sukun AND wrong sukun ────
(function applyTashkeelV2() {
  var SUKUN  = 'ْ'; // ْ
  var SHADDA = 'ّ'; // ّ

  function isLetter(code) {
    return (code >= 0x0621 && code <= 0x063A) ||
           (code >= 0x0641 && code <= 0x064A) ||
           (code >= 0x0671 && code <= 0x06FF);
  }
  function isDiacritic(code) {
    return (code >= 0x064B && code <= 0x065F) ||
           code === 0x0670 ||
           (code >= 0x0610 && code <= 0x061A) ||
           (code >= 0x06D6 && code <= 0x06ED);
  }
  // Long-vowel & hamza letters — skip auto-sukun for these
  var SKIP = { 0x0621:1,0x0622:1,0x0623:1,0x0624:1,0x0625:1,
               0x0626:1,0x0627:1,0x0648:1,0x064A:1,0x0649:1 };

  // ── Step 1: remove sukun that is directly before a letter ──
  //            whose diacritics include shadda (assimilation case:
  //            e.g. ال + sun letter → الرَّ not الْرَّ)
  function removeWrongSukun(text) {
    var chars = text.split('');
    var result = [];
    for (var i = 0; i < chars.length; i++) {
      var c = chars[i];
      if (c === SUKUN) {
        // Find next Arabic letter
        var j = i + 1;
        while (j < chars.length && !isLetter(chars[j].charCodeAt(0))) j++;
        // Check if that letter has shadda among its diacritics
        var hasShadda = false;
        var k = j + 1;
        while (k < chars.length && isDiacritic(chars[k].charCodeAt(0))) {
          if (chars[k] === SHADDA) { hasShadda = true; break; }
          k++;
        }
        if (hasShadda) continue; // drop this wrong sukun
      }
      result.push(c);
    }
    return result.join('');
  }

  // ── Step 2: add sukun to bare consonants that need one ─────
  //            (bare = no following diacritic, and next letter
  //             exists somewhere ahead without shadda)
  function addMissingSukun(text) {
    var chars = text.split('');
    var result = [];
    var i = 0;
    while (i < chars.length) {
      var c = chars[i];
      var code = c.charCodeAt(0);
      result.push(c);

      if (!isLetter(code) || SKIP[code]) { i++; continue; }

      // Collect this letter's own diacritics
      var j = i + 1;
      while (j < chars.length && isDiacritic(chars[j].charCodeAt(0))) {
        result.push(chars[j]);
        j++;
      }
      var hasMark = (j > i + 1);
      i = j;

      if (hasMark) continue; // already has a mark

      // Find next Arabic letter (skip spaces, punctuation, etc.)
      var nextIdx = j;
      while (nextIdx < chars.length && !isLetter(chars[nextIdx].charCodeAt(0))) nextIdx++;
      if (nextIdx >= chars.length) continue; // nothing follows

      // Check if next letter has shadda (sun-letter assimilation — no sukun)
      var hasShadda = false;
      var m = nextIdx + 1;
      while (m < chars.length && isDiacritic(chars[m].charCodeAt(0))) {
        if (chars[m] === SHADDA) { hasShadda = true; break; }
        m++;
      }
      if (!hasShadda) result.push(SUKUN);
    }
    return result.join('');
  }

  if (!window.RZ_QURAN_TEXT) return;
  Object.keys(RZ_QURAN_TEXT).forEach(function(surahNo) {
    var entry = RZ_QURAN_TEXT[surahNo];
    if (!entry || !entry.verses) return;
    entry.verses = entry.verses.map(function(v) {
      var ar = removeWrongSukun(v.ar); // step 1
      ar     = addMissingSukun(ar);    // step 2
      return { ar: ar, tr: v.tr, bn: v.bn };
    });
  });
})();


// ══════════════════════════════════════════════════════════════
//  SLEEP TRACKER — full implementation
// ══════════════════════════════════════════════════════════════
(function() {

// ── State ─────────────────────────────────────────────────────
var _slKidId   = null;
var _slKids    = [];
var _slLogs    = [];       // last 30 days from Supabase
var _slQuality = 2;        // default "ভালো"
var _slGoalH   = 8;        // hours
var _slCountdownTimer = null;

// Bengali digits helper (same as app)
function bn(n) {
  return typeof rzToBn === 'function' ? rzToBn(n) : String(n);
}

// ── Page Load ─────────────────────────────────────────────────
window.rzSleepPageLoad = function() {
  _slKids = window.rzKids || [];
  if (!_slKids.length) {
    // Try to load kids first
    if (window._sb && window.sbUser) {
      window._sb.from('kids')
        .select('*')
        .eq('parent_id', window.sbUser.id)
        .order('created_at')
        .then(function(r) {
          _slKids = (r && r.data) ? r.data : [];
          if (!_slKidId && _slKids.length) _slKidId = _slKids[0].id;
          rzSleepRenderKidTabs();
          rzLoadSleepData();
        });
    } else {
      rzSleepRenderKidTabs();
      rzRenderSleepPage();
    }
    return;
  }
  if (!_slKidId) _slKidId = _slKids[0] ? _slKids[0].id : null;
  rzSleepRenderKidTabs();
  rzLoadSleepData();
};

// ── Kid Tabs ──────────────────────────────────────────────────
function rzSleepRenderKidTabs() {
  var el = document.getElementById('sleep-kid-tabs');
  if (!el) return;
  if (!_slKids.length) { el.innerHTML = ''; return; }
  el.innerHTML = _slKids.map(function(k) {
    var active = k.id === _slKidId;
    return '<button onclick="rzSleepSwitchKid(\'' + k.id + '\')" style="' +
      'padding:7px 16px;border-radius:20px;font-size:12px;font-weight:700;' +
      'font-family:inherit;cursor:pointer;transition:.2s;' +
      'border:1.5px solid ' + (active ? '#FF8A00' : 'var(--border,#e5e7eb)') + ';' +
      'background:' + (active ? 'rgba(255,138,0,.12)' : 'transparent') + ';' +
      'color:' + (active ? '#FF8A00' : 'var(--text2,#888)') + '">' +
      (k.avatar || '👦') + ' ' + (k.name || 'শিশু') +
    '</button>';
  }).join('');
}

window.rzSleepSwitchKid = function(kidId) {
  _slKidId = kidId;
  rzSleepRenderKidTabs();
  rzLoadSleepData();
};

// ── Load Data from Supabase ────────────────────────────────────
function rzLoadSleepData() {
  if (!window._sb || !_slKidId) {
    _slLogs = [];
    rzRenderSleepPage();
    return;
  }
  // Get last 30 days
  var since = new Date();
  since.setDate(since.getDate() - 30);
  var sinceStr = since.toISOString().slice(0, 10);

  window._sb.from('sleep_logs')
    .select('*')
    .eq('kid_id', _slKidId)
    .gte('date', sinceStr)
    .order('date', { ascending: false })
    .then(function(r) {
      _slLogs = (r && r.data) ? r.data : [];
      rzRenderSleepPage();
    });
}

// ── Render Everything ─────────────────────────────────────────
function rzRenderSleepPage() {
  rzRenderSleepTodayInputs();
  rzRenderSleepStats();
  rzRenderSleepWeeklyChart();
  rzRenderSleepInsight();
  rzRenderSleepAchievements();
  rzRenderSleepCountdown();
  rzSleepUpdateDuration();
}

// ── Today's Inputs Pre-fill ───────────────────────────────────
function rzRenderSleepTodayInputs() {
  var today = getLocalDateStr();
  var todayLog = _slLogs.find(function(l) { return l.date === today; });

  var badge = document.getElementById('sl-today-badge');
  if (todayLog && badge) {
    var durH = todayLog.duration_minutes ? (todayLog.duration_minutes / 60).toFixed(1) : '—';
    badge.innerHTML =
      '<div style="font-size:22px;font-weight:800;color:#FF8A00">' + bn(durH) + 'ঘ</div>' +
      '<div style="font-size:10px;color:var(--text2,#888)">আজকের ঘুম</div>';
  }

  if (todayLog) {
    if (todayLog.sleep_time) {
      var st = document.getElementById('sl-sleep-time');
      if (st) st.value = todayLog.sleep_time.slice(0, 5);
    }
    if (todayLog.wake_time) {
      var wt = document.getElementById('sl-wake-time');
      if (wt) wt.value = todayLog.wake_time.slice(0, 5);
    }
    if (todayLog.quality) {
      _slQuality = todayLog.quality;
      rzSleepSetQuality(_slQuality);
    }
  }

  // Goal
  var goalEl = document.getElementById('sl-goal-display');
  if (goalEl) goalEl.textContent = bn(_slGoalH) + ' ঘণ্টা';

  rzSleepUpdateDuration();
}

// ── Duration Pill ─────────────────────────────────────────────
window.rzSleepUpdateDuration = function() {
  var st = document.getElementById('sl-sleep-time');
  var wt = document.getElementById('sl-wake-time');
  var el = document.getElementById('sl-dur-text');
  var pill = document.getElementById('sl-duration-pill');
  if (!st || !wt || !el) return;

  var mins = calcDurationMins(st.value, wt.value);
  var h = Math.floor(mins / 60);
  var m = mins % 60;
  var txt = bn(h) + 'ঘ';
  if (m) txt += ' ' + bn(m) + 'ম';
  el.textContent = txt;

  // Color feedback
  var goalMins = _slGoalH * 60;
  var color = mins >= goalMins ? '#10b981' : (mins >= goalMins * 0.85 ? '#f59e0b' : '#ef4444');
  el.style.color = color;
  if (pill) pill.style.background = color.replace(')', ',.12)').replace('rgb', 'rgba').replace('#', 'rgba(').replace('10b981', '16,185,129').replace('f59e0b', '245,158,11').replace('ef4444', '239,68,68,');
  // simpler approach:
  if (mins >= goalMins) {
    el.style.color = '#10b981';
    if (pill) pill.style.background = 'rgba(16,185,129,0.12)';
  } else if (mins >= goalMins * 0.85) {
    el.style.color = '#f59e0b';
    if (pill) pill.style.background = 'rgba(245,158,11,0.12)';
  } else {
    el.style.color = '#ef4444';
    if (pill) pill.style.background = 'rgba(239,68,68,0.12)';
  }
};

function calcDurationMins(sleepTime, wakeTime) {
  if (!sleepTime || !wakeTime) return 480;
  var sp = sleepTime.split(':').map(Number);
  var wp = wakeTime.split(':').map(Number);
  var sleepMins = sp[0] * 60 + sp[1];
  var wakeMins  = wp[0] * 60 + wp[1];
  var diff = wakeMins - sleepMins;
  if (diff <= 0) diff += 24 * 60; // overnight
  return diff;
}

// ── Quality Stars ─────────────────────────────────────────────
window.rzSleepSetQuality = function(q) {
  _slQuality = q;
  var labels = ['', 'ঠিকঠাক', 'ভালো', 'দারুণ'];
  var icons  = ['', '😴', '😊', '🌟'];
  var colors = ['', '#f59e0b', '#FF8A00', '#10b981'];
  [1, 2, 3].forEach(function(i) {
    var btn = document.getElementById('sl-q' + i);
    if (!btn) return;
    var active = i === q;
    btn.style.border     = active ? '2px solid ' + colors[i] : '1.5px solid var(--border,#e5e7eb)';
    btn.style.background = active ? colors[i].replace('#', 'rgba(').replace(/(.{6})$/, ',$1').replace('rgba(f59e0b,#f59e0b)', 'rgba(245,158,11,0.12)') : 'transparent';
    // simpler:
    if (active) {
      var rgb = i===1 ? '245,158,11' : i===2 ? '99,102,241' : '16,185,129';
      btn.style.background = 'rgba(' + rgb + ',0.12)';
      btn.style.color = colors[i];
    } else {
      btn.style.background = 'transparent';
      btn.style.color = 'var(--text2,#888)';
    }
  });
};
// Init
rzSleepSetQuality(2);

// ── Goal Stepper ──────────────────────────────────────────────
window.rzSleepChangeGoal = function(delta) {
  _slGoalH = Math.max(6, Math.min(12, _slGoalH + delta));
  var el = document.getElementById('sl-goal-display');
  if (el) el.textContent = bn(_slGoalH) + ' ঘণ্টা';
  rzSleepUpdateDuration();
  rzRenderSleepWeeklyChart();
};

// ── Save Log ──────────────────────────────────────────────────
window.rzSaveSleepLog = function() {
  var st = document.getElementById('sl-sleep-time');
  var wt = document.getElementById('sl-wake-time');
  if (!st || !wt) return;

  var sleepTime = st.value;
  var wakeTime  = wt.value;
  var mins = calcDurationMins(sleepTime, wakeTime);
  var today = getLocalDateStr();

  var row = {
    kid_id: _slKidId,
    date: today,
    sleep_time: sleepTime,
    wake_time: wakeTime,
    duration_minutes: mins,
    quality: _slQuality,
    goal_hours: _slGoalH
  };

  var btn = document.querySelector('button[onclick="rzSaveSleepLog()"]');
  if (btn) {
    btn.textContent = 'Saving...';
    btn.disabled = true;
  }

  if (!window._sb || !_slKidId) {
    // Offline mode: just update local state
    var existing = _slLogs.findIndex(function(l) { return l.date === today; });
    if (existing >= 0) _slLogs[existing] = row;
    else _slLogs.unshift(row);
    rzRenderSleepPage();
    if (btn) { btn.textContent = 'সংরক্ষিত ✓'; btn.style.background = 'linear-gradient(135deg,#10b981,#059669)'; }
    return;
  }

  window._sb.from('sleep_logs')
    .upsert(row, { onConflict: 'kid_id,date' })
    .then(function(r) {
      if (btn) {
        if (r && r.error) {
          btn.textContent = 'Error — আবার চেষ্টা করুন';
          btn.disabled = false;
          btn.style.background = 'linear-gradient(135deg,#ef4444,#dc2626)';
        } else {
          btn.textContent = 'সংরক্ষিত ✓';
          btn.disabled = false;
          btn.style.background = 'linear-gradient(135deg,#10b981,#059669)';
          // Update local log
          var ex = _slLogs.findIndex(function(l) { return l.date === today; });
          if (ex >= 0) _slLogs[ex] = Object.assign({}, _slLogs[ex], row);
          else _slLogs.unshift(row);
          rzRenderSleepPage();
          setTimeout(function() {
            if (btn) { btn.textContent = 'আজকের ঘুম Save করুন ✓'; btn.style.background = 'linear-gradient(135deg,#FF8A00,#FFB800)'; }
          }, 2500);
        }
      }
    });
};

// ── Stats Row ─────────────────────────────────────────────────
function rzRenderSleepStats() {
  var el = document.getElementById('sl-stats');
  if (!el) return;

  var streak = calcSleepStreak();
  var weekAvg = calcWeekAvg();
  var goalMins = _slGoalH * 60;

  var stats = [
    {
      icon: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="#FF8A00" stroke-width="2"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>',
      value: bn(streak) + ' দিন',
      label: 'ঘুমের Streak',
      color: '#FF8A00'
    },
    {
      icon: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="#FF8A00" stroke-width="2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
      value: weekAvg > 0 ? bn(Math.floor(weekAvg / 60)) + 'ঘ ' + bn(weekAvg % 60) + 'ম' : '—',
      label: '৭ দিনের গড়',
      color: '#FF8A00'
    },
    {
      icon: '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="#10b981" stroke-width="2"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>',
      value: bn(_slGoalH) + ' ঘণ্টা',
      label: 'দৈনিক লক্ষ্য',
      color: '#10b981'
    }
  ];

  el.innerHTML = stats.map(function(s) {
    return '<div style="background:var(--card,#fff);border-radius:14px;padding:12px 10px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.06)">' +
      '<div style="margin-bottom:4px">' + s.icon + '</div>' +
      '<div style="font-size:15px;font-weight:800;color:' + s.color + '">' + s.value + '</div>' +
      '<div style="font-size:10px;color:var(--text2,#888);margin-top:2px">' + s.label + '</div>' +
    '</div>';
  }).join('');
}

function calcSleepStreak() {
  var goalMins = _slGoalH * 60;
  var streak = 0;
  var d = new Date();
  // Don't penalize if today not yet logged
  var today = getLocalDateStr();
  var hasToday = _slLogs.some(function(l) { return l.date === today; });
  if (!hasToday) d.setDate(d.getDate() - 1);

  for (var i = 0; i < 30; i++) {
    var ds = d.toISOString().slice(0, 10);
    var log = _slLogs.find(function(l) { return l.date === ds; });
    if (log && log.duration_minutes >= goalMins) {
      streak++;
      d.setDate(d.getDate() - 1);
    } else {
      break;
    }
  }
  return streak;
}

function calcWeekAvg() {
  var last7 = getLast7Dates();
  var logs = last7.map(function(ds) {
    return _slLogs.find(function(l) { return l.date === ds; });
  }).filter(Boolean);
  if (!logs.length) return 0;
  var total = logs.reduce(function(a, l) { return a + (l.duration_minutes || 0); }, 0);
  return Math.round(total / logs.length);
}

// ── Weekly Chart ──────────────────────────────────────────────
function rzRenderSleepWeeklyChart() {
  var el = document.getElementById('sl-weekly-chart');
  if (!el) return;

  var last7 = getLast7Dates();
  var goalMins = _slGoalH * 60;
  var bnDays = ['রবি', 'সোম', 'মঙ্গল', 'বুধ', 'বৃহঃ', 'শুক্র', 'শনি'];

  var entries = last7.map(function(ds) {
    var log = _slLogs.find(function(l) { return l.date === ds; });
    var d = new Date(ds);
    return {
      day: bnDays[d.getDay()],
      mins: log ? (log.duration_minutes || 0) : 0,
      date: ds
    };
  });

  var maxH = 100; // px for chart bars
  var maxMins = Math.max(goalMins * 1.2, Math.max.apply(null, entries.map(function(e) { return e.mins || 1; })));

  var bars = entries.map(function(e) {
    var pct = Math.min(1, e.mins / maxMins);
    var barH = Math.max(4, Math.round(pct * maxH));
    var isToday = e.date === getLocalDateStr();
    var color = e.mins === 0 ? 'var(--border,#e5e7eb)' : (e.mins >= goalMins ? '#10b981' : (e.mins >= goalMins * 0.75 ? '#f59e0b' : '#ef4444'));
    var durTxt = e.mins ? (bn(Math.floor(e.mins / 60)) + 'ঘ') : '—';

    return '<div style="display:flex;flex-direction:column;align-items:center;flex:1;gap:4px">' +
      '<div style="font-size:9px;font-weight:700;color:' + (e.mins >= goalMins ? '#10b981' : 'var(--text2,#888)') + '">' + durTxt + '</div>' +
      '<div style="width:100%;display:flex;align-items:flex-end;justify-content:center;height:' + maxH + 'px">' +
        '<div style="width:70%;border-radius:6px 6px 3px 3px;background:' + color + ';height:' + barH + 'px;' +
          (isToday ? 'box-shadow:0 0 0 2px #FF8A00;' : '') +
          'transition:height .4s ease"></div>' +
      '</div>' +
      '<div style="font-size:10px;font-weight:' + (isToday ? '800' : '500') + ';color:' + (isToday ? '#FF8A00' : 'var(--text2,#888)') + '">' + e.day + '</div>' +
    '</div>';
  }).join('');

  // Goal line indicator
  var goalLinePos = Math.round((goalMins / maxMins) * maxH);

  el.innerHTML =
    '<div style="position:relative">' +
      '<div style="position:absolute;bottom:' + (goalLinePos + 22) + 'px;left:0;right:0;border-top:1.5px dashed rgba(255,138,0,0.4);z-index:1">' +
        '<span style="position:absolute;right:0;top:-10px;font-size:9px;color:#FF8A00;background:var(--card,#fff);padding:0 3px">লক্ষ্য</span>' +
      '</div>' +
      '<div style="display:flex;gap:4px;padding-top:18px">' + bars + '</div>' +
    '</div>' +
    '<div style="display:flex;gap:12px;margin-top:12px;justify-content:center">' +
      '<div style="display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text2,#888)"><div style="width:10px;height:10px;border-radius:2px;background:#10b981"></div>লক্ষ্য পূরণ</div>' +
      '<div style="display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text2,#888)"><div style="width:10px;height:10px;border-radius:2px;background:#f59e0b"></div>কাছাকাছি</div>' +
      '<div style="display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text2,#888)"><div style="width:10px;height:10px;border-radius:2px;background:#ef4444"></div>কম</div>' +
    '</div>';
}

// ── Smart Insight ─────────────────────────────────────────────
function rzRenderSleepInsight() {
  var el = document.getElementById('sl-insight');
  if (!el) return;

  var last7 = getLast7Dates();
  var goalMins = _slGoalH * 60;

  // Yesterday
  var yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  var yds = yesterday.toISOString().slice(0, 10);
  var yLog = _slLogs.find(function(l) { return l.date === yds; });

  // Day before
  var twoDaysAgo = new Date();
  twoDaysAgo.setDate(twoDaysAgo.getDate() - 2);
  var tds = twoDaysAgo.toISOString().slice(0, 10);
  var tLog = _slLogs.find(function(l) { return l.date === tds; });

  var msg = '', icon = '💡', color = '#FF8A00';

  var streak = calcSleepStreak();

  if (streak >= 7) {
    msg = 'অসাধারণ! টানা ' + bn(streak) + ' দিন লক্ষ্য পূরণ করেছ। তুমি সত্যিকারের Dream Champion! 🏆';
    icon = '🏆'; color = '#FFB800';
  } else if (streak >= 3) {
    msg = 'দারুণ! টানা ' + bn(streak) + ' দিন ভালো ঘুম হচ্ছে। চালিয়ে যাও!';
    icon = '🔥'; color = '#FF8A00';
  } else if (yLog && tLog && yLog.duration_minutes < tLog.duration_minutes) {
    var diff = Math.abs(tLog.duration_minutes - yLog.duration_minutes);
    msg = 'কাল ' + bn(Math.round(diff)) + ' মিনিট কম ঘুমিয়েছ। আজ একটু তাড়াতাড়ি ঘুমাও!';
    icon = '😴'; color = '#f59e0b';
  } else if (yLog && yLog.duration_minutes >= goalMins) {
    msg = 'গতকাল লক্ষ্য পূরণ হয়েছে! আজও ভালো ঘুমাও।';
    icon = '✨'; color = '#10b981';
  } else if (yLog && yLog.duration_minutes < goalMins * 0.75) {
    var short = Math.round(goalMins - yLog.duration_minutes);
    msg = 'গতকাল ' + bn(Math.floor(short / 60)) + ' ঘণ্টা ' + bn(short % 60) + ' মিনিট কম ঘুম হয়েছে। আজ তাড়াতাড়ি ঘুমাও!';
    icon = '⚠️'; color = '#ef4444';
  } else {
    // Week avg vs goal
    var avg = calcWeekAvg();
    if (avg > 0 && avg < goalMins) {
      msg = 'এই সপ্তাহে গড় ঘুম লক্ষ্যের চেয়ে কম। রাত ' + bn(_slGoalH <= 8 ? 10 : 9) + 'টার আগে ঘুমানোর চেষ্টা করো।';
      icon = '🌙'; color = '#FF8A00';
    } else {
      msg = 'প্রতিদিন ' + bn(_slGoalH) + ' ঘণ্টা ঘুমালে শরীর ও মন দুটোই ভালো থাকে!';
      icon = '💤'; color = '#FF8A00';
    }
  }

  el.innerHTML =
    '<div style="background:var(--card,#fff);border-radius:16px;padding:14px 16px;box-shadow:0 1px 4px rgba(0,0,0,.06);' +
      'border-left:4px solid ' + color + ';display:flex;align-items:flex-start;gap:12px">' +
      '<div style="font-size:24px;flex-shrink:0">' + icon + '</div>' +
      '<div>' +
        '<div style="font-size:11px;font-weight:700;color:' + color + ';margin-bottom:3px">স্মার্ট পরামর্শ</div>' +
        '<div style="font-size:13px;color:var(--text,#1f2937);line-height:1.5">' + msg + '</div>' +
      '</div>' +
    '</div>';
}

// ── Achievements ──────────────────────────────────────────────
function rzRenderSleepAchievements() {
  var el = document.getElementById('sl-achievements');
  if (!el) return;

  var goalMins = _slGoalH * 60;
  var streak = calcSleepStreak();
  var last7 = getLast7Dates();
  var weekLogs = last7.map(function(ds) { return _slLogs.find(function(l) { return l.date === ds; }); }).filter(Boolean);
  var weekGoalDays = weekLogs.filter(function(l) { return l.duration_minutes >= goalMins; }).length;

  // Early Bird: slept before 10pm (22:00) at least 3 times this week
  var earlyBirdDays = weekLogs.filter(function(l) {
    if (!l.sleep_time) return false;
    var h = parseInt(l.sleep_time.slice(0, 2), 10);
    var m = parseInt(l.sleep_time.slice(3, 5), 10) || 0;
    var totalMin = h * 60 + m;
    return totalMin < 22 * 60 || totalMin >= 23 * 60; // before 10pm or wraps (before midnight)
  }).length;

  // Dream Champion: 7-day streak
  var isDreamChamp = streak >= 7;

  // Star Sleeper: 3 "দারুণ" quality logs this week
  var starDays = weekLogs.filter(function(l) { return l.quality === 3; }).length;

  // Consistent: hit goal 5+ of last 7 days
  var isConsistent = weekGoalDays >= 5;

  var badges = [
    {
      id: 'early-bird',
      icon: '🌅',
      title: 'Early Bird',
      desc: 'রাত ১০টার আগে ঘুমানো',
      unlocked: earlyBirdDays >= 3,
      progress: Math.min(3, earlyBirdDays),
      total: 3
    },
    {
      id: 'dream-champ',
      icon: '🏆',
      title: 'Dream Champion',
      desc: 'টানা ৭ দিন লক্ষ্য পূরণ',
      unlocked: isDreamChamp,
      progress: Math.min(7, streak),
      total: 7
    },
    {
      id: 'star-sleeper',
      icon: '⭐',
      title: 'Star Sleeper',
      desc: '৩ রাত দারুণ ঘুম',
      unlocked: starDays >= 3,
      progress: Math.min(3, starDays),
      total: 3
    },
    {
      id: 'consistent',
      icon: '🎯',
      title: 'Consistent',
      desc: '৭ দিনে ৫ দিন লক্ষ্য পূরণ',
      unlocked: isConsistent,
      progress: Math.min(5, weekGoalDays),
      total: 5
    }
  ];

  el.innerHTML = badges.map(function(b) {
    var pct = Math.round((b.progress / b.total) * 100);
    return '<div style="padding:12px;border-radius:14px;border:1.5px solid ' +
      (b.unlocked ? '#FFB800' : 'var(--border,#e5e7eb)') + ';' +
      'background:' + (b.unlocked ? 'linear-gradient(135deg,rgba(255,184,0,0.08),rgba(255,138,0,0.05))' : 'var(--bg,#f9fafb)') + '">' +
      '<div style="font-size:26px;margin-bottom:6px;' + (b.unlocked ? '' : 'filter:grayscale(1);opacity:0.5') + '">' + b.icon + '</div>' +
      '<div style="font-size:12px;font-weight:700;color:' + (b.unlocked ? '#FF8A00' : 'var(--text,#1f2937)') + '">' + b.title + '</div>' +
      '<div style="font-size:10px;color:var(--text2,#888);margin:3px 0 8px">' + b.desc + '</div>' +
      '<div style="background:var(--border,#e5e7eb);border-radius:4px;height:4px;overflow:hidden">' +
        '<div style="background:' + (b.unlocked ? 'linear-gradient(90deg,#FFB800,#FF8A00)' : '#FF8A00') + ';height:100%;width:' + pct + '%;border-radius:4px;transition:width .6s ease"></div>' +
      '</div>' +
      '<div style="font-size:9px;color:var(--text2,#888);margin-top:4px">' + bn(b.progress) + ' / ' + bn(b.total) + '</div>' +
    '</div>';
  }).join('');
}

// ── Bedtime Countdown ─────────────────────────────────────────
function rzRenderSleepCountdown() {
  var el = document.getElementById('sl-countdown');
  if (!el) return;

  // Default bedtime: goalH hours before 6am
  var bedtimeHour = (24 + 6 - _slGoalH) % 24;
  var bedtimeStr = (bedtimeHour < 10 ? '0' : '') + bedtimeHour + ':00';

  if (_slCountdownTimer) clearInterval(_slCountdownTimer);

  function update() {
    var now = new Date();
    var bedtime = new Date();
    bedtime.setHours(bedtimeHour, 0, 0, 0);
    if (bedtime <= now) bedtime.setDate(bedtime.getDate() + 1);
    var diff = Math.floor((bedtime - now) / 1000);
    var h = Math.floor(diff / 3600);
    var m = Math.floor((diff % 3600) / 60);
    var s = diff % 60;

    var today = getLocalDateStr();
    var hasToday = _slLogs.some(function(l) { return l.date === today; });

    if (hasToday && _slLogs.find(function(l) { return l.date === today; }).duration_minutes >= _slGoalH * 60) {
      el.innerHTML = '<div style="background:linear-gradient(135deg,rgba(16,185,129,0.1),rgba(5,150,105,0.05));border-radius:16px;padding:14px 16px;display:flex;align-items:center;gap:12px;margin-bottom:0">' +
        '<div style="font-size:24px">✅</div>' +
        '<div><div style="font-size:13px;font-weight:700;color:#10b981">আজকের ঘুম লগ করা হয়েছে!</div>' +
        '<div style="font-size:11px;color:var(--text2,#888)">ভালো ঘুমের জন্য শুভকামনা 🌙</div></div>' +
      '</div>';
      if (_slCountdownTimer) clearInterval(_slCountdownTimer);
      return;
    }

    var urgency = h === 0 && m < 30;
    var color = urgency ? '#ef4444' : (h < 2 ? '#f59e0b' : '#FF8A00');
    var timeStr = bn(h) + 'ঘ ' + bn(m) + 'ম ' + bn(s) + 'স';

    el.innerHTML = '<div style="background:linear-gradient(135deg,' + (urgency ? 'rgba(239,68,68,0.08),rgba(220,38,38,0.04)' : 'rgba(255,138,0,0.08),rgba(255,184,0,0.04)') + ');border-radius:16px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between">' +
      '<div style="display:flex;align-items:center;gap:10px">' +
        '<div style="font-size:22px">' + (urgency ? '🚨' : '🌙') + '</div>' +
        '<div>' +
          '<div style="font-size:12px;font-weight:700;color:' + color + '">ঘুমানোর সময় ' + (urgency ? 'হয়ে গেছে!' : 'কাউন্টডাউন') + '</div>' +
          '<div style="font-size:10px;color:var(--text2,#888)">রাত ' + bn(bedtimeHour) + ':০০ এ ঘুমানোর লক্ষ্য</div>' +
        '</div>' +
      '</div>' +
      '<div style="text-align:right">' +
        '<div style="font-size:16px;font-weight:800;color:' + color + ';font-variant-numeric:tabular-nums">' + timeStr + '</div>' +
        '<div style="font-size:9px;color:var(--text2,#888)">বাকি আছে</div>' +
      '</div>' +
    '</div>';
  }

  update();
  _slCountdownTimer = setInterval(update, 1000);
}

// ── Helpers ───────────────────────────────────────────────────
function getLocalDateStr() {
  var d = new Date();
  return d.getFullYear() + '-' +
    String(d.getMonth() + 1).padStart(2, '0') + '-' +
    String(d.getDate()).padStart(2, '0');
}

function getLast7Dates() {
  var dates = [];
  for (var i = 6; i >= 0; i--) {
    var d = new Date();
    d.setDate(d.getDate() - i);
    dates.push(d.getFullYear() + '-' +
      String(d.getMonth() + 1).padStart(2, '0') + '-' +
      String(d.getDate()).padStart(2, '0'));
  }
  return dates;
}

})();



