// ── Sleep Tracker v2: no green, English badge, white text ─────
// Complete standalone override — supersedes all previous versions.
(function() {

  if (window._rzCdRef)  { clearInterval(window._rzCdRef);  window._rzCdRef  = null; }
  if (window._rzEngRef) { clearInterval(window._rzEngRef); window._rzEngRef = null; }

  var S = window._rzSleep = (window._rzSleep || { logs:[], goalH:8, kidId:null, quality:2 });

  var IC = {
    moon:    '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>',
    smile:   '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg>',
    star:    '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="currentColor" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>',
    sunrise: '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 18a5 5 0 0 0-10 0"/><line x1="12" y1="9" x2="12" y2="2"/><line x1="4.22" y1="10.22" x2="5.64" y2="11.64"/><line x1="1" y1="18" x2="3" y2="18"/><line x1="21" y1="18" x2="23" y2="18"/><line x1="18.36" y1="11.64" x2="19.78" y2="10.22"/><line x1="23" y1="22" x2="1" y2="22"/></svg>',
    trophy:  '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2h12v6a6 6 0 0 1-12 0V2z"/><path d="M6 7H2V5h4"/><path d="M18 7h4V5h-4"/><line x1="12" y1="14" x2="12" y2="19"/><rect x="7" y="19" width="10" height="2" rx="1"/></svg>',
    target:  '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2" fill="currentColor"/></svg>',
    flame:   '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2c0 0-6 6-6 12a6 6 0 0 0 12 0c0-6-6-12-6-12z"/></svg>',
    zap:     '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>',
    alert:   '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',
    bell:    '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 0 1-3.46 0"/></svg>',
    check:   '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>',
    trend:   '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>',
    clock:   '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>',
    ok:      '<svg viewBox="0 0 24 24" width="{s}" height="{s}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>'
  };
  function ic(name, color, size) {
    size = size || 22;
    return '<span style="color:' + color + ';display:flex;align-items:center;justify-content:center;line-height:1">' +
      (IC[name]||IC.moon).replace(/\{s\}/g, size) + '</span>';
  }

  function bn(n) { return typeof rzToBn==='function' ? rzToBn(n) : String(n); }
  function pad(n) { return n < 10 ? '0'+n : ''+n; }

  function todayStr() {
    var d=new Date();
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  function last7() {
    var r=[];
    for(var i=6;i>=0;i--){ var d=new Date(); d.setDate(d.getDate()-i); r.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')); }
    return r;
  }
  function calcDur(st,wt) {
    if(!st||!wt) return 480;
    var sp=st.split(':').map(Number), wp=wt.split(':').map(Number);
    var d=(wp[0]*60+wp[1])-(sp[0]*60+sp[1]); return d<=0?d+1440:d;
  }
  function calcStreak() {
    var gm=S.goalH*60, streak=0, d=new Date();
    if(!S.logs.some(function(l){return l.date===todayStr();})) d.setDate(d.getDate()-1);
    for(var i=0;i<30;i++){
      var ds=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
      var l=S.logs.find(function(x){return x.date===ds;});
      if(l&&l.duration_minutes>=gm){streak++;d.setDate(d.getDate()-1);}else break;
    }
    return streak;
  }
  function calcAvg() {
    var wl=last7().map(function(ds){return S.logs.find(function(l){return l.date===ds;});}).filter(Boolean);
    return wl.length?Math.round(wl.reduce(function(a,l){return a+(l.duration_minutes||0);},0)/wl.length):0;
  }

  // ── Kid Tabs ─────────────────────────────────────────────────
  function renderKidTabs() {
    var el=document.getElementById('sleep-kid-tabs'); if(!el) return;
    var kids=window.rzKids||[];
    if(!kids.length){el.innerHTML='';return;}
    el.innerHTML=kids.map(function(k){
      var a=k.id===S.kidId;
      return '<button onclick="rzSleepSwitchKid(\''+k.id+'\')" style="padding:7px 16px;border-radius:20px;font-size:12px;font-weight:700;font-family:inherit;cursor:pointer;transition:.2s;border:1.5px solid '+(a?'#FF8A00':'var(--border,#e5e7eb)')+';background:'+(a?'rgba(255,138,0,.12)':'transparent')+';color:'+(a?'#FF8A00':'var(--text,#1f2937)')+'">'+
        (k.avatar||'👦')+' '+(k.name||'শিশু')+'</button>';
    }).join('');
  }
  window.rzSleepSwitchKid=function(id){S.kidId=id;renderKidTabs();loadData();};

  // ── Data ─────────────────────────────────────────────────────
  function loadData() {
    if(!window._sb||!S.kidId){S.logs=[];renderAll();return;}
    var since=new Date(); since.setDate(since.getDate()-30);
    window._sb.from('sleep_logs').select('*').eq('kid_id',S.kidId)
      .gte('date',since.toISOString().slice(0,10))
      .order('date',{ascending:false})
      .then(function(r){S.logs=(r&&r.data)||[];renderAll();});
  }

  // ── Render all ───────────────────────────────────────────────
  function renderAll() {
    renderTodayInputs();
    renderCountdown();
    renderStats();
    renderChart();
    renderInsight();
    renderAchievements();
  }

  // ── Today inputs ─────────────────────────────────────────────
  function renderTodayInputs() {
    var today=todayStr(), tLog=S.logs.find(function(l){return l.date===today;});
    var badge=document.getElementById('sl-today-badge');
    if(tLog&&badge){
      // English digits, "h" instead of "ঘ"
      var dh=(tLog.duration_minutes/60).toFixed(1);
      badge.innerHTML='<div style="font-size:22px;font-weight:800;color:#FF8A00">'+dh+'h</div><div style="font-size:10px;color:var(--text2,#888)">আজকের ঘুম</div>';
    }
    if(tLog){
      var st=document.getElementById('sl-sleep-time'); if(st&&tLog.sleep_time) st.value=tLog.sleep_time.slice(0,5);
      var wt=document.getElementById('sl-wake-time');  if(wt&&tLog.wake_time)  wt.value=tLog.wake_time.slice(0,5);
      if(tLog.quality){S.quality=tLog.quality;setSleepQuality(tLog.quality);}
      if(tLog.goal_hours) S.goalH=tLog.goal_hours;
    }
    var ge=document.getElementById('sl-goal-display'); if(ge) ge.textContent=bn(S.goalH)+' ঘণ্টা';
    rzSleepUpdateDuration();
  }

  // ── Quality ──────────────────────────────────────────────────
  function setSleepQuality(q) {
    S.quality=q;
    var colors=['','#f59e0b','#FF8A00','#FFB800'];
    [1,2,3].forEach(function(i){
      var btn=document.getElementById('sl-q'+i); if(!btn) return;
      if(i===q){var rgb=i===1?'245,158,11':i===2?'255,138,0':'255,184,0';btn.style.border='2px solid '+colors[i];btn.style.background='rgba('+rgb+',0.12)';btn.style.color=colors[i];}
      else{btn.style.border='1.5px solid var(--border,#e5e7eb)';btn.style.background='transparent';btn.style.color='var(--text2,#888)';}
    });
  }
  window.rzSleepSetQuality=function(q){setSleepQuality(q);};
  setSleepQuality(2);

  window.rzSleepUpdateDuration=function(){
    var st=document.getElementById('sl-sleep-time'),wt=document.getElementById('sl-wake-time'),el=document.getElementById('sl-dur-text'),pill=document.getElementById('sl-duration-pill');
    if(!st||!wt||!el) return;
    var mins=calcDur(st.value,wt.value),h=Math.floor(mins/60),m=mins%60,gm=S.goalH*60;
    el.textContent=bn(h)+'ঘ'+(m?' '+bn(m)+'ম':'');
    // Goal met → orange, near goal → yellow, low → red
    var c=mins>=gm?'#FF8A00':(mins>=gm*.85?'#f59e0b':'#ef4444');
    var rgb=mins>=gm?'255,138,0':(mins>=gm*.85?'245,158,11':'239,68,68');
    el.style.color=c; if(pill) pill.style.background='rgba('+rgb+',0.12)';
  };

  window.rzSleepChangeGoal=function(d){
    S.goalH=Math.max(6,Math.min(12,S.goalH+d));
    var e=document.getElementById('sl-goal-display'); if(e) e.textContent=bn(S.goalH)+' ঘণ্টা';
    rzSleepUpdateDuration(); renderChart();
  };

  window.rzSaveSleepLog=function(){
    var st=document.getElementById('sl-sleep-time'),wt=document.getElementById('sl-wake-time'); if(!st||!wt) return;
    var mins=calcDur(st.value,wt.value),today=todayStr();
    var row={kid_id:S.kidId,date:today,sleep_time:st.value,wake_time:wt.value,duration_minutes:mins,quality:S.quality,goal_hours:S.goalH};
    var btn=document.querySelector('button[onclick="rzSaveSleepLog()"]');
    if(btn){btn.textContent='Saving...';btn.disabled=true;}
    function onSaved(){
      var ex=S.logs.findIndex(function(l){return l.date===today;}); if(ex>=0) S.logs[ex]=Object.assign({},S.logs[ex],row); else S.logs.unshift(row);
      renderAll();
      if(btn){btn.textContent='সংরক্ষিত ✓';btn.disabled=false;btn.style.background='linear-gradient(135deg,#FFB800,#FF8A00)';
        setTimeout(function(){btn.textContent='আজকের ঘুম Save করুন ✓';btn.style.background='linear-gradient(135deg,#FF8A00,#FFB800)';},2500);}
    }
    if(!window._sb||!S.kidId){onSaved();return;}
    window._sb.from('sleep_logs').upsert(row,{onConflict:'kid_id,date'}).then(function(r){
      if(r&&r.error){if(btn){btn.textContent='Error';btn.disabled=false;btn.style.background='linear-gradient(135deg,#ef4444,#dc2626)';}return;}
      onSaved();
    });
  };

  // ── Countdown — English digits, white text, single timer ─────
  function renderCountdown() {
    var el=document.getElementById('asl-countdown'); if(!el) return;
    if(window._rzCdRef){clearInterval(window._rzCdRef);window._rzCdRef=null;}
    var bedH=(24+6-S.goalH)%24;

    function tick() {
      var el2=document.getElementById('asl-countdown'); if(!el2) return;
      var today=todayStr(), tLog=S.logs.find(function(l){return l.date===today;});
      if(tLog&&tLog.duration_minutes>=S.goalH*60){
        el2.innerHTML=
          '<div style="background:linear-gradient(135deg,rgba(255,138,0,0.1),rgba(255,184,0,0.05));border-radius:16px;padding:14px 16px;display:flex;align-items:center;gap:12px">'+
          ic('check','#FF8A00',24)+
          '<div><div style="font-size:13px;font-weight:700;color:#FF8A00">আজকের ঘুম লগ করা হয়েছে!</div>'+
          '<div style="font-size:11px;color:var(--text2,#888)">ভালো ঘুমের জন্য শুভকামনা</div></div></div>';
        clearInterval(window._rzCdRef); window._rzCdRef=null; return;
      }
      var now=new Date(), bed=new Date();
      bed.setHours(bedH,0,0,0); if(bed<=now) bed.setDate(bed.getDate()+1);
      var diff=Math.floor((bed-now)/1000);
      var h=Math.floor(diff/3600), m=Math.floor((diff%3600)/60), s=diff%60;
      var urgency=(h===0&&m<30), color=urgency?'#ef4444':'#FF8A00';

      el2.innerHTML=
        '<div style="background:linear-gradient(135deg,rgba(255,138,0,0.08),rgba(255,184,0,0.04));border-radius:16px;padding:14px 16px;display:flex;align-items:center;justify-content:space-between">'+
          '<div style="display:flex;align-items:center;gap:10px">'+
            ic(urgency?'bell':'moon',color,22)+
            '<div>'+
              '<div style="font-size:12px;font-weight:700;color:'+color+'">'+(urgency?'ঘুমানোর সময় হয়ে গেছে!':'ঘুমানোর সময় কাউন্টডাউন')+'</div>'+
              '<div style="font-size:10px;color:var(--text,#1f2937);opacity:.75">রাত '+pad(bedH)+':০০ এ ঘুমানোর লক্ষ্য</div>'+
            '</div>'+
          '</div>'+
          '<div style="text-align:right">'+
            '<div style="font-family:\'Barlow Condensed\',\'Space Grotesk\',sans-serif;font-size:26px;font-weight:800;letter-spacing:0.5px;color:'+color+'">'+
              pad(h)+'<span style="font-size:14px;font-weight:700;color:var(--text,#1f2937);opacity:.85">h</span> '+
              pad(m)+'<span style="font-size:14px;font-weight:700;color:var(--text,#1f2937);opacity:.85">m</span> '+
              pad(s)+'<span style="font-size:14px;font-weight:700;color:var(--text,#1f2937);opacity:.85">s</span>'+
            '</div>'+
            '<div style="font-size:9px;color:var(--text,#1f2937);opacity:.75;margin-top:1px">বাকি আছে</div>'+
          '</div>'+
        '</div>';
    }
    tick();
    window._rzCdRef=setInterval(tick,1000);
  }

  // ── Stats ────────────────────────────────────────────────────
  function renderStats() {
    var el=document.getElementById('sl-stats'); if(!el) return;
    var streak=calcStreak(), avg=calcAvg();
    var stats=[
      {name:'trend',color:'#FF8A00',value:bn(streak)+' দিন',label:'ঘুমের Streak'},
      {name:'clock',color:'#FF8A00',value:avg>0?bn(Math.floor(avg/60))+'ঘ '+bn(avg%60)+'ম':'—',label:'৭ দিনের গড়'},
      {name:'ok',   color:'#FF8A00',value:bn(S.goalH)+' ঘণ্টা',label:'দৈনিক লক্ষ্য'}
    ];
    el.innerHTML=stats.map(function(s){
      return '<div style="background:var(--card,#fff);border-radius:14px;padding:12px 10px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,.06)">'+
        '<div style="display:flex;justify-content:center;margin-bottom:4px">'+ic(s.name,s.color,16)+'</div>'+
        '<div style="font-size:15px;font-weight:800;color:'+s.color+'">'+s.value+'</div>'+
        '<div style="font-size:10px;color:var(--text2,#888);margin-top:2px">'+s.label+'</div></div>';
    }).join('');
  }

  // ── Chart ────────────────────────────────────────────────────
  function renderChart() {
    var el=document.getElementById('sl-weekly-chart'); if(!el) return;
    var gm=S.goalH*60, days=['রবি','সোম','মঙ্গল','বুধ','বৃহঃ','শুক্র','শনি'];
    var entries=last7().map(function(ds){var l=S.logs.find(function(x){return x.date===ds;});return{day:days[new Date(ds).getDay()],mins:l?l.duration_minutes:0,date:ds};});
    var maxH=100, maxM=Math.max(gm*1.2,Math.max.apply(null,entries.map(function(e){return e.mins||1;})));
    var glp=Math.round((gm/maxM)*maxH);
    var bars=entries.map(function(e){
      var bh=Math.max(4,Math.round(Math.min(1,e.mins/maxM)*maxH)), isT=e.date===todayStr();
      // Goal met → orange, near → yellow, low → red
      var c=e.mins===0?'var(--border,#e5e7eb)':(e.mins>=gm?'#FF8A00':(e.mins>=gm*.75?'#f59e0b':'#ef4444'));
      return '<div style="display:flex;flex-direction:column;align-items:center;flex:1;gap:4px">'+
        '<div style="font-size:9px;font-weight:700;color:'+(e.mins>=gm?'#FF8A00':'var(--text2,#888)')+'">'+
        (e.mins?bn(Math.floor(e.mins/60))+'ঘ':'—')+'</div>'+
        '<div style="width:100%;display:flex;align-items:flex-end;justify-content:center;height:'+maxH+'px">'+
          '<div style="width:70%;border-radius:6px 6px 3px 3px;background:'+c+';height:'+bh+'px;'+(isT?'box-shadow:0 0 0 2px #FF8A00;':'')+'transition:height .4s ease"></div></div>'+
        '<div style="font-size:10px;font-weight:'+(isT?'800':'500')+';color:'+(isT?'#FF8A00':'var(--text2,#888)')+'">'+e.day+'</div></div>';
    }).join('');
    el.innerHTML='<div style="position:relative"><div style="position:absolute;bottom:'+(glp+22)+'px;left:0;right:0;border-top:1.5px dashed rgba(255,138,0,0.4)"><span style="position:absolute;right:0;top:-10px;font-size:9px;color:#FF8A00;background:var(--card,#fff);padding:0 3px">লক্ষ্য</span></div>'+
      '<div style="display:flex;gap:4px;padding-top:18px">'+bars+'</div></div>'+
      '<div style="display:flex;gap:12px;margin-top:12px;justify-content:center">'+
        '<div style="display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text2,#888)"><div style="width:10px;height:10px;border-radius:2px;background:#FF8A00"></div>লক্ষ্য পূরণ</div>'+
        '<div style="display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text2,#888)"><div style="width:10px;height:10px;border-radius:2px;background:#f59e0b"></div>কাছাকাছি</div>'+
        '<div style="display:flex;align-items:center;gap:4px;font-size:10px;color:var(--text2,#888)"><div style="width:10px;height:10px;border-radius:2px;background:#ef4444"></div>কম</div></div>';
  }

  // ── Insight ──────────────────────────────────────────────────
  function renderInsight() {
    var el=document.getElementById('sl-insight'); if(!el) return;
    var gm=S.goalH*60, streak=calcStreak(), avg=calcAvg();
    var yDate=new Date(); yDate.setDate(yDate.getDate()-1);
    var yds=yDate.getFullYear()+'-'+String(yDate.getMonth()+1).padStart(2,'0')+'-'+String(yDate.getDate()).padStart(2,'0');
    var tDate=new Date(); tDate.setDate(tDate.getDate()-2);
    var tds=tDate.getFullYear()+'-'+String(tDate.getMonth()+1).padStart(2,'0')+'-'+String(tDate.getDate()).padStart(2,'0');
    var yL=S.logs.find(function(l){return l.date===yds;}), tL=S.logs.find(function(l){return l.date===tds;});
    var iname, color, msg;
    if(streak>=7){iname='trophy';color='#FFB800';msg='অসাধারণ! টানা '+bn(streak)+' দিন লক্ষ্য পূরণ। তুমি Dream Champion!';}
    else if(streak>=3){iname='flame';color='#FF8A00';msg='দারুণ! টানা '+bn(streak)+' দিন ভালো ঘুম। চালিয়ে যাও!';}
    else if(yL&&tL&&yL.duration_minutes<tL.duration_minutes){iname='moon';color='#f59e0b';msg='কাল '+bn(Math.abs(tL.duration_minutes-yL.duration_minutes))+' মিনিট কম ঘুমিয়েছ। আজ তাড়াতাড়ি ঘুমাও!';}
    else if(yL&&yL.duration_minutes>=gm){iname='zap';color='#FF8A00';msg='গতকাল লক্ষ্য পূরণ হয়েছে! আজও ভালো ঘুমাও।';}
    else if(yL&&yL.duration_minutes<gm*.75){var sh=Math.round(gm-yL.duration_minutes);iname='alert';color='#ef4444';msg='গতকাল '+bn(Math.floor(sh/60))+'ঘ '+bn(sh%60)+'ম কম ঘুম। আজ তাড়াতাড়ি ঘুমাও!';}
    else if(avg>0&&avg<gm){iname='moon';color='#FF8A00';msg='এই সপ্তাহে গড় ঘুম লক্ষ্যের চেয়ে কম। রাত '+bn(S.goalH<=8?10:9)+' টার আগে ঘুমানোর চেষ্টা করো।';}
    else{iname='moon';color='#FF8A00';msg='প্রতিদিন '+bn(S.goalH)+' ঘণ্টা ঘুমালে শরীর ও মন ভালো থাকে!';}
    el.innerHTML='<div style="background:var(--card,#fff);border-radius:16px;padding:14px 16px;box-shadow:0 1px 4px rgba(0,0,0,.06);border-left:4px solid '+color+';display:flex;align-items:flex-start;gap:12px">'+
      '<div style="flex-shrink:0;margin-top:2px">'+ic(iname,color,24)+'</div>'+
      '<div><div style="font-size:11px;font-weight:700;color:'+color+';margin-bottom:3px">স্মার্ট পরামর্শ</div>'+
      '<div style="font-size:13px;color:var(--text,#1f2937);line-height:1.5">'+msg+'</div></div></div>';
  }

  // ── Achievements ─────────────────────────────────────────────
  function renderAchievements() {
    var el=document.getElementById('sl-achievements'); if(!el) return;
    var gm=S.goalH*60, streak=calcStreak();
    var wl=last7().map(function(ds){return S.logs.find(function(l){return l.date===ds;});}).filter(Boolean);
    var wgd=wl.filter(function(l){return l.duration_minutes>=gm;}).length;
    var ebd=wl.filter(function(l){if(!l.sleep_time)return false;var h=parseInt(l.sleep_time.slice(0,2),10),m2=parseInt(l.sleep_time.slice(3,5)||0,10),t=h*60+m2;return t<22*60||t>=23*60;}).length;
    var sd=wl.filter(function(l){return l.quality===3;}).length;
    var badges=[
      {icon:'sunrise',color:'#FF8A00',title:'Early Bird',     desc:'রাত ১০টার আগে ঘুমানো',   unlocked:ebd>=3,  progress:Math.min(3,ebd), total:3},
      {icon:'trophy', color:'#FFB800',title:'Dream Champion', desc:'টানা ৭ দিন লক্ষ্য পূরণ', unlocked:streak>=7,progress:Math.min(7,streak),total:7},
      {icon:'star',   color:'#FFB800',title:'Star Sleeper',   desc:'৩ রাত দারুণ ঘুম',         unlocked:sd>=3,   progress:Math.min(3,sd),  total:3},
      {icon:'target', color:'#FF8A00',title:'Consistent',     desc:'৭ দিনে ৫ দিন লক্ষ্য পূরণ',unlocked:wgd>=5, progress:Math.min(5,wgd),total:5}
    ];
    el.innerHTML=badges.map(function(b){
      var pct=Math.round((b.progress/b.total)*100);
      return '<div style="padding:12px;border-radius:14px;border:1.5px solid '+(b.unlocked?b.color:'var(--border,#e5e7eb)')+';background:'+(b.unlocked?'linear-gradient(135deg,rgba(255,184,0,0.08),rgba(255,138,0,0.05))':'var(--bg,#f9fafb)')+'">'+
        '<div style="margin-bottom:7px;'+(b.unlocked?'':'opacity:0.3')+'">'+ic(b.icon,b.unlocked?b.color:'var(--text2,#aaa)',28)+'</div>'+
        '<div style="font-size:12px;font-weight:700;color:'+(b.unlocked?b.color:'var(--text,#1f2937)')+'">'+b.title+'</div>'+
        '<div style="font-size:10px;color:var(--text2,#888);margin:3px 0 8px">'+b.desc+'</div>'+
        '<div style="background:var(--border,#e5e7eb);border-radius:4px;height:4px;overflow:hidden"><div style="background:'+(b.unlocked?'linear-gradient(90deg,#FFB800,#FF8A00)':'rgba(255,138,0,0.4)')+';height:100%;width:'+pct+'%;border-radius:4px;transition:width .6s ease"></div></div>'+
        '<div style="font-size:9px;color:var(--text2,#888);margin-top:4px">'+bn(b.progress)+' / '+bn(b.total)+'</div></div>';
    }).join('');
  }

  // ── Page Load: standalone, no chaining ──────────────────────
  window.rzSleepPageLoad = function() {
    if(window._rzCdRef){clearInterval(window._rzCdRef);window._rzCdRef=null;}
    var kids=window.rzKids||[];
    S.goalH=S.goalH||8;
    if(!S.kidId&&kids.length) S.kidId=kids[0].id;
    if(!kids.length&&window._sb&&window.sbUser){
      window._sb.from('kids').select('*').eq('parent_id',window.sbUser.id).order('created_at')
        .then(function(r){window.rzKids=(r&&r.data)||[];if(!S.kidId&&window.rzKids.length) S.kidId=window.rzKids[0].id;renderKidTabs();loadData();});
      return;
    }
    renderKidTabs();
    loadData();
  };

  setSleepQuality(2);

})();


