var DUA_CAT_LABEL = {daily:'দৈনিক দোয়া', emergency:'Emergency দোয়া', occasion:'বিশেষ দোয়া'};
var DUA_HDR_GRAD  = {daily:'linear-gradient(135deg,#FF8A00,#FFB800)', emergency:'linear-gradient(135deg,#EF4444,#dc2626)', occasion:'linear-gradient(135deg,#8B5CF6,#7c3aed)'};

var _duaCat = 'all';
var _duaCurId = null;
var _quiz = {qs:[], idx:0, score:0, quizXP:0};

/* ── Storage ── */
function xpGet(){ try{return +localStorage.getItem('_duaXP')||0;}catch(e){return 0;} }
function xpSet(v){ try{localStorage.setItem('_duaXP',v);}catch(e){} }
function learnedGet(){ try{return JSON.parse(localStorage.getItem('_duaLearned')||'[]');}catch(e){return[];} }
function learnedSave(){ var ids=DUA_DATA.filter(function(d){return d.learned;}).map(function(d){return d.id;}); try{localStorage.setItem('_duaLearned',JSON.stringify(ids));}catch(e){} }
function learnedLoad(){ var ids=learnedGet(); DUA_DATA.forEach(function(d){d.learned=ids.indexOf(d.id)>=0;}); }
function streak28Get(){ try{return JSON.parse(localStorage.getItem('_duaS28')||'[]');}catch(e){return[];} }
function streak28Mark(){ var days=streak28Get(),today=new Date().toISOString().slice(0,10); if(days.indexOf(today)<0){days.push(today);try{localStorage.setItem('_duaS28',JSON.stringify(days));}catch(e){}} }
function streakCalc(){ var days=streak28Get(),s=0,d=new Date(); while(true){var k=d.toISOString().slice(0,10);if(days.indexOf(k)>=0){s++;d.setDate(d.getDate()-1);}else break;} return s; }

/* ── Level helpers ── */
function lvFor(xp){ var l=DUA_LEVELS[0]; for(var i=0;i<DUA_LEVELS.length;i++){if(xp>=DUA_LEVELS[i].min)l=DUA_LEVELS[i];} return l; }
function lvNext(xp){ var cur=lvFor(xp); for(var i=0;i<DUA_LEVELS.length;i++){if(DUA_LEVELS[i].min>cur.min)return DUA_LEVELS[i];} return null; }

/* ── XP toast ── */
function xpToast(msg){ var t=document.createElement('div'); t.style.cssText='position:fixed;bottom:110px;left:50%;transform:translateX(-50%);background:#7c3aed;color:#fff;padding:10px 22px;border-radius:50px;font-size:14px;font-weight:700;z-index:99999;transition:opacity .5s;pointer-events:none;font-family:inherit'; t.textContent=msg; document.body.appendChild(t); setTimeout(function(){t.style.opacity='0';setTimeout(function(){t.remove();},500);},1600); }

/* ── Stats ── */
function duaUpdateStats(){
  var done=DUA_DATA.filter(function(d){return d.learned;}).length;
  var total=DUA_DATA.length;
  var pct=Math.round(done/total*100);
  var xp=xpGet();
  var lv=lvFor(xp), nlv=lvNext(xp);
  var $=function(i){return document.getElementById(i);};
  if($('dua-mem-val')) $('dua-mem-val').textContent=done;
  if($('dua-pct-val')) $('dua-pct-val').textContent=pct+'%';
  if($('dua-ring'))    $('dua-ring').setAttribute('stroke-dasharray',pct+' '+(100-pct));
  if($('dua-lv-val'))  $('dua-lv-val').textContent=lv.name;
  if($('dua-xp-stat')) $('dua-xp-stat').textContent=xp+' XP';
  if($('dua-lv-name')) $('dua-lv-name').textContent=lv.name;
  if($('dua-lv-name')) $('dua-lv-name').style.color=lv.color;
  var bar=$('dua-xp-bar'), xtxt=$('dua-xp-txt');
  if(nlv){ var pctXP=Math.round((xp-lv.min)/(nlv.min-lv.min)*100); if(bar)bar.style.width=Math.min(100,pctXP)+'%'; if(bar)bar.style.background='linear-gradient(90deg,'+lv.color+','+nlv.color+')'; if(xtxt)xtxt.textContent=xp+' / '+nlv.min+' XP'; }
  else{ if(bar)bar.style.width='100%'; if(xtxt)xtxt.textContent=xp+' XP (Max!)'; }
}

/* ── Featured ── */
function duaRenderFeatured(){
  var idx=new Date().getDate()%DUA_DATA.length, d=DUA_DATA[idx];
  var months=['জান','ফেব','মার','এপ্র','মে','জুন','জুল','আগ','সেপ','অক্ট','নভ','ডিস'];
  var now=new Date(), $=function(i){return document.getElementById(i);};
  if($('dua-feat-arabic'))  $('dua-feat-arabic').textContent=d.arabic;
  if($('dua-feat-pron'))    $('dua-feat-pron').textContent=d.pron;
  if($('dua-feat-title'))   $('dua-feat-title').textContent=d.title;
  if($('dua-feat-meaning')) $('dua-feat-meaning').textContent=d.meaning;
  if($('dua-feat-date'))    $('dua-feat-date').textContent=now.getDate()+' '+months[now.getMonth()];
}

/* ── Daily challenge ── */
function duaRenderChallenge(){
  var unlearned=DUA_DATA.filter(function(d){return !d.learned;});
  var card=document.getElementById('dua-challenge');
  if(!card) return;
  if(!unlearned.length){ card.style.display='none'; return; }
  var idx=new Date().getDate()%unlearned.length, target=unlearned[idx];
  card.style.display='';
  card.onclick=function(){ duaOpen(target.id); };
  var t=document.getElementById('dua-ch-title'), a=document.getElementById('dua-ch-arabic');
  if(t) t.textContent=target.title;
  if(a) a.textContent=target.arabic.substring(0,55)+(target.arabic.length>55?'…':'');
}

/* ── Streak calendar ── */
function duaRenderStreak(){
  var cal=document.getElementById('dua-streak-cal'); if(!cal) return;
  var days=streak28Get(), s=streakCalc();
  var lbl=document.getElementById('dua-streak-lbl'); if(lbl) lbl.textContent=s+' দিন';
  var sv=document.getElementById('dua-streak-val'); if(sv) sv.textContent=s;
  cal.innerHTML='';
  for(var i=29;i>=0;i--){
    var d=new Date(); d.setDate(d.getDate()-i);
    var key=d.toISOString().slice(0,10);
    var active=days.indexOf(key)>=0;
    var cell=document.createElement('div');
    cell.style.cssText='height:18px;border-radius:3px;background:'+(active?'#FF8A00':'var(--border,#e5e7eb)')+';transition:.3s';
    cell.title=key;
    cal.appendChild(cell);
  }
}

/* ── Render list ── */
function duaRender(){
  var list=document.getElementById('dua-list'); if(!list) return;
  var q=((document.getElementById('dua-search')||{}).value||'').toLowerCase().trim();
  var filtered=DUA_DATA.filter(function(d){
    if(_duaCat==='learned') return d.learned;
    if(_duaCat!=='all' && d.cat!==_duaCat) return false;
    if(q && d.title.indexOf(q)<0 && d.pron.toLowerCase().indexOf(q)<0 && d.arabic.indexOf(q)<0) return false;
    return true;
  });
  var lbl=document.getElementById('dua-count-lbl'); if(lbl) lbl.textContent=filtered.length+'টি দোয়া';
  list.innerHTML='';
  filtered.forEach(function(d){
    var row=document.createElement('div');
    row.className='dua-row'+(d.learned?' rd':'');
    row.onclick=function(){ duaOpen(d.id); };

    var ic=document.createElement('div');
    ic.style.cssText='width:46px;height:46px;border-radius:12px;background:'+(DUA_CAT_BG[d.cat]||'rgba(22,163,74,.08)')+';display:flex;align-items:center;justify-content:center;flex-shrink:0';
    ic.innerHTML=DUA_CAT_ICON[d.cat]||DUA_CAT_ICON.daily;

    var info=document.createElement('div'); info.style.cssText='flex:1;min-width:0';
    var title=document.createElement('div'); title.style.cssText='font-size:13.5px;font-weight:700;color:var(--text,#1f2937);margin-bottom:3px'; title.textContent=d.title;
    var prev=document.createElement('div'); prev.style.cssText='font-size:12px;color:var(--text2,#999);font-family:\'MuhammadiQuranic\',\'Scheherazade New\',\'Traditional Arabic\',serif;direction:rtl;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:160px'; prev.textContent=d.arabic.substring(0,30)+'…';
    info.appendChild(title); info.appendChild(prev);
    if(d.learned){ var badge=document.createElement('span'); badge.style.cssText='font-size:10px;background:rgba(255,138,0,.12);color:#FF8A00;padding:2px 7px;border-radius:50px;font-weight:700;display:inline-block;margin-top:3px'; badge.textContent='✓ মুখস্থ'; info.appendChild(badge); }

    var chk=document.createElement('button');
    chk.className='dchk'+(d.learned?' on':'');
    chk.onclick=function(e){ e.stopPropagation(); d.learned=!d.learned; if(d.learned){var nx=xpGet()+10;xpSet(nx);xpToast('+10 XP');} learnedSave(); duaUpdateStats(); duaRenderChallenge(); duaRender(); };
    chk.innerHTML=d.learned?'<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>':'';

    row.appendChild(ic); row.appendChild(info); row.appendChild(chk);
    list.appendChild(row);
  });
  duaUpdateStats();
}

/* ── Filter ── */
window.duaFilterCat=function(cat,btn){
  _duaCat=cat;
  document.querySelectorAll('#dua-page .dcat').forEach(function(b){b.classList.remove('on');});
  if(btn) btn.classList.add('on');
  duaRender();
};

/* ── Situational ── */
window.duaOpenSit=function(id){ duaOpen(id); };

/* ── Modal open ── */
window.duaOpen=function(id){
  var d=DUA_DATA.find(function(x){return x.id===id;}); if(!d) return;
  _duaCurId=id;
  var $=function(i){return document.getElementById(i);};
  $('ds-cat').textContent=DUA_CAT_LABEL[d.cat]||'দৈনিক';
  $('ds-title').textContent=d.title;
  $('ds-arabic').textContent=d.arabic;
  $('ds-pron').textContent='উচ্চারণ: '+d.pron;
  $('ds-meaning').textContent=d.meaning;
  $('ds-tip').textContent=d.tip||'এই দোয়াটি প্রতিদিন পড়ার চেষ্টা করো।';
  var hdr=$('dua-sheet-hdr'); if(hdr) hdr.style.background=DUA_HDR_GRAD[d.cat]||'linear-gradient(135deg,#16a34a,#15803d)';
  var lb=$('dua-learn-btn'); if(lb){ lb.textContent=d.learned?'✓ মুখস্থ হয়েছে':'মুখস্থ করলাম'; lb.style.background=d.learned?'linear-gradient(135deg,#7c3aed,#6d28d9)':'linear-gradient(135deg,#FF8A00,#FFB800)'; }
  var tog=$('dua-memo-toggle'); if(tog) tog.checked=false;
  duaMemoMode(false);
  var modal=$('dua-modal'),bg=$('dua-modal-bg'),sheet=$('dua-sheet');
  if(!modal) return;
  modal.style.display='block'; modal.style.pointerEvents='auto';
  if(sheet) sheet.style.transform='translateY(100%)';
  if(bg){bg.style.opacity='0';bg.style.pointerEvents='none';}
  requestAnimationFrame(function(){requestAnimationFrame(function(){
    if(bg){bg.style.opacity='1';bg.style.pointerEvents='auto';}
    if(sheet) sheet.style.transform='translateY(0)';
  });});
  document.body.style.overflow='hidden';
  var sc=$('dua-sheet-scroll'); if(sc) sc.scrollTop=0;
};

window.closeDuaModal=function(){
  var $=function(i){return document.getElementById(i);};
  var modal=$('dua-modal'),bg=$('dua-modal-bg'),sheet=$('dua-sheet');
  if(bg){bg.style.opacity='0';bg.style.pointerEvents='none';}
  if(sheet) sheet.style.transform='translateY(100%)';
  setTimeout(function(){if(modal){modal.style.display='none';modal.style.pointerEvents='none';}document.body.style.overflow='';},400);
};

window.duaMemoMode=function(on){
  var $=function(i){return document.getElementById(i);};
  var track=$('dua-memo-track'),thumb=$('dua-memo-thumb');
  if(track) track.style.background=on?'#16a34a':'var(--border,#ddd)';
  if(thumb) thumb.style.left=on?'23px':'3px';
  var ac=$('ds-arabic-cover'),pc=$('ds-pron-cover');
  if(ac) ac.style.display=on?'flex':'none';
  if(pc) pc.style.display=on?'flex':'none';
};

window.duaReveal=function(section){
  var el=document.getElementById(section==='arabic'?'ds-arabic-cover':'ds-pron-cover');
  if(el) el.style.display='none';
};

window.duaToggleLearn=function(){
  var d=DUA_DATA.find(function(x){return x.id===_duaCurId;}); if(!d) return;
  d.learned=!d.learned;
  if(d.learned){var nx=xpGet()+10;xpSet(nx);xpToast('+10 XP');}
  learnedSave();
  var lb=document.getElementById('dua-learn-btn');
  if(lb){lb.textContent=d.learned?'✓ মুখস্থ হয়েছে':'মুখস্থ করলাম';lb.style.background=d.learned?'linear-gradient(135deg,#7c3aed,#6d28d9)':'linear-gradient(135deg,#FF8A00,#FFB800)';}
  duaUpdateStats(); duaRender(); duaRenderChallenge();
};

window.duaShare=function(){
  var d=DUA_DATA.find(function(x){return x.id===_duaCurId;}); if(!d) return;
  var text='দোয়া: '+d.title+'\n\n'+d.arabic+'\n\n'+d.pron+'\n\n'+d.meaning+'\n\n— Rizers App';
  if(navigator.share){navigator.share({title:d.title,text:text});}
  else if(navigator.clipboard){navigator.clipboard.writeText(text).then(function(){alert('কপি হয়েছে!');});}
};

/* ── Quiz ── */
function shuffle(arr){ var a=arr.slice(); for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;} return a; }

window.duaStartQuiz=function(){
  var pool=shuffle(DUA_DATA).slice(0,10);
  _quiz={qs:pool,idx:0,score:0,quizXP:0};
  var modal=document.getElementById('dua-quiz-modal'),bg=document.getElementById('dua-quiz-bg'),sheet=document.getElementById('dua-quiz-sheet');
  if(!modal) return;
  modal.style.display='block'; modal.style.pointerEvents='auto';
  if(sheet) sheet.style.transform='translateY(100%)';
  if(bg){bg.style.opacity='0';bg.style.pointerEvents='none';}
  requestAnimationFrame(function(){requestAnimationFrame(function(){
    if(bg){bg.style.opacity='1';bg.style.pointerEvents='auto';}
    if(sheet) sheet.style.transform='translateY(0)';
  });});
  document.body.style.overflow='hidden';
  document.getElementById('dq-final').style.display='none';
  duaQuizShow();
};

function duaQuizShow(){
  var q=_quiz.qs[_quiz.idx];
  var $=function(i){return document.getElementById(i);};
  $('dq-arabic').textContent=q.arabic;
  $('dq-score-lbl').textContent='স্কোর: '+_quiz.score;
  $('dq-prog-pill').textContent=(_quiz.idx+1)+'/'+_quiz.qs.length;
  $('dq-prog-bar').style.width=((_quiz.idx+1)/_quiz.qs.length*100)+'%';
  $('dq-result').style.display='none';
  $('dq-next-btn').style.display='none';
  var others=DUA_DATA.filter(function(d){return d.id!==q.id;});
  var wrong=shuffle(others).slice(0,3).map(function(d){return d.meaning;});
  var opts=shuffle([q.meaning].concat(wrong));
  var optsEl=$('dq-opts'); optsEl.innerHTML='';
  opts.forEach(function(opt){
    var btn=document.createElement('button');
    btn.className='dq-opt'; btn.textContent=opt;
    btn.onclick=function(){
      var correct=opt===q.meaning;
      document.querySelectorAll('.dq-opt').forEach(function(b){
        b.onclick=null;
        if(b.textContent===q.meaning) b.classList.add('correct');
        else if(b===btn && !correct) b.classList.add('wrong');
      });
      var res=$('dq-result'); res.style.display='block';
      if(correct){_quiz.score++;_quiz.quizXP+=5;res.style.background='rgba(255,138,0,.15)';res.style.color='#e07000';res.textContent='সঠিক! +5 XP';}
      else{res.style.background='rgba(239,68,68,.12)';res.style.color='#dc2626';res.textContent='ভুল! সঠিক উত্তর দেখো';}
      $('dq-score-lbl').textContent='স্কোর: '+_quiz.score;
      var nxt=$('dq-next-btn'); nxt.style.display='block';
      if(_quiz.idx+1>=_quiz.qs.length) nxt.textContent='ফলাফল দেখো';
    };
    optsEl.appendChild(btn);
  });
}

window.duaQuizNext=function(){
  _quiz.idx++;
  if(_quiz.idx>=_quiz.qs.length){
    var xp=xpGet()+_quiz.quizXP; xpSet(xp); duaUpdateStats();
    var $=function(i){return document.getElementById(i);};
    $('dq-next-btn').style.display='none';
    $('dq-opts').innerHTML='';
    $('dq-result').style.display='none';
    $('dq-arabic').textContent='';
    $('dq-final').style.display='block';
    $('dq-final-score').textContent=_quiz.score+' / '+_quiz.qs.length+' সঠিক';
    $('dq-final-xp').textContent='+'+_quiz.quizXP+' XP অর্জিত!';
  } else { duaQuizShow(); }
};

window.closeDuaQuiz=function(){
  var $=function(i){return document.getElementById(i);};
  var modal=$('dua-quiz-modal'),bg=$('dua-quiz-bg'),sheet=$('dua-quiz-sheet');
  if(bg){bg.style.opacity='0';bg.style.pointerEvents='none';}
  if(sheet) sheet.style.transform='translateY(100%)';
  setTimeout(function(){if(modal){modal.style.display='none';modal.style.pointerEvents='none';}document.body.style.overflow='';},400);
};

