window.toggleLearned=function(i){DUA_DATA[i].learned=!DUA_DATA[i].learned;learnedSave();duaUpdateStats();duaRender();};

/* ── Bootstrap: polls until dua-page HTML is in DOM ── */
function _duaBootstrap(){
  var _dl=document.getElementById('dua-list'); if(!_dl){setTimeout(_duaBootstrap,100);return;}
  learnedLoad();
  streak28Mark();
  duaRenderFeatured();
  duaRenderChallenge();
  duaRenderStreak();
  duaUpdateStats();
  duaRender();
}

var _duaOrig=window.showPage;
window.showPage=function(page){
  _duaOrig(page);
  if(page==='dua') setTimeout(_duaBootstrap, 80);
};

