// ── Adult Daily Dua — Dua Vault ──────────────────────────────────────────────
(function() {
  'use strict';

  var LEARN_KEY = '_duaLearned';
  var STREAK_KEY = 'dua_streak_dates';
  var _adaFilter = 'all';

  function getLearnedSet() {
    try { var arr = JSON.parse(localStorage.getItem(LEARN_KEY) || '[]'); return new Set(arr.map(String)); }
    catch(e) { return new Set(); }
  }

  function getStreakDates() {
    try { return JSON.parse(localStorage.getItem(STREAK_KEY) || '[]'); }
    catch(e) { return []; }
  }

  function calcStreak(dates) {
    var streak = 0;
    for(var i = 0; i < 30; i++) {
      var d2 = new Date(); d2.setDate(d2.getDate() - i);
      if(dates.indexOf(d2.toISOString().slice(0, 10)) !== -1) streak++;
      else break;
    }
    return streak;
  }

  function today() { return new Date().toISOString().slice(0, 10); }

  function escHtml(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

  window.rzRenderAdultDua = function() { render(); };

  function render() {
    renderStats();
    renderFeaturedHero();
    renderStreakCal();
    renderDuaList();
  }

  function renderStats() {
    var learned = getLearnedSet();
    var dates = getStreakDates();
    var streak = calcStreak(dates);
    var total = (window.duaData && window.duaData.length) || 40;
    var pct = total ? Math.round(learned.size / total * 100) : 0;

    var e;
    e = document.getElementById('ada-mem-val'); if(e) e.textContent = learned.size;
    e = document.getElementById('ada-streak-val'); if(e) e.textContent = streak;
    e = document.getElementById('ada-pct-val'); if(e) e.textContent = pct + '%';
    e = document.getElementById('ada-xp-val'); if(e) e.textContent = (learned.size * 10) + ' XP';

    var slbl = document.getElementById('ada-streak-lbl');
    if(slbl) slbl.textContent = streak + ' days';
  }

  function renderFeaturedHero() {
    if(!window.duaData || !window.duaData.length) return;
    var data = window.duaData;
    var dayIdx = Math.floor(Date.now() / 86400000) % data.length;
    var dua = data[dayIdx];
    var dateStr = new Date().toLocaleDateString('en-GB', {day:'numeric',month:'short'});

    var e;
    e = document.getElementById('ada-feat-date'); if(e) e.textContent = dateStr;
    e = document.getElementById('ada-feat-arabic'); if(e) e.textContent = dua.arabic || '';
    e = document.getElementById('ada-feat-pron'); if(e) e.textContent = dua.pron || '';
    e = document.getElementById('ada-feat-title'); if(e) e.textContent = dua.title || '';
    e = document.getElementById('ada-feat-meaning'); if(e) e.textContent = dua.meaning || '';

    window._adaFeatIdx = dayIdx;
  }

  window.adaOpenFeatured = function() {
    if(typeof duaOpen === 'function' && window._adaFeatIdx !== undefined) duaOpen(window._adaFeatIdx);
  };

  function renderStreakCal() {
    var el = document.getElementById('ada-streak-cal');
    if(!el) return;
    var dates = getStreakDates();
    var todayStr = today();
    var html = '';
    for(var i = 29; i >= 0; i--) {
      var d2 = new Date(); d2.setDate(d2.getDate() - i);
      var dt = d2.toISOString().slice(0, 10);
      var done = dates.indexOf(dt) !== -1;
      var isToday = dt === todayStr;
      html += '<div title="' + dt + '" style="aspect-ratio:1;border-radius:4px;background:' +
        (done ? '#FF8A00' : isToday ? 'rgba(255,138,0,0.18)' : 'var(--border,#f0f0f0)') +
        (isToday ? ';outline:1.5px solid rgba(255,138,0,0.5);outline-offset:1px' : '') + '"></div>';
    }
    el.innerHTML = html;
  }

  window.rzAdaSearchDua = function() { renderDuaList(); };

  window.rzAdaFilter = function(cat, btn) {
    _adaFilter = cat;
    document.querySelectorAll('#ada-dua-list ~ * .ada-filt-btn, [id^="ada-filt-"]').forEach(function(b) {
      b.style.background = 'transparent';
      b.style.color = 'var(--text2,#888)';
      b.style.border = '1.5px solid var(--border,#e5e7eb)';
    });
    if(btn) {
      btn.style.background = '#FF8A00';
      btn.style.color = '#fff';
      btn.style.border = '1.5px solid #FF8A00';
    } else {
      var el = document.getElementById('ada-filt-' + cat);
      if(el) { el.style.background = '#FF8A00'; el.style.color = '#fff'; el.style.border = '1.5px solid #FF8A00'; }
    }
    renderDuaList();
  };

  function renderDuaList() {
    var el = document.getElementById('ada-dua-list');
    if(!el || !window.duaData) return;
    var learned = getLearnedSet();
    var q = '';
    var searchEl = document.getElementById('ada-search');
    if(searchEl) q = searchEl.value.trim().toLowerCase();

    var CAT_COLORS = {daily:'#FF8A00', emergency:'#EF4444', occasion:'#8B5CF6'};

    var filtered = window.duaData.filter(function(d) {
      if(_adaFilter === 'learned') return learned.has(String(d.id));
      if(_adaFilter !== 'all' && d.cat !== _adaFilter) return false;
      if(q) return (d.title||'').toLowerCase().indexOf(q) !== -1 || (d.meaning||'').toLowerCase().indexOf(q) !== -1 || (d.pron||'').toLowerCase().indexOf(q) !== -1;
      return true;
    });

    if(!filtered.length) {
      el.innerHTML = '<div style="text-align:center;padding:24px;color:var(--text2,#888);font-size:13px">No duas found</div>';
      return;
    }

    el.innerHTML = filtered.map(function(d) {
      var isLearned = learned.has(String(d.id));
      var col = CAT_COLORS[d.cat] || '#6B7280';
      return '<div onclick="duaOpen(' + d.id + ')" style="display:flex;align-items:flex-start;gap:10px;padding:12px 14px;background:var(--card,#fff);border-radius:14px;border:1.5px solid ' +
        (isLearned ? 'rgba(255,138,0,0.3)' : 'var(--border,#f0f0f0)') +
        (isLearned ? ';border-left:3px solid #FF8A00' : '') +
        ';cursor:pointer">' +
        '<div style="flex:1;min-width:0">' +
          '<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;flex-wrap:wrap">' +
            (d.cat ? '<span style="font-size:9px;font-weight:700;background:' + col + ';color:#fff;padding:2px 7px;border-radius:50px;letter-spacing:.3px">' + escHtml(d.cat) + '</span>' : '') +
            '<span style="font-size:13px;font-weight:700;color:var(--text,#1f2937)">' + escHtml(d.title || '') + '</span>' +
          '</div>' +
          '<div class="rz-quran-font" style="font-size:14px;direction:rtl;text-align:right;color:var(--text2,#666);line-height:1.65;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + escHtml((d.arabic || '').slice(0, 60)) + (d.arabic && d.arabic.length > 60 ? '…' : '') + '</div>' +
        '</div>' +
        (isLearned ? '<div style="width:22px;height:22px;border-radius:50%;background:linear-gradient(135deg,#FF8A00,#FFB800);display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:2px"><svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"><polyline points="20 6 9 17 4 12"/></svg></div>' : '') +
      '</div>';
    }).join('');
  }

  // showPage hook
  var _adaPrev = window.showPage;
  window.showPage = function(page) {
    _adaPrev(page);
    if(page === 'dua') setTimeout(function() {
      var kw = document.getElementById('dua-kids-wrap');
      var aw = document.getElementById('dua-adult-wrap');
      if(window.rzMode === 'forme') {
        if(kw) kw.style.display = 'none';
        if(aw) aw.style.display = 'block';
        if(typeof rzRenderAdultDua === 'function') rzRenderAdultDua();
      } else {
        if(kw) kw.style.display = '';
        if(aw) aw.style.display = 'none';
      }
    }, 80);
  };

})();

