function crCloseModal(id){var el=document.getElementById(id);if(el){el.style.display='none';}}
function crEsc(s){return (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function crFormatDate(s){if(!s)return '';var p=s.split('-');return (p[2]||'')+'/'+(p[1]||'')+'/'+p[0].slice(2);}

