// ===== BUSINESS TRACKER =====
var _bsData=null;
var _bsSelType='';
var _bsSelStage='lead';
var _bsSelStar=3;

function bsGetData(){
  if(!_bsData){
    var raw=localStorage.getItem('_bs_data');
    _bsData=raw?JSON.parse(raw):{bizName:'',bizType:'',clients:[],invoices:[],ideas:[],cashFlow:[]};
  }
  return _bsData;
}
function bsSaveData(d){_bsData=d;localStorage.setItem('_bs_data',JSON.stringify(d));}

function bsCheckMode(){
  var kw=document.getElementById('bs-kids-wrap');
  var aw=document.getElementById('bs-adult-wrap');
  if(!kw||!aw){setTimeout(bsCheckMode,150);return;}
  if(window.rzMode==='forme'){
    kw.style.display='none';aw.style.display='block';bsRender();
  } else {
    kw.style.display='block';aw.style.display='none';
  }
}

function bsHealthScore(d){
  var score=0;
  if(d.bizName) score+=10;
  if(d.bizType) score+=5;
  var closedClients=d.clients.filter(function(c){return c.stage==='closed';}).length;
  if(d.clients.length>0) score+=10;
  if(closedClients>0) score+=15;
  if(closedClients>=3) score+=10;
  if(d.invoices.length>0) score+=10;
  var paid=d.invoices.filter(function(i){return i.status==='paid';}).length;
  if(d.invoices.length>0&&paid/d.invoices.length>=0.5) score+=15;
  if(d.ideas.length>0) score+=10;
  if(d.cashFlow.length>0) score+=15;
  return Math.min(score,100);
}

function bsRender(){
  var d=bsGetData();
  // Hero
  var bn=document.getElementById('bs-biz-name');
  var bt=document.getElementById('bs-biz-type');
  if(bn) bn.innerHTML=(d.bizName||'আপনার ব্যবসার নাম')+' <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.4)" stroke-width="2.5" stroke-linecap="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>';
  if(bt) bt.textContent=d.bizType||'ব্যবসার ধরন বেছে নিন';

  // Calculate revenue from invoices (paid) and cashflow
  var paidAmt=d.invoices.filter(function(i){return i.status==='paid';}).reduce(function(s,i){return s+(i.amount||0);},0);
  var cfIncome=d.cashFlow.reduce(function(s,m){return s+(m.income||0);},0);
  var cfExpense=d.cashFlow.reduce(function(s,m){return s+(m.expense||0);},0);
  var totalRev=paidAmt+cfIncome;
  var profit=totalRev-cfExpense;
  var margin=totalRev>0?Math.round((profit/totalRev)*100):0;

  var pb=document.getElementById('bs-profit-big');
  var mb=document.getElementById('bs-margin-badge');
  var sr=document.getElementById('bs-stat-rev');
  var se=document.getElementById('bs-stat-exp');
  var sc=document.getElementById('bs-stat-clients');
  if(pb){pb.textContent='৳ '+bsFmt(profit);pb.style.color=profit>=0?'#34D399':'#EF4444';}
  if(mb){mb.textContent='মার্জিন: '+margin+'%';mb.style.color=margin>=0?'#34D399':'#EF4444';mb.style.borderColor=margin>=0?'rgba(52,211,153,.35)':'rgba(239,68,68,.35)';mb.style.background=margin>=0?'rgba(16,185,129,.2)':'rgba(239,68,68,.1)';}
  if(sr) sr.textContent='৳'+bsFmt(totalRev);
  if(se) se.textContent='৳'+bsFmt(cfExpense);
  if(sc) sc.textContent=d.clients.length;

  // Health ring
  var score=bsHealthScore(d);
  var ring=document.getElementById('bs-score-ring');
  var snum=document.getElementById('bs-score-num');
  if(ring){var circ=194.78;ring.style.strokeDashoffset=circ-(circ*score/100);}
  if(snum) snum.textContent=score;

  bsRenderPipeline(d);
  bsRenderInvoices(d);
  bsRenderCashFlow(d);
  bsRenderIdeas(d);
  bsRenderTips();
}

function bsFmt(n){
  if(Math.abs(n)>=100000) return (n/100000).toFixed(1)+'L';
  if(Math.abs(n)>=1000) return (n/1000).toFixed(1)+'K';
  return String(n);
}

function bsRenderPipeline(d){
  var el=document.getElementById('bs-pipeline-grid');
  if(!el) return;
  var stages=[
    {key:'lead',label:'🎯 Lead',color:'#6366f1',bg:'rgba(99,102,241,.08)',border:'rgba(99,102,241,.2)'},
    {key:'prospect',label:'💬 Prospect',color:'#F59E0B',bg:'rgba(245,158,11,.08)',border:'rgba(245,158,11,.2)'},
    {key:'negotiation',label:'🤝 নেগোশিয়েশন',color:'#3B82F6',bg:'rgba(59,130,246,.08)',border:'rgba(59,130,246,.2)'},
    {key:'closed',label:'✅ Closed',color:'#10B981',bg:'rgba(16,185,129,.08)',border:'rgba(16,185,129,.2)'}
  ];
  el.innerHTML=stages.map(function(st){
    var clients=d.clients.filter(function(c){return c.stage===st.key;});
    var totalVal=clients.reduce(function(s,c){return s+(c.value||0);},0);
    var cards=clients.map(function(c){
      return '<div style="background:var(--card,#fff);border:1px solid var(--border,#e5e7eb);border-radius:10px;padding:8px 10px;margin-bottom:6px">'+
        '<div style="font-size:12px;font-weight:700;color:var(--text,#1a1a2e);margin-bottom:2px">'+c.name+'</div>'+
        (c.company?'<div style="font-size:10px;color:var(--text2,#888)">'+c.company+'</div>':'')+
        (c.value?'<div style="font-size:11px;color:'+st.color+';font-weight:700;margin-top:3px">৳'+bsFmt(c.value)+'</div>':'')+
        '<div style="display:flex;gap:4px;margin-top:6px">'+
        (st.key!=='closed'?'<button onclick="bsAdvanceClient(\''+c.id+'\')" style="flex:1;padding:4px;background:'+st.color+';color:#fff;border:none;border-radius:6px;font-size:10px;font-weight:700;cursor:pointer">→ পরবর্তী</button>':'')+
        '<button onclick="bsDeleteClient(\''+c.id+'\')" style="padding:4px 8px;background:rgba(239,68,68,.1);color:#EF4444;border:none;border-radius:6px;font-size:10px;cursor:pointer">✕</button>'+
        '</div></div>';
    }).join('');
    return '<div style="background:'+st.bg+';border:1.5px solid '+st.border+';border-radius:14px;padding:10px">'+
      '<div style="font-size:11px;font-weight:800;color:'+st.color+';margin-bottom:4px">'+st.label+'</div>'+
      '<div style="font-size:10px;color:var(--text2,#888);margin-bottom:8px">'+clients.length+' ক্লায়েন্ট'+(totalVal?' • ৳'+bsFmt(totalVal):'')+
      '</div>'+cards+
      '<div style="text-align:center;padding:8px 0;color:var(--text2,#888);font-size:11px;opacity:.5">'+(clients.length===0?'এখানে কেউ নেই':'')+
      '</div></div>';
  }).join('');
}

function bsRenderInvoices(d){
  var el=document.getElementById('bs-invoice-list');
  var today=new Date().toISOString().slice(0,10);
  // Update overdue status
  d.invoices.forEach(function(inv){
    if(inv.status==='pending'&&inv.dueDate&&inv.dueDate<today) inv.status='overdue';
  });
  var pending=d.invoices.filter(function(i){return i.status==='pending';});
  var paid=d.invoices.filter(function(i){return i.status==='paid';});
  var overdue=d.invoices.filter(function(i){return i.status==='overdue';});
  var pAmt=pending.reduce(function(s,i){return s+(i.amount||0);},0);
  var pdAmt=paid.reduce(function(s,i){return s+(i.amount||0);},0);
  var oAmt=overdue.reduce(function(s,i){return s+(i.amount||0);},0);
  var pa=document.getElementById('bs-inv-pending-amt');
  var pda=document.getElementById('bs-inv-paid-amt');
  var oa=document.getElementById('bs-inv-overdue-amt');
  if(pa) pa.textContent='৳'+bsFmt(pAmt);
  if(pda) pda.textContent='৳'+bsFmt(pdAmt);
  if(oa) oa.textContent='৳'+bsFmt(oAmt);
  if(!el) return;
  if(!d.invoices.length){el.innerHTML='<div style="text-align:center;padding:20px;color:var(--text2,#888);font-size:13px">কোনো ইনভয়েস নেই। উপরের বাটন দিয়ে যোগ করুন।</div>';return;}
  var sorted=d.invoices.slice().sort(function(a,b){
    var order={overdue:0,pending:1,paid:2};
    return (order[a.status]||1)-(order[b.status]||1);
  });
  el.innerHTML=sorted.map(function(inv){
    var cfg={pending:{color:'#F59E0B',bg:'rgba(245,158,11,.1)',label:'Pending'},paid:{color:'#10B981',bg:'rgba(16,185,129,.1)',label:'Paid'},overdue:{color:'#EF4444',bg:'rgba(239,68,68,.1)',label:'Overdue'}};
    var c=cfg[inv.status]||cfg.pending;
    return '<div style="background:var(--card,#fff);border:1.5px solid '+(inv.status==='overdue'?'rgba(239,68,68,.3)':'var(--border,#e5e7eb)')+';border-radius:14px;padding:14px;display:flex;align-items:center;gap:12px">'+
      '<div style="width:42px;height:42px;border-radius:12px;background:'+c.bg+';display:flex;align-items:center;justify-content:center;flex-shrink:0">'+
      '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="'+c.color+'" stroke-width="2" stroke-linecap="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>'+
      '</div>'+
      '<div style="flex:1;min-width:0">'+
      '<div style="font-size:13px;font-weight:700;color:var(--text,#1a1a2e)">'+inv.client+'</div>'+
      '<div style="font-size:11px;color:var(--text2,#888);margin-top:1px">'+(inv.note||'')+(inv.dueDate?' • Due: '+inv.dueDate:'')+
      '</div></div>'+
      '<div style="text-align:right;flex-shrink:0">'+
      '<div style="font-size:15px;font-weight:800;color:'+c.color+'">৳'+bsFmt(inv.amount||0)+'</div>'+
      '<span style="display:inline-block;background:'+c.bg+';color:'+c.color+';font-size:9px;font-weight:700;padding:2px 8px;border-radius:10px;margin-top:3px">'+c.label+'</span>'+
      '</div>'+
      (inv.status!=='paid'?'<button onclick="bsMarkPaid(\''+inv.id+'\')" style="padding:6px 10px;background:rgba(16,185,129,.1);color:#10B981;border:none;border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;flex-shrink:0">পেমেন্ট পেয়েছি</button>':'')+
      '<button onclick="bsDeleteInvoice(\''+inv.id+'\')" style="padding:6px 8px;background:rgba(239,68,68,.08);color:#EF4444;border:none;border-radius:8px;font-size:11px;cursor:pointer;flex-shrink:0">✕</button>'+
      '</div>';
  }).join('');
}

function bsRenderCashFlow(d){
  var el=document.getElementById('bs-cf-chart');
  if(!el) return;
  var cf=d.cashFlow||[];
  if(!cf.length){el.innerHTML='<div style="text-align:center;padding:30px 0;color:var(--text2,#888);font-size:13px">কোনো ডেটা নেই।<br>উপরের "মাস যোগ" বাটন দিয়ে শুরু করুন।</div>';return;}
  var sorted=cf.slice().sort(function(a,b){return a.month>b.month?1:-1;}).slice(-6);
  var maxVal=sorted.reduce(function(m,x){return Math.max(m,x.income||0,x.expense||0);},1);
  var barW=22,gap=6,chartH=90,labelH=24,groupGap=16;
  var groupW=barW*2+gap;
  var totalW=sorted.length*(groupW+groupGap);
  var bars=sorted.map(function(m,i){
    var x=i*(groupW+groupGap);
    var incH=Math.max(2,Math.round(((m.income||0)/maxVal)*chartH));
    var expH=Math.max(2,Math.round(((m.expense||0)/maxVal)*chartH));
    var label=m.month.slice(5);
    return '<g transform="translate('+x+',0)">'+
      '<rect x="0" y="'+(chartH-incH)+'" width="'+barW+'" height="'+incH+'" rx="4" fill="#10B981"/>'+
      '<rect x="'+(barW+gap)+'" y="'+(chartH-expH)+'" width="'+barW+'" height="'+expH+'" rx="4" fill="#F59E0B"/>'+
      '<text x="'+(groupW/2)+'" y="'+(chartH+16)+'" text-anchor="middle" font-size="9" fill="var(--text2,#888)">'+label+'</text>'+
      '</g>';
  }).join('');
  el.innerHTML='<svg viewBox="0 0 '+Math.max(totalW,200)+' '+(chartH+labelH)+'" style="width:100%;overflow:visible;display:block">'+bars+'</svg>'+
    '<div style="display:flex;gap:12px;justify-content:flex-end;margin-top:8px">'+
    sorted.map(function(m){return '<div style="font-size:10px;color:var(--text2,#888)">'+m.month.slice(5)+': <span style="color:#10B981;font-weight:700">৳'+bsFmt(m.income||0)+'</span> / <span style="color:#F59E0B;font-weight:700">৳'+bsFmt(m.expense||0)+'</span>'+
      ' <button onclick="bsDeleteCashFlow(\''+m.month+'\')" style="background:none;border:none;color:#EF4444;cursor:pointer;font-size:10px;padding:0 2px">✕</button></div>';}).join('')+'</div>';
}

function bsRenderIdeas(d){
  var el=document.getElementById('bs-ideas-grid');
  if(!el) return;
  if(!d.ideas.length){el.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:24px;color:var(--text2,#888);font-size:13px">কোনো আইডিয়া নেই।<br>উপরের বাটন দিয়ে প্রথম আইডিয়া যোগ করুন।</div>';return;}
  var sorted=d.ideas.slice().sort(function(a,b){return (b.rating||0)-(a.rating||0);});
  el.innerHTML=sorted.map(function(idea){
    var stars='';
    for(var i=1;i<=5;i++) stars+='<span style="font-size:13px;opacity:'+(i<=(idea.rating||0)?'1':'.25')+'">⭐</span>';
    return '<div style="background:var(--card,#fff);border:1.5px solid var(--border,#e5e7eb);border-radius:16px;padding:14px;position:relative">'+
      '<button onclick="bsDeleteIdea(\''+idea.id+'\')" style="position:absolute;top:10px;right:10px;background:none;border:none;color:var(--text2,#bbb);cursor:pointer;font-size:14px;line-height:1">✕</button>'+
      '<div style="font-size:13px;font-weight:800;color:var(--text,#1a1a2e);margin-bottom:4px;padding-right:20px">'+idea.title+'</div>'+
      (idea.desc?'<div style="font-size:11.5px;color:var(--text2,#888);line-height:1.5;margin-bottom:8px">'+idea.desc+'</div>':'')+
      '<div style="display:flex;align-items:center;gap:2px;margin-top:6px">'+stars+'</div>'+
      '</div>';
  }).join('');
}

function bsRenderTips(){
  var el=document.getElementById('bs-tips-list');
  if(!el) return;
  var tips=[
    {icon:'⚖️',text:'সৎ ব্যবসা করুন — পণ্যের দোষ লুকাবেন না। নবী (সা.) বলেছেন: "প্রতারণাকারী আমার উম্মত নয়।"'},
    {icon:'🤝',text:'চুক্তি লিখিত রাখুন। আল্লাহ বলেন: "ঋণের লেনদেন লিখে রাখো।" (সূরা বাকারা: ২৮২)'},
    {icon:'💰',text:'সুদ থেকে বিরত থাকুন। ইসলামে সুদ হারাম। Profit-sharing (মুদারাবা) ব্যবহার করুন।'},
    {icon:'🌱',text:'ব্যবসার আয়ের ২.৫% যাকাত দিন। এতে বরকত বাড়ে এবং সম্পদ পবিত্র হয়।'},
    {icon:'⏰',text:'ওজনে কম দেবেন না। "যারা মাপে কম দেয় তাদের জন্য ধ্বংস।" (সূরা মুতাফফিফিন: ১)'},
  ];
  el.innerHTML=tips.map(function(t){
    return '<div style="background:var(--card,#fff);border:1.5px solid var(--border,#e5e7eb);border-radius:14px;padding:14px;display:flex;gap:12px;align-items:flex-start">'+
      '<div style="font-size:22px;flex-shrink:0;margin-top:1px">'+t.icon+'</div>'+
      '<div style="font-size:13px;color:var(--text,#1a1a2e);line-height:1.6">'+t.text+'</div></div>';
  }).join('');
}

// ── Profile ──
function bsEditProfile(){
  var d=bsGetData();
  _bsSelType=d.bizType||'';
  var ni=document.getElementById('bs-p-name');
  if(ni) ni.value=d.bizName||'';
  var btns=document.querySelectorAll('#bs-type-picker button');
  btns.forEach(function(b){
    var t=b.textContent.trim().replace(/^[^\s]+\s/,'');
    b.style.borderColor=(_bsSelType&&b.textContent.indexOf(_bsSelType)>-1)?'#10B981':'var(--border,#e5e7eb)';
    b.style.background=(_bsSelType&&b.textContent.indexOf(_bsSelType)>-1)?'rgba(16,185,129,.1)':'var(--bg2,#f3f4f6)';
  });
  var m=document.getElementById('bs-profile-modal');
  if(m){m.style.display='flex';}
}
function bsSelType(el,type){
  _bsSelType=type;
  document.querySelectorAll('#bs-type-picker button').forEach(function(b){
    var sel=b===el;
    b.style.borderColor=sel?'#10B981':'var(--border,#e5e7eb)';
    b.style.background=sel?'rgba(16,185,129,.1)':'var(--bg2,#f3f4f6)';
  });
}
function bsSaveProfile(){
  var d=bsGetData();
  var ni=document.getElementById('bs-p-name');
  d.bizName=ni?ni.value.trim():'';
  d.bizType=_bsSelType;
  bsSaveData(d);bsCloseModal('bs-profile-modal');bsRender();
}

// ── Client ──
function bsOpenAddClient(){
  _bsSelStage='lead';
  ['bs-cl-name','bs-cl-company','bs-cl-note'].forEach(function(id){var e=document.getElementById(id);if(e)e.value='';});
  var ve=document.getElementById('bs-cl-value');if(ve)ve.value='';
  document.querySelectorAll('#bs-cl-stage-picker button').forEach(function(b){
    var sel=b.textContent.indexOf('Lead')>-1;
    b.style.borderColor=sel?'#10B981':'var(--border,#e5e7eb)';
    b.style.background=sel?'rgba(16,185,129,.1)':'var(--bg2,#f3f4f6)';
  });
  var m=document.getElementById('bs-client-modal');if(m)m.style.display='flex';
}
function bsSelStage(el,stage){
  _bsSelStage=stage;
  var stageColor={lead:'#6366f1',prospect:'#F59E0B',negotiation:'#3B82F6',closed:'#10B981'};
  var c=stageColor[stage]||'#10B981';
  document.querySelectorAll('#bs-cl-stage-picker button').forEach(function(b){
    var sel=b===el;
    b.style.borderColor=sel?c:'var(--border,#e5e7eb)';
    b.style.background=sel?'rgba(99,102,241,.08)':'var(--bg2,#f3f4f6)';
  });
}
function bsSaveClient(){
  var nm=document.getElementById('bs-cl-name');
  if(!nm||!nm.value.trim()){alert('ক্লায়েন্টের নাম লিখুন।');return;}
  var d=bsGetData();
  d.clients.push({
    id:'cl'+Date.now(),
    name:nm.value.trim(),
    company:(document.getElementById('bs-cl-company')||{}).value||'',
    stage:_bsSelStage||'lead',
    value:parseFloat((document.getElementById('bs-cl-value')||{}).value)||0,
    note:(document.getElementById('bs-cl-note')||{}).value||'',
    date:new Date().toISOString().slice(0,10)
  });
  bsSaveData(d);bsCloseModal('bs-client-modal');bsRender();
}
function bsAdvanceClient(id){
  var order=['lead','prospect','negotiation','closed'];
  var d=bsGetData();
  var c=d.clients.find(function(x){return x.id===id;});
  if(c){var i=order.indexOf(c.stage);if(i<order.length-1)c.stage=order[i+1];}
  bsSaveData(d);bsRender();
}
function bsDeleteClient(id){
  var d=bsGetData();
  d.clients=d.clients.filter(function(c){return c.id!==id;});
  bsSaveData(d);bsRender();
}

// ── Invoice ──
function bsOpenAddInvoice(){
  ['bs-inv-client','bs-inv-amount','bs-inv-note'].forEach(function(id){var e=document.getElementById(id);if(e)e.value='';});
  var de=document.getElementById('bs-inv-due');if(de)de.value='';
  var m=document.getElementById('bs-invoice-modal');if(m)m.style.display='flex';
}
function bsSaveInvoice(){
  var ce=document.getElementById('bs-inv-client');
  var ae=document.getElementById('bs-inv-amount');
  if(!ce||!ce.value.trim()||!ae||!ae.value){alert('ক্লায়েন্ট ও পরিমাণ লিখুন।');return;}
  var d=bsGetData();
  var due=(document.getElementById('bs-inv-due')||{}).value||'';
  var today=new Date().toISOString().slice(0,10);
  d.invoices.push({
    id:'inv'+Date.now(),
    client:ce.value.trim(),
    amount:parseFloat(ae.value)||0,
    dueDate:due,
    note:(document.getElementById('bs-inv-note')||{}).value||'',
    status:(due&&due<today)?'overdue':'pending',
    date:today
  });
  bsSaveData(d);bsCloseModal('bs-invoice-modal');bsRender();
}
function bsMarkPaid(id){
  var d=bsGetData();
  var inv=d.invoices.find(function(i){return i.id===id;});
  if(inv) inv.status='paid';
  bsSaveData(d);bsRender();
}
function bsDeleteInvoice(id){
  var d=bsGetData();
  d.invoices=d.invoices.filter(function(i){return i.id!==id;});
  bsSaveData(d);bsRender();
}

// ── Cash Flow ──
function bsOpenAddCashFlow(){
  var me=document.getElementById('bs-cf-month');
  if(me){var now=new Date();me.value=now.getFullYear()+'-'+(String(now.getMonth()+1).padStart(2,'0'));}
  ['bs-cf-income','bs-cf-expense'].forEach(function(id){var e=document.getElementById(id);if(e)e.value='';});
  var m=document.getElementById('bs-cf-modal');if(m)m.style.display='flex';
}
function bsSaveCashFlow(){
  var me=document.getElementById('bs-cf-month');
  if(!me||!me.value){alert('মাস বেছে নিন।');return;}
  var d=bsGetData();
  var existing=d.cashFlow.find(function(x){return x.month===me.value;});
  var inc=parseFloat((document.getElementById('bs-cf-income')||{}).value)||0;
  var exp=parseFloat((document.getElementById('bs-cf-expense')||{}).value)||0;
  if(existing){existing.income=inc;existing.expense=exp;}
  else d.cashFlow.push({month:me.value,income:inc,expense:exp});
  bsSaveData(d);bsCloseModal('bs-cf-modal');bsRender();
}
function bsDeleteCashFlow(month){
  var d=bsGetData();
  d.cashFlow=d.cashFlow.filter(function(x){return x.month!==month;});
  bsSaveData(d);bsRender();
}

