function zkSaveLoan(){
  var fromEl=document.getElementById('zk-loan-from');
  var amtEl=document.getElementById('zk-loan-amount');
  var from=fromEl?fromEl.value.trim():'';
  var amt=parseFloat(amtEl?amtEl.value:0)||0;
  if(!from){alert('কার কাছে ঋণ তা লিখুন');return;}
  if(!amt){alert('পরিমাণ লিখুন');return;}
  var d=zkGetData();
  if(!d.loans) d.loans=[];
  d.loans.push({id:Date.now(),from:from,amount:amt,type:_zkLoanType});
  zkSaveData(d);
  zkCloseLoanModal();
  zkRenderLoans();
  zkRecalc();
}

function zkDeleteLoan(id){
  var d=zkGetData();
  d.loans=(d.loans||[]).filter(function(l){return l.id!==id;});
  zkSaveData(d);
  zkRenderLoans();
  zkRecalc();
}

