      '</div>'+
      '<div style="text-align:right;margin-right:8px">'+
        '<div style="font-size:15px;font-weight:900;color:#EF4444">'+zkFmt(l.amount)+'</div>'+
      '</div>'+
      '<button onclick="zkDeleteLoan('+l.id+')" style="width:30px;height:30px;border-radius:8px;border:none;background:rgba(239,68,68,.1);color:#EF4444;font-size:16px;cursor:pointer;flex-shrink:0">×</button>'+
    '</div>';
