// ===== FITNESS TRACKER =====
var _ftData=null;
var _ftWType='';var _ftWTypeIcon='';var _ftWTypeColor='';
var _ftCalPerMin={cardio:8,strength:5,hiit:10,yoga:3,sports:7,walk:4};

function ftTodayKey(){
  var d=new Date();
  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
}

function ftGetData(){
  if(!_ftData){
    try{
      var s=localStorage.getItem('_ft_data');
      _ftData=s?JSON.parse(s):ftDefaultData();
    }catch(e){ _ftData=ftDefaultData(); }
  }
  var today=ftTodayKey();
  if(_ftData.todayDate!==today){
    // Archive previous day
    if(_ftData.todayDate&&(_ftData.today.steps||_ftData.today.caloriesBurned||_ftData.today.water)){
      if(!_ftData.history) _ftData.history=[];
      _ftData.history.unshift({date:_ftData.todayDate,steps:_ftData.today.steps,water:_ftData.today.water,caloriesBurned:_ftData.today.caloriesBurned,activeMinutes:_ftData.today.activeMinutes,workouts:(_ftData.today.workouts||[]).length});
      if(_ftData.history.length>30) _ftData.history=_ftData.history.slice(0,30);
    }
    _ftData.todayDate=today;
    _ftData.today={steps:0,water:0,workouts:[],caloriesBurned:0,activeMinutes:0};
    ftSaveData(_ftData);
  }
  return _ftData;
}

function ftDefaultData(){
  return {
    todayDate:'',
    today:{steps:0,water:0,workouts:[],caloriesBurned:0,activeMinutes:0},
    profile:{weight:0,height:0,age:0,gender:'male',goal:'maintain'},
    prs:[
      {key:'pushups',label:'সর্বোচ্চ পুশআপ',unit:'টি',icon:'🔼',value:0,date:''},
      {key:'pullups',label:'সর্বোচ্চ পুলআপ',unit:'টি',icon:'💪',value:0,date:''},
      {key:'plank',label:'সর্বোচ্চ প্লাঙ্ক',unit:'সেকেন্ড',icon:'⏱️',value:0,date:''},
      {key:'run5k',label:'৫ কিমি দৌড়',unit:'মিনিট',icon:'🏃',value:0,date:''},
      {key:'squat',label:'সর্বোচ্চ স্কোয়াট',unit:'কেজি',icon:'🏋️',value:0,date:''}
    ],
    history:[]
  };
}

function ftSaveData(d){ _ftData=d; try{localStorage.setItem('_ft_data',JSON.stringify(d));}catch(e){} }

function ftCheckMode(){
  var kids=document.getElementById('ft-kids-wrap');
  var adult=document.getElementById('ft-adult-wrap');
  if(!kids){setTimeout(function(){ftCheckMode();},150);return;}
  var isAdult=(typeof rzMode!=='undefined'?rzMode:'kids')==='forme';
  kids.style.display=isAdult?'none':'block';
  adult.style.display=isAdult?'block':'none';
  if(isAdult) ftRender();
}

function ftRender(){
  var d=ftGetData();
  var si=document.getElementById('ft-steps-input');
  if(si) si.value=d.today.steps||0;
  ftUpdateStepsUI(d.today.steps||0);
  ftRenderRings(d);
  ftRenderBMI(d);
  ftRenderWater(d);
  ftRenderWorkouts(d);
  ftRenderWeekly(d);
  ftRenderPRs(d);
  ftUpdateHeroStats(d);
  ftRenderSmartCard(d);
  ftRenderTodayPlan(d);
  ftRenderNutrition(d);
  ftRenderSleep(d);
  ftRenderMeasurements(d);
  ftRenderInsights(d);
}

function ftUpdateHeroStats(d){
  var today=d.today;
  var streak=ftCalcStreak(d);
  var sw=document.getElementById('ft-stat-streak'); if(sw) sw.textContent=streak;
  var ww=document.getElementById('ft-stat-workouts'); if(ww) ww.textContent=(today.workouts||[]).length;
  var wt=document.getElementById('ft-stat-water'); if(wt) wt.textContent=(today.water||0)+'/8';
  var hc=document.getElementById('ft-hero-cal'); if(hc) hc.textContent=today.caloriesBurned||0;
  var ha=document.getElementById('ft-hero-active'); if(ha) ha.textContent=today.activeMinutes||0;
  var hs=document.getElementById('ft-hero-steps'); if(hs) hs.textContent=(today.steps||0).toLocaleString('bn-BD');
}

function ftCalcStreak(d){
  var streak=0;
  var today=ftTodayKey();
  var h=d.history||[];
  // Check if today has activity
  var todayActive=(d.today.steps>=5000)||(d.today.workouts&&d.today.workouts.length>0);
  if(todayActive) streak=1;
  // Check past days
  for(var i=0;i<h.length;i++){
    var diff=Math.round((new Date(today)-new Date(h[i].date))/(24*60*60*1000));
    if(diff===streak&&(h[i].steps>=5000||h[i].workouts>0)){streak++;}
    else if(diff>streak) break;
  }
  return streak;
}

function ftRenderRings(d){
  var today=d.today;
  var steps=today.steps||0;
  var cal=today.caloriesBurned||0;
  var active=today.activeMinutes||0;
  var goalSteps=10000, goalCal=500, goalActive=30;
  var pSteps=Math.min(steps/goalSteps,1);
  var pCal=Math.min(cal/goalCal,1);
  var pActive=Math.min(active/goalActive,1);
  var rSteps=document.getElementById('ft-ring-steps');
  var rCal=document.getElementById('ft-ring-cal');
  var rActive=document.getElementById('ft-ring-active');
  if(rSteps) rSteps.setAttribute('stroke-dasharray',(pSteps*534)+' 534');
  if(rCal) rCal.setAttribute('stroke-dasharray',(pCal*421)+' 421');
  if(rActive) rActive.setAttribute('stroke-dasharray',(pActive*308)+' 308');
}

function ftUpdateStepsUI(steps){
  var pct=Math.min(Math.round((steps/10000)*100),100);
  var badge=document.getElementById('ft-steps-badge');
  if(badge) badge.textContent=pct+'%';
  var bar=document.getElementById('ft-steps-bar');
  if(bar) bar.style.width=pct+'%';
  var hs=document.getElementById('ft-hero-steps');
  if(hs) hs.textContent=(steps||0).toLocaleString('bn-BD');
}

function ftUpdateSteps(val){
  var steps=parseInt(val)||0;
  var d=ftGetData();
  d.today.steps=steps;
  ftSaveData(d);
  ftUpdateStepsUI(steps);
  ftRenderRings(d);
}

function ftAddSteps(n){
  var d=ftGetData();
  d.today.steps=(d.today.steps||0)+n;
  ftSaveData(d);
  var si=document.getElementById('ft-steps-input');
  if(si) si.value=d.today.steps;
  ftUpdateStepsUI(d.today.steps);
  ftRenderRings(d);
}

function ftRenderBMI(d){
  var p=d.profile||{};
  var wEl=document.getElementById('ft-disp-weight');
  var hEl=document.getElementById('ft-disp-height');
  var bEl=document.getElementById('ft-disp-bmi');
  var nEl=document.getElementById('ft-bmi-needle');
  var lEl=document.getElementById('ft-bmi-label');
  if(wEl) wEl.textContent=p.weight||'--';
  if(hEl) hEl.textContent=p.height||'--';
  if(!p.weight||!p.height){
    if(bEl) bEl.textContent='--';
    if(nEl) nEl.style.display='none';
    return;
  }
  var bmi=p.weight/Math.pow(p.height/100,2);
  bmi=Math.round(bmi*10)/10;
  if(bEl) bEl.textContent=bmi;
  // BMI range 10-45 mapped to 0-100%
  var pct=Math.max(0,Math.min(((bmi-10)/35)*100,100));
  if(nEl){ nEl.style.display='block'; nEl.style.left=pct+'%'; }
  var label='',color='';
  if(bmi<18.5){label='অপুষ্টি (Underweight)';color='#EAB308';}
  else if(bmi<25){label='স্বাভাবিক ✓ (Normal)';color='#10B981';}
  else if(bmi<30){label='বেশি ওজন (Overweight)';color='#F97316';}
  else{label='স্থূলতা (Obese)';color='#EF4444';}
  if(lEl){lEl.textContent=label;lEl.style.color=color;}
  if(bEl) bEl.style.color=color;
}

function ftRenderWater(d){
  var w=d.today.water||0;
  var grid=document.getElementById('ft-water-grid');
  var cnt=document.getElementById('ft-water-count');
  var bar=document.getElementById('ft-water-bar');
  var sw=document.getElementById('ft-stat-water');
  if(cnt) cnt.textContent=w;
  if(bar) bar.style.width=(w/8*100)+'%';
  if(sw) sw.textContent=w+'/8';
  if(!grid) return;
  var html='';
  for(var i=0;i<8;i++){
    var filled=i<w;
    html+='<div onclick="ftToggleWater('+i+')" style="cursor:pointer;text-align:center;padding:4px 2px;border-radius:8px;background:'+(filled?'rgba(59,130,246,.1)':'var(--bg2,#f3f4f6)')+';border:1.5px solid '+(filled?'rgba(59,130,246,.4)':'var(--border,#e5e7eb)')+'">'+
      '<div style="font-size:18px;filter:'+(filled?'none':'grayscale(1) opacity(.3)')+'">💧</div>'+
    '</div>';
  }
  grid.innerHTML=html;
}

function ftToggleWater(idx){
  var d=ftGetData();
  var w=d.today.water||0;
  // If clicking filled glass, remove from that point
  if(idx<w) d.today.water=idx;
  else d.today.water=idx+1;
  if(d.today.water>8) d.today.water=8;
  ftSaveData(d);
  ftRenderWater(d);
}

function ftAddWater(){
  var d=ftGetData();
  if((d.today.water||0)<8){ d.today.water=(d.today.water||0)+1; ftSaveData(d); ftRenderWater(d); }
}
function ftRemoveWater(){
  var d=ftGetData();
  if((d.today.water||0)>0){ d.today.water=(d.today.water||0)-1; ftSaveData(d); ftRenderWater(d); }
}

function ftRenderWorkouts(d){
  var el=document.getElementById('ft-workout-list');
  if(!el) return;
  var list=d.today.workouts||[];
  if(!list.length){
    el.innerHTML='<div style="background:var(--card,#fff);border:1.5px dashed var(--border,#e5e7eb);border-radius:14px;padding:20px;text-align:center;color:var(--text2,#888);font-size:13px">আজ কোনো workout নেই — শুরু করুন!</div>';
    return;
  }
  var icons={cardio:'🏃',strength:'💪',hiit:'⚡',yoga:'🧘',sports:'⚽',walk:'🚶'};
  var colors={cardio:'#FF6B35',strength:'#7C3AED',hiit:'#F59E0B',yoga:'#10B981',sports:'#3B82F6',walk:'#00D4AA'};
  var html='';
  list.forEach(function(w){
    var ic=icons[w.type]||'💪';
    var col=colors[w.type]||'#00D4AA';
    var setsReps=w.sets&&w.reps?' • '+w.sets+'×'+w.reps:'';
    html+='<div style="background:var(--card,#fff);border:1.5px solid var(--border,#e5e7eb);border-radius:14px;padding:12px 14px;display:flex;align-items:center;gap:12px">'+
      '<div style="width:40px;height:40px;border-radius:12px;background:'+col+'18;border:1.5px solid '+col+'44;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:20px">'+ic+'</div>'+
      '<div style="flex:1">'+
        '<div style="font-size:13px;font-weight:700;color:var(--text,#1a1a2e)">'+(w.name||w.type)+'</div>'+
        '<div style="font-size:11px;color:var(--text2,#888);margin-top:2px">'+w.duration+' মিনিট'+setsReps+' • '+w.calories+' kcal</div>'+
      '</div>'+
      '<button onclick="ftDeleteWorkout('+w.id+')" style="width:30px;height:30px;border-radius:8px;border:none;background:rgba(239,68,68,.08);color:#EF4444;font-size:16px;cursor:pointer;flex-shrink:0">×</button>'+
    '</div>';
  });
  el.innerHTML=html;
}

function ftRenderWeekly(d){
  var el=document.getElementById('ft-weekly-grid');
  if(!el) return;
  var days=['রবি','সোম','মঙ্গ','বুধ','বৃহ','শুক্র','শনি'];
  var today=new Date();
  var todayKey=ftTodayKey();
  var html='';
  for(var i=6;i>=0;i--){
    var dd=new Date(today); dd.setDate(today.getDate()-i);
    var dk=dd.getFullYear()+'-'+String(dd.getMonth()+1).padStart(2,'0')+'-'+String(dd.getDate()).padStart(2,'0');
    var isToday=dk===todayKey;
    var steps=0,workouts=0;
    if(isToday){ steps=d.today.steps||0; workouts=(d.today.workouts||[]).length; }
    else{
      var h=(d.history||[]).find(function(x){return x.date===dk;});
      if(h){ steps=h.steps||0; workouts=h.workouts||0; }
    }
    var intensity=0;
    if(steps>=10000||workouts>=3) intensity=3;
    else if(steps>=7000||workouts>=2) intensity=2;
    else if(steps>=3000||workouts>=1) intensity=1;
    var bg=['var(--bg2,#e5e7eb)','rgba(0,212,170,.25)','rgba(0,212,170,.55)','#00D4AA'][intensity];
    html+='<div>'+
      '<div style="font-size:9px;color:var(--text2,#888);margin-bottom:5px">'+(days[dd.getDay()])+'</div>'+
      '<div style="width:100%;aspect-ratio:1;border-radius:8px;background:'+bg+';border:'+(isToday?'2px solid #00D4AA':'1.5px solid transparent')+'" title="'+dd.getDate()+'/'+(dd.getMonth()+1)+'"></div>'+
      '<div style="font-size:9px;color:var(--text2,#888);margin-top:4px">'+dd.getDate()+'</div>'+
    '</div>';
  }
  el.innerHTML=html;
}

function ftRenderPRs(d){
  var el=document.getElementById('ft-pr-list');
  if(!el) return;
  var prs=d.prs||[];
  var html='';
  prs.forEach(function(pr,i){
    html+='<div style="background:var(--card,#fff);border:1.5px solid var(--border,#e5e7eb);border-radius:14px;padding:12px 14px;display:flex;align-items:center;gap:12px">'+
      '<div style="width:40px;height:40px;border-radius:12px;background:rgba(245,158,11,.1);border:1.5px solid rgba(245,158,11,.25);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:20px">'+pr.icon+'</div>'+
      '<div style="flex:1">'+
        '<div style="font-size:12px;font-weight:700;color:var(--text,#1a1a2e)">'+pr.label+'</div>'+
        (pr.date?'<div style="font-size:10px;color:var(--text2,#888);margin-top:2px">'+pr.date+'</div>':'<div style="font-size:10px;color:var(--text2,#888);margin-top:2px">এখনো রেকর্ড করা হয়নি</div>')+
      '</div>'+
      '<div style="text-align:right">'+
        '<div style="font-size:20px;font-weight:900;color:#F59E0B">'+(pr.value||'—')+'</div>'+
        '<div style="font-size:9px;color:var(--text2,#888)">'+pr.unit+'</div>'+
      '</div>'+
      '<button onclick="ftEditPR('+i+')" style="width:30px;height:30px;border-radius:8px;border:1.5px solid rgba(245,158,11,.3);background:rgba(245,158,11,.08);color:#F59E0B;font-size:14px;cursor:pointer;flex-shrink:0">✏</button>'+
    '</div>';
  });
  el.innerHTML=html;
}

function ftEditPR(idx){
  var d=ftGetData();
  var pr=d.prs[idx];
  if(!pr) return;
  var val=prompt(pr.label+' — নতুন রেকর্ড লিখুন ('+pr.unit+'):', pr.value||'');
  if(val===null) return;
  var num=parseFloat(val)||0;
  if(!num) return;
  var today=ftTodayKey();
  pr.value=num;
  pr.date=today;
  ftSaveData(d);
  ftRenderPRs(d);
}

// Workout modal
function ftOpenAddWorkout(){
  _ftWType=''; _ftWTypeIcon=''; _ftWTypeColor='';
  document.querySelectorAll('.ft-wtype-btn').forEach(function(b){
    b.style.border='1.5px solid var(--border,#e5e7eb)';
    b.style.background='var(--bg2,#f3f4f6)';
    b.style.color='var(--text2,#888)';
  });
  var inputs=['ft-w-name','ft-w-duration','ft-w-calories','ft-w-sets','ft-w-reps'];
  inputs.forEach(function(id){ var el=document.getElementById(id); if(el) el.value=''; });
  var sf=document.getElementById('ft-w-strength-fields');
  if(sf) sf.style.display='none';
  var m=document.getElementById('ft-workout-modal');
  if(m) m.style.display='flex';
}

function ftPickWType(btn,type,icon,color){
  _ftWType=type; _ftWTypeIcon=icon; _ftWTypeColor=color;
  document.getElementById('ft-w-type').value=type;
  document.querySelectorAll('.ft-wtype-btn').forEach(function(b){
    b.style.border='1.5px solid var(--border,#e5e7eb)';
    b.style.background='var(--bg2,#f3f4f6)';
    b.style.color='var(--text2,#888)';
  });
  btn.style.border='1.5px solid '+color;
  btn.style.background=color+'18';
  btn.style.color=color;
  var sf=document.getElementById('ft-w-strength-fields');
  if(sf) sf.style.display=(type==='strength')?'grid':'none';
  ftCalcAutoCalories();
}

function ftCalcAutoCalories(){
  var dur=parseInt((document.getElementById('ft-w-duration')||{}).value)||0;
  var cpm=_ftCalPerMin[_ftWType]||5;
  var cal=dur*cpm;
  var ce=document.getElementById('ft-w-calories');
  if(ce&&cal>0) ce.value=cal;
}

function ftSaveWorkout(){
  if(!_ftWType){alert('ব্যায়ামের ধরন বাছাই করুন');return;}
  var dur=parseInt((document.getElementById('ft-w-duration')||{}).value)||0;
  if(!dur){alert('সময় লিখুন');return;}
  var name=(document.getElementById('ft-w-name')||{}).value||_ftWType;
  var cal=parseInt((document.getElementById('ft-w-calories')||{}).value)||dur*(_ftCalPerMin[_ftWType]||5);
  var sets=parseInt((document.getElementById('ft-w-sets')||{}).value)||0;
  var reps=parseInt((document.getElementById('ft-w-reps')||{}).value)||0;
  var d=ftGetData();
  if(!d.today.workouts) d.today.workouts=[];
  d.today.workouts.push({id:Date.now(),type:_ftWType,icon:_ftWTypeIcon,color:_ftWTypeColor,name:name,duration:dur,calories:cal,sets:sets,reps:reps});
  d.today.caloriesBurned=(d.today.caloriesBurned||0)+cal;
  d.today.activeMinutes=(d.today.activeMinutes||0)+dur;
  ftSaveData(d);
  ftCloseModal('ft-workout-modal');
  ftRenderWorkouts(d);
  ftRenderRings(d);
  ftUpdateHeroStats(d);
  ftRenderWeekly(d);
}

function ftDeleteWorkout(id){
  var d=ftGetData();
  var w=d.today.workouts.find(function(x){return x.id===id;});
  if(w){
    d.today.caloriesBurned=Math.max(0,(d.today.caloriesBurned||0)-w.calories);
    d.today.activeMinutes=Math.max(0,(d.today.activeMinutes||0)-w.duration);
  }
  d.today.workouts=d.today.workouts.filter(function(x){return x.id!==id;});
  ftSaveData(d);
  ftRenderWorkouts(d);
  ftRenderRings(d);
  ftUpdateHeroStats(d);
}

// Profile modal
function ftOpenProfile(){
  var d=ftGetData();
  var p=d.profile||{};
  var w=document.getElementById('ft-p-weight'); if(w) w.value=p.weight||'';
  var h=document.getElementById('ft-p-height'); if(h) h.value=p.height||'';
  var a=document.getElementById('ft-p-age'); if(a) a.value=p.age||'';
  var g=document.getElementById('ft-p-gender'); if(g) g.value=p.gender||'male';
  var gl=document.getElementById('ft-p-goal'); if(gl) gl.value=p.goal||'maintain';
  var m=document.getElementById('ft-profile-modal'); if(m) m.style.display='flex';
}

function ftSaveProfile(){
  var d=ftGetData();
  d.profile={
    weight:parseFloat((document.getElementById('ft-p-weight')||{}).value)||0,
    height:parseFloat((document.getElementById('ft-p-height')||{}).value)||0,
    age:parseInt((document.getElementById('ft-p-age')||{}).value)||0,
    gender:((document.getElementById('ft-p-gender')||{}).value)||'male',
    goal:((document.getElementById('ft-p-goal')||{}).value)||'maintain'
  };
  ftSaveData(d);
  ftCloseModal('ft-profile-modal');
  ftRenderBMI(d);
  ftRenderSmartCard(d);
  ftRenderTodayPlan(d);
  ftRenderNutrition(d);
  ftRenderInsights(d);
}

function ftCloseModal(id){
  var m=document.getElementById(id); if(m) m.style.display='none';
}

