        '<div style="font-size:26px;font-weight:900;color:'+(netCal>calGoal?'#EF4444':'#10B981')+'">'+netCal+'</div>'+
        '<div style="font-size:10px;color:var(--text2,#888)">খাওয়া − বার্ন</div>'+
      '</div>'+
    '</div>'+
    '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;margin-bottom:14px">'+
      '<div style="text-align:center;background:rgba(124,58,237,.08);border-radius:10px;padding:8px">'+
        '<div style="font-size:14px;font-weight:900;color:#7C3AED">'+food.protein+'g</div>'+
        '<div style="font-size:9px;color:var(--text2,#888)">প্রোটিন /'+targets.protein+'g</div>'+
        '<div style="background:rgba(124,58,237,.15);height:4px;border-radius:2px;margin-top:5px"><div style="height:100%;background:#7C3AED;width:'+proteinPct+'%;border-radius:2px"></div></div>'+
      '</div>'+
      '<div style="text-align:center;background:rgba(251,191,36,.08);border-radius:10px;padding:8px">'+
        '<div style="font-size:14px;font-weight:900;color:#F59E0B">'+food.carbs+'g</div>'+
        '<div style="font-size:9px;color:var(--text2,#888)">কার্বস</div>'+
      '</div>'+
      '<div style="text-align:center;background:rgba(239,68,68,.08);border-radius:10px;padding:8px">'+
        '<div style="font-size:14px;font-weight:900;color:#EF4444">'+food.fat+'g</div>'+
        '<div style="font-size:9px;color:var(--text2,#888)">ফ্যাট</div>'+
      '</div>'+
    '</div>'+
    '<div id="ft-food-log-list" style="display:flex;flex-direction:column;gap:6px;margin-bottom:10px"></div>'+
    '<button onclick="ftOpenAddFood()" style="width:100%;padding:11px;border:1.5px dashed rgba(255,107,53,.4);border-radius:12px;font-size:13px;font-weight:700;color:#FF6B35;background:rgba(255,107,53,.05);cursor:pointer">🍽️ খাবার যোগ করুন</button>';
  var logEl=document.getElementById('ft-food-log-list');
