function ftRenderSleep(d){
  var el=document.getElementById('ft-sleep-section');
  if(!el) return;
  var sleep=d.today.sleep||{hours:0,quality:''};
  var hrs=sleep.hours||0;
  var quality=sleep.quality||'';
  var sleepMsg='';
  if(hrs){
    if(hrs>=7&&hrs<=9) sleepMsg='✅ চমৎকার! ৭-৯ ঘণ্টা ঘুম আদর্শ।';
    else if(hrs<6) sleepMsg='⚠️ ঘুম কম! ৭+ ঘণ্টা ঘুমান। কম ঘুম ওজন বাড়ায়।';
    else if(hrs>9) sleepMsg='😴 একটু বেশি হয়েছে। ৭-৮ ঘণ্টাই যথেষ্ট।';
  }
  var qualColors={ভালো:'#10B981',মাঝারি:'#F59E0B',খারাপ:'#EF4444'};
  var qBtns=['ভালো','মাঝারি','খারাপ'].map(function(q){
    var active=quality===q; var c=qualColors[q];
    return '<button onclick="ftSetSleepQuality(\''+q+'\')" style="flex:1;padding:9px;border:1.5px solid '+(active?c:'var(--border,#e5e7eb)')+';border-radius:10px;font-size:12px;font-weight:700;color:'+(active?c:'var(--text2,#888)')+';background:'+(active?c+'18':'var(--bg2,#f3f4f6)')+';cursor:pointer">'+q+'</button>';
  }).join('');
  el.innerHTML=
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:12px">'+
      '<div>'+
        '<div style="font-size:11px;font-weight:700;color:var(--text2,#888);margin-bottom:8px">ঘুমের সময়</div>'+
        '<div style="display:flex;align-items:center;gap:6px">'+
          '<input id="ft-sleep-hours" type="number" min="0" max="14" step="0.5" value="'+(hrs||'')+'" placeholder="৭" oninput="ftSaveSleep()" style="width:60px;padding:8px;border:1.5px solid var(--border,#e5e7eb);border-radius:10px;font-size:20px;font-weight:900;color:var(--text,#1a1a2e);background:var(--bg,#fff);text-align:center;outline:none"/>'+
          '<span style="font-size:13px;color:var(--text2,#888)">ঘণ্টা</span>'+
        '</div>'+
      '</div>'+
      '<div>'+
        '<div style="font-size:11px;font-weight:700;color:var(--text2,#888);margin-bottom:8px">ঘুমের মান</div>'+
        '<div style="display:flex;gap:5px">'+qBtns+'</div>'+
      '</div>'+
    '</div>'+
    (sleepMsg?'<div style="background:rgba(59,130,246,.06);border:1px solid rgba(59,130,246,.15);border-radius:10px;padding:10px;font-size:12px;color:var(--text,#1a1a2e);line-height:1.6">'+sleepMsg+'</div>':'');
}

function ftRenderMeasurements(d){
  var el=document.getElementById('ft-measurements-section');
  if(!el) return;
  var m=d.measurements||{};
  var p=d.profile||{};
  var bfPct='--';
  if(m.waist&&m.neck&&p.height&&m.waist>m.neck){
    var bf;
    if(p.gender==='female'&&m.hips){
      bf=163.205*Math.log10(m.waist+m.hips-m.neck)-97.684*Math.log10(p.height)-78.387;
    } else {
      bf=495/(1.0324-0.19077*Math.log10(m.waist-m.neck)+0.15456*Math.log10(p.height))-450;
    }
    bf=Math.round(bf*10)/10;
    bfPct=(bf>=3&&bf<=60)?bf+'%':'--';
  }
  var fields=[{key:'waist',label:'কোমর'},{key:'chest',label:'বুক'},{key:'hips',label:'নিতম্ব'},{key:'arms',label:'হাত'},{key:'neck',label:'গলা'}];
  var mHtml=fields.map(function(f){
    return '<div style="text-align:center;background:var(--bg2,#f9fafb);border-radius:10px;padding:10px">'+
      '<div style="font-size:15px;font-weight:900;color:var(--text,#1a1a2e)">'+(m[f.key]||'—')+'</div>'+
      '<div style="font-size:9px;color:var(--text2,#888);margin-top:2px">'+f.label+'</div>'+
    '</div>';
  }).join('');
  el.innerHTML=
    '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:6px;margin-bottom:12px">'+mHtml+'</div>'+
    '<div style="display:flex;align-items:center;justify-content:space-between">'+
      '<div style="font-size:12px;color:var(--text2,#888)">চর্বির হার (Navy): <strong style="color:'+(bfPct!=='--'?'#10B981':'var(--text2,#888)')+'">'+bfPct+'</strong></div>'+
      '<button onclick="ftOpenMeasureModal()" style="padding:7px 14px;border:1.5px solid rgba(0,212,170,.4);border-radius:14px;font-size:11px;font-weight:700;color:#00D4AA;background:rgba(0,212,170,.06);cursor:pointer">📏 আপডেট</button>'+
    '</div>';
}

function ftRenderInsights(d){
  var el=document.getElementById('ft-insights-section');
  if(!el) return;
  var p=d.profile||{};
  var today=d.today;
  var sleep=today.sleep||{};
  var tips=[];
  if(p.weight&&p.height){
    var bmi=p.weight/Math.pow(p.height/100,2);
    var bmiR=Math.round(bmi*10)/10;
    if(bmi<18.5) tips.push({icon:'⚖️',color:'#EAB308',title:'ওজন কম',msg:'BMI '+bmiR+' — পুষ্টিকর খাবার ও প্রোটিন বাড়ান।'});
    else if(bmi>=30) tips.push({icon:'🔥',color:'#EF4444',title:'স্থূলতা',msg:'BMI '+bmiR+' — HIIT ও কার্ডিও বাড়ান, ক্যালোরি ঘাটতি রাখুন।'});
    else if(bmi>=25) tips.push({icon:'📉',color:'#F97316',title:'সামান্য বেশি',msg:'BMI '+bmiR+' — নিয়মিত হাঁটুন ও প্রক্রিয়াজাত খাবার এড়ান।'});
  }
  var steps=today.steps||0;
  if(steps<3000) tips.push({icon:'🚶',color:'#3B82F6',title:'কম হেঁটেছেন',msg:'আজ মাত্র '+steps+' কদম হেঁটেছেন। এখনই ১০ মিনিট হাঁটতে বের হন!'});
  else if(steps>=10000) tips.push({icon:'🏆',color:'#10B981',title:'দারুণ!',msg:'আজ '+steps.toLocaleString()+' পদক্ষেপ — লক্ষ্য পূরণ হয়েছে!'});
  if((today.water||0)<4) tips.push({icon:'💧',color:'#3B82F6',title:'পানি কম',msg:'মাত্র '+(today.water||0)+' গ্লাস। পানিশূন্যতা মেটাবলিজম কমায়।'});
  if(sleep.hours&&sleep.hours<6) tips.push({icon:'😴',color:'#7C3AED',title:'ঘুম কম',msg:'ঘুম কম হলে ক্ষুধা বাড়ে ও ওজন বাড়ে। আজ তাড়াতাড়ি ঘুমান।'});
  if(!(today.workouts||[]).length&&new Date().getHours()>15) tips.push({icon:'💪',color:'#FF6B35',title:'ব্যায়াম হয়নি!',msg:'সন্ধ্যা হয়ে গেছে — এখনই ২০ মিনিটের হাঁটা যান!'});
  var food=today.nutrition||{cals:0};
  var targets=ftGetGoalTargets(p);
  if(food.cals&&p.goal==='lose'&&food.cals>targets.cal) tips.push({icon:'🍽️',color:'#EF4444',title:'ক্যালোরি বেশি',msg:'আজ '+food.cals+' kcal খেয়েছেন, লক্ষ্য '+targets.cal+' kcal।'});
  if(!p.weight||!p.height||!p.age) tips.push({icon:'👤',color:'#00D4AA',title:'প্রোফাইল অসম্পূর্ণ',msg:'ওজন, উচ্চতা ও বয়স লিখলে AI আরো ভালো পরামর্শ দিতে পারবে।'});
  if(!tips.length) tips.push({icon:'🌟',color:'#10B981',title:'সব ঠিকঠাক!',msg:'দারুণ! আজকের সব সূচক ভালো আছে। এভাবেই চালিয়ে যান।'});
  el.innerHTML=tips.map(function(t){
    return '<div style="display:flex;align-items:flex-start;gap:12px;padding:12px;background:'+t.color+'0d;border-left:3px solid '+t.color+';border-radius:0 10px 10px 0;margin-bottom:8px">'+
      '<div style="font-size:18px;flex-shrink:0;margin-top:1px">'+t.icon+'</div>'+
      '<div><div style="font-size:12px;font-weight:800;color:'+t.color+';margin-bottom:3px">'+t.title+'</div>'+
      '<div style="font-size:11.5px;color:var(--text,#1a1a2e);line-height:1.6">'+t.msg+'</div></div>'+
    '</div>';
  }).join('');
}

function ftOpenAddFood(){
  var m=document.getElementById('ft-food-modal');
  if(m) m.style.display='flex';
  var qp=document.getElementById('ft-food-quickpicks');
  if(!qp) return;
  var html='';
  FT_FOODS_DB.forEach(function(food,i){
    html+='<button onclick="ftQuickAddFood('+i+')" style="text-align:left;padding:10px 12px;border:1.5px solid var(--border,#e5e7eb);border-radius:10px;font-size:11.5px;color:var(--text,#1a1a2e);background:var(--bg2,#f9fafb);cursor:pointer;display:flex;justify-content:space-between;align-items:center">'+
      '<span style="font-weight:600">'+food.name+'</span>'+
      '<span style="color:#FF6B35;font-weight:700;font-size:11px">'+food.cal+' kcal</span>'+
    '</button>';
  });
  qp.innerHTML=html;
}

function ftQuickAddFood(idx){
  var food=FT_FOODS_DB[idx];
  if(!food) return;
  var d=ftGetData();
  if(!d.today.nutrition) d.today.nutrition={foodLog:[],cals:0,protein:0,carbs:0,fat:0};
  var n=d.today.nutrition;
  n.foodLog.push({id:Date.now(),name:food.name,cal:food.cal,protein:food.protein,carbs:food.carbs,fat:food.fat});
  n.cals+=food.cal; n.protein+=food.protein; n.carbs+=food.carbs; n.fat+=food.fat;
  n.cals=Math.round(n.cals); n.protein=Math.round(n.protein*10)/10;
  n.carbs=Math.round(n.carbs*10)/10; n.fat=Math.round(n.fat*10)/10;
  ftSaveData(d);
  ftCloseModal('ft-food-modal');
  ftRenderNutrition(d);
  ftRenderInsights(d);
}

function ftDeleteFood(id){
  var d=ftGetData();
  if(!d.today.nutrition) return;
  var n=d.today.nutrition;
  var item=n.foodLog.find(function(x){return x.id===id;});
  if(item){
    n.cals=Math.max(0,n.cals-item.cal); n.protein=Math.max(0,n.protein-item.protein);
    n.carbs=Math.max(0,n.carbs-item.carbs); n.fat=Math.max(0,n.fat-item.fat);
    n.cals=Math.round(n.cals); n.protein=Math.round(n.protein*10)/10;
    n.carbs=Math.round(n.carbs*10)/10; n.fat=Math.round(n.fat*10)/10;
  }
  n.foodLog=n.foodLog.filter(function(x){return x.id!==id;});
  ftSaveData(d);
  ftRenderNutrition(d);
  ftRenderInsights(d);
}

function ftSaveSleep(){
  var hrs=parseFloat((document.getElementById('ft-sleep-hours')||{}).value)||0;
  var d=ftGetData();
  if(!d.today.sleep) d.today.sleep={hours:0,quality:''};
  d.today.sleep.hours=hrs;
  ftSaveData(d);
  ftRenderInsights(d);
}

function ftSetSleepQuality(q){
  var d=ftGetData();
  if(!d.today.sleep) d.today.sleep={hours:0,quality:''};
  d.today.sleep.quality=q;
  ftSaveData(d);
  ftRenderSleep(d);
  ftRenderInsights(d);
}

function ftOpenMeasureModal(){
  var d=ftGetData();
  var m=d.measurements||{};
  ['waist','chest','hips','arms','neck'].forEach(function(f){
    var el=document.getElementById('ft-m-'+f); if(el) el.value=m[f]||'';
  });
  var modal=document.getElementById('ft-measure-modal');
  if(modal) modal.style.display='flex';
}

function ftSaveMeasurements(){
  var d=ftGetData();
  d.measurements={
    waist:parseFloat((document.getElementById('ft-m-waist')||{}).value)||0,
    chest:parseFloat((document.getElementById('ft-m-chest')||{}).value)||0,
    hips:parseFloat((document.getElementById('ft-m-hips')||{}).value)||0,
    arms:parseFloat((document.getElementById('ft-m-arms')||{}).value)||0,
    neck:parseFloat((document.getElementById('ft-m-neck')||{}).value)||0
  };
  ftSaveData(d);
  ftCloseModal('ft-measure-modal');
  ftRenderMeasurements(d);
  ftRenderInsights(d);
}

