var MP_DAYS = ['রবি','সোম','মঙ্গল','বুধ','বৃহস্পতি','শুক্র','শনি'];
var MP_MEAL_TYPES = [{key:'breakfast',label:'সকাল',icon:'🌅'},{key:'lunch',label:'দুপুর',icon:'☀️'},{key:'dinner',label:'রাত',icon:'🌙'},{key:'snack',label:'নাশতা',icon:'🍿'}];
var _mpRamadanTimer = null;
var _mpCurrentAddDay = null;
var _mpCurrentAddType = null;
var _mpRecipeFilter = 'all';

function mpKey(){ return 'rz_mp_'+new Date().getFullYear()+'_w'+mpWeekNum(); }
function mpWeekNum(){ var d=new Date(); return Math.ceil(((d-new Date(d.getFullYear(),0,1))/86400000+new Date(d.getFullYear(),0,1).getDay()+1)/7); }

function mpGetData(){
  try{ return JSON.parse(localStorage.getItem(mpKey())||'{}'); }catch(e){ return {}; }
}
function mpSaveData(d){
  localStorage.setItem(mpKey(), JSON.stringify(d));
}

function mpCheckMode(){
  var k=document.getElementById('mp-kids-wrap');
  var a=document.getElementById('mp-adult-wrap');
  if(!k||!a){ setTimeout(mpCheckMode,150); return; }
  var isAdult = window.rzMode==='forme';
  k.style.display = isAdult?'none':'block';
  a.style.display = isAdult?'block':'none';
  if(isAdult) mpRender();
}

function mpRender(){
  var d = mpGetData();
  mpRenderHero(d);
  mpRenderBudget(d);
  mpRenderDayTabs(d);
  mpRenderNutritionSummary(d);
  mpRenderRecipes(_mpRecipeFilter);
  if(d.ramadanMode) mpStartFastingTimer();
}

function mpRenderHero(d){
  var todayIdx = new Date().getDay();
  var dayKey = 'day'+todayIdx;
  var dayMeals = (d.meals&&d.meals[dayKey]) || {};
  var cal=0,protein=0,count=0,spent=0;
  MP_MEAL_TYPES.forEach(function(t){
    var m = dayMeals[t.key];
    if(m && m.recipeId){
      var r = MP_RECIPES.find(function(x){return x.id===m.recipeId;});
      if(r){ cal+=r.cal; protein+=r.protein; count++; }
      if(m.cost) spent+=Number(m.cost)||0;
    }
  });
  var dateEl=document.getElementById('mp-hero-date');
  var statusEl=document.getElementById('mp-hero-status');
  var calEl=document.getElementById('mp-today-cal');
  var protEl=document.getElementById('mp-today-protein');
  var spentEl=document.getElementById('mp-today-budget-spent');
  var cntEl=document.getElementById('mp-today-count');
  var days=['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
  if(dateEl) dateEl.textContent = days[todayIdx]+', আজ';
  if(statusEl){
    var msgs=['পরিকল্পনা নেই','সকাল পরিকল্পিত','দুটি বেলা পরিকল্পিত','তিন বেলা পরিকল্পিত','সব বেলা পরিকল্পিত ✓'];
    statusEl.textContent = msgs[Math.min(count,4)];
  }
  if(calEl) calEl.textContent = cal;
  if(protEl) protEl.textContent = protein+'g';
  if(spentEl) spentEl.textContent = '৳'+spent;
  if(cntEl) cntEl.textContent = count+'/4';
}

function mpRenderBudget(d){
  var budget = d.weeklyBudget||0;
  var spent = 0;
  if(d.meals){
    Object.values(d.meals).forEach(function(dayMeals){
      MP_MEAL_TYPES.forEach(function(t){
        var m=dayMeals[t.key];
        if(m&&m.cost) spent+=Number(m.cost)||0;
      });
    });
  }
  var pct = budget>0 ? Math.min(100,Math.round(spent/budget*100)) : 0;
  var color = pct>90?'#EF4444':pct>70?'#F59E0B':'linear-gradient(90deg,#FF8C42,#FFB800)';
  var barEl=document.getElementById('mp-budget-bar');
  var spentEl=document.getElementById('mp-week-spent');
  var budEl=document.getElementById('mp-week-budget-disp');
  if(barEl){ barEl.style.width=pct+'%'; barEl.style.background=color; }
  if(spentEl) spentEl.textContent='৳'+spent;
  if(budEl) budEl.textContent='৳'+budget;
}

function mpRenderDayTabs(d){
  var tabsEl=document.getElementById('mp-day-tabs');
  var mealsEl=document.getElementById('mp-day-meals');
  if(!tabsEl||!mealsEl) return;
  var todayIdx=new Date().getDay();
  var currentDay = d._selectedDay!=null ? d._selectedDay : todayIdx;
  tabsEl.innerHTML='';
  MP_DAYS.forEach(function(name,i){
    var active=i===currentDay;
    var btn=document.createElement('button');
    btn.style.cssText='flex-shrink:0;padding:7px 14px;border-radius:20px;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap;transition:.2s;'+(active?'background:linear-gradient(135deg,#FF8C42,#FF6B00);color:#fff;border:none;':'background:var(--bg2,#f3f4f6);color:var(--text2,#888);border:1.5px solid var(--border,#e5e7eb);');
    if(i===todayIdx) btn.textContent='আজ ('+name+')';
    else btn.textContent=name;
    btn.onclick=(function(idx){ return function(){ d._selectedDay=idx; mpSaveData(d); mpRenderDayTabs(d); }; })(i);
    tabsEl.appendChild(btn);
  });
  var dayKey='day'+currentDay;
  var dayMeals=(d.meals&&d.meals[dayKey])||{};
  mealsEl.innerHTML='';
  MP_MEAL_TYPES.forEach(function(t){
    var m=dayMeals[t.key];
    var r=m&&m.recipeId?MP_RECIPES.find(function(x){return x.id===m.recipeId;}):null;
    var card=document.createElement('div');
    card.style.cssText='background:var(--card,#fff);border:1.5px solid var(--border,#e5e7eb);border-radius:14px;padding:14px;display:flex;align-items:center;gap:12px;';
    if(r){
      card.innerHTML='<div style="width:40px;height:40px;border-radius:12px;background:rgba(255,140,66,.1);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:18px">'+t.icon+'</div><div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:800;color:var(--text,#1a1a2e);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+r.name+'</div><div style="font-size:11px;color:var(--text2,#888);margin-top:2px">'+r.cal+' kcal • '+r.protein+'g প্রোটিন'+(m.cost?' • ৳'+m.cost:'')+'</div></div><button onclick="mpRemoveMeal(\''+currentDay+'\',\''+t.key+'\')" style="flex-shrink:0;width:30px;height:30px;border-radius:8px;background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.2);color:#EF4444;font-size:14px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center">×</button>';
    } else {
      card.innerHTML='<div style="width:40px;height:40px;border-radius:12px;background:var(--bg2,#f3f4f6);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:18px;opacity:.5">'+t.icon+'</div><div style="flex:1"><div style="font-size:12px;font-weight:700;color:var(--text2,#888)">'+t.label+'</div><div style="font-size:11px;color:var(--text2,#888);opacity:.7">কোনো খাবার যোগ হয়নি</div></div><button onclick="mpOpenAddMeal('+currentDay+',\''+t.key+'\')" style="flex-shrink:0;padding:7px 12px;background:linear-gradient(135deg,#FF8C42,#FF6B00);color:#fff;border:none;border-radius:10px;font-size:11px;font-weight:700;cursor:pointer">+ যোগ করুন</button>';
    }
    mealsEl.appendChild(card);
  });
}

function mpRemoveMeal(dayIdx, mealType){
  var d=mpGetData();
  var key='day'+dayIdx;
  if(d.meals&&d.meals[key]&&d.meals[key][mealType]) delete d.meals[key][mealType];
  mpSaveData(d);
  mpRenderHero(d);
  mpRenderBudget(d);
  mpRenderDayTabs(d);
  mpRenderNutritionSummary(d);
}

function mpOpenAddMeal(dayIdx, mealType){
  _mpCurrentAddDay=dayIdx;
  _mpCurrentAddType=mealType;
  var mtype=MP_MEAL_TYPES.find(function(t){return t.key===mealType;});
  var titleEl=document.getElementById('mp-modal-title');
  var subtitleEl=document.getElementById('mp-modal-subtitle');
  var listEl=document.getElementById('mp-modal-recipes');
  if(titleEl) titleEl.textContent=(mtype?mtype.label+' '+mtype.icon:'খাবার')+' বাছাই করুন';
  if(subtitleEl) subtitleEl.textContent='রেসিপি বেছে নিন';
  var recipes=mealType==='all'?MP_RECIPES:MP_RECIPES.filter(function(r){return r.meal===mealType;});
  if(listEl){
    listEl.innerHTML='';
    recipes.forEach(function(r){
      var item=document.createElement('div');
      item.style.cssText='display:flex;align-items:center;gap:12px;padding:12px;background:var(--bg2,#f3f4f6);border-radius:12px;cursor:pointer;border:1.5px solid transparent;transition:.2s;';
      item.innerHTML='<div style="flex:1"><div style="font-size:13px;font-weight:700;color:var(--text,#1a1a2e)">'+r.name+'</div><div style="font-size:11px;color:var(--text2,#888);margin-top:2px">'+r.cal+' kcal • '+r.protein+'g প্রোটিন • ⏱'+r.time+'মিন</div></div><button onclick="mpSelectRecipe(\''+r.id+'\')" style="flex-shrink:0;padding:7px 12px;background:linear-gradient(135deg,#FF8C42,#FF6B00);color:#fff;border:none;border-radius:10px;font-size:11px;font-weight:700;cursor:pointer">বেছে নিন</button>';
      listEl.appendChild(item);
    });
  }
  var modal=document.getElementById('mp-meal-modal');
  if(modal) modal.style.display='flex';
}

function mpSelectRecipe(recipeId){
  var d=mpGetData();
  if(!d.meals) d.meals={};
  var key='day'+_mpCurrentAddDay;
  if(!d.meals[key]) d.meals[key]={};
  var r=MP_RECIPES.find(function(x){return x.id===recipeId;});
  d.meals[key][_mpCurrentAddType]={recipeId:recipeId, cost: r?Math.round(r.cal/10*2):0};
  mpSaveData(d);
  mpCloseModal('mp-meal-modal');
  mpRenderHero(d);
  mpRenderBudget(d);
  mpRenderDayTabs(d);
  mpRenderNutritionSummary(d);
}

function mpCloseModal(id){
  var m=document.getElementById(id||'mp-meal-modal');
  if(m) m.style.display='none';
}

function mpOpenBudgetModal(){
  var d=mpGetData();
  var inp=document.getElementById('mp-budget-input');
  if(inp) inp.value=d.weeklyBudget||'';
  var m=document.getElementById('mp-budget-modal');
  if(m) m.style.display='flex';
}

function mpSaveBudget(){
  var d=mpGetData();
  var inp=document.getElementById('mp-budget-input');
  d.weeklyBudget=inp?Number(inp.value)||0:0;
  mpSaveData(d);
  mpCloseModal('mp-budget-modal');
  mpRenderBudget(d);
}

function mpClearDay(){
  var d=mpGetData();
  var dayIdx=d._selectedDay!=null?d._selectedDay:new Date().getDay();
  if(!d.meals) d.meals={};
  d.meals['day'+dayIdx]={};
  mpSaveData(d);
  mpRenderHero(d);
  mpRenderBudget(d);
  mpRenderDayTabs(d);
  mpRenderNutritionSummary(d);
}

function mpGenerateShoppingList(){
  var d=mpGetData();
  var el=document.getElementById('mp-shopping-list');
  if(!el) return;
  var ingredMap={};
  if(d.meals){
    Object.values(d.meals).forEach(function(dayMeals){
      MP_MEAL_TYPES.forEach(function(t){
        var m=dayMeals[t.key];
        if(m&&m.recipeId){
          var r=MP_RECIPES.find(function(x){return x.id===m.recipeId;});
          if(r&&r.ingredients){
            r.ingredients.forEach(function(ing){
              var key=ing.split(' ')[0];
              ingredMap[key]=(ingredMap[key]||[]); if(!ingredMap[key].includes(ing)) ingredMap[key].push(ing);
            });
          }
        }
      });
    });
  }
  if(d.ramadan){
    ['sehri','iftar'].forEach(function(type){
      (d.ramadan[type]||[]).forEach(function(item){
        var key=item.name;
        if(!ingredMap[key]) ingredMap[key]=[item.name];
      });
    });
  }
  var items=Object.values(ingredMap).map(function(arr){return arr[0];});
  if(!items.length){ el.innerHTML='<div style="text-align:center;padding:20px;font-size:13px;color:var(--text2,#888)">এই সপ্তাহের কোনো খাবার পরিকল্পনা নেই।</div>'; return; }
  el.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px"><div style="font-size:12px;font-weight:700;color:var(--text2,#888)">'+items.length+' টি উপাদান</div><div style="font-size:10px;color:#10B981;font-weight:700">✓ অটো তৈরি</div></div>'+items.map(function(item,i){
    return '<div style="display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--border,#e5e7eb)"><div style="width:20px;height:20px;border-radius:6px;background:rgba(255,140,66,.1);border:1.5px solid rgba(255,140,66,.3);flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:800;color:#FF8C42">'+(i+1)+'</div><div style="font-size:13px;color:var(--text,#1a1a2e)">'+item+'</div></div>';
  }).join('');
}

function mpRenderNutritionSummary(d){
  var el=document.getElementById('mp-nutrition-summary');
  if(!el) return;
  var totals={cal:0,protein:0,carbs:0,fat:0,days:0};
  if(d.meals){
    Object.values(d.meals).forEach(function(dayMeals){
      var dayHasMeal=false;
      MP_MEAL_TYPES.forEach(function(t){
        var m=dayMeals[t.key];
        if(m&&m.recipeId){
          var r=MP_RECIPES.find(function(x){return x.id===m.recipeId;});
          if(r){ totals.cal+=r.cal; totals.protein+=r.protein; totals.carbs+=r.carbs; totals.fat+=r.fat; dayHasMeal=true; }
        }
      });
      if(dayHasMeal) totals.days++;
    });
  }
  var bars=[
    {label:'ক্যালোরি',val:totals.cal,max:14000,color:'#FF8C42',unit:'kcal'},
    {label:'প্রোটিন',val:totals.protein,max:350,color:'#7C3AED',unit:'g'},
    {label:'কার্বস',val:totals.carbs,max:1400,color:'#3B82F6',unit:'g'},
    {label:'ফ্যাট',val:totals.fat,max:490,color:'#10B981',unit:'g'},
  ];
  el.innerHTML='<div style="font-size:11px;color:var(--text2,#888);margin-bottom:10px">'+totals.days+' দিনের ডেটা</div>'+bars.map(function(b){
    var pct=b.max>0?Math.min(100,Math.round(b.val/b.max*100)):0;
    return '<div style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;font-size:11px;color:var(--text2,#888);margin-bottom:4px"><span>'+b.label+'</span><span style="font-weight:700;color:var(--text,#1a1a2e)">'+b.val+' '+b.unit+'</span></div><div style="background:var(--bg2,#f3f4f6);height:6px;border-radius:4px;overflow:hidden"><div style="width:'+pct+'%;height:100%;background:'+b.color+';border-radius:4px;transition:.8s"></div></div></div>';
  }).join('');
}

function mpFilterRecipes(filter){
  _mpRecipeFilter=filter;
  ['all','breakfast','lunch','dinner','snack'].forEach(function(f){
    var btn=document.getElementById('mp-rf-'+f);
    if(!btn) return;
    if(f===filter){
      btn.style.background='linear-gradient(135deg,#FF8C42,#FF6B00)';
      btn.style.color='#fff';
      btn.style.border='none';
    } else {
      btn.style.background='var(--bg2,#f3f4f6)';
      btn.style.color='var(--text2,#888)';
      btn.style.border='1.5px solid var(--border,#e5e7eb)';
    }
  });
  mpRenderRecipes(filter);
}

function mpRenderRecipes(filter){
  var el=document.getElementById('mp-recipe-grid');
  if(!el) return;
  var list=filter==='all'?MP_RECIPES:MP_RECIPES.filter(function(r){return r.meal===filter;});
  el.innerHTML='';
  list.forEach(function(r){
    var mtype=MP_MEAL_TYPES.find(function(t){return t.key===r.meal;})||{icon:'🍽️',label:''};
    var card=document.createElement('div');
    card.style.cssText='background:var(--card,#fff);border:1.5px solid var(--border,#e5e7eb);border-radius:14px;padding:14px;cursor:pointer;';
    card.innerHTML='<div style="display:flex;align-items:center;gap:12px"><div style="font-size:28px;flex-shrink:0">'+mtype.icon+'</div><div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:800;color:var(--text,#1a1a2e)">'+r.name+'</div><div style="font-size:11px;color:var(--text2,#888);margin-top:2px">'+r.cal+' kcal • '+r.protein+'g প্রোটিন • ⏱'+r.time+'মিন</div><div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:5px">'+r.tags.map(function(t){return '<span style="font-size:9px;padding:2px 7px;background:rgba(255,140,66,.1);color:#FF8C42;border-radius:8px;font-weight:700">'+t+'</span>';}).join('')+'</div></div><button onclick="event.stopPropagation();mpShowRecipeDetail(\''+r.id+'\')" style="flex-shrink:0;padding:6px 10px;background:var(--bg2,#f3f4f6);color:var(--text2,#888);border:1.5px solid var(--border,#e5e7eb);border-radius:10px;font-size:10px;font-weight:700;cursor:pointer">বিস্তারিত</button></div>';
    el.appendChild(card);
  });
}

function mpShowRecipeDetail(recipeId){
  var r=MP_RECIPES.find(function(x){return x.id===recipeId;});
  if(!r) return;
  var mtype=MP_MEAL_TYPES.find(function(t){return t.key===r.meal;})||{icon:'🍽️'};
  var el=document.getElementById('mp-recipe-detail-content');
  if(el){
    el.innerHTML='<div style="font-size:24px;text-align:center;margin-bottom:12px">'+mtype.icon+'</div><div style="font-size:20px;font-weight:900;color:var(--text,#1a1a2e);margin-bottom:6px">'+r.name+'</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px">'+[{l:'ক্যালোরি',v:r.cal+'kcal',c:'#FF8C42'},{l:'প্রোটিন',v:r.protein+'g',c:'#7C3AED'},{l:'কার্বস',v:r.carbs+'g',c:'#3B82F6'},{l:'ফ্যাট',v:r.fat+'g',c:'#10B981'},{l:'সময়',v:r.time+'মিন',c:'#F59E0B'}].map(function(x){return '<div style="background:var(--bg2,#f3f4f6);border-radius:10px;padding:8px 10px;text-align:center"><div style="font-size:13px;font-weight:800;color:'+x.c+'">'+x.v+'</div><div style="font-size:9px;color:var(--text2,#888)">'+x.l+'</div></div>';}).join('')+'</div><div style="font-size:13px;font-weight:800;color:var(--text,#1a1a2e);margin-bottom:8px">উপাদান</div><div style="display:flex;flex-direction:column;gap:6px;margin-bottom:16px">'+r.ingredients.map(function(ing){return '<div style="font-size:13px;color:var(--text,#1a1a2e);padding:8px 12px;background:var(--bg2,#f3f4f6);border-radius:8px;">• '+ing+'</div>';}).join('')+'</div><div style="font-size:13px;font-weight:800;color:var(--text,#1a1a2e);margin-bottom:8px">রান্নার পদ্ধতি</div><div style="font-size:13px;color:var(--text2,#888);line-height:1.7;background:var(--bg2,#f3f4f6);border-radius:10px;padding:12px">'+r.steps+'</div>';
  }
  var modal=document.getElementById('mp-recipe-detail-modal');
  if(modal) modal.style.display='flex';
}

function mpToggleRamadan(){
  var d=mpGetData();
  d.ramadanMode=!d.ramadanMode;
  mpSaveData(d);
  var sec=document.getElementById('mp-ramadan-section');
  if(sec) sec.style.display=d.ramadanMode?'block':'none';
  if(d.ramadanMode){ mpRenderRamadan(d); mpStartFastingTimer(); }
  else { if(_mpRamadanTimer) clearInterval(_mpRamadanTimer); }
}

function mpRenderRamadan(d){
  var sehriEl=document.getElementById('mp-sehri-list');
  var iftarEl=document.getElementById('mp-iftar-list');
  var rd=d.ramadan||{sehri:[],iftar:[]};
  function renderList(el, items, type){
    if(!el) return;
    el.innerHTML='';
    (items||[]).forEach(function(item,i){
      var row=document.createElement('div');
      row.style.cssText='display:flex;align-items:center;gap:8px;padding:8px;background:rgba(255,255,255,.05);border-radius:8px;';
      row.innerHTML='<div style="flex:1;font-size:12px;color:rgba(255,255,255,.8)">'+item.name+(item.cal?' ('+item.cal+'kcal)':'')+'</div><button onclick="mpRemoveRamadanItem(\''+type+'\','+i+')" style="width:22px;height:22px;border-radius:6px;background:rgba(239,68,68,.2);border:none;color:#EF4444;font-size:12px;cursor:pointer;font-weight:700">×</button>';
      el.appendChild(row);
    });
  }
  renderList(sehriEl, rd.sehri, 'sehri');
  renderList(iftarEl, rd.iftar, 'iftar');
}

function mpOpenAddRamadan(type){
  var name=prompt((type==='sehri'?'সেহরি':'ইফতার')+' আইটেম লিখুন (যেমন: খেজুর):');
  if(!name||!name.trim()) return;
  var calStr=prompt('ক্যালোরি (ঐচ্ছিক, খালি রাখলে এড়িয়ে যাবে):');
  var d=mpGetData();
  if(!d.ramadan) d.ramadan={sehri:[],iftar:[]};
  if(!d.ramadan[type]) d.ramadan[type]=[];
  d.ramadan[type].push({name:name.trim(), cal:Number(calStr)||0});
  mpSaveData(d);
  mpRenderRamadan(d);
}

function mpRemoveRamadanItem(type, idx){
  var d=mpGetData();
  if(d.ramadan&&d.ramadan[type]) d.ramadan[type].splice(idx,1);
  mpSaveData(d);
  mpRenderRamadan(d);
}

function mpStartFastingTimer(){
  if(_mpRamadanTimer) clearInterval(_mpRamadanTimer);
  function tick(){
    var now=new Date();
    var iftarH=18, iftarM=30;
    var iftar=new Date(now.getFullYear(),now.getMonth(),now.getDate(),iftarH,iftarM,0);
    var sehriH=4, sehriM=30;
    var sehri=new Date(now.getFullYear(),now.getMonth(),now.getDate(),sehriH,sehriM,0);
    var timerEl=document.getElementById('mp-fasting-timer');
    var labelEl=document.getElementById('mp-fasting-label');
    if(!timerEl) { clearInterval(_mpRamadanTimer); return; }
    var diff, label;
    if(now<sehri){ diff=sehri-now; label='সেহরি পর্যন্ত'; }
    else if(now<iftar){ diff=iftar-now; label='ইফতার পর্যন্ত'; }
    else { diff=0; label='ইফতারের সময় হয়েছে! 🌙'; }
    if(diff>0){
      var h=Math.floor(diff/3600000);
      var m=Math.floor((diff%3600000)/60000);
      var s=Math.floor((diff%60000)/1000);
      timerEl.textContent=(h<10?'0':'')+h+':'+(m<10?'0':'')+m+':'+(s<10?'0':'')+s;
    } else {
      timerEl.textContent='🌙';
    }
    if(labelEl) labelEl.textContent=label;
  }
  tick();
  _mpRamadanTimer=setInterval(tick,1000);
}

