var _mhBreathInterval = null;
var _mhBreathRunning = false;
var _mhBreathPhase = 0;
var _mhBreathSec = 0;
var _mhBreathCycles = 0;
var _mhBreathConfig = {box:{phases:['শ্বাস নিন','ধরুন','ছাড়ুন','বিশ্রাম'],times:[4,4,4,4]},['478']:{phases:['শ্বাস নিন','ধরুন','ছাড়ুন'],times:[4,7,8]},calm:{phases:['শ্বাস নিন','ছাড়ুন'],times:[5,5]}};
var _mhBreathType = 'box';
var _mhDhikrCount = 0;
var _mhDhikrArabic = 'سُبْحَانَ اللّٰهِ';
var _mhDhikrBangla = 'সুবহানাল্লাহ';
var _mhDhikrTarget = 33;
var _mhStressTriggers = [];

function mhKey(){ return 'rz_mh_'+new Date().toISOString().slice(0,10); }
function mhWeekKey(){ return 'rz_mh_week_'+new Date().getFullYear()+'_'+Math.ceil(((new Date()-new Date(new Date().getFullYear(),0,1))/86400000+new Date(new Date().getFullYear(),0,1).getDay()+1)/7); }

function mhGetData(){ try{ return JSON.parse(localStorage.getItem(mhKey())||'{}'); }catch(e){ return {}; } }
function mhSaveData(d){ localStorage.setItem(mhKey(), JSON.stringify(d)); }
function mhGetWeekData(){ try{ return JSON.parse(localStorage.getItem(mhWeekKey())||'{}'); }catch(e){ return {}; } }
function mhSaveWeekData(d){ localStorage.setItem(mhWeekKey(), JSON.stringify(d)); }

function mhCheckMode(){
  var k=document.getElementById('mh-kids-wrap');
  var a=document.getElementById('mh-adult-wrap');
  if(!k||!a){ setTimeout(mhCheckMode,150); return; }
  var isAdult=window.rzMode==='forme';
  k.style.display=isAdult?'none':'block';
  a.style.display=isAdult?'block':'none';
  if(isAdult) mhRender();
}

function mhRender(){
  var d=mhGetData();
  mhRenderHero(d);
  mhRenderMoodCalendar();
  mhRenderSelfCare(d);
  mhRenderCBTList(d);
  mhRenderWeeklyReport();
  if(d.stress!=null){ var sl=document.getElementById('mh-stress-slider'); if(sl) sl.value=d.stress; mhUpdateStressDisplay(d.stress); }
  if(d.mood){ mhHighlightMood(d.mood); }
}

var MH_MOOD_EMOJIS = ['','😢','😔','😐','🙂','😄'];
var MH_MOOD_COLORS = ['','#EF4444','#F59E0B','#6B7280','#10B981','#7C3AED'];
var MH_MOOD_LABELS = ['','খুব খারাপ','খারাপ','মাঝারি','ভালো','খুব ভালো'];

function mhRenderHero(d){
  var dateEl=document.getElementById('mh-hero-date');
  var moodLabel=document.getElementById('mh-hero-mood-label');
  var tileMood=document.getElementById('mh-tile-mood');
  var tileStress=document.getElementById('mh-tile-stress');
  var tileStreak=document.getElementById('mh-tile-streak');
  var tileSC=document.getElementById('mh-tile-selfcare');
  var days=['রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার','শনিবার'];
  if(dateEl) dateEl.textContent=days[new Date().getDay()]+', আজ';
  if(moodLabel) moodLabel.textContent=d.mood?MH_MOOD_LABELS[d.mood]:'মুড লগ করুন';
  if(tileMood) tileMood.textContent=d.mood?MH_MOOD_EMOJIS[d.mood]:'😐';
  if(tileStress) tileStress.textContent=d.stress!=null?d.stress+'/10':'—';
  // Streak
  var streak=0;
  for(var i=0;i<30;i++){
    var dt=new Date(); dt.setDate(dt.getDate()-i);
    var k='rz_mh_'+dt.toISOString().slice(0,10);
    var dd; try{ dd=JSON.parse(localStorage.getItem(k)||'{}'); }catch(e){ dd={}; }
    if(dd.mood) streak++; else if(i>0) break;
  }
  if(tileStreak) tileStreak.textContent=streak;
  var scDone=d.selfcare?Object.values(d.selfcare).filter(Boolean).length:0;
  if(tileSC) tileSC.textContent=scDone+'/6';
  // Score
  var score=0, factors=0;
  if(d.mood){ score+=d.mood/5*100; factors++; }
  if(d.stress!=null){ score+=(10-d.stress)/9*100; factors++; }
  if(d.selfcare){ var sc=Object.values(d.selfcare).filter(Boolean).length; score+=sc/6*100; factors++; }
  var finalScore=factors>0?Math.round(score/factors):0;
  var ring=document.getElementById('mh-score-ring');
  var txt=document.getElementById('mh-score-txt');
  if(ring){ var circ=188.5; ring.style.strokeDashoffset=circ-(circ*finalScore/100); }
  if(txt) txt.textContent=factors>0?finalScore:'—';
}

function mhSetMood(val){
  mhHighlightMood(val);
}

function mhHighlightMood(val){
  for(var i=1;i<=5;i++){
    var btn=document.getElementById('mh-m'+i);
    if(!btn) continue;
    if(i===val){
      btn.style.borderColor=MH_MOOD_COLORS[i];
      btn.style.background='rgba(124,58,237,.08)';
      btn.style.transform='scale(1.2)';
    } else {
      btn.style.borderColor='transparent';
      btn.style.background='none';
      btn.style.transform='scale(1)';
    }
  }
}

function mhSaveMood(){
  var d=mhGetData();
  var selected=0;
  for(var i=1;i<=5;i++){
    var btn=document.getElementById('mh-m'+i);
    if(btn&&btn.style.transform==='scale(1.2)') selected=i;
  }
  if(!selected){ alert('একটি মুড বেছে নিন।'); return; }
  var note=document.getElementById('mh-mood-note');
  d.mood=selected;
  d.moodNote=note?note.value:'';
  mhSaveData(d);
  mhRenderHero(d);
  mhRenderMoodCalendar();
  mhRenderWeeklyReport();
  var saveBtn=document.querySelector('[onclick="mhSaveMood()"]');
  if(saveBtn){ saveBtn.textContent='✓ সেভ হয়েছে!'; setTimeout(function(){saveBtn.textContent='মুড সেভ করুন';},2000); }
}

function mhRenderMoodCalendar(){
  var el=document.getElementById('mh-mood-calendar');
  if(!el) return;
  var days=['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
  el.innerHTML='';
  for(var i=6;i>=0;i--){
    var dt=new Date(); dt.setDate(dt.getDate()-i);
    var k='rz_mh_'+dt.toISOString().slice(0,10);
    var dd; try{ dd=JSON.parse(localStorage.getItem(k)||'{}'); }catch(e){ dd={}; }
    var isToday=i===0;
    var cell=document.createElement('div');
    cell.style.cssText='text-align:center;padding:8px 4px;border-radius:10px;border:1.5px solid '+(isToday?'rgba(124,58,237,.4)':'var(--border,#e5e7eb)')+';background:'+(isToday?'rgba(124,58,237,.05)':'var(--bg2,#f3f4f6)')+';';
    cell.innerHTML='<div style="font-size:9px;font-weight:700;color:var(--text2,#888);margin-bottom:4px">'+days[dt.getDay()]+'</div><div style="font-size:18px;line-height:1">'+(dd.mood?MH_MOOD_EMOJIS[dd.mood]:'·')+'</div><div style="font-size:8px;color:var(--text2,#888);margin-top:2px">'+dt.getDate()+'</div>';
    el.appendChild(cell);
  }
}

function mhSetBreathType(){
  var sel=document.getElementById('mh-breath-type');
  if(!sel) return;
  _mhBreathType=sel.value;
  var descs={box:'৪ সেকেন্ড শ্বাস নিন → ৪ ধরুন → ৪ ছাড়ুন → ৪ বিশ্রাম','478':'৪ সেকেন্ড শ্বাস → ৭ সেকেন্ড ধরুন → ৮ সেকেন্ড ছাড়ুন',calm:'৫ সেকেন্ড শ্বাস নিন → ৫ সেকেন্ড ছাড়ুন'};
  var desc=document.getElementById('mh-breath-desc');
  if(desc) desc.textContent=descs[_mhBreathType]||'';
  if(_mhBreathRunning) mhStopBreath();
  _mhBreathPhase=0; _mhBreathSec=0; _mhBreathCycles=0;
  mhUpdateBreathDisplay();
}

function mhToggleBreath(){
  if(_mhBreathRunning) mhStopBreath();
  else mhStartBreath();
}

function mhStartBreath(){
  _mhBreathRunning=true;
  _mhBreathPhase=0; _mhBreathSec=0;
  var btn=document.getElementById('mh-breath-btn');
  if(btn) btn.textContent='থামুন';
  _mhBreathInterval=setInterval(mhBreathTick,1000);
  mhUpdateBreathDisplay();
}

function mhStopBreath(){
  _mhBreathRunning=false;
  clearInterval(_mhBreathInterval);
  var btn=document.getElementById('mh-breath-btn');
  if(btn) btn.textContent='শুরু করুন';
  var lbl=document.getElementById('mh-breath-label');
  if(lbl) lbl.textContent='শুরু করুন';
  var cnt=document.getElementById('mh-breath-count');
  var cfg=_mhBreathConfig[_mhBreathType];
  if(cnt&&cfg) cnt.textContent=cfg.times[0];
  var ring=document.getElementById('mh-breath-ring');
  if(ring) ring.style.strokeDashoffset='439.8';
  var circle=document.getElementById('mh-breath-circle');
  if(circle){ circle.style.width='90px'; circle.style.height='90px'; circle.style.boxShadow='none'; }
}

function mhBreathTick(){
  var cfg=_mhBreathConfig[_mhBreathType];
  if(!cfg) return;
  var phaseDur=cfg.times[_mhBreathPhase];
  _mhBreathSec++;
  if(_mhBreathSec>=phaseDur){
    _mhBreathSec=0;
    _mhBreathPhase=(_mhBreathPhase+1)%cfg.phases.length;
    if(_mhBreathPhase===0) _mhBreathCycles++;
  }
  mhUpdateBreathDisplay();
}

function mhUpdateBreathDisplay(){
  var cfg=_mhBreathConfig[_mhBreathType];
  if(!cfg) return;
  var phaseDur=cfg.times[_mhBreathPhase];
  var remaining=phaseDur-_mhBreathSec;
  var cnt=document.getElementById('mh-breath-count');
  var lbl=document.getElementById('mh-breath-label');
  var ring=document.getElementById('mh-breath-ring');
  var circle=document.getElementById('mh-breath-circle');
  var cyclesEl=document.getElementById('mh-breath-cycles');
  if(cnt) cnt.textContent=remaining;
  if(lbl) lbl.textContent=cfg.phases[_mhBreathPhase]||'';
  var progress=_mhBreathSec/phaseDur;
  var circumference=439.8;
  if(ring) ring.style.strokeDashoffset=circumference-(circumference*progress);
  var isInhale=_mhBreathPhase===0;
  var isHold=cfg.phases[_mhBreathPhase]==='ধরুন';
  if(circle){
    var size=isInhale?(90+progress*30):(isHold?120:(120-progress*30));
    size=Math.max(90,Math.min(120,size));
    circle.style.width=size+'px';
    circle.style.height=size+'px';
    circle.style.boxShadow=isHold?'0 0 20px rgba(124,58,237,.4)':'none';
  }
  if(cyclesEl) cyclesEl.textContent=_mhBreathCycles+' cycle';
}

function mhUpdateStressDisplay(val){
  val=Number(val);
  var el=document.getElementById('mh-stress-val');
  var color=val<=3?'#10B981':val<=6?'#F59E0B':'#EF4444';
  if(el){ el.textContent=val+'/10'; el.style.color=color; }
}

function mhToggleTrigger(btn, name){
  var idx=_mhStressTriggers.indexOf(name);
  if(idx>-1){
    _mhStressTriggers.splice(idx,1);
    btn.style.background='var(--bg2,#f3f4f6)';
    btn.style.color='var(--text2,#888)';
    btn.style.borderColor='var(--border,#e5e7eb)';
  } else {
    _mhStressTriggers.push(name);
    btn.style.background='rgba(124,58,237,.1)';
    btn.style.color='#7C3AED';
    btn.style.borderColor='rgba(124,58,237,.4)';
  }
}

function mhSaveStress(){
  var d=mhGetData();
  var sl=document.getElementById('mh-stress-slider');
  d.stress=sl?Number(sl.value):5;
  d.stressTriggers=_mhStressTriggers.slice();
  mhSaveData(d);
  mhRenderHero(d);
  mhRenderWeeklyReport();
  var btn=document.querySelector('[onclick="mhSaveStress()"]');
  if(btn){ btn.textContent='✓ সেভ হয়েছে!'; setTimeout(function(){btn.textContent='স্ট্রেস লগ করুন';},2000); }
}

function mhToggleSelfCare(el, name){
  var d=mhGetData();
  if(!d.selfcare) d.selfcare={};
  var key=el.getAttribute('data-key');
  d.selfcare[key]=!d.selfcare[key];
  mhSaveData(d);
  var check=el.querySelector('.mh-sc-check');
  if(d.selfcare[key]){
    el.style.borderColor='rgba(124,58,237,.4)';
    el.style.background='rgba(124,58,237,.05)';
    if(check){ check.innerHTML='✓'; check.style.background='#7C3AED'; check.style.borderColor='#7C3AED'; check.style.color='#fff'; }
  } else {
    el.style.borderColor='transparent';
    el.style.background='var(--bg2,#f3f4f6)';
    if(check){ check.innerHTML=''; check.style.background='var(--card,#fff)'; check.style.borderColor='var(--border,#e5e7eb)'; check.style.color=''; }
  }
  var count=Object.values(d.selfcare).filter(Boolean).length;
  var countEl=document.getElementById('mh-selfcare-count');
  if(countEl) countEl.textContent=count+'/6';
  var tileSC=document.getElementById('mh-tile-selfcare');
  if(tileSC) tileSC.textContent=count+'/6';
}

function mhRenderSelfCare(d){
  if(!d.selfcare) return;
  var items=document.querySelectorAll('#mh-selfcare-items > div');
  var count=0;
  items.forEach(function(el){
    var key=el.getAttribute('data-key');
    if(!key) return;
    var check=el.querySelector('.mh-sc-check');
    if(d.selfcare[key]){
      count++;
      el.style.borderColor='rgba(124,58,237,.4)';
      el.style.background='rgba(124,58,237,.05)';
      if(check){ check.innerHTML='✓'; check.style.background='#7C3AED'; check.style.borderColor='#7C3AED'; check.style.color='#fff'; }
    }
  });
  var countEl=document.getElementById('mh-selfcare-count');
  if(countEl) countEl.textContent=count+'/6';
}

function mhSaveCBT(){
  var situation=document.getElementById('mh-cbt-situation');
  var thought=document.getElementById('mh-cbt-thought');
  var emotion=document.getElementById('mh-cbt-emotion');
  var intensity=document.getElementById('mh-cbt-intensity');
  var reframe=document.getElementById('mh-cbt-reframe');
  if(!situation||!situation.value.trim()||!thought||!thought.value.trim()){ alert('পরিস্থিতি এবং চিন্তা লিখুন।'); return; }
  var d=mhGetData();
  if(!d.cbt) d.cbt=[];
  d.cbt.unshift({ situation:situation.value.trim(), thought:thought.value.trim(), emotion:emotion?emotion.value:'', intensity:intensity?Number(intensity.value)||0:0, reframe:reframe?reframe.value.trim():'', time:Date.now() });
  if(d.cbt.length>10) d.cbt=d.cbt.slice(0,10);
  mhSaveData(d);
  if(situation) situation.value='';
  if(thought) thought.value='';
  if(emotion) emotion.value='';
  if(intensity) intensity.value='';
  if(reframe) reframe.value='';
  mhRenderCBTList(d);
}

function mhRenderCBTList(d){
  var el=document.getElementById('mh-cbt-list');
  if(!el||!d.cbt||!d.cbt.length) return;
  el.innerHTML='<div style="font-size:11px;font-weight:700;color:var(--text2,#888);margin-bottom:6px">সম্প্রতি সেভ করা রেকর্ড</div>'+d.cbt.slice(0,3).map(function(r){
    return '<div style="background:var(--bg2,#f3f4f6);border-radius:10px;padding:10px;border-left:3px solid #7C3AED"><div style="font-size:11px;color:var(--text2,#888);margin-bottom:3px">পরিস্থিতি: <span style="color:var(--text,#1a1a2e);font-weight:700">'+r.situation.substring(0,60)+(r.situation.length>60?'...':'')+'</span></div>'+(r.reframe?'<div style="font-size:11px;color:#10B981;margin-top:4px">✨ রিফ্রেম: '+r.reframe.substring(0,80)+'</div>':'')+'</div>';
  }).join('');
}

function mhSetDhikr(arabic, bangla){
  _mhDhikrArabic=arabic;
  _mhDhikrBangla=bangla;
  _mhDhikrCount=0;
  var aEl=document.getElementById('mh-dhikr-arabic');
  var bEl=document.getElementById('mh-dhikr-bangla');
  var cEl=document.getElementById('mh-dhikr-count');
  var bar=document.getElementById('mh-dhikr-bar');
  if(aEl) aEl.textContent=arabic;
  if(bEl) bEl.textContent=bangla;
  if(cEl) cEl.textContent=0;
  if(bar) bar.style.width='0%';
  var btns=document.querySelectorAll('#mh-dhikr-btns button');
  btns.forEach(function(btn){
    btn.style.background='rgba(124,58,237,.15)';
    btn.style.color='rgba(167,139,250,.7)';
    if(btn.textContent.trim()===bangla){
      btn.style.background='rgba(124,58,237,.3)';
      btn.style.color='#a78bfa';
    }
  });
}

function mhDhikrTap(){
  _mhDhikrCount++;
  var cEl=document.getElementById('mh-dhikr-count');
  var bar=document.getElementById('mh-dhikr-bar');
  var btn=document.getElementById('mh-dhikr-tap-btn');
  if(cEl) cEl.textContent=_mhDhikrCount;
  var pct=Math.min(100,Math.round(_mhDhikrCount/_mhDhikrTarget*100));
  if(bar) bar.style.width=pct+'%';
  if(btn){ btn.style.transform='scale(0.92)'; setTimeout(function(){btn.style.transform='scale(1)';},100); }
  if(_mhDhikrCount===_mhDhikrTarget){
    setTimeout(function(){ alert('মাশাআল্লাহ! '+_mhDhikrTarget+'বার সম্পন্ন হয়েছে 🤲'); },200);
  }
}

function mhDhikrReset(){
  _mhDhikrCount=0;
  var cEl=document.getElementById('mh-dhikr-count');
  var bar=document.getElementById('mh-dhikr-bar');
  if(cEl) cEl.textContent=0;
  if(bar) bar.style.width='0%';
}

function mhStartGrounding(){
  var btn=document.getElementById('mh-ground-btn');
  var content=document.getElementById('mh-grounding-content');
  if(!content) return;
  var steps=[
    {n:5,icon:'👁️',label:'৫টি জিনিস দেখুন',desc:'এখন চারপাশে ৫টি আলাদা জিনিস খুঁজে বের করুন এবং মনে মনে নাম বলুন।'},
    {n:4,icon:'✋',label:'৪টি জিনিস ছুঁয়ে দেখুন',desc:'কাছের ৪টি জিনিস স্পর্শ করুন এবং টেক্সচার অনুভব করুন।'},
    {n:3,icon:'👂',label:'৩টি শব্দ শুনুন',desc:'চুপ করে বসে ৩টি শব্দ শুনুন — পাখির ডাক, ট্রাফিক, বাতাস।'},
    {n:2,icon:'👃',label:'২টি গন্ধ',desc:'আপনার কাছে কোনো সুগন্ধ বা গন্ধ আছে? চা, সাবান, খাবার?'},
    {n:1,icon:'👅',label:'১টি স্বাদ নিন',desc:'এক ঢোক পানি পান করুন বা কিছু একটু খান।'},
  ];
  var current=0;
  if(btn) btn.style.display='none';
  function showStep(){
    if(current>=steps.length){
      content.innerHTML='<div style="text-align:center;padding:20px"><div style="font-size:32px;margin-bottom:12px">🌟</div><div style="font-size:15px;font-weight:800;color:var(--text,#1a1a2e);margin-bottom:6px">অভিনন্দন!</div><div style="font-size:13px;color:var(--text2,#888)">আপনি grounding সম্পন্ন করেছেন। এখন আরো ভালো অনুভব করছেন?</div><button onclick="mhResetGrounding()" style="margin-top:14px;padding:10px 20px;background:linear-gradient(135deg,#7C3AED,#06B6D4);color:#fff;border:none;border-radius:10px;font-size:12px;font-weight:700;cursor:pointer">আবার করুন</button></div>';
      return;
    }
    var s=steps[current];
    content.innerHTML='<div style="text-align:center;padding:16px 0"><div style="width:60px;height:60px;border-radius:20px;background:linear-gradient(135deg,rgba(124,58,237,.15),rgba(6,182,212,.1));border:2px solid rgba(124,58,237,.3);display:flex;align-items:center;justify-content:center;font-size:28px;margin:0 auto 12px">'+s.icon+'</div><div style="font-size:32px;font-weight:900;color:#7C3AED;margin-bottom:6px">'+s.n+'</div><div style="font-size:15px;font-weight:800;color:var(--text,#1a1a2e);margin-bottom:8px">'+s.label+'</div><div style="font-size:13px;color:var(--text2,#888);line-height:1.6;max-width:320px;margin:0 auto 20px">'+s.desc+'</div><button onclick="mhGroundNext()" style="padding:12px 28px;background:linear-gradient(135deg,#7C3AED,#06B6D4);color:#fff;border:none;border-radius:12px;font-size:13px;font-weight:800;cursor:pointer">সম্পন্ন ✓</button></div>';
    window._mhGroundNext=function(){ current++; showStep(); };
  }
  window.mhGroundNext=function(){ current++; showStep(); };
  showStep();
}

function mhResetGrounding(){
  var btn=document.getElementById('mh-ground-btn');
  var content=document.getElementById('mh-grounding-content');
  if(btn) btn.style.display='';
  if(content){
    content.innerHTML=['<div style="display:flex;flex-direction:column;gap:8px">',
      ...[{n:5,icon:'👁️',l:'৫টি জিনিস দেখুন',d:'চারপাশে ৫টি জিনিস খুঁজে বের করুন'},{n:4,icon:'✋',l:'৪টি জিনিস ছুঁয়ে দেখুন',d:'টেক্সচার অনুভব করুন'},{n:3,icon:'👂',l:'৩টি শব্দ শুনুন',d:'মনোযোগ দিয়ে শুনুন'},{n:2,icon:'👃',l:'২টি গন্ধ শুঁকুন',d:'যে কোনো সুগন্ধ/গন্ধ'},{n:1,icon:'👅',l:'১টি স্বাদ নিন',d:'পানি পান করুন বা কিছু খান'}].map(function(s){
        return '<div style="background:rgba(124,58,237,.06);border:1.5px solid rgba(124,58,237,.15);border-radius:12px;padding:12px;display:flex;align-items:center;gap:10px"><div style="width:28px;height:28px;border-radius:8px;background:rgba(124,58,237,.15);display:flex;align-items:center;justify-content:center;font-size:14px;font-weight:900;color:#7C3AED;flex-shrink:0">'+s.n+'</div><div><div style="font-size:12px;font-weight:700;color:var(--text,#1a1a2e)">'+s.icon+' '+s.l+'</div><div style="font-size:11px;color:var(--text2,#888)">'+s.d+'</div></div></div>';
      }),
    '</div>'].join('');
  }
}

function mhRenderWeeklyReport(){
  var el=document.getElementById('mh-weekly-report');
  if(!el) return;
  var moods=[],stresses=[],scScores=[];
  for(var i=6;i>=0;i--){
    var dt=new Date(); dt.setDate(dt.getDate()-i);
    var k='rz_mh_'+dt.toISOString().slice(0,10);
    var dd; try{ dd=JSON.parse(localStorage.getItem(k)||'{}'); }catch(e){ dd={}; }
    if(dd.mood) moods.push(dd.mood);
    if(dd.stress!=null) stresses.push(dd.stress);
    if(dd.selfcare) scScores.push(Object.values(dd.selfcare).filter(Boolean).length);
  }
  var avgMood=moods.length?Math.round(moods.reduce(function(a,b){return a+b;},0)/moods.length*10)/10:null;
  var avgStress=stresses.length?Math.round(stresses.reduce(function(a,b){return a+b;},0)/stresses.length*10)/10:null;
  var avgSC=scScores.length?Math.round(scScores.reduce(function(a,b){return a+b;},0)/scScores.length*10)/10:null;
  var items=[
    {label:'গড় মুড',val:avgMood?MH_MOOD_EMOJIS[Math.round(avgMood)]+' '+MH_MOOD_LABELS[Math.round(avgMood)]:'কোনো ডেটা নেই',sub:avgMood?avgMood+'/5':'',color:'#7C3AED'},
    {label:'গড় স্ট্রেস',val:avgStress!=null?avgStress+'/10':'কোনো ডেটা নেই',sub:avgStress!=null?(avgStress<=3?'কম ✓':avgStress<=6?'মাঝারি':'বেশি ⚠️'):'',color:avgStress!=null?(avgStress<=3?'#10B981':avgStress<=6?'#F59E0B':'#EF4444'):'#888'},
    {label:'গড় Self-care',val:avgSC!=null?avgSC+'/6':'কোনো ডেটা নেই',sub:avgSC!=null?Math.round(avgSC/6*100)+'% সম্পন্ন':'',color:'#06B6D4'},
    {label:'মুড লগ করা দিন',val:moods.length+'/7',sub:'এই সপ্তাহে',color:'#F59E0B'},
  ];
  el.innerHTML=items.map(function(item){
    return '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:var(--bg2,#f3f4f6);border-radius:12px"><div><div style="font-size:11px;font-weight:700;color:var(--text2,#888)">'+item.label+'</div>'+(item.sub?'<div style="font-size:10px;color:var(--text2,#888);opacity:.7">'+item.sub+'</div>':'')+'</div><div style="font-size:14px;font-weight:900;color:'+item.color+'">'+item.val+'</div></div>';
  }).join('');
}

