var TD_STATUS_MAP = { backlog:{label:'Backlog',col:'backlog'}, inprogress:{label:'চলছে',col:'inprogress'}, review:{label:'রিভিউ',col:'review'}, done:{label:'সম্পন্ন',col:'done'} };

var _tdCache = null;
function tdGetData(){
  if(_tdCache) return _tdCache;
  try{ _tdCache=JSON.parse(localStorage.getItem('rz_td_data')||'{"tasks":[],"projects":[]}'); }catch(e){ _tdCache={tasks:[],projects:[]}; }
  return _tdCache;
}
function tdSaveData(d){ _tdCache=d; try{localStorage.setItem('rz_td_data', JSON.stringify(d));}catch(e){} }

async function tdLoadFromSb(){
  if(!window.sbUser||!_sb) return;
  try{
    var tr=await _sb.from('todo_tasks').select('*').eq('user_id',sbUser.id).order('created_at',{ascending:false});
    var pr=await _sb.from('todo_projects').select('*').eq('user_id',sbUser.id).order('created_at',{ascending:true});
    var tasks=(tr.data||[]).map(function(r){return{id:r.id,title:r.title,desc:r.task_desc||'',priority:r.priority||'normal',energy:r.energy||'medium',due:r.due||'',islamic:r.islamic||'',project:r.project||'',status:r.status||'backlog',recur:r.recur||'',pomos:r.pomos||1,tags:r.tags||[],subtasks:r.subtasks||[],createdAt:r.created_date||'',completedDate:r.completed_date||''};});
    var projects=(pr.data||[]).map(function(r){return{id:r.id,name:r.name,color:r.color||'#6366F1'};});
    _tdCache={tasks:tasks,projects:projects};
  }catch(e){}
}
function _tdTaskToRow(t){
  return{id:t.id,user_id:sbUser.id,title:t.title,task_desc:t.desc||'',priority:t.priority||'normal',energy:t.energy||'medium',due:t.due||'',islamic:t.islamic||'',project:t.project||'',status:t.status||'backlog',recur:t.recur||'',pomos:t.pomos||1,tags:t.tags||[],subtasks:t.subtasks||[],created_date:t.createdAt||'',completed_date:t.completedDate||''};
}
function tdUpsertTaskSb(task){
  if(!window.sbUser||!_sb) return;
  _sb.from('todo_tasks').upsert(_tdTaskToRow(task),{onConflict:'id'});
}
function tdDeleteTaskSb(id){
  if(!window.sbUser||!_sb) return;
  _sb.from('todo_tasks').delete().eq('id',id).eq('user_id',sbUser.id);
}
function tdUpsertProjectSb(proj){
  if(!window.sbUser||!_sb) return;
  _sb.from('todo_projects').upsert({id:proj.id,user_id:sbUser.id,name:proj.name,color:proj.color||'#6366F1'},{onConflict:'id'});
}
function tdDeleteProjectSb(id){
  if(!window.sbUser||!_sb) return;
  _sb.from('todo_projects').delete().eq('id',id).eq('user_id',sbUser.id);
}
function tdToday(){ return new Date().toISOString().slice(0,10); }
function tdUid(){ return Date.now().toString(36)+Math.random().toString(36).slice(2,6); }

function tdCheckMode(){
  var k=document.getElementById('td-kids-wrap');
  var a=document.getElementById('td-adult-wrap');
  if(!k||!a){ setTimeout(tdCheckMode,150); return; }
  var isAdult=window.rzMode==='forme';
  k.style.display=isAdult?'none':'block';
  a.style.display=isAdult?'block':'none';
  if(isAdult){ _tdCache=null; tdLoadFromSb().then(function(){ tdRender(); }); }
}

function tdRender(){
  tdUpdateHero();
  tdRenderProjectChips();
  tdRenderCurrentView();
  tdRenderProjects();
  tdRenderHeatmap();
  tdRenderIslamicBlocks();
  tdPopulateProjectSelect();
}

function tdUpdateHero(){
  var d=tdGetData();
  var today=tdToday();
  var tasks=d.tasks||[];
  var todayTasks=tasks.filter(function(t){ return t.due===today||(!t.due&&t.status!=='done'); });
  var doneTasks=tasks.filter(function(t){ return t.status==='done'; });
  var overdueTasks=tasks.filter(function(t){ return t.due&&t.due<today&&t.status!=='done'; });
  var urgentTasks=tasks.filter(function(t){ return t.priority==='urgent'&&t.status!=='done'; });
  var totalToday=todayTasks.length;
  var doneToday=todayTasks.filter(function(t){ return t.status==='done'; }).length;
  var pct=totalToday>0?Math.round(doneToday/totalToday*100):0;
  // Ring
  var ring=document.getElementById('td-hero-ring');
  if(ring){ ring.style.strokeDashoffset=238.8-(238.8*pct/100); }
  var pctEl=document.getElementById('td-hero-pct');
  if(pctEl) pctEl.textContent=pct+'%';
  // Stats
  var se=document.getElementById('td-stat-today'); if(se) se.textContent=totalToday;
  var sd=document.getElementById('td-stat-done'); if(sd) sd.textContent=doneTasks.length;
  var so=document.getElementById('td-stat-overdue'); if(so) so.textContent=overdueTasks.length;
  var su=document.getElementById('td-ct-urgent'); if(su) su.textContent=urgentTasks.length;
  var st=document.getElementById('td-ct-total'); if(st) st.textContent=doneTasks.length;
  // Streak
  var streak=tdCalcStreak(tasks);
  var ss=document.getElementById('td-ct-streak'); if(ss) ss.textContent=streak+' দিন';
  var ssb=document.getElementById('td-sb-streak'); if(ssb) ssb.textContent=streak+' দিন';
  // Hero focus — top priority incomplete task
  var pending=tasks.filter(function(t){ return t.status!=='done'; }).sort(function(a,b){
    var pa=TD_PRIORITY_MAP[a.priority]||{score:0};
    var pb=TD_PRIORITY_MAP[b.priority]||{score:0};
    if(pb.score!==pa.score) return pb.score-pa.score;
    if(a.due&&b.due) return a.due<b.due?-1:1;
    if(a.due) return -1; if(b.due) return 1;
    return 0;
  });
  var focus=pending[0];
  var hf=document.getElementById('td-hero-focus');
  var hd=document.getElementById('td-hero-deadline');
  if(hf) hf.textContent=focus?focus.title:'সব কাজ সম্পন্ন! 🎉';
  if(hd&&focus){
    var info=(TD_PRIORITY_MAP[focus.priority]||{label:''}).label;
    if(focus.due){ var diff=Math.ceil((new Date(focus.due)-new Date(today))/86400000); info+=' • '+(diff===0?'আজই শেষ':diff<0?Math.abs(diff)+' দিন পার!':diff+' দিন বাকি'); }
    hd.textContent=info;
    hd.style.color=diff<0?'#EF4444':diff===0?'#F59E0B':'rgba(255,255,255,.5)';
  } else if(hd) hd.textContent='';
  // Sidebar
  var sp=document.getElementById('td-sb-pct'); if(sp) sp.textContent=pct+'%';
  var sb=document.getElementById('td-sb-bar'); if(sb) sb.style.width=pct+'%';
  var sf=document.getElementById('td-sb-focus'); if(sf) sf.textContent=_tdPomoFocusTotal+' মিনিট';
}

function tdCalcStreak(tasks){
  var streak=0;
  var today=tdToday();
  for(var i=0;i<30;i++){
    var dt=new Date(); dt.setDate(dt.getDate()-i);
    var ds=dt.toISOString().slice(0,10);
    var hadDone=tasks.some(function(t){ return t.completedDate===ds; });
    if(hadDone) streak++; else if(i>0) break;
  }
  return streak;
}

function tdGetFilteredTasks(){
  var d=tdGetData(); var tasks=d.tasks||[];
  var today=tdToday();
  if(_tdFilter==='today') tasks=tasks.filter(function(t){ return t.due===today; });
  else if(_tdFilter==='overdue') tasks=tasks.filter(function(t){ return t.due&&t.due<today&&t.status!=='done'; });
  else if(_tdFilter==='done') tasks=tasks.filter(function(t){ return t.status==='done'; });
  if(_tdProjectFilter) tasks=tasks.filter(function(t){ return t.project===_tdProjectFilter; });
  return tasks;
}

function tdRenderCurrentView(){
  if(_tdView==='list') tdRenderList();
  else if(_tdView==='kanban') tdRenderKanban();
  else if(_tdView==='matrix') tdRenderMatrix();
  else if(_tdView==='timeline') tdRenderTimeline();
}

function tdMakeTaskCard(task, mini){
  var pr=TD_PRIORITY_MAP[task.priority]||{color:'#94A3B8',label:''};
  var d=tdGetData(); var projects=d.projects||[];
  var proj=projects.find(function(p){ return p.id===task.project; });
  var today=tdToday();
  var isOverdue=task.due&&task.due<today&&task.status!=='done';
  var isDone=task.status==='done';
  var subtasksDone=(task.subtasks||[]).filter(function(s){ return s.done; }).length;
  var subtasksTotal=(task.subtasks||[]).length;
  var energyMap={high:'⚡',medium:'🔋',low:'😴'};
  var islamicEl=task.islamic?(' <span style="font-size:9px;background:rgba(99,102,241,.08);color:#6366F1;padding:2px 6px;border-radius:6px;font-weight:700">'+(TD_ISLAMIC[task.islamic]||{label:''}).label+'</span>'):'';
  var tagsHtml=(task.tags||[]).slice(0,2).map(function(t){ return '<span style="font-size:9px;background:var(--bg2,#f3f4f6);color:var(--text2,#888);padding:2px 6px;border-radius:6px;font-weight:600">'+t+'</span>'; }).join('');
  var pomoHtml=task.pomos>1?('<span style="font-size:9px;color:var(--text2,#888)">🍅×'+task.pomos+'</span>'):'';
  var subtaskHtml=subtasksTotal>0?('<span style="font-size:9px;color:var(--text2,#888)">✅ '+subtasksDone+'/'+subtasksTotal+'</span>'):'';
  var dueHtml='';
  if(task.due){
    var diff=Math.ceil((new Date(task.due)-new Date(today))/86400000);
    var dueColor=isOverdue?'#EF4444':diff===0?'#F59E0B':'var(--text2,#888)';
    dueHtml='<span style="font-size:9px;color:'+dueColor+';font-weight:700">'+(isOverdue?'⚠️ '+Math.abs(diff)+'দ পার':diff===0?'⏰ আজ':'📅 '+task.due.slice(5))+'</span>';
  }
  if(mini){
    return '<div style="background:var(--bg,#fff);border:1px solid '+(isOverdue?'rgba(239,68,68,.3)':isDone?'rgba(16,185,129,.2)':'var(--border,#e5e7eb)')+';border-left:3px solid '+(isDone?'#10B981':pr.color)+';border-radius:10px;padding:8px 10px;cursor:pointer;opacity:'+(isDone?.6:1)+'" onclick="tdOpenModal(\''+task.id+'\')">'
      +'<div style="font-size:11px;font-weight:700;color:var(--text,#1a1a2e);'+(isDone?'text-decoration:line-through;':'')+'margin-bottom:3px">'+task.title+'</div>'
      +'<div style="display:flex;gap:4px;flex-wrap:wrap;align-items:center">'+(dueHtml||'')+(subtaskHtml)+'</div>'
      +'</div>';
  }
  return '<div id="tdcard-'+task.id+'" style="background:var(--bg,#fff);border:1.5px solid '+(isOverdue?'rgba(239,68,68,.25)':isDone?'rgba(16,185,129,.15)':'var(--border,#e5e7eb)')+';border-radius:14px;padding:14px 16px;margin-bottom:8px;transition:.2s;position:relative;opacity:'+(isDone?.65:1)+'">'
    +'<div style="display:flex;align-items:flex-start;gap:10px">'
    +'<div onclick="tdToggleDone(\''+task.id+'\')" style="width:20px;height:20px;border-radius:6px;border:2px solid '+(isDone?'#10B981':pr.color)+';background:'+(isDone?'#10B981':'transparent')+';flex-shrink:0;cursor:pointer;display:flex;align-items:center;justify-content:center;margin-top:1px;transition:.2s">'+(isDone?'<svg width="10" height="8" viewBox="0 0 10 8"><polyline points="1,4 4,7 9,1" fill="none" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/></svg>':'')+'</div>'
    +'<div style="flex:1;min-width:0">'
    +'<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:4px">'
    +'<span style="font-size:13px;font-weight:800;color:var(--text,#1a1a2e);'+(isDone?'text-decoration:line-through;opacity:.6':'')+'">'+task.title+'</span>'
    +(proj?'<span style="width:6px;height:6px;border-radius:50%;background:'+proj.color+';display:inline-block"></span>':'')
    +'</div>'
    +(task.desc?'<div style="font-size:11px;color:var(--text2,#888);margin-bottom:6px">'+task.desc+'</div>':'')
    +'<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center">'
    +'<span style="font-size:10px;background:'+pr.color+'18;color:'+pr.color+';padding:2px 8px;border-radius:6px;font-weight:700">'+pr.label+'</span>'
    +(energyMap[task.energy]?'<span style="font-size:11px">'+energyMap[task.energy]+'</span>':'')
    +islamicEl+tagsHtml+pomoHtml+subtaskHtml+dueHtml
    +(task.recur?'<span style="font-size:9px;color:#6366F1;font-weight:700">🔄 '+task.recur+'</span>':'')
    +'</div>'
    +(subtasksTotal>0?tdRenderSubtasksInline(task):'')
    +'</div>'
    +'<div style="display:flex;flex-direction:column;gap:6px;flex-shrink:0">'
    +'<button onclick="tdStartPomo(\''+task.id+'\')" style="background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.2);border-radius:8px;padding:5px 8px;cursor:pointer;font-size:12px" title="Pomodoro শুরু করুন">🍅</button>'
    +'<button onclick="tdOpenModal(\''+task.id+'\')" style="background:var(--bg2,#f3f4f6);border:1px solid var(--border,#e5e7eb);border-radius:8px;padding:5px 8px;cursor:pointer;font-size:11px">✏️</button>'
    +'<button onclick="tdDeleteTask(\''+task.id+'\')" style="background:rgba(239,68,68,.06);border:1px solid rgba(239,68,68,.15);border-radius:8px;padding:5px 8px;cursor:pointer;font-size:11px">🗑️</button>'
    +'</div>'
    +'</div>'
    +'</div>';
}

function tdRenderSubtasksInline(task){
  if(!task.subtasks||!task.subtasks.length) return '';
  return '<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border,#e5e7eb);display:flex;flex-direction:column;gap:4px">'
    +task.subtasks.map(function(s,i){
      return '<div style="display:flex;align-items:center;gap:6px">'
        +'<div onclick="tdToggleSubtask(\''+task.id+'\','+i+')" style="width:14px;height:14px;border-radius:4px;border:1.5px solid '+(s.done?'#10B981':'var(--border,#e5e7eb)')+';background:'+(s.done?'#10B981':'transparent')+';cursor:pointer;flex-shrink:0;display:flex;align-items:center;justify-content:center">'+(s.done?'<svg width="8" height="6" viewBox="0 0 8 6"><polyline points="1,3 3,5 7,1" fill="none" stroke="#fff" stroke-width="1.5" stroke-linecap="round"/></svg>':'')+'</div>'
        +'<span style="font-size:11px;color:var(--text,#1a1a2e);'+(s.done?'text-decoration:line-through;opacity:.5':'')+'">'+s.text+'</span>'
        +'</div>';
    }).join('')
    +'</div>';
}

function tdRenderList(){
  var el=document.getElementById('td-task-list'); if(!el) return;
  var tasks=tdGetFilteredTasks();
  if(!tasks.length){
    el.innerHTML='<div style="text-align:center;padding:40px 20px"><div style="font-size:36px;margin-bottom:12px">✨</div><div style="font-size:14px;font-weight:700;color:var(--text,#1a1a2e);margin-bottom:6px">কোনো কাজ নেই!</div><div style="font-size:12px;color:var(--text2,#888)">নতুন কাজ যোগ করুন বা ফিল্টার পরিবর্তন করুন।</div></div>';
    return;
  }
  // Group: overdue, today, upcoming, no-date, done
  var today=tdToday();
  var overdue=tasks.filter(function(t){ return t.due&&t.due<today&&t.status!=='done'; });
  var todayT=tasks.filter(function(t){ return t.due===today&&t.status!=='done'; });
  var upcoming=tasks.filter(function(t){ return t.due&&t.due>today&&t.status!=='done'; });
  var noDate=tasks.filter(function(t){ return !t.due&&t.status!=='done'; });
  var done=tasks.filter(function(t){ return t.status==='done'; });
  var html='';
  function group(title, color, arr){
    if(!arr.length) return '';
    return '<div style="font-size:10px;font-weight:800;color:'+color+';letter-spacing:1px;margin:14px 0 8px;display:flex;align-items:center;gap:6px">'+title+' <span style="background:'+color+'20;color:'+color+';border-radius:8px;padding:1px 7px;font-size:10px">'+arr.length+'</span></div>'
      +arr.map(function(t){ return tdMakeTaskCard(t,false); }).join('');
  }
  html+=group('⚠️ মেয়াদ শেষ','#EF4444',overdue);
  html+=group('📅 আজ','#F59E0B',todayT);
  html+=group('📆 আসছে','#6366F1',upcoming);
  html+=group('📝 তারিখ নেই','var(--text2,#888)',noDate);
  html+=group('✅ সম্পন্ন','#10B981',done);
  el.innerHTML=html;
}

function tdRenderKanban(){
  var tasks=tdGetFilteredTasks();
  var cols={backlog:[],inprogress:[],review:[],done:[]};
  tasks.forEach(function(t){ if(cols[t.status||'backlog']) cols[t.status||'backlog'].push(t); });
  Object.keys(cols).forEach(function(col){
    var el=document.getElementById('kboard-'+col); if(!el) return;
    var cnt=document.getElementById('kc-'+col);
    if(cnt) cnt.textContent=cols[col].length;
    el.innerHTML=cols[col].length?cols[col].map(function(t){ return tdMakeTaskCard(t,true); }).join('')
      :'<div style="border:1.5px dashed var(--border,#e5e7eb);border-radius:10px;padding:16px;text-align:center;font-size:11px;color:var(--text2,#888)">কোনো কাজ নেই</div>';
  });
}

function tdRenderMatrix(){
  var tasks=tdGetFilteredTasks().filter(function(t){ return t.status!=='done'; });
  function getQuadrant(t){
    var isUrgent=t.priority==='urgent'||(t.due&&t.due<=tdToday());
    var isImportant=t.priority==='urgent'||t.priority==='high';
    if(isUrgent&&isImportant) return 'q1';
    if(!isUrgent&&isImportant) return 'q2';
    if(isUrgent&&!isImportant) return 'q3';
    return 'q4';
  }
  var qs={q1:[],q2:[],q3:[],q4:[]};
  tasks.forEach(function(t){ qs[getQuadrant(t)].push(t); });
  ['q1','q2','q3','q4'].forEach(function(q){
    var el=document.getElementById('mq-'+q); if(!el) return;
    el.innerHTML=qs[q].length?qs[q].map(function(t){ return tdMakeTaskCard(t,true); }).join('')
      :'<div style="font-size:11px;color:var(--text2,#888);text-align:center;padding:8px">কোনো কাজ নেই</div>';
  });
}

function tdRenderTimeline(){
  var el=document.getElementById('td-timeline-grid'); if(!el) return;
  var tasks=tdGetData().tasks||[];
  var days=['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
  var html='';
  for(var i=0;i<7;i++){
    var dt=new Date(); dt.setDate(dt.getDate()+i-1);
    var ds=dt.toISOString().slice(0,10);
    var dayTasks=tasks.filter(function(t){ return t.due===ds; });
    var isToday=ds===tdToday();
    html+='<div style="margin-bottom:12px">'
      +'<div style="font-size:11px;font-weight:800;color:'+(isToday?'#6366F1':'var(--text2,#888)')+';margin-bottom:6px;display:flex;align-items:center;gap:8px">'
      +'<span>'+(i===0?'গতকাল ':'')+days[dt.getDay()]+' '+dt.getDate()+'</span>'
      +(isToday?'<span style="font-size:9px;background:#6366F1;color:#fff;border-radius:6px;padding:1px 6px">আজ</span>':'')
      +'<span style="margin-left:auto;font-size:10px;color:var(--text2,#888)">'+dayTasks.length+' টি কাজ</span>'
      +'</div>'
      +(dayTasks.length?dayTasks.map(function(t){ return tdMakeTaskCard(t,true); }).join('')
        :'<div style="font-size:11px;color:var(--text2,#888);padding:8px 12px;background:var(--bg2,#f3f4f6);border-radius:8px">কোনো কাজ নির্ধারিত নেই</div>')
      +'</div>';
  }
  el.innerHTML=html;
}

function tdRenderProjects(){
  var d=tdGetData(); var projects=d.projects||[]; var tasks=d.tasks||[];
  var el=document.getElementById('td-projects-list'); if(!el) return;
  if(!projects.length){
    el.innerHTML='<div style="font-size:12px;color:var(--text2,#888);text-align:center;padding:12px">কোনো প্রজেক্ট নেই। নতুন প্রজেক্ট যোগ করুন।</div>';
    return;
  }
  el.innerHTML=projects.map(function(p){
    var ptasks=tasks.filter(function(t){ return t.project===p.id; });
    var done=ptasks.filter(function(t){ return t.status==='done'; }).length;
    var pct=ptasks.length?Math.round(done/ptasks.length*100):0;
    return '<div style="display:flex;align-items:center;gap:10px;cursor:pointer" onclick="tdFilterProject(\''+p.id+'\')">'
      +'<div style="width:10px;height:10px;border-radius:50%;background:'+p.color+';flex-shrink:0"></div>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="display:flex;justify-content:space-between;margin-bottom:4px"><span style="font-size:12px;font-weight:700;color:var(--text,#1a1a2e)">'+p.name+'</span><span style="font-size:11px;color:var(--text2,#888)">'+done+'/'+ptasks.length+'</span></div>'
      +'<div style="background:var(--border,#e5e7eb);height:4px;border-radius:4px"><div style="width:'+pct+'%;height:4px;background:'+p.color+';border-radius:4px;transition:.5s"></div></div>'
      +'</div>'
      +'<button onclick="event.stopPropagation();tdDeleteProject(\''+p.id+'\')" style="background:transparent;border:none;cursor:pointer;font-size:12px;color:var(--text2,#888)">×</button>'
      +'</div>';
  }).join('');
}

function tdRenderProjectChips(){
  var d=tdGetData(); var projects=d.projects||[];
  var el=document.getElementById('td-project-chips'); if(!el) return;
  if(!projects.length){ el.innerHTML=''; return; }
  el.innerHTML='<button onclick="tdFilterProject(\'\')" style="padding:4px 12px;border-radius:20px;border:1.5px solid '+(_tdProjectFilter?'var(--border,#e5e7eb)':'#6366F1')+';background:'+(_tdProjectFilter?'transparent':'#6366F1')+';color:'+(_tdProjectFilter?'var(--text2,#888)':'#fff')+';font-size:11px;font-weight:700;cursor:pointer">সব</button>'
    +projects.map(function(p){
      var active=_tdProjectFilter===p.id;
      return '<button onclick="tdFilterProject(\''+p.id+'\')" style="padding:4px 12px;border-radius:20px;border:1.5px solid '+(active?p.color:'var(--border,#e5e7eb)')+';background:'+(active?p.color+'20':'transparent')+';color:'+(active?p.color:'var(--text2,#888)')+';font-size:11px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px"><span style="width:7px;height:7px;border-radius:50%;background:'+p.color+';display:inline-block"></span>'+p.name+'</button>';
    }).join('');
}

function tdRenderHeatmap(){
  var el=document.getElementById('td-heatmap'); if(!el) return;
  var d=tdGetData(); var tasks=d.tasks||[];
  var completedByDate={};
  tasks.forEach(function(t){ if(t.completedDate) completedByDate[t.completedDate]=(completedByDate[t.completedDate]||0)+1; });
  var html='';
  var days=['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
  for(var i=48;i>=0;i--){
    var dt=new Date(); dt.setDate(dt.getDate()-i);
    var ds=dt.toISOString().slice(0,10);
    var cnt=completedByDate[ds]||0;
    var opacity=cnt===0?0:cnt===1?.3:cnt<=3?.6:1;
    var isToday=ds===tdToday();
    html+='<div title="'+ds+': '+cnt+'টি সম্পন্ন" style="width:11px;height:11px;border-radius:2px;background:'+(cnt>0?'rgba(99,102,241,'+opacity+')':'var(--border,#e5e7eb)')+';'+(isToday?'outline:2px solid #6366F1;outline-offset:1px':'')+'"></div>';
  }
  el.innerHTML=html;
}

function tdRenderIslamicBlocks(){
  var el=document.getElementById('td-islamic-blocks'); if(!el) return;
  var d=tdGetData(); var tasks=d.tasks||[];
  el.innerHTML=Object.keys(TD_ISLAMIC).map(function(key){
    var info=TD_ISLAMIC[key];
    var blockTasks=tasks.filter(function(t){ return t.islamic===key&&t.status!=='done'; });
    return '<div style="background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);border-radius:10px;padding:10px">'
      +'<div style="font-size:11px;font-weight:800;color:#fff;margin-bottom:2px">'+info.label+'</div>'
      +'<div style="font-size:9px;color:rgba(255,255,255,.4);margin-bottom:6px">'+info.time+'</div>'
      +(blockTasks.length?blockTasks.slice(0,2).map(function(t){ return '<div style="font-size:10px;color:rgba(255,255,255,.7);background:rgba(255,255,255,.04);border-radius:5px;padding:3px 6px;margin-bottom:3px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis">'+t.title+'</div>'; }).join('')
        :'<div style="font-size:10px;color:rgba(255,255,255,.25)">কোনো কাজ নেই</div>')
      +'</div>';
  }).join('');
}

function tdPopulateProjectSelect(){
  var d=tdGetData(); var projects=d.projects||[];
  var sel=document.getElementById('td-m-project'); if(!sel) return;
  sel.innerHTML='<option value="">কোনো প্রজেক্ট নেই</option>'
    +projects.map(function(p){ return '<option value="'+p.id+'">'+p.name+'</option>'; }).join('');
}

function tdSetView(view){
  _tdView=view;
  ['list','kanban','matrix','timeline'].forEach(function(v){
    var btn=document.getElementById('tdv-'+v);
    var panel=document.getElementById('td-view-'+v);
    if(btn){ btn.style.background=v===view?'#6366F1':'transparent'; btn.style.color=v===view?'#fff':'var(--text2,#888)'; }
    if(panel) panel.style.display=v===view?'block':'none';
  });
  tdRenderCurrentView();
}

function tdSetFilter(f){
  _tdFilter=f;
  ['all','today','overdue','done'].forEach(function(x){
    var btn=document.getElementById('tdf-'+x);
    if(!btn) return;
    if(x===f){ btn.style.background='#6366F1'; btn.style.color='#fff'; btn.style.borderColor='#6366F1'; }
    else { btn.style.background='transparent'; btn.style.color='var(--text2,#888)'; btn.style.borderColor='var(--border,#e5e7eb)'; }
  });
  tdRenderList();
}

function tdFilterProject(id){
  _tdProjectFilter=id;
  tdRenderProjectChips();
  tdRenderCurrentView();
}

function tdToggleDone(id){
  var d=tdGetData(); var tasks=d.tasks||[];
  var t=tasks.find(function(x){ return x.id===id; }); if(!t) return;
  if(t.status==='done'){ t.status='backlog'; delete t.completedDate; }
  else { t.status='done'; t.completedDate=tdToday(); }
  tdSaveData(d); tdUpsertTaskSb(t);
  tdUpdateHero();
  tdRenderCurrentView();
  tdRenderHeatmap();
  tdRenderProjects();
}

function tdToggleSubtask(taskId, idx){
  var d=tdGetData(); var tasks=d.tasks||[];
  var t=tasks.find(function(x){ return x.id===taskId; }); if(!t||!t.subtasks) return;
  t.subtasks[idx].done=!t.subtasks[idx].done;
  tdSaveData(d); tdUpsertTaskSb(t);
  tdRenderCurrentView();
  tdUpdateHero();
}

function tdDeleteTask(id){
  if(!confirm('এই কাজটি মুছে ফেলবেন?')) return;
  var d=tdGetData(); d.tasks=(d.tasks||[]).filter(function(t){ return t.id!==id; });
  tdSaveData(d); tdDeleteTaskSb(id); tdRender();
}

function tdQuickAdd(){
  var inp=document.getElementById('td-quick-input');
  var pri=document.getElementById('td-quick-priority');
  var title=inp?inp.value.trim():'';
  if(!title) return;
  var d=tdGetData();
  d.tasks=d.tasks||[];
  var _qt={id:tdUid(),title:title,priority:pri?pri.value:'normal',status:'backlog',energy:'medium',tags:[],subtasks:[],pomos:1,createdAt:tdToday()};
  d.tasks.unshift(_qt);
  tdSaveData(d); tdUpsertTaskSb(_qt);
  inp.value='';
  tdRender();
}

function tdOpenModal(id){
  _tdSubtasks=[];
  _tdSelectedTags=[];
  _tdSelectedPomo=1;
  var modal=document.getElementById('td-task-modal'); if(!modal) return;
  tdPopulateProjectSelect();
  // Reset fields
  ['td-m-title','td-m-desc'].forEach(function(i){ var el=document.getElementById(i); if(el) el.value=''; });
  ['td-m-priority','td-m-energy','td-m-islamic','td-m-project','td-m-status','td-m-recur'].forEach(function(i){ var el=document.getElementById(i); if(el) el.selectedIndex=el.id==='td-m-priority'?2:el.id==='td-m-energy'?1:0; });
  var dueEl=document.getElementById('td-m-due'); if(dueEl) dueEl.value='';
  document.getElementById('td-modal-id').value='';
  document.getElementById('td-modal-title').textContent='✏️ নতুন কাজ';
  document.getElementById('td-m-tags').value='[]';
  document.getElementById('td-m-pomos').value='1';
  document.getElementById('td-subtasks-list').innerHTML='';
  // Reset pomo buttons
  for(var i=1;i<=5;i++){ var pb=document.getElementById('tdp-'+i); if(pb){ pb.style.background='transparent'; pb.style.borderColor='var(--border,#e5e7eb)'; pb.style.color='var(--text,#1a1a2e)'; } }
  var pb1=document.getElementById('tdp-1'); if(pb1){ pb1.style.background='#6366F1'; pb1.style.color='#fff'; }
  // Reset tag buttons
  document.querySelectorAll('.td-tag-btn').forEach(function(b){ b.style.background='transparent'; b.style.borderColor='var(--border,#e5e7eb)'; b.style.color='var(--text2,#888)'; });
  if(id){
    var d=tdGetData(); var t=d.tasks.find(function(x){ return x.id===id; });
    if(t){
      document.getElementById('td-modal-id').value=id;
      document.getElementById('td-modal-title').textContent='✏️ কাজ সম্পাদনা';
      var ti=document.getElementById('td-m-title'); if(ti) ti.value=t.title;
      var de=document.getElementById('td-m-desc'); if(de) de.value=t.desc||'';
      var pr=document.getElementById('td-m-priority'); if(pr) pr.value=t.priority||'normal';
      var en=document.getElementById('td-m-energy'); if(en) en.value=t.energy||'medium';
      var du=document.getElementById('td-m-due'); if(du) du.value=t.due||'';
      var il=document.getElementById('td-m-islamic'); if(il) il.value=t.islamic||'';
      var pj=document.getElementById('td-m-project'); if(pj) pj.value=t.project||'';
      var st=document.getElementById('td-m-status'); if(st) st.value=t.status||'backlog';
      var rc=document.getElementById('td-m-recur'); if(rc) rc.value=t.recur||'';
      _tdSubtasks=(t.subtasks||[]).map(function(s){ return {text:s.text,done:s.done}; });
      tdRenderSubtasksList();
      _tdSelectedTags=t.tags||[];
      document.getElementById('td-m-tags').value=JSON.stringify(_tdSelectedTags);
      _tdSelectedTags.forEach(function(tag){
        var btn=document.querySelector('.td-tag-btn[data-tag="'+tag+'"]');
        if(btn){ btn.style.background='#6366F1'; btn.style.borderColor='#6366F1'; btn.style.color='#fff'; }
      });
      _tdSelectedPomo=t.pomos||1;
      document.getElementById('td-m-pomos').value=_tdSelectedPomo;
      tdSetPomo(_tdSelectedPomo);
    }
  }
  modal.style.display='flex';
}

function tdCloseModal(){
  var m=document.getElementById('td-task-modal'); if(m) m.style.display='none';
}

function tdSaveTask(){
  var title=document.getElementById('td-m-title');
  if(!title||!title.value.trim()){ alert('কাজের শিরোনাম দিন।'); return; }
  var d=tdGetData(); d.tasks=d.tasks||[];
  var id=document.getElementById('td-modal-id').value;
  var getValue=function(elId){ var el=document.getElementById(elId); return el?el.value:''; };
  var task={
    id:id||tdUid(), title:title.value.trim(), desc:getValue('td-m-desc'),
    priority:getValue('td-m-priority')||'normal', energy:getValue('td-m-energy')||'medium',
    due:getValue('td-m-due'), islamic:getValue('td-m-islamic'),
    project:getValue('td-m-project'), status:getValue('td-m-status')||'backlog',
    recur:getValue('td-m-recur'), pomos:_tdSelectedPomo,
    tags:_tdSelectedTags.slice(), subtasks:_tdSubtasks.slice(),
    createdAt:tdToday()
  };
  if(id){ var idx=d.tasks.findIndex(function(t){ return t.id===id; }); if(idx>-1){ task.completedDate=d.tasks[idx].completedDate; d.tasks[idx]=task; } else d.tasks.unshift(task); }
  else d.tasks.unshift(task);
  tdSaveData(d); tdUpsertTaskSb(task);
  tdCloseModal();
  tdRender();
}

function tdAddSubtask(){
  var inp=document.getElementById('td-subtask-inp'); if(!inp) return;
  var text=inp.value.trim(); if(!text) return;
  _tdSubtasks.push({text:text,done:false});
  inp.value='';
  tdRenderSubtasksList();
}

function tdRenderSubtasksList(){
  var el=document.getElementById('td-subtasks-list'); if(!el) return;
  el.innerHTML=_tdSubtasks.map(function(s,i){
    return '<div style="display:flex;align-items:center;gap:6px;padding:5px 8px;background:var(--bg2,#f3f4f6);border-radius:7px">'
      +'<div onclick="(function(){window._tdSubtasks['+i+'].done=!window._tdSubtasks['+i+'].done;tdRenderSubtasksList();})()" style="width:14px;height:14px;border-radius:4px;border:1.5px solid '+(s.done?'#10B981':'var(--border,#e5e7eb)')+';background:'+(s.done?'#10B981':'transparent')+';cursor:pointer;flex-shrink:0"></div>'
      +'<span style="flex:1;font-size:11px;color:var(--text,#1a1a2e);'+(s.done?'text-decoration:line-through;opacity:.5':'')+'">'+s.text+'</span>'
      +'<button onclick="_tdSubtasks.splice('+i+',1);tdRenderSubtasksList()" style="background:transparent;border:none;cursor:pointer;color:var(--text2,#888);font-size:13px;padding:0">×</button>'
      +'</div>';
  }).join('');
}

function tdToggleTag(tag){
  var idx=_tdSelectedTags.indexOf(tag);
  if(idx>-1) _tdSelectedTags.splice(idx,1); else _tdSelectedTags.push(tag);
  document.getElementById('td-m-tags').value=JSON.stringify(_tdSelectedTags);
  var btn=document.querySelector('.td-tag-btn[data-tag="'+tag+'"]');
  if(btn){
    var active=_tdSelectedTags.indexOf(tag)>-1;
    btn.style.background=active?'#6366F1':'transparent';
    btn.style.borderColor=active?'#6366F1':'var(--border,#e5e7eb)';
    btn.style.color=active?'#fff':'var(--text2,#888)';
  }
}

function tdSetPomo(n){
  _tdSelectedPomo=n;
  document.getElementById('td-m-pomos').value=n;
  for(var i=1;i<=5;i++){
    var btn=document.getElementById('tdp-'+i);
    if(!btn) continue;
    if(i===n){ btn.style.background='#EF4444'; btn.style.borderColor='#EF4444'; btn.style.color='#fff'; }
    else { btn.style.background='transparent'; btn.style.borderColor='var(--border,#e5e7eb)'; btn.style.color='var(--text,#1a1a2e)'; }
  }
}

function tdAddProject(){
  var m=document.getElementById('td-project-modal'); if(m) m.style.display='flex';
  var inp=document.getElementById('td-proj-name'); if(inp) inp.value='';
  document.getElementById('td-proj-color').value='#6366F1';
}

function tdSelProjColor(color, el){
  document.getElementById('td-proj-color').value=color;
  var parent=el.parentElement;
  parent.querySelectorAll('div').forEach(function(d){ d.style.borderColor='transparent'; });
  el.style.borderColor=color;
}

function tdSaveProject(){
  var name=document.getElementById('td-proj-name'); var color=document.getElementById('td-proj-color');
  if(!name||!name.value.trim()) return;
  var d=tdGetData(); d.projects=d.projects||[];
  var _np={id:tdUid(),name:name.value.trim(),color:color?color.value:'#6366F1'};
  d.projects.push(_np);
  tdSaveData(d); tdUpsertProjectSb(_np);
  document.getElementById('td-project-modal').style.display='none';
  tdRenderProjects(); tdRenderProjectChips(); tdPopulateProjectSelect();
}

function tdDeleteProject(id){
  if(!confirm('প্রজেক্ট মুছে ফেলবেন? (কাজগুলো থাকবে)')) return;
  var d=tdGetData();
  d.projects=(d.projects||[]).filter(function(p){ return p.id!==id; });
  d.tasks=(d.tasks||[]).map(function(t){ if(t.project===id) t.project=''; return t; });
  tdSaveData(d); tdDeleteProjectSb(id); tdRender();
}

// POMODORO
function tdStartPomo(taskId){
  var d=tdGetData(); var t=(d.tasks||[]).find(function(x){ return x.id===taskId; });
  _tdPomoTask=t?t.title:'কাজ';
  _tdPomoSecs=25*60;
  _tdPomoRunning=false;
  var bar=document.getElementById('td-pomo-bar'); if(bar) bar.style.display='flex';
  var tlbl=document.getElementById('td-pomo-task'); if(tlbl) tlbl.textContent=_tdPomoTask;
  var ttm=document.getElementById('td-pomo-time'); if(ttm) ttm.textContent='25:00';
  var tbtn=document.getElementById('td-pomo-toggle'); if(tbtn) tbtn.textContent='▶ শুরু';
}

function tdPomoToggle(){
  if(_tdPomoRunning){
    clearInterval(_tdPomoInterval); _tdPomoRunning=false;
    var btn=document.getElementById('td-pomo-toggle'); if(btn) btn.textContent='▶ শুরু';
  } else {
    _tdPomoRunning=true;
    var btn=document.getElementById('td-pomo-toggle'); if(btn) btn.textContent='⏸ বিরতি';
    _tdPomoInterval=setInterval(function(){
      _tdPomoSecs--;
      if(_tdPomoSecs<=0){
        clearInterval(_tdPomoInterval); _tdPomoRunning=false;
        _tdPomoSessions++;
        _tdPomoFocusTotal+=25;
        var cnt=document.getElementById('td-pomo-count'); if(cnt) cnt.textContent='🍅 '+_tdPomoSessions+' সেশন';
        var sf=document.getElementById('td-sb-focus'); if(sf) sf.textContent=_tdPomoFocusTotal+' মিনিট';
        var btn=document.getElementById('td-pomo-toggle'); if(btn) btn.textContent='▶ শুরু';
        _tdPomoSecs=5*60;
        var ttm=document.getElementById('td-pomo-time'); if(ttm) ttm.textContent='✓ বিশ্রাম নিন!';
        return;
      }
      var m=Math.floor(_tdPomoSecs/60); var s=_tdPomoSecs%60;
      var ttm=document.getElementById('td-pomo-time');
      if(ttm) ttm.textContent=(m<10?'0':'')+m+':'+(s<10?'0':'')+s;
    },1000);
  }
}

function tdPomoStop(){
  clearInterval(_tdPomoInterval); _tdPomoRunning=false; _tdPomoSecs=25*60;
  var bar=document.getElementById('td-pomo-bar'); if(bar) bar.style.display='none';
}

