// Journal data cache
var _jnCache=null;

async function jnGetData(){
  if(_jnCache) return _jnCache;
  if(!window.sbUser||!_sb){ try{return JSON.parse(localStorage.getItem('rz_jn_data')||'{"entries":[]}');}catch(e){return {entries:[]};} }
  try{
    var res=await _sb.from('journal_entries').select('*').eq('user_id',sbUser.id).order('created_at',{ascending:false});
    var entries=(res.data||[]).map(function(r){return{id:r.id,date:r.date,title:r.title||'',body:r.body||'',mood:r.mood||'',tags:r.tags||[],starred:r.starred||false,wordCount:r.word_count||0,createdAt:r.created_at};});
    _jnCache={entries:entries};
    return _jnCache;
  }catch(e){try{return JSON.parse(localStorage.getItem('rz_jn_data')||'{"entries":[]}');}catch(e2){return {entries:[]};}}
}

async function jnSaveEntry_sb(entry){
  if(!window.sbUser||!_sb) return;
  _jnCache=null;
  await _sb.from('journal_entries').upsert({
    id:entry.id, user_id:sbUser.id, date:entry.date, title:entry.title||'',
    body:entry.body||'', mood:entry.mood||'', tags:entry.tags||[],
    starred:entry.starred||false, word_count:entry.wordCount||0
  },{onConflict:'id'});
}

async function jnDeleteEntry_sb(id){
  if(!window.sbUser||!_sb) return;
  _jnCache=null;
  await _sb.from('journal_entries').delete().eq('id',id).eq('user_id',sbUser.id);
}

function jnSaveData(d){ _jnCache=d; /* legacy localStorage fallback */ }
function jnToday(){ return new Date().toISOString().slice(0,10); }
function jnUid(){ return Date.now().toString(36)+Math.random().toString(36).slice(2,6); }
function jnWordCount(text){ return text.trim().split(/\s+/).filter(function(w){ return w.length>0; }).length; }
function jnReadTime(words){ return Math.max(1, Math.ceil(words/200)); }

function jnCheckMode(){
  var k=document.getElementById('jn-kids-wrap');
  var a=document.getElementById('jn-adult-wrap');
  if(!k||!a){ setTimeout(jnCheckMode,150); return; }
  var isAdult=window.rzMode==='forme';
  k.style.display=isAdult?'none':'block';
  a.style.display=isAdult?'block':'none';
  if(isAdult) jnRender();
}

async function jnRender(){
  jnUpdateHero();
  jnUpdatePrompt();
  jnRenderEntries();
  jnRenderHeatmap();
  jnRenderMoodChart();
  jnUpdateSidebar();
  // Force clear browser autofill on search box
  setTimeout(function(){
    var s=document.getElementById('jn-search');
    if(s&&s.value&&s.value.trim().length>5&&/^\d+$/.test(s.value.trim())){ s.value=''; _jnSearchQuery=''; }
  }, 100);
}

async function jnUpdateHero(){
  var d=await jnGetData(); var entries=d.entries||[];
  var today=jnToday();
  var thisMonth=today.slice(0,7);
  var totalWords=entries.reduce(function(s,e){ return s+jnWordCount(e.body||''); },0);
  var monthEntries=entries.filter(function(e){ return (e.date||'').slice(0,7)===thisMonth; });
  var starred=entries.filter(function(e){ return e.starred; });
  var streak=jnCalcStreak(entries);
  var avgWords=entries.length?Math.round(totalWords/entries.length):0;
  var setEl=function(id,v){ var el=document.getElementById(id); if(el) el.textContent=v; };
  setEl('jn-stat-streak',streak);
  setEl('jn-stat-entries',entries.length);
  setEl('jn-stat-words',totalWords>999?(Math.round(totalWords/100)/10)+'k':totalWords);
  setEl('jn-ct-starred',starred.length);
  setEl('jn-ct-month',monthEntries.length);
  setEl('jn-ct-avg',avgWords+' শব্দ');
}

function jnCalcStreak(entries){
  var dates={}; entries.forEach(function(e){ if(e.date) dates[e.date]=true; });
  var streak=0; var today=jnToday();
  for(var i=0;i<365;i++){
    var dt=new Date(); dt.setDate(dt.getDate()-i);
    var ds=dt.toISOString().slice(0,10);
    if(dates[ds]) streak++; else if(i>0) break;
  }
  return streak;
}

function jnUpdatePrompt(){
  var prompts=JN_PROMPTS;
  var idx=_jnPromptIdx % prompts.length;
  var el=document.getElementById('jn-prompt-text');
  if(el) el.textContent=prompts[idx];
}

function jnNextPrompt(){
  _jnPromptIdx=(_jnPromptIdx+1) % JN_PROMPTS.length;
  jnUpdatePrompt();
}

function jnUpdateWordCount(){
  var body=document.getElementById('jn-c-body');
  if(!body) return;
  var words=jnWordCount(body.value);
  var mins=jnReadTime(words);
  var el=document.getElementById('jn-word-count');
  if(el) el.textContent=words+' শব্দ · ~'+mins+' মিনিট পড়া';
}

function jnSetMood(mood, icon){
  _jnSelectedMood=mood;
  var inp=document.getElementById('jn-c-mood'); if(inp) inp.value=mood;
  // Reset all mood buttons
  Object.keys(JN_MOODS).forEach(function(m){
    var btn=document.getElementById('jnm-'+m);
    if(!btn) return;
    btn.style.background=m===mood?'rgba(255,255,255,.25)':'rgba(255,255,255,.1)';
    btn.style.borderColor=m===mood?'rgba(255,255,255,.6)':'transparent';
    btn.style.transform=m===mood?'scale(1.15)':'scale(1)';
  });
}

function jnToggleTag(tag){
  var idx=_jnSelectedTags.indexOf(tag);
  if(idx>-1) _jnSelectedTags.splice(idx,1); else _jnSelectedTags.push(tag);
  document.getElementById('jn-c-tags').value=JSON.stringify(_jnSelectedTags);
  document.querySelectorAll('.jn-tag-btn').forEach(function(b){
    var t=b.getAttribute('data-tag');
    var active=_jnSelectedTags.indexOf(t)>-1;
    b.style.background=active?'#1a6b3c':'transparent';
    b.style.borderColor=active?'#1a6b3c':'var(--border,#e5e7eb)';
    b.style.color=active?'#fff':'var(--text2,#888)';
  });
}

function jnUseTemplate(key){
  var tpl=JN_TEMPLATES[key]; if(!tpl) return;
  var body=document.getElementById('jn-c-body');
  if(body){ body.value=tpl; jnUpdateWordCount(); }
  var title=document.getElementById('jn-c-title');
  var titleMap={morning:'সকালের জার্নাল',evening:'সন্ধ্যার রিফ্লেকশন',gratitude:'শোকরানার জার্নাল',dua:'দুআর লগ',review:'সাপ্তাহিক রিভিউ',dream:'স্বপ্ন লগ',shukr:'শোকরানা',tawbah:'তওবাহ ও মুহাসাবা',quran:'কোরআন রিফ্লেকশন'};
  if(title&&!title.value) title.value=titleMap[key]||'';
  // auto-set mood for some templates
  var moodMap={morning:'motivated',evening:'reflective',gratitude:'grateful',shukr:'grateful',tawbah:'reflective',dua:'peaceful',quran:'peaceful'};
  if(moodMap[key]) jnSetMood(moodMap[key]);
  var tagMap={shukr:'ইসলাম',tawbah:'ইসলাম',dua:'ইসলাম',quran:'ইসলাম',dream:'স্বপ্ন',review:'লক্ষ্য'};
  if(tagMap[key]&&_jnSelectedTags.indexOf(tagMap[key])===-1) jnToggleTag(tagMap[key]);
  body.focus();
}

function jnOpenComposer(){
  var body=document.getElementById('jn-c-body');
  if(body){ body.focus(); body.scrollIntoView({behavior:'smooth',block:'center'}); }
}

async function jnSaveEntry(){
  var body=document.getElementById('jn-c-body');
  if(!body||!body.value.trim()){ alert('কিছু লিখুন!'); return; }
  var editId=document.getElementById('jn-c-id').value;
  var title=document.getElementById('jn-c-title'); var titleVal=title?title.value.trim():'';
  var starred=document.getElementById('jn-c-starred'); var isStarred=starred?starred.checked:false;
  var entry={
    id:editId||jnUid(), date:jnToday(), title:titleVal, body:body.value,
    mood:_jnSelectedMood, tags:_jnSelectedTags.slice(), starred:isStarred,
    wordCount:jnWordCount(body.value), createdAt:new Date().toISOString()
  };
  await jnSaveEntry_sb(entry);
  // Reset composer
  body.value='';
  if(title) title.value='';
  if(starred) starred.checked=false;
  document.getElementById('jn-c-id').value='';
  _jnSelectedTags=[]; _jnSelectedMood='';
  document.getElementById('jn-c-tags').value='[]';
  jnUpdateWordCount();
  document.querySelectorAll('.jn-tag-btn').forEach(function(b){ b.style.background='transparent'; b.style.borderColor='var(--border,#e5e7eb)'; b.style.color='var(--text2,#888)'; });
  Object.keys(JN_MOODS).forEach(function(m){ var btn=document.getElementById('jnm-'+m); if(btn){ btn.style.background='rgba(255,255,255,.1)'; btn.style.borderColor='transparent'; btn.style.transform='scale(1)'; } });
  jnRender();
}

async function jnGetFilteredEntries(){
  var d=await jnGetData(); var entries=d.entries||[];
  var today=jnToday();
  if(_jnFilter==='today') entries=entries.filter(function(e){ return e.date===today; });
  else if(_jnFilter==='starred') entries=entries.filter(function(e){ return e.starred; });
  else if(_jnFilter==='islamic') entries=entries.filter(function(e){ return (e.tags||[]).indexOf('ইসলাম')>-1; });
  if(_jnSearchQuery){
    var q=_jnSearchQuery.toLowerCase();
    entries=entries.filter(function(e){ return (e.title||'').toLowerCase().indexOf(q)>-1||(e.body||'').toLowerCase().indexOf(q)>-1; });
  }
  return entries;
}

async function jnRenderEntries(){
  var el=document.getElementById('jn-entry-list'); if(!el) return;
  var entries=await jnGetFilteredEntries();
  if(!entries.length){
    el.innerHTML='<div style="text-align:center;padding:40px 20px"><div style="font-size:40px;margin-bottom:12px">📔</div><div style="font-size:14px;font-weight:700;color:var(--text,#1a1a2e);margin-bottom:6px">কোনো এন্ট্রি নেই</div><div style="font-size:12px;color:var(--text2,#888)">প্রথম এন্ট্রি লিখুন — উপরের কম্পোজার ব্যবহার করুন।</div></div>';
    return;
  }
  // Group by date
  var groups={};
  entries.forEach(function(e){
    var dateKey=e.date||jnToday();
    if(!groups[dateKey]) groups[dateKey]=[];
    groups[dateKey].push(e);
  });
  var sortedDates=Object.keys(groups).sort(function(a,b){ return b>a?1:-1; });
  var today=jnToday();
  var html='';
  sortedDates.forEach(function(date){
    var label=date===today?'📅 আজ':date;
    html+='<div style="font-size:10px;font-weight:800;color:var(--text2,#888);letter-spacing:1px;margin:16px 0 8px">'+label+'</div>';
    groups[date].forEach(function(entry){
      var mood=entry.mood?JN_MOODS[entry.mood]:{icon:'',color:'var(--border,#e5e7eb)'};
      var excerpt=(entry.body||'').replace(/\n/g,' ').slice(0,120)+(entry.body&&entry.body.length>120?'...':'');
      var tagsHtml=(entry.tags||[]).map(function(t){ return '<span style="font-size:9px;background:rgba(26,107,60,.08);color:#1a6b3c;padding:2px 7px;border-radius:6px;font-weight:600">'+t+'</span>'; }).join('');
      html+='<div onclick="jnOpenEntry(\''+entry.id+'\')" style="background:var(--bg,#fff);border:1.5px solid var(--border,#e5e7eb);border-left:3px solid '+(mood.color||'#1a6b3c')+';border-radius:14px;padding:14px 16px;margin-bottom:8px;cursor:pointer;transition:.2s" onmouseover="this.style.borderColor=\'rgba(26,107,60,.3)\'" onmouseout="this.style.borderColor=\'var(--border,#e5e7eb)\'">'
        +'<div style="display:flex;align-items:flex-start;gap:10px">'
        +(mood.icon?'<span style="font-size:20px;flex-shrink:0;margin-top:1px">'+mood.icon+'</span>':'')
        +'<div style="flex:1;min-width:0">'
        +'<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;flex-wrap:wrap">'
        +(entry.title?'<span style="font-size:13px;font-weight:800;color:var(--text,#1a1a2e)">'+entry.title+'</span>':'')
        +(entry.starred?'<span style="font-size:12px">⭐</span>':'')
        +'<span style="font-size:10px;color:var(--text2,#888);margin-left:auto">'+entry.wordCount+'শব্দ · ~'+jnReadTime(entry.wordCount)+'মি</span>'
        +'</div>'
        +'<div style="font-size:12px;color:var(--text2,#888);line-height:1.5;margin-bottom:6px">'+excerpt+'</div>'
        +'<div style="display:flex;gap:5px;flex-wrap:wrap">'+tagsHtml+'</div>'
        +'</div>'
        +'</div>'
        +'</div>';
    });
  });
  el.innerHTML=html;
}

async function jnRenderHeatmap(){
  var el=document.getElementById('jn-heatmap'); if(!el) return;
  var d=await jnGetData(); var entries=d.entries||[];
  var byDate={};
  entries.forEach(function(e){ if(e.date) byDate[e.date]=(byDate[e.date]||0)+1; });
  var html='';
  for(var i=48;i>=0;i--){
    var dt=new Date(); dt.setDate(dt.getDate()-i);
    var ds=dt.toISOString().slice(0,10);
    var cnt=byDate[ds]||0;
    var isToday=ds===jnToday();
    var alpha=cnt===0?0:cnt===1?.35:cnt<=2?.6:1;
    html+='<div title="'+ds+': '+cnt+'টি এন্ট্রি" style="width:11px;height:11px;border-radius:2px;background:'+(cnt>0?'rgba(26,107,60,'+alpha+')':'var(--border,#e5e7eb)')+';'+(isToday?'outline:2px solid #FF8A00;outline-offset:1px':'')+'"></div>';
  }
  el.innerHTML=html;
}

async function jnRenderMoodChart(){
  var el=document.getElementById('jn-mood-chart'); if(!el) return;
  var d=await jnGetData(); var entries=d.entries||[];
  var counts={};
  entries.forEach(function(e){ if(e.mood) counts[e.mood]=(counts[e.mood]||0)+1; });
  var maxCount=Math.max(1, Math.max.apply(null, Object.values(counts).concat([0])));
  var moods=Object.keys(JN_MOODS).filter(function(m){ return counts[m]>0; }).sort(function(a,b){ return (counts[b]||0)-(counts[a]||0); });
  if(!moods.length){ el.innerHTML='<div style="font-size:12px;color:var(--text2,#888);text-align:center;padding:12px">এন্ট্রি লিখলে মেজাজের তথ্য দেখাবে।</div>'; return; }
  el.innerHTML=moods.map(function(m){
    var info=JN_MOODS[m]; var cnt=counts[m]||0; var pct=Math.round(cnt/maxCount*100);
    return '<div style="display:flex;align-items:center;gap:10px">'
      +'<span style="font-size:16px;width:24px;text-align:center">'+info.icon+'</span>'
      +'<div style="flex:1"><div style="display:flex;justify-content:space-between;margin-bottom:3px"><span style="font-size:11px;font-weight:700;color:var(--text,#1a1a2e)">'+info.label+'</span><span style="font-size:10px;color:var(--text2,#888)">'+cnt+'x</span></div>'
      +'<div style="background:var(--border,#e5e7eb);height:5px;border-radius:4px"><div style="width:'+pct+'%;height:5px;background:'+info.color+';border-radius:4px;transition:.5s"></div></div></div>'
      +'</div>';
  }).join('');
}

async function jnUpdateSidebar(){
  var d=await jnGetData(); var entries=d.entries||[];
  var streak=jnCalcStreak(entries);
  var totalWords=entries.reduce(function(s,e){ return s+jnWordCount(e.body||''); },0);
  var setEl=function(id,v){ var el=document.getElementById(id); if(el) el.textContent=v; };
  setEl('jn-sb-streak', streak+' দিন');
  setEl('jn-sb-entries', entries.length);
  setEl('jn-sb-words', totalWords>999?(Math.round(totalWords/100)/10)+'k':totalWords);
  // Recent moods
  var moodsEl=document.getElementById('jn-sb-moods');
  if(moodsEl){
    var recent=entries.slice(0,7).filter(function(e){ return e.mood; });
    moodsEl.innerHTML=recent.length?recent.map(function(e){ return '<span title="'+e.date+'" style="font-size:18px;cursor:pointer" onclick="jnOpenEntry(\''+e.id+'\')">'+(JN_MOODS[e.mood]||{icon:'📔'}).icon+'</span>'; }).join('')
      :'<span style="font-size:11px;color:var(--text2,#888)">এখনো কোনো এন্ট্রি নেই</span>';
  }
}

function jnSetFilter(f){
  _jnFilter=f;
  ['all','today','starred','islamic'].forEach(function(x){
    var btn=document.getElementById('jnf-'+x); if(!btn) return;
    if(x===f){ btn.style.background='#1a6b3c'; btn.style.color='#fff'; btn.style.borderColor='#1a6b3c'; }
    else { btn.style.background='transparent'; btn.style.color='var(--text2,#888)'; btn.style.borderColor='var(--border,#e5e7eb)'; }
  });
  jnRenderEntries();
}

function jnSearch(){
  var inp=document.getElementById('jn-search');
  _jnSearchQuery=inp?inp.value.trim():'';
  jnRenderEntries();
}

async function jnOpenEntry(id){
  var d=await jnGetData(); var entry=(d.entries||[]).find(function(e){ return e.id===id; });
  if(!entry) return;
  _jnModalEntryId=id;
  var mood=entry.mood?JN_MOODS[entry.mood]:{icon:'📔',color:'#1a6b3c'};
  var setEl=function(elId,v){ var el=document.getElementById(elId); if(el) el.textContent=v; };
  setEl('jn-modal-date', entry.date+(mood.label?' · '+mood.label:''));
  setEl('jn-modal-title', entry.title||'(শিরোনাম নেই)');
  setEl('jn-modal-body', entry.body||'');
  setEl('jn-modal-stats', entry.wordCount+'টি শব্দ · ~'+jnReadTime(entry.wordCount)+' মিনিট');
  var moodIcon=document.getElementById('jn-modal-mood-icon'); if(moodIcon) moodIcon.textContent=mood.icon||'📔';
  var starBtn=document.getElementById('jn-modal-star-btn'); if(starBtn) starBtn.textContent=entry.starred?'⭐ পছন্দের':'☆ পছন্দ';
  var tagsEl=document.getElementById('jn-modal-tags');
  if(tagsEl) tagsEl.innerHTML=(entry.tags||[]).map(function(t){ return '<span style="font-size:10px;background:rgba(26,107,60,.08);color:#1a6b3c;padding:3px 9px;border-radius:8px;font-weight:700">'+t+'</span>'; }).join('')||'<span style="font-size:10px;color:var(--text2,#888)">কোনো ট্যাগ নেই</span>';
  var modal=document.getElementById('jn-entry-modal'); if(modal) modal.style.display='flex';
}

function jnCloseModal(){
  var m=document.getElementById('jn-entry-modal'); if(m) m.style.display='none';
  _jnModalEntryId='';
}

async function jnModalToggleStar(){
  if(!_jnModalEntryId) return;
  var d=await jnGetData(); var entries=d.entries||[];
  var entry=entries.find(function(e){ return e.id===_jnModalEntryId; });
  if(!entry) return;
  entry.starred=!entry.starred;
  await jnSaveEntry_sb(entry);
  var btn=document.getElementById('jn-modal-star-btn'); if(btn) btn.textContent=entry.starred?'⭐ পছন্দের':'☆ পছন্দ';
  jnUpdateHero(); jnUpdateSidebar();
}

async function jnModalEdit(){
  if(!_jnModalEntryId) return;
  var d=await jnGetData(); var entry=(d.entries||[]).find(function(e){ return e.id===_jnModalEntryId; });
  if(!entry) return;
  jnCloseModal();
  var title=document.getElementById('jn-c-title'); if(title) title.value=entry.title||'';
  var body=document.getElementById('jn-c-body'); if(body){ body.value=entry.body||''; jnUpdateWordCount(); }
  var id=document.getElementById('jn-c-id'); if(id) id.value=entry.id;
  var starred=document.getElementById('jn-c-starred'); if(starred) starred.checked=!!entry.starred;
  _jnSelectedTags=(entry.tags||[]).slice();
  document.getElementById('jn-c-tags').value=JSON.stringify(_jnSelectedTags);
  document.querySelectorAll('.jn-tag-btn').forEach(function(b){
    var t=b.getAttribute('data-tag'); var active=_jnSelectedTags.indexOf(t)>-1;
    b.style.background=active?'#1a6b3c':'transparent';
    b.style.borderColor=active?'#1a6b3c':'var(--border,#e5e7eb)';
    b.style.color=active?'#fff':'var(--text2,#888)';
  });
  if(entry.mood) jnSetMood(entry.mood);
  var composer=document.getElementById('jn-composer'); if(composer) composer.scrollIntoView({behavior:'smooth',block:'start'});
}

async function jnModalDelete(){
  if(!_jnModalEntryId) return;
  if(!confirm('এই এন্ট্রিটি মুছে ফেলবেন?')) return;
  await jnDeleteEntry_sb(_jnModalEntryId);
  jnCloseModal(); jnRender();
}

