/* ═══════════════════════════════════════════════════════
   DEEP WORK PAGE
   ═══════════════════════════════════════════════════════ */
var DW_KEY = 'rz_deepwork';
var _dwTimer = null;
var _dwRunning = false;
var _dwPaused = false;
var _dwTotalSecs = 45 * 60;
var _dwRemainSecs = 45 * 60;
var _dwDuration = 45;
var _dwSelectedProject = '';
var _dwFlowRating = 0;
var _dwDistractions = 0;
var _dwStartTimestamp = 0;
var _dwFocusMode = false;

var _dwCache = null;
function dwGetData() {
  if(_dwCache) return _dwCache;
  try { _dwCache=JSON.parse(localStorage.getItem(DW_KEY)||'null')||{sessions:[],projects:['পড়াশোনা','কাজ','সৃজনশীলতা'],dailyGoal:120}; } catch(e) { _dwCache={sessions:[],projects:['পড়াশোনা','কাজ','সৃজনশীলতা'],dailyGoal:120}; }
  return _dwCache;
}
function dwSaveData(d) { _dwCache=d; try { localStorage.setItem(DW_KEY, JSON.stringify(d)); } catch(e) {} }

async function dwLoadFromSb() {
  if(!window.sbUser||!_sb) return;
  try {
    var sr=await _sb.from('deepwork_sessions').select('*').eq('user_id',sbUser.id).order('created_at',{ascending:false});
    var st=await _sb.from('deepwork_settings').select('*').eq('user_id',sbUser.id).single();
    // deepwork_sessions only has id/user_id/task/duration_mins/date/created_at — the other
    // fields (startTime/startHour/project/flowRating/distractions/notes) never had DB columns
    // to begin with, so they stay local-only (empty/default) rather than reading nonexistent
    // remote columns.
    var sessions=(sr.data||[]).map(function(r){return{id:r.id,date:r.date,startTime:'',startHour:0,duration:r.duration_mins||0,actual:r.duration_mins||0,task:r.task||'',project:'',flowRating:3,distractions:0,notes:''};});
    var projects=['পড়াশোনা','কাজ','সৃজনশীলতা'];
    var dailyGoal=120;
    if(st.data){
      dailyGoal=st.data.daily_goal||120;
      var p=st.data.projects;
      if(Array.isArray(p)&&p.length) projects=p;
    }
    _dwCache={sessions:sessions,projects:projects,dailyGoal:dailyGoal};
  } catch(e) {}
}
function dwInsertSessionSb(s) {
  if(!window.sbUser||!_sb) return;
  // Only id/user_id/task/duration_mins/date exist as real columns — see dwLoadFromSb().
  _sb.from('deepwork_sessions').insert({id:s.id,user_id:sbUser.id,date:s.date,duration_mins:s.actual||s.duration||0,task:s.task||''});
}
function dwSaveSettingsSb(d) {
  if(!window.sbUser||!_sb) return;
  _sb.from('deepwork_settings').upsert({user_id:sbUser.id,daily_goal:d.dailyGoal||120,projects:d.projects||[],updated_at:new Date().toISOString()},{onConflict:'user_id'});
}
function dwClearSessionsSb() {
  if(!window.sbUser||!_sb) return;
  _sb.from('deepwork_sessions').delete().eq('user_id',sbUser.id);
}

function dwToday() {
  var now = new Date();
  return now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
}

function dwFmtMins(m) {
  if(m >= 60) { var h=Math.floor(m/60),mn=m%60; return mn>0?h+'h '+mn+'m':h+'h'; }
  return m+'m';
}

function dwFmtSecs(s) {
  var m=Math.floor(s/60),sc=s%60;
  return String(m).padStart(2,'0')+':'+String(sc).padStart(2,'0');
}

function dwCheckMode() {
  var k = document.getElementById('dw-kids-wrap');
  var a = document.getElementById('dw-adult-wrap');
  if(!k||!a){ setTimeout(dwCheckMode,150); return; }
  if(window.rzMode==='forme') {
    k.style.display='none'; a.style.display='block';
    _dwCache=null; dwLoadFromSb().then(function(){ dwRender(); });
  } else {
    k.style.display='block'; a.style.display='none';
  }
}

function dwRender() {
  dwRenderStats();
  dwRenderGoal();
  dwRenderWeekChart();
  dwRenderHeatmap();
  dwRenderInsights();
  dwRenderLog();
  dwRenderProjectChips();
  dwRenderSidebar();
}

function dwRenderStats() {
  var d = dwGetData();
  var today = dwToday();
  var now = new Date();
  var weekStart = new Date(now); weekStart.setDate(now.getDate() - now.getDay());

  var todayMins = 0, weekMins = 0, totalMins = 0;
  (d.sessions||[]).forEach(function(s) {
    totalMins += (s.actual||0);
    if(s.date === today) todayMins += (s.actual||0);
    var sd = new Date(s.date+'T00:00:00');
    if(sd >= weekStart) weekMins += (s.actual||0);
  });

  var el = document.getElementById('dw-stat-today'); if(el) el.textContent = dwFmtMins(todayMins);
  var we = document.getElementById('dw-stat-week'); if(we) we.textContent = dwFmtMins(weekMins);
  var st = document.getElementById('dw-stat-streak'); if(st) st.textContent = dwCalcStreak(d) + ' দিন';
  var sc = document.getElementById('dw-stat-score'); if(sc) sc.textContent = dwCalcScore(d);
}

function dwCalcStreak(d) {
  var sessions = (d.sessions||[]);
  if(!sessions.length) return 0;
  var dates = {};
  sessions.forEach(function(s){ dates[s.date]=true; });
  var streak = 0;
  var cur = new Date();
  while(true) {
    var key = cur.getFullYear()+'-'+String(cur.getMonth()+1).padStart(2,'0')+'-'+String(cur.getDate()).padStart(2,'0');
    if(dates[key]) { streak++; cur.setDate(cur.getDate()-1); }
    else break;
  }
  return streak;
}

function dwCalcScore(d) {
  var sessions = (d.sessions||[]);
  if(!sessions.length) return 0;
  var score = 0;
  sessions.forEach(function(s){
    var mins = s.actual||0;
    var flow = s.flowRating||3;
    var dis = s.distractions||0;
    score += Math.round(mins * (flow/3) * Math.max(0.5, 1 - dis*0.05));
  });
  return Math.min(9999, score);
}

function dwRenderGoal() {
  var d = dwGetData();
  var today = dwToday();
  var todayMins = 0;
  (d.sessions||[]).forEach(function(s){ if(s.date===today) todayMins+=(s.actual||0); });
  var goal = d.dailyGoal||120;
  var pct = Math.min(100, Math.round(todayMins/goal*100));
  var bar = document.getElementById('dw-goal-bar'); if(bar) bar.style.width = pct+'%';
  var txt = document.getElementById('dw-goal-text'); if(txt) txt.textContent = dwFmtMins(todayMins)+' / '+dwFmtMins(goal);

  // session dots
  var gs = document.getElementById('dw-goal-sessions'); if(!gs) return;
  var todaySessions = (d.sessions||[]).filter(function(s){return s.date===today;});
  if(!todaySessions.length){ gs.innerHTML='<span style="font-size:10px;color:var(--text2,#888)">আজ কোনো সেশন নেই</span>'; return; }
  gs.innerHTML = todaySessions.map(function(s){
    return '<div style="display:flex;align-items:center;gap:4px;background:rgba(56,189,248,.08);border:1px solid rgba(56,189,248,.2);border-radius:8px;padding:3px 8px">'
      +'<span style="font-size:9px;color:#38BDF8;font-weight:700">'+dwFmtMins(s.actual||0)+'</span>'
      +(s.task?'<span style="font-size:9px;color:var(--text2,#888);max-width:80px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+s.task+'</span>':'')
      +'</div>';
  }).join('');
}

function dwRenderWeekChart() {
  var d = dwGetData();
  var days = ['রবি','সোম','মঙ্গল','বুধ','বৃহ','শুক্র','শনি'];
  var now = new Date();
  var weekData = [];
  for(var i=6;i>=0;i--) {
    var dt = new Date(now); dt.setDate(now.getDate()-i);
    var key = dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');
    var mins = 0;
    (d.sessions||[]).forEach(function(s){ if(s.date===key) mins+=(s.actual||0); });
    weekData.push({label:days[dt.getDay()], mins:mins, isToday:i===0});
  }
  var maxMins = Math.max(60, Math.max.apply(null, weekData.map(function(x){return x.mins;})));
  var chartEl = document.getElementById('dw-week-chart');
  var labelsEl = document.getElementById('dw-week-labels');
  if(!chartEl||!labelsEl) return;

  chartEl.innerHTML = weekData.map(function(day) {
    var h = day.mins > 0 ? Math.max(6, Math.round(day.mins/maxMins*72)) : 3;
    var color = day.isToday ? 'linear-gradient(180deg,#38BDF8,#6366F1)' : 'rgba(56,189,248,.35)';
    return '<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:2px">'
      +'<div style="font-size:8px;color:var(--text2,#888);font-weight:700">'+(day.mins>0?dwFmtMins(day.mins):'')+'</div>'
      +'<div style="width:100%;max-width:28px;height:'+h+'px;background:'+color+';border-radius:4px 4px 0 0;transition:.5s"></div>'
      +'</div>';
  }).join('');
  labelsEl.innerHTML = weekData.map(function(day) {
    return '<div style="flex:1;text-align:center;font-size:9px;color:'+(day.isToday?'#38BDF8':'var(--text2,#888)')+';font-weight:'+(day.isToday?'800':'600')+'">'+day.label+'</div>';
  }).join('');
}

function dwRenderHeatmap() {
  var d = dwGetData();
  var el = document.getElementById('dw-heatmap'); if(!el) return;
  var now = new Date();
  var html = '';
  for(var i=48;i>=0;i--) {
    var dt = new Date(now); dt.setDate(now.getDate()-i);
    var key = dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0');
    var mins = 0;
    (d.sessions||[]).forEach(function(s){ if(s.date===key) mins+=(s.actual||0); });
    var isToday = i===0;
    var alpha = mins===0?0:(mins<30?0.3:mins<60?0.6:1);
    var bg = mins>0?'rgba(56,189,248,'+alpha+')':'var(--border,#e5e7eb)';
    var outline = isToday?'outline:2px solid #FF8A00;outline-offset:1px':'';
    html += '<div title="'+key+': '+dwFmtMins(mins)+'" style="width:9px;height:9px;border-radius:2px;background:'+bg+';'+outline+'"></div>';
  }
  el.innerHTML = html;
}

function dwRenderInsights() {
  var d = dwGetData();
  var sessions = d.sessions||[];
  if(!sessions.length) return;

  // peak hour
  var hourMap = {};
  sessions.forEach(function(s){
    var h = s.startHour||0;
    hourMap[h] = (hourMap[h]||0) + (s.actual||0);
  });
  var peakHour = -1, peakVal = 0;
  Object.keys(hourMap).forEach(function(h){ if(hourMap[h]>peakVal){peakVal=hourMap[h];peakHour=parseInt(h);} });
  var peakEl = document.getElementById('dw-ins-peak');
  if(peakEl && peakHour>=0) {
    var ampm = peakHour<12?'AM':'PM'; var h12=(peakHour%12)||12;
    peakEl.textContent = h12+ampm;
  }

  // avg session
  var totalActual = sessions.reduce(function(a,s){return a+(s.actual||0);},0);
  var avgEl = document.getElementById('dw-ins-avg');
  if(avgEl) avgEl.textContent = dwFmtMins(Math.round(totalActual/sessions.length));

  // avg flow
  var flowSessions = sessions.filter(function(s){return s.flowRating;});
  var flowEl = document.getElementById('dw-ins-flow');
  if(flowEl && flowSessions.length) {
    var avgFlow = flowSessions.reduce(function(a,s){return a+s.flowRating;},0)/flowSessions.length;
    var flowEmoji = ['','😩','😕','😐','😊','🚀'];
    flowEl.textContent = flowEmoji[Math.round(avgFlow)]||'😐';
  }

  // total sessions
  var totEl = document.getElementById('dw-ins-total');
  if(totEl) totEl.textContent = sessions.length;
}

function dwRenderLog() {
  var d = dwGetData();
  var el = document.getElementById('dw-session-log'); if(!el) return;
  var sessions = (d.sessions||[]).slice().reverse();
  if(!sessions.length) {
    el.innerHTML = '<div style="text-align:center;padding:24px;color:var(--text2,#888);font-size:13px">এখনো কোনো সেশন নেই। আজই শুরু করুন! 🧠</div>';
    return;
  }
  var flowEmoji = ['','😩','😕','😐','😊','🚀'];
  el.innerHTML = sessions.slice(0,20).map(function(s) {
    return '<div style="display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--border,#e5e7eb)">'
      +'<div style="width:36px;height:36px;border-radius:10px;background:rgba(56,189,248,.1);border:1px solid rgba(56,189,248,.2);display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0">'+(flowEmoji[s.flowRating||3]||'😐')+'</div>'
      +'<div style="flex:1;min-width:0">'
        +'<div style="font-size:12px;font-weight:700;color:var(--text,#1a1a2e);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+(s.task||'সেশন')+'</div>'
        +'<div style="font-size:10px;color:var(--text2,#888);margin-top:2px">'+(s.project?'<span style="color:#38BDF8">'+s.project+'</span> &bull; ':'')+''+s.date+' '+s.startTime+'</div>'
      +'</div>'
      +'<div style="text-align:right;flex-shrink:0">'
        +'<div style="font-size:13px;font-weight:800;color:#38BDF8">'+dwFmtMins(s.actual||0)+'</div>'
        +'<div style="font-size:9px;color:var(--text2,#888)">'+(s.distractions?s.distractions+' বাধা':'')+'</div>'
      +'</div>'
      +'</div>';
  }).join('');
}

function dwRenderProjectChips() {
  var d = dwGetData();
  var el = document.getElementById('dw-project-chips'); if(!el) return;
  el.innerHTML = (d.projects||[]).map(function(p) {
    var active = _dwSelectedProject===p;
    return '<button onclick="dwSelectProject(\''+p+'\')" style="padding:4px 10px;border-radius:8px;border:1.5px solid '+(active?'#38BDF8':'rgba(56,189,248,.3)')+';background:'+(active?'rgba(56,189,248,.15)':'transparent')+';color:'+(active?'#38BDF8':'rgba(255,255,255,.5)')+';font-size:10px;font-weight:700;cursor:pointer">'+p+'</button>';
  }).join('');
}

function dwRenderSidebar() {
  var d = dwGetData();
  var today = dwToday();

  // Today sessions in sidebar
  var sbToday = document.getElementById('dw-sb-today');
  if(sbToday) {
    var ts = (d.sessions||[]).filter(function(s){return s.date===today;});
    if(!ts.length) { sbToday.innerHTML='<div style="font-size:11px;color:var(--text2,#888)">কোনো সেশন নেই</div>'; }
    else {
      sbToday.innerHTML = ts.map(function(s){
        return '<div style="display:flex;justify-content:space-between;margin-bottom:4px">'
          +'<span style="font-size:11px;color:var(--text,#1a1a2e);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:120px">'+(s.task||'সেশন')+'</span>'
          +'<span style="font-size:11px;font-weight:700;color:#38BDF8">'+dwFmtMins(s.actual||0)+'</span></div>';
      }).join('');
    }
  }

  var sessions = d.sessions||[];
  var totalMins = sessions.reduce(function(a,s){return a+(s.actual||0);},0);
  var streak = dwCalcStreak(d);

  var sbStreak = document.getElementById('dw-sb-streak'); if(sbStreak) sbStreak.textContent = streak+' দিন';
  var sbTotal = document.getElementById('dw-sb-total'); if(sbTotal) sbTotal.textContent = dwFmtMins(totalMins);

  var flowSessions = sessions.filter(function(s){return s.flowRating;});
  var flowEmoji = ['','😩','😕','😐','😊','🚀'];
  var sbFlow = document.getElementById('dw-sb-flow');
  if(sbFlow) {
    if(flowSessions.length) {
      var avg = flowSessions.reduce(function(a,s){return a+s.flowRating;},0)/flowSessions.length;
      sbFlow.textContent = flowEmoji[Math.round(avg)]||'😐';
    } else sbFlow.textContent='--';
  }
}

function dwSetDuration(mins) {
  if(_dwRunning&&!_dwPaused) return;
  _dwDuration = mins;
  _dwTotalSecs = mins*60;
  _dwRemainSecs = mins*60;
  // update ring to full
  dwUpdateTimerRing(1);
  var d=document.getElementById('dw-timer-display'); if(d)d.textContent=dwFmtSecs(_dwRemainSecs);
  [25,45,90,120].forEach(function(m){
    var b=document.getElementById('dw-dur-'+m);
    if(!b)return;
    if(m===mins){ b.classList.add('active'); } else { b.classList.remove('active'); }
  });
}

function dwUpdateTimerRing(pct) {
  var ring = document.getElementById('dw-timer-ring');
  if(ring) {
    if(ring.tagName && ring.tagName.toLowerCase()==='circle') {
      var dash=Math.round(pct*490); ring.setAttribute('stroke-dasharray',dash+' 490');
    } else {
      ring.style.width = Math.round(pct*100)+'%';
    }
  }
  var ringGlow = document.getElementById('dw-timer-ring-glow');
  if(ringGlow) { ringGlow.setAttribute('stroke-dasharray',Math.round(pct*490)+' 490'); }
  var foring = document.getElementById('dw-fo-ring');
  if(foring) { foring.style.width = Math.round(pct*100)+'%'; }
}

function dwStartSession() {
  if(_dwRunning) { if(_dwPaused) { _dwPaused=false; dwResume(); } return; }
  _dwRunning = true; _dwPaused = false;
  _dwDistractions = 0;
  _dwFlowRating = 0;
  _dwStartTimestamp = Date.now();
  var bs=document.getElementById('dw-btn-start'); if(bs)bs.style.display='none';
  var bp=document.getElementById('dw-btn-pause'); if(bp)bp.style.display='flex';
  var bst=document.getElementById('dw-btn-stop'); if(bst){bst.style.display='';bst.style.display='inline-block';}
  var bf=document.getElementById('dw-btn-focus'); if(bf){bf.style.display='';bf.style.display='inline-block';}
  var dp=document.getElementById('dw-distraction-panel'); if(dp)dp.style.display='flex';
  var dc=document.getElementById('dw-distraction-count'); if(dc)dc.textContent='0';
  var st=document.getElementById('dw-timer-status'); if(st)st.textContent='চলছে...';
  // animate drain bar glow
  var ring=document.getElementById('dw-timer-ring'); if(ring)ring.classList.add('dw-active');
  // animate EQ bars
  for(var _i=0;_i<=10;_i++){var _b=document.getElementById('dw-eq-'+_i);if(_b)_b.classList.add('active');}
  // scanline
  var sl=document.getElementById('dw-scanline'); if(sl)sl.classList.add('active');
  // live dot
  var dot=document.getElementById('dw-live-dot'); if(dot){dot.style.background='#38BDF8';dot.style.animation='dwDotBlink 1s ease-in-out infinite';}
  dwResume();
}

function dwResume() {
  clearInterval(_dwTimer);
  _dwTimer = setInterval(function(){
    if(_dwPaused) return;
    _dwRemainSecs--;
    var pct = _dwRemainSecs/_dwTotalSecs;
    dwUpdateTimerRing(pct);
    var disp = dwFmtSecs(_dwRemainSecs);
    var td=document.getElementById('dw-timer-display'); if(td)td.textContent=disp;
    var fot=document.getElementById('dw-fo-timer'); if(fot)fot.textContent=disp;
    if(_dwRemainSecs<=0) { clearInterval(_dwTimer); dwStopSession(); }
  }, 1000);
}

function dwPauseSession() {
  if(!_dwRunning) return;
  _dwPaused = !_dwPaused;
  var icon=document.getElementById('dw-pause-icon');
  var lbl=document.getElementById('dw-pause-label');
  var fop=document.getElementById('dw-fo-pause-icon');
  var fopl=document.getElementById('dw-fo-pause-label');
  var st=document.getElementById('dw-timer-status');
  var fos=document.getElementById('dw-fo-status');
  // main HUD EQ + scanline
  for(var _i=0;_i<=10;_i++){var _b=document.getElementById('dw-eq-'+_i);if(_b){if(_dwPaused)_b.classList.remove('active');else _b.classList.add('active');}}
  var sl=document.getElementById('dw-scanline');if(sl){if(_dwPaused)sl.classList.remove('active');else sl.classList.add('active');}
  // focus overlay EQ + scanline + dot
  for(var _j=0;_j<=10;_j++){var _c=document.getElementById('dw-fo-eq-'+_j);if(_c){if(_dwPaused)_c.classList.remove('active');else _c.classList.add('active');}}
  var fsl=document.getElementById('dw-fo-scanline');if(fsl)fsl.style.opacity=_dwPaused?'0':'1';
  var fdot=document.getElementById('dw-fo-dot');if(fdot){fdot.style.background=_dwPaused?'rgba(56,189,248,.3)':'#38BDF8';fdot.style.animation=_dwPaused?'none':'dwDotBlink 1s ease-in-out infinite';}
  if(_dwPaused) {
    if(icon) icon.innerHTML='<polygon points="4,2 16,9 4,16" fill="#38BDF8"/>';
    if(lbl) lbl.textContent='চালিয়ে যান';
    if(fop) fop.innerHTML='<polygon points="3,1 12,6.5 3,12" fill="#38BDF8"/>';
    if(fopl) fopl.textContent='চালিয়ে যান';
    if(st) st.textContent='বিরতিতে...';
    if(fos) fos.textContent='বিরতিতে...';
  } else {
    if(icon) icon.innerHTML='<rect x="3" y="2" width="4" height="14" rx="1.5" fill="#38BDF8"/><rect x="11" y="2" width="4" height="14" rx="1.5" fill="#38BDF8"/>';
    if(lbl) lbl.textContent='বিরতি';
    if(fop) fop.innerHTML='<rect x="2" y="1" width="3" height="11" rx="1" fill="#38BDF8"/><rect x="8" y="1" width="3" height="11" rx="1" fill="#38BDF8"/>';
    if(fopl) fopl.textContent='বিরতি';
    if(st) st.textContent='চলছে...';
    if(fos) fos.textContent='চলছে...';
  }
}

function dwStopSession() {
  clearInterval(_dwTimer);
  _dwRunning = false; _dwPaused = false;
  var actualMins = Math.round((_dwTotalSecs - _dwRemainSecs)/60);
  if(actualMins < 1) { dwResetTimer(); return; }
  // show flow modal
  var sumEl = document.getElementById('dw-modal-summary');
  if(sumEl) sumEl.textContent = dwFmtMins(actualMins)+' কাজ করলেন'+(document.getElementById('dw-session-task').value?' — '+document.getElementById('dw-session-task').value:'')+('. বাধা: '+_dwDistractions);
  var notesEl = document.getElementById('dw-modal-notes'); if(notesEl)notesEl.value='';
  _dwFlowRating = 0;
  document.querySelectorAll('.dw-flow-btn').forEach(function(b){b.style.border='2px solid var(--border,#e5e7eb)';b.style.background='var(--bg2,#f3f4f6)';});
  var modal = document.getElementById('dw-flow-modal');
  if(modal) modal.style.display='flex';
  if(_dwFocusMode) dwExitFocusMode();
  // store for saving
  window._dwPendingActual = actualMins;
}

function dwRateFlow(r) {
  _dwFlowRating = r;
  document.querySelectorAll('.dw-flow-btn').forEach(function(b,i){
    b.style.border = i+1===r ? '2px solid #38BDF8' : '2px solid var(--border,#e5e7eb)';
    b.style.background = i+1===r ? 'rgba(56,189,248,.12)' : 'var(--bg2,#f3f4f6)';
  });
}

function dwSaveSession() {
  var modal = document.getElementById('dw-flow-modal');
  if(modal) modal.style.display='none';
  var now = new Date();
  var session = {
    id: Date.now()+'',
    date: dwToday(),
    startTime: String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0'),
    startHour: now.getHours(),
    duration: _dwDuration,
    actual: window._dwPendingActual||0,
    task: (document.getElementById('dw-session-task')||{}).value||'',
    project: _dwSelectedProject,
    flowRating: _dwFlowRating||3,
    distractions: _dwDistractions,
    notes: (document.getElementById('dw-modal-notes')||{}).value||''
  };
  var d = dwGetData();
  d.sessions = (d.sessions||[]);
  d.sessions.push(session);
  dwSaveData(d); dwInsertSessionSb(session);
  dwResetTimer();
  dwRender();
}

function dwResetTimer() {
  clearInterval(_dwTimer);
  _dwRunning = false; _dwPaused = false; _dwDistractions = 0;
  _dwRemainSecs = _dwTotalSecs;
  dwUpdateTimerRing(1);
  var td=document.getElementById('dw-timer-display'); if(td)td.textContent=dwFmtSecs(_dwTotalSecs);
  var st=document.getElementById('dw-timer-status'); if(st)st.textContent='প্রস্তুত';
  var bs=document.getElementById('dw-btn-start'); if(bs)bs.style.display='';
  var bp=document.getElementById('dw-btn-pause'); if(bp)bp.style.display='none';
  var bst=document.getElementById('dw-btn-stop'); if(bst)bst.style.display='none';
  var bf=document.getElementById('dw-btn-focus'); if(bf)bf.style.display='none';
  var dp=document.getElementById('dw-distraction-panel'); if(dp)dp.style.display='none';
  // remove active animations
  var ring=document.getElementById('dw-timer-ring'); if(ring)ring.classList.remove('dw-active');
  for(var _i=0;_i<=10;_i++){var _b=document.getElementById('dw-eq-'+_i);if(_b)_b.classList.remove('active');}
  var sl=document.getElementById('dw-scanline'); if(sl)sl.classList.remove('active');
  var dot=document.getElementById('dw-live-dot'); if(dot){dot.style.background='rgba(56,189,248,.3)';dot.style.animation='';}
}

function dwLogDistraction() {
  _dwDistractions++;
  var dc=document.getElementById('dw-distraction-count'); if(dc)dc.textContent=_dwDistractions;
  var fod=document.getElementById('dw-fo-distract'); if(fod)fod.textContent=_dwDistractions;
}

function dwEnterFocusMode() {
  _dwFocusMode = true;
  var foTask = document.getElementById('dw-fo-task');
  if(foTask) foTask.textContent = (document.getElementById('dw-session-task')||{}).value||'Deep Work';
  var overlay = document.getElementById('dw-focus-overlay');
  if(overlay) overlay.style.display='flex';
  var fot=document.getElementById('dw-fo-timer'); if(fot)fot.textContent=dwFmtSecs(_dwRemainSecs);
  dwUpdateTimerRing(_dwRemainSecs/_dwTotalSecs);
  // activate EQ bars
  for(var _i=0;_i<=10;_i++){var _b=document.getElementById('dw-fo-eq-'+_i);if(_b)_b.classList.add('active');}
  // activate scanline
  var sl=document.getElementById('dw-fo-scanline');if(sl)sl.style.opacity='1';
  // blink dot
  var dot=document.getElementById('dw-fo-dot');if(dot){dot.style.background='#38BDF8';dot.style.animation='dwDotBlink 1s ease-in-out infinite';}
}

function dwExitFocusMode() {
  _dwFocusMode = false;
  var overlay = document.getElementById('dw-focus-overlay');
  if(overlay) overlay.style.display='none';
  for(var _i=0;_i<=10;_i++){var _b=document.getElementById('dw-fo-eq-'+_i);if(_b)_b.classList.remove('active');}
  var sl=document.getElementById('dw-fo-scanline');if(sl)sl.style.opacity='0';
  var dot=document.getElementById('dw-fo-dot');if(dot){dot.style.background='rgba(56,189,248,.3)';dot.style.animation='none';}
}

function dwChangeGoal() {
  var modal = document.getElementById('dw-goal-modal');
  if(modal) modal.style.display='flex';
}

function dwSetGoal(mins) {
  var modal = document.getElementById('dw-goal-modal');
  if(modal) modal.style.display='none';
  var d = dwGetData();
  d.dailyGoal = mins;
  dwSaveData(d); dwSaveSettingsSb(d);
  dwRenderGoal();
}

function dwOpenProjectModal() {
  var modal = document.getElementById('dw-project-modal');
  if(modal) modal.style.display='flex';
  var inp = document.getElementById('dw-project-input');
  if(inp) { inp.value=''; setTimeout(function(){inp.focus();},100); }
}

function dwAddProject() {
  var inp = document.getElementById('dw-project-input'); if(!inp||!inp.value.trim()) return;
  var name = inp.value.trim();
  var d = dwGetData();
  d.projects = d.projects||[];
  if(d.projects.indexOf(name)===-1) d.projects.push(name);
  dwSaveData(d); dwSaveSettingsSb(d);
  var modal = document.getElementById('dw-project-modal');
  if(modal) modal.style.display='none';
  dwRenderProjectChips();
}

function dwSelectProject(p) {
  _dwSelectedProject = _dwSelectedProject===p?'':p;
  dwRenderProjectChips();
}

function dwClearLog() {
  if(!confirm('সব সেশন মুছে ফেলবেন?')) return;
  var d = dwGetData(); d.sessions=[]; dwSaveData(d); dwClearSessionsSb(); dwRender();
}

window.dwCheckMode=dwCheckMode;
window.dwRender=dwRender;
window.dwSetDuration=dwSetDuration;
window.dwStartSession=dwStartSession;
window.dwPauseSession=dwPauseSession;
window.dwStopSession=dwStopSession;
window.dwRateFlow=dwRateFlow;
window.dwSaveSession=dwSaveSession;
window.dwLogDistraction=dwLogDistraction;
window.dwEnterFocusMode=dwEnterFocusMode;
window.dwExitFocusMode=dwExitFocusMode;
window.dwChangeGoal=dwChangeGoal;
window.dwSetGoal=dwSetGoal;
window.dwOpenProjectModal=dwOpenProjectModal;
window.dwAddProject=dwAddProject;
window.dwSelectProject=dwSelectProject;
window.dwClearLog=dwClearLog;

// ===== SMART NOTE =====
var SN_KEY = 'rz_smartnotes';
var _snNotes = [];
var _snFilter = 'all';
var _snSearch = '';
var _snEditId = null;
var _snViewId = null;
var _snType = 'text';
var _snColor = 'default';
var _snStar = 0;

async function snLoad() {
  if(!window.sbUser||!_sb){
    try{_snNotes=JSON.parse(localStorage.getItem(SN_KEY)||'[]');}catch(e){_snNotes=[];}
  } else {
    try{
      var res=await _sb.from('smart_notes').select('*').eq('user_id',sbUser.id).order('ts',{ascending:false});
      _snNotes=(res.data||[]).map(function(r){
        var n={id:r.id,ts:r.ts,updatedTs:r.updated_ts,type:r.type||'text',title:r.title||'',color:r.color||'default',tags:r.tags||[],pinned:r.pinned||false};
        if(r.type==='checklist') n.checklist=r.checklist||[];
        else if(r.type==='book'){n.author=r.author||'';n.star=r.star||0;n.progress=r.progress||0;n.takeaways=r.takeaways||'';n.quote=r.quote||'';}
        else n.body=r.body||'';
        return n;
      });
    }catch(e){try{_snNotes=JSON.parse(localStorage.getItem(SN_KEY)||'[]');}catch(e2){_snNotes=[];}}
  }
  snRenderStats();
  snRender();
}

async function snSave_sb(note){
  if(!window.sbUser||!_sb) return;
  await _sb.from('smart_notes').upsert({
    id:note.id, user_id:sbUser.id, type:note.type||'text',
    title:note.title||'', body:note.body||'', color:note.color||'default',
    tags:note.tags||[], pinned:note.pinned||false,
    checklist:note.checklist||[], author:note.author||'',
    star:note.star||0, progress:note.progress||0,
    takeaways:note.takeaways||'', quote:note.quote||'',
    ts:note.ts, updated_ts:note.updatedTs
  },{onConflict:'id'});
}

async function snDelete_sb(id){
  if(!window.sbUser||!_sb) return;
  await _sb.from('smart_notes').delete().eq('id',id).eq('user_id',sbUser.id);
}

function snSave() { /* legacy — data now in _snNotes array, persisted via snSave_sb */ }

function snRenderStats() {
  var el = document.getElementById('sn-stats');
  if(!el) return;
  var total = _snNotes.length;
  var now = Date.now();
  var week = _snNotes.filter(function(n){ return (now - n.ts) < 7*86400000; }).length;
  var pins = _snNotes.filter(function(n){ return n.pinned; }).length;
  var _snIco = {
    note:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>',
    cal:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>',
    pin:'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>'
  };
  var stats = [
    {val:total, color:'#8b5cf6', svg:_snIco.note},
    {val:week,  color:'#38BDF8', svg:_snIco.cal},
    {val:pins,  color:'#f59e0b', svg:_snIco.pin}
  ];
  el.innerHTML = stats.map(function(s){
    return '<div style="display:flex;align-items:center;gap:4px;background:var(--card,#fff);border:1px solid var(--border,#e5e7eb);border-radius:20px;padding:3px 9px 3px 6px;color:'+s.color+'">'
      +s.svg
      +'<span style="font-size:12px;font-weight:700;color:var(--text,#1a1a2e)">'+s.val+'</span>'
      +'</div>';
  }).join('');
}

function snOpenModalType(type) {
  snExpandBar(type);
}

// ===== INLINE EDITOR (Google Keep style) =====
var _snIeType = 'text';
var _snIeColor = 'default';
var _snIePinned = false;

function snExpandBar(type) {
  var collapsed = document.getElementById('sn-bar-collapsed');
  var expanded  = document.getElementById('sn-bar-expanded');
  if(!expanded) return;
  if(collapsed) collapsed.style.display = 'none';
  expanded.style.display = 'block';
  // reset
  _snIeType = type || 'text';
  _snIeColor = 'default';
  _snIePinned = false;
  var fields = ['sn-ie-title','sn-ie-body','sn-ie-checklist','sn-ie-author','sn-ie-takeaways','sn-ie-quote','sn-ie-tags'];
  fields.forEach(function(id){ var el=document.getElementById(id); if(el){el.value='';el.style.height='';} });
  snIeSetType(_snIeType);
  snIeSetColor('default', document.querySelector('.sn-ie-dot-sm[data-c="default"]'));
  var pinIco = document.getElementById('sn-ie-pin-btn');
  if(pinIco) pinIco.style.color = 'var(--text2,#bbb)';
  snIeCheck();
  // focus
  setTimeout(function(){
    var f = _snIeType==='checklist' ? 'sn-ie-checklist' : _snIeType==='book' ? 'sn-ie-takeaways' : 'sn-ie-body';
    var el = document.getElementById(f); if(el) el.focus();
  }, 60);
}

function snCollapseBar() {
  var collapsed = document.getElementById('sn-bar-collapsed');
  var expanded  = document.getElementById('sn-bar-expanded');
  if(collapsed) collapsed.style.display = 'flex';
  if(expanded)  expanded.style.display  = 'none';
}

function snIeSetType(type) {
  _snIeType = type;
  ['text','checklist','book'].forEach(function(t){
    var w = document.getElementById('sn-ie-'+t+'-wrap');
    if(w) w.style.display = (t===type||(t==='text'&&type==='idea')) ? 'block' : 'none';
  });
  if(type==='book') {
    var bw=document.getElementById('sn-ie-book-wrap'); if(bw) bw.style.display='block';
    var tw=document.getElementById('sn-ie-text-wrap'); if(tw) tw.style.display='none';
  }
  // highlight active toolbar icon
  ['text','checklist','book','idea'].forEach(function(t){
    var btn=document.getElementById('sn-ie-t-'+t);
    if(btn) btn.style.background = (t===type) ? 'rgba(139,92,246,.12)' : 'none';
    if(btn) btn.style.color = (t===type) ? '#8b5cf6' : 'var(--text2,#aaa)';
  });
}

function snIeSetColor(color, dot) {
  _snIeColor = color;
  document.querySelectorAll('.sn-ie-dot-sm').forEach(function(d){
    d.style.transform = 'scale(1)';
    d.style.outline = 'none';
  });
  if(dot) { dot.style.transform='scale(1.3)'; dot.style.outline='2px solid rgba(139,92,246,.5)'; dot.style.outlineOffset='1px'; }
  // update expanded editor background
  var exp = document.getElementById('sn-bar-expanded');
  var colors = {default:'var(--card,#fff)',purple:'rgba(139,92,246,.06)',blue:'rgba(56,189,248,.06)',green:'rgba(16,185,129,.06)',yellow:'rgba(245,158,11,.07)',red:'rgba(239,68,68,.06)'};
  if(exp) exp.style.background = colors[color]||'var(--card,#fff)';
}

function snIeTogglePin() {
  _snIePinned = !_snIePinned;
  var btn = document.getElementById('sn-ie-pin-btn');
  if(btn) btn.style.color = _snIePinned ? '#8b5cf6' : 'var(--text2,#bbb)';
}

function snIeCheck() {
  var hasContent = false;
  var title = (document.getElementById('sn-ie-title')||{}).value||'';
  var body  = (document.getElementById('sn-ie-body')||{}).value||'';
  var cl    = (document.getElementById('sn-ie-checklist')||{}).value||'';
  var ta    = (document.getElementById('sn-ie-takeaways')||{}).value||'';
  hasContent = !!(title||body||cl||ta);
  var btn = document.getElementById('sn-ie-save-btn');
  if(btn){ btn.disabled=!hasContent; btn.style.opacity=hasContent?'1':'.4'; }
}

function snIeSave() {
  var title = (document.getElementById('sn-ie-title')||{}).value.trim()||'';
  var body  = (document.getElementById('sn-ie-body')||{}).value.trim()||'';
  var cl    = (document.getElementById('sn-ie-checklist')||{}).value||'';
  var author= (document.getElementById('sn-ie-author')||{}).value.trim()||'';
  var ta    = (document.getElementById('sn-ie-takeaways')||{}).value.trim()||'';
  var quote = (document.getElementById('sn-ie-quote')||{}).value.trim()||'';
  var tagsRaw = (document.getElementById('sn-ie-tags')||{}).value||'';
  var tags = tagsRaw.split(/[,\s]+/).map(function(t){return t.replace(/^#/,'').trim();}).filter(Boolean);
  if(!title&&!body&&!cl.trim()&&!ta) return;
  var note = {
    id:'sn_'+(Date.now())+'_'+Math.random().toString(36).slice(2,6),
    ts:Date.now(), updatedTs:Date.now(),
    type:_snIeType, title:title, color:_snIeColor, tags:tags, pinned:_snIePinned
  };
  if(_snIeType==='checklist') {
    note.checklist = cl.split('\n').map(function(t){return {text:t.trim(),done:false};}).filter(function(t){return t.text;});
  } else if(_snIeType==='book') {
    note.author=author; note.takeaways=ta; note.quote=quote; note.star=0; note.progress=0;
  } else {
    note.body = body;
  }
  _snNotes.unshift(note);
  snSave_sb(note); snRenderStats(); snRender();
  snCollapseBar();
}

function snRender() {
  var grid = document.getElementById('sn-grid');
  var empty = document.getElementById('sn-empty');
  if(!grid) return;
  var q = _snSearch.toLowerCase();
  var notes = _snNotes.slice().sort(function(a,b){ return (b.pinned?1:0)-(a.pinned?1:0)||(b.ts-a.ts); });
  notes = notes.filter(function(n){
    if(_snFilter==='pinned') return n.pinned;
    if(_snFilter!=='all' && n.type!==_snFilter) return false;
    if(q) {
      var hay = (n.title+' '+(n.body||'')+(n.takeaways||'')+(n.quote||'')+(n.tags||'')).toLowerCase();
      return hay.indexOf(q)>=0;
    }
    return true;
  });
  if(!notes.length){
    grid.innerHTML=''; empty.style.display='block'; return;
  }
  empty.style.display='none';
  grid.innerHTML = notes.map(function(n){ return snCardHTML(n); }).join('');
}

var _snTypeIco = {
  text:     '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4z"/></svg>',
  checklist:'<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 11 12 14 22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>',
  book:     '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>',
  idea:     '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>'
};
var _snAuthorIco = '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';

function snCardHTML(n) {
  var typeIco   = _snTypeIco[n.type]||_snTypeIco.text;
  var typeName  = {text:'টেক্সট',checklist:'চেকলিস্ট',book:'বুক নোট',idea:'আইডিয়া'}[n.type]||'';
  var typeColor = {text:'rgba(56,189,248,.12)',checklist:'rgba(16,185,129,.12)',book:'rgba(245,158,11,.12)',idea:'rgba(139,92,246,.12)'}[n.type];
  var typeText  = {text:'#38BDF8',checklist:'#10b981',book:'#f59e0b',idea:'#8b5cf6'}[n.type];
  var body = '';
  if(n.type==='checklist' && n.checklist){
    body = n.checklist.slice(0,5).map(function(item){
      return '<div style="display:flex;align-items:center;gap:7px;margin-bottom:4px">'
        +'<div style="width:14px;height:14px;border-radius:4px;border:1.5px solid '+(item.done?'#8b5cf6':'var(--border,#ccc)')+';background:'+(item.done?'#8b5cf6':'transparent')+';flex-shrink:0;display:flex;align-items:center;justify-content:center">'
        +(item.done?'<svg width="9" height="9" viewBox="0 0 9 9" fill="none"><polyline points="1.5,4.5 3.5,6.5 7.5,2.5" stroke="white" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>':'')
        +'</div>'
        +'<span style="font-size:12px;color:var(--text2,#555);'+(item.done?'text-decoration:line-through;opacity:.5':'')+'">'+(item.text||'')+'</span>'
        +'</div>';
    }).join('');
    if(n.checklist.length>5) body+='<div style="font-size:11px;color:var(--text2,#aaa);margin-top:2px">+ '+(n.checklist.length-5)+' টি আরও</div>';
  } else if(n.type==='book'){
    var stars = '';
    for(var s=1;s<=5;s++) stars+='<span style="color:'+(s<=(n.star||0)?'#f59e0b':'var(--border,#ccc)')+'">★</span>';
    body = (n.author?'<div style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--text2,#888);margin-bottom:5px">'+_snAuthorIco+' '+snEsc(n.author)+'</div>':'')
      +'<div style="font-size:13px;letter-spacing:1px;margin-bottom:6px">'+stars+'</div>';
    if(n.progress) body += '<div class="sn-book-progress"><div class="sn-book-progress-fill" style="width:'+n.progress+'%"></div></div>'
      +'<div style="font-size:10px;color:var(--text2,#aaa);margin-top:3px;margin-bottom:6px">'+n.progress+'% পড়া হয়েছে</div>';
    if(n.takeaways) body += '<div style="font-size:12px;color:var(--text2,#555);white-space:pre-wrap;display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden">'+snEsc(n.takeaways)+'</div>';
    if(n.quote) body += '<div style="margin-top:8px;padding:8px 10px;border-left:3px solid #f59e0b;background:rgba(245,158,11,.06);border-radius:0 8px 8px 0;font-size:12px;color:var(--text2,#666);font-style:italic">'+snEsc(n.quote)+'</div>';
  } else {
    body = '<div class="sn-card-body">'+snEsc(n.body||'')+'</div>';
  }
  var tagsHtml = '';
  if(n.tags && n.tags.length){
    tagsHtml = '<div class="sn-card-tags">'+n.tags.slice(0,3).map(function(t){
      return '<span class="sn-tag">'+snEsc(t)+'</span>';
    }).join('')+'</div>';
  }
  var dateStr = snFmtDate(n.ts);
  return '<div class="sn-card sn-c-'+n.color+' '+(n.pinned?'pinned':'')+'" onclick="snOpenView(\''+n.id+'\')">'
    +'<div class="sn-type-badge" style="background:'+typeColor+';color:'+typeText+'">'+typeIco+' '+typeName+'</div>'
    +(n.title?'<div class="sn-card-title">'+snEsc(n.title)+'</div>':'')
    +body
    +tagsHtml
    +'<div class="sn-card-footer">'
    +'<div class="sn-card-date">'+dateStr+'</div>'
    +'<div class="sn-card-actions" onclick="event.stopPropagation()">'
    +'<button class="sn-action-btn" onclick="snTogglePin(\''+n.id+'\')" title="পিন"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg></button>'
    +'<button class="sn-action-btn" onclick="snEditNote(\''+n.id+'\')" title="এডিট"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>'
    +'<button class="sn-action-btn del" onclick="snDeleteNote(\''+n.id+'\')" title="মুছুন"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/></svg></button>'
    +'</div></div>'
    +'</div>';
}

function snOpenView(id) {
  var n = _snNotes.find(function(x){return x.id===id;});
  if(!n) return;
  _snViewId = id;
  var el = document.getElementById('sn-view-content');
  if(!el) return;
  var _pinIco='<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>';
  var typeIco2 = _snTypeIco[n.type]||_snTypeIco.text;
  var html = '<div style="display:flex;align-items:center;gap:5px;font-size:11px;color:var(--text2,#888);margin-bottom:8px">'+typeIco2+' '+snFmtDate(n.ts)+(n.pinned?' &middot; '+_pinIco+' পিন':'')+'</div>';
  if(n.title) html += '<div style="font-size:20px;font-weight:800;color:var(--text,#1a1a2e);margin-bottom:14px;line-height:1.3">'+snEsc(n.title)+'</div>';
  if(n.type==='checklist' && n.checklist){
    html += n.checklist.map(function(item,i){
      return '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border,#f0f0f0)" onclick="snToggleCheck(\''+id+'\','+i+')">'
        +'<div style="width:18px;height:18px;border-radius:5px;border:2px solid '+(item.done?'#8b5cf6':'var(--border,#ccc)')+';background:'+(item.done?'#8b5cf6':'transparent')+';flex-shrink:0;display:flex;align-items:center;justify-content:center;cursor:pointer">'
        +(item.done?'<svg width="10" height="10" viewBox="0 0 10 10" fill="none"><polyline points="1.5,5 4,7.5 8.5,2.5" stroke="white" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>':'')
        +'</div>'
        +'<span style="font-size:14px;color:var(--text,#333);'+(item.done?'text-decoration:line-through;opacity:.5':'')+';cursor:pointer">'+snEsc(item.text||'')+'</span>'
        +'</div>';
    }).join('');
  } else if(n.type==='book'){
    var stars='';for(var s=1;s<=5;s++)stars+='<span style="color:'+(s<=(n.star||0)?'#f59e0b':'var(--border,#ccc)')+'">★</span>';
    html += (n.author?'<div style="display:flex;align-items:center;gap:5px;font-size:13px;color:var(--text2,#888);margin-bottom:6px">'+_snAuthorIco+' '+snEsc(n.author)+'</div>':'');
    html += '<div style="font-size:20px;margin-bottom:10px">'+stars+'</div>';
    if(n.progress) html += '<div style="margin-bottom:12px"><div style="font-size:11px;color:var(--text2,#888);margin-bottom:4px">'+n.progress+'% পড়া হয়েছে</div><div style="height:8px;background:rgba(139,92,246,.1);border-radius:4px;overflow:hidden"><div style="height:100%;width:'+n.progress+'%;background:linear-gradient(90deg,#8b5cf6,#38BDF8);border-radius:4px"></div></div></div>';
    if(n.takeaways) html += '<div style="margin-bottom:12px"><div style="font-size:11px;font-weight:700;color:var(--text2,#888);margin-bottom:6px;text-transform:uppercase;letter-spacing:.5px">মূল শিক্ষা</div><div style="font-size:14px;color:var(--text,#333);white-space:pre-wrap;line-height:1.7">'+snEsc(n.takeaways)+'</div></div>';
    if(n.quote) html += '<div style="padding:14px;border-left:4px solid #f59e0b;background:rgba(245,158,11,.07);border-radius:0 12px 12px 0;margin-bottom:12px"><div style="font-size:10px;font-weight:700;color:#f59e0b;margin-bottom:4px;letter-spacing:1px">QUOTE</div><div style="font-size:14px;color:var(--text,#333);font-style:italic;line-height:1.6">'+snEsc(n.quote)+'</div></div>';
  } else {
    html += '<div style="font-size:14px;color:var(--text,#333);white-space:pre-wrap;line-height:1.8">'+snEsc(n.body||'')+'</div>';
  }
  if(n.tags && n.tags.length) html += '<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:16px">'+n.tags.map(function(t){return '<span class="sn-tag">'+snEsc(t)+'</span>';}).join('')+'</div>';
  el.innerHTML = html;
  var vb = document.getElementById('sn-view-bg');
  if(vb) {
    if(window.innerWidth > 500) {
      vb.style.alignItems='center'; vb.style.padding='16px';
      var vm=vb.querySelector('div'); if(vm){vm.style.borderRadius='16px';vm.style.maxWidth='480px';}
    } else {
      vb.style.alignItems='flex-end'; vb.style.padding='0';
      var vm2=vb.querySelector('div'); if(vm2){vm2.style.borderRadius='18px 18px 0 0';vm2.style.maxWidth='100%';}
    }
    vb.style.display='flex';
  }
  var editBtn = document.getElementById('sn-view-edit-btn');
  var pinBtn  = document.getElementById('sn-view-pin-btn');
  var delBtn  = document.getElementById('sn-view-del-btn');
  if(editBtn) editBtn.onclick = function(){ snCloseView(); snEditNote(id); };
  if(pinBtn)  pinBtn.onclick  = function(){ snTogglePin(id); snOpenView(id); };
  if(delBtn)  delBtn.onclick  = function(){ if(confirm('এই নোট মুছে ফেলবেন?')){ snDeleteNote(id); snCloseView(); } };
}

function snCloseView() {
  var vb = document.getElementById('sn-view-bg');
  if(vb) vb.style.display='none';
  _snViewId = null;
}

function snToggleCheck(id, idx) {
  var n = _snNotes.find(function(x){return x.id===id;});
  if(!n||!n.checklist||!n.checklist[idx]) return;
  n.checklist[idx].done = !n.checklist[idx].done;
  snSave_sb(n); snRender(); snOpenView(id);
}

function snOpenModal(editId) {
  _snEditId = editId||null;
  var bg = document.getElementById('sn-modal-bg');
  if(!bg) return;
  var heading = document.getElementById('sn-modal-heading');
  // reset
  _snType='text'; _snColor='default'; _snStar=0;
  document.getElementById('sn-f-title').value='';
  document.getElementById('sn-f-body').value='';
  document.getElementById('sn-f-checklist').value='';
  document.getElementById('sn-f-author').value='';
  document.getElementById('sn-f-takeaways').value='';
  document.getElementById('sn-f-quote').value='';
  document.getElementById('sn-f-tags').value='';
  document.getElementById('sn-f-progress').value=0;
  document.getElementById('sn-prog-val').textContent='0';
  snSetType('text', document.querySelector('.sn-type-tab[data-type="text"]'));
  snSetColor('default', document.querySelector('.sn-color-dot[data-color="default"]'));
  snUpdateStars(0);
  if(_snEditId){
    var n=_snNotes.find(function(x){return x.id===_snEditId;});
    if(n){
      if(heading) heading.textContent='নোট সম্পাদনা';
      document.getElementById('sn-f-title').value=n.title||'';
      document.getElementById('sn-f-body').value=n.body||'';
      if(n.checklist) document.getElementById('sn-f-checklist').value=n.checklist.map(function(c){return c.text;}).join('\n');
      document.getElementById('sn-f-author').value=n.author||'';
      document.getElementById('sn-f-takeaways').value=n.takeaways||'';
      document.getElementById('sn-f-quote').value=n.quote||'';
      document.getElementById('sn-f-tags').value=(n.tags||[]).join(', ');
      document.getElementById('sn-f-progress').value=n.progress||0;
      document.getElementById('sn-prog-val').textContent=n.progress||0;
      snSetType(n.type, document.querySelector('.sn-type-tab[data-type="'+n.type+'"]'));
      snSetColor(n.color||'default', document.querySelector('.sn-color-dot[data-color="'+(n.color||'default')+'"]'));
      _snStar=n.star||0; snUpdateStars(_snStar);
    }
  } else {
    if(heading) heading.textContent='নতুন নোট';
  }
  // Desktop: centered popup; Mobile: bottom sheet
  if(window.innerWidth > 500) {
    bg.style.alignItems = 'center';
    bg.style.padding = '16px';
    var modal = bg.querySelector('.sn-modal');
    if(modal) { modal.style.borderRadius = '16px'; modal.style.maxWidth = '480px'; }
  } else {
    bg.style.alignItems = 'flex-end';
    bg.style.padding = '0';
    var modal2 = bg.querySelector('.sn-modal');
    if(modal2) { modal2.style.borderRadius = '18px 18px 0 0'; modal2.style.maxWidth = '100%'; }
  }
  bg.style.display='flex';
}

function snCloseModal() {
  var bg = document.getElementById('sn-modal-bg');
  if(bg) bg.style.display='none';
}

function snModalBgClick(e) {
  if(e.target===document.getElementById('sn-modal-bg')) snCloseModal();
}

function snSetType(type, btn) {
  _snType = type;
  document.querySelectorAll('.sn-type-tab').forEach(function(b){ b.classList.remove('active'); });
  if(btn) btn.classList.add('active');
  var sections=['text','checklist','book'];
  sections.forEach(function(s){
    var el=document.getElementById('sn-section-'+s);
    if(el) el.style.display=(s===type||(s==='text'&&type==='idea'))?'block':'none';
  });
  if(type==='book'){
    var bs=document.getElementById('sn-section-book');
    if(bs) bs.style.display='block';
    var ts=document.getElementById('sn-section-text');
    if(ts) ts.style.display='none';
  } else {
    var bs2=document.getElementById('sn-section-book');
    if(bs2) bs2.style.display='none';
  }
}

function snSetColor(color, dot) {
  _snColor = color;
  document.querySelectorAll('.sn-color-dot').forEach(function(d){ d.classList.remove('active'); });
  if(dot) dot.classList.add('active');
}

function snSetStar(n) {
  _snStar = n;
  snUpdateStars(n);
}

function snUpdateStars(n) {
  document.querySelectorAll('.sn-star-btn').forEach(function(b,i){
    if(i<n) b.classList.add('lit'); else b.classList.remove('lit');
  });
}

function snSaveNote() {
  var title = document.getElementById('sn-f-title').value.trim();
  var body  = document.getElementById('sn-f-body').value.trim();
  var cl    = document.getElementById('sn-f-checklist').value;
  var tagsRaw = document.getElementById('sn-f-tags').value;
  var tags  = tagsRaw.split(/[,\s]+/).map(function(t){return t.replace(/^#/,'').trim();}).filter(Boolean);
  var prog  = parseInt(document.getElementById('sn-f-progress').value)||0;
  if(!title && !body && !cl.trim()) { alert('শিরোনাম বা বিষয়বস্তু লিখুন'); return; }
  var note = {
    id: _snEditId || ('sn_'+(Date.now())+'_'+Math.random().toString(36).slice(2,7)),
    ts: _snEditId ? (_snNotes.find(function(x){return x.id===_snEditId;})||{ts:Date.now()}).ts : Date.now(),
    updatedTs: Date.now(),
    type: _snType,
    title: title,
    color: _snColor,
    tags: tags,
    pinned: _snEditId ? ((_snNotes.find(function(x){return x.id===_snEditId;})||{}).pinned||false) : false
  };
  if(_snType==='checklist'){
    note.checklist = cl.split('\n').map(function(t){return {text:t.trim(),done:false};}).filter(function(t){return t.text;});
    if(_snEditId){
      var old=_snNotes.find(function(x){return x.id===_snEditId;});
      if(old&&old.checklist) note.checklist=note.checklist.map(function(item){
        var prev=old.checklist.find(function(c){return c.text===item.text;});
        return prev||item;
      });
    }
  } else if(_snType==='book'){
    note.author   = document.getElementById('sn-f-author').value.trim();
    note.star     = _snStar;
    note.progress = prog;
    note.takeaways= document.getElementById('sn-f-takeaways').value.trim();
    note.quote    = document.getElementById('sn-f-quote').value.trim();
  } else {
    note.body = body;
  }
  if(_snEditId){
    var idx=_snNotes.findIndex(function(x){return x.id===_snEditId;});
    if(idx>=0) _snNotes[idx]=note;
  } else {
    _snNotes.unshift(note);
  }
  snSave_sb(note); snRenderStats(); snRender(); snCloseModal();
}

function snDeleteNote(id) {
  _snNotes = _snNotes.filter(function(n){return n.id!==id;});
  snDelete_sb(id); snRenderStats(); snRender();
}

function snTogglePin(id) {
  var n=_snNotes.find(function(x){return x.id===id;});
  if(n) { n.pinned=!n.pinned; snSave_sb(n); snRenderStats(); snRender(); }
}

function snEditNote(id) {
  snOpenModal(id);
}

function snFilter() {
  _snSearch = (document.getElementById('sn-search-input')||{}).value||'';
  snRender();
}

function snSetFilter(f, btn) {
  _snFilter = f;
  document.querySelectorAll('.sn-filter-btn').forEach(function(b){b.classList.remove('active');});
  if(btn) btn.classList.add('active');
  snRender();
}

function snFmtDate(ts) {
  var d=new Date(ts), now=new Date();
  var diff=Math.floor((now-d)/86400000);
  if(diff===0)return 'আজ '+d.getHours()+':'+(d.getMinutes()<10?'0':'')+d.getMinutes();
  if(diff===1)return 'গতকাল';
  if(diff<7)return diff+' দিন আগে';
  return d.getDate()+'/'+(d.getMonth()+1)+'/'+d.getFullYear();
}

function snEsc(str) {
  return (str||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function snCheckMode() {
  snLoad();
  // Clear autofill aggressively
  var clr = function(){
    var si = document.getElementById('sn-search-input');
    if(si && !si._userTyped) { si.value = ''; _snSearch = ''; }
  };
  clr();
  setTimeout(clr, 100);
  setTimeout(clr, 300);
  setTimeout(clr, 600);
  setTimeout(clr, 1000);
}

