// ── Deep Work inline timer — state lives outside the DOM (window._cmDwTimer) on purpose: this
// card gets torn down and rebuilt by cmRenderFeed()/other toggles while a session might be
// running, and a plain interval tied to the old (now-removed) DOM node would silently die.
// cmDwTimerTick() re-queries every .cm-dw-timer-display by class every second instead of
// holding a reference — there can now be more than one (the আজকের কাজ card's Deep Work box AND
// the dedicated Deep Work card both show the same underlying session), and it keeps ticking
// correctly across any number of re-renders of either card in between.
function cmDwFmt(ms){
  var s=Math.floor(ms/1000);
  var m=Math.floor(s/60),sec=s%60;
  return (m<10?'0':'')+m+':'+(sec<10?'0':'')+sec;
}
function cmDwTimerTick(){
  var t=window._cmDwTimer;
  if(!t||!t.running)return;
  var elapsedMs=Date.now()-t.startTs;
  var txt=cmDwFmt(elapsedMs);
  var els=document.querySelectorAll('.cm-dw-timer-display');
  for(var i=0;i<els.length;i++)els[i].textContent=txt;
  // Quick Start presets (cmDwStartPreset) auto-stop-and-save once the chosen duration is hit —
  // reuses the exact same stop path (cmDwTimerToggle's running→stop branch) a manual Session
  // শেষ করো tap would take, so presets and manual timing save identically.
  if(t.presetTarget&&elapsedMs>=t.presetTarget*60000){
    t.presetTarget=null;
    cmDwTimerToggle();
  }
}
window.cmDwTimerToggle=async function(){
  if(!window.sbUser)return;
  if(!window._cmDwTimer)window._cmDwTimer={running:false,startTs:null,tickInterval:null};
  var t=window._cmDwTimer;
  if(!t.running){
    t.running=true;
    t.startTs=Date.now();
    t.presetTarget=null; // a manual start (not a preset button) always runs open-ended
    clearInterval(t.tickInterval);
    t.tickInterval=setInterval(cmDwTimerTick,1000);
    var card=document.getElementById('cm-feed-actnow-card');
    if(card){card.remove();await cmInjectFeedActNowCard();}
    if(typeof cmRefreshFeedDeepWorkCard==='function')cmRefreshFeedDeepWorkCard();
  }else{
    var minutes=Math.round((Date.now()-t.startTs)/60000);
    t.running=false;
    clearInterval(t.tickInterval);
    t.tickInterval=null;
    if(minutes>=1){
      try{
        var today=new Date().toISOString().split('T')[0];
        // Real columns only — deepwork_sessions has just id/user_id/date/task/duration_mins/
        // created_at; duration/actual/flow_rating/distractions/notes/start_time/start_hour
        // (used by several older call sites in this file) don't exist on the table at all.
        await _sb.from('deepwork_sessions').insert({id:crypto.randomUUID(),user_id:sbUser.id,date:today,duration_mins:minutes,task:''});
        if(typeof cmToast==='function')cmToast('মাশাআল্লাহ! '+minutes+' মিনিট Deep Work হলো ✓');
      }catch(e){ if(typeof cmToast==='function')cmToast('Session সেভ করা যায়নি।'); }
    }
    var card2=document.getElementById('cm-feed-actnow-card');
    if(card2){card2.remove();await cmInjectFeedActNowCard();}
    if(typeof cmLoadToolCarousel==='function')cmLoadToolCarousel();
    if(typeof cmRefreshFeedDeepWorkCard==='function')cmRefreshFeedDeepWorkCard();
  }
};
// Quick Start — one-tap fixed-duration session (25/50 min), auto-saves when the time is up
// instead of requiring a manual stop. This is the "lower the friction even further" action box
// from the plan: a plain Start/Stop timer still asks the user to remember to come back and
// stop it; a preset removes that decision entirely.
window.cmDwStartPreset=async function(mins){
  if(!window.sbUser)return;
  if(!window._cmDwTimer)window._cmDwTimer={running:false,startTs:null,tickInterval:null};
  var t=window._cmDwTimer;
  if(t.running)return; // already running (manual or another preset) — don't stomp on it
  t.running=true;
  t.startTs=Date.now();
  t.presetTarget=mins;
  clearInterval(t.tickInterval);
  t.tickInterval=setInterval(cmDwTimerTick,1000);
  if(typeof cmToast==='function')cmToast(mins+' মিনিটের Session শুরু হলো — শেষ হলে নিজে থেকেই সেভ হবে');
  var card=document.getElementById('cm-feed-actnow-card');
  if(card){card.remove();await cmInjectFeedActNowCard();}
  if(typeof cmRefreshFeedDeepWorkCard==='function')cmRefreshFeedDeepWorkCard();
};

// ── Deep Work — dedicated feed card. Action-first per the plan: the first two boxes are
// always something to DO right now (timer, quick-start presets); সপ্তাহ/Streak sit last and
// are pure summary, not the focus.
async function cmInjectFeedDeepWorkCard(){
  var feed=document.getElementById('cm-feed');
  if(!feed||typeof _sb==='undefined'||!window.sbUser||document.getElementById('cm-feed-dw-card'))return;
  if(feed._cmDwCardInjecting)return;
  feed._cmDwCardInjecting=true;
  var posts=feed.querySelectorAll('.cm-post[data-post-id]');
  if(posts.length<1){feed._cmDwCardInjecting=false;return;}
  try{
    var today=new Date().toISOString().split('T')[0];
    var dRes=await _sb.from('deepwork_sessions').select('duration_mins,date').eq('user_id',sbUser.id).gte('date',new Date(Date.now()-6*86400000).toISOString().split('T')[0]);
    var allWeek=dRes.data||[];
    var todayMin=allWeek.filter(function(r){return r.date===today;}).reduce(function(s,r){return s+(r.duration_mins||0);},0);
    var weekTotal=allWeek.reduce(function(s,r){return s+(r.duration_mins||0);},0);
    var weekAvg=Math.round(weekTotal/7*10)/10;
    var dSetRes=await _sb.from('deepwork_settings').select('daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var goal=(dSetRes.data&&dSetRes.data.daily_goal)||120;
    // Streak: consecutive days (today backward) meeting the goal, same rule as the Quran card —
    // today only "counts" toward the streak once its own goal is actually met.
    var byDate={};
    allWeek.forEach(function(r){byDate[r.date]=(byDate[r.date]||0)+(r.duration_mins||0);});
    var streak=0;
    var checkDate=new Date();
    if(todayMin<goal)checkDate.setDate(checkDate.getDate()-1);
    while(true){
      var ds=checkDate.toISOString().split('T')[0];
      if((byDate[ds]||0)>=goal){streak++;checkDate.setDate(checkDate.getDate()-1);}
      else break;
    }
    if(document.getElementById('cm-feed-dw-card'))return;
    var t=window._cmDwTimer;
    var isRunning=t&&t.running;
    var card=document.createElement('div');
    card.id='cm-feed-dw-card';
    card.className='cm-card';
    card.style.cssText='margin-bottom:10px;border-radius:16px;padding:16px 0 16px 16px;overflow:hidden;font-family:\'Hind Siliguri\',sans-serif';
    card.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--ct);margin-bottom:12px;padding-right:16px;display:flex;align-items:center;gap:6px"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/></svg> Deep Work</div>'
      +'<div id="cm-feed-dw-row" style="display:flex;gap:12px;overflow-x:auto;padding-right:16px;padding-bottom:2px;scrollbar-width:none">'
      // Box 1 — Timer (Act Now, primary)
      +'<div style="flex-shrink:0;width:180px;padding:16px;border-radius:16px;background:linear-gradient(160deg,#8B5CF614,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:11px;font-weight:700;color:#8B5CF6;text-transform:uppercase;letter-spacing:.3px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--cl)">Timer</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px">'
      +'<div class="cm-dw-timer-display" style="font-size:26px;font-weight:800;color:var(--ct);font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">'+(isRunning?cmDwFmt(Date.now()-t.startTs):'00:00')+'</div>'
      +'<div style="font-size:11px;color:var(--ct2)">'+(isRunning?'চলছে…':'আজ '+(Math.round(todayMin/6)/10)+'h হয়েছে')+'</div>'
      +'</div>'
      +'<button onclick="cmDwTimerToggle()" style="margin-top:auto;padding:8px 0;border-radius:999px;border:none;background:'+(isRunning?'linear-gradient(90deg,#EF4444,#F87171)':'linear-gradient(90deg,#8B5CF6,#A78BFA)')+';color:#fff;font-weight:700;cursor:pointer;font-size:12.5px">'+(isRunning?'⏹ Session শেষ করো':'▶ Session শুরু করো')+'</button>'
      +'</div>'
      // Box 2 — Quick Start presets (Act Now, secondary — even lower friction)
      +'<div style="flex-shrink:0;width:170px;padding:16px;border-radius:16px;background:linear-gradient(160deg,#8B5CF614,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:11px;font-weight:700;color:#8B5CF6;text-transform:uppercase;letter-spacing:.3px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--cl)">Quick Start</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;justify-content:center;gap:8px">'
      +'<button '+(isRunning?'disabled':'')+' onclick="cmDwStartPreset(25)" style="padding:9px 0;border-radius:10px;border:1px solid #8B5CF660;background:transparent;color:#8B5CF6;font-weight:700;cursor:'+(isRunning?'default':'pointer')+';font-size:12.5px;opacity:'+(isRunning?'.5':'1')+'">২৫ মিনিট</button>'
      +'<button '+(isRunning?'disabled':'')+' onclick="cmDwStartPreset(50)" style="padding:9px 0;border-radius:10px;border:none;background:linear-gradient(90deg,#8B5CF6,#A78BFA);color:#fff;font-weight:700;cursor:'+(isRunning?'default':'pointer')+';font-size:12.5px;opacity:'+(isRunning?'.5':'1')+'">৫০ মিনিট</button>'
      +'</div></div>'
      // Box 3 — সপ্তাহ (summary, last)
      +'<div style="flex-shrink:0;width:150px;padding:16px;border-radius:16px;background:linear-gradient(160deg,#8B5CF614,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:11px;font-weight:700;color:#8B5CF6;text-transform:uppercase;letter-spacing:.3px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--cl)">সপ্তাহ</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px">'
      +'<div style="font-size:22px;font-weight:800;color:var(--ct);font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">'+(Math.round(weekTotal/6)/10)+'h</div>'
      +'<div style="font-size:10.5px;color:var(--ct2)">গড় '+(Math.round(weekAvg/6)/10)+'h/দিন</div>'
      +'</div></div>'
      // Box 4 — Streak (summary, last)
      +'<div style="flex-shrink:0;width:130px;padding:16px;border-radius:16px;background:linear-gradient(160deg,#F59E0B14,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:11px;font-weight:700;color:#F59E0B;text-transform:uppercase;letter-spacing:.3px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--cl)">Streak</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px">'
      +'<div style="font-size:22px;font-weight:800;color:#F59E0B;font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">🔥 '+streak+'</div>'
      +'</div></div>'
      +'</div>';
    var livePosts8=feed.querySelectorAll('.cm-post[data-post-id]');
    if(!livePosts8.length){feed._cmDwCardInjecting=false;return;}
    var afterEl8=livePosts8[Math.min(5,livePosts8.length-1)];
    afterEl8.parentNode.insertBefore(card,afterEl8.nextSibling);
    var dwRowEl=document.getElementById('cm-feed-dw-row');
    if(dwRowEl&&typeof cmEnableMouseScroll==='function')cmEnableMouseScroll(dwRowEl);
  }catch(e){}
  finally{ feed._cmDwCardInjecting=false; }
}
window.cmRefreshFeedDeepWorkCard=async function(){
  var card=document.getElementById('cm-feed-dw-card');
  if(!card)return;
  card.remove();
  await cmInjectFeedDeepWorkCard();
};

window.cmFeedActNowLogSleep=async function(){
  if(!window.sbUser)return;
  var inp=document.getElementById('cm-feed-sleep-inp');
  var hours=inp?parseFloat(inp.value):NaN;
  if(!hours||hours<=0)return;
  try{
    var mins=Math.round(hours*60);
    var yesterday=new Date(Date.now()-86400000).toISOString().split('T')[0];
    // st/wt (sleep-time/wake-time) are approximated — this quick-log UI only collects total
    // hours, not exact clock times, unlike the full Sleep Tracker page's own entry form.
    await _sb.from('adult_sleep_logs').upsert({user_id:sbUser.id,date_key:yesterday,st:'',wt:'',dur:mins,q:3,tags:[]},{onConflict:'user_id,date_key'});
    if(typeof cmToast==='function')cmToast('মাশাআল্লাহ! ঘুম log হয়েছে ✓');
    var card=document.getElementById('cm-feed-actnow-card');
    if(card){card.remove();await cmInjectFeedActNowCard();}
    if(typeof cmLoadToolCarousel==='function')cmLoadToolCarousel();
  }catch(e){ if(typeof cmToast==='function')cmToast('Log করা যায়নি।'); }
};

// ── To-Do — dedicated feed card (separate from "আজকের কাজ", per plan: this tool gets its own
// card, not folded into the shared one). Connects directly to the REAL To-Do page's own table
// (todo_tasks — same one pages/todo.html's tdLoadFromSb/tdUpsertTaskSb/tdToggleDone use), not a
// separate feed-only table, so a task written here shows up on the actual To-Do page and vice
// versa. Box 1: plan tomorrow (3 quick-add slots). Box 2: today's checklist (Act Now).
async function cmInjectFeedTodoCard(){
  var feed=document.getElementById('cm-feed');
  if(!feed||typeof _sb==='undefined'||!window.sbUser||document.getElementById('cm-feed-todo-card'))return;
  if(feed._cmTodoInjecting)return;
  feed._cmTodoInjecting=true;
  var posts=feed.querySelectorAll('.cm-post[data-post-id]');
  // TEMP PREVIEW: same reasoning as the other feed-injected cards — show regardless of real
  // post count for now, real "when to show" threshold logic comes later.
  if(posts.length<1){feed._cmTodoInjecting=false;return;}
  try{
    var today=new Date().toISOString().split('T')[0];
    var tomorrow=new Date(Date.now()+86400000).toISOString().split('T')[0];
    // Real column is due_date (not due), and status is a simple pending/done (not the
    // backlog/inprogress/review/done the full To-Do page's own code assumes — that page has
    // the same real-vs-assumed schema gap, just not something to fix here).
    var tRes=await _sb.from('todo_tasks').select('id,title,status,due_date').eq('user_id',sbUser.id).eq('due_date',today);
    var todayTasks=tRes.data||[];
    var tmRes=await _sb.from('todo_tasks').select('id,title,status,due_date').eq('user_id',sbUser.id).eq('due_date',tomorrow);
    var tomorrowTasks=tmRes.data||[];
    if(document.getElementById('cm-feed-todo-card'))return;
    var todayDone=todayTasks.filter(function(t){return t.status==='done';}).length;
    var card=document.createElement('div');
    card.id='cm-feed-todo-card';
    card.className='cm-card';
    card.style.cssText='margin-bottom:10px;border-radius:16px;padding:16px 0 16px 16px;overflow:hidden;font-family:\'Hind Siliguri\',sans-serif';
    var todayRows=todayTasks.map(function(t){
      var isDone=t.status==='done';
      return '<div onclick="cmTodoToggle(\''+t.id+'\','+(isDone?'true':'false')+')" style="display:flex;align-items:center;gap:9px;padding:7px 6px;margin:0 -6px;border-radius:9px;cursor:pointer;transition:background .12s" onmouseenter="this.style.background=\'rgba(139,92,246,.08)\'" onmouseleave="this.style.background=\'\'">'
        +'<div style="width:19px;height:19px;border-radius:6px;border:2px solid '+(isDone?'#8B5CF6':'var(--cl)')+';background:'+(isDone?'#8B5CF6':'transparent')+';display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:.15s">'+(isDone?'<svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>':'')+'</div>'
        +'<div style="flex:1;font-size:12.5px;font-weight:600;color:'+(isDone?'var(--ct2)':'var(--ct)')+';text-decoration:'+(isDone?'line-through':'none')+';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escapeHtml(t.title||'Task')+'</div>'
        +'</div>';
    }).join('');
    var todayEmpty='<div style="text-align:center;padding:10px 0 4px;color:var(--ct2)">'
      +'<div style="font-size:22px;margin-bottom:4px">📋</div>'
      +'<div style="font-size:12px">আজকের জন্য কোনো Task নেই</div></div>';
    var tmRows=[0,1,2].map(function(i){
      var t=tomorrowTasks[i];
      return '<input class="cm-todo-tm-inp" data-idx="'+i+'" placeholder="'+(i+1)+'. কাজ লিখো…" autocomplete="off" value="'+(t?escapeHtml(t.title||''):'')+'" '+(t?'data-id="'+t.id+'"':'')+' style="width:100%;padding:7px 10px;border-radius:10px;border:1px solid var(--cl);background:rgba(0,0,0,.15);color:var(--ct);font-size:12px;margin-bottom:6px;outline:none" onkeydown="if(event.key===\'Enter\')this.blur()" onblur="cmTodoSaveTomorrow('+i+')">';
    }).join('');
    card.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--ct);margin-bottom:12px;padding-right:16px;display:flex;align-items:center;gap:6px"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg> To-Do</div>'
      +'<div id="cm-feed-todo-row" style="display:flex;gap:12px;overflow-x:auto;padding-right:16px;padding-bottom:2px;scrollbar-width:none">'
      // Box 1 — Plan tomorrow (implementation-intention nudge: "ঘুমানোর আগে")
      +'<div style="flex-shrink:0;width:210px;padding:14px;border-radius:16px;background:linear-gradient(160deg,#8B5CF614,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:11px;font-weight:700;color:#8B5CF6;text-transform:uppercase;letter-spacing:.3px;margin-bottom:8px;padding-bottom:8px;border-bottom:1px solid var(--cl)">📝 আগামীকালের কাজ</div>'
      +'<div style="font-size:11px;color:var(--ct2);margin-bottom:8px">ঘুমানোর আগে ৩টি কাজ লিখে ফেলো</div>'
      +tmRows
      +'</div>'
      // Box 2 — Today's checklist (Act Now)
      +'<div style="flex-shrink:0;width:200px;padding:14px;border-radius:16px;background:linear-gradient(160deg,#8B5CF614,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;padding-bottom:8px;border-bottom:1px solid var(--cl)">'
      +'<div style="font-size:11px;font-weight:700;color:#8B5CF6;text-transform:uppercase;letter-spacing:.3px;display:flex;align-items:center;gap:5px">✅ আজকের কাজ</div>'
      +(todayTasks.length?'<div style="font-size:11px;font-weight:700;color:#8B5CF6;background:#8B5CF622;border-radius:20px;padding:2px 8px">'+todayDone+'/'+todayTasks.length+'</div>':'')
      +'</div>'
      +(todayRows||todayEmpty)
      +'</div>'
      // Box 3 — Score (Reflect, no action)
      +(function(){
        var pct=todayTasks.length?Math.round(todayDone/todayTasks.length*100):null;
        var color=pct===null?'var(--ct2)':pct>=85?'#10B981':pct>=50?'#F59E0B':'#EF4444';
        return '<div style="flex-shrink:0;width:180px;padding:14px;border-radius:16px;background:linear-gradient(160deg,'+(pct===null?'#8B5CF6':color)+'14,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
          +'<div style="font-size:11px;font-weight:700;color:#8B5CF6;text-transform:uppercase;letter-spacing:.3px;margin-bottom:8px;padding-bottom:8px;border-bottom:1px solid var(--cl)">📊 আজকের Score</div>'
          +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px">'
          +'<div style="font-size:28px;font-weight:800;color:'+color+';font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">'+(pct===null?'—':pct+'%')+'</div>'
          +'<div style="font-size:11px;color:var(--ct2)">'+(pct===null?'আজ কোনো Task নেই':todayDone+'/'+todayTasks.length+' সম্পন্ন')+'</div>'
          +'</div></div>';
      })()
      +'</div>'
      +'</div>';
    var livePosts5=feed.querySelectorAll('.cm-post[data-post-id]');
    if(!livePosts5.length){feed._cmTodoInjecting=false;return;}
    var afterEl5=livePosts5[Math.min(2,livePosts5.length-1)];
    afterEl5.parentNode.insertBefore(card,afterEl5.nextSibling);
    var todoRowEl=document.getElementById('cm-feed-todo-row');
    if(todoRowEl&&typeof cmEnableMouseScroll==='function')cmEnableMouseScroll(todoRowEl);
  }catch(e){}
  finally{ feed._cmTodoInjecting=false; }
}
window.cmTodoToggle=async function(id,wasDone){
  if(!window.sbUser)return;
  try{
    await _sb.from('todo_tasks').update({status:wasDone?'pending':'done'}).eq('id',id);
    if(typeof cmToast==='function')cmToast(wasDone?'':'মাশাআল্লাহ! ✓');
    var card=document.getElementById('cm-feed-todo-card');
    if(card){card.remove();await cmInjectFeedTodoCard();}
  }catch(e){}
};
window.cmTodoSaveTomorrow=async function(idx){
  var inp=document.querySelector('.cm-todo-tm-inp[data-idx="'+idx+'"]');
  if(!inp||!window.sbUser)return;
  var title=inp.value.trim();
  var existingId=inp.getAttribute('data-id');
  if(!title){
    if(existingId){ try{await _sb.from('todo_tasks').delete().eq('id',existingId);}catch(e){} }
    return;
  }
  try{
    var tomorrow=new Date(Date.now()+86400000).toISOString().split('T')[0];
    if(existingId){
      await _sb.from('todo_tasks').update({title:title}).eq('id',existingId);
    }else{
      var res=await _sb.from('todo_tasks').insert({id:crypto.randomUUID(),user_id:sbUser.id,title:title,due_date:tomorrow,status:'pending',created_at:new Date().toISOString()}).select();
      var newId=res.data&&res.data[0]&&res.data[0].id;
      if(newId)inp.setAttribute('data-id',newId);
    }
  }catch(e){ if(typeof cmToast==='function')cmToast('Save করা যায়নি।'); }
};

// ── Quran — dedicated feed card (its own card, like To-Do, not folded into "আজকের কাজ").
// Box 1 আজকে (Act Now), Box 2 সপ্তাহ (Reflect, 7-day total+avg), Box 3 Streak (Reflect,
// consecutive days meeting the daily goal) — all computed from adult_quran_data.tilawat, the
// same JSON-by-date field the Quran Tracker page and the আজকের কাজ card's Quran box both use.
async function cmInjectFeedQuranCard(){
  var feed=document.getElementById('cm-feed');
  if(!feed||typeof _sb==='undefined'||!window.sbUser||document.getElementById('cm-feed-quran-card'))return;
  if(feed._cmQuranInjecting)return;
  feed._cmQuranInjecting=true;
  var posts=feed.querySelectorAll('.cm-post[data-post-id]');
  if(posts.length<1){feed._cmQuranInjecting=false;return;}
  try{
    var today=new Date().toISOString().split('T')[0];
    var qRes=await _sb.from('adult_quran_data').select('tilawat,daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var qData=qRes.data;
    var tilawat=(qData&&qData.tilawat)||{};
    var goal=(qData&&qData.daily_goal)||2;
    var todayPages=tilawat[today]||0;
    if(document.getElementById('cm-feed-quran-card'))return;
    // Week: sum + average of the last 7 days (today included).
    var weekTotal=0;
    for(var i=0;i<7;i++){
      var d=new Date(Date.now()-i*86400000).toISOString().split('T')[0];
      weekTotal+=tilawat[d]||0;
    }
    var weekAvg=Math.round(weekTotal/7*10)/10;
    // Streak: walk backwards from today, counting consecutive days meeting the goal. Today
    // itself only counts once its goal is actually met (an unmet "in-progress" today doesn't
    // break a streak built on prior days, so check yesterday-backwards if today isn't done yet).
    var streak=0;
    var checkDate=new Date();
    if(todayPages<goal)checkDate.setDate(checkDate.getDate()-1);
    while(true){
      var ds=checkDate.toISOString().split('T')[0];
      if((tilawat[ds]||0)>=goal){streak++;checkDate.setDate(checkDate.getDate()-1);}
      else break;
    }
    var card=document.createElement('div');
    card.id='cm-feed-quran-card';
    card.className='cm-card';
    card.style.cssText='margin-bottom:10px;border-radius:16px;padding:16px 0 16px 16px;overflow:hidden;font-family:\'Hind Siliguri\',sans-serif';
    card.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--ct);margin-bottom:12px;padding-right:16px;display:flex;align-items:center;gap:6px"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg> Daily '+goal+' পেজ কোরআন পড়া</div>'
      +'<div id="cm-feed-quran-row" style="display:flex;gap:12px;overflow-x:auto;padding-right:16px;padding-bottom:2px;scrollbar-width:none">'
      // Box 1 — আজকে (Act Now)
      +'<div style="flex-shrink:0;width:190px;padding:14px;border-radius:16px;background:linear-gradient(160deg,#3B82F614,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;padding-bottom:8px;border-bottom:1px solid var(--cl)">'
      +'<div style="font-size:11px;font-weight:700;color:#3B82F6;text-transform:uppercase;letter-spacing:.3px">আজকে</div>'
      +'<div style="font-size:11px;font-weight:700;color:#3B82F6;background:#3B82F622;border-radius:20px;padding:2px 8px">'+todayPages+'/'+goal+'</div>'
      +'</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:6px 0">'
      +'<div style="font-size:30px;font-weight:800;color:var(--ct);font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">'+todayPages+'</div>'
      +'<div style="font-size:11px;color:var(--ct2)">পেজ পড়া হয়েছে</div>'
      +'</div>'
      +'<button onclick="cmToolQuranAddPage()" style="margin-top:auto;padding:8px 0;border-radius:999px;border:none;background:linear-gradient(90deg,#3B82F6,#60A5FA);color:#fff;font-weight:700;cursor:pointer;font-size:12.5px">+ ১ পেজ যোগ করো</button>'
      +'</div>'
      // Box 2 — সপ্তাহ (Reflect)
      +'<div style="flex-shrink:0;width:180px;padding:14px;border-radius:16px;background:linear-gradient(160deg,#3B82F614,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:11px;font-weight:700;color:#3B82F6;text-transform:uppercase;letter-spacing:.3px;margin-bottom:8px;padding-bottom:8px;border-bottom:1px solid var(--cl)">সপ্তাহ</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px">'
      +'<div style="font-size:26px;font-weight:800;color:var(--ct);font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">'+weekTotal+'</div>'
      +'<div style="font-size:11px;color:var(--ct2)">মোট পেজ (৭ দিন)</div>'
      +'<div style="font-size:11px;color:var(--ct2);margin-top:4px">গড় '+weekAvg+' পেজ/দিন</div>'
      +'</div></div>'
      // Box 3 — Streak (Reflect)
      +'<div style="flex-shrink:0;width:150px;padding:14px;border-radius:16px;background:linear-gradient(160deg,#F59E0B14,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:11px;font-weight:700;color:#F59E0B;text-transform:uppercase;letter-spacing:.3px;margin-bottom:8px;padding-bottom:8px;border-bottom:1px solid var(--cl)">Streak</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px">'
      +'<div style="font-size:26px;font-weight:800;color:#F59E0B;font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">🔥 '+streak+'</div>'
      +'<div style="font-size:11px;color:var(--ct2)">দিন ধারাবাহিক</div>'
      +'</div></div>'
      +'</div>';
    var livePosts6=feed.querySelectorAll('.cm-post[data-post-id]');
    if(!livePosts6.length){feed._cmQuranInjecting=false;return;}
    var afterEl6=livePosts6[Math.min(3,livePosts6.length-1)];
    afterEl6.parentNode.insertBefore(card,afterEl6.nextSibling);
    var quranRowEl=document.getElementById('cm-feed-quran-row');
    if(quranRowEl&&typeof cmEnableMouseScroll==='function')cmEnableMouseScroll(quranRowEl);
  }catch(e){}
  finally{ feed._cmQuranInjecting=false; }
}
window.cmRefreshFeedQuranCard=async function(){
  var card=document.getElementById('cm-feed-quran-card');
  if(!card)return;
  card.remove();
  await cmInjectFeedQuranCard();
};

// ── Screen Time Control — dedicated feed card. Reads/writes the SAME localStorage key
// (rz_adult_screentime_v1) as the full "Adult Screen Time — Digital Wellness Command Center"
// page, so a session logged here shows up there too. That page's own loadData/saveData are
// closures private to its IIFE, so this reads the key directly instead — same JSON shape
// ({sessions:[{date,app,minutes,category,...}], limit}), just accessed from outside.
// Per-app target limits are a NEW field this card adds (appLimits:{Facebook:60,...}) — the
// existing page only ever had one overall daily limit, not per-app ones.
var CM_ST_KEY='rz_adult_screentime_v1';
function cmStLoad(){
  try{ return JSON.parse(localStorage.getItem(CM_ST_KEY))||{sessions:[],limit:120,appLimits:{}}; }
  catch(e){ return {sessions:[],limit:120,appLimits:{}}; }
}
function cmStSave(d){ try{localStorage.setItem(CM_ST_KEY,JSON.stringify(d));}catch(e){} }
function cmStTodayAppMins(d,appName){
  var t=new Date().toISOString().slice(0,10);
  return d.sessions.filter(function(s){return s.date===t&&(s.app||'').toLowerCase()===appName.toLowerCase();}).reduce(function(a,s){return a+(s.minutes||0);},0);
}
function cmStTodayTotalMins(d){
  var t=new Date().toISOString().slice(0,10);
  return d.sessions.filter(function(s){return s.date===t;}).reduce(function(a,s){return a+(s.minutes||0);},0);
}
async function cmInjectFeedScreenTimeCard(){
  var feed=document.getElementById('cm-feed');
  if(!feed||!window.sbUser||document.getElementById('cm-feed-st-card'))return;
  if(feed._cmStInjecting)return;
  feed._cmStInjecting=true;
  var posts=feed.querySelectorAll('.cm-post[data-post-id]');
  if(posts.length<1){feed._cmStInjecting=false;return;}
  try{
    var d=cmStLoad();
    if(!d.appLimits)d.appLimits={};
    var fbMins=cmStTodayAppMins(d,'Facebook');
    var ytMins=cmStTodayAppMins(d,'YouTube');
    var fbLimit=d.appLimits.Facebook||60;
    var ytLimit=d.appLimits.YouTube||60;
    var totalMins=cmStTodayTotalMins(d);
    var totalLimit=d.limit||120;
    if(document.getElementById('cm-feed-st-card'))return;
    function fmtM(m){ if(m<60)return m+'মি'; return Math.floor(m/60)+'ঘ'+(m%60?' '+(m%60)+'মি':''); }
    // Real brand marks (fixed brand colors, not currentColor) instead of a plain text label —
    // instantly recognizable at a glance, matching how the actual apps present themselves.
    var APP_ICONS={
      Facebook:'<svg width="20" height="20" viewBox="0 0 36 36"><circle cx="18" cy="18" r="18" fill="#1877F2"/><path fill="#fff" d="M25 18.06C25 13.6 21.42 10 17 10s-8 3.6-8 8.06c0 4.02 2.93 7.36 6.75 7.94v-5.61h-2.03v-2.33h2.03v-1.78c0-2.01 1.2-3.13 3.02-3.13.87 0 1.79.16 1.79.16v1.98h-1.01c-1 0-1.31.62-1.31 1.26v1.51h2.23l-.36 2.33h-1.87V26c3.82-.58 6.75-3.92 6.75-7.94z"/></svg>',
      YouTube:'<svg width="22" height="20" viewBox="0 0 28 20"><path fill="#FF0000" d="M27.4 3.1S27.1 1 26.2 0.1C25 -0.9 23.8 -0.9 23.2 -1H23.2C19.5 -1.3 14 -1.3 14 -1.3H14S8.5 -1.3 4.8 -1C4.2 -0.9 3 -0.9 1.8 0.1 0.9 1 0.6 3.1 0.6 3.1S0.3 5.6 0.3 8V10.1C0.3 12.5 0.6 15 0.6 15S0.9 17.1 1.8 18C3 19 4.5 19 5.1 19.1 7.5 19.3 14 19.4 14 19.4S19.5 19.4 23.2 19.1C23.8 19 25 19 26.2 18 27.1 17.1 27.4 15 27.4 15S27.7 12.5 27.7 10.1V8C27.7 5.6 27.4 3.1 27.4 3.1Z" transform="translate(0,1)"/><path fill="#fff" d="M11.2 13.8V5.3L18.6 9.5Z"/></svg>'
    };
    function appBox(name,label,color,mins,limit){
      var over=mins>limit;
      var pct=Math.min(100,Math.round(mins/limit*100));
      return '<div style="flex-shrink:0;width:200px;padding:16px;border-radius:16px;background:linear-gradient(160deg,'+color+'14,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
        +'<div style="display:flex;align-items:center;gap:7px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--cl)">'+(APP_ICONS[name]||'')+'<div style="font-size:12px;font-weight:700;color:'+color+';text-transform:uppercase;letter-spacing:.3px">'+label+'</div></div>'
        +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:4px 0">'
        +'<div style="font-size:26px;font-weight:800;color:'+(over?'#EF4444':'var(--ct)')+';font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">'+fmtM(mins)+'</div>'
        +'<div id="cm-st-limit-'+name+'" style="font-size:11px;color:var(--ct2);cursor:pointer;text-decoration:underline dotted" onclick="cmStEditLimit(\''+name+'\')">target '+fmtM(limit)+'</div>'
        +'</div>'
        +'<div style="height:5px;background:var(--cl);border-radius:4px;overflow:hidden;margin-bottom:10px"><div style="width:'+pct+'%;height:100%;background:'+(over?'#EF4444':color)+';border-radius:4px"></div></div>'
        +'<button onclick="cmStLogMinutes(\''+name+'\')" style="padding:8px 0;border-radius:999px;border:none;background:'+color+';color:#fff;font-weight:700;cursor:pointer;font-size:12.5px">+১৫ মিনিট</button>'
        +'</div>';
    }
    var card=document.createElement('div');
    card.id='cm-feed-st-card';
    card.className='cm-card';
    card.style.cssText='margin-bottom:10px;border-radius:16px;padding:16px 0 16px 16px;overflow:hidden;font-family:\'Hind Siliguri\',sans-serif';
    var totalColor=totalMins>totalLimit?'#EF4444':totalMins>totalLimit*0.75?'#F59E0B':'#10B981';
    card.innerHTML='<div style="font-size:13px;font-weight:700;color:var(--ct);margin-bottom:12px;padding-right:16px;display:flex;align-items:center;justify-content:space-between">'
      +'<span style="display:flex;align-items:center;gap:6px"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="5" y="2" width="14" height="20" rx="2"/><line x1="12" y1="18" x2="12" y2="18"/></svg> Screen Time Control</span>'
      +'<span onclick="switchTab(\'screentime\')" style="font-size:11px;font-weight:700;color:var(--cgold);cursor:pointer">সব App দেখো ›</span>'
      +'</div>'
      +'<div id="cm-feed-st-row" style="display:flex;gap:12px;overflow-x:auto;padding-right:16px;padding-bottom:2px;scrollbar-width:none">'
      +appBox('Facebook','Facebook','#3B82F6',fbMins,fbLimit)
      +appBox('YouTube','YouTube','#EF4444',ytMins,ytLimit)
      +'<div style="flex-shrink:0;width:180px;padding:16px;border-radius:16px;background:linear-gradient(160deg,'+totalColor+'14,transparent 60%),var(--cc);border:1px solid var(--cl);box-shadow:0 6px 10px -6px rgba(0,0,0,.35);display:flex;flex-direction:column;box-sizing:border-box">'
      +'<div style="font-size:12px;font-weight:700;color:'+totalColor+';text-transform:uppercase;letter-spacing:.3px;margin-bottom:10px;padding-bottom:10px;border-bottom:1px solid var(--cl)">মোট আজকে</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:4px 0">'
      +'<div style="font-size:26px;font-weight:800;color:'+totalColor+';font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1">'+fmtM(totalMins)+'</div>'
      +'<div style="font-size:11px;color:var(--ct2)">লিমিট '+fmtM(totalLimit)+'</div>'
      +'</div></div>'
      +'</div>';
    var livePosts7=feed.querySelectorAll('.cm-post[data-post-id]');
    if(!livePosts7.length){feed._cmStInjecting=false;return;}
    var afterEl7=livePosts7[Math.min(4,livePosts7.length-1)];
    afterEl7.parentNode.insertBefore(card,afterEl7.nextSibling);
    var stRowEl=document.getElementById('cm-feed-st-row');
    if(stRowEl&&typeof cmEnableMouseScroll==='function')cmEnableMouseScroll(stRowEl);
  }catch(e){}
  finally{ feed._cmStInjecting=false; }
}
window.cmStLogMinutes=function(appName){
  var d=cmStLoad();
  d.sessions.push({id:Date.now(),date:new Date().toISOString().slice(0,10),category:'Social',app:appName,minutes:15,note:'',ts:Date.now()});
  cmStSave(d);
  if(typeof cmToast==='function')cmToast(appName+'-এ ১৫ মিনিট log হলো');
  var card=document.getElementById('cm-feed-st-card');
  if(card){card.remove();cmInjectFeedScreenTimeCard();}
  if(typeof window.rzRenderAdultScreentime==='function')window.rzRenderAdultScreentime();
};
window.cmStEditLimit=function(appName){
  var d=cmStLoad();
  if(!d.appLimits)d.appLimits={};
  var current=d.appLimits[appName]||60;
  var input=prompt(appName+'-এর জন্য দৈনিক target (মিনিটে) লিখো:',current);
  if(input===null)return;
  var mins=parseInt(input);
  if(!mins||mins<=0)return;
  d.appLimits[appName]=mins;
  cmStSave(d);
  var card=document.getElementById('cm-feed-st-card');
  if(card){card.remove();cmInjectFeedScreenTimeCard();}
};

// cmToolHabitToggle/cmToolNamazToggle refresh this card too — see their own definitions further
// down in the file (near cmLoadToolCarousel), which call cmRefreshFeedActNowCard() directly
// after every toggle, rather than monkey-patching here (this code runs before those functions
// are even defined, so wrapping window.cmToolHabitToggle at this point would have captured
// `undefined`).
window.cmRefreshFeedActNowCard=async function(){
  var card=document.getElementById('cm-feed-actnow-card');
  if(!card)return;
  card.remove();
  await cmInjectFeedActNowCard();
};

window.cmSendSuggestedRequest=async function(userId,name,btn){
  if(!window.sbUser)return;
  if(btn){btn.disabled=true;btn.textContent='...';}
  try{
    var res=await _sb.from('rizer_requests').upsert({from_user_id:sbUser.id,to_user_id:userId,status:'pending'},{onConflict:'from_user_id,to_user_id',ignoreDuplicates:false}).select();
    var myName=(window.sbProfile&&window.sbProfile.name)||'একজন Rizer';
    var reqId=(res.data&&res.data[0]&&res.data[0].id)||null;
    await _sb.from('notifications').insert({user_id:userId,type:'rise_request',title:myName+' Connect করতে চায়!',msg:'⚡ তোমার সাথে Rise করতে চায়।',read:false,dot:'#FF8A00',metadata:{from_user_id:sbUser.id,from_name:myName,request_id:reqId}});
    if(btn)btn.textContent='⏳ Pending';
    if(typeof cmToast==='function')cmToast('⚡ '+name+' কে Rise Request পাঠানো হয়েছে!');
  }catch(e){
    if(btn){
      if(e&&e.code==='23505'){btn.textContent='⏳ Pending';}
      else{btn.disabled=false;btn.textContent='Connect';}
    }
  }
};

// Today's Snapshot — real per-user data from each adult tracker table, "today" filtered by
// YYYY-MM-DD (matches the date format every tracker already writes).
function _cmSetSnap(key,label,pct){
  var lbl=document.getElementById('cm-snap-'+key+'-label');
  var bar=document.getElementById('cm-snap-'+key+'-bar');
  if(lbl)lbl.textContent=label;
  if(bar)bar.style.width=Math.max(0,Math.min(100,pct||0))+'%';
}
async function cmLoadTodaySnapshot(){
  if(typeof _sb==='undefined'||!window.sbUser)return;
  var today=new Date().toISOString().split('T')[0];
  try{
    var hRes=await _sb.from('adult_habits').select('done,last_done_date').eq('user_id',sbUser.id);
    var habits=hRes.data||[];
    var doneToday=habits.filter(function(h){return h.done&&h.last_done_date===today;}).length;
    _cmSetSnap('habit',doneToday+'/'+habits.length+' সম্পন্ন',habits.length?Math.round(doneToday/habits.length*100):0);
  }catch(e){}
  try{
    var qRes=await _sb.from('adult_quran_data').select('tilawat,daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var qData=qRes.data;
    var todayPages=(qData&&qData.tilawat&&qData.tilawat[today])||0;
    var goal=(qData&&qData.daily_goal)||2;
    _cmSetSnap('quran',todayPages+'/'+goal+' পেজ',Math.round(todayPages/goal*100));
  }catch(e){}
  try{
    var nRes=await _sb.from('adult_namaz_logs').select('prayer,status,date').eq('user_id',sbUser.id).eq('date',today);
    var doneNamaz=(nRes.data||[]).filter(function(n){return n.status==='completed';}).length;
    _cmSetSnap('namaz',doneNamaz+'/5 ওয়াক্ত',Math.round(doneNamaz/5*100));
  }catch(e){}
  try{
    var dRes=await _sb.from('deepwork_sessions').select('duration_mins,date').eq('user_id',sbUser.id).eq('date',today);
    var dSet=await _sb.from('deepwork_settings').select('daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var mins=(dRes.data||[]).reduce(function(s,d){return s+(d.duration_mins||0);},0);
    var dwGoal=(dSet.data&&dSet.data.daily_goal)||120;
    _cmSetSnap('deepwork',(Math.round(mins/6)/10)+'h / '+(Math.round(dwGoal/6)/10)+'h',Math.round(mins/dwGoal*100));
  }catch(e){}
}

// ── Tool Progress Carousel — Rise Feed personalization Phase 1. Horizontal, real per-tracker
// "today" data (same queries/columns as cmLoadTodaySnapshot, plus Sleep), premium glass cards,
// each tap jumps straight to that tracker instead of the user hunting for it in the sidebar.
async function cmLoadToolCarousel(){
  var wrap=document.getElementById('cm-tool-carousel-wrap');
  var el=document.getElementById('cm-tool-carousel');
  if(!wrap||!el||typeof _sb==='undefined'||!window.sbUser)return;
  var today=new Date().toISOString().split('T')[0];
  var cards=[];
  try{
    var hRes=await _sb.from('adult_habits').select('done,last_done_date').eq('user_id',sbUser.id);
    var habits=hRes.data||[];
    var doneHabit=habits.filter(function(h){return h.done&&h.last_done_date===today;}).length;
    cards.push({tab:'habits',color:'#FF8A00',icon:'<path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"/>',label:'Habit',value:doneHabit+'/'+habits.length,pct:habits.length?Math.round(doneHabit/habits.length*100):0});
  }catch(e){}
  try{
    var qRes=await _sb.from('adult_quran_data').select('tilawat,daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var qData=qRes.data;
    var todayPages=(qData&&qData.tilawat&&qData.tilawat[today])||0;
    var qGoal=(qData&&qData.daily_goal)||2;
    cards.push({tab:'quran',color:'#3B82F6',icon:'<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',label:'Quran',value:todayPages+'/'+qGoal+' পেজ',pct:Math.round(todayPages/qGoal*100)});
  }catch(e){}
  try{
    var nRes=await _sb.from('adult_namaz_logs').select('prayer,status,date').eq('user_id',sbUser.id).eq('date',today);
    var doneNamaz=(nRes.data||[]).filter(function(n){return n.status==='completed';}).length;
    cards.push({tab:'namaz',color:'#10B981',icon:'<path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9z"/>',label:'Namaz',value:doneNamaz+'/5',pct:Math.round(doneNamaz/5*100)});
  }catch(e){}
  try{
    var dRes=await _sb.from('deepwork_sessions').select('duration_mins,date').eq('user_id',sbUser.id).eq('date',today);
    var dSet=await _sb.from('deepwork_settings').select('daily_goal').eq('user_id',sbUser.id).maybeSingle();
    var mins=(dRes.data||[]).reduce(function(s,d){return s+(d.duration_mins||0);},0);
    var dwGoal=(dSet.data&&dSet.data.daily_goal)||120;
    cards.push({tab:'deepwork',color:'#8B5CF6',icon:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',label:'Deep Work',value:(Math.round(mins/6)/10)+'h',pct:Math.round(mins/dwGoal*100)});
  }catch(e){}
  try{
    var slRes=await _sb.from('adult_sleep_logs').select('dur').eq('user_id',sbUser.id).eq('date_key',today).maybeSingle();
    var slSet=await _sb.from('adult_sleep_settings').select('goal').eq('user_id',sbUser.id).maybeSingle();
    var slDur=(slRes.data&&slRes.data.dur)||0;
    var slGoal=(slSet.data&&slSet.data.goal)||8;
    cards.push({tab:'sleep',color:'#EF4444',icon:'<path d="M17 18a5 5 0 0 0-10 0"/><line x1="12" y1="9" x2="12" y2="2"/><line x1="4.22" y1="10.22" x2="5.64" y2="11.64"/><line x1="1" y1="18" x2="3" y2="18"/><line x1="21" y1="18" x2="23" y2="18"/><line x1="18.36" y1="11.64" x2="19.78" y2="10.22"/>',label:'Sleep',value:slDur+'h',pct:Math.round(slDur/slGoal*100)});
  }catch(e){}
  if(!cards.length){wrap.style.display='none';return;}
  // Theme-aware via CSS custom properties (var(--cc)/var(--ct)/var(--ct2)/var(--cl), already
  // defined per-theme for #community-page in styles.css), NOT a one-time JS dark-mode check —
  // that approach baked in whichever theme was active at the exact render instant and went
  // stale/wrong if the theme class attached after this ran (or the user toggled theme later).
  // The browser re-resolves CSS vars live, so this always matches the current theme.
  el.innerHTML=cards.map(function(c){
    var pct=Math.max(0,Math.min(100,c.pct||0));
    // Negative spread keeps the shadow hugging the card edge instead of spreading outward —
    // a plain blur (however small) always leaked across the 10px gap and read as a ghost card;
    // -6px spread shrinks the shadow's source rect inward before the blur softens it, so it
    // stays visually inside/right at the card and never reaches the neighbor.
    // Habit/Namaz open an inline Act-Now checklist (see cmToggleToolInlinePanel) right in the
    // feed instead of navigating away — the other tools still jump to their own page for now.
    var cardClick=(c.tab==='habits'||c.tab==='namaz')?('cmToggleToolInlinePanel(\''+c.tab+'\')'):('switchTab(\''+c.tab+'\')');
    return '<div onclick="'+cardClick+'" style="cursor:pointer;flex-shrink:0;width:190px;height:150px;padding:18px 16px;border-radius:18px;background:linear-gradient(160deg,'+c.color+'14,transparent 60%),var(--cc);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);border:1px solid '+c.color+'40;box-shadow:0 6px 10px -6px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.08);position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between">'
      +'<div style="position:absolute;width:120px;height:120px;border-radius:50%;background:'+c.color+';opacity:.18;filter:blur(28px);top:-40px;right:-40px;pointer-events:none"></div>'
      +'<div style="position:relative;width:34px;height:34px;border-radius:10px;background:'+c.color+'22;display:flex;align-items:center;justify-content:center">'
      +'<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="'+c.color+'" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'+c.icon+'</svg>'
      +'</div>'
      +'<div style="position:relative">'
      +'<div style="font-size:25px;font-weight:800;color:var(--ct);font-family:\'Barlow Condensed\',\'Hind Siliguri\',sans-serif;line-height:1.1">'+c.value+'</div>'
      +'<div style="font-size:12.5px;color:var(--ct2);margin-top:2px;font-weight:600;font-family:\'Hind Siliguri\',sans-serif">'+c.label+'</div>'
      +'<div style="height:5px;background:var(--cl);border-radius:4px;margin-top:10px;overflow:hidden"><div style="width:'+pct+'%;height:100%;background:'+c.color+';border-radius:4px"></div></div>'
      +'</div></div>';
  }).join('');
  wrap.style.display='block';
  cmEnableMouseScroll(el);
}
// ── Interactive Tool Catalog — Act Now panel (Habit + Namaz) ────────────────
// Tapping the Habit/Namaz carousel card opens a compact checklist right below the carousel
// instead of navigating to the full tracker page — the whole point being zero-friction inline
// action (per the "Interactive Tool Carousel" plan): mark a habit/prayer done without ever
// leaving the feed. Toggling an item re-renders both this panel and the carousel's own summary
// numbers so everything stays in sync.
var _cmToolPanelOpen=null; // 'habits' | 'namaz' | null
function _cmToolPanelEl(){
  var wrap=document.getElementById('cm-tool-carousel-wrap');
  if(!wrap)return null;
  var panel=document.getElementById('cm-tool-inline-panel');
  if(!panel){
    panel=document.createElement('div');
    panel.id='cm-tool-inline-panel';
    panel.style.cssText='display:none;margin-top:10px;border-radius:14px;background:var(--cc);border:1px solid var(--cl);padding:12px 14px';
    wrap.appendChild(panel);
  }
  return panel;
}
window.cmToggleToolInlinePanel=async function(tool){
  var panel=_cmToolPanelEl();
  if(!panel)return;
  if(_cmToolPanelOpen===tool){ // tap the same card again → close
    panel.style.display='none';
    _cmToolPanelOpen=null;
    return;
  }
  _cmToolPanelOpen=tool;
  panel.style.display='block';
  panel.innerHTML='<div style="font-size:12px;color:var(--ct2);text-align:center;padding:6px 0">লোড হচ্ছে…</div>';
  if(tool==='habits')await cmRenderToolHabitPanel(panel);
  else if(tool==='namaz')await cmRenderToolNamazPanel(panel);
};
async function cmRenderToolHabitPanel(panel){
  if(typeof _sb==='undefined'||!window.sbUser)return;
  var today=new Date().toISOString().split('T')[0];
  try{
    var res=await _sb.from('adult_habits').select('id,name,streak,done,last_done_date').eq('user_id',sbUser.id).order('name');
    var habits=res.data||[];
    var rows=habits.map(function(h){
      var isDone=h.done&&h.last_done_date===today;
      return '<div onclick="cmToolHabitToggle(\''+h.id+'\','+(isDone?'true':'false')+','+(h.streak||0)+')" style="display:flex;align-items:center;gap:10px;padding:8px 4px;cursor:pointer;border-radius:8px" onmouseenter="this.style.background=\'var(--bg,rgba(128,128,128,.06))\'" onmouseleave="this.style.background=\'\'">'
        +'<div style="width:20px;height:20px;border-radius:6px;border:2px solid '+(isDone?'#22C55E':'var(--cl)')+';background:'+(isDone?'#22C55E':'transparent')+';display:flex;align-items:center;justify-content:center;flex-shrink:0">'+(isDone?'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>':'')+'</div>'
        +'<div style="flex:1;font-size:13px;font-weight:600;color:var(--ct);text-decoration:'+(isDone?'line-through':'none')+';opacity:'+(isDone?'.6':'1')+'">'+escapeHtml(h.name||'Habit')+'</div>'
        +'</div>';
    }).join('');
    panel.innerHTML='<div style="font-size:12px;font-weight:700;color:var(--ct2);margin-bottom:6px;text-transform:uppercase;letter-spacing:.3px">আজকের Habit</div>'
      +(rows||'<div style="font-size:12px;color:var(--ct2);padding:8px 0">এখনো কোনো Habit যোগ করোনি।</div>')
      +'<div style="display:flex;gap:8px;margin-top:8px">'
      +'<input id="cm-tool-newhabit-inp" placeholder="নতুন Habit-এর নাম…" autocomplete="off" style="flex:1;padding:8px 12px;border-radius:20px;border:1px solid var(--cl);background:var(--bg);color:var(--ct);font-size:13px" onkeydown="if(event.key===\'Enter\')cmToolAddHabit()">'
      +'<button onclick="cmToolAddHabit()" style="padding:8px 14px;border-radius:20px;border:none;background:linear-gradient(90deg,#FF8A00,#FFB800);color:#fff;font-weight:700;cursor:pointer;font-size:13px">যোগ</button>'
      +'</div>';
  }catch(e){ panel.innerHTML='<div style="font-size:12px;color:var(--ct2)">লোড করা যায়নি।</div>'; }
}
window.cmToolHabitToggle=async function(id,wasDone,streak){
  if(!window.sbUser)return;
  var today=new Date().toISOString().split('T')[0];
  try{
    if(wasDone){
      await _sb.from('adult_habits').update({done:false}).eq('id',id);
    }else{
      await _sb.from('adult_habits').update({done:true,last_done_date:today,streak:(streak||0)+1}).eq('id',id);
      if(typeof cmToast==='function')cmToast('মাশাআল্লাহ! ✓');
    }
    var panel=document.getElementById('cm-tool-inline-panel');
    if(panel)await cmRenderToolHabitPanel(panel);
    cmLoadToolCarousel();
    if(typeof cmRefreshFeedActNowCard==='function')cmRefreshFeedActNowCard();
  }catch(e){}
};
window.cmToolAddHabit=async function(){
  if(!window.sbUser)return;
  var inp=document.getElementById('cm-tool-newhabit-inp');
  var name=inp?inp.value.trim():'';
  if(!name)return;
  try{
    await _sb.from('adult_habits').insert({id:crypto.randomUUID(),user_id:sbUser.id,name:name,streak:0,done:false});
    var panel=document.getElementById('cm-tool-inline-panel');
    if(panel)await cmRenderToolHabitPanel(panel);
    cmLoadToolCarousel();
    if(typeof cmRefreshFeedActNowCard==='function')cmRefreshFeedActNowCard();
  }catch(e){ if(typeof cmToast==='function')cmToast('Habit যোগ করা যায়নি।'); }
};
async function cmRenderToolNamazPanel(panel){
  if(typeof _sb==='undefined'||!window.sbUser)return;
  var today=new Date().toISOString().split('T')[0];
  var order=[['Fajr','ফজর'],['Dhuhr','যোহর'],['Asr','আসর'],['Maghrib','মাগরিব'],['Isha','ইশা']];
  try{
    var res=await _sb.from('adult_namaz_logs').select('prayer,status').eq('user_id',sbUser.id).eq('date',today).eq('status','completed');
    var doneSet={}; (res.data||[]).forEach(function(r){doneSet[r.prayer]=true;});
    var rows=order.map(function(o){
      var isDone=!!doneSet[o[0]];
      return '<div onclick="cmToolNamazToggle(\''+o[0]+'\','+(isDone?'true':'false')+')" style="display:flex;align-items:center;gap:10px;padding:8px 4px;cursor:pointer;border-radius:8px" onmouseenter="this.style.background=\'var(--bg,rgba(128,128,128,.06))\'" onmouseleave="this.style.background=\'\'">'
        +'<div style="width:20px;height:20px;border-radius:6px;border:2px solid '+(isDone?'#10B981':'var(--cl)')+';background:'+(isDone?'#10B981':'transparent')+';display:flex;align-items:center;justify-content:center;flex-shrink:0">'+(isDone?'<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>':'')+'</div>'
        +'<div style="flex:1;font-size:13px;font-weight:600;color:var(--ct);text-decoration:'+(isDone?'line-through':'none')+';opacity:'+(isDone?'.6':'1')+'">'+o[1]+'</div>'
        +'</div>';
    }).join('');
    panel.innerHTML='<div style="font-size:12px;font-weight:700;color:var(--ct2);margin-bottom:6px;text-transform:uppercase;letter-spacing:.3px">আজকের নামাজ</div>'+rows;
  }catch(e){ panel.innerHTML='<div style="font-size:12px;color:var(--ct2)">লোড করা যায়নি।</div>'; }
}
window.cmToolNamazToggle=async function(prayer,wasDone){
  if(!window.sbUser)return;
  var today=new Date().toISOString().split('T')[0];
  try{
    if(wasDone){
      await _sb.from('adult_namaz_logs').delete().eq('user_id',sbUser.id).eq('prayer',prayer).eq('date',today);
    }else{
      await _sb.from('adult_namaz_logs').upsert({user_id:sbUser.id,prayer:prayer,status:'completed',date:today},{onConflict:'user_id,prayer,date'});
      if(typeof cmToast==='function')cmToast('মাশাআল্লাহ! ✓');
    }
    var panel=document.getElementById('cm-tool-inline-panel');
    if(panel)await cmRenderToolNamazPanel(panel);
    cmLoadToolCarousel();
    if(typeof cmRefreshFeedActNowCard==='function')cmRefreshFeedActNowCard();
  }catch(e){}
};
// overflow-x:auto only responds to touch/trackpad swipe by default — a plain mouse has neither,
// so without this a mouse user genuinely cannot scroll a horizontal row. Converts vertical wheel
// delta into horizontal scroll, and adds click-drag scrolling. Guarded so re-rendering the same
// element (every page-load) doesn't stack duplicate listeners.
function cmEnableMouseScroll(el){
  if(!el||el._cmScrollBound)return;
  el._cmScrollBound=true;
  el.addEventListener('wheel',function(e){
    if(Math.abs(e.deltaY)>Math.abs(e.deltaX)){e.preventDefault();el.scrollLeft+=e.deltaY;}
  },{passive:false});
  var down=false,startX=0,startScroll=0;
  el.addEventListener('mousedown',function(e){down=true;startX=e.pageX;startScroll=el.scrollLeft;el.style.cursor='grabbing';});
  window.addEventListener('mouseup',function(){down=false;el.style.cursor='';});
  el.addEventListener('mouseleave',function(){down=false;el.style.cursor='';});
  el.addEventListener('mousemove',function(e){
    if(!down)return;
    e.preventDefault();
    el.scrollLeft=startScroll-(e.pageX-startX);
  });
}

// ── Hadi — AI Partner feed card. Rise Feed personalization Phase 2: whatever the system itself
// injects into the feed (not a real user's post) is attributed to Hadi so it's never mistaken
// for organic content. Picks the single most relevant nudge right now: the most recently-passed
// prayer if it isn't logged yet, else the first incomplete habit, else a plain encouragement.
async function cmLoadHadiCard(){
  var wrap=document.getElementById('cm-hadi-card-wrap');
  var body=document.getElementById('cm-hadi-card-body');
  if(!wrap||!body||typeof _sb==='undefined'||!window.sbUser)return;
  var today=new Date().toISOString().split('T')[0];
  try{
    if(!_cmPrayerTimings){
      var res=await fetch('https://api.aladhan.com/v1/timingsByCity?city=Dhaka&country=Bangladesh&method=1');
      var json=await res.json();
      _cmPrayerTimings=json.data.timings;
    }
    var order=[['Fajr','ফজর'],['Dhuhr','যোহর'],['Asr','আসর'],['Maghrib','মাগরিব'],['Isha','ইশা']];
    var now=new Date();
    var lastPassed=null;
    order.forEach(function(o){
      var hm=_cmPrayerTimings[o[0]].split(' ')[0].split(':');
      var pd=new Date(now);pd.setHours(+hm[0],+hm[1],0,0);
      if(pd<=now)lastPassed=o;
    });
    if(lastPassed){
      var nRes=await _sb.from('adult_namaz_logs').select('status').eq('user_id',sbUser.id).eq('date',today).eq('prayer',lastPassed[0]);
      var done=(nRes.data||[]).some(function(n){return n.status==='completed';});
      if(!done){
        body.innerHTML='<div style="font-size:14px;color:var(--ct);font-family:\'Hind Siliguri\',sans-serif;margin-bottom:10px">'+lastPassed[1]+'ের নামাজ পড়েছ? সময় চলে যাচ্ছে ⏳</div>'
          +'<div style="display:flex;gap:8px">'
          +'<button onclick="cmHadiMarkNamaz(\''+lastPassed[0]+'\',this)" style="flex:1;padding:9px;background:linear-gradient(90deg,#FF8A00,#FFB800);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-family:\'Hind Siliguri\',sans-serif">হ্যাঁ, পড়েছি ✓</button>'
          +'<button onclick="switchTab(\'namaz\')" style="flex:1;padding:9px;background:var(--border);color:var(--ct);border:none;border-radius:8px;font-weight:700;cursor:pointer;font-family:\'Hind Siliguri\',sans-serif">এখনো পড়িনি</button>'
          +'</div>';
        wrap.style.display='block';
        return;
      }
    }
  }catch(e){}
  try{
    var hRes=await _sb.from('adult_habits').select('id,name,streak,done,last_done_date').eq('user_id',sbUser.id);
    var habitsAll=hRes.data||[];
    var pending=habitsAll.find(function(h){return !(h.done&&h.last_done_date===today);});
    if(pending){
      body.innerHTML='<div style="font-size:14px;color:var(--ct);font-family:\'Hind Siliguri\',sans-serif;margin-bottom:10px">"'+(pending.name||'Habit')+'" আজ এখনো করা হয়নি</div>'
        +'<button onclick="cmHadiMarkHabit(\''+pending.id+'\','+(pending.streak||0)+',this)" style="width:100%;padding:9px;background:linear-gradient(90deg,#FF8A00,#FFB800);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-family:\'Hind Siliguri\',sans-serif">Complete করলাম ✓</button>';
      wrap.style.display='block';
      return;
    }
  }catch(e){}
  var qRowForDiscovery=null;
  try{
    var qRes=await _sb.from('adult_quran_data').select('tilawat,daily_goal').eq('user_id',sbUser.id).maybeSingle();
    qRowForDiscovery=qRes.data;
    var todayPages=(qRowForDiscovery&&qRowForDiscovery.tilawat&&qRowForDiscovery.tilawat[today])||0;
    var qGoal=(qRowForDiscovery&&qRowForDiscovery.daily_goal)||2;
    if(todayPages<qGoal){
      body.innerHTML='<div style="font-size:14px;color:var(--ct);font-family:\'Hind Siliguri\',sans-serif;margin-bottom:10px">আজ কোরআন তিলাওয়াত হয়েছে? লক্ষ্য '+qGoal+' পেজ, এখনো '+todayPages+' পেজ 📖</div>'
        +'<button onclick="switchTab(\'quran\')" style="width:100%;padding:9px;background:linear-gradient(90deg,#FF8A00,#FFB800);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-family:\'Hind Siliguri\',sans-serif">তিলাওয়াত log করো</button>';
      wrap.style.display='block';
      return;
    }
  }catch(e){}
  var dwSessionCount=0;
  try{
    var dRes=await _sb.from('deepwork_sessions').select('duration_mins,date').eq('user_id',sbUser.id).eq('date',today);
    dwSessionCount=(dRes.data||[]).length;
    var mins=(dRes.data||[]).reduce(function(s,d){return s+(d.duration_mins||0);},0);
    if(mins===0){
      body.innerHTML='<div style="font-size:14px;color:var(--ct);font-family:\'Hind Siliguri\',sans-serif;margin-bottom:10px">আজ এখনো কোনো Deep Work session হয়নি 🎯</div>'
        +'<button onclick="switchTab(\'deepwork\')" style="width:100%;padding:9px;background:linear-gradient(90deg,#FF8A00,#FFB800);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-family:\'Hind Siliguri\',sans-serif">Session শুরু করো</button>';
      wrap.style.display='block';
      return;
    }
  }catch(e){}
  // Unused-tool discovery — everything today is on track, so instead of a generic "well done"
  // every single time, check for a tracker the user has NEVER touched at all and nudge them
  // toward trying it once, so the app naturally introduces features over time.
  try{
    var slRowForDiscovery=null;
    try{ var slRes2=await _sb.from('adult_sleep_logs').select('date_key').eq('user_id',sbUser.id).limit(1); slRowForDiscovery=(slRes2.data||[])[0]||null; }catch(e){}
    var discoveries=[
      {key:'habits',cond:!habitsAll.length,tab:'habits',label:'Habit Tracker',msg:'ছোট ছোট daily habit ট্র্যাক করলে বড় পরিবর্তন হয় — একটা যোগ করে দেখো?'},
      {key:'quran',cond:!qRowForDiscovery,tab:'quran',label:'Quran Tracker',msg:'প্রতিদিন অল্প অল্প তিলাওয়াতের অভ্যাস গড়ে তুলতে পারো এখান থেকে।'},
      {key:'deepwork',cond:dwSessionCount===0,tab:'deepwork',label:'Deep Work Timer',msg:'বিভ্রান্তি ছাড়া কাজ করার জন্য এই timer টা try করে দেখো।'},
      {key:'sleep',cond:!slRowForDiscovery,tab:'sleep',label:'Sleep Tracker',msg:'ঘুমের সময় ট্র্যাক করলে নিজের রুটিন সম্পর্কে ভালো ধারণা পাবে — একবার log করে দেখো?'}
    ];
    // Frequency cap + permanent dismiss (localStorage, per user+tool): a dismissed discovery
    // never shows again; a shown-but-not-dismissed one waits 3 days before repeating, so it
    // doesn't nag every single day the user happens to have everything else on track.
    var discStKey='_cmDiscoveryState_'+sbUser.id;
    var discSt={}; try{discSt=JSON.parse(localStorage.getItem(discStKey)||'{}');}catch(e){}
    var nowTs=new Date().getTime();
    var disc=discoveries.find(function(d){
      if(!d.cond)return false;
      var st=discSt[d.key];
      if(st&&st.dismissed)return false;
      if(st&&st.lastShown&&(nowTs-st.lastShown)<3*86400000)return false;
      return true;
    });
    if(disc){
      discSt[disc.key]={lastShown:nowTs,dismissed:false};
      try{localStorage.setItem(discStKey,JSON.stringify(discSt));}catch(e){}
      body.innerHTML='<div style="font-size:11px;color:var(--cgold);font-weight:700;margin-bottom:4px">🆕 এখনো Try করোনি</div>'
        +'<div style="font-size:14px;color:var(--ct);font-family:\'Hind Siliguri\',sans-serif;margin-bottom:10px">'+disc.msg+'</div>'
        +'<div style="display:flex;gap:8px">'
        +'<button onclick="switchTab(\''+disc.tab+'\')" style="flex:1;padding:9px;background:var(--border);color:var(--ct);border:none;border-radius:8px;font-weight:700;cursor:pointer;font-family:\'Hind Siliguri\',sans-serif">'+disc.label+' দেখো</button>'
        +'<button onclick="cmHadiDismissDiscovery(\''+disc.key+'\',this)" style="padding:9px 12px;background:transparent;color:var(--ct2);border:1px solid var(--cl);border-radius:8px;font-weight:600;cursor:pointer;font-size:12px;font-family:\'Hind Siliguri\',sans-serif">দরকার নেই</button>'
        +'</div>';
      wrap.style.display='block';
      return;
    }
  }catch(e){}
  body.innerHTML='<div style="font-size:14px;color:var(--ct);font-family:\'Hind Siliguri\',sans-serif">মাশাআল্লাহ! আজকে সব ঠিকঠাক চলছে। এভাবেই এগিয়ে যাও 🔥</div>';
  wrap.style.display='block';
}
window.cmHadiMarkNamaz=async function(prayer,btn){
  if(!window.sbUser)return;
  if(btn)btn.disabled=true;
  var today=new Date().toISOString().split('T')[0];
  await _sb.from('adult_namaz_logs').upsert({user_id:sbUser.id,prayer:prayer,status:'completed',date:today},{onConflict:'user_id,prayer,date'});
  if(typeof cmToast==='function')cmToast('মাশাআল্লাহ! ✓');
  cmLoadHadiCard();
  cmLoadToolCarousel();
};
window.cmHadiMarkHabit=async function(id,streak,btn){
  if(!window.sbUser)return;
  if(btn)btn.disabled=true;
  var today=new Date().toISOString().split('T')[0];
  await _sb.from('adult_habits').update({done:true,last_done_date:today,streak:(streak||0)+1}).eq('id',id);
  if(typeof cmToast==='function')cmToast('Done! ✓');
  cmLoadHadiCard();
  cmLoadToolCarousel();
};
window.cmHadiDismissDiscovery=function(key,btn){
  if(!window.sbUser)return;
  if(btn)btn.disabled=true;
  var discStKey='_cmDiscoveryState_'+sbUser.id;
  var discSt={}; try{discSt=JSON.parse(localStorage.getItem(discStKey)||'{}');}catch(e){}
  discSt[key]={dismissed:true};
  try{localStorage.setItem(discStKey,JSON.stringify(discSt));}catch(e){}
  cmLoadHadiCard();
};

(function(){
  var _cmWidgetsOrig=window.showPage;
  window.showPage=function(page){
    var r=_cmWidgetsOrig.apply(this,arguments);
    if(page==='community'){
      cmLoadNamazCountdown();
      cmLoadRizPlayPromo();
      cmLoadCommunityStats();
      cmLoadWeeklyHero();
      cmLoadSuggestedRisers();
      cmLoadTodaySnapshot();
      cmLoadToolCarousel();
      cmLoadHadiCard();
      // Posts load asynchronously (cmLoadPosts → cmRenderFeed), so the .cm-post elements these
      // two depend on may not exist yet right after showPage returns. A single one-shot check
      // (fire once when posts first appear, then stop polling forever) turned out unreliable in
      // practice — occasionally the very first injection attempt's Supabase round-trip lands
      // right as another cmRenderFeed() re-render wipes the feed out from under it, and since
      // polling had already stopped, the card just never came back, leaving "Grow Your Network"/
      // the RizPlay suggestion permanently missing for that visit. cmRenderFeed() itself also
      // re-invokes both injectors after every render as a second line of defense, but neither
      // one alone proved fully reliable, so this now keeps re-checking for a while and re-fires
      // (both functions are idempotent — id-guarded — so a redundant call is a harmless no-op).
      (function(){
        var tries=0;
        var iv=setInterval(function(){
          tries++;
          var feed=document.getElementById('cm-feed');
          if(feed&&feed.querySelectorAll('.cm-post[data-post-id]').length>0){
            cmInjectFeedRizPlayCard();
            cmInjectFeedSuggestedCard();
            cmInjectFeedSquadCard();
            cmInjectFeedActNowCard();
            cmInjectFeedTodoCard();
            cmInjectFeedQuranCard();
            cmInjectFeedScreenTimeCard();
            cmInjectFeedDeepWorkCard();
          }
          if(tries>=15)clearInterval(iv); // ~15s of watchdog re-checks, then give up
        },1000);
      })();
    }
    return r;
  };
})();

// ══ CHALLENGES FEATURE (chl*) ═══════════════════════════════════════════════════════════
// Users create a challenge, anyone can join it (no approval step — challenge_participants is
// a plain insert/delete row, same shape as post_reactions), and progress updates posted inside
// a challenge are real `posts` rows tagged with challenge_id — see cmSubmitPost_sb/cmMapPostRow/
// cmBuildPostCardHtml for how that reuses the entire existing feed/reactions/comments stack
// (same proven pattern pfLoadVisitorPosts() already uses to merge a visited profile's posts
// into the shared cmPosts array so react/comment/share keep working unmodified).
var chlChallenges=[];            // browse-list cache
var chlMyChallengeIds=null;      // Set<string> of challenge_ids the current user has joined
var chlCurrentChallengeId=null;  // non-null only while detail view is open
var chlCurrentChallenge=null;    // full row of the open challenge

// pages/community.html owns #cm-menu/#cm-menu-backdrop (the "…" post-action popup) — the only
// shared post-action DOM that isn't already in index.html (#cm-post-modal/#cm-composer live
// there directly). If the user opens Challenges without ever visiting Rise Feed this session,
// that markup wouldn't exist yet and a card's "…" button would silently no-op. Mirrors
// showPage()'s own lazy-fragment-fetch (same _rzLoadedPages tracker, so the two never double-fetch).
function chlEnsureCommunityLoaded(cb){
  if(document.getElementById('cm-menu')){ cb(); return; }
  if(_rzLoadedPages['community']==='loading'){ setTimeout(function(){chlEnsureCommunityLoaded(cb);},150); return; }
  _rzLoadedPages['community']='loading';
  fetch('pages/community.html?v='+_RZ_ASSET_V).then(function(r){return r.text();}).then(function(html){
    var tmp=document.createElement('div');tmp.innerHTML=html;
    var al=document.getElementById('app-layout')||document.body;
    var appMain=al.querySelector('.app-main')||al;
    while(tmp.firstChild) appMain.appendChild(tmp.firstChild);
    _rzLoadedPages['community']='loaded';
    cb();
  }).catch(function(){cb();});
}

async function chlLoadChallenges(){
  var el=document.getElementById('chl-browse-list');
  if(!el||typeof _sb==='undefined')return;
  el.innerHTML='<div class="chl-empty">Loading challenges...</div>';
  try{
    var res=await _sb.from('challenges').select('*, challenge_participants(count)').order('created_at',{ascending:false}).limit(50);
    if(res.error){ el.innerHTML='<div class="chl-empty">Couldn\'t load challenges.</div>'; return; }
    var now=Date.now();
    // "Active" = no duration set (ongoing) or created_at+duration_days hasn't passed yet.
    chlChallenges=(res.data||[]).filter(function(c){
      if(!c.duration_days)return true;
      var end=new Date(c.created_at).getTime()+c.duration_days*86400000;
      return end>now;
    });
    if(sbUser){
      var mine=await _sb.from('challenge_participants').select('challenge_id').eq('user_id',sbUser.id);
      chlMyChallengeIds=new Set((mine.data||[]).map(function(r){return r.challenge_id;}));
    }else{
      chlMyChallengeIds=new Set();
    }
    chlRenderBrowseList();
  }catch(e){ el.innerHTML='<div class="chl-empty">Couldn\'t load challenges.</div>'; }
}

function chlRenderBrowseList(){
  var el=document.getElementById('chl-browse-list');
  if(!el)return;
  if(!chlChallenges.length){
    el.innerHTML='<div class="chl-empty">No active challenges yet — be the first to start one! 🎯</div>';
    return;
  }
  el.innerHTML=chlChallenges.map(function(c){
    var count=(c.challenge_participants&&c.challenge_participants[0])?(c.challenge_participants[0].count||0):0;
    var joined=chlMyChallengeIds&&chlMyChallengeIds.has(c.id);
    var durText=c.duration_days?(c.duration_days+' Days'):'Ongoing';
    var actionBtn=joined
      ?'<button class="chl-btn-outline" onclick="event.stopPropagation();chlToggleJoin(\''+c.id+'\')">Joined</button>'
      :'<button class="chl-btn-primary" onclick="event.stopPropagation();chlToggleJoin(\''+c.id+'\')">Join</button>';
    return '<div class="chl-card" onclick="chlOpenChallenge(\''+c.id+'\')">'
      +'<div class="chl-card-icon">'+(c.icon||'🎯')+'</div>'
      +'<div class="chl-card-body">'
      +'<div class="chl-card-title">'+escapeHtml(c.title)+'</div>'
      +(c.description?'<div class="chl-card-desc">'+escapeHtml(c.description)+'</div>':'')
      +'<div class="chl-card-meta">'+count+' joined · '+durText+'</div>'
      +'</div>'
      +'<div class="chl-card-actions">'+actionBtn+'</div>'
      +'</div>';
  }).join('');
}

window.chlOpenCreateModal=function(){
  if(!sbUser){ if(typeof sbOpenAuth==='function')sbOpenAuth('login'); return; }
  var m=document.getElementById('chl-create-modal');
  if(m)m.classList.add('open');
};

// Entry point from the Rise Feed's "Active Challenges" sidebar card (pages/community.html) —
// showPage('challenges') lazy-fetches pages/challenges.html if it isn't already in the DOM
// (same generic mechanism every page uses), so the create modal doesn't exist yet on the very
// first call; poll briefly until it does, matching chlJumpToChallenge's own wait pattern.
window.chlGoCreateChallenge=function(){
  if(!sbUser){ if(typeof sbOpenAuth==='function')sbOpenAuth('login'); return; }
  showPage('challenges');
  var tries=0;
  var iv=setInterval(function(){
    tries++;
    if(document.getElementById('chl-create-modal')){
      clearInterval(iv);
      chlOpenCreateModal();
    }else if(tries>=30){ clearInterval(iv); }
  },100);
};

window.chlSelectChip=function(group,el){
  var wrap=document.getElementById('chl-'+group+'-chips');
  if(wrap)wrap.querySelectorAll('.chl-chip').forEach(function(c){c.classList.remove('selected');});
  el.classList.add('selected');
  var hidden=document.getElementById('chl-'+group);
  if(hidden)hidden.value=el.getAttribute('data-val');
};

window.chlSubmitCreate=async function(){
  var titleEl=document.getElementById('chl-c-title');
  var title=titleEl?titleEl.value.trim():'';
  var errEl=document.getElementById('chl-c-error');
  if(!title){ if(errEl){errEl.textContent='Title is required';errEl.style.display='block';} return; }
  if(!sbUser){ if(typeof sbOpenAuth==='function')sbOpenAuth('login'); return; }
  if(errEl)errEl.style.display='none';
  var btn=document.getElementById('chl-c-submit-btn');
  if(btn){btn.disabled=true;btn.textContent='Creating...';}
  try{
    var descEl=document.getElementById('chl-c-desc');
    var desc=descEl?descEl.value.trim():'';
    var icon=(document.getElementById('chl-c-icon')||{}).value||'🎯';
    var durVal=(document.getElementById('chl-c-duration')||{}).value||'';
    var duration=durVal?parseInt(durVal,10):null;
    var ins=await _sb.from('challenges').insert({
      creator_id:sbUser.id, title:title, description:desc||null, icon:icon, duration_days:duration
    }).select('*').single();
    if(ins.error){ if(errEl){errEl.textContent='Error: '+ins.error.message;errEl.style.display='block';} return; }
    var newId=ins.data.id;
    await _sb.from('challenge_participants').insert({challenge_id:newId,user_id:sbUser.id});
    titleEl.value='';
    if(descEl)descEl.value='';
    var m=document.getElementById('chl-create-modal'); if(m)m.classList.remove('open');
    await chlLoadChallenges();
    chlOpenChallenge(newId);
  }catch(e){
    if(errEl){errEl.textContent='Error: '+e.message;errEl.style.display='block';}
  }finally{
    if(btn){btn.disabled=false;btn.textContent='Create Challenge';}
  }
};

function chlUpdateDetailJoinState(){
  var wrap=document.getElementById('chl-join-actions');
  if(!wrap||!chlCurrentChallengeId)return;
  var joined=chlMyChallengeIds&&chlMyChallengeIds.has(chlCurrentChallengeId);
  wrap.className='chl-join-actions '+(joined?'chl-joined':'chl-not-joined');
  var prompt=document.getElementById('chl-progress-prompt');
  if(prompt)prompt.style.display=joined?'block':'none';
}

// Custom confirm — replaces the browser's native confirm() for Join/Leave/Streak Freeze
// (looked jarring and inconsistent across browsers/OSes). Promise-based so existing
// "if(!confirm(...))return;" call sites just become "if(!await chlConfirm(...))return;".
// Only one confirm can be in flight at a time (a single shared modal), which matches every
// current call site — none of them open a second confirm while one's already showing.
var _chlConfirmResolve=null;
function chlConfirm(message,confirmLabel,icon){
  return new Promise(function(resolve){
    _chlConfirmResolve=resolve;
    var msgEl=document.getElementById('chl-confirm-message'); if(msgEl)msgEl.textContent=message;
    var btn=document.getElementById('chl-confirm-ok-btn'); if(btn)btn.textContent=confirmLabel||'নিশ্চিত করো';
    var iconEl=document.getElementById('chl-confirm-icon'); if(iconEl)iconEl.innerHTML=icon||'❓';
    var modal=document.getElementById('chl-confirm-modal'); if(modal)modal.classList.add('open');
  });
}
window.chlConfirmResolve=function(val){
  var modal=document.getElementById('chl-confirm-modal'); if(modal)modal.classList.remove('open');
  if(_chlConfirmResolve){ var r=_chlConfirmResolve; _chlConfirmResolve=null; r(val); }
};

// Join costs a one-time 100 Reys entry fee (chl_join_challenge RPC, security definer —
// a plain client insert is blocked by RLS now, see challenges_reys_pivot.sql) — after
// that everything inside the challenge (Streak Freeze etc.) is free, no repeated spend.
// Leaving doesn't refund it, so confirm before either side of this toggle.
window.chlToggleJoin=async function(challengeId){
  if(!challengeId)return;
  if(!sbUser){ if(typeof sbOpenAuth==='function')sbOpenAuth('login'); return; }
  var joined=chlMyChallengeIds&&chlMyChallengeIds.has(challengeId);
  try{
    if(joined){
      if(!await chlConfirm('চ্যালেঞ্জ ছেড়ে দিলে আবার join করতে ১০০ Reys লাগবে।','Leave করবো','<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#FF8A00" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 21H5a2 2 0 01-2-2V5a2 2 0 012-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/></svg>'))return;
      await _sb.from('challenge_participants').delete().eq('challenge_id',challengeId).eq('user_id',sbUser.id);
      if(chlMyChallengeIds)chlMyChallengeIds.delete(challengeId);
    }else{
      if(!await chlConfirm('এই চ্যালেঞ্জে join করতে ১০০ Reys লাগবে — একবারই, এরপর আর কোনো খরচ নেই।','Join করবো','🎯'))return;
      var r=await _sb.rpc('chl_join_challenge',{p_challenge_id:challengeId});
      if(r.error){
        if(typeof cmToast==='function')cmToast(r.error.message.indexOf('Not enough')!==-1?'যথেষ্ট Reys নেই — Subscription পেজ থেকে কিনে নাও':'কিছু ভুল হয়েছে');
        return;
      }
      if(window.sbProfile) window.sbProfile.reys_balance=r.data;
      if(typeof stRenderSubscription==='function') stRenderSubscription();
      if(!chlMyChallengeIds)chlMyChallengeIds=new Set();
      chlMyChallengeIds.add(challengeId);
    }
  }catch(e){ if(typeof cmToast==='function')cmToast('Error: '+e.message); return; }
  chlRenderBrowseList();
  if(chlCurrentChallengeId===challengeId) chlUpdateDetailJoinState();
  var row=chlChallenges.find(function(c){return c.id===challengeId;});
  if(row&&row.challenge_participants&&row.challenge_participants[0]){
    row.challenge_participants[0].count=Math.max(0,(row.challenge_participants[0].count||0)+(joined?-1:1));
  }
};

window.chlOpenChallenge=async function(challengeId){
  chlCurrentChallengeId=challengeId;
  var browse=document.getElementById('chl-browse-view');
  var detail=document.getElementById('chl-detail-view');
  if(browse)browse.style.display='none';
  if(detail)detail.style.display='block';
  var titleEl=document.getElementById('chl-detail-title');
  if(titleEl)titleEl.textContent='Loading...';
  try{
    var res=await _sb.from('challenges').select('*, profiles(name)').eq('id',challengeId).maybeSingle();
    if(!res.data){ if(titleEl)titleEl.textContent='Challenge not found'; return; }
    chlCurrentChallenge=res.data;
    var iconEl=document.getElementById('chl-detail-icon'); if(iconEl)iconEl.textContent=res.data.icon||'🎯';
    if(titleEl)titleEl.textContent=res.data.title;
    var creatorEl=document.getElementById('chl-detail-creator');
    if(creatorEl){
      var isMine=sbUser&&res.data.creator_id===sbUser.id;
      creatorEl.textContent='Created by '+(isMine?'you':((res.data.profiles&&res.data.profiles.name)||'a Rizer'));
    }
    var descEl2=document.getElementById('chl-detail-desc');
    if(descEl2){ descEl2.textContent=res.data.description||''; descEl2.style.display=res.data.description?'block':'none'; }

    var pres=await _sb.from('challenge_participants').select('user_id, profiles(name,avatar_url)').eq('challenge_id',challengeId).limit(8);
    var members=pres.data||[];
    var avEl=document.getElementById('chl-detail-avatars');
    if(avEl){
      avEl.innerHTML=members.map(function(m){
        var prof=m.profiles||{};
        return prof.avatar_url
          ?'<img src="'+prof.avatar_url+'" alt="">'
          :'<div class="chl-av-fallback">'+((prof.name||'R').charAt(0).toUpperCase())+'</div>';
      }).join('');
    }
    var cres=await _sb.from('challenge_participants').select('id',{count:'exact',head:true}).eq('challenge_id',challengeId);
    var mcEl=document.getElementById('chl-detail-membercount');
    if(mcEl)mcEl.textContent=(cres.count||0)+' joined';
    var durEl=document.getElementById('chl-detail-duration');
    if(durEl)durEl.textContent=res.data.duration_days?(res.data.duration_days+' day challenge'):'Ongoing';

    if(sbUser){
      var myRow=await _sb.from('challenge_participants').select('id').eq('challenge_id',challengeId).eq('user_id',sbUser.id).maybeSingle();
      if(!chlMyChallengeIds)chlMyChallengeIds=new Set();
      if(myRow.data)chlMyChallengeIds.add(challengeId); else chlMyChallengeIds.delete(challengeId);
    }
    chlUpdateDetailJoinState();
    if(sbUser&&typeof chlRenderProgressCalendar==='function') chlRenderProgressCalendar(challengeId);
    if(sbUser&&typeof chlRenderQuickCompleteBtn==='function') chlRenderQuickCompleteBtn(challengeId);
    if(sbUser&&typeof chlRenderMilestoneCardBtn==='function') chlRenderMilestoneCardBtn(challengeId);
    await chlLoadChallengeFeed(challengeId);
  }catch(e){ if(titleEl)titleEl.textContent='Error loading challenge'; }
};

window.chlBackToBrowse=function(){
  chlCurrentChallengeId=null;
  chlCurrentChallenge=null;
  var browse=document.getElementById('chl-browse-view');
  var detail=document.getElementById('chl-detail-view');
  if(detail)detail.style.display='none';
  if(browse)browse.style.display='block';
  chlLoadChallenges();
};

// Purpose-built progress-log composer (replaces reusing the generic Rise-feed
// composer): shows which day of the challenge this is and any current
// posting streak — both computed client-side from challenge_participants
// .joined_at and this user's own posts.challenge_id history, since neither
// concept has a ready-made column. Submission still goes through the shared
// cmSubmitPost_sb() pipeline (image upload, cmPosts update, feed refresh),
// just tagged category:'progress' instead of the composer's own UI.
var chlComposerImgFile=null;
var _chlComposerChallengeId=null;

// YYYY-MM-DD from LOCAL date parts — deliberately not toISOString() (UTC), since freeze_date
// is a plain SQL `date` with no timezone and must line up with what the user considers "today".
function _rzLocalDateStr(d){
  d=d||new Date();
  var m=String(d.getMonth()+1).padStart(2,'0'), day=String(d.getDate()).padStart(2,'0');
  return d.getFullYear()+'-'+m+'-'+day;
}

async function chlComputeDayAndStreak(challengeId){
  var result={day:1,streak:0,durationDays:null,todayFrozen:false,todayLogged:false};
  try{
    var chal=window.chlCurrentChallenge;
    if(chal) result.durationDays=chal.duration_days||null;
    var pr=await _sb.from('challenge_participants').select('joined_at').eq('challenge_id',challengeId).eq('user_id',sbUser.id).maybeSingle();
    if(pr.data&&pr.data.joined_at){
      var joined=new Date(pr.data.joined_at);
      var joinedDay=new Date(joined.getFullYear(),joined.getMonth(),joined.getDate());
      var today=new Date();
      var todayDay=new Date(today.getFullYear(),today.getMonth(),today.getDate());
      result.day=Math.max(1,Math.round((todayDay-joinedDay)/86400000)+1);
    }
    var pr2=await _sb.from('posts').select('created_at').eq('challenge_id',challengeId).eq('user_id',sbUser.id).order('created_at',{ascending:false}).limit(60);
    var pr3=await _sb.from('challenge_streak_freezes').select('freeze_date').eq('challenge_id',challengeId).eq('user_id',sbUser.id);
    var frozen=new Set((pr3.data||[]).map(function(r){return r.freeze_date;}));
    var days=new Set((pr2.data||[]).map(function(r){var d=new Date(r.created_at);return d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate();}));
    var todayKeyLocal=(function(){var d=new Date();return d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate();})();
    result.todayLogged=days.has(todayKeyLocal);
    result.todayFrozen=frozen.has(_rzLocalDateStr());
    var cursor=new Date();
    var streak=0;
    while(true){
      var key=cursor.getFullYear()+'-'+cursor.getMonth()+'-'+cursor.getDate();
      if(days.has(key)||frozen.has(_rzLocalDateStr(cursor))){streak++;cursor.setDate(cursor.getDate()-1);}
      else break;
    }
    result.streak=streak;
  }catch(e){}
  return result;
}

// One-tap "today done" action — replaces the old paid-in-Reys Streak Freeze entry point
// (freeze buying stays reachable via chl_buy_streak_freeze RPC/table for any historical
// frozen days already on record, just no longer offered from the UI). Reuses the exact
// same auto-card-generation + submit pipeline chlComposerSubmit() uses, just driven off
// the hidden composer DOM (#chl-pc-text/#chl-pc-card-canvas, which stay in the DOM even
// while the composer modal itself is closed) instead of requiring the modal to be opened.
async function chlQuickCompleteToday(challengeId){
  if(!sbUser){ if(typeof sbOpenAuth==='function')sbOpenAuth('login'); return; }
  if(_chlSubmittingProgress)return;
  var wrap=document.getElementById('chl-quick-complete-wrap');
  var btn=document.getElementById('chl-quick-complete-btn');
  _chlSubmittingProgress=true;
  if(btn){btn.disabled=true;btn.style.opacity='.6';}
  try{
    var info=await chlComputeDayAndStreak(challengeId);
    var day=info.day||1;
    var text='Day '+day+': আজকের Challenge সম্পন্ন করেছি! ✅';
    window._chlComposerDay=day;
    var ta=document.getElementById('chl-pc-text');
    if(ta) ta.value=text;
    await chlRenderProgressCardPreview();
    var imgFile=await chlProgressCardToFile();
    var submitText=imgFile?('Day '+day+':'):text;
    window.cmComposerImgFile=imgFile;
    var balBefore=(window.sbProfile&&window.sbProfile.reys_balance)||0;
    var ok=await cmSubmitPost_sb(submitText,'progress',null,challengeId);
    window.cmComposerImgFile=null;
    if(ok){
      var fresh=await _sb.from('profiles').select('*').eq('id',sbUser.id).single();
      var earned=0;
      if(fresh.data){ earned=Math.max(0,(fresh.data.reys_balance||0)-balBefore); window.sbProfile=fresh.data; }
      var sinfo=await chlComputeDayAndStreak(challengeId);
      var hitMilestone=CHL_STREAK_MILESTONES.indexOf(sinfo.streak)!==-1;
      if(typeof cmToast==='function'){
        if(hitMilestone) cmToast('🎉 '+sinfo.streak+' দিনের streak সম্পন্ন! Alhamdulillah, চালিয়ে যাও!');
        else if(earned>0) cmToast('✅ আজকের progress post হয়েছে! +'+earned+' Reys');
        else cmToast('✅ আজকের progress post হয়েছে!');
      }
      if(hitMilestone && typeof chlOpenMilestoneCard==='function') chlOpenMilestoneCard(challengeId,sinfo.streak);
      if(typeof chlRenderProgressCalendar==='function') chlRenderProgressCalendar(challengeId);
      if(typeof chlRenderMilestoneCardBtn==='function') chlRenderMilestoneCardBtn(challengeId);
      if(typeof chlRenderQuickCompleteBtn==='function') chlRenderQuickCompleteBtn(challengeId);
      if(typeof stRenderSubscription==='function') stRenderSubscription();
    } else {
      if(typeof cmToast==='function')cmToast('কিছু ভুল হয়েছে, আবার চেষ্টা করো');
    }
  }catch(e){
    if(typeof cmToast==='function')cmToast('কিছু ভুল হয়েছে, আবার চেষ্টা করো');
  }finally{
    _chlSubmittingProgress=false;
    if(btn){btn.disabled=false;btn.style.opacity='';}
  }
}

async function chlRenderQuickCompleteBtn(challengeId){
  var el=document.getElementById('chl-quick-complete-wrap');
  if(!el||!sbUser)return;
  var info=await chlComputeDayAndStreak(challengeId);
  el.style.display=(info.todayLogged||info.todayFrozen)?'none':'block';
}

// ══ MILESTONE SHAREABLE CARD ═══════════════════════════════════════════════
// Free perk (see challenges_reys_pivot.sql) — draws a 1080x1920 (Instagram/
// WhatsApp Story ratio) "certificate" entirely with the Canvas 2D API, same
// approach as the avatar-crop flow (pfCropSave, ~line 20213) — no external
// library. The user's avatar image is deliberately NOT drawn onto the canvas:
// a cross-origin image without the right CORS headers "taints" the canvas and
// throws on toBlob()/share, silently breaking download+share both. A
// text-initial circle (matching the app's own avatar-fallback style) sidesteps
// that entirely.
var _chlMcStreak=0;

async function chlRenderMilestoneCardBtn(challengeId){
  var el=document.getElementById('chl-milestone-btn-wrap');
  if(!el||!sbUser)return;
  var info=await chlComputeDayAndStreak(challengeId);
  el.style.display=(info.streak>=CHL_STREAK_MILESTONES[0])?'block':'none';
}

window.chlOpenMilestoneCardCurrent=function(challengeId){
  chlComputeDayAndStreak(challengeId).then(function(info){ chlOpenMilestoneCard(challengeId,info.streak); });
};

async function chlOpenMilestoneCard(challengeId,streak){
  if(!sbUser){ if(typeof sbOpenAuth==='function')sbOpenAuth('login'); return; }
  _chlMcStreak=streak;
  var modal=document.getElementById('chl-milestone-modal');
  if(modal)modal.classList.add('open');
  try{ await document.fonts.ready; }catch(e){}
  var canvas=document.getElementById('chl-mc-canvas');
  if(!canvas)return;
  var chal=window.chlCurrentChallenge||{};
  chlDrawMilestoneCard(canvas,{
    streak:streak,
    challengeTitle:chal.title||'Challenge',
    challengeIcon:chal.icon||'🎯',
    userName:(window.sbProfile&&window.sbProfile.name)||'Rizer'
  });
}

window.chlCloseMilestoneCard=function(){
  var modal=document.getElementById('chl-milestone-modal');
  if(modal)modal.classList.remove('open');
};

function chlWrapCanvasText(ctx,text,x,y,maxWidth,lineHeight){
  var words=(text||'').split(' '), line='', lines=[];
  for(var i=0;i<words.length;i++){
    var test=line?line+' '+words[i]:words[i];
    if(ctx.measureText(test).width>maxWidth && line){ lines.push(line); line=words[i]; }
    else line=test;
  }
  if(line)lines.push(line);
  var startY=y-((lines.length-1)*lineHeight)/2;
  lines.forEach(function(l,i){ ctx.fillText(l,x,startY+i*lineHeight); });
}

function chlDrawMilestoneCard(canvas,info){
  var ctx=canvas.getContext('2d');
  var W=canvas.width, H=canvas.height;

  var bg=ctx.createLinearGradient(0,0,0,H);
  bg.addColorStop(0,'#1c2436'); bg.addColorStop(0.55,'#121724'); bg.addColorStop(1,'#0b0e15');
  ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

  var g1=ctx.createRadialGradient(W*0.85,H*0.12,0,W*0.85,H*0.12,W*0.55);
  g1.addColorStop(0,'rgba(255,138,0,.22)'); g1.addColorStop(1,'rgba(255,138,0,0)');
  ctx.fillStyle=g1; ctx.fillRect(0,0,W,H);
  var g2=ctx.createRadialGradient(W*0.1,H*0.85,0,W*0.1,H*0.85,W*0.6);
  g2.addColorStop(0,'rgba(255,184,0,.14)'); g2.addColorStop(1,'rgba(255,184,0,0)');
  ctx.fillStyle=g2; ctx.fillRect(0,0,W,H);

  ctx.textAlign='center';

  ctx.fillStyle='rgba(255,255,255,.55)';
  ctx.font='700 30px "Hind Siliguri",sans-serif';
  ctx.fillText('R I Z E R S', W/2, 120);

  ctx.font='170px "Hind Siliguri",sans-serif';
  ctx.fillText(info.challengeIcon, W/2, H*0.36);

  ctx.font='800 320px "Hind Siliguri",sans-serif';
  var grad=ctx.createLinearGradient(0,H*0.38,0,H*0.58);
  grad.addColorStop(0,'#FFB800'); grad.addColorStop(1,'#FF8A00');
  ctx.fillStyle=grad;
  ctx.fillText(String(info.streak), W/2, H*0.58);

  ctx.font='800 46px "Hind Siliguri",sans-serif';
  ctx.fillStyle='#fff';
  ctx.fillText('DAY STREAK 🔥', W/2, H*0.63);

  ctx.font='600 40px "Hind Siliguri",sans-serif';
  ctx.fillStyle='rgba(255,255,255,.85)';
  chlWrapCanvasText(ctx, info.challengeTitle, W/2, H*0.705, W*0.8, 52);

  var cy=H*0.83;
  ctx.beginPath(); ctx.arc(W/2-70,cy,36,0,Math.PI*2);
  ctx.fillStyle='#FF8A00'; ctx.fill();
  ctx.font='700 36px "Hind Siliguri",sans-serif';
  ctx.fillStyle='#090B12';
  ctx.fillText((info.userName||'R').charAt(0).toUpperCase(), W/2-70, cy+13);
  ctx.textAlign='left';
  ctx.font='600 38px "Hind Siliguri",sans-serif';
  ctx.fillStyle='#fff';
  ctx.fillText(info.userName, W/2-20, cy+13);

  ctx.textAlign='center';
  ctx.font='500 28px "Hind Siliguri",sans-serif';
  ctx.fillStyle='rgba(255,255,255,.5)';
  ctx.fillText('Rizers এ Challenge করছি — তুমিও করো', W/2, H*0.94);
}

function chlMilestoneCardBlob(cb){
  var canvas=document.getElementById('chl-mc-canvas');
  if(!canvas)return;
  canvas.toBlob(function(blob){ cb(blob); }, 'image/png');
}

window.chlDownloadMilestoneCard=function(){
  chlMilestoneCardBlob(function(blob){
    if(!blob)return;
    var url=URL.createObjectURL(blob);
    var a=document.createElement('a');
    a.href=url; a.download='rizers-streak-'+_chlMcStreak+'.png';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){URL.revokeObjectURL(url);},2000);
  });
};

window.chlShareMilestoneCard=function(){
  chlMilestoneCardBlob(async function(blob){
    if(!blob)return;
    var file=new File([blob],'rizers-streak-'+_chlMcStreak+'.png',{type:'image/png'});
    if(navigator.canShare && navigator.canShare({files:[file]})){
      try{ await navigator.share({files:[file], title:'Rizers Streak', text:_chlMcStreak+' দিনের streak! 🔥'}); }
      catch(e){}
    } else {
      window.chlDownloadMilestoneCard();
      if(typeof cmToast==='function')cmToast('Image download হয়েছে — WhatsApp/Instagram এ share করো');
    }
  });
};

// ══ AUTO-GENERATED PROGRESS INFOGRAPHIC (FB-colored-status-style) ═══════════
// When a user shares progress WITHOUT attaching their own photo, a dark/premium
// 1:1 "infographic" (gradient + Day N + challenge icon + their caption text
// overlaid, auto-sized to fit) is drawn on a canvas and used AS the post's
// image — same Canvas 2D approach as the Milestone Card, and same "generate →
// toBlob → File" upload path a real photo attachment already goes through
// (cmSubmitPost_sb doesn't need to know or care that the File wasn't picked
// from disk). If a real photo IS attached, this is skipped entirely — matches
// Facebook: colored-background-text is only offered for photo-less posts.
var _chlPcPreviewRAF=null;

// Word-wraps at a given font size, hard-splitting (character by character) any single
// token that's wider than maxWidth on its own — a long URL/hashtag/unbroken word would
// otherwise never break and could render past the canvas edges regardless of font size.
function chlWrapAtSize(ctx,text,maxWidth,size,weight,family){
  ctx.font=weight+' '+size+'px '+family;
  var words=(text||'').split(/\s+/).filter(Boolean), line='', lines=[];
  for(var i=0;i<words.length;i++){
    var word=words[i];
    if(ctx.measureText(word).width>maxWidth){
      var piece='';
      for(var c=0;c<word.length;c++){
        var testPiece=piece+word[c];
        if(ctx.measureText(testPiece).width>maxWidth && piece){
          if(line){lines.push(line);line='';}
          lines.push(piece);
          piece=word[c];
        }else piece=testPiece;
      }
      word=piece;
    }
    var test=line?line+' '+word:word;
    if(ctx.measureText(test).width>maxWidth && line){ lines.push(line); line=word; }
    else line=test;
  }
  if(line)lines.push(line);
  var lineHeight=size*1.38;
  return {size:size,lines:lines,lineHeight:lineHeight,height:lines.length*lineHeight};
}

// Shrinks the font size until the wrapped text fits maxHeight, or gives up at minFont —
// always returns a fresh {size,lines,lineHeight} computed together at the SAME size (the
// previous version could return a size that the loop's own height-check was never run
// against, since the loop's step size skipped straight past minFont without testing it).
function chlFitWrapText(ctx,text,maxWidth,maxHeight,maxFont,minFont,weight,family){
  var size=maxFont;
  while(size>minFont){
    var fit=chlWrapAtSize(ctx,text,maxWidth,size,weight,family);
    if(fit.height<=maxHeight) return fit;
    size-=3;
  }
  return chlWrapAtSize(ctx,text,maxWidth,minFont,weight,family);
}

function chlDrawProgressCard(canvas,info){
  var ctx=canvas.getContext('2d');
  var W=canvas.width, H=canvas.height;

  var bg=ctx.createLinearGradient(0,0,W,H);
  bg.addColorStop(0,'#1c2436'); bg.addColorStop(0.55,'#121724'); bg.addColorStop(1,'#0b0e15');
  ctx.fillStyle=bg; ctx.fillRect(0,0,W,H);

  var g1=ctx.createRadialGradient(W*0.88,H*0.08,0,W*0.88,H*0.08,W*0.6);
  g1.addColorStop(0,'rgba(255,138,0,.20)'); g1.addColorStop(1,'rgba(255,138,0,0)');
  ctx.fillStyle=g1; ctx.fillRect(0,0,W,H);
  var g2=ctx.createRadialGradient(W*0.08,H*0.92,0,W*0.08,H*0.92,W*0.6);
  g2.addColorStop(0,'rgba(255,184,0,.14)'); g2.addColorStop(1,'rgba(255,184,0,0)');
  ctx.fillStyle=g2; ctx.fillRect(0,0,W,H);

  ctx.textAlign='center';

  // top: challenge icon + "DAY N" pill
  // fillStyle must be reset to an opaque color here — it was left as the fully-transparent
  // radial gradient (g2) from the glow fillRect above, which would silently render the icon
  // invisible (canvas text respects a gradient/color's alpha even for color-emoji glyphs).
  ctx.fillStyle='#fff';
  ctx.font='84px "Hind Siliguri",sans-serif';
  ctx.fillText(info.challengeIcon, W/2, H*0.155);

  var pillW=W*0.34, pillH=H*0.058, pillY=H*0.20;
  var pillGrad=ctx.createLinearGradient(W/2-pillW/2,0,W/2+pillW/2,0);
  pillGrad.addColorStop(0,'#FF8A00'); pillGrad.addColorStop(1,'#FFB800');
  ctx.fillStyle=pillGrad;
  ctx.beginPath();
  if(ctx.roundRect) ctx.roundRect(W/2-pillW/2,pillY,pillW,pillH,pillH/2);
  else ctx.rect(W/2-pillW/2,pillY,pillW,pillH);
  ctx.fill();
  ctx.font='800 '+Math.round(H*0.032)+'px "Hind Siliguri",sans-serif';
  ctx.fillStyle='#090B12';
  ctx.fillText('DAY '+info.dayNum, W/2, pillY+pillH*0.68);

  // middle: the caption, auto-sized to fit — the actual "star" of the card
  var fit=chlFitWrapText(ctx, info.caption||'', W*0.82, H*0.34, Math.round(H*0.052), Math.round(H*0.026), '700', '"Hind Siliguri",sans-serif');
  ctx.font='700 '+fit.size+'px "Hind Siliguri",sans-serif';
  ctx.fillStyle='#fff';
  var textBlockH=fit.lines.length*fit.lineHeight;
  var startY=H*0.50-textBlockH/2+fit.size*0.8;
  fit.lines.forEach(function(l,i){ ctx.fillText(l, W/2, startY+i*fit.lineHeight); });

  // bottom: challenge title + Rizers branding — bumped up from the original .6/.026 opacity+
  // size, which read as too faint/small to notice at typical feed display sizes (the whole
  // point of drawing it here is so the challenge is identifiable at a glance).
  ctx.font='700 '+Math.round(H*0.034)+'px "Hind Siliguri",sans-serif';
  ctx.fillStyle='rgba(255,255,255,.85)';
  chlWrapAtSize(ctx, info.challengeTitle||'Challenge', W*0.8, Math.round(H*0.034), '700', '"Hind Siliguri",sans-serif').lines.forEach(function(l,i,arr){
    ctx.fillText(l, W/2, H*0.86+i*Math.round(H*0.034)*1.3-(arr.length-1)*Math.round(H*0.034)*0.65);
  });

  ctx.font='800 '+Math.round(H*0.024)+'px "Hind Siliguri",sans-serif';
  ctx.fillStyle='rgba(255,138,0,.9)';
  ctx.fillText('R I Z E R S', W/2, H*0.945);
}

async function chlRenderProgressCardPreview(){
  var canvas=document.getElementById('chl-pc-card-canvas');
  var wrap=document.getElementById('chl-pc-card-preview');
  if(!canvas||!wrap)return;
  // window._chlComposerDay is null while chlComputeDayAndStreak is still resolving for the
  // challenge that was just opened — drawing now would use whatever day number the PREVIOUS
  // challenge's composer left behind (a stale/wrong "DAY N" flash), so blank the canvas and
  // wait for the real value instead of guessing.
  if(window._chlComposerDay==null){
    var ctx0=canvas.getContext('2d');
    ctx0.clearRect(0,0,canvas.width,canvas.height);
    return;
  }
  var ta=document.getElementById('chl-pc-text');
  var rawText=(ta&&ta.value)||'';
  var caption=rawText.replace(/^Day\s+\d+:\s*/,'').trim();
  var chal=window.chlCurrentChallenge||{};
  try{ await document.fonts.ready; }catch(e){}
  chlDrawProgressCard(canvas,{
    dayNum:window._chlComposerDay||1,
    challengeTitle:chal.title||'Challenge',
    challengeIcon:chal.icon||'🎯',
    caption:caption||'আজকের অগ্রগতি শেয়ার করো...'
  });
}

// Debounced so a fast typist doesn't trigger a full canvas redraw on every keystroke.
function chlScheduleProgressCardPreview(){
  if(_chlPcPreviewRAF)cancelAnimationFrame(_chlPcPreviewRAF);
  _chlPcPreviewRAF=requestAnimationFrame(function(){ chlRenderProgressCardPreview(); });
}

function chlProgressCardToFile(){
  return new Promise(function(resolve){
    var canvas=document.getElementById('chl-pc-card-canvas');
    if(!canvas){ console.warn('chlProgressCardToFile: #chl-pc-card-canvas not found in DOM'); resolve(null); return; }
    try{
      canvas.toBlob(function(blob){
        if(!blob) console.warn('chlProgressCardToFile: canvas.toBlob resolved with a null blob (canvas may be tainted by a privacy/anti-fingerprinting extension, or 0x0/blank)');
        resolve(blob?new File([blob],'rizers-progress.png',{type:'image/png'}):null);
      },'image/png');
    }catch(e){
      console.warn('chlProgressCardToFile: canvas.toBlob threw synchronously —', e && e.message);
      resolve(null);
    }
  });
}

window.chlOpenProgressComposer=function(challengeId){
  if(!sbUser){ if(typeof sbOpenAuth==='function')sbOpenAuth('login'); return; }
  chlEnsureCommunityLoaded(function(){ chlOpenProgressComposerReal(challengeId); });
};

async function chlOpenProgressComposerReal(challengeId){
  _chlComposerChallengeId=challengeId;
  window._chlComposerDay=null; // unknown until chlComputeDayAndStreak resolves below (see chlRenderProgressCardPreview's null-guard)
  var chal=window.chlCurrentChallenge;
  var icon=document.getElementById('chl-pc-icon'); if(icon)icon.textContent=(chal&&chal.icon)||'🎯';
  var title=document.getElementById('chl-pc-title-lbl'); if(title)title.textContent=(chal&&chal.title)||'Challenge';

  var ta=document.getElementById('chl-pc-text'); if(ta) ta.value='';
  chlClearImage();
  var streakBadge=document.getElementById('chl-pc-streak-badge'); if(streakBadge)streakBadge.style.display='none';
  var dayEl=document.getElementById('chl-pc-day'); if(dayEl)dayEl.textContent='...';

  var modal=document.getElementById('chl-progress-modal');
  if(modal)modal.classList.add('open');
  chlUpdateSubmitState();

  var info=await chlComputeDayAndStreak(challengeId);
  window._chlComposerDay=info.day;
  if(dayEl)dayEl.textContent='Day '+info.day+(info.durationDays?' / '+info.durationDays:'');
  if(info.streak>=2&&streakBadge){
    var streakText=document.getElementById('chl-pc-streak-text');
    if(streakText)streakText.textContent=info.streak+' দিনের streak চলছে এই challenge-এ — আজও রাখো!';
    streakBadge.style.display='flex';
  }
  if(ta){ ta.value='Day '+info.day+': '; ta.focus(); ta.setSelectionRange(ta.value.length,ta.value.length); }
  chlUpdateSubmitState();
  chlRenderProgressCardPreview();
}

function chlQuickLog(){
  var ta=document.getElementById('chl-pc-text');
  if(!ta)return;
  var day=window._chlComposerDay||1;
  ta.value='Day '+day+': আজ সম্পন্ন করেছি! ✅';
  chlUpdateSubmitState();
  chlRenderProgressCardPreview();
}

function chlUpdateSubmitState(){
  var ta=document.getElementById('chl-pc-text');
  var btn=document.getElementById('chl-pc-submit-btn');
  if(!ta||!btn)return;
  btn.disabled=!ta.value.trim();
}

function chlPickImage(inp){
  var f=inp.files&&inp.files[0];if(!f)return;
  chlComposerImgFile=f;
  var rd=new FileReader();
  rd.onload=function(e){
    var pv=document.getElementById('chl-pc-attach-prev');
    var im=document.getElementById('chl-pc-attach-img');
    if(im)im.src=e.target.result;
    if(pv)pv.style.display='block';
  };
  rd.readAsDataURL(f);
  // A real photo takes priority over the auto-generated card — matches Facebook
  // (colored-background text is only offered for photo-less posts).
  var cardPv=document.getElementById('chl-pc-card-preview'); if(cardPv)cardPv.style.display='none';
}
function chlClearImage(){
  chlComposerImgFile=null;
  var pv=document.getElementById('chl-pc-attach-prev'); if(pv)pv.style.display='none';
  var fi=document.getElementById('chl-pc-file'); if(fi)fi.value='';
  var cardPv=document.getElementById('chl-pc-card-preview'); if(cardPv)cardPv.style.display='flex';
  chlRenderProgressCardPreview();
}

function chlCloseProgressComposer(){
  // Blocked mid-submit — closing (and a later reopen for a different challenge) would let
  // the still-pending chlComposerSubmit() finish uploading a canvas that's since been
  // overwritten/re-purposed for a different challenge's composer, since #chl-pc-card-canvas
  // and window._chlComposerDay/chlCurrentChallenge are shared singletons across composer
  // sessions, not per-challenge state.
  if(_chlSubmittingProgress)return;
  var modal=document.getElementById('chl-progress-modal');
  if(modal)modal.classList.remove('open');
  chlClearImage();
  _chlComposerChallengeId=null;
}

var CHL_STREAK_MILESTONES=[3,7,14,21,30];
var _chlSubmittingProgress=false;

async function chlComposerSubmit(){
  if(_chlSubmittingProgress)return;
  var ta=document.getElementById('chl-pc-text');
  var btn=document.getElementById('chl-pc-submit-btn');
  var challengeId=_chlComposerChallengeId;
  if(!ta||!challengeId)return;
  var text=ta.value.trim();
  if(!text)return;
  _chlSubmittingProgress=true;
  if(btn){btn.disabled=true;btn.textContent='Sharing...';}
  try{
    // No real photo attached → generate the dark/premium infographic (the live preview the
    // user's already been looking at) and post THAT as the image, same upload path a real
    // photo attachment already goes through — cmSubmitPost_sb doesn't need to know the
    // difference between a picked file and a canvas-generated one. The full caption is
    // drawn ONTO that image, so the saved post text is trimmed back down to just the day
    // prefix — otherwise chlBuildProgressCardHtml would show the identical caption a second
    // time as plain text directly under an image that already contains it. Reducing to
    // 'Day N:' isn't a hack around that renderer: its own regex (/^Day\s+(\d+):\s*/) already
    // strips exactly that prefix down to an empty body, which cmBuildPostCardHtml already
    // renders as no body div at all — the same path a real photo-only post takes today.
    // Only shortened when the image actually generated — canvas.toBlob() CAN resolve to a
    // null blob on failure, and silently posting neither the real caption nor an image
    // would be worse than falling back to a plain text-only post.
    var imgFile=chlComposerImgFile;
    var submitText=text;
    if(!imgFile){
      await chlRenderProgressCardPreview();
      imgFile=await chlProgressCardToFile();
      if(imgFile) submitText='Day '+(window._chlComposerDay||1)+':';
    }
    window.cmComposerImgFile=imgFile;
    var balBefore=(window.sbProfile&&window.sbProfile.reys_balance)||0;
    var ok=await cmSubmitPost_sb(submitText,'progress',null,challengeId);
    window.cmComposerImgFile=null;
    if(btn)btn.textContent='Share Progress';
    // The submission itself has finished by this point (success or fail) — clear the guard
    // BEFORE closing, or chlCloseProgressComposer's own in-flight check would block this
    // legitimate internal close-on-success call too, not just an external one.
    _chlSubmittingProgress=false;
    if(ok){
      chlCloseProgressComposer();
      // Re-fetch rather than assume +15 — the server trigger only pays out on the
      // FIRST progress post of the day, so a second post today earns nothing and
      // a blind local increment would show a number the balance won't actually reach.
      var fresh=await _sb.from('profiles').select('*').eq('id',sbUser.id).single();
      var earned=0;
      if(fresh.data){ earned=Math.max(0,(fresh.data.reys_balance||0)-balBefore); window.sbProfile=fresh.data; }
      var info=await chlComputeDayAndStreak(challengeId);
      var hitMilestone=CHL_STREAK_MILESTONES.indexOf(info.streak)!==-1;
      if(typeof cmToast==='function'){
        if(hitMilestone) cmToast('🎉 '+info.streak+' দিনের streak সম্পন্ন! Alhamdulillah, চালিয়ে যাও!');
        else if(earned>0) cmToast('✅ Progress shared! +'+earned+' Reys');
        else cmToast('✅ Progress shared!');
      }
      if(hitMilestone && typeof chlOpenMilestoneCard==='function') chlOpenMilestoneCard(challengeId,info.streak);
      if(typeof chlRenderProgressCalendar==='function') chlRenderProgressCalendar(challengeId);
      if(typeof chlRenderMilestoneCardBtn==='function') chlRenderMilestoneCardBtn(challengeId);
      if(typeof stRenderSubscription==='function') stRenderSubscription();
    } else {
      if(btn)btn.disabled=false;
      if(typeof cmToast==='function')cmToast('কিছু ভুল হয়েছে, আবার চেষ্টা করো');
    }
  }catch(e){
    window.cmComposerImgFile=null;
    if(btn){btn.disabled=false;btn.textContent='Share Progress';}
    if(typeof cmToast==='function')cmToast('কিছু ভুল হয়েছে, আবার চেষ্টা করো');
  }finally{
    _chlSubmittingProgress=false;
  }
}

// Last-14-days consistency strip on the challenge detail page — filled dot = logged
// progress that day, hollow = not. Reuses the same posts.challenge_id query shape as
// chlComputeDayAndStreak, just over a wider window and without the backward-walk.
async function chlRenderProgressCalendar(challengeId){
  var el=document.getElementById('chl-progress-cal');
  if(!el||!sbUser)return;
  try{
    var since=new Date(); since.setDate(since.getDate()-6);
    var r=await _sb.from('posts').select('created_at').eq('challenge_id',challengeId).eq('user_id',sbUser.id).eq('category','progress').gte('created_at',since.toISOString());
    var r2=await _sb.from('challenge_streak_freezes').select('freeze_date').eq('challenge_id',challengeId).eq('user_id',sbUser.id);
    var logged=new Set((r.data||[]).map(function(row){var d=new Date(row.created_at);return d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate();}));
    var frozen=new Set((r2.data||[]).map(function(row){return row.freeze_date;}));
    var html='';
    var dayNames=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    for(var i=6;i>=0;i--){
      var d=new Date(); d.setDate(d.getDate()-i);
      var key=d.getFullYear()+'-'+d.getMonth()+'-'+d.getDate();
      var isToday=i===0;
      var on=logged.has(key);
      var isFrozen=!on&&frozen.has(_rzLocalDateStr(d));
      var bg=on?'linear-gradient(135deg,#FF8A00,#FFB800)':(isFrozen?'linear-gradient(135deg,#3B82F6,#60A5FA)':'var(--bg,#f0f0f0)');
      var border=(on||isFrozen)?'transparent':(isToday?'#FF8A00':'var(--border,#e5e7eb)');
      html+='<div style="display:flex;flex-direction:column;align-items:center;gap:4px;flex:1">'
        +'<div style="width:100%;max-width:40px;aspect-ratio:1;border-radius:9px;background:'+bg+';border:1.5px solid '+border+';display:flex;align-items:center;justify-content:center;font-size:15px">'+(isFrozen?'🧊':'')+'</div>'
        +'<div style="font-size:10.5px;font-weight:600;color:var(--text2,#999)">'+dayNames[d.getDay()]+'</div>'
        +'</div>';
    }
    el.innerHTML=html;
  }catch(e){}
}

window.chlJumpToChallenge=function(challengeId){
  showPage('challenges');
  var tries=0;
  var iv=setInterval(function(){
    tries++;
    if(document.getElementById('chl-detail-view')){
      clearInterval(iv);
      chlOpenChallenge(challengeId);
    }else if(tries>=30){ clearInterval(iv); }
  },100);
};

async function chlLoadChallengeFeed(challengeId){
  var el=document.getElementById('chl-feed');
  if(!el)return;
  el.innerHTML='<div class="chl-empty">Loading...</div>';
  try{
    var res=await _sb.from('posts')
      .select('*, profiles(name, streak_count, points, avatar_url, is_verified), comments(count), post_reactions(post_id, type, user_id), challenges(title, icon)')
      .eq('challenge_id',challengeId).order('created_at',{ascending:false}).limit(30);
    if(res.error){ el.innerHTML='<div class="chl-empty">Couldn\'t load posts.</div>'; return; }
    // Drop any stale copy of this challenge's posts from a prior visit, then merge fresh rows
    // into the SAME shared cmPosts array (not a parallel one) — see file header comment.
    cmPosts=cmPosts.filter(function(p){ return p.challengeId!==challengeId; });
    (res.data||[]).forEach(function(p,i){ cmPosts.push(cmMapPostRow(p,i)); });
    chlRenderFeed();
  }catch(e){ el.innerHTML='<div class="chl-empty">Couldn\'t load posts.</div>'; }
}

// Premium wrapper around the shared, battle-tested cm-post card — reuses
// cmBuildPostCardHtml() as-is (reactions/comments/menu/voice/media all stay
// exactly as proven) rather than hand-rebuilding that markup, and just adds
// an outer accent card + a gradient "Day N" strip pulled out of the post
// text. The strip is real flow content (not position:absolute like the
// earlier version) so it can't sit on top of cm-post's own ⋯ menu button.
// The day prefix is stripped only from the COPY passed to the renderer, so
// the same post still reads "Day N: ..." normally when it surfaces in the
// main Rise feed via cmBuildPostCardHtml directly.
function chlBuildProgressCardHtml(p){
  var dayMatch=(p.text||'').match(/^Day\s+(\d+):\s*/);
  var strip='',pForCard=p;
  if(dayMatch){
    strip='<div class="chl-pcard-strip"><span class="chl-pcard-strip-ic">'+(p.challengeIcon||'🎯')+'</span><span class="chl-pcard-strip-txt">DAY '+dayMatch[1]+' PROGRESS</span></div>';
    pForCard=Object.assign({},p,{text:p.text.slice(dayMatch[0].length)});
  }
  return '<div class="chl-pcard">'+strip+cmBuildPostCardHtml(pForCard)+'</div>';
}

function chlRenderFeed(){
  if(!chlCurrentChallengeId)return;
  var el=document.getElementById('chl-feed');
  if(!el)return;
  var list=cmPosts.filter(function(p){ return p.challengeId===chlCurrentChallengeId&&!p.hidden; });
  el.innerHTML=list.length?list.map(chlBuildProgressCardHtml).join(''):'<div class="chl-empty">No progress posts yet — be the first!</div>';
  if(typeof _cmStartTimeUpdater==='function')_cmStartTimeUpdater();
}

// ══ URL ROUTER (top-level pages + profiles) ═══════════════════════════════════════════
// Appended last so it wraps every earlier showPage hook and observes every call site's
// final page argument. Profile pages are excluded here (page==='profile') because they
// get their URL from viewUserProfile/pfSetVisitorMode instead — always /@username, never
// the generic /profile.
(function(){
  var _rzUrlOrig = window.showPage;
  window.showPage = function(page){
    var r = _rzUrlOrig.apply(this, arguments);
    if(!window._rzRouterSyncing && page !== 'profile' && pageMap[page]){
      var path = '/' + page;
      if(location.pathname !== path){
        if(window._rzRouteInitial){ window._rzRouteInitial=false; history.replaceState({rzPage:page},'',path); }
        else history.pushState({rzPage:page},'',path);
      } else {
        window._rzRouteInitial = false;
      }
    }
    return r;
  };
})();

window._rzNavToken = 0;
window.addEventListener('popstate', function(){
  var al = document.getElementById('app-layout');
  if(!al || !al.classList.contains('visible')) return; // pre-login landing page owns its own popstate exclusively
  var myToken = ++window._rzNavToken;
  var route = _rzParseRoute(location.pathname);
  window._rzRouterSyncing = true;
  if(route && route.type==='profile'){
    _rzResolveUsernameToId(route.username).then(function(id){
      if(myToken !== window._rzNavToken) return; // superseded by a newer popstate — discard stale result
      window._rzRouterSyncing = false;
      if(id) viewUserProfile(id); else showPage('community');
    });
  } else if(route && route.type==='page'){
    window._rzRouterSyncing = false;
    showPage(route.page);
  } else {
    window._rzRouterSyncing = false;
    showPage('community');
  }
});

